def accepted() -> dict:
    return state_record(
        "passed",
        "accepted",
        "current",
        ["recoil:evidence:r1:000001"],
        gating=True,
        validation_mode="live",
    )


def pending() -> dict:
    return state_record("pending", "observed", "changed", [])


def call_contract_fixture(count: int) -> dict:
    data = empty_progress_document()
    data["revision"] = 1
    start = 0x401000
    end = start + count * 0x10
    data["binaries"]["recoil"] = {
        "text": {"start": hex(start), "end_exclusive": hex(end)}
    }
    target_id = "recoil:vc5-target:synthetic-authored-order"
    addresses: list[str] = []
    for index in range(count):
        address = hex(start + index * 0x10)
        end_exclusive = hex(start + (index + 1) * 0x10)
        symbol_id = f"recoil:function:{address}"
        block_id = f"recoil:block:{address}"
        addresses.append(address)
        data["symbols"][symbol_id] = {
            "binary": "recoil",
            "kind": "function",
            "address": address,
            "start": address,
            "end_exclusive": end_exclusive,
            "physical_block_id": block_id,
            "pipeline_class": "authored",
            "authored_order_role": "authored-body",
            "binary_state": {"call_contract": pending()},
        }
        data["physical_blocks"][block_id] = {
            "binary": "recoil",
            "start": address,
            "end_exclusive": end_exclusive,
            "agent_source_path": "tools/recoil.py",
            "order": {
                "authored": {
                    dimension: accepted() for dimension in AUTHORED_ORDER_DIMENSIONS
                },
                "full": {dimension: pending() for dimension in FULL_ORDER_DIMENSIONS},
            },
            "accepted_order_facts": {
                "phase": "authored-function-order",
                "target_id": target_id,
                "matched_identities": [symbol_id],
                "validation_mode": "live",
            },
        }
    data["verification_targets"][target_id] = {
        "binary": "recoil",
        "kind": "vc5",
        "name": "synthetic-authored-order",
        "registered_addresses": addresses,
        "registration": {
            "name": "synthetic-authored-order",
            "binary": "recoil",
            "function_order_scope": "authored",
            "function_addresses": addresses,
            "source_from": "tools/recoil.py",
            "order_edit_paths": ["tools/recoil.py"],
            "manifest_path": "tools/recoil.py",
            "translation_unit_function_order": [],
        },
    }
    return data


def reviewed_existing_provider_binding(
    *,
    target_symbol_id: str,
    target_address: str,
    target_end_exclusive: str,
    object_symbol: str,
) -> dict:
    return {
        "reviewed": True,
        "object_symbol": object_symbol,
        "reason": "unit-test reviewed existing provider identity",
        "evidence_ids": ["unit:evidence:provider-binding"],
        "binding_context": {
            "source_binding": {
                "symbol_id": "recoil:function:0x401000",
                "address": "0x401000",
                "end_exclusive": "0x401010",
                "object_symbol": "?Caller@@YAXXZ",
                "physical_pipeline_class": "authored",
                "object_pipeline_class": "authored",
                "registration_ids": ["unit:registration:caller"],
                "evidence_ids": [],
            },
            "relocation": {
                "offset": 1,
                "type": 0x14,
                "type_name": "REL32",
                "retail_target": int(target_address, 16),
                "instruction_offset": 0,
                "opcode": "e8",
            },
            "target": {
                "symbol_id": target_symbol_id,
                "address": target_address,
                "end_exclusive": target_end_exclusive,
                "kind": "function",
                "navigation_name": object_symbol,
                "object_symbol": object_symbol,
                "output_section_id": "recoil:section:.text",
                "pipeline_class": "unresolved",
                "ownership_state": "unresolved",
            },
            "owner": {
                "owner_id": "recoil:owner:provider.unit",
                "kind": "provider-boundary",
                "provider_state": "accepted",
                "lifecycle_state": "accepted",
                "binding_evidence_ids": ["unit:evidence:provider-binding"],
            },
            "relationship": None,
            "creation_mode": "existing-symbol",
        },
    }


