def build_registered_decorated_data_indexes(
    data: dict,
    manifests: dict[str, SimpleNamespace],
    current_targets: dict[str, tuple[str, dict]],
) -> IdentityIndexes:
    def current_registration(path: Path) -> tuple[str, dict]:
        return current_targets[path.as_posix()]

    def current_manifest(
        path: Path,
        **_kwargs: object,
    ) -> SimpleNamespace:
        return manifests[path.as_posix()]

    with (
        patch(
            "_recoil.lib.verification_targets.vc5_target_registration",
            side_effect=current_registration,
        ),
        patch(
            "_recoil.commands.call_contract_verify.load_manifest",
            side_effect=current_manifest,
        ),
    ):
        return build_identity_indexes(ProgressDocument(data))


