def _eligible_fixture_toolchain_receipt(
    *,
    target_id: str,
    source_from: str,
    compiler_profile: str,
    compiler_flags: Sequence[str],
    manifest_index: int = 0,
) -> dict[str, object]:
    """Build one complete stable compile-only receipt for orchestration tests."""

    source_path = str((REPO_ROOT / source_from).resolve())
    manifest_path = str(
        (REPO_ROOT / "tools/vc5_verify_targets" / f"{target_id}.json").resolve()
    )
    compiler_environment = "C:/VC5/BIN/VCVARS32.BAT"
    argv = ["C:/VC5/BIN/CL.EXE", *compiler_flags, "/c", source_path]
    command_line = " ".join(argv)

    def identity(path: str, file_id: int, file_size: int) -> dict[str, object]:
        return {
            "volume_identity": 1,
            "file_id": file_id,
            "file_size": file_size,
            "is_directory": False,
            "canonical_path": path,
        }

    components = []
    for index, (role, name, status) in enumerate(
        (
            ("compiler-driver", "CL.EXE", "invoked"),
            ("compiler-front-end", "C1XX.DLL", "invoked-by-driver"),
            ("compiler-back-end", "C2.DLL", "invoked-by-driver"),
            ("linker", "LINK.EXE", "not-applicable"),
            ("librarian", "LIB.EXE", "not-applicable"),
            ("resource-compiler", "RC.EXE", "not-applicable"),
            ("assembler", "ML.EXE", "not-applicable"),
        ),
        start=10,
    ):
        path = f"C:/VC5/BIN/{name}"
        invoked = status != "not-applicable"
        components.append(
            {
                "role": role,
                "status": status,
                "invocation": {
                    "invoked": invoked,
                    "form": (
                        "command-line"
                        if role == "compiler-driver"
                        else "internal-driver-dispatch"
                        if invoked
                        else "not-applicable"
                    ),
                    "argv": "see compiler.argv" if invoked else [],
                    **(
                        {
                            "driver_argv": list(argv),
                            "exact_driver_command_line": command_line,
                        }
                        if invoked
                        else {"reason": "compile-only-/c-operation"}
                    ),
                },
                "path": path,
                "configured_absolute_path": path,
                "physical_identity": identity(path, index, index * 100),
                "size": index * 100,
                "version": "11.00.7022",
            }
        )
    source_identity = identity(source_path, 2, 200)
    environment_identity = identity(compiler_environment, 3, 300)
    manifest_identity = identity(manifest_path, 4, 400)
    observation = {
        "contract_version": 3,
        "tu_context_id": f"recoil:call-contract-tu:{target_id}:{manifest_index}",
        "manifest_entry_id": f"{manifest_path}#{manifest_index}",
        "source_from": source_from,
        "source": {"path": source_path, "physical_identity": source_identity},
        "dependencies": [
            {
                "path": source_path,
                "role": "authored-source",
                "physical_identity": source_identity,
            },
            {
                "path": source_path,
                "role": "compiled-input",
                "physical_identity": source_identity,
            },
            {
                "path": compiler_environment,
                "role": "compiler-environment-script",
                "physical_identity": environment_identity,
            },
        ],
        "compiler": {
            "executable_path": "C:/VC5/BIN/CL.EXE",
            "explicit_argv": list(argv),
            "argv": list(argv),
            "expanded_argv": list(argv),
            "response_files": [],
            "exact_command_line": command_line,
            "cwd": "${RECOIL_ISOLATED_BUILD_ROOT}",
            "observed_cwd": "C:/fixture/build",
            "inherited_options": {
                "CL": "",
                "_CL_": "",
                "CL_tokens": [],
                "_CL__tokens": [],
            },
            "environment_capture_complete": True,
        },
        "toolchain": {
            "profile_id": compiler_profile,
            "profile_flags": list(compiler_flags),
            "components": components,
            "compiler_version": (
                "Microsoft (R) 32-bit C/C++ Compiler Version 11.00.7022"
            ),
            "include_search_roots": [],
            "header_inputs": [],
            "library_inputs": {
                "status": "not-applicable",
                "reason": "compile-only-/c-operation",
                "rows": [],
            },
        },
        "manifest": {
            "path": manifest_path,
            "physical_identity": manifest_identity,
            "projection": {
                "name": target_id,
                "target_binary": "recoil",
                "manifest_path": manifest_path,
                "source_from": source_from,
                "manifest_index": manifest_index,
                "include_dirs": [],
                "compiler_profile": compiler_profile,
                "compiler_flags": list(compiler_flags),
                "compile_context_from": "",
            },
        },
        "verification_eligible": True,
        "ineligibility_reasons": [],
    }
    return call_contract_verify_module.compiler_receipt_stability(
        observation,
        deepcopy(observation),
    )


class FiniteSymbolRegexParserTests(unittest.TestCase):
    def test_exact_get_network_enabled_pair_is_enumerated(self) -> None:
        self.assertEqual(
            (
                "?GetNetworkEnabled@zOpt@@YAHXZ",
                "?GetNetworkEnabled@zOpt@@YIHXZ",
            ),
            _finite_literal_symbol_regex_alternatives(
                r"^(?:\?GetNetworkEnabled@zOpt@@YAHXZ|"
                r"\?GetNetworkEnabled@zOpt@@YIHXZ)$"
            ),
        )
    def test_non_finite_or_non_literal_regexes_are_rejected(self) -> None:
        invalid = (
            r"(?:\?One@@YAXXZ|\?Two@@YAXXZ)",
            r"^(?:\?One@@YAXXZ|\?Two@@YAXXZ)",
            r"(?:\?One@@YAXXZ|\?Two@@YAXXZ)$",
            r"^(?:\?One.*|\?Two@@YAXXZ)$",
            r"^(?:\?One@@YAXXZ?|\?Two@@YAXXZ)$",
            r"^(?:\?One@@YAXXZ+|\?Two@@YAXXZ)$",
            r"^(?:\?One[AB]@@YAXXZ|\?Two@@YAXXZ)$",
            r"^(?:(?:\?One@@YAXXZ)|\?Two@@YAXXZ)$",
            r"^(?:(?=\?One)\?One@@YAXXZ|\?Two@@YAXXZ)$",
            r"(?i)^(?:\?One@@YAXXZ|\?Two@@YAXXZ)$",
            r"^(?:\?One@@YAXXZ|\1)$",
            r"^(?:\?One\d@@YAXXZ|\?Two@@YAXXZ)$",
            r"^(?:\?One\x41@@YAXXZ|\?Two@@YAXXZ)$",
            r"^(?:\?One\101@@YAXXZ|\?Two@@YAXXZ)$",
            r"^(?:\?One\n@@YAXXZ|\?Two@@YAXXZ)$",
        )
        for symbol_regex in invalid:
            with self.subTest(symbol_regex=symbol_regex):
                self.assertIsNone(
                    _finite_literal_symbol_regex_alternatives(symbol_regex)
                )

    def test_empty_duplicate_excessive_and_non_decorated_rows_are_rejected(
        self,
    ) -> None:
        duplicate = r"^(?:\?One@@YAXXZ|\?One@@YAXXZ)$"
        empty = r"^(?:\?One@@YAXXZ|)$"
        too_many = "^(?:" + "|".join(
            rf"\?Name{index}@@YAXXZ" for index in range(33)
        ) + ")$"
        too_long = "^(?:?" + ("A" * 1025) + "|?Two@@YAXXZ)$"
        non_decorated = r"^(?:One@@YAXXZ|Two@@YAXXZ)$"
        for symbol_regex in (
            duplicate,
            empty,
            too_many,
            too_long,
            non_decorated,
        ):
            with self.subTest(symbol_regex=symbol_regex[:80]):
                self.assertIsNone(
                    _finite_literal_symbol_regex_alternatives(symbol_regex)
                )


