    def indexes(
        self,
        *,
        by_candidate_name: dict[str, str] | None = None,
        provider: bool = False,
        storage_by_name: dict[str, str] | None = None,
        by_address: dict[str, str] | None = None,
    ) -> IdentityIndexes:
        return IdentityIndexes(
            by_address=by_address or {self.address: self.identity},
            by_candidate_name=by_candidate_name or {},
            provider_ids=(
                frozenset({self.identity}) if provider else frozenset()
            ),
            storage_by_address={},
            storage_by_name=storage_by_name or {},
        )

    def candidate(
        self,
        *,
        calls: tuple[tuple[int, int], ...] = ((0x15, 0xE8), (0x30, 0xE8)),
        relocation_offsets: tuple[int, ...] | None = None,
        relocation_type: int = 0x14,
        masked: bool = True,
        addend: int = 0,
        relocation_names: tuple[str, ...] | None = None,
        defined_external_functions: tuple[str, ...] | None = None,
        undefined_external_functions: tuple[str, ...] = (),
        local_indices: frozenset[int] = frozenset(),
        data_opcode: int | None = None,
        candidate_name: str | None = None,
    ) -> CandidateAssembly:
        selected_name = candidate_name or self.name
        instructions = tuple(
            parse_assembly(
                "\n".join(
                    (
                        f"  {offset:05x} {opcode:02x} 00 00 00 00 "
                        f"{'call' if opcode == 0xE8 else 'jmp'} {selected_name}"
                    )
                    for offset, opcode in calls
                ),
                source="cod",
            )
        )
        offsets = relocation_offsets or tuple(
            offset + 1 for offset, _opcode in calls
        )
        names = relocation_names or tuple(
            selected_name for _offset in offsets
        )
        data = bytearray(0x80)
        relocation_mask = [False] * len(data)
        for offset, opcode in calls:
            data[offset] = opcode if data_opcode is None else data_opcode
        for offset in offsets:
            if offset + 4 > len(data):
                continue
            data[offset : offset + 4] = addend.to_bytes(4, "little")
            if masked:
                for index in range(offset, offset + 4):
                    relocation_mask[index] = True
        return CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=local_indices,
            caller_definition=CandidateCallerDefinition(
                symbol="?Caller@@QAEXXZ",
                data=bytes(data),
                relocations=tuple(
                    CoffRelocation(
                        offset=offset,
                        symbol_index=40 + index,
                        type=relocation_type,
                        symbol_name=names[index],
                    )
                    for index, offset in enumerate(offsets)
                ),
                relocation_mask=tuple(relocation_mask),
                defined_external_functions=(
                    defined_external_functions
                    if defined_external_functions is not None
                    else (selected_name,)
                ),
                undefined_external_functions=undefined_external_functions,
            ),
        )

    def bridge(
        self,
        *,
        data: dict | None = None,
        candidate: CandidateAssembly | None = None,
        indexes: IdentityIndexes | None = None,
        bridge_names: dict[str, object] | None = None,
        compiler_generated_bridges: dict[str, str] | None = None,
        synchronization_error: str | None = None,
    ) -> dict[str, str]:
        side_effect = (
            ValueError(synchronization_error)
            if synchronization_error is not None
            else None
        )
        with patch(
            "_recoil.commands.call_contract_verify."
            "_synchronized_finite_symbol_regex_target",
            side_effect=side_effect,
        ):
            return (
                _registered_target_symbol_regex_direct_candidate_bridges(
                    candidate or self.candidate(),
                    document=ProgressDocument(data or self.document_data()),
                    indexes=indexes or self.indexes(),
                    bridge_names=bridge_names or {},
                    compiler_generated_bridges=(
                        compiler_generated_bridges or {}
                    ),
                )
            )

    def row(self, data: dict) -> dict:
        return data["verification_targets"][self.target_id]["registration"][
            "functions"
        ][0]

