    def test_exact_registered_regex_and_relocations_resolve_authored_identity(
        self,
    ) -> None:
        candidate = self.candidate(calls=((0x15, 0xE8),))
        data = self.document_data()
        indexes = build_identity_indexes(ProgressDocument(data))
        self.assertEqual(self.identity, indexes.by_address[self.address])
        self.assertNotIn(self.name, indexes.by_candidate_name)
        bridges = self.bridge(
            data=data,
            candidate=candidate,
            indexes=indexes,
        )
        self.assertEqual({self.name: self.identity}, bridges)
        candidate_contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x401000",
            caller_end_exclusive="0x401080",
            indexes=indexes,
            compiler_generated_bridges=bridges,
        )
        retail_contract = extract_invocation_contract(
            parse_assembly(
                "00401015 e8 46 de 00 00 call 0x40ee60",
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:caller",
            caller_start="0x401000",
            caller_end_exclusive="0x401080",
            indexes=indexes,
        )
        self.assertEqual(retail_contract, candidate_contract)
        self.assertEqual(
            [("call", self.identity)],
            [
                (row["form"], row["target_identity"])
                for row in candidate_contract
            ],
        )

