    def test_absolute_tu_local_bridge_accepts_exact_two_call_population(
        self,
    ) -> None:
        data, candidate, candidate_name, _reviewed_name = (
            self.absolute_tu_local_fixture(
                calls=((0x49, 0xE8), (0x6C, 0xE8)),
            )
        )
        bridges = self.bridge(data=data, candidate=candidate)
        self.assertEqual({candidate_name: self.identity}, bridges)
        contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity="symbol:recoil:function:0x457d90",
            caller_start="0x457d90",
            caller_end_exclusive="0x457e20",
            indexes=self.indexes(),
            compiler_generated_bridges=bridges,
        )
        self.assertEqual(
            [self.identity, self.identity],
            [row["target_identity"] for row in contract],
        )

        missing = replace(
            candidate,
            caller_definition=replace(
                candidate.caller_definition,
                relocations=candidate.caller_definition.relocations[:1],
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "one exact caller-object relocation per COD invocation",
        ):
            self.bridge(data=data, candidate=missing)

        alias = replace(
            candidate,
            caller_definition=replace(
                candidate.caller_definition,
                relocations=(
                    *candidate.caller_definition.relocations,
                    CoffRelocation(
                        offset=0x76,
                        symbol_index=40,
                        type=call_contract_verify_module.IMAGE_REL_I386_REL32,
                        symbol_name=candidate_name + "$alias",
                    ),
                ),
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "differently named relocation alias",
        ):
            self.bridge(data=data, candidate=alias)

        definition = candidate.caller_definition.coff_symbols[0]
        definition_aliases = {
            "coincident": replace(
                definition,
                index=41,
                name=candidate_name + "$coincident",
            ),
            "weak": replace(
                definition,
                index=42,
                name=candidate_name + "$weak",
                section_number=0,
                symbol_type=0,
                storage_class=105,
                weak_external_tag_index=definition.index,
            ),
        }
        for label, definition_alias in definition_aliases.items():
            aliased_definition = replace(
                candidate,
                caller_definition=replace(
                    candidate.caller_definition,
                    coff_symbols=(definition, definition_alias),
                ),
            )
            with self.subTest(definition_alias=label), self.assertRaisesRegex(
                ValueError,
                "exact unaliased same-TU defined COFF function symbol",
            ):
                self.bridge(data=data, candidate=aliased_definition)

        mixed = replace(
            candidate,
            caller_definition=replace(
                candidate.caller_definition,
                relocations=(
                    candidate.caller_definition.relocations[0],
                    replace(
                        candidate.caller_definition.relocations[1],
                        symbol_index=41,
                    ),
                ),
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "zero-addend fully masked E8/E9 REL32 evidence",
        ):
            self.bridge(data=data, candidate=mixed)

    def test_schema82_minimal_and_authority_views_synchronize_exact_tu_local(
        self,
    ) -> None:
        data, candidate, candidate_name, _reviewed_name = (
            self.absolute_tu_local_fixture()
        )
        target = data["verification_targets"][self.target_id]
        registration = target["registration"]
        authority_row = deepcopy(self.row(data))
        synchronized_fields = (
            "address",
            "pipeline_class",
            "authored_order_role",
            "authored_order_gate",
            "authored_relative_order_gate",
            "required_presence",
            "full_order_gate",
            "logical_identity_key",
            "icf_fold_status",
        )
        registration["functions"] = [
            {
                field: authority_row[field]
                for field in synchronized_fields
            }
        ]
        registration["translation_unit_function_order"] = [
            {"functions": [deepcopy(authority_row)]}
        ]
        registration["linked_function_intervals"] = [
            {
                "functions": [
                    deepcopy(authority_row),
                    {
                        **deepcopy(authority_row),
                        "address": "0x402000",
                        "name": "Unrelated::LaterRow",
                        "symbol": "?LaterRow@Unrelated@@QAEXXZ",
                        "symbol_regex": r"\?LaterRow@Unrelated@@QAEXXZ",
                    },
                ]
            }
        ]
        data["symbols"][self.symbol_id]["navigation_name"] = (
            "zSys::UpdateHMSFromSeconds"
        )

        def prove(current: dict) -> dict[str, str]:
            with patch(
                "_recoil.lib.verification_targets.vc5_target_registration",
                return_value=(self.target_id, current),
            ):
                return _registered_target_symbol_regex_direct_candidate_bridges(
                    candidate,
                    document=ProgressDocument(data),
                    indexes=self.indexes(),
                    bridge_names={},
                    compiler_generated_bridges={},
                )

        self.assertEqual(
            {candidate_name: self.identity},
            prove(deepcopy(target)),
        )

        cases = {
            "minimal-gate-drift": lambda current: current["registration"][
                "functions"
            ][0].__setitem__("required_presence", False),
            "authority-case-drift": lambda current: current["registration"][
                "translation_unit_function_order"
            ][0]["functions"][0].__setitem__(
                "symbol",
                authority_row["symbol"].replace("Update", "update", 1),
            ),
            "duplicate-view": lambda current: current["registration"][
                "linked_function_intervals"
            ][0]["functions"].append(deepcopy(authority_row)),
        }
        for label, mutate in cases.items():
            current = deepcopy(target)
            mutate(current)
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "stale, duplicated, or conflicting",
            ):
                prove(current)

    def test_absolute_tu_local_regex_bridge_rejects_inexact_authority(
        self,
    ) -> None:
        data, candidate, candidate_name, _reviewed_name = (
            self.absolute_tu_local_fixture()
        )
        synchronized_views = deepcopy(data)
        synchronized_registration = synchronized_views["verification_targets"][
            self.target_id
        ]["registration"]
        identical_row = deepcopy(self.row(synchronized_views))
        synchronized_registration["translation_unit_function_order"] = [
            {"functions": [deepcopy(identical_row)]}
        ]
        synchronized_registration["linked_function_intervals"] = [
            {"functions": [deepcopy(identical_row)]}
        ]
        self.assertEqual(
            {candidate_name: self.identity},
            self.bridge(data=synchronized_views, candidate=candidate),
        )

        duplicate_rows = deepcopy(synchronized_views)
        distinct_row = deepcopy(self.row(duplicate_rows))
        distinct_row["name"] = "HudUiTimerPanel::DistinctReviewedRow"
        duplicate_rows["verification_targets"][self.target_id]["registration"][
            "linked_function_intervals"
        ].append({"functions": [distinct_row]})
        with self.assertRaisesRegex(ValueError, "exactly one selected full-regex"):
            self.bridge(data=duplicate_rows, candidate=candidate)

        signature_drift = deepcopy(data)
        self.row(signature_drift)["symbol"] = self.row(signature_drift)[
            "symbol"
        ].replace("@@QAEXM@Z", "@@QAEXH@Z")
        with self.assertRaisesRegex(ValueError, "exact reviewed basename"):
            self.bridge(data=signature_drift, candidate=candidate)

        definition = candidate.caller_definition.coff_symbols[0]
        duplicate_definition = replace(
            candidate,
            caller_definition=replace(
                candidate.caller_definition,
                coff_symbols=(definition, replace(definition, index=41)),
            ),
        )
        with self.assertRaisesRegex(ValueError, "exact same-TU defined COFF"):
            self.bridge(data=data, candidate=duplicate_definition)

        undefined = replace(
            candidate,
            caller_definition=replace(
                candidate.caller_definition,
                defined_external_functions=(),
                undefined_external_functions=(candidate_name,),
            ),
        )
        with self.assertRaisesRegex(ValueError, "exact same-TU defined COFF"):
            self.bridge(data=data, candidate=undefined)

        missing_relocation = replace(
            candidate,
            caller_definition=replace(
                candidate.caller_definition,
                relocations=(),
            ),
        )
        with self.assertRaisesRegex(ValueError, "caller-object relocation"):
            self.bridge(data=data, candidate=missing_relocation)

        wrong_relocation = replace(
            candidate,
            caller_definition=replace(
                candidate.caller_definition,
                relocations=(
                    replace(
                        candidate.caller_definition.relocations[0],
                        type=0x06,
                    ),
                ),
            ),
        )
        with self.assertRaisesRegex(ValueError, "REL32 evidence"):
            self.bridge(data=data, candidate=wrong_relocation)

        self.assertEqual(
            {},
            self.bridge(
                data=data,
                candidate=replace(
                    candidate,
                    target=SimpleNamespace(name="unrelated-target"),
                ),
            ),
        )

