    def test_identical_destructor_suppliers_coalesce_one_call_identity(
        self,
    ) -> None:
        candidate_name = "??1zFMV_Action@@UAE@XZ"
        data = self.document_data()
        semantic_name = "zFMV_Action::~zFMV_Action"
        self.row(data).update(
            {
                "symbol_regex": re.escape(candidate_name),
                "name": semantic_name,
            }
        )
        candidate = self.candidate(candidate_name=candidate_name)
        resolved = self.arbitrate_destructor_bridges(
            data=data,
            candidate=candidate,
        )
        self.assertEqual({candidate_name: self.identity}, resolved)
        canonical = {candidate_name: self.identity}
        canonical.update(resolved)
        contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x401000",
            caller_end_exclusive="0x401080",
            indexes=self.indexes(),
            compiler_generated_bridges=canonical,
        )
        self.assertEqual(1, len(contract))
        self.assertEqual(self.identity, contract[0]["target_identity"])

    def test_candidate_only_registered_destructor_keeps_authored_identity(
        self,
    ) -> None:
        candidate_name = "??1zFMV_Action@@UAE@XZ"
        data = self.document_data()
        self.row(data).update(
            {
                "symbol_regex": re.escape(candidate_name),
                "name": "zFMV_Action::~zFMV_Action",
            }
        )
        other_retail_identity = "symbol:recoil:function:0x415a80"
        for opcode, expected_form in ((0xE8, "call"), (0xE9, "tail")):
            with self.subTest(expected_form=expected_form):
                candidate = RegisteredTargetSymbolRegexDirectBridgeTests().candidate(
                    calls=((0x15, opcode),),
                    candidate_name=candidate_name,
                )
                resolved = self.arbitrate_destructor_bridges(
                    data=data,
                    candidate=candidate,
                    expected_identity=other_retail_identity,
                )
                self.assertEqual({candidate_name: self.identity}, resolved)
                contract = extract_invocation_contract(
                    candidate.instructions,
                    source="cod",
                    caller_identity="symbol:caller",
                    caller_start="0x401000",
                    caller_end_exclusive="0x401080",
                    indexes=self.indexes(),
                    compiler_generated_bridges=resolved,
                )
                self.assertEqual(expected_form, contract[0]["form"])
                self.assertEqual(self.identity, contract[0]["target_identity"])
                expected = [
                    {
                        "ordinal": 0,
                        "form": "call",
                        "dispatch": "direct",
                        "identity_kind": "direct",
                        "target_identity": other_retail_identity,
                        "storage_identity": "",
                        "slot_displacement": None,
                        "cleanup_bytes": None,
                    }
                ]
                comparison = compare_call_contracts(expected, contract)
                self.assertFalse(comparison["passed"])
                self.assertEqual("mismatch", comparison["first_divergence"]["kind"])
                self.assertEqual(
                    self.identity,
                    comparison["first_divergence"]["candidate"][
                        "target_identity"
                    ],
                )

