    def test_destructor_arbitration_rejects_caller_cleanup(self) -> None:
        candidate_name = "??1zFMV_Action@@UAE@XZ"
        data = self.document_data()
        self.row(data).update(
            {
                "symbol_regex": re.escape(candidate_name),
                "name": "zFMV_Action::~zFMV_Action",
            }
        )
        candidate = self.candidate(candidate_name=candidate_name)
        cleanup = parse_assembly(
            "  0001a 83 c4 04 add esp, 4",
            source="cod",
        )
        candidate = replace(
            candidate,
            instructions=(*candidate.instructions, *cleanup),
        )
        with self.assertRaisesRegex(ValueError, "call/tail form, cleanup"):
            self.arbitrate_destructor_bridges(
                data=data,
                candidate=candidate,
            )

