    def test_exact_named_zeroarg_constructor_package_resolves(self) -> None:
        candidate_name = (
            "?Constructor@HudUiBackgroundConfirmQuit@@QAEPAU1@XZ"
        )
        identity = "symbol:recoil:function:0x415680"
        candidate = self.candidate(candidate_name=candidate_name)
        bridges = self.bridge(
            data=self.named_constructor_data(),
            candidate=candidate,
            indexes=self.named_constructor_indexes(),
            bridge_names={},
        )
        self.assertEqual({candidate_name: identity}, bridges)
        contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity="symbol:recoil:function:0x4158f0",
            caller_start="0x4158f0",
            caller_end_exclusive="0x415960",
            indexes=self.named_constructor_indexes(),
            compiler_generated_bridges=bridges,
        )
        expected = [
            {
                "ordinal": 0,
                "form": "call",
                "dispatch": "direct",
                "identity_kind": "direct",
                "target_identity": identity,
                "storage_identity": "",
                "slot_displacement": None,
                "cleanup_bytes": None,
            }
        ]
        self.assertTrue(compare_call_contracts(expected, contract)["passed"])
        wrong_expected = deepcopy(expected)
        wrong_expected[0]["target_identity"] = (
            "symbol:recoil:function:0x415690"
        )
        comparison = compare_call_contracts(wrong_expected, contract)
        self.assertFalse(comparison["passed"])
        self.assertEqual("mismatch", comparison["first_divergence"]["kind"])

