    def test_rejects_virtual_wrong_argument_and_conflicting_bridges(
        self,
    ) -> None:
        data, current = self._fixture()
        indexes = self._indexes(data, current)
        for malformed in (
            self.candidate_name.replace("PAXI@Z", "PAXH@Z"),
            self.candidate_name.replace("QAEPAX", "QAEX"),
        ):
            with self.subTest(name=malformed), self.assertRaisesRegex(
                ValueError,
                "ABI-incompatible scalar-deleting-destructor",
            ):
                self._contract(indexes, name=malformed)

        with self.assertRaisesRegex(ValueError, "conflicting indexed"):
            self._contract(
                replace(
                    indexes,
                    by_candidate_name={
                        **indexes.by_candidate_name,
                        self.candidate_name: "symbol:different",
                    },
                )
            )
        legacy_fallback_indexes = replace(
            indexes,
            by_candidate_name={
                **indexes.by_candidate_name,
                self.candidate_name: "",
            },
            scalar_deleting_destructor_legacy_fallback_names=frozenset(
                {self.candidate_name}
            ),
        )
        self.assertEqual(
            self.identity,
            self._contract(legacy_fallback_indexes)[0][
                "target_identity"
            ],
        )
        with self.assertRaisesRegex(ValueError, "conflicting compiler"):
            self._contract(
                indexes,
                compiler_bridges={self.candidate_name: "symbol:different"},
            )
        with self.assertRaisesRegex(ValueError, "conflicting BN"):
            self._contract(
                indexes,
                bridge_names={
                    self.candidate_name: Symbol(
                        address="0x40bf90",
                        name=self.candidate_name,
                    )
                },
            )

    def test_existing_implicit_cleanup_bridge_still_resolves(self) -> None:
        data, current = LifecycleDeletingDestructorIndexTests()._fixture()
        helper = LifecycleDeletingDestructorIndexTests()
        names = helper._index(data, helper._current_targets(current))
        indexes = IdentityIndexes(
            by_address={helper.address: helper.identity},
            by_candidate_name=names,
            provider_ids=frozenset(),
            storage_by_address={},
            storage_by_name={},
        )
        contract = self._contract(indexes, name=helper.scalar_name)
        self.assertEqual(helper.identity, contract[0]["target_identity"])

        virtual_name = "??_GHudCmdDialogState@@UAEPAXI@Z"
        virtual_identity = "symbol:virtual-scalar-dtor"
        virtual_indexes = replace(
            indexes,
            by_candidate_name={
                **indexes.by_candidate_name,
                virtual_name: virtual_identity,
            },
        )
        virtual_contract = self._contract(
            virtual_indexes,
            name=virtual_name,
        )
        self.assertEqual(
            virtual_identity,
            virtual_contract[0]["target_identity"],
        )


