    def test_retail_chain_and_candidate_relocation_drift_fail_closed(
        self,
    ) -> None:
        cases = {
            "retail-chain": {
                "retail": self.retail(corrupt_primary=True),
            },
            "relocation-type": {
                "candidate": self.candidate(relocation_type=0x14),
            },
            "pointer-addend": {
                "candidate": self.candidate(pointer_addend=0xED8),
            },
            "wrong-register": {
                "candidate": self.candidate(
                    reference_mutation="wrong-register"
                ),
            },
            "wrong-opcode": {
                "candidate": self.candidate(
                    reference_mutation="wrong-opcode"
                ),
            },
            "wrong-expression": {
                "candidate": self.candidate(
                    reference_mutation="wrong-expression"
                ),
            },
            "wrong-add-child": {
                "candidate": self.candidate(
                    reference_mutation="wrong-add-child"
                ),
            },
            "missing-reference": {
                "candidate": self.candidate(
                    reference_mutation="missing-reference"
                ),
            },
            "extra-reference": {
                "candidate": self.candidate(
                    reference_mutation="extra-reference"
                ),
            },
            "missing-relocation": {
                "candidate": self.candidate(
                    reference_mutation="missing-relocation"
                ),
            },
            "duplicate-relocation": {
                "candidate": self.candidate(
                    reference_mutation="duplicate-relocation"
                ),
            },
            "extra-relocation": {
                "candidate": self.candidate(extra_relocation=True),
            },
            "wrong-case-relocation": {
                "candidate": self.candidate(
                    relocation_symbol=self.aggregate_symbol.swapcase()
                ),
            },
            "unmasked-relocation": {
                "candidate": self.candidate(fully_masked=False),
            },
            "truncated-body": {
                "candidate": self.candidate(
                    layout="shifted",
                    body_length=0xFB,
                ),
            },
            "mask-length": {
                "candidate": self.candidate(mask_length_delta=-1),
            },
        }
        for label, kwargs in cases.items():
            with self.subTest(label=label), self.assertRaises(ValueError):
                self.bridge(**kwargs)

    def test_tu_wide_external_data_filters_only_the_exact_aggregate(
        self,
    ) -> None:
        unrelated = (
            "?g_Unrelated@@3HA",
            self.aggregate_symbol,
            "_another_data_symbol",
        )
        self.assertTrue(
            self.bridge(
                candidate=self.candidate(
                    undefined_external_data=unrelated,
                    defined_external_data=("?g_DefinedElsewhere@@3HA",),
                )
            )[1]
        )
        cases = {
            "duplicate": (
                (self.aggregate_symbol, self.aggregate_symbol),
                (),
            ),
            "wrong-case": (
                (self.aggregate_symbol.swapcase(),),
                (),
            ),
            "defined-aggregate": (
                (self.aggregate_symbol,),
                (self.aggregate_symbol,),
            ),
        }
        for label, (undefined, defined) in cases.items():
            with self.subTest(label=label), self.assertRaises(ValueError):
                self.bridge(
                    candidate=self.candidate(
                        undefined_external_data=undefined,
                        defined_external_data=defined,
                    )
                )

