    def test_cleanup_classifier_preserves_true_and_ambiguous_adjustments(
        self,
    ) -> None:
        cases = {
            "true-adjacent-cleanup": (
                4,
                (
                    "00401000 81 ec 80 00 00 00 sub esp, 0x80",
                    "00401006 e8 00 00 00 00 call 0x402000",
                    "0040100b 83 c4 04 add esp, 4",
                    "0040100e 33 c0 xor eax, eax",
                    "00401010 81 c4 80 00 00 00 add esp, 0x80",
                    "00401016 c3 ret",
                ),
            ),
            "scheduled-true-cleanup": (
                4,
                (
                    "00401000 e8 00 00 00 00 call 0x402000",
                    "00401005 8b ff mov edi, edi",
                    "00401007 83 c4 04 add esp, 4",
                    "0040100a c3 ret",
                ),
            ),
            "no-return-value-proof": (
                128,
                (
                    "00401000 81 ec 80 00 00 00 sub esp, 0x80",
                    "00401006 e8 00 00 00 00 call 0x402000",
                    "0040100b 8b ff mov edi, edi",
                    "0040100d 81 c4 80 00 00 00 add esp, 0x80",
                    "00401013 c3 ret",
                ),
            ),
            "ambiguous-frame-allocation": (
                128,
                (
                    "00401000 81 ec 80 00 00 00 sub esp, 0x80",
                    "00401006 81 ec 80 00 00 00 sub esp, 0x80",
                    "0040100c e8 00 00 00 00 call 0x402000",
                    "00401011 33 c0 xor eax, eax",
                    "00401013 81 c4 80 00 00 00 add esp, 0x80",
                    "00401019 c3 ret",
                ),
            ),
            "wrong-frame-size": (
                128,
                (
                    "00401000 83 ec 7c sub esp, 0x7c",
                    "00401003 e8 00 00 00 00 call 0x402000",
                    "00401008 33 c0 xor eax, eax",
                    "0040100a 81 c4 80 00 00 00 add esp, 0x80",
                    "00401010 c3 ret",
                ),
            ),
            "nonterminal-adjustment": (
                128,
                (
                    "00401000 81 ec 80 00 00 00 sub esp, 0x80",
                    "00401006 e8 00 00 00 00 call 0x402000",
                    "0040100b 33 c0 xor eax, eax",
                    "0040100d 81 c4 80 00 00 00 add esp, 0x80",
                    "00401013 eb 00 jmp 0x401015",
                ),
            ),
            "intervening-return-work": (
                128,
                (
                    "00401000 81 ec 80 00 00 00 sub esp, 0x80",
                    "00401006 e8 00 00 00 00 call 0x402000",
                    "0040100b 33 c0 xor eax, eax",
                    "0040100d 8b ff mov edi, edi",
                    "0040100f 81 c4 80 00 00 00 add esp, 0x80",
                    "00401015 c3 ret",
                ),
            ),
        }
        for label, (expected, lines) in cases.items():
            instructions = tuple(
                parse_assembly("\n".join(lines), source="bn")
            )
            call_index = next(
                index
                for index, instruction in enumerate(instructions)
                if instruction.raw_text.lower().startswith("call")
            )
            with self.subTest(label=label):
                self.assertEqual(
                    expected,
                    call_contract_verify_module._cleanup_after(
                        instructions, call_index
                    ),
                )

    def _shifted_candidate_unit(
        self,
        rows: tuple[tuple[int, bytes, str], ...],
        *,
        size: int = 0x60,
    ) -> CandidateAssembly:
        listing = "\n".join(
            f"{offset:05x} {body.hex(' ')} {text}"
            for offset, body, text in rows
        )
        data = bytearray(size)
        for offset, body, _text in rows:
            data[offset : offset + len(body)] = body
        return CandidateAssembly(
            instructions=tuple(parse_assembly(listing, source="cod")),
            local_control_flow_indices=frozenset(),
            caller_definition=CandidateCallerDefinition(
                symbol="?Unit@@YAXXZ",
                data=bytes(data),
                relocations=(),
                relocation_mask=(False,) * len(data),
                undefined_external_functions=(),
            ),
        )

    def test_shifted_candidate_instruction_unit_accepts_unique_offset_drift(
        self,
    ) -> None:
        candidate = self._shifted_candidate_unit(
            (
                (0x20, bytes.fromhex("8b 41 04"), "mov eax, dword [ecx+4]"),
                (0x23, bytes.fromhex("ff 50 20"), "call dword [eax+32]"),
            )
        )
        shift, offsets, _by_offset, index_by_offset = (
            _locate_shifted_candidate_instruction_unit(
                candidate,
                {
                    0x10: (
                        ("8b", "41", "04"),
                        r"mov\s+eax\s*,\s*dword\s+\[ecx\+4\]",
                    ),
                    0x13: (
                        ("ff", "50", "20"),
                        r"call\s+dword\s+\[eax\+32\]",
                    ),
                },
                label="unit-test shifted candidate",
            )
        )
        self.assertEqual(shift, 0x10)
        self.assertEqual(offsets, (0x20, 0x23))
        self.assertEqual(index_by_offset, {0x20: 0, 0x23: 1})

    def test_shifted_candidate_instruction_unit_rejects_duplicate_unit(
        self,
    ) -> None:
        candidate = self._shifted_candidate_unit(
            (
                (0x20, bytes.fromhex("8b 41 04"), "mov eax, dword [ecx+4]"),
                (0x23, bytes.fromhex("ff 50 20"), "call dword [eax+32]"),
                (0x30, bytes.fromhex("8b 41 04"), "mov eax, dword [ecx+4]"),
                (0x33, bytes.fromhex("ff 50 20"), "call dword [eax+32]"),
            )
        )
        with self.assertRaisesRegex(ValueError, "found 2"):
            _locate_shifted_candidate_instruction_unit(
                candidate,
                {
                    0x10: (
                        ("8b", "41", "04"),
                        r"mov\s+eax\s*,\s*dword\s+\[ecx\+4\]",
                    ),
                    0x13: (
                        ("ff", "50", "20"),
                        r"call\s+dword\s+\[eax\+32\]",
                    ),
                },
                label="unit-test duplicated candidate",
            )

    def test_shifted_candidate_instruction_unit_rejects_internal_drift_or_reorder(
        self,
    ) -> None:
        expected_rows = {
            0x10: (
                ("8b", "41", "04"),
                r"mov\s+eax\s*,\s*dword\s+\[ecx\+4\]",
            ),
            0x13: (
                ("ff", "50", "20"),
                r"call\s+dword\s+\[eax\+32\]",
            ),
        }
        for rows in (
            (
                (0x20, bytes.fromhex("8b 41 04"), "mov eax, dword [ecx+4]"),
                (0x24, bytes.fromhex("ff 50 20"), "call dword [eax+32]"),
            ),
            (
                (0x20, bytes.fromhex("ff 50 20"), "call dword [eax+32]"),
                (0x23, bytes.fromhex("8b 41 04"), "mov eax, dword [ecx+4]"),
            ),
        ):
            with self.subTest(rows=rows), self.assertRaisesRegex(
                ValueError,
                "found 0",
            ):
                _locate_shifted_candidate_instruction_unit(
                    self._shifted_candidate_unit(rows),
                    expected_rows,
                    label="unit-test malformed candidate",
                )

