    def test_reviewed_exact_indirect_storage_bridge_fails_closed(
        self,
    ) -> None:
        indexes = IdentityIndexes(
            by_address={},
            by_candidate_name={},
            provider_ids=frozenset(),
            storage_by_address={},
            storage_by_name={},
            storage_containers=(),
        )
        exact = ReviewedExactIndirectStorageBridge(
            register="edx",
            storage_identity="load(storage:recoil:data:0x4e6638)",
            slot_displacement=0x0C,
            assembly_source="cod",
        )
        cases = {
            "register": (
                "00010 ff 50 0c call DWORD PTR [eax+12]",
                exact,
                "does not match",
            ),
            "slot": (
                "00010 ff 52 10 call DWORD PTR [edx+16]",
                exact,
                "does not match",
            ),
            "source": (
                "00010 ff 52 0c call DWORD PTR [edx+12]",
                replace(exact, assembly_source="bn"),
                "declared assembly source",
            ),
            "iat-storage": (
                "00010 ff 52 0c call DWORD PTR [edx+12]",
                replace(exact, storage_identity="iat:recoil:data:0x4cc500"),
                "does not match",
            ),
        }
        for label, (assembly, bridge, message) in cases.items():
            with self.subTest(label=label):
                with self.assertRaisesRegex(ValueError, message):
                    extract_invocation_contract(
                        tuple(parse_assembly(assembly, source="cod")),
                        source="cod",
                        caller_identity=(
                            "symbol:recoil:function:0x410160"
                        ),
                        caller_start="0x410160",
                        caller_end_exclusive="0x410d10",
                        indexes=indexes,
                        reviewed_exact_indirect_storage_bridges={
                            "0x10": bridge
                        },
                    )

        with self.assertRaisesRegex(
            ValueError,
            "unused reviewed exact indirect storage bridge",
        ):
            extract_invocation_contract(
                (),
                source="cod",
                caller_identity="symbol:recoil:function:0x410160",
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=indexes,
                reviewed_exact_indirect_storage_bridges={"0x10": exact},
            )

        with self.assertRaisesRegex(ValueError, "declared assembly source"):
            extract_invocation_contract(
                tuple(
                    parse_assembly(
                        "00410170 ff 52 0c call dword [edx+0xc]",
                        source="bn",
                    )
                ),
                source="bn",
                caller_identity="symbol:recoil:function:0x410160",
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=indexes,
                reviewed_exact_indirect_storage_bridges={
                    "0x410170": exact
                },
            )

        retail_exact = replace(exact, assembly_source="bn")
        retail_contract = extract_invocation_contract(
            tuple(
                parse_assembly(
                    "00410170 ff 52 0c call dword [edx+0xc]",
                    source="bn",
                )
            ),
            source="bn",
            caller_identity="symbol:recoil:function:0x410160",
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=indexes,
            reviewed_exact_indirect_storage_bridges={
                "0x410170": retail_exact
            },
        )
        self.assertEqual("virtual-slot", retail_contract[0]["identity_kind"])
        self.assertEqual(
            "load(storage:recoil:data:0x4e6638)",
            retail_contract[0]["storage_identity"],
        )

