    def _prove_hud_string_menu_generated_destructor(
        self,
        fixture: dict,
        **overrides: object,
    ) -> bool:
        arguments = {
            "expected": fixture["expected"],
            "document": fixture["document"],
            "candidate": fixture["candidate"],
            "caller_identity": "symbol:recoil:function:0x40fbd0",
            "caller_start": "0x40fbd0",
            "caller_end_exclusive": "0x40fdd0",
            "indexes": fixture["indexes"],
            "bridge_names": fixture["bridge_names"],
            "bridge": fixture["bridge"],
            "invocation_row": fixture["invocation_row"],
        }
        arguments.update(overrides)
        return _prove_hud_ui_string_menu_generated_destructor_bridge(
            fixture["candidate_name"],
            fixture["target_identity"],
            **arguments,
        )

    def test_hud_string_menu_generated_destructor_exact_bridge(self) -> None:
        fixture = self._hud_string_menu_generated_destructor_fixture()
        self.assertEqual(
            {
                fixture["candidate_name"]: fixture["target_identity"],
            },
            _compiler_destructor_provider_bridges(
                fixture["expected"],
                fixture["candidate"],
                document=fixture["document"],
                caller_identity="symbol:recoil:function:0x40fbd0",
                caller_start="0x40fbd0",
                caller_end_exclusive="0x40fdd0",
                indexes=fixture["indexes"],
                bridge_names=fixture["bridge_names"],
                bridge=fixture["bridge"],
            ),
        )

    def test_hud_string_menu_generated_destructor_rejects_identity_drift(
        self,
    ) -> None:
        fixture = self._hud_string_menu_generated_destructor_fixture()
        for label, overrides in {
            "caller": {"caller_start": "0x40fbd1"},
            "ordinal": {
                "invocation_row": {
                    **fixture["invocation_row"],
                    "ordinal": 17,
                }
            },
            "form": {
                "invocation_row": {
                    **fixture["invocation_row"],
                    "form": "tail",
                }
            },
            "cleanup": {
                "invocation_row": {
                    **fixture["invocation_row"],
                    "cleanup_bytes": 4,
                }
            },
        }.items():
            with self.subTest(label=label):
                with self.assertRaises(ValueError):
                    self._prove_hud_string_menu_generated_destructor(
                        fixture,
                        **overrides,
                    )
        self.assertFalse(
            _prove_hud_ui_string_menu_generated_destructor_bridge(
                "??1OtherMenu@@QAE@XZ",
                fixture["target_identity"],
                expected=fixture["expected"],
                document=fixture["document"],
                candidate=fixture["candidate"],
                caller_identity="symbol:recoil:function:0x40fbd0",
                caller_start="0x40fbd0",
                caller_end_exclusive="0x40fdd0",
                indexes=fixture["indexes"],
                bridge_names=fixture["bridge_names"],
                bridge=fixture["bridge"],
                invocation_row=fixture["invocation_row"],
            )
        )

    def test_hud_string_menu_generated_destructor_rejects_caller_drift(
        self,
    ) -> None:
        fixture = self._hud_string_menu_generated_destructor_fixture()
        caller = fixture["caller"]
        bad_cleanup = bytearray(caller.data)
        bad_cleanup[0xFB] = 8
        duplicate_relocation = replace(
            fixture["candidate"],
            caller_definition=replace(
                caller,
                relocations=(
                    *caller.relocations,
                    caller.relocations[1],
                ),
            ),
        )
        fake_helper = replace(
            fixture["candidate"],
            caller_definition=replace(
                caller,
                defined_external_functions=(
                    *caller.defined_external_functions,
                    fixture["fake_core"],
                ),
            ),
        )
        for label, candidate in {
            "cleanup": replace(
                fixture["candidate"],
                caller_definition=replace(
                    caller,
                    data=bytes(bad_cleanup),
                ),
            ),
            "duplicate": duplicate_relocation,
            "authored-helper": fake_helper,
        }.items():
            with self.subTest(label=label):
                with self.assertRaises(ValueError):
                    self._prove_hud_string_menu_generated_destructor(
                        fixture,
                        candidate=candidate,
                    )

    def test_hud_string_menu_generated_destructor_rejects_definition_drift(
        self,
    ) -> None:
        fixture = self._hud_string_menu_generated_destructor_fixture()
        destructor = fixture["destructor"]
        vptr_body = bytearray(destructor.data)
        vptr_body[0x18] = 0xC7
        bad_panel_relocation = replace(
            destructor.relocations[3],
            symbol_name="??1WrongPanel@@UAE@XZ",
        )
        variants = {
            "vptr-store": replace(destructor, data=bytes(vptr_body)),
            "extent": replace(destructor, section_size=0x5F),
            "selection": replace(destructor, comdat_selection=1),
            "relocation": replace(
                destructor,
                relocations=(
                    *destructor.relocations[:3],
                    bad_panel_relocation,
                    *destructor.relocations[4:],
                ),
            ),
        }
        for label, definition in variants.items():
            with self.subTest(label=label):
                candidate = replace(
                    fixture["candidate"],
                    complete_destructor_definitions={
                        fixture["candidate_name"]: definition,
                    },
                )
                with self.assertRaises(ValueError):
                    self._prove_hud_string_menu_generated_destructor(
                        fixture,
                        candidate=candidate,
                    )

    def test_hud_string_menu_generated_destructor_rejects_alias_or_topology(
        self,
    ) -> None:
        fixture = self._hud_string_menu_generated_destructor_fixture()
        aliased_data = deepcopy(fixture["document"].data)
        aliased_data["symbols"]["recoil:function:0x40fdd0"][
            "logical_identity_key"
        ] = "alias"
        with self.assertRaises(ValueError):
            self._prove_hud_string_menu_generated_destructor(
                fixture,
                document=ProgressDocument(aliased_data),
            )
        wrong_delete_expected = deepcopy(fixture["expected"])
        wrong_delete_expected[19]["cleanup_bytes"] = None
        with self.assertRaises(ValueError):
            self._prove_hud_string_menu_generated_destructor(
                fixture,
                expected=wrong_delete_expected,
            )
        wrong_bridge = SimpleNamespace(
            hexdump=fixture["bridge"].hexdump,
            assembly=lambda address: "\n".join(
                [
                    "0040fe00 e8 00 00 00 00 call 0x4bc7b0",
                    "0040fe0f e8 00 00 00 00 call 0x4bc7b0",
                ]
            ),
        )
        with self.assertRaises(ValueError):
            self._prove_hud_string_menu_generated_destructor(
                fixture,
                bridge=wrong_bridge,
            )

