    def test_compiler_authored_destructor_bridge_rejects_invalid_caller_object_evidence(
        self,
    ) -> None:
        fixture = self._authored_destructor_bridge_fixture()
        caller = fixture["caller_definition"]
        relocation = caller.relocations[0]
        cases = (
            (
                "missing caller",
                None,
                "requires exactly one undefined and no defined",
            ),
            (
                "duplicate undefined external",
                replace(
                    caller,
                    undefined_external_functions=(
                        fixture["candidate_name"],
                        fixture["candidate_name"],
                    ),
                ),
                "requires exactly one undefined and no defined",
            ),
            (
                "defined collision",
                replace(
                    caller,
                    defined_external_functions=(fixture["candidate_name"],),
                ),
                "requires exactly one undefined and no defined",
            ),
            (
                "missing relocation",
                replace(caller, relocations=()),
                "requires exactly one caller-object relocation",
            ),
            (
                "duplicate relocation",
                replace(
                    caller,
                    relocations=(relocation, relocation),
                ),
                "requires exactly one caller-object relocation",
            ),
            (
                "wrong relocation type",
                replace(
                    caller,
                    relocations=(replace(relocation, type=0x06),),
                ),
                "relocation is not REL32",
            ),
            (
                "out-of-range relocation",
                replace(
                    caller,
                    relocations=(replace(relocation, offset=2),),
                ),
                "REL32 relocation is out of range",
            ),
            (
                "partially unmasked relocation",
                replace(
                    caller,
                    relocation_mask=(False, True, True, True, False),
                ),
                "REL32 relocation is not fully masked",
            ),
            (
                "nonzero relocation addend",
                replace(
                    caller,
                    data=bytes.fromhex("e8 01 00 00 00"),
                ),
                "REL32 relocation has a nonzero addend",
            ),
            (
                "opcode mismatch",
                replace(
                    caller,
                    data=bytes.fromhex("e9 00 00 00 00"),
                ),
                "opcode does not match its exact direct invocation form",
            ),
        )
        for label, caller_definition, message in cases:
            with self.subTest(label=label):
                fixture["candidate"] = replace(
                    fixture["candidate"],
                    caller_definition=caller_definition,
                )
                with self.assertRaisesRegex(ValueError, message):
                    self._prove_authored_destructor_bridges(fixture)

