    def test_briefing_runtime_vftable_proof_defers_exact_reviewed_eh_helper(
        self,
    ) -> None:
        fixture = self._briefing_runtime_vftable_fixture()
        helper_name = "??_M@YGXPAXIHP6EX0@Z@Z"
        caller = fixture["caller_definition"]
        caller_data = caller.data[:-1] + bytes.fromhex(
            "e8 00 00 00 00 c3"
        )
        helper_offset = len(caller.data)
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=fixture["candidate"].instructions
            + tuple(
                parse_assembly(
                    "  0000e e8 00 00 00 00 call "
                    f"{helper_name}",
                    source="cod",
                )
            ),
            caller_definition=replace(
                caller,
                data=caller_data,
                relocations=caller.relocations
                + (
                    CoffRelocation(
                        offset=helper_offset,
                        symbol_index=5,
                        type=0x14,
                        symbol_name=helper_name,
                    ),
                ),
                relocation_mask=caller.relocation_mask[:-1]
                + (False, True, True, True, True, False),
                undefined_external_functions=(helper_name,),
            ),
        )
        fixture["expected"].append(
            {
                "ordinal": 1,
                "form": "call",
                "dispatch": "direct",
                "identity_kind": "provider",
                "target_identity": "provider:recoil:function:0x4c5ec0",
                "storage_identity": "",
                "slot_displacement": None,
                "cleanup_bytes": None,
            }
        )
        fixture["caller_identity"] = "symbol:recoil:function:0x403ed0"
        self.assertEqual(
            {
                fixture["vftable_name"].lower():
                fixture["storage_identity"]
            },
            self._prove_briefing_runtime_vftable(fixture),
        )

        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=fixture["candidate"].instructions
            + tuple(
                parse_assembly(
                    "  00013 e8 00 00 00 00 call "
                    f"{helper_name}",
                    source="cod",
                )
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "exactly 1 main-procedure exact direct helper call",
        ):
            self._prove_briefing_runtime_vftable(fixture)

