    def test_schema112_ftol_live_local_thunk_population_normalizes_to_provider(
        self,
    ) -> None:
        fixture = self._briefing_locator_panel_ftol_fixture()
        provider_identity, retail_names = self._prove_ftol_retail_bridge(
            fixture
        )
        thunk = ProviderNamedImportThunk(
            provider_identity=provider_identity,
            thunk_address="0x4c60a6",
            retail_name="_ftol_import_thunk",
            callable_symbol="__ftol",
            iat_object_symbol="__imp___ftol",
            iat_identity="iat:_ftol",
            iat_address="0x4cc5ac",
            import_dll="MSVCRT.dll",
            import_name="_ftol",
        )
        call_address = 0x403D26
        tail_address = 0x407209
        encoded = b"\xe8" + struct.pack(
            "<i", int(thunk.thunk_address, 16) - (call_address + 5)
        )
        tail_encoded = b"\xe9" + struct.pack(
            "<i", int(thunk.thunk_address, 16) - (tail_address + 5)
        )
        retail = tuple(
            parse_assembly(
                f"{call_address:08x} "
                + " ".join(f"{value:02x}" for value in encoded)
                + " call _ftol_import_thunk",
                source="bn",
            )
        )
        tail_retail = tuple(
            parse_assembly(
                f"{tail_address:08x} "
                + " ".join(f"{value:02x}" for value in tail_encoded)
                + " jmp _ftol_import_thunk",
                source="bn",
            )
        )
        local_population = (*retail, *tail_retail)
        class LiveFtolBridge:
            @staticmethod
            def hexdump(address, size):
                values = {
                    (hex(call_address), 5): encoded,
                    (hex(tail_address), 5): tail_encoded,
                    ("0x4c60a6", 10): bytes.fromhex(
                        "ff 25 ac c5 4c 00 cc cc cc cc"
                    ),
                    ("0x4cc5ac", 4): bytes.fromhex("10 20 30 40"),
                }
                body = values[(address, size)]
                return f"{int(address, 16):08x} " + " ".join(
                    f"{value:02x}" for value in body
                )

            @staticmethod
            def assembly(address):
                if address != "0x4c60a6":
                    raise AssertionError(address)
                return "004c60a6 ff 25 ac c5 4c 00 jmp dword [0x4cc5ac]"

        local_indexes = (
            call_contract_verify_module._retail_local_named_import_thunk_indexes(
                local_population,
                document=fixture["document"],
                indexes=fixture["indexes"],
                bridge=LiveFtolBridge(),
                caller_start=hex(call_address),
                retail_import_targets=(
                    SimpleNamespace(
                        address="0x4cc5ac",
                        dll="MSVCRT.dll",
                        import_name="_ftol",
                        import_ordinal=None,
                    ),
                ),
            )
        )
        self.assertEqual(
            ("0x4c60a6", "iat:_ftol"),
            local_indexes.reviewed_exact_local_import_thunk_by_call_site[
                hex(call_address)
            ],
        )
        self.assertEqual(
            ("0x4c60a6", "iat:_ftol"),
            local_indexes.reviewed_exact_local_import_thunk_by_call_site[
                hex(tail_address)
            ],
        )
        retail_indexes = (
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                local_population,
                indexes=local_indexes,
                thunks=(thunk,),
                preserved_provider_identities=frozenset({provider_identity}),
            )
        )
        self.assertNotIn(
            hex(call_address),
            retail_indexes.reviewed_exact_local_import_thunk_by_call_site,
        )
        self.assertNotIn(
            hex(tail_address),
            retail_indexes.reviewed_exact_local_import_thunk_by_call_site,
        )
        self.assertEqual(
            ("0x4c60a6", provider_identity),
            retail_indexes.reviewed_direct_import_thunk_by_call_site[
                hex(call_address)
            ],
        )
        self.assertEqual(
            ("0x4c60a6", provider_identity),
            retail_indexes.reviewed_direct_import_thunk_by_call_site[
                hex(tail_address)
            ],
        )
        expected = extract_invocation_contract(
            retail,
            source="bn",
            caller_identity="symbol:recoil:function:0x453d20",
            caller_start=hex(call_address),
            caller_end_exclusive=hex(call_address + 5),
            indexes=retail_indexes,
            bridge_names=retail_names,
        )
        self.assertEqual(
            ("call", "direct", "provider", provider_identity, None),
            (
                expected[0]["form"],
                expected[0]["dispatch"],
                expected[0]["identity_kind"],
                expected[0]["target_identity"],
                expected[0]["cleanup_bytes"],
            ),
        )

        self._set_ftol_candidate_population(fixture, ("call",))
        fixture["expected"] = expected
        bridges = self._prove_ftol_candidate(fixture)
        self.assertEqual({"__ftol": "iat:_ftol"}, bridges)
        candidate = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity="symbol:recoil:function:0x453d20",
            caller_start="0x453d20",
            caller_end_exclusive="0x453d60",
            indexes=fixture["indexes"],
            bridge_names=retail_names,
            compiler_generated_bridges=bridges,
        )
        self.assertEqual("direct", candidate[0]["identity_kind"])
        self.assertTrue(
            compare_call_contracts(
                expected,
                candidate,
                reviewed_direct_target_equivalences={
                    "iat:_ftol": provider_identity,
                },
            )["passed"]
        )

        conflicting_local = replace(
            local_indexes,
            reviewed_exact_local_import_thunk_by_call_site={
                hex(call_address): ("0x4c60a6", "iat:wrong")
            },
        )
        with self.assertRaisesRegex(
            ValueError,
            "conflicts with its exact-local import-thunk selector",
        ):
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                retail,
                indexes=conflicting_local,
                thunks=(thunk,),
                preserved_provider_identities=frozenset({provider_identity}),
            )

    def test_ftol_provisional_accepts_registered_timer_panel_target_and_conflict_fails(
        self,
    ) -> None:
        fixture = self._briefing_locator_panel_ftol_fixture()
        timer_name = (
            "?UpdateHMSFromSeconds@HudUiTimerPanel@@QAEXM@Z"
        )
        timer_identity = "symbol:recoil:function:0x40ee60"
        other_name = next(iter(fixture["indexes"].by_candidate_name))
        other_identity = fixture["indexes"].by_candidate_name[other_name]
        candidate = fixture["candidate"]
        candidate_lines = [
            instruction.source_line.replace(other_name, timer_name)
            if other_name in instruction.source_line
            else instruction.source_line
            for instruction in candidate.instructions
        ]
        fixture["candidate"] = replace(
            candidate,
            instructions=tuple(
                parse_assembly("\n".join(candidate_lines), source="cod")
            ),
        )
        fixture["indexes"] = replace(
            fixture["indexes"],
            by_candidate_name={
                name: identity
                for name, identity in fixture[
                    "indexes"
                ].by_candidate_name.items()
                if name != other_name
            },
        )
        fixture["expected"][0] = {
            **fixture["expected"][0],
            "target_identity": timer_identity,
        }
        bridges = self._prove_ftol_candidate(
            fixture,
            reviewed_candidate_direct_bridges={
                timer_name: timer_identity,
            },
        )
        self.assertEqual(
            {"__ftol": "iat:_ftol"},
            bridges,
        )
        contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x403cb0",
            caller_end_exclusive="0x403d70",
            indexes=fixture["indexes"],
            bridge_names={
                "_ftol_import_thunk": [fixture["thunk_symbol"]]
            },
            compiler_generated_bridges={
                timer_name: timer_identity,
                **bridges,
            },
        )
        self.assertTrue(
            compare_call_contracts(
                fixture["expected"],
                contract,
                reviewed_direct_target_equivalences={
                    "iat:_ftol": fixture["provider_identity"],
                },
            )["passed"]
        )
        self.assertEqual(
            (timer_identity, "iat:_ftol"),
            (
                contract[0]["target_identity"],
                contract[-1]["target_identity"],
            ),
        )

        fixture["expected"][0] = {
            **fixture["expected"][0],
            "target_identity": other_identity,
        }
        with self.assertRaisesRegex(
            ValueError,
            "conflicts with an already-reviewed candidate direct bridge",
        ):
            self._prove_ftol_candidate(
                fixture,
                reviewed_candidate_direct_bridges={
                    "__ftol": "provider:wrong",
                },
            )

