    def test_ensure_unsupported_helper_bridge_is_candidate_only_and_exact(
        self,
    ) -> None:
        caller_identity = "symbol:recoil:function:0x410160"
        discriminator = "123"
        cod_symbol = (
            "?HudUiSetFontFromRect@?_tu_order\\00_hud.cpp"
            f"{discriminator}"
            "@@YIXPAUHudUiPanel@@ABUHudUiRect@@@Z"
        )
        coff_symbol = cod_symbol.replace(
            "@?_tu_order\\",
            "@?%_tu_order\\",
            1,
        )
        offsets = (0x722, 0x731)
        instructions = tuple(
            parse_assembly(
                "\n".join(
                    f"{offset:05x} e8 00 00 00 00 call {cod_symbol}"
                    for offset in offsets
                ),
                source="cod",
            )
        )
        body = bytearray(0xC30)
        mask = [False] * len(body)
        relocations: list[CoffRelocation] = []
        for index, offset in enumerate(offsets):
            body[offset] = 0xE8
            relocations.append(
                CoffRelocation(
                    offset=offset + 1,
                    symbol_index=1200 + index,
                    type=0x14,
                    symbol_name=coff_symbol,
                )
            )
            for field_index in range(offset + 1, offset + 5):
                mask[field_index] = True
        candidate = CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=frozenset(),
            tu_local_function_definitions={
                coff_symbol: CandidateTuLocalFunctionDefinition(
                    symbol=coff_symbol,
                    data=b"\xc3",
                    relocations=(),
                    relocation_mask=(False,),
                    section_size=1,
                    section_external_functions=(coff_symbol,),
                )
            },
            caller_definition=CandidateCallerDefinition(
                symbol="?EnsureHudLoaded@HudUiMgr@@YIHPBD@Z",
                data=bytes(body),
                relocations=tuple(relocations),
                relocation_mask=tuple(mask),
                undefined_external_functions=(),
                defined_external_functions=(coff_symbol,),
            ),
        )
        indexes = IdentityIndexes(
            by_address={"0x410160": caller_identity},
            by_candidate_name={},
            provider_ids=frozenset(),
            storage_by_address={},
            storage_by_name={},
        )
        bridges = _hud_ui_mgr_ensure_unsupported_helpers_candidate_bridges(
            [],
            candidate,
            caller_identity=caller_identity,
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=indexes,
            bridge_names={},
            compiler_generated_bridges={},
        )

        self.assertEqual({cod_symbol: caller_identity}, bridges)
        contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=caller_identity,
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=indexes,
            compiler_generated_bridges=bridges,
        )
        self.assertEqual(
            [caller_identity, caller_identity],
            [row["target_identity"] for row in contract],
        )
        self.assertTrue(
            all(row["identity_kind"] == "direct" for row in contract)
        )

        drifted = replace(
            candidate,
            instructions=tuple(
                parse_assembly(
                    "\n".join(
                        [
                            (
                                "00723 e8 00 00 00 00 "
                                f"call {cod_symbol}"
                            ),
                            (
                                "00731 e8 00 00 00 00 "
                                f"call {cod_symbol}"
                            ),
                        ]
                    ),
                    source="cod",
                )
            ),
        )
        with self.assertRaisesRegex(ValueError, "ordered COFF relocation"):
            _hud_ui_mgr_ensure_unsupported_helpers_candidate_bridges(
                [],
                drifted,
                caller_identity=caller_identity,
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=indexes,
                bridge_names={},
                compiler_generated_bridges={},
            )

        shifted_offsets = tuple(offset + 0x20 for offset in offsets)
        shifted_body = bytearray(candidate.caller_definition.data)
        shifted_mask = list(candidate.caller_definition.relocation_mask)
        for offset in offsets:
            shifted_body[offset : offset + 5] = b"\0" * 5
            shifted_mask[offset : offset + 5] = [False] * 5
        shifted_relocations = []
        for index, offset in enumerate(shifted_offsets):
            shifted_body[offset : offset + 5] = b"\xe8\0\0\0\0"
            shifted_mask[offset + 1 : offset + 5] = [True] * 4
            shifted_relocations.append(
                CoffRelocation(
                    offset=offset + 1,
                    symbol_index=1300 + index,
                    type=0x14,
                    symbol_name=coff_symbol,
                )
            )
        shifted = replace(
            candidate,
            instructions=tuple(
                parse_assembly(
                    "\n".join(
                        f"{offset:05x} e8 00 00 00 00 call {cod_symbol}"
                        for offset in shifted_offsets
                    ),
                    source="cod",
                )
            ),
            caller_definition=replace(
                candidate.caller_definition,
                data=bytes(shifted_body),
                relocations=tuple(shifted_relocations),
                relocation_mask=tuple(shifted_mask),
            ),
        )
        self.assertEqual(
            {cod_symbol: caller_identity},
            _hud_ui_mgr_ensure_unsupported_helpers_candidate_bridges(
                [],
                shifted,
                caller_identity=caller_identity,
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=indexes,
                bridge_names={},
                compiler_generated_bridges={},
            ),
        )

        fixture = self._briefing_locator_panel_ftol_fixture()
        self._set_ftol_candidate_population(
            fixture,
            ("other", "other", "other", "other", "tail"),
        )
        bridges = self._prove_ftol_candidate(fixture)
        contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x4071f0",
            caller_end_exclusive="0x40720e",
            indexes=fixture["indexes"],
            bridge_names={
                "_ftol_import_thunk": [fixture["thunk_symbol"]]
            },
            compiler_generated_bridges=bridges,
        )
        self.assertTrue(
            compare_call_contracts(
                fixture["expected"],
                contract,
                reviewed_direct_target_equivalences={
                    "iat:_ftol": fixture["provider_identity"],
                },
            )["passed"]
        )

