    def test_forward_branch_rejects_prefixed_trailing_indirect_and_unsupported(
        self,
    ) -> None:
        cases = {
            "prefixed-jcc": (
                "00401000 66 74 0d je 0x401010",
                frozenset(),
            ),
            "trailing-jcc-byte": (
                "00401000 74 0e 90 je 0x401010",
                frozenset(),
            ),
            "prefixed-jmp": (
                "00401000 66 eb 0d jmp 0x401010",
                frozenset(),
            ),
            "trailing-jmp-byte": (
                "00401000 eb 0e 90 jmp 0x401010",
                frozenset(),
            ),
            "indirect-jump": (
                "00401000 ff e0 jmp eax",
                frozenset({0}),
            ),
            "unsupported-jecxz": (
                "00401000 e3 0e jecxz 0x401010",
                frozenset(),
            ),
            "opcode-mnemonic-mismatch": (
                "00401000 74 0e jg 0x401010",
                frozenset(),
            ),
        }
        tail = [
            "00401004 c3 ret",
            "00401010 8b 01 mov eax, [ecx]",
            "00401012 ff 50 20 call [eax+0x20]",
        ]
        for label, (branch, local_indices) in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "unresolved indirect register storage eax",
            ):
                extract_invocation_contract(
                    parse_assembly(
                        "\n".join([branch, *tail]),
                        source="bn",
                    ),
                    source="bn",
                    caller_identity="symbol:caller",
                    caller_start="0x401000",
                    caller_end_exclusive="0x401100",
                    indexes=self.indexes,
                    local_control_flow_indices=local_indices,
                )

