        contract = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "00405000 8b 01 mov eax, [ecx]",
                        "00405002 0f 84 18 00 00 00 je 0x405020",
                        "00405008 ff 50 20 call [eax+0x20]",
                        "0040500b c3 ret",
                        "00405020 ff 50 20 call [eax+0x20]",
                        "00405023 c3 ret",
                    ]
                ),
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:synthetic-later-recurrence",
            caller_start="0x405000",
            caller_end_exclusive="0x405100",
            indexes=self.indexes,
        )
        self.assertEqual([0, 1], [row["ordinal"] for row in contract])
        self.assertEqual(
            ["load(this)", "load(this)"],
            [row["storage_identity"] for row in contract],
        )
        self.assertEqual(
            [0x20, 0x20],
            [row["slot_displacement"] for row in contract],
        )

