    def test_wrapped_cod_branch_without_exact_prior_address_fails_closed(
        self,
    ) -> None:
        cases = {
            "no-prior-instruction": [
                "  00000 0f 84 0a 00 00",
                "  00 je 0x10",
                "  00006 c3 ret 0",
                "  00010 8b 01 mov eax, [ecx]",
                "  00012 ff 50 20 call [eax+32]",
            ],
            "prior-has-no-exact-byte-length": [
                "  00000 nop",
                "  00001 0f 84 09 00 00",
                "  00 je 0x10",
                "  00007 c3 ret 0",
                "  00010 8b 01 mov eax, [ecx]",
                "  00012 ff 50 20 call [eax+32]",
            ],
        }
        for label, lines in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "unresolved indirect register storage eax",
            ):
                extract_invocation_contract(
                    parse_assembly("\n".join(lines), source="cod"),
                    source="cod",
                    caller_identity="symbol:wrapped-near-branch",
                    caller_start="0x405000",
                    caller_end_exclusive="0x405100",
                    indexes=self.indexes,
                )

    def test_indirect_base_register_displacement_precedes_absolute_storage(self) -> None:
        indexes = IdentityIndexes(
            by_address=self.indexes.by_address,
            by_candidate_name=self.indexes.by_candidate_name,
            provider_ids=self.indexes.provider_ids,
            storage_by_address={
                **self.indexes.storage_by_address,
                "0x4cc5b4": "iat:free",
            },
            storage_by_name={"free": "iat:free"},
        )
        virtual = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "004038a0 8b f1 mov esi, ecx",
                        "004038a2 8b 06 mov eax, dword [esi]",
                        "004038a4 ff 50 64 call dword [eax+0x64]",
                    ]
                ),
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:caller",
            caller_start="0x4038a0",
            caller_end_exclusive="0x403900",
            indexes=indexes,
        )
        self.assertEqual("virtual-slot", virtual[0]["identity_kind"])
        self.assertEqual(0x64, virtual[0]["slot_displacement"])
        self.assertEqual("load(this)", virtual[0]["storage_identity"])

        negative = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "004038a0 8b f1 mov esi, ecx",
                        "004038a2 8b 06 mov eax, dword [esi]",
                        "004038a4 ff 50 fc call dword [eax-0x4]",
                    ]
                ),
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:caller",
            caller_start="0x4038a0",
            caller_end_exclusive="0x403900",
            indexes=indexes,
        )
        self.assertEqual(-4, negative[0]["slot_displacement"])
        self.assertEqual("load(this)", negative[0]["storage_identity"])

        absolute = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "004038a0 ff 15 b4 c5 4c 00 call dword [0x4cc5b4]",
                        "004038a6 ff 15 00 00 50 00 call dword [0x500000]",
                    ]
                ),
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:caller",
            caller_start="0x4038a0",
            caller_end_exclusive="0x403900",
            indexes=indexes,
        )
        self.assertEqual("iat:free", absolute[0]["target_identity"])
        self.assertEqual("storage:callback", absolute[1]["storage_identity"])

        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register storage eax",
        ):
            extract_invocation_contract(
                parse_assembly(
                    "004038a0 ff 90 b4 c5 4c 00 call dword [eax+0x4cc5b4]",
                    source="bn",
                ),
                source="bn",
                caller_identity="symbol:caller",
                caller_start="0x4038a0",
                caller_end_exclusive="0x403900",
                indexes=indexes,
            )

