    def _prove_cached_fread_retail_indexes(
        self,
        *,
        document: ProgressDocument | None = None,
        retail: list[Instruction] | None = None,
        indexes: IdentityIndexes | None = None,
        import_name: str = "fread",
    ) -> IdentityIndexes:
        document = document or self._cached_fread_scope_document()
        indexes = indexes or build_identity_indexes(document)
        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(
                SimpleNamespace(
                    address="0x4cc4e0",
                    dll="MSVCRT.dll",
                    import_name=import_name,
                    import_ordinal=None,
                ),
                {},
            ),
        ):
            return _cached_fread_retail_iat_indexes(
                retail or self._cached_fread_retail_rows(),
                document=document,
                caller_identity="symbol:recoil:function:0x415bd0",
                caller_start="0x415bd0",
                caller_end_exclusive="0x415c90",
                indexes=indexes,
            )

    def test_cached_fread_retail_identity_is_pe_bn_tracker_scoped(
        self,
    ) -> None:
        indexes = self._prove_cached_fread_retail_indexes()
        self.assertEqual("iat:fread", indexes.storage_by_address["0x4cc4e0"])
        self.assertEqual("iat:fread", indexes.storage_by_name["fread"])
        self.assertEqual("iat:fread", indexes.storage_by_name["__imp__fread"])

        retail = extract_invocation_contract(
            self._cached_fread_retail_rows(),
            source="bn",
            caller_identity="symbol:recoil:function:0x415bd0",
            caller_start="0x415bd0",
            caller_end_exclusive="0x415c90",
            indexes=indexes,
        )
        candidate = self._fread_cached_ebp_contract(
            source="cod",
            indexes=indexes,
        )
        self.assertEqual(retail, candidate)
        self.assertEqual(["iat:fread"] * 4, [
            row["target_identity"] for row in retail
        ])
        self.assertEqual([16] * 4, [
            row["cleanup_bytes"] for row in retail
        ])

    def test_cached_fread_retail_identity_fails_closed_on_authority_drift(
        self,
    ) -> None:
        tracker_drift = self._cached_fread_scope_document()
        tracker_drift.data["symbols"]["recoil:function:0x415bd0"][
            "navigation_name"
        ] = "Wrong"
        load_drift = self._cached_fread_retail_rows()
        load_drift[0] = replace(
            load_drift[0],
            bytes=("8b", "35", "e0", "c4", "4c", "00"),
        )
        cleanup_drift = self._cached_fread_retail_rows()
        cleanup_drift[2] = replace(
            cleanup_drift[2],
            raw_text="add esp, 12",
            text="add esp, 0xc",
            bytes=("83", "c4", "0c"),
        )
        conflict_document = self._cached_fread_scope_document()
        conflict_indexes = replace(
            build_identity_indexes(conflict_document),
            storage_by_address={"0x4cc4e0": "iat:wrong"},
        )
        cases = (
            ("pe", {"import_name": "Fread"}),
            ("tracker", {"document": tracker_drift}),
            ("load", {"retail": load_drift}),
            ("cleanup", {"retail": cleanup_drift}),
            (
                "conflict",
                {
                    "document": conflict_document,
                    "indexes": conflict_indexes,
                },
            ),
        )
        for label, kwargs in cases:
            with self.subTest(label=label), self.assertRaises(ValueError):
                self._prove_cached_fread_retail_indexes(**kwargs)

    def _fread_cached_ebp_contract(
        self,
        *,
        source: str,
        indexes: IdentityIndexes,
        lines: list[str] | None = None,
    ) -> list[dict]:
        default_lines = (
            [
                "00415be7 8b 2d e0 c4 4c 00 "
                "mov ebp, dword [0x4cc4e0]",
                "00415bf6 ff d5 call ebp",
                "00415bf8 83 c4 10 add esp, 0x10",
                "00415c12 ff d5 call ebp",
                "00415c14 83 c4 10 add esp, 0x10",
                "00415c41 ff d5 call ebp",
                "00415c43 83 c4 10 add esp, 0x10",
                "00415c5e ff d5 call ebp",
                "00415c60 83 c4 10 add esp, 0x10",
            ]
            if source == "bn"
            else [
                "  00017 8b 2d 00 00 00 00 "
                "mov ebp, DWORD PTR __imp__fread",
                "  00026 ff d5 call ebp",
                "  00028 83 c4 10 add esp, 16",
                "  00042 ff d5 call ebp",
                "  00044 83 c4 10 add esp, 16",
                "  00071 ff d5 call ebp",
                "  00073 83 c4 10 add esp, 16",
                "  0008e ff d5 call ebp",
                "  00090 83 c4 10 add esp, 16",
            ]
        )
        return extract_invocation_contract(
            parse_assembly("\n".join(lines or default_lines), source=source),
            source=source,
            caller_identity="symbol:recoil:function:0x415bd0",
            caller_start="0x415bd0",
            caller_end_exclusive="0x415c80",
            indexes=indexes,
        )

