    def _generic_cached_fread_document(self) -> ProgressDocument:
        data = empty_progress_document()
        data["symbols"]["recoil:function:0x4168d0"] = {
            "address": "0x4168d0",
            "binary": "recoil",
            "disposition": "unresolved",
            "end_exclusive": "0x4169d0",
            "extent_state": "known",
            "kind": "function",
            "ownership_state": "primary-owned",
            "physical_block_id": "recoil:block:0x415ab0",
            "pipeline_class": "authored",
            "size": 0x100,
        }
        return ProgressDocument(data)

    def _generic_cached_fread_contract(
        self,
        lines: list[str],
        *,
        import_name: str = "fread",
    ) -> tuple[list[dict], IdentityIndexes]:
        document = self._generic_cached_fread_document()
        indexes = build_identity_indexes(document)
        instructions = parse_assembly("\n".join(lines), source="bn")
        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(
                SimpleNamespace(
                    address="0x4cc4e0",
                    dll="MSVCRT.dll",
                    import_name=import_name,
                    import_ordinal=None,
                ),
                {},
            ),
        ):
            indexes = _cached_fread_retail_iat_indexes(
                instructions,
                document=document,
                caller_identity="symbol:recoil:function:0x4168d0",
                caller_start="0x4168d0",
                caller_end_exclusive="0x4169d0",
                indexes=indexes,
            )
        return (
            extract_invocation_contract(
                instructions,
                source="bn",
                caller_identity="symbol:recoil:function:0x4168d0",
                caller_start="0x4168d0",
                caller_end_exclusive="0x4169d0",
                indexes=indexes,
            ),
            indexes,
        )

