    def test_schema85_cached_fread_rejects_clobber_and_composes_exact_reloads(
        self,
    ) -> None:
        cases = {
            "clobber": [
                "004168fa 8b 3d e0 c4 4c 00 "
                "mov edi, dword [0x4cc4e0]",
                "00416900 33 ff xor edi, edi",
                "00416909 ff d7 call edi",
            ],
            "alternate-definitions": [
                "004168fa 74 08 je 0x416904",
                "004168fc 8b 3d e0 c4 4c 00 "
                "mov edi, dword [0x4cc4e0]",
                "00416902 eb 06 jmp 0x41690a",
                "00416904 8b 3d e0 c4 4c 00 "
                "mov edi, dword [0x4cc4e0]",
                "0041690a ff d7 call edi",
            ],
            "loop-carried": [
                "004168fa 8b 3d e0 c4 4c 00 "
                "mov edi, dword [0x4cc4e0]",
                "00416900 75 f8 jne 0x4168fa",
                "00416902 ff d7 call edi",
            ],
        }
        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register (?:storage|provenance) edi",
        ):
            self._generic_cached_fread_contract(cases["clobber"])
        for label in ("alternate-definitions", "loop-carried"):
            contract, _indexes = self._generic_cached_fread_contract(
                cases[label]
            )
            with self.subTest(label=label):
                self.assertEqual("iat:fread", contract[0]["target_identity"])

    def test_schema50_preserved_entry_stack_file_argument_survives_slot_reuse(
        self,
    ) -> None:
        retail_lines = [
            "004168d0 8b 5d 08 mov ebx, dword [ebp+8]",
            "004168d3 89 45 08 mov dword [ebp+8], eax",
            "004168d6 8b 3d e0 c4 4c 00 mov edi, dword [0x4cc4e0]",
            "004168dc 53 push ebx",
            "004168dd ff d7 call edi",
            "004168df 83 c4 10 add esp, 0x10",
            "004168e2 53 push ebx",
            "004168e3 ff d7 call edi",
            "004168e5 83 c4 10 add esp, 0x10",
            "004168e8 53 push ebx",
            "004168e9 ff d7 call edi",
            "004168eb 83 c4 10 add esp, 0x10",
        ]
        retail, indexes = self._generic_cached_fread_contract(retail_lines)
        candidate_lines = [
            "  00000 8b 5d 08 mov ebx, dword [ebp+8]",
            "  00003 89 45 08 mov dword [ebp+8], eax",
            "  00006 8b 3d 00 00 00 00 mov edi, DWORD PTR __imp__fread",
            "  0000c 53 push ebx",
            "  0000d ff d7 call edi",
            "  0000f 83 c4 10 add esp, 16",
            "  00012 53 push ebx",
            "  00013 ff d7 call edi",
            "  00015 83 c4 10 add esp, 16",
            "  00018 53 push ebx",
            "  00019 ff d7 call edi",
            "  0001b 83 c4 10 add esp, 16",
        ]
        candidate = extract_invocation_contract(
            parse_assembly("\n".join(candidate_lines), source="cod"),
            source="cod",
            caller_identity="symbol:recoil:function:0x4168d0",
            caller_start="0x4168d0",
            caller_end_exclusive="0x4169d0",
            indexes=indexes,
            reviewed_register_storage_bridges={
                "__imp__fread": "iat:fread",
            },
        )
        self.assertTrue(compare_call_contracts(retail, candidate)["passed"])
        self.assertEqual(
            ["entry-stack+0x8"] * 3,
            [row["argument_lineage"] for row in candidate],
        )

        cases = {
            "kill": candidate_lines[:4]
            + ["  0000d 33 db xor ebx, ebx"]
            + [
                "  0000f 53 push ebx",
                "  00010 ff d7 call edi",
                "  00012 83 c4 10 add esp, 16",
            ],
            "ambiguous": candidate_lines[:1]
            + ["  00003 8b 5d 0c mov ebx, dword [ebp+0xc]"]
            + candidate_lines[2:5],
        }
        for label, lines in cases.items():
            with self.subTest(label=label):
                drifted = extract_invocation_contract(
                    parse_assembly("\n".join(lines), source="cod"),
                    source="cod",
                    caller_identity="symbol:recoil:function:0x4168d0",
                    caller_start="0x4168d0",
                    caller_end_exclusive="0x4169d0",
                    indexes=indexes,
                    reviewed_register_storage_bridges={
                        "__imp__fread": "iat:fread",
                    },
                )
                self.assertFalse(compare_call_contracts(retail, drifted)["passed"])

