    def test_loop_invariant_iat_keeps_identity_relocation_and_form_exact(
        self,
    ) -> None:
        wrong_identity = replace(
            self._loop_invariant_free_indexes(),
            storage_by_name={"__imp__free": "iat:wrong"},
        )
        wrong_identity_contract = self._loop_invariant_free_contract(
            [
                "  0000a 8b 1d 00 00 00 00 mov ebx, DWORD PTR __imp__free",
                "  00018 90 nop",
                "  00019 75 fd jne SHORT $Lloop",
                "  0001b ff d3 call ebx",
            ],
            source="cod",
            indexes=wrong_identity,
        )
        self.assertEqual(
            "iat:wrong",
            wrong_identity_contract[0]["target_identity"],
        )
        correct_identity_contract = self._loop_invariant_free_contract(
            [
                "  0000a 8b 1d 00 00 00 00 mov ebx, DWORD PTR __imp__free",
                "  00018 90 nop",
                "  00019 75 fd jne SHORT $Lloop",
                "  0001b ff d3 call ebx",
            ],
            source="cod",
        )
        self.assertFalse(
            compare_call_contracts(
                correct_identity_contract,
                wrong_identity_contract,
            )["passed"]
        )
        with self.assertRaisesRegex(ValueError, "placeholder identity drift"):
            self._loop_invariant_free_contract(
                [
                    "  0000a 8b 1d b4 c5 4c 00 mov ebx, DWORD PTR __imp__free",
                    "  00018 90 nop",
                    "  00019 75 fd jne SHORT $Lloop",
                    "  0001b ff d3 call ebx",
                ],
                source="cod",
            )

        expected = self._loop_invariant_free_contract(
            [
                "004037ca 8b 1d b4 c5 4c 00 mov ebx, dword [0x4cc5b4]",
                "004037d8 90 nop",
                "004037d9 75 fd jne 0x4037d8",
                "004037db ff d3 call ebx",
            ],
            source="bn",
        )
        tail = self._loop_invariant_free_contract(
            [
                "004037ca 8b 1d b4 c5 4c 00 mov ebx, dword [0x4cc5b4]",
                "004037d8 90 nop",
                "004037d9 75 fd jne 0x4037d8",
                "004037db ff e3 jmp ebx",
            ],
            source="bn",
        )
        comparison = compare_call_contracts(expected, tail)
        self.assertFalse(comparison["passed"])
        self.assertEqual("call", comparison["first_divergence"]["expected"]["form"])
        self.assertEqual("tail", comparison["first_divergence"]["candidate"]["form"])

