    def test_comparison_scoped_direct_iat_rejects_import_authority_drift(
        self,
    ) -> None:
        call = ["004169eb ff 15 b8 c5 4c 00 call dword [fopen]"]
        base = self._direct_iat_targets()
        cases = {
            "duplicate-slot": [
                base[0],
                SimpleNamespace(**{**vars(base[0]), "dll": "OTHER.dll"}),
            ],
            "ordinal": [
                SimpleNamespace(
                    **{
                        **vars(base[0]),
                        "import_name": "#7",
                        "import_ordinal": 7,
                    }
                )
            ],
            "ambiguous-name-dll": [
                base[0],
                SimpleNamespace(
                    **{
                        **vars(base[0]),
                        "address": "0x4cc000",
                        "dll": "OTHER.dll",
                    }
                ),
            ],
        }
        for label, targets in cases.items():
            with self.subTest(label=label), self.assertRaises(ValueError):
                self._direct_iat_indexes(call, targets=targets)

        with self.assertRaisesRegex(ValueError, "BN name"):
            self._direct_iat_indexes(
                ["004169eb ff 15 b8 c5 4c 00 call dword [Fopen]"]
            )

