    def test_comparison_scoped_direct_iat_lifecycle_extent_fails_closed(
        self,
    ) -> None:
        mutations: dict[str, tuple[ProgressDocument, list[str] | None, str]] = {}

        wrong_role = self._direct_iat_lifecycle_document()
        wrong_role.collection("symbols")["recoil:function:0x40ef60"][
            "authored_order_role"
        ] = "authored-body"
        mutations["wrong-role"] = (wrong_role, None, "lifecycle-body")

        non_authored = self._direct_iat_lifecycle_document()
        non_authored.collection("symbols")["recoil:function:0x40ef60"][
            "pipeline_class"
        ] = "non-authored"
        mutations["non-authored"] = (
            non_authored,
            None,
            "current authored caller",
        )

        unresolved_owner = self._direct_iat_lifecycle_document()
        unresolved_owner.collection("symbols")["recoil:function:0x40ef60"][
            "ownership_state"
        ] = "unresolved"
        mutations["unresolved-owner"] = (
            unresolved_owner,
            None,
            "current authored caller",
        )

        unknown_extent = self._direct_iat_lifecycle_document()
        unknown_extent.collection("symbols")["recoil:function:0x40ef60"][
            "extent_state"
        ] = "unknown"
        mutations["unknown-extent"] = (
            unknown_extent,
            None,
            "exact registered extent",
        )

        provider_block = self._direct_iat_lifecycle_document()
        provider_block.collection("physical_blocks")[
            "recoil:block:0x404ca0"
        ]["contribution_kind"] = "provider"
        mutations["provider-block"] = (
            provider_block,
            None,
            "authored physical contribution",
        )

        missing_boundary = self._direct_iat_lifecycle_document()
        del missing_boundary.collection("symbols")["recoil:function:0x40f040"]
        mutations["missing-boundary"] = (
            missing_boundary,
            None,
            "next registered",
        )

        for label, (document, lines, message) in mutations.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                message,
            ):
                self._direct_iat_lifecycle_indexes(
                    document=document,
                    lines=lines,
                )

        with self.assertRaisesRegex(ValueError, "out-of-body"):
            self._direct_iat_lifecycle_indexes(
                lines=[
                    "0040f020 ff 15 38 e8 4c 00 "
                    "call dword [GetTickCount]",
                    "0040f03f 90 90 nop",
                ]
            )

        with patch(
            "_recoil.commands.call_contract_verify._immutable_retail_interval",
            return_value=b"\x90\x90\x00\x90\x90\x90",
        ), self.assertRaisesRegex(ValueError, "not complete NOP padding"):
            self._direct_iat_lifecycle_indexes()

    def test_comparison_scoped_direct_iat_rejects_non_ff15_or_name_only(
        self,
    ) -> None:
        instructions, indexes = self._direct_iat_indexes(
            [
                "004169eb ff 15 b8 c5 4c 00 call dword [fopen]",
                "004169f1 83 c4 08 add esp, 8",
                "00416a01 ff 25 b8 c5 4c 00 jmp dword [fopen]",
            ]
        )
        with self.assertRaisesRegex(ValueError, "exact unprefixed FF15 CALL"):
            extract_invocation_contract(
                instructions,
                source="bn",
                caller_identity="symbol:recoil:function:0x4169d0",
                caller_start="0x4169d0",
                caller_end_exclusive="0x416a30",
                indexes=indexes,
            )

        document = self._direct_iat_scope_document()
        name_only = parse_assembly(
            "004169eb ff 25 b8 c5 4c 00 jmp dword [fopen]",
            source="bn",
        )
        unchanged = _comparison_scoped_direct_iat_indexes(
            name_only,
            document=document,
            caller_identity="symbol:recoil:function:0x4169d0",
            caller_start="0x4169d0",
            caller_end_exclusive="0x416a30",
            indexes=build_identity_indexes(document),
            retail_import_targets=self._direct_iat_targets(),
        )
        self.assertNotIn("fopen", unchanged.storage_by_name)

