    @staticmethod
    def _terminal_wrapped_ff25_fixture(
        listing: tuple[str, ...] | None = None,
    ) -> tuple[list[Instruction], CandidateCallerDefinition]:
        symbol = "_g_zVideo_pfnClearZBufferRect"
        rows = listing or (
            "?CallClearZBufferRect@@YIXPAUFixture@@@Z PROC NEAR",
            "  00000 ff 25 00 00 00",
            f"  00 jmp DWORD PTR {symbol}",
            "?CallClearZBufferRect@@YIXPAUFixture@@@Z ENDP",
        )
        instructions = call_contract_verify_module.parse_assembly(
            "\n".join(rows),
            source="cod",
        )
        definition = CandidateCallerDefinition(
            symbol="?CallClearZBufferRect@@YIXPAUFixture@@@Z",
            data=b"\xff\x25\0\0\0\0",
            relocations=(
                CoffRelocation(
                    offset=2,
                    symbol_index=17,
                    type=call_contract_verify_module.IMAGE_REL_I386_DIR32,
                    symbol_name=symbol,
                ),
            ),
            relocation_mask=(False, False, True, True, True, True),
            undefined_external_functions=(),
            defined_external_data=(symbol,),
            section_index=15,
            section_start=0,
            section_end=6,
        )
        return instructions, definition

    def _terminal_wrapped_ff25_contract(
        self,
        instructions: Sequence[Instruction],
        definition: CandidateCallerDefinition,
    ) -> tuple[list[dict[str, object]], list[str]]:
        sites: list[str] = []
        contract = extract_invocation_contract(
            instructions,
            source="cod",
            caller_identity="symbol:recoil:function:0x4a6750",
            caller_start="0x4a6750",
            caller_end_exclusive=hex(0x4A6750 + len(definition.data)),
            indexes=IdentityIndexes(
                by_address={},
                by_candidate_name={},
                provider_ids=frozenset(),
                storage_by_address={},
                storage_by_name={},
            ),
            candidate_storage_bridges={
                "_g_zVideo_pfnClearZBufferRect": (
                    "storage:recoil:data:0x4ce874"
                ),
            },
            invocation_call_sites_out=sites,
            candidate_caller_definition=definition,
        )
        return contract, sites

    def test_terminal_wrapped_ff25_closes_only_through_exact_coff_body(
        self,
    ) -> None:
        instructions, definition = self._terminal_wrapped_ff25_fixture()
        self.assertEqual(1, len(instructions))
        self.assertEqual(
            ("ff", "25", "00", "00", "00", "00"),
            instructions[0].bytes,
        )
        self.assertEqual(
            "",
            call_contract_verify_module._source_instruction_address(
                instructions[0]
            ),
        )
        contract, sites = self._terminal_wrapped_ff25_contract(
            instructions,
            definition,
        )
        self.assertEqual(["0x4a6750"], sites)
        self.assertEqual(1, len(contract))
        self.assertEqual("tail", contract[0]["form"])
        self.assertEqual("callback", contract[0]["identity_kind"])
        self.assertEqual(
            "storage:recoil:data:0x4ce874",
            contract[0]["storage_identity"],
        )
        padded = replace(
            definition,
            data=definition.data + b"\x90" * 10,
            relocation_mask=definition.relocation_mask + (False,) * 10,
            section_end=16,
        )
        padded_contract, padded_sites = (
            self._terminal_wrapped_ff25_contract(instructions, padded)
        )
        self.assertEqual(contract, padded_contract)
        self.assertEqual(["0x4a6750"], padded_sites)
        with tempfile.TemporaryDirectory() as temporary:
            cod_path = Path(temporary) / "terminal-wrap.cod"
            symbol = definition.symbol
            cod_path.write_text(
                "\n".join(
                    (
                        f"{symbol} PROC NEAR",
                        "  00000 ff 25 00 00 00",
                        "  00 jmp DWORD PTR "
                        "_g_zVideo_pfnClearZBufferRect",
                        f"{symbol} ENDP",
                    )
                ),
                encoding="utf-8",
            )
            indexed = (
                call_contract_verify_module
                ._extract_cod_proc_with_local_switches(cod_path, symbol)
            )
        self.assertEqual(1, len(indexed.instructions))
        self.assertIn(
            call_contract_verify_module._COD_TERMINAL_WRAP_MARKER,
            indexed.instructions[0].source_line,
        )

    def test_terminal_wrapped_ff25_listing_and_coff_drifts_fail_closed(
        self,
    ) -> None:
        instructions, definition = self._terminal_wrapped_ff25_fixture()
        relocation = definition.relocations[0]
        malformed_definitions = {
            "wrong-byte": replace(
                definition,
                data=b"\xff\x15\0\0\0\0",
            ),
            "wrong-relocation": replace(
                definition,
                relocations=(replace(relocation, type=0),),
            ),
            "extra-relocation": replace(
                definition,
                relocations=(
                    relocation,
                    replace(relocation, offset=0),
                ),
            ),
            "wrong-mask": replace(
                definition,
                relocation_mask=(False,) * 6,
            ),
            "wrong-section": replace(definition, section_index=0),
            "partial-section": replace(definition, section_end=5),
            "extra-body": replace(
                definition,
                data=definition.data + b"\xcc",
                relocation_mask=definition.relocation_mask + (False,),
                section_end=7,
            ),
            "missing-symbol": replace(
                definition,
                defined_external_data=(),
            ),
            "ambiguous-symbol": replace(
                definition,
                undefined_external_data=definition.defined_external_data,
            ),
        }
        for label, malformed in malformed_definitions.items():
            with self.subTest(label=label), self.assertRaises(ValueError):
                self._terminal_wrapped_ff25_contract(
                    instructions,
                    malformed,
                )

        symbol = "_g_zVideo_pfnClearZBufferRect"
        malformed_listings = {
            "missing-endp": (
                "  00000 ff 25 00 00 00",
                f"  00 jmp DWORD PTR {symbol}",
            ),
            "extra-row": (
                "  00000 ff 25 00 00 00",
                f"  00 jmp DWORD PTR {symbol}",
                "  00006 90 nop",
                "?CallClearZBufferRect@@YIXPAUFixture@@@Z ENDP",
            ),
            "wrong-mnemonic": (
                "  00000 ff 25 00 00 00",
                f"  00 call DWORD PTR {symbol}",
                "?CallClearZBufferRect@@YIXPAUFixture@@@Z ENDP",
            ),
            "wrong-byte": (
                "  00000 ff 15 00 00 00",
                f"  00 jmp DWORD PTR {symbol}",
                "?CallClearZBufferRect@@YIXPAUFixture@@@Z ENDP",
            ),
            "nonterminal": (
                "  00000 ff 25 00 00 00",
                f"  00 jmp DWORD PTR {symbol}",
                "  00006 90 nop",
            ),
        }
        for label, listing in malformed_listings.items():
            malformed_instructions, _ = self._terminal_wrapped_ff25_fixture(
                listing
            )
            with self.subTest(label=label):
                if not malformed_instructions:
                    continue
                with self.assertRaises(ValueError):
                    self._terminal_wrapped_ff25_contract(
                        malformed_instructions,
                        definition,
                    )

        ambiguous = replace(
            instructions[0],
            source_line=(
                instructions[0].source_line
                + call_contract_verify_module._COD_TERMINAL_WRAP_MARKER
                + "00000 ff 25 00 00 00"
            ),
        )
        with self.assertRaises(ValueError):
            self._terminal_wrapped_ff25_contract(
                [ambiguous],
                definition,
            )

