    def _zeffect_save_running_anim_record_candidate_fixture(
        self,
        *,
        load_symbol: str = "__imp__fwrite",
        cleanup_bytes: int = 16,
        clobber_offset: int | None = None,
        bypass_load: bool = False,
        unresolved_branch_offset: int | None = None,
    ) -> CandidateAssembly:
        direct_calls = {0x170, 0x2C7, 0x39B}
        cached_calls = {0x1DC, 0x206}
        cleanup_offsets = {
            0x176: cleanup_bytes,
            0x1DE: cleanup_bytes,
            0x208: cleanup_bytes,
            0x2CD: cleanup_bytes,
            0x3A1: cleanup_bytes,
        }
        lines = [
            "  00000 81 ec c8 00 00",
            "  00 sub esp, 200",
        ]
        offset = 6
        while offset < 0x3E4:
            if bypass_load and offset == 0x1C4:
                lines.append("  001c4 eb 16 jmp 0x1dc")
                offset += 2
            elif offset == 0x1C6:
                lines.extend(
                    [
                        "  001c6 8b 3d 00 00 00",
                        f"  00 mov edi, DWORD PTR {load_symbol}",
                    ]
                )
                offset += 6
            elif offset in direct_calls:
                lines.extend(
                    [
                        f"  {offset:05x} ff 15 00 00 00",
                        "  00 call DWORD PTR __imp__fwrite",
                    ]
                )
                offset += 6
            elif offset in cached_calls:
                lines.append(f"  {offset:05x} ff d7 call edi")
                offset += 2
            elif offset in cleanup_offsets:
                value = cleanup_offsets[offset]
                lines.append(
                    f"  {offset:05x} 83 c4 {value:02x} add esp, {value}"
                )
                offset += 3
            elif offset == clobber_offset:
                lines.append(f"  {offset:05x} 8b f8 mov edi, eax")
                offset += 2
            elif offset == unresolved_branch_offset:
                lines.append(f"  {offset:05x} 75 03 jne 0x1dc")
                offset += 2
            elif offset == 0x3E1:
                lines.append("  003e1 c2 08 00 ret 8")
                offset += 3
            else:
                lines.append(f"  {offset:05x} 90 nop")
                offset += 1
        instructions = parse_assembly("\n".join(lines), source="cod")
        code = bytes(
            int(value, 16)
            for instruction in instructions
            for value in instruction.bytes
        )
        self.assertEqual(0x3E4, len(code))
        data = code + b"\x90" * 12
        relocation_offsets = (0x172, 0x1C8, 0x2C9, 0x39D)
        relocation_mask = tuple(
            any(start <= index < start + 4 for start in relocation_offsets)
            for index in range(len(data))
        )
        target = SimpleNamespace(
            name="zeffect_anim_save_4603d0_4622f0_authored_order",
            target_binary="recoil",
            manifest_path=(
                REPO_ROOT
                / "tools"
                / "vc5_verify_targets"
                / "zeffect_anim_save_4603d0_4622f0_authored_order.json"
            ),
            source_from="src/GameZRecoil/zEffect/zeff_anim_save.c",
        )
        return CandidateAssembly(
            instructions=tuple(instructions),
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
            target=target,
            caller_definition=CandidateCallerDefinition(
                symbol=(
                    "?SaveRunningAnimRecord@zEffect_Anim@@"
                    "YIHPAUzZbdSectionCallbackCtx@@PAUzEffectAnimEntry@@HH@Z"
                ),
                data=data,
                relocations=tuple(
                    CoffRelocation(
                        offset=relocation_offset,
                        symbol_index=index,
                        type=0x06,
                        symbol_name="__imp__fwrite",
                    )
                    for index, relocation_offset in enumerate(
                        relocation_offsets,
                        start=1,
                    )
                ),
                relocation_mask=relocation_mask,
                undefined_external_functions=("__imp__fwrite",),
                section_index=15,
                section_start=0,
                section_end=len(data),
            ),
        )

