    def test_zeffect_save_running_anim_record_fwrite_rejects_coff_drift(
        self,
    ) -> None:
        cases: dict[str, CandidateAssembly] = {}
        for label in ("missing", "type", "addend", "mask"):
            candidate = self._zeffect_save_running_anim_record_candidate_fixture()
            definition = candidate.caller_definition
            self.assertIsNotNone(definition)
            assert definition is not None
            if label == "missing":
                changed = replace(
                    definition,
                    relocations=definition.relocations[:-1],
                )
            elif label == "type":
                relocations = list(definition.relocations)
                relocations[1] = replace(relocations[1], type=0x14)
                changed = replace(definition, relocations=tuple(relocations))
            elif label == "addend":
                data = bytearray(definition.data)
                data[0x1C8] = 1
                changed = replace(definition, data=bytes(data))
            else:
                relocation_mask = list(definition.relocation_mask)
                relocation_mask[0x1C8] = False
                changed = replace(
                    definition,
                    relocation_mask=tuple(relocation_mask),
                )
            cases[label] = replace(candidate, caller_definition=changed)

        for label, candidate in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "four-site.*DIR32",
            ):
                self._prove_zeffect_save_running_anim_record_candidate(candidate)

