    def test_schema75_gettickcount_retail_e8_truth_is_candidate_independent(
        self,
    ) -> None:
        fixture = self._gettickcount_named_thunk_fixture()
        thunk, names = self._prove_gettickcount_retail(fixture)
        population = (
            call_contract_verify_module._gettickcount_retail_e8_call_population(
                fixture["retail"],
                thunk=thunk,
                caller_identity=fixture["caller_identity"],
                caller_start="0x4159e0",
                caller_end_exclusive="0x415a80",
            )
        )
        self.assertEqual((0x4159EE, 0x415A16, 0x415A42), population)

        malformed_candidate = replace(
            fixture["candidate"],
            instructions=fixture["candidate"].instructions[:-1],
        )
        self.assertEqual((0x4159EE, 0x415A16, 0x415A42), population)
        with self.assertRaisesRegex(
            ValueError,
            "immutable-retail-derived population",
        ):
            _gettickcount_named_import_thunk_candidate_bridges(
                population,
                malformed_candidate,
                thunk=thunk,
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x4159e0",
                caller_end_exclusive="0x415a80",
                indexes=fixture["indexes"],
                bridge_names=names,
            )

        retail_with_candidate_call = (
            *fixture["retail"][:-1],
            parse_assembly("00415a42 ff d7 call edi", source="bn")[0],
        )
        with self.assertRaisesRegex(ValueError, "no candidate-shaped FF D7"):
            call_contract_verify_module._gettickcount_retail_e8_call_population(
                retail_with_candidate_call,
                thunk=thunk,
                caller_identity=fixture["caller_identity"],
                caller_start="0x4159e0",
                caller_end_exclusive="0x415a80",
            )

        with self.assertRaisesRegex(ValueError, "immutable retail E8"):
            _gettickcount_named_import_thunk_candidate_bridges(
                population[:-1],
                fixture["candidate"],
                thunk=thunk,
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x4159e0",
                caller_end_exclusive="0x415a80",
                indexes=fixture["indexes"],
                bridge_names=names,
            )

    def test_gettickcount_named_thunk_preserves_three_vs_two_mismatch(
        self,
    ) -> None:
        fixture = self._gettickcount_named_thunk_fixture()
        thunk, names = self._prove_gettickcount_retail(fixture)
        self.assertIsNotNone(thunk)
        self.assertEqual(
            "provider:recoil:function:0x4a59d0",
            thunk.provider_identity,
        )
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=fixture["candidate"].instructions[:-1],
            caller_definition=replace(
                fixture["definition"],
                data=(
                    fixture["definition"].data[:0x5A]
                    + b"\0\0"
                    + fixture["definition"].data[0x5C:]
                ),
            ),
        )
        indexes, _packages = (
            call_contract_verify_module
            ._integrate_preproven_named_import_thunk_packages(
                fixture["indexes"],
                (thunk,),
            )
        )
        fixture["indexes"] = indexes
        retail_indexes = (
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                fixture["retail"],
                indexes=indexes,
                thunks=(thunk,),
            )
        )
        expected = extract_invocation_contract(
            fixture["retail"],
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x4159e0",
            caller_end_exclusive="0x415a80",
            indexes=retail_indexes,
            bridge_names=names,
        )
        direct_bridges, register_bridges = self._prove_gettickcount_candidate(
            fixture, thunk, names
        )
        self.assertEqual({}, direct_bridges)
        proof_indexes = (
            call_contract_verify_module
            ._candidate_exact_iat_register_storage_indexes(
                indexes,
                register_bridges,
            )
        )
        proofs = (
            call_contract_verify_module
            ._candidate_exact_iat_register_load_proofs(
                fixture["candidate"],
                indexes=proof_indexes,
                retail_import_targets=(
                    SimpleNamespace(
                        address="0x4cc140",
                        dll="KERNEL32.dll",
                        import_name="GetTickCount",
                        import_ordinal=None,
                    ),
                ),
            )
        )
        candidate = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x4159e0",
            caller_end_exclusive="0x415a80",
            indexes=proof_indexes,
            bridge_names=names,
            reviewed_register_storage_bridges=register_bridges,
            reviewed_iat_register_definition_offsets=frozenset(proofs),
            candidate_exact_iat_register_load_proofs=proofs,
        )
        comparison = compare_call_contracts(
            expected,
            candidate,
            reviewed_provider_iat_equivalences=(
                call_contract_verify_module
                ._gettickcount_candidate_retail_iat_equivalences(
                    thunk,
                    direct_bridges,
                    register_bridges,
                )
            ),
        )
        self.assertFalse(comparison["passed"])
        self.assertEqual("missing", comparison["first_divergence"]["kind"])
        self.assertEqual(2, comparison["first_divergence"]["ordinal"])

    def test_schema40_preproven_named_package_composes_once_end_to_end(
        self,
    ) -> None:
        fixture = self._gettickcount_named_thunk_fixture()
        thunk, _names = self._prove_gettickcount_retail(fixture)
        self.assertIsNotNone(thunk)
        indexes, packages = (
            call_contract_verify_module
            ._integrate_preproven_named_import_thunk_packages(
                fixture["indexes"],
                (thunk,),
            )
        )
        generic, names = _provider_named_import_thunk_retail_bridges(
            document=fixture["document"],
            indexes=indexes,
            bridge_by_address=fixture["by_address"],
            bridge_by_name=fixture["by_name"],
            bridge=fixture["bridge"],
            additional_named_packages=packages,
            preproven_named_thunks=(thunk,),
        )
        self.assertEqual((), generic)
        self.assertEqual({}, names)
        fixture["indexes"] = indexes
        direct_bridges, register_bridges = self._prove_gettickcount_candidate(
            fixture,
            thunk,
            names,
        )
        self.assertEqual({}, direct_bridges)
        self.assertEqual(
            {"__imp__GetTickCount@0": "iat:GetTickCount"},
            register_bridges,
        )
        call_address = 0x4159EE
        displacement = int(thunk.thunk_address, 16) - (call_address + 5)
        rows = parse_assembly(
            f"{call_address:08x} "
            + " ".join(
                f"{value:02x}"
                for value in b"\xe8" + struct.pack("<i", displacement)
            )
            + f" call {thunk.retail_name}",
            source="bn",
        )
        direct_indexes = (
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                rows,
                indexes=indexes,
                thunks=(thunk, *generic),
            )
        )
        contract = extract_invocation_contract(
            rows,
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x4159e0",
            caller_end_exclusive="0x415a80",
            indexes=direct_indexes,
            bridge_names={
                thunk.retail_name: [fixture["by_name"][thunk.retail_name]]
            },
        )
        self.assertEqual("iat", contract[0]["identity_kind"])
        self.assertEqual("iat:GetTickCount", contract[0]["target_identity"])

