    def test_schema52_gettickcount_candidate_index_fails_closed(
        self,
    ) -> None:
        fixture = self._gettickcount_named_thunk_fixture()
        thunk, names = self._prove_gettickcount_retail(fixture)
        self.assertIsNotNone(thunk)
        indexes, _packages = (
            call_contract_verify_module
            ._integrate_preproven_named_import_thunk_packages(
                fixture["indexes"],
                (thunk,),
            )
        )
        fixture["indexes"] = indexes
        _direct_bridges, register_bridges = (
            self._prove_gettickcount_candidate(fixture, thunk, names)
        )
        retail_import = SimpleNamespace(
            address="0x4cc140",
            dll="KERNEL32.dll",
            import_name="GetTickCount",
            import_ordinal=None,
        )

        with self.subTest("missing"), self.assertRaisesRegex(
            call_contract_verify_module.CandidateCallContractEvidenceError,
            "already-published immutable retail identity",
        ):
            call_contract_verify_module._candidate_exact_iat_register_load_proofs(
                fixture["candidate"],
                indexes=call_contract_verify_module._candidate_exact_iat_register_storage_indexes(
                    indexes,
                    {},
                ),
                retail_import_targets=(retail_import,),
            )

        conflicting_names = dict(indexes.storage_by_name)
        conflicting_names["GetTickCount"] = "iat:Sleep"
        with self.subTest("conflicting"), self.assertRaisesRegex(
            call_contract_verify_module.CandidateCallContractEvidenceError,
            "conflicts with already-published immutable identity",
        ):
            call_contract_verify_module._candidate_exact_iat_register_storage_indexes(
                replace(indexes, storage_by_name=conflicting_names),
                register_bridges,
            )

        proof_indexes = (
            call_contract_verify_module
            ._candidate_exact_iat_register_storage_indexes(
                indexes,
                register_bridges,
            )
        )
        with self.subTest("ambiguous"), self.assertRaisesRegex(
            call_contract_verify_module.CandidateCallContractEvidenceError,
            "one unique immutable import route",
        ):
            call_contract_verify_module._candidate_exact_iat_register_load_proofs(
                fixture["candidate"],
                indexes=proof_indexes,
                retail_import_targets=(
                    retail_import,
                    SimpleNamespace(
                        address="0x4cc144",
                        dll="KERNEL32.dll",
                        import_name="GetTickCount",
                        import_ordinal=None,
                    ),
                ),
            )

