    def test_schema55_gettickcount_register_population_fails_closed(
        self,
    ) -> None:
        cases = (
            (
                "missing",
                lambda candidate: replace(
                    candidate,
                    instructions=candidate.instructions[:-1],
                ),
            ),
            (
                "extra",
                lambda candidate: replace(
                    candidate,
                    instructions=(
                        *candidate.instructions,
                        parse_assembly(
                            "  00070 ff d7 call edi",
                            source="cod",
                        )[0],
                    ),
                ),
            ),
            (
                "wrong-bytes",
                lambda candidate: replace(
                    candidate,
                    instructions=(
                        *candidate.instructions[:-1],
                        parse_assembly(
                            "  0005a ff d6 call edi",
                            source="cod",
                        )[0],
                    ),
                ),
            ),
            (
                "before-load",
                lambda candidate: replace(
                    candidate,
                    instructions=(
                        parse_assembly(
                            "  00008 ff d7 call edi",
                            source="cod",
                        )[0],
                        *candidate.instructions[1:],
                    ),
                ),
            ),
        )
        for label, mutate in cases:
            fixture = self._gettickcount_named_thunk_fixture()
            thunk, names = self._prove_gettickcount_retail(fixture)
            fixture["candidate"] = mutate(fixture["candidate"])
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "immutable-retail-derived population",
            ):
                self._prove_gettickcount_candidate(fixture, thunk, names)

