    def test_ordinal_bridge_scopes_relocations_to_exact_caller_interval(
        self,
    ) -> None:
        fixture = self._cstring_ordinal_import_thunk_fixture()
        thunks, retail_names = self._prove_cstring_ordinal_retail(fixture)
        definition = fixture["candidate"].caller_definition
        self.assertIsNotNone(definition)
        assert definition is not None
        selected_start = 0x20
        direct_field = selected_start + 1
        neighbor_field = 0x31
        scoped_definition = replace(
            definition,
            relocations=(
                replace(definition.relocations[0], offset=direct_field),
                replace(definition.relocations[0], offset=neighbor_field),
            ),
            section_start=selected_start,
            section_end=selected_start + len(definition.data),
        )
        fixture["candidate"] = replace(
            fixture["candidate"],
            caller_definition=scoped_definition,
        )
        self.assertEqual(
            {fixture["callable_symbol"]: fixture["provider_identity"]},
            self._prove_cstring_ordinal_candidate(
                fixture,
                thunks,
                retail_names,
            ),
        )

        fixture["candidate"] = replace(
            fixture["candidate"],
            caller_definition=replace(
                scoped_definition,
                relocations=scoped_definition.relocations + (
                    replace(
                        definition.relocations[0],
                        offset=scoped_definition.section_end - 2,
                    ),
                ),
            ),
        )
        with self.assertRaisesRegex(ValueError, "definition boundary"):
            self._prove_cstring_ordinal_candidate(
                fixture,
                thunks,
                retail_names,
            )

    def test_generic_named_import_thunks_join_unique_exact_iat_chains(
        self,
    ) -> None:
        cases = (
            (
                "0x4c637c",
                "0x4cc700",
                "COMDLG32.dll",
                "GetOpenFileNameA",
                "__imp__GetOpenFileNameA@4",
                0x14,
            ),
            (
                "0x4c6390",
                "0x4cc020",
                "AVIFIL32.dll",
                "AVIFileInit",
                "__imp__AVIFileInit@0",
                6,
            ),
            (
                "0x4c6396",
                "0x4cc038",
                "AVIFIL32.dll",
                "AVIFileExit",
                "__imp__AVIFileExit@0",
                0x12,
            ),
            (
                "0x4c63a8",
                "0x4cc01c",
                "AVIFIL32.dll",
                "AVIStreamRelease",
                "__imp__AVIStreamRelease@4",
                6,
            ),
        )
        for index, (
            thunk_address,
            iat_address,
            import_dll,
            import_name,
            object_symbol,
            size,
        ) in enumerate(cases):
            with self.subTest(import_name=import_name):
                document = self._named_iat_provider_document(
                    address=iat_address,
                    import_dll=import_dll,
                    import_name=import_name,
                    object_symbol=object_symbol,
                    owner_id=(
                        "recoil:owner:provider.synthetic."
                        f"{import_name.lower()}_iat"
                    ),
                    evidence_id=f"recoil:evidence:r3296:{index + 1:06d}",
                    evidence_kind="provider-target-registration",
                    descriptor_index=index + 1,
                    thunk_index=index,
                )
                thunk_symbol_id = f"recoil:function:{thunk_address}"
                thunk_owner_id = (
                    "recoil:owner:provider.synthetic."
                    f"{import_name.lower()}_thunk"
                )
                thunk_block_id = f"recoil:block:{thunk_address}"
                end_exclusive = hex(int(thunk_address, 16) + size)
                retail_name = (
                    f"{import_dll.removesuffix('.dll').upper()}_"
                    f"{import_name}_ImportThunk"
                )
                document.data["symbols"][thunk_symbol_id] = {
                    "address": thunk_address,
                    "authored_order_role": "non-authored",
                    "binary": "recoil",
                    "end_exclusive": end_exclusive,
                    "extent_state": "known",
                    "kind": "function",
                    "navigation_name": retail_name,
                    "output_section_id": "recoil:section:.text",
                    "ownership_state": "primary-owned",
                    "physical_block_id": thunk_block_id,
                    "pipeline_class": "non-authored",
                    "size": size,
                }
                document.data["owners"][thunk_owner_id] = {
                    "binary": "recoil",
                    "blocker": "none",
                    "kind": "provider-boundary",
                    "lifecycle_state": "accepted",
                    "provider_state": "accepted",
                    "relationships": [
                        {
                            "kind": "anchor-address",
                            "address": thunk_address,
                        },
                        {
                            "kind": "primary-function",
                            "address": thunk_address,
                            "symbol_id": thunk_symbol_id,
                        },
                    ],
                    "source_paths": [],
                }
                document.data["physical_blocks"][thunk_block_id] = {
                    "agent_source_path": "provider:named-import-thunks",
                    "binary": "recoil",
                    "contribution_ids": [thunk_symbol_id],
                    "contribution_kind": "provider",
                    "end_exclusive": end_exclusive,
                    "mapping": {"status": "provider-boundary"},
                    "row_kind": "physical-source-block",
                    "source_path": "provider:named-import-thunks",
                    "start": thunk_address,
                }
                grouped_address = "0x443b90"
                grouped_symbol_id = f"recoil:function:{grouped_address}"
                grouped_owner_id = "recoil:owner:provider.synthetic.gdi_group"
                grouped_block_id = "recoil:block:0x443b70"
                document.data["symbols"][grouped_symbol_id] = {
                    "address": grouped_address,
                    "authored_order_role": "non-authored",
                    "binary": "recoil",
                    "end_exclusive": "0x443be0",
                    "extent_state": "known",
                    "kind": "function",
                    "navigation_name": "CGdiObject::Destructor",
                    "output_section_id": "recoil:section:.text",
                    "ownership_state": "primary-owned",
                    "physical_block_id": grouped_block_id,
                    "pipeline_class": "non-authored",
                    "size": 0x50,
                }
                grouped_relationships = [
                    {"kind": "anchor-address", "address": "0x443b70"},
                    *(
                        {
                            "kind": "primary-function",
                            "address": address,
                            "symbol_id": f"recoil:function:{address}",
                        }
                        for address in (
                            "0x443b70",
                            "0x443b90",
                            "0x443be0",
                            "0x443c00",
                        )
                    ),
                ]
                document.data["owners"][grouped_owner_id] = {
                    "binary": "recoil",
                    "blocker": "none",
                    "kind": "provider-boundary",
                    "lifecycle_state": "accepted",
                    "provider_state": "accepted",
                    "relationships": grouped_relationships,
                    "source_paths": [],
                }
                friendly = Symbol(
                    address=thunk_address,
                    name=retail_name,
                    raw_name=retail_name,
                    full_name="",
                    kind="function",
                )
                import_friendly = Symbol(
                    address=thunk_address,
                    name=import_name,
                    raw_name=import_name,
                    full_name=import_name,
                    kind="import",
                )
                bridge_by_address = {thunk_address: import_friendly}
                bridge_by_name = {
                    retail_name: friendly,
                    import_name: import_friendly,
                }
                encoded = (
                    b"\xff\x25"
                    + struct.pack("<I", int(iat_address, 16))
                    + b"\x90" * (size - 6)
                )
                grouped_body = bytes.fromhex("6a ff 68 48 ad 4c 00") + (
                    b"\x90" * (0x50 - 7)
                )
                bodies = {
                    thunk_address: encoded,
                    grouped_address: grouped_body,
                }

                def hexdump(address, requested_size):
                    body = bodies[address][:requested_size]
                    return (
                        address.removeprefix("0x")
                        + " "
                        + " ".join(f"{value:02x}" for value in body)
                    )

                bridge = SimpleNamespace(
                    hexdump=hexdump,
                )
                indexes = build_identity_indexes(
                    document,
                    bridge_by_address=bridge_by_address,
                )
                thunks, names = _provider_named_import_thunk_retail_bridges(
                    document=document,
                    indexes=indexes,
                    bridge_by_address=bridge_by_address,
                    bridge_by_name=bridge_by_name,
                    bridge=bridge,
                )
                self.assertEqual(1, len(thunks))
                self.assertEqual(iat_address, thunks[0].iat_address)
                self.assertEqual(import_name, thunks[0].import_name)
                self.assertEqual(retail_name, thunks[0].retail_name)
                self.assertEqual([friendly], names[retail_name])
                caller_address = 0x401000 + index * 0x20
                direct_displacement = int(thunk_address, 16) - (
                    caller_address + 5
                )
                direct_rows = parse_assembly(
                    f"{caller_address:08x} "
                    + " ".join(
                        f"{value:02x}"
                        for value in b"\xe8"
                        + struct.pack("<i", direct_displacement)
                    )
                    + f" call {thunk_address}",
                    source="bn",
                )
                direct_indexes = call_contract_verify_module._retail_direct_import_thunk_indexes(
                    direct_rows,
                    indexes=indexes,
                    thunks=thunks,
                )
                direct_contract = extract_invocation_contract(
                    direct_rows,
                    source="bn",
                    caller_identity=(
                        f"symbol:recoil:function:{hex(caller_address)}"
                    ),
                    caller_start=hex(caller_address),
                    caller_end_exclusive=hex(caller_address + 5),
                    indexes=direct_indexes,
                )
                self.assertEqual(
                    f"iat:{import_name}",
                    direct_contract[0]["target_identity"],
                )
                bodies[grouped_address] = (
                    b"\xff\x25"
                    + struct.pack("<I", int(iat_address, 16))
                    + b"\x90" * (0x50 - 6)
                )
                with self.assertRaisesRegex(
                    ValueError,
                    "lacks exactly one accepted provider-boundary primary owner",
                ):
                    _provider_named_import_thunk_retail_bridges(
                        document=document,
                        indexes=indexes,
                        bridge_by_address=bridge_by_address,
                        bridge_by_name=bridge_by_name,
                        bridge=bridge,
                    )

