    def test_schema35_named_router_rejects_missing_or_ambiguous_package(
        self,
    ) -> None:
        fixture = self._cstring_ordinal_import_thunk_fixture()
        missing_data = deepcopy(fixture["document"].data)
        del missing_data["storage_contributions"][
            f"recoil:storage:va:{fixture['iat_address']}"
        ]
        missing_document = ProgressDocument(missing_data)
        missing_indexes = build_identity_indexes(
            missing_document,
            bridge_by_address=fixture["bridge_by_address"],
        )
        message = (
            "IAT operand does not join one unique complete current "
            "named or ordinal package"
        )
        with self.assertRaisesRegex(ValueError, message):
            _provider_named_import_thunk_retail_bridges(
                document=missing_document,
                indexes=missing_indexes,
                bridge_by_address=fixture["bridge_by_address"],
                bridge_by_name=fixture["bridge_by_name"],
                bridge=fixture["bridge"],
            )

        competing = call_contract_verify_module.CurrentIatStoragePackage(
            address=fixture["iat_address"],
            import_dll="MFC42.DLL",
            import_name="CompetingNamedImport",
            import_ordinal=None,
            object_symbol="__imp__CompetingNamedImport@0",
            identity="iat:CompetingNamedImport",
        )
        with self.assertRaisesRegex(ValueError, message):
            _provider_named_import_thunk_retail_bridges(
                document=fixture["document"],
                indexes=fixture["indexes"],
                bridge_by_address=fixture["bridge_by_address"],
                bridge_by_name=fixture["bridge_by_name"],
                bridge=fixture["bridge"],
                additional_named_packages=(competing,),
            )

