    def test_schema37_overlapping_eh_short_jump_is_not_tail_call(self) -> None:
        rows = parse_assembly(
            "\n".join(
                (
                    "0043f67c eb 10 jmp 0x43f68e",
                    "0043f67e 90 nop",
                    "0043f68e c3 ret",
                )
            ),
            source="bn",
        )
        self.assertEqual(
            [],
            extract_invocation_contract(
                rows,
                source="bn",
                caller_identity="symbol:recoil:function:0x43f610",
                caller_start="0x43f610",
                caller_end_exclusive="0x43f682",
                indexes=self.indexes,
            ),
        )

        target = "symbol:recoil:function:0x401010"
        real_tail = extract_invocation_contract(
            parse_assembly(
                "00401000 eb 0e jmp 0x401010",
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:recoil:function:0x401000",
            caller_start="0x401000",
            caller_end_exclusive="0x401002",
            indexes=replace(
                self.indexes,
                by_address={"0x401010": target},
            ),
        )
        self.assertEqual(1, len(real_tail))
        self.assertEqual("tail", real_tail[0]["form"])
        self.assertEqual(target, real_tail[0]["target_identity"])

