    def test_live_ordinal_bridge_wiring_forwards_pre_ftol_direct_bridges(
        self,
    ) -> None:
        fixture = self._cstring_ordinal_import_thunk_fixture()
        thunks, names = self._prove_cstring_ordinal_retail(fixture)
        reviewed_direct_bridges = {
            "?ReviewedAuthoredCall@@YAXXZ": (
                "symbol:recoil:function:0x407060"
            ),
        }
        sentinel = {fixture["callable_symbol"]: fixture["provider_identity"]}
        register_storage_bridges = {"__imp__atoi": "iat:atoi"}
        exact_iat_proofs = {
            "0x93": (
                call_contract_verify_module.CandidateExactIatRegisterLoadProof(
                definition_offset="0x93",
                destination="edi",
                object_symbol="__imp__atoi",
                identity="iat:atoi",
                transfer_offsets=("0x9c",),
                )
            )
        }

        self.assertIn(
            "_provider_ordinal_import_thunk_candidate_bridges_from_reviewed_directs",
            call_contract_verify_module.live_call_contract_result.__code__.co_names,
        )
        with patch.object(
            call_contract_verify_module,
            "_provider_ordinal_import_thunk_candidate_bridges",
            return_value=sentinel,
        ) as ordinal_bridge_spy:
            result = call_contract_verify_module._provider_ordinal_import_thunk_candidate_bridges_from_reviewed_directs(
                fixture["expected"],
                fixture["candidate"],
                thunks=thunks,
                caller_identity="symbol:recoil:function:0x407010",
                caller_start="0x407010",
                caller_end_exclusive="0x407050",
                indexes=fixture["indexes"],
                bridge_names=names,
                reviewed_candidate_direct_bridges=reviewed_direct_bridges,
                reviewed_register_storage_bridges=register_storage_bridges,
                candidate_exact_iat_register_load_proofs=exact_iat_proofs,
            )

        self.assertIs(result, sentinel)
        self.assertEqual(
            ordinal_bridge_spy.call_args.kwargs[
                "reviewed_candidate_direct_bridges"
            ],
            reviewed_direct_bridges,
        )
        self.assertIsNot(
            ordinal_bridge_spy.call_args.kwargs[
                "reviewed_candidate_direct_bridges"
            ],
            reviewed_direct_bridges,
        )
        self.assertIs(
            ordinal_bridge_spy.call_args.kwargs[
                "reviewed_register_storage_bridges"
            ],
            register_storage_bridges,
        )
        self.assertIs(
            ordinal_bridge_spy.call_args.kwargs[
                "candidate_exact_iat_register_load_proofs"
            ],
            exact_iat_proofs,
        )

    def test_generic_ordinal_iat_identity_is_dll_collision_safe(self) -> None:
        first = self._named_iat_provider_document(
            address="0x4cc3c0",
            import_dll="MFC42.DLL",
            import_name="#540",
            import_ordinal=540,
            object_symbol="__imp_??0CString@@QAE@XZ",
            owner_id="recoil:owner:provider.mfc42.ordinal540",
            evidence_id="recoil:evidence:r1326:000001",
            evidence_kind="provider-target-registration",
            descriptor_index=2,
            thunk_index=147,
        )
        second = self._named_iat_provider_document(
            address="0x4cc3c4",
            import_dll="OTHER.DLL",
            import_name="#540",
            import_ordinal=540,
            object_symbol="__imp_?Ordinal540@Other@@YAXXZ",
            owner_id="recoil:owner:provider.other.ordinal540",
            evidence_id="recoil:evidence:r1326:000002",
            evidence_kind="provider-target-registration",
            descriptor_index=7,
            thunk_index=3,
        )
        data = deepcopy(first.data)
        for collection in (
            "evidence",
            "owners",
            "symbols",
            "storage_contributions",
        ):
            data[collection].update(deepcopy(second.data[collection]))
        indexes = build_identity_indexes(ProgressDocument(data))
        first_identity = "iat:ordinal:9:MFC42.DLL:540"
        second_identity = "iat:ordinal:9:OTHER.DLL:540"
        self.assertEqual(
            first_identity,
            indexes.storage_by_address["0x4cc3c0"],
        )
        self.assertEqual(
            second_identity,
            indexes.storage_by_address["0x4cc3c4"],
        )
        self.assertEqual("", indexes.storage_by_name["#540"])
        self.assertEqual(
            first_identity,
            indexes.storage_by_name["MFC42.DLL!#540"],
        )
        self.assertEqual(
            second_identity,
            indexes.storage_by_name["OTHER.DLL!#540"],
        )

    def test_0x407010_cstring_ordinal_import_thunk_exact(self) -> None:
        fixture = self._cstring_ordinal_import_thunk_fixture()
        thunks, retail_names = self._prove_cstring_ordinal_retail(fixture)
        self.assertEqual(1, len(thunks))
        self.assertEqual(fixture["provider_identity"], thunks[0].provider_identity)
        self.assertEqual(fixture["callable_symbol"], thunks[0].callable_symbol)
        self.assertEqual("MFC42.DLL", thunks[0].import_dll)
        self.assertEqual(540, thunks[0].import_ordinal)
        call_address = 0x40702D
        displacement = int(fixture["thunk_address"], 16) - (call_address + 5)
        encoded = b"\xe8" + struct.pack("<i", displacement)
        retail = tuple(
            parse_assembly(
                f"{call_address:08x} "
                + " ".join(f"{value:02x}" for value in encoded)
                + " call CString::ConstructorDefault",
                source="bn",
            )
        )
        retail_indexes = (
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                retail,
                indexes=fixture["indexes"],
                thunks=thunks,
            )
        )
        fixture["expected"] = extract_invocation_contract(
            retail,
            source="bn",
            caller_identity="symbol:recoil:function:0x407010",
            caller_start="0x407010",
            caller_end_exclusive="0x407050",
            indexes=retail_indexes,
            bridge_names=retail_names,
        )
        self.assertEqual(
            fixture["provider_identity"],
            fixture["expected"][0]["target_identity"],
        )
        self.assertEqual("provider", fixture["expected"][0]["identity_kind"])
        bridges = self._prove_cstring_ordinal_candidate(
            fixture,
            thunks,
            retail_names,
        )
        self.assertEqual(
            {fixture["callable_symbol"]: fixture["provider_identity"]},
            bridges,
        )
        candidate_contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity="symbol:recoil:function:0x407010",
            caller_start="0x407010",
            caller_end_exclusive="0x407050",
            indexes=fixture["indexes"],
            bridge_names=retail_names,
            compiler_generated_bridges=bridges,
        )
        self.assertEqual(fixture["expected"], candidate_contract)

    def test_ordinal_import_thunk_retail_identity_map_fails_closed(self) -> None:
        fixture = self._cstring_ordinal_import_thunk_fixture()
        thunks, retail_names = self._prove_cstring_ordinal_retail(fixture)
        call_address = 0x40702D
        displacement = int(fixture["thunk_address"], 16) - (call_address + 5)
        encoded = b"\xe8" + struct.pack("<i", displacement)
        retail = tuple(
            parse_assembly(
                f"{call_address:08x} "
                + " ".join(f"{value:02x}" for value in encoded)
                + " call CString::ConstructorDefault",
                source="bn",
            )
        )

        with self.assertRaisesRegex(ValueError, "ambiguous import thunks"):
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                retail,
                indexes=fixture["indexes"],
                thunks=(thunks[0], thunks[0]),
            )

        incomplete_indexes = replace(
            fixture["indexes"],
            provider_ids=frozenset(),
        )
        with self.assertRaisesRegex(ValueError, "exact provider/IAT proof"):
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                retail,
                indexes=incomplete_indexes,
                thunks=thunks,
            )

        conflicting_indexes = replace(
            fixture["indexes"],
            reviewed_direct_import_thunk_by_call_site={
                "0x40702d": (
                    fixture["thunk_address"],
                    "provider:recoil:function:0x4c5ba6",
                )
            },
        )
        with self.assertRaisesRegex(ValueError, "conflicting immutable identities"):
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                retail,
                indexes=conflicting_indexes,
                thunks=thunks,
            )

        malformed = (
            replace(
                retail[0],
                bytes=("e9", *retail[0].bytes[1:]),
            ),
        )
        malformed_indexes = (
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                malformed,
                indexes=fixture["indexes"],
                thunks=thunks,
            )
        )
        self.assertEqual(
            {},
            malformed_indexes.reviewed_direct_import_thunk_by_call_site,
        )
        with self.assertRaisesRegex(ValueError, "exact x86 CALL/JMP encoding"):
            extract_invocation_contract(
                malformed,
                source="bn",
                caller_identity="symbol:recoil:function:0x407010",
                caller_start="0x407010",
                caller_end_exclusive="0x407050",
                indexes=malformed_indexes,
                bridge_names=retail_names,
            )

    def test_ordinal_import_thunk_retail_negative_matrix(self) -> None:
        cases = (
            (
                "named-substitution",
                lambda fixture, data: (
                    data["symbols"][f"recoil:function:{fixture['iat_address']}"]
                    .pop("import_ordinal"),
                    data["symbols"][f"recoil:data:{fixture['iat_address']}"]
                    .pop("import_ordinal"),
                ),
                "complete current ordinal package",
            ),
            (
                "wrong-dll",
                lambda fixture, data: data["symbols"][
                    f"recoil:function:{fixture['iat_address']}"
                ].__setitem__("import_dll", "MFC40.DLL"),
                "complete current ordinal package",
            ),
            (
                "wrong-ordinal",
                lambda fixture, data: data["symbols"][
                    f"recoil:function:{fixture['iat_address']}"
                ].__setitem__("import_ordinal", 541),
                "complete current ordinal package",
            ),
            (
                "wrong-descriptor",
                lambda fixture, data: data["evidence"][
                    "recoil:evidence:r1326:000001"
                ]["provenance"].__setitem__("descriptor_index", -1),
                "complete current ordinal package",
            ),
            (
                "stale-evidence",
                lambda fixture, data: data["evidence"][
                    "recoil:evidence:r1326:000001"
                ].__setitem__("freshness", "historical"),
                "complete current ordinal package",
            ),
            (
                "wrong-extent",
                lambda fixture, data: data["symbols"][
                    f"recoil:data:{fixture['iat_address']}"
                ].__setitem__("end_exclusive", "0x4cc3c8"),
                "complete current ordinal package",
            ),
            (
                "missing-owner",
                lambda fixture, data: data["owners"].pop(
                    fixture["thunk_owner_id"]
                ),
                None,
            ),
            (
                "multiple-owner",
                lambda fixture, data: data["owners"].__setitem__(
                    f"{fixture['thunk_owner_id']}.duplicate",
                    deepcopy(data["owners"][fixture["thunk_owner_id"]]),
                ),
                "exactly one accepted",
            ),
            (
                "wrong-thunk-extent",
                lambda fixture, data: data["symbols"][
                    fixture["thunk_symbol_id"]
                ].__setitem__("size", 7),
                None,
            ),
            (
                "wrong-provider-block",
                lambda fixture, data: data["physical_blocks"][
                    fixture["thunk_block_id"]
                ].__setitem__("contribution_kind", "authored"),
                "provider block",
            ),
        )
        for label, mutate, message in cases:
            fixture = self._cstring_ordinal_import_thunk_fixture()
            data = deepcopy(fixture["document"].data)
            mutate(fixture, data)
            fixture["document"] = ProgressDocument(data)
            fixture["indexes"] = build_identity_indexes(
                fixture["document"],
                bridge_by_address=fixture["bridge_by_address"],
            )
            with self.subTest(label=label):
                if message is None:
                    self.assertEqual(
                        ((), {}),
                        self._prove_cstring_ordinal_retail(fixture),
                    )
                else:
                    with self.assertRaisesRegex(ValueError, message):
                        self._prove_cstring_ordinal_retail(fixture)

        for label, hexdump, message in (
            (
                "non-ff25",
                "004c5ba0 ff 15 c0 c3 4c 00",
                "six-byte FF25",
            ),
            (
                "wrong-iat-operand",
                "004c5ba0 ff 25 c4 c3 4c 00",
                "complete current ordinal package",
            ),
        ):
            fixture = self._cstring_ordinal_import_thunk_fixture()
            fixture["bridge"] = SimpleNamespace(
                hexdump=lambda address, size, value=hexdump: value
            )
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                message,
            ):
                self._prove_cstring_ordinal_retail(fixture)

        fixture = self._cstring_ordinal_import_thunk_fixture()
        wrong_friendly = replace(
            fixture["friendly_symbol"],
            address="0x4c5ba6",
        )
        fixture["bridge_by_name"] = {
            "CString::ConstructorDefault": wrong_friendly
        }
        with self.assertRaisesRegex(ValueError, "BN friendly target"):
            self._prove_cstring_ordinal_retail(fixture)

    def test_ordinal_import_thunk_candidate_negative_matrix(self) -> None:
        operand_cases = (
            (
                "case-alias",
                "??0cstring@@QAE@XZ",
                "exact direct callable operand",
            ),
            (
                "indirect",
                "dword ptr [??0CString@@QAE@XZ]",
                "exact direct callable operand",
            ),
            (
                "direct-iat",
                "__imp_??0CString@@QAE@XZ",
                "exact direct callable operand",
            ),
        )
        for label, operand, message in operand_cases:
            fixture = self._cstring_ordinal_import_thunk_fixture()
            thunks, names = self._prove_cstring_ordinal_retail(fixture)
            instruction = fixture["candidate"].instructions[0]
            fixture["candidate"] = replace(
                fixture["candidate"],
                instructions=(
                    replace(
                        instruction,
                        raw_text=f"call {operand}",
                        text=f"call {operand}",
                    ),
                ),
            )
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                message,
            ):
                self._prove_cstring_ordinal_candidate(fixture, thunks, names)

        caller_cases = (
            (
                "missing",
                lambda fixture, caller: replace(
                    caller,
                    undefined_external_functions=(),
                ),
                "exactly one undefined",
            ),
            (
                "duplicate",
                lambda fixture, caller: replace(
                    caller,
                    undefined_external_functions=(
                        fixture["callable_symbol"],
                        fixture["callable_symbol"],
                    ),
                ),
                "exactly one undefined",
            ),
            (
                "nonfunction-or-defined",
                lambda fixture, caller: replace(
                    caller,
                    undefined_external_functions=("?Other@@3HA",),
                ),
                "exactly one undefined",
            ),
            (
                "relocation-type",
                lambda fixture, caller: replace(
                    caller,
                    relocations=(
                        replace(caller.relocations[0], type=0x06),
                    ),
                ),
                "E8/E9 REL32",
            ),
            (
                "relocation-addend",
                lambda fixture, caller: replace(
                    caller,
                    data=bytes.fromhex("e8 01 00 00 00 c3"),
                ),
                "E8/E9 REL32",
            ),
            (
                "relocation-mask",
                lambda fixture, caller: replace(
                    caller,
                    relocation_mask=(
                        False,
                        True,
                        True,
                        False,
                        True,
                        False,
                    ),
                ),
                "E8/E9 REL32",
            ),
            (
                "missing-relocation",
                lambda fixture, caller: replace(
                    caller,
                    relocations=(),
                ),
                "equal nonempty",
            ),
        )
        for label, mutate, message in caller_cases:
            fixture = self._cstring_ordinal_import_thunk_fixture()
            thunks, names = self._prove_cstring_ordinal_retail(fixture)
            caller = mutate(fixture, fixture["caller"])
            fixture["candidate"] = replace(
                fixture["candidate"],
                caller_definition=caller,
            )
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                message,
            ):
                self._prove_cstring_ordinal_candidate(fixture, thunks, names)

        fixture = self._cstring_ordinal_import_thunk_fixture()
        thunks, names = self._prove_cstring_ordinal_retail(fixture)
        instruction = fixture["candidate"].instructions[0]
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=(
                replace(
                    instruction,
                    bytes=("e9", "00", "00", "00", "00"),
                ),
            ),
        )
        with self.assertRaisesRegex(ValueError, "direct E8 CALL"):
            self._prove_cstring_ordinal_candidate(fixture, thunks, names)

        for label, mutate in (
            (
                "candidate-index-collision",
                lambda fixture, names: fixture.__setitem__(
                    "indexes",
                    replace(
                        fixture["indexes"],
                        by_candidate_name={
                            fixture["callable_symbol"]: "symbol:collision"
                        },
                    ),
                ),
            ),
            (
                "bridge-name-collision",
                lambda fixture, names: names.__setitem__(
                    fixture["callable_symbol"],
                    [
                        Symbol(
                            address="0x4c5ba6",
                            name=fixture["callable_symbol"],
                        )
                    ],
                ),
            ),
        ):
            fixture = self._cstring_ordinal_import_thunk_fixture()
            thunks, names = self._prove_cstring_ordinal_retail(fixture)
            mutate(fixture, names)
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "collision-free",
            ):
                self._prove_cstring_ordinal_candidate(fixture, thunks, names)

        for label, mutate in (
            (
                "ordinal-drift",
                lambda row: row.__setitem__("ordinal", 1),
            ),
            (
                "cleanup-drift",
                lambda row: row.__setitem__("cleanup_bytes", 4),
            ),
            (
                "form-drift",
                lambda row: row.__setitem__("form", "tail"),
            ),
        ):
            fixture = self._cstring_ordinal_import_thunk_fixture()
            thunks, names = self._prove_cstring_ordinal_retail(fixture)
            mutate(fixture["expected"][0])
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "ordinal, direct call/tail form, or cleanup drift",
            ):
                self._prove_cstring_ordinal_candidate(fixture, thunks, names)

