    def test_register_based_lea_preserves_member_address_provenance(self) -> None:
        retail = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "00403af0 8b f1 mov esi, ecx",
                        "00403af2 8d ae e8 aa 00 00 lea ebp, [esi+0xaae8]",
                        "00403af8 8b 45 00 mov eax, dword [ebp]",
                        "00403afb ff 50 60 call dword [eax+0x60]",
                    ]
                ),
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:caller",
            caller_start="0x403930",
            caller_end_exclusive="0x403b20",
            indexes=self.indexes,
        )
        candidate = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "  00010 8b f9 mov edi, ecx",
                        "  00012 8d 9f e8 aa 00 00 lea ebx, [edi+0xaae8]",
                        "  00018 8b 13 mov edx, dword [ebx]",
                        "  0001a ff 52 60 call dword [edx+0x60]",
                    ]
                ),
                source="cod",
            ),
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x403930",
            caller_end_exclusive="0x403b20",
            indexes=self.indexes,
        )
        self.assertEqual(retail, candidate)
        self.assertEqual("virtual-slot", retail[0]["identity_kind"])
        self.assertEqual(0x60, retail[0]["slot_displacement"])
        self.assertEqual(
            "load(address(this+0xaae8))",
            retail[0]["storage_identity"],
        )

        negative = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "00403af0 8b f1 mov esi, ecx",
                        "00403af2 8d 6e fc lea ebp, [esi-0x4]",
                        "00403af5 8b 45 00 mov eax, dword [ebp]",
                        "00403af8 ff 50 08 call dword [eax+0x8]",
                    ]
                ),
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:caller",
            caller_start="0x403930",
            caller_end_exclusive="0x403b20",
            indexes=self.indexes,
        )
        self.assertEqual(
            "load(address(this-0x4))",
            negative[0]["storage_identity"],
        )

    def test_register_based_lea_provenance_fails_closed_when_unproven(self) -> None:
        indexes = IdentityIndexes(
            by_address=self.indexes.by_address,
            by_candidate_name=self.indexes.by_candidate_name,
            provider_ids=self.indexes.provider_ids,
            storage_by_address={"0x4cc5c4": "iat:sprintf"},
            storage_by_name={"__imp__sprintf": "iat:sprintf"},
        )
        cases = {
            "unknown-base": [
                "00403af0 8d af e8 aa 00 00 lea ebp, [edi+0xaae8]",
                "00403af6 8b 45 00 mov eax, dword [ebp]",
                "00403af9 ff 50 60 call dword [eax+0x60]",
            ],
            "absolute-lea-is-not-load": [
                "00403af0 8d 2d c4 c5 4c 00 lea ebp, [0x4cc5c4]",
                "00403af6 8b 45 00 mov eax, dword [ebp]",
                "00403af9 ff 50 60 call dword [eax+0x60]",
            ],
            "member-address-clobbered": [
                "00403af0 8b f1 mov esi, ecx",
                "00403af2 8d ae e8 aa 00 00 lea ebp, [esi+0xaae8]",
                "00403af8 33 ed xor ebp, ebp",
                "00403afa 8b 45 00 mov eax, dword [ebp]",
                "00403afd ff 50 60 call dword [eax+0x60]",
            ],
            "unknown-register-load": [
                "00403af0 8b 07 mov eax, dword [edi]",
                "00403af2 ff 50 60 call dword [eax+0x60]",
            ],
        }
        for label, lines in cases.items():
            with self.subTest(label=label):
                with self.assertRaisesRegex(
                    ValueError,
                    "unresolved indirect register (?:storage|provenance) eax",
                ):
                    extract_invocation_contract(
                        parse_assembly("\n".join(lines), source="bn"),
                        source="bn",
                        caller_identity="symbol:caller",
                        caller_start="0x403930",
                        caller_end_exclusive="0x403b20",
                        indexes=indexes,
                    )

