    def test_exact_address_cursor_spill_is_transparent_and_symmetric(
        self,
    ) -> None:
        direct = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "  00000 8d 79 1c lea edi, [ecx+0x1c]",
                        "  00003 8b 0f mov ecx, [edi]",
                        "  00005 8b 01 mov eax, [ecx]",
                        "  00007 ff 50 60 call [eax+0x60]",
                    ]
                ),
                source="cod",
            ),
            source="cod",
            caller_identity="symbol:cursor-direct",
            caller_start="0x401000",
            caller_end_exclusive="0x401100",
            indexes=self.indexes,
        )
        spilled = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "00401000 8d 51 1c lea edx, [ecx+0x1c]",
                        "00401003 89 54 24 14 mov [esp+0x14], edx",
                        "00401007 8b 7c 24 14 mov edi, [esp+0x14]",
                        "0040100b 8b 0f mov ecx, [edi]",
                        "0040100d 8b 01 mov eax, [ecx]",
                        "0040100f ff 50 60 call [eax+0x60]",
                    ]
                ),
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:cursor-spilled",
            caller_start="0x401000",
            caller_end_exclusive="0x401100",
            indexes=self.indexes,
        )
        self.assertEqual(direct, spilled)
        self.assertEqual(
            "load(load(address(this+0x1c)))",
            spilled[0]["storage_identity"],
        )

        incremented = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "00401000 8d 51 1c lea edx, [ecx+0x1c]",
                        "00401003 83 c2 04 add edx, 4",
                        "00401006 89 54 24 14 mov [esp+0x14], edx",
                        "0040100a 8b 7c 24 14 mov edi, [esp+0x14]",
                        "0040100e 8b 0f mov ecx, [edi]",
                        "00401010 8b 01 mov eax, [ecx]",
                        "00401012 ff 50 60 call [eax+0x60]",
                    ]
                ),
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:cursor-incremented",
            caller_start="0x401000",
            caller_end_exclusive="0x401100",
            indexes=self.indexes,
        )
        self.assertEqual(
            "load(load(address(this+0x20)))",
            incremented[0]["storage_identity"],
        )

