    def test_vc5_affine_cursor_locals_preserve_real_loop_topology(
        self,
    ) -> None:
        cases = (
            ("retail-shaped", "14", "-24", 0x14),
            ("candidate-shaped", "10", "-28", 0x10),
        )
        for label, encoded_slot, prefix, slot in cases:
            with self.subTest(label=label):
                instructions = parse_assembly(
                    "\n".join(
                        [
                            "  00000 8b e9 mov ebp, ecx",
                            (
                                f"  00002 8a 4c 24 "
                                f"{slot - 1:02x} "
                                f"mov cl, byte ptr [esp+{slot - 1}]"
                            ),
                            (
                                f"  00006 c7 44 24 {encoded_slot} "
                                "03 00 00 00 "
                                f"mov dword ptr {prefix}+[esp+44], 3"
                            ),
                            (
                                "  0000e 8d 55 1c "
                                "lea edx, dword ptr [ebp+28]"
                            ),
                            (
                                f"  00011 89 54 24 {encoded_slot} "
                                f"mov dword ptr {prefix}+[esp+44], edx"
                            ),
                            (
                                "  00015 c7 44 24 18 08 00 00 00 "
                                "mov dword ptr [esp+24], 8"
                            ),
                            (
                                f"  0001d 8b 74 24 {encoded_slot} "
                                f"mov esi, dword ptr {prefix}+[esp+44]"
                            ),
                            "  00021 bb 03 00 00 00 mov ebx, 3",
                            (
                                "  00026 e8 00 00 00 00 "
                                "call ?Callee@@YAXXZ"
                            ),
                            "  0002b 8b 0e mov ecx, [esi]",
                            "  0002d 8b 01 mov eax, [ecx]",
                            "  0002f ff 50 60 call [eax+96]",
                            "  00032 83 c6 04 add esi, 4",
                            "  00035 4b dec ebx",
                            "  00036 75 ee jne 0x26",
                            (
                                f"  00038 89 74 24 {encoded_slot} "
                                f"mov dword ptr {prefix}+[esp+44], esi"
                            ),
                            "  0003c 8b 44 24 18 mov eax, [esp+24]",
                            "  00040 48 dec eax",
                            "  00041 89 44 24 18 mov [esp+24], eax",
                            "  00045 75 d6 jne 0x1d",
                        ]
                    ),
                    source="cod",
                )
                contract = extract_invocation_contract(
                    instructions,
                    source="cod",
                    caller_identity=f"symbol:{label}",
                    caller_start="0x401000",
                    caller_end_exclusive="0x401100",
                    indexes=self.indexes,
                )
                self.assertEqual(2, len(contract))
                self.assertEqual("symbol:callee", contract[0]["target_identity"])
                self.assertEqual(
                    "load(load(address(this+0x1c)))",
                    contract[1]["storage_identity"],
                )
                self.assertNotIn(
                    f"stack+0x{slot:x}",
                    contract[1]["storage_identity"],
                )

