    def test_bounded_stack_vptr_helper_rejects_non_stack_and_wrapped_roots(
        self,
    ) -> None:
        for abstract in (
            "load(stack+0x14)",
            "load(load(load(load(stack+0x14))))",
            "load(load(frame+0x14))",
            "load(load(address(this+0x14)))",
            "load(load(nullable(stack+0x14)))",
            "load(load(stack+0x14)+0x4)",
            "nullable(load(load(stack+0x14)))",
            "load(load(stack+20))",
            "load(load(stack+0x))",
        ):
            with self.subTest(abstract=abstract):
                self.assertFalse(_is_bounded_stack_vptr(abstract))

