    def test_vc5_symbolic_indexed_stack_array_fails_closed_on_drift(
        self,
    ) -> None:
        base = [
            "  00000 33 ff xor edi, edi",
            (
                "  00002 89 4c 24 2c "
                "mov dword _cells$82920[esp+56], ecx"
            ),
            (
                "  00006 89 54 24 30 "
                "mov dword _cells$82920[esp+60], edx"
            ),
            (
                "  0000a 89 44 24 34 "
                "mov dword _cells$82920[esp+64], eax"
            ),
            (
                "  0000e 8b 74 bc 2c "
                "mov esi, dword _cells$82920[esp+edi*4+56]"
            ),
            "  00012 8b 16 mov edx, dword [esi]",
            "  00014 ff 92 80 00 00 00 call dword [edx+128]",
            "  0001a 83 ff 02 cmp edi, 2",
            "  0001d 75 00 jne 0x1f",
            "  0001f 47 inc edi",
            "  00020 83 ff 03 cmp edi, 3",
            "  00023 72 e9 jb 0x0e",
        ]
        cases = {
            "backing-symbol-drift": base[:3]
            + [
                (
                    "  0000a 89 44 24 34 "
                    "mov dword _other$82920[esp+64], eax"
                )
            ]
            + base[4:],
            "nonconstant-symbol-delta": base[:2]
            + [
                (
                    "  00006 89 54 24 30 "
                    "mov dword _cells$82920[esp+61], edx"
                )
            ]
            + base[3:],
            "mixed-numeric-backing-store": base[:2]
            + ["  00006 89 54 24 30 mov dword [esp+48], edx"]
            + base[3:],
            "nonexact-intervening-compare": base[:7]
            + ["  0001a 8b ff 02 cmp edi, 2"]
            + base[8:],
        }
        for label, lines in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "unresolved indirect register storage edx",
            ):
                extract_invocation_contract(
                    parse_assembly("\n".join(lines), source="cod"),
                    source="cod",
                    caller_identity="symbol:vc5-symbolic-array-drift",
                    caller_start="0x40e140",
                    caller_end_exclusive="0x40e240",
                    indexes=self.indexes,
                )

        with self.subTest(label="symbolic-operands-are-cod-only"):
            with self.assertRaisesRegex(
                ValueError,
                "unresolved indirect register storage edx",
            ):
                extract_invocation_contract(
                    parse_assembly(
                        "\n".join(
                            [
                                "00401000 33 ff xor edi, edi",
                                (
                                    "00401002 89 4c 24 2c "
                                    "mov dword _cells$1[esp+56], ecx"
                                ),
                                (
                                    "00401006 89 54 24 30 "
                                    "mov dword _cells$1[esp+60], edx"
                                ),
                                (
                                    "0040100a 89 44 24 34 "
                                    "mov dword _cells$1[esp+64], eax"
                                ),
                                (
                                    "0040100e 8b 74 bc 2c "
                                    "mov esi, dword "
                                    "_cells$1[esp+edi*4+56]"
                                ),
                                "00401012 8b 16 mov edx, dword [esi]",
                                (
                                    "00401014 ff 92 80 00 00 00 "
                                    "call dword [edx+128]"
                                ),
                                "0040101a 83 ff 02 cmp edi, 2",
                                "0040101d 75 00 jne 0x40101f",
                                "0040101f 47 inc edi",
                                "00401020 83 ff 03 cmp edi, 3",
                                "00401023 72 e9 jb 0x40100e",
                            ]
                        ),
                        source="bn",
                    ),
                    source="bn",
                    caller_identity="symbol:bn-symbolic-array",
                    caller_start="0x401000",
                    caller_end_exclusive="0x401100",
                    indexes=self.indexes,
                )

    def test_bounded_indexed_stack_array_rejects_unproven_topology(
        self,
    ) -> None:
        base = [
            "00401000 33 ff xor edi, edi",
            "00401002 89 44 24 2c mov [esp+0x2c], eax",
            "00401006 89 4c 24 30 mov [esp+0x30], ecx",
            "0040100a 89 54 24 34 mov [esp+0x34], edx",
            "0040100e 8b 74 bc 2c mov esi, [esp+edi*4+0x2c]",
            "00401012 8b 16 mov edx, [esi]",
            "00401014 ff 92 80 00 00 00 call dword [edx+0x80]",
            "0040101a 47 inc edi",
            "0040101b 83 ff 03 cmp edi, 3",
            "0040101e 72 ee jb 0x40100e",
        ]
        cases = {
            "missing-backing-slot": base[:3] + base[4:],
            "index-clobber": base[:4]
            + ["0040100d 8b f8 mov edi, eax"]
            + base[4:],
            "excessive-count": base[:-2]
            + [
                "0040101b 83 ff 11 cmp edi, 17",
                "0040101e 72 ee jb 0x40100e",
            ],
            "slot-clobber-before-backedge": base[:-2]
            + [
                "0040101b 89 44 24 2c mov [esp+0x2c], eax",
                "0040101f 83 ff 03 cmp edi, 3",
                "00401022 72 ea jb 0x40100e",
            ],
            "non-exact-final-operand": base[:6]
            + [
                (
                    "00401014 ff 94 82 80 00 00 00 "
                    "call dword [edx+eax*4+0x80]"
                )
            ]
            + base[7:],
            "excessive-vptr-depth": base[:6]
            + [
                "00401014 8b 02 mov eax, [edx]",
                "00401016 8b 08 mov ecx, [eax]",
                (
                    "00401018 ff 91 80 00 00 00 "
                    "call dword [ecx+0x80]"
                ),
                "0040101e 47 inc edi",
                "0040101f 83 ff 03 cmp edi, 3",
                "00401022 72 ea jb 0x40100e",
            ],
        }
        for label, lines in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "unresolved indirect register (?:storage|provenance)",
            ):
                extract_invocation_contract(
                    parse_assembly("\n".join(lines), source="bn"),
                    source="bn",
                    caller_identity="symbol:indexed-stack-negative",
                    caller_start="0x401000",
                    caller_end_exclusive="0x401100",
                    indexes=self.indexes,
                )

