    def test_stack_root_fails_closed_on_unsafe_grammar_or_clobber(
        self,
    ) -> None:
        cases = {
            "negative-add": "00401000 83 c4 fc add esp, -4",
            "negative-sub": "00401000 83 ec fc sub esp, -4",
            "non-immediate-add": "00401000 03 e0 add esp, eax",
            "non-immediate-sub": "00401000 2b e0 sub esp, eax",
            "partial-register": "00401000 66 83 c4 04 add sp, 4",
            "positive-overflow-add": (
                "00401000 81 c4 00 00 00 80 add esp, 0x80000000"
            ),
            "positive-overflow-sub": (
                "00401000 81 ec 00 00 00 80 sub esp, 0x80000000"
            ),
            "operand-prefix": "00401000 66 83 c4 04 add esp, 4",
            "encoded-text-mismatch": "00401000 83 c4 04 add esp, 8",
            "encoded-negative": "00401000 83 c4 fc add esp, 252",
            "trailing-byte": "00401000 83 c4 04 90 add esp, 4",
            "increment": "00401000 44 inc esp",
            "move-clobber": "00401000 8b e1 mov esp, ecx",
            "partial-move": "00401000 66 8b e0 mov sp, ax",
            "lea-clobber": "00401000 8d 65 04 lea esp, [ebp+4]",
            "partial-and": "00401000 66 83 e4 fc and sp, 0xfffc",
            "pop-esp": "00401000 5c pop esp",
            "exchange": "00401000 94 xchg esp, eax",
            "partial-exchange": "00401000 66 93 xchg sp, ax",
            "enter": "00401000 c8 08 00 00 enter 8, 0",
            "leave": "00401000 c9 leave",
        }
        tail = [
            "00401010 8b 4c 24 08 mov ecx, [esp+8]",
            "00401014 8b 11 mov edx, [ecx]",
            "00401016 ff 52 60 call [edx+96]",
        ]
        for label, unsafe in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "unresolved indirect register storage edx",
            ):
                extract_invocation_contract(
                    parse_assembly("\n".join([unsafe, *tail]), source="bn"),
                    source="bn",
                    caller_identity="symbol:caller",
                    caller_start="0x401000",
                    caller_end_exclusive="0x401100",
                    indexes=self.indexes,
                )

