    def _non_gating_logical_target_indexes(
        self,
        data: dict,
        target_id: str,
        *,
        current: dict | None = None,
    ) -> IdentityIndexes:
        synchronized = deepcopy(
            current
            if current is not None
            else data["verification_targets"][target_id]
        )
        with patch(
            "_recoil.lib.verification_targets.vc5_target_registration",
            return_value=(target_id, synchronized),
        ):
            return build_identity_indexes(ProgressDocument(data))

