    def test_winner_unknown_icf_group_matches_exact_0x404e90_ordinal_6(
        self,
    ) -> None:
        data, physical_id, target_id, primary, alternate = (
            self._winner_unknown_icf_fixture()
        )
        indexes = self._winner_unknown_icf_indexes(data, target_id)
        group_identity = f"icf-group:{physical_id}"
        self.assertEqual("", indexes.by_address["0x4076f0"])
        self.assertEqual(
            group_identity,
            indexes.reviewed_icf_group_by_address["0x4076f0"],
        )
        for alias_id, object_symbol in (primary, alternate):
            self.assertEqual(
                group_identity,
                indexes.reviewed_icf_group_by_logical_identity[
                    f"logical:{alias_id}"
                ],
            )
            self.assertEqual(
                f"logical:{alias_id}",
                indexes.by_candidate_name[object_symbol],
            )

        direct_targets = {
            "0x44a250": "symbol:camera-target",
            "0x4726d0": "symbol:delta-length",
            "0x405040": "symbol:chase-camera",
            "0x4057d0": "symbol:top-down-camera",
            "0x4059a0": "symbol:first-person-camera",
            "0x405650": "symbol:third-person-camera",
        }
        candidate_targets = {
            "?CameraTarget@@YAXXZ": "symbol:camera-target",
            "?DeltaLength@@YAXXZ": "symbol:delta-length",
            "?ChaseCamera@@YAXXZ": "symbol:chase-camera",
            "?TopDownCamera@@YAXXZ": "symbol:top-down-camera",
            "?FirstPersonCamera@@YAXXZ": "symbol:first-person-camera",
            "?ThirdPersonCamera@@YAXXZ": "symbol:third-person-camera",
        }
        indexes = replace(
            indexes,
            by_address={**indexes.by_address, **direct_targets},
            by_candidate_name={
                **indexes.by_candidate_name,
                **candidate_targets,
            },
        )
        retail = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "00404ee1 e8 6a 53 04 00 call 0x44a250",
                        "00404eec e8 df d7 06 00 call 0x4726d0",
                        "00404f7e e8 bd 00 00 00 call 0x405040",
                        "00404f87 e8 44 08 00 00 call 0x4057d0",
                        "00404f90 e8 0b 0a 00 00 call 0x4059a0",
                        "00404f99 e8 b2 06 00 00 call 0x405650",
                        "00404fa2 e8 49 27 00 00 call "
                        "CompilerICF::ReturnOnlyRepresentative_WinnerUnknown",
                        "00404fa7 eb 10 jmp 0x404fb9",
                    ]
                ),
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:recoil:function:0x404e90",
            caller_start="0x404e90",
            caller_end_exclusive="0x405040",
            indexes=indexes,
            bridge_names={
                "CompilerICF::ReturnOnlyRepresentative_WinnerUnknown": [
                    Symbol(
                        address="0x4076f0",
                        name=(
                            "CompilerICF::"
                            "ReturnOnlyRepresentative_WinnerUnknown"
                        ),
                    )
                ]
            },
        )
        candidate = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "  00001 e8 00 00 00 00 call ?CameraTarget@@YAXXZ",
                        "  00010 e8 00 00 00 00 call ?DeltaLength@@YAXXZ",
                        "  00126 e8 00 00 00 00 call ?ChaseCamera@@YAXXZ",
                        "  0012f e8 00 00 00 00 call ?TopDownCamera@@YAXXZ",
                        "  00138 e8 00 00 00 00 call ?FirstPersonCamera@@YAXXZ",
                        "  00141 e8 00 00 00 00 call ?ThirdPersonCamera@@YAXXZ",
                        "  00148 e8 00 00 00 00 call "
                        "?ReturnOnlyStub@zGame@@YAXXZ",
                        "  0014d eb 10 jmp $Ldone",
                    ]
                ),
                source="cod",
            ),
            source="cod",
            caller_identity="symbol:recoil:function:0x404e90",
            caller_start="0x404e90",
            caller_end_exclusive="0x405040",
            indexes=indexes,
        )
        self.assertEqual(retail, candidate)
        self.assertEqual(6, retail[6]["ordinal"])
        self.assertEqual(group_identity, retail[6]["target_identity"])
        self.assertEqual("direct", retail[6]["dispatch"])
        self.assertIsNone(retail[6]["cleanup_bytes"])

        alternate_candidate = deepcopy(candidate)
        alternate_contract = extract_invocation_contract(
            parse_assembly(
                f"  00148 e8 00 00 00 00 call {alternate[1]}",
                source="cod",
            ),
            source="cod",
            caller_identity="symbol:recoil:function:0x404e90",
            caller_start="0x404e90",
            caller_end_exclusive="0x405040",
            indexes=indexes,
        )
        self.assertEqual(group_identity, alternate_contract[0]["target_identity"])
        alternate_candidate[6] = alternate_contract[0]
        alternate_candidate[6]["ordinal"] = 6
        self.assertEqual(retail, alternate_candidate)

