                changed = deepcopy(data)
                mutation(changed["evidence"][evidence_id])
                with self.assertRaisesRegex(
                    ValueError,
                    "stale, candidate-dependent, or inexact current alias-review evidence",
                ):
                    self._winner_unknown_icf_indexes(changed, target_id)

