    def test_winner_unknown_icf_group_rejects_incomplete_authority(
        self,
    ) -> None:
        mutations = {
            "provider physical row": lambda data, physical, _target, _primary, _alternate: (
                data["symbols"][physical].__setitem__("kind", "provider-function")
            ),
            "wrong compiler role": lambda data, physical, _target, _primary, _alternate: (
                data["symbols"][physical].__setitem__(
                    "authored_order_role", "authored-body"
                )
            ),
            "singleton group": lambda data, physical, target, _primary, alternate: (
                data["symbols"][physical]["logical_aliases"].pop(alternate[0]),
                data["verification_targets"][target]["registration"][
                    "translation_unit_function_order"
                ][0]["functions"].pop(),
            ),
            "wrong-address alias": lambda data, physical, _target, primary, _alternate: (
                data["symbols"][physical]["logical_aliases"].__setitem__(
                    primary[0].replace("0x4076f0", "0x407700"),
                    data["symbols"][physical]["logical_aliases"].pop(primary[0]),
                )
            ),
            "missing owner": lambda data, physical, _target, primary, _alternate: (
                data["symbols"][physical]["logical_aliases"][primary[0]].__setitem__(
                    "owner_id", "recoil:owner:missing"
                )
            ),
            "provider owner": lambda data, physical, _target, primary, _alternate: (
                data["owners"][
                    data["symbols"][physical]["logical_aliases"][primary[0]][
                        "owner_id"
                    ]
                ].__setitem__("kind", "provider-boundary")
            ),
            "missing evidence membership": lambda data, physical, _target, primary, _alternate: (
                data["evidence"][
                    data["symbols"][physical]["icf_address_group"]["evidence_ids"][0]
                ]["scope_ids"].remove(primary[0])
            ),
            "duplicate group evidence": lambda data, physical, _target, _primary, _alternate: (
                data["symbols"][physical]["icf_address_group"]["evidence_ids"].append(
                    data["symbols"][physical]["icf_address_group"]["evidence_ids"][0]
                )
            ),
            "missing registration": lambda data, _physical, target, _primary, _alternate: (
                data["verification_targets"][target]["registration"][
                    "translation_unit_function_order"
                ][0]["functions"].pop()
            ),
            "duplicate registration": lambda data, _physical, target, _primary, _alternate: (
                data["verification_targets"][target]["registration"][
                    "translation_unit_function_order"
                ][0]["functions"].append(
                    deepcopy(
                        data["verification_targets"][target]["registration"][
                            "translation_unit_function_order"
                        ][0]["functions"][0]
                    )
                )
            ),
            "duplicate alias symbol": lambda data, physical, _target, primary, alternate: (
                data["symbols"][physical]["logical_aliases"][alternate[0]].__setitem__(
                    "object_symbol",
                    data["symbols"][physical]["logical_aliases"][primary[0]][
                        "object_symbol"
                    ],
                )
            ),
            "synthetic authored alias": lambda data, physical, _target, primary, _alternate: (
                data["symbols"][physical]["logical_aliases"][primary[0]].__setitem__(
                    "original_name",
                    "CompilerICF::ReturnOnlyRepresentative_WinnerUnknown",
                )
            ),
        }
        non_authoritative_without_error = {
            "provider physical row",
            "wrong compiler role",
            "singleton group",
        }
        for label, mutate in mutations.items():
            with self.subTest(label=label):
                data, physical_id, target_id, primary, alternate = (
                    self._winner_unknown_icf_fixture()
                )
                mutate(data, physical_id, target_id, primary, alternate)
                current = deepcopy(data["verification_targets"][target_id])
                with patch(
                    "_recoil.lib.verification_targets.vc5_target_registration",
                    return_value=(target_id, current),
                ):
                    if label in non_authoritative_without_error:
                        indexes = build_identity_indexes(
                            ProgressDocument(data)
                        )
                        self.assertNotIn(
                            "0x4076f0",
                            indexes.reviewed_icf_group_by_address,
                        )
                    else:
                        with self.assertRaises(ValueError):
                            build_identity_indexes(ProgressDocument(data))

