    def test_generic_legacy_iat_rejects_kind_operation_and_provenance_mismatch(
        self,
    ) -> None:
        base = self._named_iat_provider_document(
            address="0x4cc5c4",
            import_dll="MSVCRT.dll",
            import_name="sprintf",
            object_symbol="__imp__sprintf",
            owner_id="recoil:owner:provider.crt.sprintf_import",
            evidence_id="recoil:evidence:r1300:000001",
            evidence_kind="provider-target-legacy-completion",
            descriptor_index=3,
            thunk_index=79,
            operation="legacy-provider-completion",
        )
        evidence_id = "recoil:evidence:r1300:000001"
        mutations = (
            (
                "missing-legacy-operation",
                lambda row: row["provenance"].pop("operation"),
            ),
            (
                "wrong-legacy-operation",
                lambda row: row["provenance"].__setitem__(
                    "operation",
                    "provider-registration",
                ),
            ),
            (
                "arbitrary-evidence-kind",
                lambda row: row.__setitem__("kind", "provider-note"),
            ),
            (
                "duplicate-scope-identity",
                lambda row: row["scope_ids"].append(row["scope_ids"][0]),
            ),
            (
                "stale-evidence",
                lambda row: row.__setitem__("freshness", "historical"),
            ),
            (
                "candidate-derived-provenance",
                lambda row: row["provenance"].__setitem__(
                    "candidate_independent",
                    False,
                ),
            ),
            (
                "candidate-producer",
                lambda row: row["provenance"].__setitem__(
                    "producer",
                    "candidate-pe-imports",
                ),
            ),
            (
                "wrong-reference",
                lambda row: row["provenance"].__setitem__(
                    "reference",
                    "build/Recoil.exe",
                ),
            ),
            (
                "wrong-iat-coordinate",
                lambda row: row["provenance"].__setitem__(
                    "iat_rva",
                    "0xcc5c0",
                ),
            ),
        )
        for label, mutate in mutations:
            data = deepcopy(base.data)
            mutate(data["evidence"][evidence_id])
            indexes = build_identity_indexes(ProgressDocument(data))
            with self.subTest(label=label):
                self.assertNotEqual(
                    "iat:sprintf",
                    indexes.storage_by_address.get("0x4cc5c4", ""),
                )
                self.assertNotEqual(
                    "iat:sprintf",
                    indexes.storage_by_name.get("sprintf", ""),
                )

