    def test_bn_guarded_jump_table_is_local_only_when_all_targets_are_local(self) -> None:
        instructions = parse_assembly(
            "\n".join(
                [
                    "00401000 83 f8 01 cmp eax, 1",
                    "00401003 77 05 ja 0x40100a",
                    "00401005 ff 24 85 30 10 40 00 jmp dword [eax*4+0x401030]",
                    "0040100c c3 ret",
                    "0040100d c3 ret",
                ]
            ),
            source="bn",
        )

        class HexdumpBridge:
            def __init__(self, targets: tuple[int, ...]) -> None:
                self.targets = targets

            def hexdump(self, address: str, length: int) -> str:
                self.asserted = (address, length)
                raw = struct.pack(f"<{len(self.targets)}I", *self.targets)
                return "401030  " + " ".join(f"{item:02x}" for item in raw)

        local_bridge = HexdumpBridge((0x40100C, 0x40100D))
        local_targets = retail_local_switch_targets(
            instructions,
            caller_start="0x401000",
            caller_end_exclusive="0x401020",
            bridge=local_bridge,  # type: ignore[arg-type]
        )
        self.assertEqual({2: (3, 4)}, local_targets)
        local_indices = retail_local_switch_indices(
            instructions,
            caller_start="0x401000",
            caller_end_exclusive="0x401020",
            bridge=local_bridge,  # type: ignore[arg-type]
        )
        self.assertEqual(frozenset({2}), local_indices)
        self.assertEqual(
            [],
            extract_invocation_contract(
                instructions,
                source="bn",
                caller_identity="symbol:caller",
                caller_start="0x401000",
                caller_end_exclusive="0x401020",
                indexes=self.indexes,
                local_control_flow_indices=local_indices,
                local_control_flow_targets=local_targets,
            ),
        )

        mixed_bridge = HexdumpBridge((0x40100C, 0x402000))
        mixed_indices = retail_local_switch_indices(
            instructions,
            caller_start="0x401000",
            caller_end_exclusive="0x401020",
            bridge=mixed_bridge,  # type: ignore[arg-type]
        )
        self.assertEqual(frozenset(), mixed_indices)
        self.assertEqual(
            {},
            retail_local_switch_targets(
                instructions,
                caller_start="0x401000",
                caller_end_exclusive="0x401020",
                bridge=mixed_bridge,  # type: ignore[arg-type]
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register storage eax",
        ):
            extract_invocation_contract(
                instructions,
                source="bn",
                caller_identity="symbol:caller",
                caller_start="0x401000",
                caller_end_exclusive="0x401020",
                indexes=self.indexes,
                local_control_flow_indices=mixed_indices,
            )

