    def test_candidate_local_switch_classification_requires_exact_coff_population(self) -> None:
        module = call_contract_verify_module
        lines = [
            "?SwitchBack@@YAXXZ PROC NEAR",
            "$Lcase0:",
            "  00010 c3 ret 0",
            "$Lcase1:",
            "  00020 c3 ret 0",
            "  00040 83 ff 04 cmp edi, 4",
            "  00043 77 1b ja SHORT $Ldefault",
            "  00045 ff 24 bd 00 00 00 00 jmp DWORD PTR $Ltable[edi*4]",
            "$Lcase2:",
            "  0004c c3 ret 0",
            "$Lcase3:",
            "  00050 c3 ret 0",
            "$Lcase4:",
            "  00054 c3 ret 0",
            "$Ldefault:",
            "  00060 c3 ret 0",
            "$Ltable:",
            "  00070 00 00 00 00 DD $Lcase0",
            "  00074 00 00 00 00 DD $Lcase1",
            "  00078 00 00 00 00 DD $Lcase2",
            "  0007c 00 00 00 00 DD $Lcase3",
            "  00080 00 00 00 00 DD $Lcase4",
            "?SwitchBack@@YAXXZ ENDP",
        ]
        instructions = tuple(parse_assembly("\n".join(lines), source="cod"))
        parsed = CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=frozenset(),
        )
        data = bytearray(0x84)
        data[0x10] = data[0x20] = data[0x4c] = 0xC3
        data[0x50] = data[0x54] = data[0x60] = 0xC3
        data[0x40:0x43] = bytes.fromhex("83 ff 04")
        data[0x43:0x45] = bytes.fromhex("77 1b")
        data[0x45:0x4c] = bytes.fromhex("ff 24 bd 00 00 00 00")
        names = ("$Lcase0", "$Lcase1", "$Lcase2", "$Lcase3", "$Lcase4")
        offsets = (0x10, 0x20, 0x4C, 0x50, 0x54)
        symbols = (
            CoffSymbol(0, "?SwitchBack@@YAXXZ", 0, 1, 0x20, 2, 0),
            CoffSymbol(1, "$Ltable", 0x70, 1, 0, 6, 0),
            *(CoffSymbol(index + 2, name, offset, 1, 0, 6, 0)
              for index, (name, offset) in enumerate(zip(names, offsets))),
        )
        relocations = (
            CoffRelocation(0x48, 1, module.IMAGE_REL_I386_DIR32, "$Ltable"),
            *(CoffRelocation(0x70 + index * 4, index + 2,
                            module.IMAGE_REL_I386_DIR32, name)
              for index, name in enumerate(names)),
        )
        mask = [False] * len(data)
        for start in (0x48, 0x70, 0x74, 0x78, 0x7C, 0x80):
            mask[start:start + 4] = [True] * 4
        body = module.CoffFunctionBytes(
            symbol="?SwitchBack@@YAXXZ", section_name=".text",
            section_index=1, start=0, end=len(data), natural_end=len(data),
            data=bytes(data), relocations=relocations,
            relocation_mask=tuple(mask), excluded_tail_relocation_count=0,
        )

        def coff(rows=relocations, current_symbols=symbols) -> CoffObject:
            section = CoffSection(
                index=1, name=".text", raw_data=bytes(data),
                relocation_offset=0, relocation_count=len(rows),
                characteristics=module.IMAGE_SCN_CNT_CODE,
            )
            return CoffObject(
                sections=(section,), symbols=tuple(current_symbols),
                symbols_by_index={row.index: row for row in current_symbols},
                relocations_by_section={1: tuple(rows)},
            )

        classify = module._candidate_exact_local_switch_classification_indices
        self.assertEqual(frozenset({4}), classify(lines, parsed, body, coff()))
        self.assertEqual(
            {4: (0, 1, 5, 6, 7, 8)},
            module._candidate_exact_local_switch_classification_targets(
                lines, parsed, body, coff()
            ),
        )
        self.assertEqual(
            [],
            extract_invocation_contract(
                instructions, source="cod", caller_identity="symbol:caller",
                caller_start="0x401000", caller_end_exclusive="0x401084",
                indexes=self.indexes,
                local_control_flow_indices=frozenset({4}),
            ),
        )
        negatives = {
            "missing-table-entry-relocation": relocations[:-1],
            "external-table-relocation": (
                replace(relocations[0], symbol_name="_external"),
                *relocations[1:],
            ),
            "wrong-slot-relocation": (
                relocations[0],
                replace(relocations[1], offset=0x71),
                *relocations[2:],
            ),
        }
        for label, rows in negatives.items():
            with self.subTest(label=label):
                self.assertEqual(
                    frozenset(),
                    classify(
                        lines,
                        parsed,
                        replace(body, relocations=tuple(rows)),
                        coff(rows),
                    ),
                )
        out_of_function = (
            *symbols[:2],
            replace(symbols[2], value=0x100),
            *symbols[3:],
        )
        self.assertEqual(
            frozenset(), classify(lines, parsed, body, coff(current_symbols=out_of_function))
        )
        true_call = list(instructions)
        true_call[4] = parse_assembly(
            "00045 ff d7 call edi", source="cod"
        )[0]
        self.assertEqual(
            frozenset(),
            classify(
                lines,
                CandidateAssembly(
                    instructions=tuple(true_call),
                    local_control_flow_indices=frozenset(),
                ),
                body,
                coff(),
            ),
        )

