    def test_reporter_switch_requires_exact_57_entry_coff_table(self) -> None:
        module = call_contract_verify_module
        selected = SimpleNamespace(
            address=module.ZSND_REPORT_A3D_ADDRESS,
            symbol=module.ZSND_REPORT_A3D_SYMBOL,
            symbol_regex=None,
            pipeline_class="authored",
            authored_order_role="authored-body",
            required_presence=True,
            full_order_gate=True,
        )
        target = SimpleNamespace(
            name=module.ZSND_REPORTER_TARGET_NAME,
            target_binary="recoil",
            manifest_path=str(module.ZSND_REPORTER_TARGET_MANIFEST),
            source_from=module.ZSND_REPORTER_SOURCE_PATH,
            check_translation_unit_function_order=True,
            description=(
                "The 57-entry .text switch table is attached compiler output"
            ),
            functions=(selected,),
            translation_unit_function_order=(),
        )
        compiled_entry = SimpleNamespace(
            source_from=module.ZSND_REPORTER_SOURCE_PATH,
            functions=(selected,),
        )
        document = MagicMock()
        document.collection.side_effect = lambda name: {
            "verification_targets": {
                module.ZSND_REPORTER_TARGET_ID: {
                    "binary": "recoil",
                    "kind": "vc5",
                    "name": module.ZSND_REPORTER_TARGET_NAME,
                    "registration": {
                        "manifest_path": (
                            module.ZSND_REPORTER_TARGET_MANIFEST.relative_to(
                                REPO_ROOT
                            ).as_posix()
                        ),
                        "source_from": module.ZSND_REPORTER_SOURCE_PATH,
                        "check_translation_unit_function_order": True,
                        "function_order_scope": "authored",
                        "function_addresses": [module.ZSND_REPORT_A3D_ADDRESS],
                    },
                }
            },
            "symbols": {
                "recoil:function:0x4a3ef0": {
                    "binary": "recoil",
                    "kind": "function",
                    "pipeline_class": "authored",
                    "address": module.ZSND_REPORT_A3D_ADDRESS,
                    "end_exclusive": "0x4a4330",
                    "extent_state": "known",
                    "size": 0x440,
                    "physical_block_id": "recoil:block:0x4a3ea0",
                }
            },
        }[name]
        self.assertTrue(
            module._zsnd_reporter_manifest_attached_switch_authority(
                document,
                target,
                module.ZSND_REPORT_A3D_ADDRESS,
                compiled_entry,
            )
        )
        with self.assertRaisesRegex(ValueError, "exact synchronized manifest"):
            module._zsnd_reporter_manifest_attached_switch_authority(
                document,
                target,
                module.ZSND_REPORT_A3D_ADDRESS,
                SimpleNamespace(
                    source_from="src/GameZRecoil/zSound/not_zsnd_error.cpp",
                    functions=(selected,),
                ),
            )

        section_start = 0x180
        section_index = 1
        section_end = (
            section_start + module.ZSND_REPORT_A3D_CANDIDATE_BODY_SIZE
        )
        table_offsets = tuple(
            module.ZSND_REPORT_A3D_SWITCH_TABLE_OFFSET + index * 4
            for index in range(module.ZSND_REPORT_A3D_SWITCH_ENTRY_COUNT)
        )
        absolute_table_offsets = tuple(
            section_start + offset for offset in table_offsets
        )
        body = bytearray(module.ZSND_REPORT_A3D_CANDIDATE_BODY_SIZE)
        body[
            module.ZSND_REPORT_A3D_SWITCH_DISPATCH_OFFSET:
            module.ZSND_REPORT_A3D_SWITCH_DISPATCH_OFFSET + 7
        ] = b"\xff\x24\x85\0\0\0\0"
        relocations = (
            CoffRelocation(
                section_start
                + module.ZSND_REPORT_A3D_SWITCH_DISPATCH_OFFSET
                + 3,
                1,
                0x06,
                "$L33356",
            ),
            *(
                CoffRelocation(
                    offset, index + 2, 0x06, f"$L{index + 1}"
                )
                for index, offset in enumerate(absolute_table_offsets)
            ),
        )
        caller_symbol = CoffSymbol(
            index=0,
            name=module.ZSND_REPORT_A3D_SYMBOL,
            value=section_start,
            section_number=section_index,
            type=0x20,
            storage_class=2,
            aux_count=0,
        )
        table_symbol = CoffSymbol(
            index=1,
            name="$L33356",
            value=section_start + module.ZSND_REPORT_A3D_SWITCH_TABLE_OFFSET,
            section_number=section_index,
            type=0,
            storage_class=6,
            aux_count=0,
        )
        case_symbols = tuple(
            replace(
                table_symbol,
                index=index + 2,
                name=f"$L{index + 1}",
                value=(
                    section_start
                    + module.ZSND_REPORT_A3D_SWITCH_TARGET_OFFSETS[index]
                ),
            )
            for index in range(module.ZSND_REPORT_A3D_SWITCH_ENTRY_COUNT)
        )

        def object_fixture(
            *,
            table: CoffSymbol = table_symbol,
            cases: tuple[CoffSymbol, ...] = case_symbols,
            rows: tuple[CoffRelocation, ...] = relocations,
            raw_body: bytes = bytes(body),
            extra_symbols: tuple[CoffSymbol, ...] = (),
        ) -> CoffObject:
            section = CoffSection(
                index=section_index,
                name=".text",
                raw_data=b"\x90" * section_start + raw_body,
                relocation_offset=0,
                relocation_count=len(rows),
                characteristics=module.IMAGE_SCN_CNT_CODE,
            )
            symbols = (
                caller_symbol,
                table,
                *cases,
                *extra_symbols,
            )
            return CoffObject(
                sections=(section,),
                symbols=symbols,
                symbols_by_index={symbol.index: symbol for symbol in symbols},
                relocations_by_section={section_index: rows},
            )

        parsed = CandidateAssembly(
            instructions=tuple(
                parse_assembly(
                    "\n".join(
                        (
                            "00026 ff 24 85 00 00 00 00 "
                            "jmp DWORD PTR $L33356[eax*4]",
                            *(
                                f"{offset:05x} c3 ret 0"
                                for offset in (
                                    module.ZSND_REPORT_A3D_SWITCH_TARGET_OFFSETS
                                )
                            ),
                        )
                    ),
                    source="cod",
                )
            ),
            local_control_flow_indices=frozenset({0}),
            local_control_flow_targets={
                0: tuple(
                    range(1, module.ZSND_REPORT_A3D_SWITCH_ENTRY_COUNT + 1)
                )
            },
        )
        coff_object = object_fixture()
        caller = coff_object.function_bytes(module.ZSND_REPORT_A3D_SYMBOL)
        self.assertEqual(section_start, caller.start)
        self.assertEqual(section_end, caller.end)
        self.assertFalse(hasattr(caller, "section_start"))
        module._require_zsnd_reporter_candidate_switch_coff(
            parsed, caller, coff_object
        )

        different_ordinal = replace(
            table_symbol, name="$L99123"
        )
        different_ordinal_parsed = replace(
            parsed,
            instructions=(
                parse_assembly(
                    "00026 ff 24 85 00 00 00 00 "
                    "jmp DWORD PTR $L99123[eax*4]",
                    source="cod",
                )[0],
                *parsed.instructions[1:],
            ),
        )
        different_ordinal_rows = (
            replace(relocations[0], symbol_name=different_ordinal.name),
            *relocations[1:],
        )
        different_ordinal_object = object_fixture(
            table=different_ordinal,
            rows=different_ordinal_rows,
        )
        module._require_zsnd_reporter_candidate_switch_coff(
            different_ordinal_parsed,
            different_ordinal_object.function_bytes(
                module.ZSND_REPORT_A3D_SYMBOL
            ),
            different_ordinal_object,
        )

        drifted_target_instructions = list(parsed.instructions)
        drifted_target_instructions[1] = replace(
            drifted_target_instructions[1],
            source_line="0002e c3 ret 0",
        )
        drifted_target_parsed = replace(
            parsed,
            instructions=tuple(drifted_target_instructions),
        )
        with self.assertRaisesRegex(ValueError, "COD/COFF dispatch"):
            module._require_zsnd_reporter_candidate_switch_coff(
                drifted_target_parsed,
                caller,
                coff_object,
            )

        historical_target_offsets = (
            0x02D, 0x037, 0x046, 0x055, 0x05F, 0x06E, 0x07D, 0x087,
            0x096, 0x0A5, 0x0AF, 0x0BE, 0x0CD, 0x0D7, 0x0E6, 0x0F5,
            0x0FF, 0x10E, 0x11D, 0x127, 0x136, 0x145, 0x14F, 0x15E,
            0x16D, 0x177, 0x186, 0x195, 0x19F, 0x1AE, 0x1BD, 0x1C7,
            0x1D6, 0x1E5, 0x1EF, 0x1FE, 0x20D, 0x217, 0x226, 0x235,
            0x23F, 0x24E, 0x25D, 0x267, 0x276, 0x285, 0x28F, 0x29E,
            0x2AA, 0x2B1, 0x2BD, 0x2C9, 0x2D0, 0x2DC, 0x2E8, 0x2EF,
            0x2FB,
        )
        historical_table_offset = 0x358
        historical_table_offsets = tuple(
            historical_table_offset + index * 4
            for index in range(module.ZSND_REPORT_A3D_SWITCH_ENTRY_COUNT)
        )
        historical_table = replace(
            table_symbol,
            value=section_start + historical_table_offset,
        )
        historical_cases = tuple(
            replace(
                case_symbols[index],
                value=section_start + historical_target_offsets[index],
            )
            for index in range(module.ZSND_REPORT_A3D_SWITCH_ENTRY_COUNT)
        )
        historical_rows = (
            replace(relocations[0], symbol_name=historical_table.name),
            *(
                replace(
                    relocations[index + 1],
                    offset=section_start + historical_table_offsets[index],
                )
                for index in range(module.ZSND_REPORT_A3D_SWITCH_ENTRY_COUNT)
            ),
        )
        historical_body = bytearray(0x440)
        historical_body[
            module.ZSND_REPORT_A3D_SWITCH_DISPATCH_OFFSET:
            module.ZSND_REPORT_A3D_SWITCH_DISPATCH_OFFSET + 7
        ] = b"\xff\x24\x85\0\0\0\0"
        historical_object = object_fixture(
            table=historical_table,
            cases=historical_cases,
            rows=historical_rows,
            raw_body=bytes(historical_body),
        )
        with self.assertRaisesRegex(ValueError, "COD/COFF dispatch"):
            module._require_zsnd_reporter_candidate_switch_coff(
                parsed,
                historical_object.function_bytes(
                    module.ZSND_REPORT_A3D_SYMBOL
                ),
                historical_object,
            )

        drifted_mask = list(caller.relocation_mask)
        drifted_mask[table_offsets[-1]] = False
        nonzero_addend = bytearray(caller.data)
        nonzero_addend[
            module.ZSND_REPORT_A3D_SWITCH_DISPATCH_OFFSET + 3
        ] = 1
        external_object = object_fixture(
            table=replace(
                table_symbol,
                section_number=0,
                storage_class=2,
            )
        )
        ambiguous_object = object_fixture(
            extra_symbols=(
                replace(table_symbol, index=100, name="$L33357"),
            )
        )
        wrong_offset_object = object_fixture(
            table=replace(table_symbol, value=table_symbol.value + 4)
        )
        wrong_section_object = object_fixture(
            table=replace(table_symbol, section_number=section_index + 1)
        )
        mismatched_cod_object = object_fixture(
            table=different_ordinal,
            rows=different_ordinal_rows,
        )
        relocation_type_object = object_fixture(
            rows=(replace(relocations[0], type=0x14), *relocations[1:])
        )
        nonzero_addend_object = object_fixture(raw_body=bytes(nonzero_addend))
        cases = {
            "external-target": (
                external_object.function_bytes(module.ZSND_REPORT_A3D_SYMBOL),
                external_object,
            ),
            "ambiguous-target": (
                ambiguous_object.function_bytes(module.ZSND_REPORT_A3D_SYMBOL),
                ambiguous_object,
            ),
            "wrong-offset": (
                wrong_offset_object.function_bytes(module.ZSND_REPORT_A3D_SYMBOL),
                wrong_offset_object,
            ),
            "wrong-section": (
                wrong_section_object.function_bytes(module.ZSND_REPORT_A3D_SYMBOL),
                wrong_section_object,
            ),
            "cod-symbol-join": (
                mismatched_cod_object.function_bytes(
                    module.ZSND_REPORT_A3D_SYMBOL
                ),
                mismatched_cod_object,
            ),
            "relocation-type": (
                relocation_type_object.function_bytes(
                    module.ZSND_REPORT_A3D_SYMBOL
                ),
                relocation_type_object,
            ),
            "addend": (
                nonzero_addend_object.function_bytes(
                    module.ZSND_REPORT_A3D_SYMBOL
                ),
                nonzero_addend_object,
            ),
            "mask": (
                replace(caller, relocation_mask=tuple(drifted_mask)),
                coff_object,
            ),
        }
        for label, (drifted, drifted_object) in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "COD/COFF dispatch"
            ):
                module._require_zsnd_reporter_candidate_switch_coff(
                    parsed, drifted, drifted_object
                )

    def test_candidate_branch_partitioned_tables_share_one_dominating_guard(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            cod_path = Path(temporary) / "SharedGuard.cod"
            cod_path.write_text(
                "\n".join(
                    [
                        "?SharedGuard@@YAXXZ PROC NEAR",
                        "  00000 83 f8 01 cmp eax, 1",
                        "  00003 77 18 ja $Ldefault",
                        "  00005 85 ff test edi, edi",
                        "  00007 75 0b jne $Lsecond",
                        "  00009 ff 24 85 00 00 00 00 "
                        "jmp DWORD PTR $Ltable1[eax*4]",
                        "$Lfirst0:",
                        "  00010 b0 01 mov al, 1",
                        "  00012 c3 ret 0",
                        "$Lfirst1:",
                        "  00013 e8 00 00 00 00 call ?Helper@@YAXXZ",
                        "  00018 c3 ret 0",
                        "$Lsecond:",
                        "  00019 ff 24 85 00 00 00 00 "
                        "jmp DWORD PTR $Ltable2[eax*4]",
                        "$Lsecond0:",
                        "  00020 c3 ret 0",
                        "$Lsecond1:",
                        "  00021 c3 ret 0",
                        "$Ldefault:",
                        "  00022 c3 ret 0",
                        "$Ltable1:",
                        "  00024 00 00 00 00 DD $Lfirst0",
                        "  00028 00 00 00 00 DD $Lfirst1",
                        "$Ltable2:",
                        "  0002c 00 00 00 00 DD $Lsecond0",
                        "  00030 00 00 00 00 DD $Lsecond1",
                        "?SharedGuard@@YAXXZ ENDP",
                    ]
                ),
                encoding="utf-8",
            )
            candidate = _extract_cod_proc_with_local_switches(
                cod_path,
                "?SharedGuard@@YAXXZ",
            )

        self.assertEqual(frozenset({4, 9}), candidate.local_control_flow_indices)
        self.assertEqual({4: (5, 7), 9: (10, 11)}, candidate.local_control_flow_targets)

    def test_candidate_shared_switch_guard_rejects_reaching_index_clobbers(
        self,
    ) -> None:
        variants = {
            "full": "  00019 33 c0 xor eax, eax",
            "partial": "  00019 b0 00 mov al, 0",
            "call": "  00019 e8 00 00 00 00 call ?Helper@@YAXXZ",
        }
        for label, clobber in variants.items():
            with self.subTest(label=label), tempfile.TemporaryDirectory() as temporary:
                cod_path = Path(temporary) / f"Clobber_{label}.cod"
                cod_path.write_text(
                    "\n".join(
                        [
                            f"?Clobber_{label}@@YAXXZ PROC NEAR",
                            "  00000 83 f8 01 cmp eax, 1",
                            "  00003 77 18 ja $Ldefault",
                            "  00005 85 ff test edi, edi",
                            "  00007 75 0b jne $Lsecond",
                            "  00009 ff 24 85 00 00 00 00 "
                            "jmp DWORD PTR $Ltable1[eax*4]",
                            "$Lfirst0:",
                            "  00010 c3 ret 0",
                            "$Lfirst1:",
                            "  00011 c3 ret 0",
                            "$Lsecond:",
                            clobber,
                            "  0001e ff 24 85 00 00 00 00 "
                            "jmp DWORD PTR $Ltable2[eax*4]",
                            "$Lsecond0:",
                            "  00025 c3 ret 0",
                            "$Lsecond1:",
                            "  00026 c3 ret 0",
                            "$Ldefault:",
                            "  00027 c3 ret 0",
                            "$Ltable1:",
                            "  00028 00 00 00 00 DD $Lfirst0",
                            "  0002c 00 00 00 00 DD $Lfirst1",
                            "$Ltable2:",
                            "  00030 00 00 00 00 DD $Lsecond0",
                            "  00034 00 00 00 00 DD $Lsecond1",
                            f"?Clobber_{label}@@YAXXZ ENDP",
                        ]
                    ),
                    encoding="utf-8",
                )
                candidate = _extract_cod_proc_with_local_switches(
                    cod_path,
                    f"?Clobber_{label}@@YAXXZ",
                )

            self.assertEqual(
                frozenset({4}),
                candidate.local_control_flow_indices,
            )

