    def test_exact_jump_table_edges_preserve_case_register_storage_provenance(
        self,
    ) -> None:
        indexes = replace(
            self.indexes,
            storage_by_name={"callback": "storage:callback"},
        )
        retail_instructions = parse_assembly(
            "\n".join(
                [
                    "00401000 83 f8 01 cmp eax, 1",
                    "00401003 77 1b ja 0x401020",
                    "00401005 ff 24 85 30 10 40 00 "
                    "jmp dword [eax*4+0x401030]",
                    "0040100c a1 00 00 50 00 mov eax, dword [0x500000]",
                    "00401011 ff 50 60 call dword [eax+0x60]",
                    "00401014 eb 0b jmp 0x401021",
                    "00401016 a1 00 00 50 00 mov eax, dword [0x500000]",
                    "0040101b ff 50 60 call dword [eax+0x60]",
                    "0040101e eb 01 jmp 0x401021",
                    "00401020 c3 ret",
                    "00401021 c3 ret",
                ]
            ),
            source="bn",
        )

        class HexdumpBridge:
            def hexdump(self, address: str, length: int) -> str:
                self.asserted = (address, length)
                raw = struct.pack("<2I", 0x40100C, 0x401016)
                return "401030  " + " ".join(f"{item:02x}" for item in raw)

        bridge = HexdumpBridge()
        retail_targets = retail_local_switch_targets(
            retail_instructions,
            caller_start="0x401000",
            caller_end_exclusive="0x401022",
            bridge=bridge,  # type: ignore[arg-type]
        )
        self.assertEqual(("0x401030", 8), bridge.asserted)
        self.assertEqual({2: (3, 6)}, retail_targets)
        retail_contract = extract_invocation_contract(
            retail_instructions,
            source="bn",
            caller_identity="symbol:caller",
            caller_start="0x401000",
            caller_end_exclusive="0x401022",
            indexes=indexes,
            local_control_flow_indices=frozenset(retail_targets),
            local_control_flow_targets=retail_targets,
        )

        with tempfile.TemporaryDirectory() as temporary:
            cod_path = Path(temporary) / "SwitchCalls.cod"
            cod_path.write_text(
                "\n".join(
                    [
                        "?SwitchCalls@@YAXXZ PROC NEAR",
                        "  00000 83 f8 01 cmp eax, 1",
                        "  00003 77 1b ja $Ldefault",
                        "  00005 ff 24 85 00 00 00 00 "
                        "jmp DWORD PTR $Ltable[eax*4]",
                        "$Lcase0:",
                        "  0000c a1 00 00 00 00 mov eax, DWORD PTR _callback",
                        "  00011 ff 50 60 call DWORD PTR [eax+96]",
                        "  00014 eb 0b jmp $Lend",
                        "$Lcase1:",
                        "  00016 a1 00 00 00 00 mov eax, DWORD PTR _callback",
                        "  0001b ff 50 60 call DWORD PTR [eax+96]",
                        "  0001e eb 01 jmp $Lend",
                        "$Ldefault:",
                        "  00020 c3 ret 0",
                        "$Lend:",
                        "  00021 c3 ret 0",
                        "$Ltable:",
                        "  00022 00 00 00 00 DD $Lcase0",
                        "  00026 00 00 00 00 DD $Lcase1",
                        "?SwitchCalls@@YAXXZ ENDP",
                    ]
                ),
                encoding="utf-8",
            )
            candidate = _extract_cod_proc_with_local_switches(
                cod_path,
                "?SwitchCalls@@YAXXZ",
            )

        self.assertEqual({2: (3, 6)}, candidate.local_control_flow_targets)
        candidate_contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x401000",
            caller_end_exclusive="0x401022",
            indexes=indexes,
            local_control_flow_indices=candidate.local_control_flow_indices,
            local_control_flow_targets=candidate.local_control_flow_targets,
        )
        expected_rows = [
            {
                "ordinal": ordinal,
                "form": "call",
                "dispatch": "indirect",
                "identity_kind": "callback",
                "target_identity": "",
                "storage_identity": "storage:callback",
                "slot_displacement": 0x60,
                "cleanup_bytes": None,
            }
            for ordinal in range(2)
        ]
        self.assertEqual(expected_rows, retail_contract)
        self.assertEqual(expected_rows, candidate_contract)

    def test_candidate_c_external_storage_undecoration_is_collision_checked(
        self,
    ) -> None:
        instruction = parse_assembly(
            "\n".join(
                [
                    "  00000 a1 00 00 00 00 mov eax, DWORD PTR _global",
                    "  00005 ff 50 60 call DWORD PTR [eax+96]",
                ]
            ),
            source="cod",
        )
        contract = extract_invocation_contract(
            instruction,
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x401000",
            caller_end_exclusive="0x401020",
            indexes=replace(
                self.indexes,
                storage_by_name={"global": "storage:global"},
            ),
        )
        self.assertEqual("storage:global", contract[0]["storage_identity"])

        with self.assertRaisesRegex(
            ValueError,
            "conflicting exact and x86 C external storage identities",
        ):
            extract_invocation_contract(
                instruction,
                source="cod",
                caller_identity="symbol:caller",
                caller_start="0x401000",
                caller_end_exclusive="0x401020",
                indexes=replace(
                    self.indexes,
                    storage_by_name={
                        "_global": "storage:decorated",
                        "global": "storage:authored",
                    },
                ),
            )

        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register storage eax",
        ):
            extract_invocation_contract(
                parse_assembly(
                    "\n".join(
                        [
                            "00401000 a1 00 00 00 00 "
                            "mov eax, dword [_global]",
                            "00401005 ff 50 60 call dword [eax+0x60]",
                        ]
                    ),
                    source="bn",
                ),
                source="bn",
                caller_identity="symbol:caller",
                caller_start="0x401000",
                caller_end_exclusive="0x401020",
                indexes=replace(
                    self.indexes,
                    storage_by_name={"global": "storage:global"},
                ),
            )

    def test_candidate_absolute_callback_root_preserves_explicit_zero_slot(
        self,
    ) -> None:
        indexes = replace(
            self.indexes,
            storage_by_name={
                "_callback": "storage:callback",
                "callback": "storage:callback",
            },
        )
        retail = extract_invocation_contract(
            parse_assembly(
                "00401000 ff 15 18 bc 56 00 "
                "call dword [_callback]",
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:caller",
            caller_start="0x401000",
            caller_end_exclusive="0x401010",
            indexes=indexes,
        )
        candidate = extract_invocation_contract(
            parse_assembly(
                "\n".join(
                    [
                        "  00000 ff 15 00 00 00 00 "
                        "call DWORD PTR _callback",
                        "  00006 ff 15 00 00 00 00 "
                        "call DWORD PTR _callback+4",
                    ]
                ),
                source="cod",
            ),
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x401000",
            caller_end_exclusive="0x401010",
            indexes=indexes,
        )
        bridged_candidate = extract_invocation_contract(
            parse_assembly(
                "  00000 ff 15 00 00 00 00 "
                "call DWORD PTR _callback",
                source="cod",
            ),
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x401000",
            caller_end_exclusive="0x401010",
            indexes=self.indexes,
            candidate_storage_bridges={
                "_callback": "storage:callback",
            },
        )
        self.assertEqual(retail[0], candidate[0])
        self.assertEqual(retail, bridged_candidate)
        self.assertEqual(0, candidate[0]["slot_displacement"])
        self.assertEqual(4, candidate[1]["slot_displacement"])

