    def test_local_switch_target_mapping_fails_closed_on_unreviewed_or_backward_edges(
        self,
    ) -> None:
        instructions = parse_assembly(
            "\n".join(
                [
                    "00401000 83 f8 00 cmp eax, 0",
                    "00401003 77 05 ja 0x40100a",
                    "00401005 ff 24 85 20 10 40 00 "
                    "jmp dword [eax*4+0x401020]",
                    "0040100c c3 ret",
                ]
            ),
            source="bn",
        )
        with self.assertRaisesRegex(
            ValueError,
            "require matching dispatch indices",
        ):
            extract_invocation_contract(
                instructions,
                source="bn",
                caller_identity="symbol:caller",
                caller_start="0x401000",
                caller_end_exclusive="0x401020",
                indexes=self.indexes,
                local_control_flow_targets={2: (3,)},
            )
        with self.assertRaisesRegex(ValueError, "invalid non-forward target"):
            extract_invocation_contract(
                instructions,
                source="bn",
                caller_identity="symbol:caller",
                caller_start="0x401000",
                caller_end_exclusive="0x401020",
                indexes=self.indexes,
                local_control_flow_indices=frozenset({2}),
                local_control_flow_targets={2: (1,)},
            )

