    def test_invocation_cod_index_reads_once_and_preserves_exact_proc_rows(
        self,
    ) -> None:
        ordinary_symbol = "?Ordinary@@YAXXZ"
        coff_symbol = (
            r"?Tick@Scope@?%D:\Recoil Project\RecoilRebuild"
            r"\src\tick.cpp123@@YAHXZ"
        )
        listing_symbol = coff_symbol.replace("@?%D:\\", "@?D:\\", 1)
        with tempfile.TemporaryDirectory() as temporary:
            cod_path = Path(temporary) / "indexed.cod"
            cod_path.write_text(
                "\n".join(
                    [
                        "_TEXT SEGMENT",
                        f"{ordinary_symbol} PROC NEAR",
                        "  00000\te8 00 00 00 00\t call\t ?First@@YAXXZ",
                        "  00005\tc3\t ret\t 0",
                        f"{ordinary_symbol} ENDP",
                        f"{listing_symbol} PROC NEAR ; {coff_symbol}, COMDAT",
                        "  00000\te8 00 00 00 00\t call\t ?Second@@YAXXZ",
                        "  00005\tc3\t ret\t 0",
                        f"{listing_symbol} ENDP ; {coff_symbol}",
                        "_TEXT ENDS",
                    ]
                ),
                encoding="utf-8",
            )
            expected_ordinary = call_contract_verify_module._extract_cod_proc_lines(
                cod_path, ordinary_symbol
            )
            expected_anonymous = call_contract_verify_module._extract_cod_proc_lines(
                cod_path, coff_symbol
            )
            invocation_index = (
                call_contract_verify_module._CodListingInvocationIndex()
            )
            token = call_contract_verify_module._ACTIVE_COD_LISTING_INDEX.set(
                invocation_index
            )
            try:
                self.assertEqual(
                    expected_ordinary,
                    call_contract_verify_module._extract_cod_proc_lines(
                        cod_path, ordinary_symbol
                    ),
                )
                self.assertEqual(
                    expected_anonymous,
                    call_contract_verify_module._extract_cod_proc_lines(
                        cod_path, coff_symbol
                    ),
                )
                # Repeated acquisition and full-text consumers share the same
                # immutable per-invocation file read and exact result rows.
                self.assertEqual(
                    expected_ordinary,
                    call_contract_verify_module._extract_cod_proc_lines(
                        cod_path, ordinary_symbol
                    ),
                )
                self.assertEqual(
                    expected_anonymous,
                    call_contract_verify_module._extract_cod_proc_lines(
                        cod_path, coff_symbol
                    ),
                )
                self.assertIn(
                    ordinary_symbol,
                    call_contract_verify_module._read_cod_text(
                        cod_path, errors="replace"
                    ),
                )
            finally:
                call_contract_verify_module._ACTIVE_COD_LISTING_INDEX.reset(token)
        metrics = invocation_index.metrics()
        self.assertEqual(1, metrics["file_read_count"])
        self.assertEqual(1, metrics["file_index_count"])
        self.assertEqual(4, metrics["procedure_lookup_count"])
        self.assertEqual(2, metrics["procedure_cache_hit_count"])

    def test_invocation_cod_index_keeps_anonymous_pairing_fail_closed(
        self,
    ) -> None:
        coff_symbol = (
            r"?Tick@Scope@?%D:\Recoil Project\RecoilRebuild"
            r"\src\tick.cpp123@@YAHXZ"
        )
        listing_symbol = coff_symbol.replace("@?%D:\\", "@?D:\\", 1)
        wrong_endp = listing_symbol.replace("tick.cpp123", "tick.cpp124", 1)
        with tempfile.TemporaryDirectory() as temporary:
            cod_path = Path(temporary) / "malformed-indexed.cod"
            cod_path.write_text(
                "\n".join(
                    [
                        f"{listing_symbol} PROC NEAR",
                        "  00000\tc3\t ret\t 0",
                        f"{wrong_endp} ENDP",
                    ]
                ),
                encoding="utf-8",
            )
            with self.assertRaises(ValueError) as uncached:
                call_contract_verify_module._extract_cod_proc_lines(
                    cod_path, coff_symbol
                )
            invocation_index = (
                call_contract_verify_module._CodListingInvocationIndex()
            )
            token = call_contract_verify_module._ACTIVE_COD_LISTING_INDEX.set(
                invocation_index
            )
            try:
                with self.assertRaises(ValueError) as indexed:
                    call_contract_verify_module._extract_cod_proc_lines(
                        cod_path, coff_symbol
                    )
                with self.assertRaises(ValueError) as indexed_cached:
                    call_contract_verify_module._extract_cod_proc_lines(
                        cod_path, coff_symbol
                    )
            finally:
                call_contract_verify_module._ACTIVE_COD_LISTING_INDEX.reset(token)
        self.assertEqual(str(uncached.exception), str(indexed.exception))
        self.assertEqual(str(indexed.exception), str(indexed_cached.exception))
        self.assertEqual(1, invocation_index.metrics()["file_read_count"])
        self.assertEqual(1, invocation_index.metrics()["procedure_cache_hit_count"])

    def test_json_mode_routes_compile_transcript_to_stderr_and_runs_once(self) -> None:
        typed_result = {
            "kind": "authored-call-contract-live-result",
            "contract_version": CALL_CONTRACT_CONTRACT_VERSION,
            "slice_id": "slice",
            "passed": False,
            "first_divergence": {"kind": "mismatch"},
            "candidate_expected_truth": False,
        }

        def fake_live_result(**_kwargs: object) -> dict:
            print("VC5 compile transcript")
            return typed_result

        stdout = io.StringIO()
        stderr = io.StringIO()
        with (
            patch(
                "_recoil.commands.call_contract_verify.ProgressDocument.load",
                return_value=object(),
            ),
            patch(
                "_recoil.commands.call_contract_verify.live_call_contract_result",
                side_effect=fake_live_result,
            ) as live_result,
            contextlib.redirect_stdout(stdout),
            contextlib.redirect_stderr(stderr),
        ):
            returncode = call_contract_main(
                ["--slice", "slice", "--build-root", "build/unit-call-contract", "--json"]
            )

        self.assertEqual(1, returncode)
        self.assertEqual(typed_result, json.loads(stdout.getvalue()))
        self.assertEqual("VC5 compile transcript\n", stderr.getvalue())
        live_result.assert_called_once()

    def test_json_summary_keeps_only_terminal_sized_typed_result(self) -> None:
        typed_result = {
            "kind": "authored-call-contract-live-result",
            "contract_version": CALL_CONTRACT_CONTRACT_VERSION,
            "slice_id": "slice",
            "body_count": 160,
            "passed": False,
            "first_divergence": {"kind": "mismatch", "ordinal": 3},
            "candidate_expected_truth": False,
            "caller_divergences": [{"kind": "mismatch", "ordinal": 3}],
            "expected_contracts": {"large": [object()]},
            "candidate_contracts": {"large": [object()]},
            "timings_ms": {"total": 1.0},
        }

        stdout = io.StringIO()
        with (
            patch(
                "_recoil.commands.call_contract_verify.ProgressDocument.load",
                return_value=object(),
            ),
            patch(
                "_recoil.commands.call_contract_verify.live_call_contract_result",
                return_value=typed_result,
            ) as live_result,
            contextlib.redirect_stdout(stdout),
        ):
            returncode = call_contract_main(
                [
                    "--slice", "slice",
                    "--build-root", "build/unit-call-contract-summary",
                    "--json", "--summary",
                ]
            )

        summary = json.loads(stdout.getvalue())
        self.assertEqual(1, returncode)
        self.assertEqual("slice", summary["slice_id"])
        self.assertEqual(160, summary["body_count"])
        self.assertEqual(1, summary["caller_divergence_count"])
        self.assertEqual(
            typed_result["caller_divergences"], summary["caller_divergences"]
        )
        self.assertEqual(
            typed_result["first_divergence"], summary["first_divergence"]
        )
        self.assertNotIn("expected_contracts", summary)
        self.assertNotIn("candidate_contracts", summary)
        live_result.assert_called_once()

