    def _prove_hud_message_stack_generated_destructor(
        self,
        fixture: dict,
        **overrides: object,
    ) -> bool:
        arguments = {
            "expected": fixture["expected"],
            "document": fixture["document"],
            "candidate": fixture["candidate"],
            "caller_identity": "symbol:recoil:function:0x40fbd0",
            "caller_start": "0x40fbd0",
            "caller_end_exclusive": "0x40fdd0",
            "indexes": fixture["indexes"],
            "bridge_names": fixture["bridge_names"],
            "bridge": fixture["bridge"],
            "invocation_row": fixture["invocation_row"],
        }
        arguments.update(overrides)
        with patch(
            "_recoil.commands.call_contract_verify.parse_source_trace_path",
            return_value=fixture["trace_document"],
        ):
            return _prove_hud_ui_message_stack_generated_destructor_bridge(
                fixture["candidate_name"],
                fixture["target_identity"],
                **arguments,
            )

    def test_hud_message_stack_generated_destructors_exact_two_identity_bridge(
        self,
    ) -> None:
        for label in ("top", "chat"):
            fixture = self._hud_message_stack_generated_destructor_fixture(
                label
            )
            with self.subTest(label=label), patch(
                "_recoil.commands.call_contract_verify.parse_source_trace_path",
                return_value=fixture["trace_document"],
            ):
                self.assertEqual(
                    {
                        fixture["candidate_name"]: fixture["target_identity"]
                    },
                    _compiler_destructor_provider_bridges(
                        fixture["expected"],
                        fixture["candidate"],
                        document=fixture["document"],
                        caller_identity="symbol:recoil:function:0x40fbd0",
                        caller_start="0x40fbd0",
                        caller_end_exclusive="0x40fdd0",
                        indexes=fixture["indexes"],
                        bridge_names=fixture["bridge_names"],
                        bridge=fixture["bridge"],
                    ),
                )
        fixture = self._hud_message_stack_generated_destructor_fixture(
            "chat"
        )
        active_package = (
            call_contract_verify_module.RetailCallerScopedProofPackage(
                caller_identity="symbol:recoil:function:0x40fbd0",
                caller_start="0x40fbd0",
                caller_end_exclusive="0x40fdd0",
                instruction_objects=tuple(
                    parse_assembly("0040fbd0 90 nop", source="bn")
                ),
            )
        )
        packaged_indexes = replace(
            fixture["indexes"],
            active_retail_caller_proof_package=active_package,
        )
        foreign_rows = parse_assembly(
            fixture["bridge"].assembly(
                str(fixture["spec"]["target_address"])
            ),
            source="bn",
        )
        with self.assertRaisesRegex(
            ValueError, "exact ordered caller instructions"
        ):
            extract_invocation_contract(
                foreign_rows,
                source="bn",
                caller_identity=fixture["target_identity"],
                caller_start=str(fixture["spec"]["target_address"]),
                caller_end_exclusive=str(fixture["spec"]["target_end"]),
                indexes=packaged_indexes,
            )
        self.assertTrue(
            self._prove_hud_message_stack_generated_destructor(
                fixture,
                indexes=packaged_indexes,
            )
        )
        fixture = self._hud_message_stack_generated_destructor_fixture("top")
        self.assertFalse(
            _prove_hud_ui_message_stack_generated_destructor_bridge(
                "??1OtherImplicit@@QAE@XZ",
                fixture["target_identity"],
                expected=fixture["expected"],
                document=fixture["document"],
                candidate=fixture["candidate"],
                caller_identity="symbol:recoil:function:0x40fbd0",
                caller_start="0x40fbd0",
                caller_end_exclusive="0x40fdd0",
                indexes=fixture["indexes"],
                bridge_names=fixture["bridge_names"],
                bridge=fixture["bridge"],
                invocation_row=fixture["invocation_row"],
            )
        )

    def test_hud_message_stack_generated_destructors_fail_closed_on_reviewed_edges(
        self,
    ) -> None:
        fixture = self._hud_message_stack_generated_destructor_fixture("chat")
        target_id = fixture["target_identity"].removeprefix("symbol:")
        drifted = deepcopy(fixture["document"].data)
        drifted["symbols"][target_id]["authored_order_role"] = "authored-body"
        with self.assertRaisesRegex(ValueError, "lifecycle target"):
            self._prove_hud_message_stack_generated_destructor(
                fixture,
                document=ProgressDocument(drifted),
            )

        drifted = deepcopy(fixture["document"].data)
        drifted["symbols"][target_id]["source_traceability"][
            "source_edges"
        ][0]["relation"] = "defines"
        with self.assertRaisesRegex(ValueError, "emits source-trace"):
            self._prove_hud_message_stack_generated_destructor(
                fixture,
                document=ProgressDocument(drifted),
            )

        prior_anchor = fixture["trace_document"].anchors[0]
        bad_trace = SimpleNamespace(
            anchors=(
                SimpleNamespace(
                    anchor_id=prior_anchor.anchor_id,
                    construct=SimpleNamespace(
                        kind="type",
                        name="WrongMessageStack",
                    ),
                    comment_style=prior_anchor.comment_style,
                    attachment_status=prior_anchor.attachment_status,
                ),
            ),
            artifacts=fixture["trace_document"].artifacts,
            findings=(),
        )
        prior_trace = fixture["trace_document"]
        fixture["trace_document"] = bad_trace
        with self.assertRaisesRegex(ValueError, "complete-type anchor"):
            self._prove_hud_message_stack_generated_destructor(fixture)
        fixture["trace_document"] = prior_trace

        indexes = replace(
            fixture["indexes"],
            storage_by_address={},
        )
        with self.assertRaisesRegex(ValueError, "typed global storage"):
            self._prove_hud_message_stack_generated_destructor(
                fixture,
                indexes=indexes,
            )

    def test_hud_message_stack_generated_destructors_fail_closed_on_candidate_shape(
        self,
    ) -> None:
        fixture = self._hud_message_stack_generated_destructor_fixture("top")
        caller = fixture["caller"]
        fake_core = "?DestructorCore@HudUiTopMessageStack@@QAEXXZ"
        fake_candidate = replace(
            fixture["candidate"],
            caller_definition=replace(
                caller,
                defined_external_functions=(
                    *caller.defined_external_functions,
                    fake_core,
                ),
            ),
        )
        with self.assertRaisesRegex(ValueError, "fake authored DestructorCore"):
            self._prove_hud_message_stack_generated_destructor(
                fixture,
                candidate=fake_candidate,
            )

        destructor = fixture["destructor"]
        wrong_count = bytearray(destructor.data)
        wrong_count[0x1E] = 3
        bad_definition = replace(destructor, data=bytes(wrong_count))
        with self.assertRaisesRegex(ValueError, "four exact HudUiPanel"):
            self._prove_hud_message_stack_generated_destructor(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    complete_destructor_definitions={
                        fixture["candidate_name"]: bad_definition
                    },
                ),
            )

        bad_xdata = replace(
            fixture["xdata"],
            relocations=(
                fixture["xdata"].relocations[0],
                replace(
                    fixture["xdata"].relocations[1],
                    symbol_name="$L99999",
                ),
            ),
        )
        bad_definition = replace(
            destructor,
            associated_sections=(fixture["funclet"], bad_xdata),
        )
        with self.assertRaisesRegex(ValueError, "local-symbol linkage"):
            self._prove_hud_message_stack_generated_destructor(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    complete_destructor_definitions={
                        fixture["candidate_name"]: bad_definition
                    },
                ),
            )

        bad_invocation = {
            **fixture["invocation_row"],
            "ordinal": fixture["invocation_row"]["ordinal"] - 1,
        }
        with self.assertRaisesRegex(ValueError, "retail target, ordinal"):
            self._prove_hud_message_stack_generated_destructor(
                fixture,
                invocation_row=bad_invocation,
            )

