    def test_hud_viewport_layout_vptr_rejects_authority_and_contract_drift(
        self,
    ) -> None:
        fixture = self._hud_viewport_layout_vptr_fixture()
        drifted = deepcopy(fixture["document"].data)
        drifted["symbols"]["recoil:function:0x40ff80"][
            "source_traceability"
        ]["source_edges"][0]["relation"] = "emits"
        with self.assertRaisesRegex(ValueError, "source edge"):
            self._hud_viewport_layout_vptr_bridges(
                fixture,
                document=ProgressDocument(drifted),
            )

        aliased_indexes = replace(
            fixture["indexes"],
            by_candidate_name={
                **fixture["indexes"].by_candidate_name,
                fixture["caller_symbol"].lower(): "symbol:wrong",
            },
        )
        with self.assertRaisesRegex(ValueError, "identity, extent, symbol"):
            self._hud_viewport_layout_vptr_bridges(
                fixture,
                indexes=aliased_indexes,
            )

        bad_expected = deepcopy(fixture["expected"])
        bad_expected[1]["slot_displacement"] = 0x1C
        with self.assertRaisesRegex(ValueError, "ordinal-1 retail"):
            _hud_ui_mgr_viewport_layout_candidate_vptr_bridges(
                bad_expected,
                fixture["candidate"],
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x40ff80",
                caller_end_exclusive="0x410140",
                indexes=fixture["indexes"],
            )

    def test_hud_viewport_layout_vptr_rejects_object_and_neighbor_drift(
        self,
    ) -> None:
        fixture = self._hud_viewport_layout_vptr_fixture()
        caller = fixture["caller"]
        bad_addend = bytearray(caller.data)
        struct.pack_into("<I", bad_addend, 0x130, 0x1C)
        with self.assertRaisesRegex(ValueError, "object body|relocation"):
            self._hud_viewport_layout_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    caller_definition=replace(
                        caller,
                        data=bytes(bad_addend),
                    ),
                ),
            )

        duplicate_call = tuple(
            parse_assembly(
                "  00140 ff 50 18 call dword [eax+24]",
                source="cod",
            )
        )[0]
        with self.assertRaisesRegex(ValueError, "one unique contiguous"):
            self._hud_viewport_layout_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=(
                        *fixture["candidate"].instructions,
                        duplicate_call,
                    ),
                ),
            )

        reordered = list(fixture["candidate"].instructions)
        reordered[2], reordered[3] = reordered[3], reordered[2]
        with self.assertRaisesRegex(ValueError, "reordered"):
            self._hud_viewport_layout_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=tuple(reordered),
                ),
            )

        self.assertEqual(
            ({}, {}),
            _hud_ui_mgr_viewport_layout_candidate_vptr_bridges(
                fixture["expected"],
                fixture["candidate"],
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x40ff81",
                caller_end_exclusive="0x410140",
                indexes=fixture["indexes"],
            ),
        )

