    def test_hud_enable_hud_vptr_rejects_coff_relocation_drift(
        self,
    ) -> None:
        fixture = self._hud_enable_hud_vptr_fixture()
        caller = fixture["caller"]

        bad_addend = bytearray(caller.data)
        struct.pack_into("<I", bad_addend, 0x01, 4)
        mutations = {
            "addend": replace(caller, data=bytes(bad_addend)),
            "symbol": replace(
                caller,
                relocations=(
                    replace(caller.relocations[0], symbol_name="?wrong@@3HA"),
                    *caller.relocations[1:],
                ),
            ),
            "type": replace(
                caller,
                relocations=(
                    replace(caller.relocations[0], type=0x14),
                    *caller.relocations[1:],
                ),
            ),
            "offset": replace(
                caller,
                relocations=(
                    replace(caller.relocations[0], offset=0x02),
                    *caller.relocations[1:],
                ),
            ),
            "missing": replace(
                caller,
                relocations=caller.relocations[1:],
            ),
            "duplicate": replace(
                caller,
                relocations=(
                    *caller.relocations,
                    caller.relocations[0],
                ),
            ),
            "mask": replace(
                caller,
                relocation_mask=(
                    False,
                    False,
                    *caller.relocation_mask[2:],
                ),
            ),
        }
        for label, definition in mutations.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "object body|DIR32 relocation|relocation mask",
            ):
                self._hud_enable_hud_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

    def test_hud_enable_hud_vptr_rejects_semantic_and_cfg_drift(
        self,
    ) -> None:
        fixture = self._hud_enable_hud_vptr_fixture()
        instructions = fixture["candidate"].instructions
        replacements = {
            "load-register": (
                0,
                "  00000 a1 00 00 00 00 mov edx, dword "
                f"{fixture['aggregate_symbol']}",
            ),
            "indexed-load": (
                0,
                "  00000 a1 00 00 00 00 mov eax, dword "
                f"[{fixture['aggregate_symbol']}+ecx]",
            ),
            "argument": (3, "  0000c 6a 00 push 0"),
            "receiver": (4, "  0000e b9 00 00 00 00 mov ecx, eax"),
            "slot": (5, "  00013 ff 50 08 call dword [eax+8]"),
        }
        for label, (index, line) in replacements.items():
            changed = list(instructions)
            changed[index] = tuple(parse_assembly(line, source="cod"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "instruction|unique",
            ):
                self._hud_enable_hud_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(changed),
                    ),
                )

        duplicate = tuple(
            parse_assembly(
                "  00020 a1 00 00 00 00 mov eax, dword "
                f"{fixture['aggregate_symbol']}",
                source="cod",
            )
        )[0]
        with self.assertRaisesRegex(ValueError, "one unique"):
            self._hud_enable_hud_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=(*instructions, duplicate),
                ),
            )

        with self.assertRaisesRegex(ValueError, "control-flow ambiguity"):
            self._hud_enable_hud_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({2}),
                    local_control_flow_targets={2: (5,)},
                ),
            )

        consumed = tuple(
            parse_assembly("  00016 8b f0 mov esi, eax", source="cod")
        )[0]
        with self.assertRaisesRegex(ValueError, "result consumption"):
            self._hud_enable_hud_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=(*instructions, consumed),
                ),
            )

