    def test_hud_disable_slot_base_exact_loop_vptr_provenance(
        self,
    ) -> None:
        fixture = self._hud_disable_slot_base_fixture()
        first_bridges = self._hud_disable_track_marker_bridge(fixture)
        second_bridges = self._hud_disable_slot_base_bridge(fixture)
        self.assertEqual({"0x20"}, set(first_bridges))
        self.assertEqual({"0x29"}, set(second_bridges))
        self.assertFalse(first_bridges.keys() & second_bridges.keys())
        bridges = {**first_bridges, **second_bridges}
        contract = extract_invocation_contract(
            fixture["candidate"].instructions[:13],
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410ed0",
            caller_end_exclusive="0x410fe0",
            indexes=fixture["indexes"],
            reviewed_loop_vptr_storage_bridges=bridges,
        )
        self.assertEqual(fixture["expected"], contract)

        for field, value in (
            ("ordinal", 3),
            (
                "storage_identity",
                "load(storage:recoil:data:0x4e5ed0+0xf44)",
            ),
            ("slot_displacement", 100),
            ("cleanup_bytes", 4),
        ):
            changed = deepcopy(fixture)
            changed["expected"][2][field] = value
            with self.subTest(field=field), self.assertRaisesRegex(
                ValueError,
                "immutable ordinal-2",
            ):
                self._hud_disable_slot_base_bridge(changed)

