    def test_hud_disable_slot_base_rejects_semantic_and_use_drift(
        self,
    ) -> None:
        fixture = self._hud_disable_slot_base_fixture()
        instructions = fixture["candidate"].instructions
        aggregate = fixture["aggregate_symbol"]
        replacements = {
            "loop-base": (
                4,
                (
                    "  0000d be 44 0f 00 00 mov esi, OFFSET FLAT:"
                    f"{aggregate}+3912"
                ),
            ),
            "base": (
                9,
                "  00023 8b 16 mov edx, dword [edi]",
            ),
            "register": (
                9,
                "  00023 8b 16 mov eax, dword [esi]",
            ),
            "receiver": (
                10,
                "  00025 8b ce mov ecx, edi",
            ),
            "argument": (11, "  00027 6a 00 push 1"),
            "slot": (
                12,
                "  00029 ff 52 60 call dword [edx+100]",
            ),
        }
        for label, (index, line) in replacements.items():
            changed = list(instructions)
            changed[index] = tuple(parse_assembly(line, source="cod"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "base|register|receiver|argument|slot|byte",
            ):
                self._hud_disable_slot_base_bridge(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(changed),
                    ),
                )

        with self.assertRaisesRegex(
            ValueError,
            "instruction offsets|missing|noncontiguous|loop tail",
        ):
            self._hud_disable_slot_base_bridge(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=(*instructions[:9], *instructions[10:]),
                ),
            )

        intervening = tuple(
            parse_assembly("  00024 90 nop", source="cod")
        )[0]
        with self.assertRaisesRegex(ValueError, "noncontiguous|loop tail"):
            self._hud_disable_slot_base_bridge(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=(
                        *instructions[:10],
                        intervening,
                        *instructions[10:],
                    ),
                ),
            )

        duplicate = tuple(
            parse_assembly(
                "\n".join(
                    (
                        "  0003a 8b 16 mov edx, dword [esi]",
                        "  0003c 8b ce mov ecx, esi",
                        "  0003e 6a 00 push 0",
                        "  00040 ff 52 60 call dword [edx+96]",
                    )
                ),
                source="cod",
            )
        )
        with self.assertRaisesRegex(ValueError, "one unique"):
            self._hud_disable_slot_base_bridge(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=(*instructions, *duplicate),
                ),
            )

        for label, line in (
            ("edx", "  00022 8b 16 mov edx, dword [esi]"),
            ("ecx", "  00022 8b ce mov ecx, esi"),
            ("esi", "  00022 8b f7 mov esi, edi"),
        ):
            extra_definition = tuple(
                parse_assembly(line, source="cod")
            )[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "reaching definitions|ESI",
            ):
                self._hud_disable_slot_base_bridge(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=(
                            *instructions[:9],
                            extra_definition,
                            *instructions[9:],
                        ),
                    ),
                )

        cleanup = tuple(
            parse_assembly(
                "  0002c 81 c6 c0 01 00 00 add esp, 4",
                source="cod",
            )
        )[0]
        changed = list(instructions)
