    def _hud_disable_set_enabled_fixture(self) -> dict:
        fixture = self._hud_disable_slot_base_fixture()
        caller = fixture["caller"]
        aggregate = fixture["aggregate_symbol"]
        body = bytearray(caller.data)
        body[0x3A:0x5D] = bytes.fromhex(
            "a1 00 00 00 00 "
            "6a 00 "
            "b9 00 00 00 00 "
            "c7 05 f8 0e 00 00 00 00 00 00 "
            "c7 05 00 47 00 00 00 00 00 00 "
            "ff 50 04"
        )
        body[0x5D:0x68] = bytes.fromhex(
            "8b 0d 18 00 00 00 8b 11 ff 52 14"
        )
        relocations = (
            *caller.relocations,
            CoffRelocation(0x3B, 1, 0x06, aggregate),
            CoffRelocation(0x42, 1, 0x06, aggregate),
            CoffRelocation(0x48, 1, 0x06, aggregate),
            CoffRelocation(0x52, 1, 0x06, aggregate),
            CoffRelocation(0x5F, 1, 0x06, aggregate),
        )
        mask = list(caller.relocation_mask)
        for relocation in relocations[len(caller.relocations) :]:
            mask[relocation.offset : relocation.offset + 4] = [True] * 4
        caller = replace(
            caller,
            data=bytes(body),
            relocations=relocations,
            relocation_mask=tuple(mask),
        )
        instructions = (
            *fixture["candidate"].instructions,
            *tuple(
                parse_assembly(
                    "\n".join(
                        (
                            (
                                "  0003a a1 00 00 00 00 mov eax, dword "
                                f"{aggregate}"
                            ),
                            "  0003f 6a 00 push 0",
                            (
                                "  00041 b9 00 00 00 00 mov ecx, "
                                f"OFFSET FLAT:{aggregate}"
                            ),
                            (
                                "  00046 c7 05 f8 0e 00 00 00 00 00 00 "
                                f"mov dword {aggregate}+3832, 0"
                            ),
                            (
                                "  00050 c7 05 00 47 00 00 00 00 00 00 "
                                f"mov dword {aggregate}+18176, 0"
                            ),
                            "  0005a ff 50 04 call dword [eax+4]",
                            (
                                "  0005d 8b 0d 18 00 00 00 mov ecx, dword "
                                f"{aggregate}+24"
                            ),
                            "  00063 8b 11 mov edx, dword [ecx]",
                            "  00065 ff 52 14 call dword [edx+20]",
                        )
                    ),
                    source="cod",
                )
            ),
        )
        fixture["caller"] = caller
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=instructions,
            caller_definition=caller,
        )
        fixture["expected"] = [
            *fixture["expected"],
            {
                "ordinal": 3,
                "form": "call",
                "dispatch": "indirect",
                "identity_kind": "callback",
                "target_identity": "",
                "storage_identity": "storage:recoil:data:0x4e5ed0",
                "slot_displacement": 4,
                "cleanup_bytes": None,
            },
        ]
        return fixture

