    def test_hud_disable_set_enabled_exact_delayed_callback(
        self,
    ) -> None:
        fixture = self._hud_disable_set_enabled_fixture()
        track_bridges = self._hud_disable_track_marker_bridge(fixture)
        slot_bridges = self._hud_disable_slot_base_bridge(fixture)
        absolute_bridges, callback_bridges = (
            self._hud_disable_set_enabled_bridges(fixture)
        )
        self.assertEqual({"0x3a"}, set(absolute_bridges))
        self.assertEqual({"0x5a"}, set(callback_bridges))
        self.assertFalse(track_bridges.keys() & slot_bridges.keys())
        self.assertFalse(callback_bridges.keys() & track_bridges.keys())
        self.assertFalse(callback_bridges.keys() & slot_bridges.keys())
        contracts = extract_invocation_contract(
            fixture["candidate"].instructions[:22],
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410ed0",
            caller_end_exclusive="0x410fe0",
            indexes=fixture["indexes"],
            reviewed_absolute_storage_load_bridges=absolute_bridges,
            reviewed_vptr_storage_bridges=callback_bridges,
            reviewed_loop_vptr_storage_bridges={
                **track_bridges,
                **slot_bridges,
            },
        )
        self.assertEqual(fixture["expected"], contracts)

        for field, value in (
            ("ordinal", 4),
            ("identity_kind", "virtual-slot"),
            (
                "storage_identity",
                "load(storage:recoil:data:0x4e5ed0)",
            ),
            ("slot_displacement", 8),
            ("cleanup_bytes", 4),
        ):
            changed = deepcopy(fixture)
            changed["expected"][3][field] = value
            with self.subTest(field=field), self.assertRaisesRegex(
                ValueError,
                "immutable ordinal-3",
            ):
                self._hud_disable_set_enabled_bridges(changed)

    def test_hud_disable_set_enabled_rejects_four_dir32_drift(
        self,
    ) -> None:
        fixture = self._hud_disable_set_enabled_fixture()
        caller = fixture["caller"]
        bounded_rows = caller.relocations[4:8]
        expected_addends = {
            0x3B: 0,
            0x42: 0,
            0x48: 0xEF8,
            0x52: 0x4700,
        }
        for row in bounded_rows:
            changed_body = bytearray(caller.data)
            struct.pack_into(
                "<I",
                changed_body,
                row.offset,
                expected_addends[row.offset] + 4,
            )
            with self.subTest(addend=row.offset), self.assertRaisesRegex(
                ValueError,
                "object body|DIR32 relocation",
            ):
                self._hud_disable_set_enabled_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=replace(
                            caller,
                            data=bytes(changed_body),
                        ),
                    ),
                )

        mutations = {
            "symbol": replace(
                caller,
                relocations=(
                    *caller.relocations[:4],
                    replace(bounded_rows[0], symbol_name="?wrong@@3HA"),
                    *caller.relocations[5:],
                ),
            ),
            "type": replace(
                caller,
                relocations=(
                    *caller.relocations[:5],
                    replace(bounded_rows[1], type=0x14),
                    *caller.relocations[6:],
                ),
            ),
            "offset": replace(
                caller,
                relocations=(
                    *caller.relocations[:6],
                    replace(bounded_rows[2], offset=0x49),
                    *caller.relocations[7:],
                ),
            ),
            "missing": replace(
                caller,
                relocations=(
                    *caller.relocations[:7],
                    *caller.relocations[8:],
                ),
            ),
            "duplicate": replace(
                caller,
                relocations=(*caller.relocations, bounded_rows[0]),
            ),
            "mask": replace(
                caller,
                relocation_mask=(
                    *caller.relocation_mask[:0x52],
                    False,
                    *caller.relocation_mask[0x53:],
                ),
            ),
        }
        for label, definition in mutations.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "DIR32 relocation|relocation mask",
            ):
                self._hud_disable_set_enabled_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

    def test_hud_disable_set_enabled_rejects_semantic_and_cfg_drift(
        self,
    ) -> None:
        fixture = self._hud_disable_set_enabled_fixture()
        instructions = fixture["candidate"].instructions
        aggregate = fixture["aggregate_symbol"]
        replacements = {
            "load-register": (
                16,
                (
                    "  0003a a1 00 00 00 00 mov edx, dword "
                    f"{aggregate}"
                ),
            ),
            "load-symbol": (
                16,
                "  0003a a1 00 00 00 00 mov eax, dword ?wrong@@3HA",
            ),
            "argument": (17, "  0003f 6a 00 push 1"),
            "receiver-register": (
                18,
                (
                    "  00041 b9 00 00 00 00 mov edx, "
                    f"OFFSET FLAT:{aggregate}"
                ),
            ),
            "receiver-symbol": (
                18,
                (
                    "  00041 b9 00 00 00 00 mov ecx, "
                    "OFFSET FLAT:?wrong@@3HA"
                ),
            ),
            "first-store": (
                19,
                (
                    "  00046 c7 05 f8 0e 00 00 00 00 00 00 "
                    f"mov dword {aggregate}+3836, 0"
                ),
            ),
            "first-store-value": (
                19,
                (
                    "  00046 c7 05 f8 0e 00 00 00 00 00 00 "
                    f"mov dword {aggregate}+3832, 1"
                ),
            ),
            "second-store": (
                20,
                (
                    "  00050 c7 05 00 47 00 00 00 00 00 00 "
                    f"mov dword {aggregate}+18180, 0"
                ),
            ),
            "slot": (
                21,
                "  0005a ff 50 04 call dword [eax+8]",
            ),
        }
        for label, (index, line) in replacements.items():
            changed = list(instructions)
            changed[index] = tuple(parse_assembly(line, source="cod"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "symbol|addend|register|receiver|argument|slot|store|byte",
            ):
                self._hud_disable_set_enabled_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(changed),
                    ),
                )

        with self.assertRaisesRegex(
            ValueError,
            "instruction offsets|missing|noncontiguous",
        ):
            self._hud_disable_set_enabled_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=(*instructions[:19], *instructions[20:]),
                ),
            )

        duplicate = tuple(
            parse_assembly(
                "\n".join(
                    (
                        (
                            "  00068 a1 00 00 00 00 mov eax, dword "
                            f"{aggregate}"
                        ),
                        "  0006d 6a 00 push 0",
                        (
                            "  0006f b9 00 00 00 00 mov ecx, "
                            f"OFFSET FLAT:{aggregate}"
                        ),
                        (
                            "  00074 c7 05 f8 0e 00 00 00 00 00 00 "
                            f"mov dword {aggregate}+3832, 0"
                        ),
                        (
                            "  0007e c7 05 00 47 00 00 00 00 00 00 "
                            f"mov dword {aggregate}+18176, 0"
                        ),
                        "  00088 ff 50 04 call dword [eax+4]",
                    )
                ),
                source="cod",
            )
        )
        with self.assertRaisesRegex(ValueError, "one unique"):
            self._hud_disable_set_enabled_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=(*instructions, *duplicate),
                ),
            )

        for label, line in (
            ("eax", "  00039 8b c3 mov eax, ebx"),
            ("ecx", "  00039 8b cb mov ecx, ebx"),
            ("stack", "  00039 53 push ebx"),
            (
                "store",
                (
                    "  00039 c7 05 00 00 00 00 00 00 00 00 "
                    f"mov dword {aggregate}, 0"
                ),
            ),
        ):
            extra = tuple(parse_assembly(line, source="cod"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "definitions|false argument|two independent",
            ):
                self._hud_disable_set_enabled_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=(
                            *instructions[:16],
                            extra,
                            *instructions[16:],
                        ),
                    ),
                )

        with self.assertRaisesRegex(ValueError, "control-flow ambiguity"):
            self._hud_disable_set_enabled_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({18}),
                    local_control_flow_targets={18: (21,)},
                ),
            )

        cleanup = tuple(
            parse_assembly(
                "  0005d 8b 0d 18 00 00 00 add esp, 4",
                source="cod",
            )
        )[0]
        changed = list(instructions)
        changed[22] = cleanup
        with self.assertRaisesRegex(ValueError, "no caller cleanup"):
            self._hud_disable_set_enabled_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=tuple(changed),
                ),
            )

        consumed = tuple(
            parse_assembly(
                "  0005d 8b 0d 18 00 00 00 mov ecx, eax",
                source="cod",
            )
        )[0]
        changed = list(instructions)
        changed[22] = consumed
        with self.assertRaisesRegex(ValueError, "result consumption"):
            self._hud_disable_set_enabled_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=tuple(changed),
                ),
            )

