    def _hud_disable_visibility_cluster_bridges(
        self,
        fixture: dict,
        **overrides: object,
    ) -> tuple[dict, dict, dict, dict]:
        arguments = {
            "candidate": fixture["candidate"],
            "document": fixture["document"],
            "caller_identity": fixture["caller_identity"],
            "caller_start": "0x410ed0",
            "caller_end_exclusive": "0x410fe0",
            "indexes": fixture["indexes"],
        }
        arguments.update(overrides)
        return _hud_ui_mgr_disable_visibility_cluster_candidate_bridges(
            fixture["expected"],
            **arguments,
        )

    def test_hud_disable_visibility_cluster_exact_contract(self) -> None:
        fixture = self._hud_disable_visibility_cluster_fixture()
        static, absolute, vptr, member = (
            self._hud_disable_visibility_cluster_bridges(fixture)
        )
        self.assertEqual(
            {
                f"{fixture['aggregate_symbol']}+2420",
                f"{fixture['aggregate_symbol']}+2084",
                f"{fixture['aggregate_symbol']}+2088",
                f"{fixture['aggregate_symbol']}+18308",
            },
            set(static),
        )
        self.assertEqual({"0x68", "0x84", "0x93", "0xbd"}, set(absolute))
        self.assertEqual({"0x74", "0x90", "0xa0", "0xc9"}, set(vptr))
        self.assertEqual({"0x7f", "0xab", "0xb8", "0xfb"}, set(member))

        track = self._hud_disable_track_marker_bridge(fixture)
        slot = self._hud_disable_slot_base_bridge(fixture)
        base_absolute, callback = self._hud_disable_set_enabled_bridges(
            fixture
        )
        current_static, current_member = (
            self._hud_disable_current_layout_bridges(fixture)
        )
        contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410ed0",
            caller_end_exclusive="0x410fe0",
            indexes=fixture["indexes"],
            reviewed_static_storage_reference_bridges={
                **current_static,
                **static,
            },
            reviewed_absolute_storage_load_bridges={
                **base_absolute,
                **absolute,
            },
            reviewed_member_vptr_storage_bridges={
                **current_member,
                **member,
            },
            reviewed_vptr_storage_bridges={**callback, **vptr},
            reviewed_loop_vptr_storage_bridges={**track, **slot},
        )
        self.assertEqual(fixture["expected"], contract)

        for field, value in (
            ("ordinal", 16),
            ("identity_kind", "callback"),
            ("storage_identity", "load(storage:recoil:data:0x4e5ed0)"),
            ("slot_displacement", 100),
            ("cleanup_bytes", 4),
        ):
            changed = deepcopy(fixture)
            changed["expected"][5][field] = value
            with self.subTest(field=field), self.assertRaisesRegex(
                ValueError,
                "immutable ordinal-5-through-15",
            ):
                self._hud_disable_visibility_cluster_bridges(changed)

    def test_hud_disable_visibility_cluster_rejects_stale_reset_frame_fastcall_profile(
        self,
    ) -> None:
        fixture = self._hud_disable_visibility_cluster_fixture()
        accepted_name = fixture["direct_rows"][1][0]
        stale_name = "?SpanOcclusionResetFrame@zRndr@@YIXXZ"
        self.assertEqual(
            "?SpanOcclusionResetFrame@zRndr@@YAXXZ",
            accepted_name,
        )

        caller = fixture["caller"]
        changed_caller = replace(
            caller,
            relocations=tuple(
                replace(row, symbol_name=stale_name)
                if row.offset == 0xE0
                else row
                for row in caller.relocations
            ),
            undefined_external_functions=tuple(
                stale_name if row == accepted_name else row
                for row in caller.undefined_external_functions
            ),
        )
        instructions = list(fixture["candidate"].instructions)
        offsets = (
            call_contract_verify_module
            ._candidate_complete_instruction_offsets(fixture["candidate"])
        )
        instructions[offsets.index(0xDF)] = parse_assembly(
            f"  000df e8 00 00 00 00 call {stale_name}",
            source="cod",
        )[0]
        stale_candidate = replace(
            fixture["candidate"],
            instructions=tuple(instructions),
            caller_definition=changed_caller,
        )
        stale_indexes = replace(
            fixture["indexes"],
            by_candidate_name={
                **fixture["indexes"].by_candidate_name,
                stale_name: "symbol:recoil:function:0x490600",
            },
        )
        with self.assertRaisesRegex(ValueError, "COFF relocations"):
            self._hud_disable_visibility_cluster_bridges(
                fixture,
                candidate=stale_candidate,
                indexes=stale_indexes,
            )

        duplicate = replace(
            caller,
            undefined_external_functions=(
                *caller.undefined_external_functions,
                accepted_name,
            ),
        )
        with self.assertRaisesRegex(ValueError, "direct-call identity"):
            self._hud_disable_visibility_cluster_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    caller_definition=duplicate,
                ),
            )

    def test_hud_disable_visibility_cluster_rejects_object_and_authority_drift(
        self,
    ) -> None:
        fixture = self._hud_disable_visibility_cluster_fixture()
        caller = fixture["caller"]
        bad_body = bytearray(caller.data)
        bad_body[0xC9] = 0x90
        mutations = {
            "body": replace(caller, data=bytes(bad_body)),
            "relocation": replace(
                caller,
                relocations=(
                    *caller.relocations[:-1],
                    replace(caller.relocations[-1], type=0x14),
                ),
            ),
            "extra": replace(
                caller,
                relocations=(*caller.relocations, caller.relocations[-1]),
            ),
            "mask": replace(
                caller,
                relocation_mask=(
                    *caller.relocation_mask[:0xF5],
                    False,
                    *caller.relocation_mask[0xF6:],
                ),
            ),
        }
        for label, definition in mutations.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "object body|COFF relocations",
            ):
                self._hud_disable_visibility_cluster_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

        changed = deepcopy(fixture)
        changed["document"].data["symbols"][
            "recoil:data:0x4ea654"
        ]["extent_state"] = "known"
        with self.assertRaisesRegex(ValueError, "timer-panel"):
            self._hud_disable_visibility_cluster_bridges(changed)

        name, address, identity = fixture["direct_rows"][0]
        with self.assertRaisesRegex(ValueError, "direct-call identity"):
            self._hud_disable_visibility_cluster_bridges(
                fixture,
                indexes=replace(
                    fixture["indexes"],
                    by_candidate_name={
                        **fixture["indexes"].by_candidate_name,
                        name: "symbol:wrong",
                    },
                ),
            )

    def test_hud_disable_visibility_cluster_rejects_semantic_cfg_drift(
        self,
    ) -> None:
        fixture = self._hud_disable_visibility_cluster_fixture()
        instructions = list(fixture["candidate"].instructions)
        instructions[28] = tuple(
            parse_assembly(
                "  00074 ff 50 60 call dword [eax+100]",
                source="cod",
            )
        )[0]
        with self.assertRaisesRegex(
            ValueError,
            "candidate instructions|semantic drift",
        ):
            self._hud_disable_visibility_cluster_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=tuple(instructions),
                ),
            )

        with self.assertRaisesRegex(ValueError, "alternate CFG"):
            self._hud_disable_visibility_cluster_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({56}),
                    local_control_flow_targets={56: (57,)},
                ),
            )

