    def test_hud_switch_active_dialog_exact_current_layout_contract(self) -> None:
        fixture = self._hud_switch_active_dialog_fixture()
        static, vptr = self._hud_switch_active_dialog_bridges(fixture)
        self.assertEqual({f"{fixture['aggregate_symbol']}+24"}, set(static))
        self.assertEqual({"0x2d"}, set(vptr))
        retail_contract = extract_invocation_contract(
            fixture["retail"],
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x413660",
            caller_end_exclusive="0x4136b0",
            indexes=fixture["indexes"],
            bridge_names={
                "HudUiMgr::DisableHud": SimpleNamespace(address="0x410ed0"),
                "HudUiMgr::EnableHud": SimpleNamespace(address="0x410e90"),
            },
        )
        candidate_contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x413660",
            caller_end_exclusive="0x4136b0",
            indexes=fixture["indexes"],
            reviewed_static_storage_reference_bridges=static,
            reviewed_vptr_storage_bridges=vptr,
            local_control_flow_indices=(
                fixture["candidate"].local_control_flow_indices
            ),
            local_control_flow_targets=(
                fixture["candidate"].local_control_flow_targets
            ),
        )
        self.assertEqual(fixture["expected"], retail_contract)
        self.assertEqual(retail_contract, candidate_contract)

        changed = deepcopy(fixture)
        changed["expected"][1]["slot_displacement"] = 0x0C
        with self.assertRaisesRegex(ValueError, "immutable four-call"):
            self._hud_switch_active_dialog_bridges(changed)

