    def test_hud_switch_active_dialog_rejects_retail_topology_drift(self) -> None:
        fixture = self._hud_switch_active_dialog_fixture()
        retail = fixture["retail"]
        mutations = {
            "storage": (
                *retail[:10],
                tuple(parse_assembly(
                    "00413680 8b 0d ec 5e 4e 00 mov ecx, dword [0x4e5eec]",
                    source="bn",
                ))[0],
                *retail[11:],
            ),
            "argument": (
                *retail[:14],
                tuple(parse_assembly(
                    "0041368c 6a 01 push 0x1", source="bn"
                ))[0],
                *retail[15:],
            ),
            "slot": (
                *retail[:15],
                tuple(parse_assembly(
                    "0041368e ff 50 0c call dword [eax+0xc]", source="bn"
                ))[0],
                *retail[16:],
            ),
            "topology": retail[:-1],
        }
        for label, instructions in mutations.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "immutable retail",
            ):
                self._hud_switch_active_dialog_bridges(
                    fixture,
                    retail_instructions=instructions,
                )

    def test_hud_switch_active_dialog_rejects_candidate_provenance_drift(
        self,
    ) -> None:
        fixture = self._hud_switch_active_dialog_fixture()
        caller = fixture["caller"]
        relocation = caller.relocations[3]
        bad_addend = bytearray(caller.data)
        struct.pack_into("<I", bad_addend, 0x21, 0x1C)
        definitions = {
            "body": replace(caller, data=bytes(bad_addend)),
            "symbol": replace(
                caller,
                relocations=(
                    *caller.relocations[:3],
                    replace(relocation, symbol_name="?wrong@@3HA"),
                    *caller.relocations[4:],
                ),
            ),
            "type": replace(
                caller,
                relocations=(
                    *caller.relocations[:3],
                    replace(relocation, type=0x14),
                    *caller.relocations[4:],
                ),
            ),
            "missing": replace(
                caller,
                relocations=caller.relocations[:3] + caller.relocations[4:],
            ),
            "mask": replace(
                caller,
                relocation_mask=(
                    *caller.relocation_mask[:0x21],
                    False,
                    *caller.relocation_mask[0x22:],
                ),
            ),
        }
        for label, definition in definitions.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "body|external population|relocation|mask",
            ):
                self._hud_switch_active_dialog_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

        instructions = fixture["candidate"].instructions
        for label, index, line in (
            ("guard", 10, "00025 85 c9 test edx, edx"),
            ("argument", 13, "0002b 6a 01 push 1"),
            ("receiver", 12, "00029 8b 01 mov eax, dword [edx]"),
            ("slot", 14, "0002d ff 50 0c call dword [eax+0xc]"),
        ):
            changed = list(instructions)
            changed[index] = tuple(parse_assembly(line, source="cod"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "candidate storage|null guard|SetActive|receiver|slot",
            ):
                self._hud_switch_active_dialog_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(changed),
                    ),
                )
        with self.assertRaisesRegex(ValueError, "topology drift"):
            self._hud_switch_active_dialog_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({11}),
                    local_control_flow_targets={11: (15,)},
                ),
            )

