    def test_hud_set_float_timer_visible_resolves_without_population_normalization(
        self,
    ) -> None:
        fixture = self._hud_set_float_timer_visible_fixture()
        static, vptr = self._hud_set_float_timer_visible_bridges(fixture)
        self.assertEqual({f"{fixture['aggregate_symbol']}+18312"}, set(static))
        self.assertEqual({"0xe", "0x16"}, set(vptr))
        retail_contract = extract_invocation_contract(
            fixture["retail"],
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x413770",
            caller_end_exclusive="0x4137a0",
            indexes=fixture["indexes"],
            bridge_names={
                "HudUiMgr::TriggerCurrentLayoutOnActivated": (
                    SimpleNamespace(address="0x413630")
                ),
            },
        )
        candidate_contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x413770",
            caller_end_exclusive="0x4137a0",
            indexes=fixture["indexes"],
            reviewed_static_storage_reference_bridges=static,
            reviewed_vptr_storage_bridges=vptr,
        )
        self.assertEqual(fixture["expected"], retail_contract)
        self.assertEqual(3, len(candidate_contract))
        comparison = compare_call_contracts(retail_contract, candidate_contract)
        self.assertFalse(comparison["passed"])
        self.assertEqual(
            {
                "ordinal": 2,
                "expected": retail_contract[2],
                "candidate": candidate_contract[2],
                "kind": "mismatch",
            },
            comparison["first_divergence"],
        )

        changed = deepcopy(fixture)
        changed["expected"][0]["slot_displacement"] = 0x64
        with self.assertRaisesRegex(ValueError, "immutable two-path"):
            self._hud_set_float_timer_visible_bridges(changed)

