    def test_hud_set_aux_overlay_visible_proves_exact_two_call_population(
        self,
    ) -> None:
        fixture = self._hud_set_aux_overlay_visible_fixture()
        static, vptr = self._hud_set_aux_overlay_visible_bridges(fixture)
        self.assertEqual({f"{fixture['aggregate_symbol']}+3808"}, set(static))
        self.assertEqual({"0xe", "0x16"}, set(vptr))
        self.assertEqual("eax", vptr["0xe"].register)
        self.assertEqual("edx", vptr["0x16"].register)
        retail_contract = extract_invocation_contract(
            fixture["retail"],
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x4137a0",
            caller_end_exclusive="0x4137c0",
            indexes=fixture["indexes"],
        )
        candidate_contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x4137a0",
            caller_end_exclusive="0x4137c0",
            indexes=fixture["indexes"],
            reviewed_static_storage_reference_bridges=static,
            reviewed_vptr_storage_bridges=vptr,
        )
        self.assertEqual(fixture["expected"], retail_contract)
        self.assertEqual(fixture["expected"], candidate_contract)
        self.assertEqual(2, len(candidate_contract))
        comparison = compare_call_contracts(retail_contract, candidate_contract)
        self.assertTrue(comparison["passed"])
        self.assertIsNone(comparison["first_divergence"])

