    def test_hud_apply_text_line_proves_six_independent_callsite_units(self) -> None:
        fixture = self._hud_apply_text_line_fixture()
        retail_vptr = self._hud_apply_text_line_retail(fixture)
        static, candidate_vptr = self._hud_apply_text_line_candidate(fixture)
        self.assertEqual(
            {"0x41381a", "0x413830", "0x413857", "0x41388a", "0x41389f", "0x4138c1"},
            set(retail_vptr),
        )
        self.assertEqual({"0x24", "0x30", "0x40", "0x59", "0x65", "0x72"}, set(candidate_vptr))
        self.assertEqual({f"{fixture['aggregate_symbol']}+3808"}, set(static))
        retail_contract = extract_invocation_contract(
            fixture["retail"],
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x4137f0",
            caller_end_exclusive="0x4138d0",
            indexes=fixture["indexes"],
            reviewed_loop_vptr_storage_bridges=retail_vptr,
        )
        candidate_contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x4137f0",
            caller_end_exclusive="0x4138d0",
            indexes=fixture["indexes"],
            reviewed_static_storage_reference_bridges=static,
            reviewed_loop_vptr_storage_bridges=candidate_vptr,
        )
        self.assertEqual(fixture["expected"], retail_contract)
        self.assertEqual(fixture["expected"], candidate_contract)
        self.assertTrue(compare_call_contracts(retail_contract, candidate_contract)["passed"])

    def test_hud_apply_text_line_rejects_authority_and_expected_drift(self) -> None:
        fixture = self._hud_apply_text_line_fixture()
        with self.assertRaisesRegex(ValueError, "caller identity"):
            self._hud_apply_text_line_retail(
                fixture, caller_end_exclusive="0x4138e0"
            )
        data = deepcopy(fixture["document"].data)
        data["symbols"]["recoil:function:0x4137f0"]["source_traceability"][
            "source_edges"
        ][0]["anchor_id"] = "recoil:anchor:wrong"
        with self.assertRaisesRegex(ValueError, "resolved source edge"):
            self._hud_apply_text_line_retail(
                fixture, document=ProgressDocument(data)
            )
        data = deepcopy(fixture["document"].data)
        data["verification_targets"][
            "recoil:functional-target:hud_ui_aux_overlay_apply_text_line_op"
        ]["registration"]["manifest_path"] = "wrong.json"
        with self.assertRaisesRegex(ValueError, "functional verification-target"):
            self._hud_apply_text_line_candidate(
                fixture, document=ProgressDocument(data)
            )
        with self.assertRaisesRegex(ValueError, "container authority"):
            self._hud_apply_text_line_candidate(
                fixture,
                indexes=replace(fixture["indexes"], storage_containers=()),
            )
        changed = deepcopy(fixture)
        changed["expected"][0]["slot_displacement"] = 0x70
        with self.assertRaisesRegex(ValueError, "immutable six-call"):
            self._hud_apply_text_line_candidate(changed)

    def test_hud_apply_text_line_rejects_retail_edx_and_topology_drift(self) -> None:
        fixture = self._hud_apply_text_line_fixture()
        retail = fixture["retail"]
        mutations = {
            "first-edx-definition": (10, "0041380c 8b 54 31 24 mov edx, dword [ecx+esi+0x24]"),
            "slot": (15, "0041381a ff 52 70 call dword [edx+0x70]"),
            "cleanup": (17, "00413823 83 c4 04 add esp, 0x4"),
            "branch": (2, "004137f4 75 40 jne 0x413836"),
        }
        for label, (index, line) in mutations.items():
            changed = list(retail)
            changed[index] = tuple(parse_assembly(line, source="bn"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "immutable retail"
            ):
                self._hud_apply_text_line_retail(
                    fixture, retail_instructions=tuple(changed)
                )
        with self.assertRaisesRegex(ValueError, "immutable retail"):
            self._hud_apply_text_line_retail(
                fixture, retail_instructions=retail[:-3]
            )

    def test_hud_apply_text_line_rejects_candidate_body_and_topology_drift(self) -> None:
        fixture = self._hud_apply_text_line_fixture()
        caller = fixture["caller"]
        relocation = caller.relocations[0]
        bad_addend = bytearray(caller.data)
        struct.pack_into("<I", bad_addend, 0x12, 0x0EE4)
        bad_padding = bytearray(caller.data)
        bad_padding[-1] = 0xCC
        definitions = {
            "addend": replace(caller, data=bytes(bad_addend)),
            "padding": replace(caller, data=bytes(bad_padding)),
            "symbol": replace(caller, relocations=(replace(relocation, symbol_name="?wrong@@3HA"),)),
            "type": replace(caller, relocations=(replace(relocation, type=0x14),)),
            "missing": replace(caller, relocations=()),
            "mask": replace(caller, relocation_mask=(*caller.relocation_mask[:0x12], False, *caller.relocation_mask[0x13:])),
            "external": replace(caller, undefined_external_data=()),
        }
        for label, definition in definitions.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "complete candidate body|COFF|relocation mask|padding|external"
            ):
                self._hud_apply_text_line_candidate(
                    fixture,
                    candidate=replace(fixture["candidate"], caller_definition=definition),
                )
        instructions = fixture["candidate"].instructions
        for label, index, line in (
            ("index", 6, "0000e 8d 14 c1 lea edx, [ecx+eax*8]"),
            ("receiver", 11, "00020 8b 0f mov ecx, dword [edi]"),
            ("slot", 14, "00024 ff 51 70 call dword [ecx+112]"),
            ("cleanup", 16, "00029 83 c4 04 add esp, 4"),
            ("branch", 9, "0001a 75 1a jne $L84939"),
        ):
            changed = list(instructions)
