    def test_hud_enable_stacks_proves_exact_four_call_unit(self) -> None:
        fixture = self._hud_enable_stacks_fixture()
        retail_vptr = self._hud_enable_stacks_retail(fixture)
        candidate_vptr = self._hud_enable_stacks_candidate(fixture)
        self.assertEqual({"0x413925", "0x41393d"}, set(retail_vptr))
        self.assertEqual({"0x15", "0x2d"}, set(candidate_vptr))
        retail_contract = extract_invocation_contract(
            fixture["retail"],
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x413910",
            caller_end_exclusive="0x413950",
            indexes=fixture["indexes"],
            bridge_names={
                "HudUiTextStack4::Clear": SimpleNamespace(
                    address="0x4bd2a0"
                )
            },
            reviewed_loop_vptr_storage_bridges=retail_vptr,
        )
        candidate_contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x413910",
            caller_end_exclusive="0x413950",
            indexes=fixture["indexes"],
            reviewed_loop_vptr_storage_bridges=candidate_vptr,
        )
        self.assertEqual(fixture["expected"], retail_contract)
        self.assertEqual(fixture["expected"], candidate_contract)
        self.assertTrue(compare_call_contracts(retail_contract, candidate_contract)["passed"])

    def test_hud_enable_stacks_rejects_authority_drift(self) -> None:
        fixture = self._hud_enable_stacks_fixture()
        with self.assertRaisesRegex(ValueError, "caller identity"):
            self._hud_enable_stacks_retail(
                fixture, caller_end_exclusive="0x413960"
            )
        data = deepcopy(fixture["document"].data)
        data["symbols"]["recoil:function:0x413910"]["source_traceability"][
            "source_edges"
        ][0]["anchor_id"] = "recoil:anchor:wrong"
        with self.assertRaisesRegex(ValueError, "resolved source edge"):
            self._hud_enable_stacks_candidate(
                fixture, document=ProgressDocument(data)
            )
        data = deepcopy(fixture["document"].data)
        data["verification_targets"][
            "recoil:functional-target:zhud_mgr_enable_top_and_chat_stacks"
        ]["registration"]["manifest_path"] = "wrong.json"
        with self.assertRaisesRegex(ValueError, "functional and focused"):
            self._hud_enable_stacks_candidate(
                fixture, document=ProgressDocument(data)
            )
        data = deepcopy(fixture["document"].data)
        data["storage_contributions"]["recoil:storage:va:0x56bd24"][
            "overlap"
        ] = "ambiguous"
        with self.assertRaisesRegex(ValueError, "top stack"):
            self._hud_enable_stacks_retail(
                fixture, document=ProgressDocument(data)
            )
        changed = deepcopy(fixture)
        changed["expected"][1]["slot_displacement"] = 8
        with self.assertRaisesRegex(ValueError, "immutable four-call"):
            self._hud_enable_stacks_candidate(changed)

    def test_hud_enable_stacks_rejects_retail_provenance_drift(self) -> None:
        fixture = self._hud_enable_stacks_fixture()
        retail = fixture["retail"]
        mutations = {
            "top-storage": (0, "00413910 8b 0d 20 bd 56 00 mov ecx, dword [0x56bd20]"),
            "eax-vptr": (4, "00413923 8b 11 mov edx, dword [ecx]"),
            "top-slot": (5, "00413925 ff 50 08 call dword [eax+0x8]"),
            "chat-vptr": (10, "0041393b 8b 01 mov eax, dword [ecx]"),
            "chat-argument": (9, "00413939 6a 00 push 0x0"),
        }
        for label, (index, line) in mutations.items():
            changed = list(retail)
            changed[index] = tuple(parse_assembly(line, source="bn"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "immutable retail"
            ):
                self._hud_enable_stacks_retail(
                    fixture, retail_instructions=tuple(changed)
                )
        with self.assertRaisesRegex(ValueError, "immutable retail"):
            self._hud_enable_stacks_retail(
                fixture, retail_instructions=retail[:-2]
            )

    def test_hud_enable_stacks_rejects_candidate_body_and_topology_drift(self) -> None:
        fixture = self._hud_enable_stacks_fixture()
        caller = fixture["caller"]
        first = caller.relocations[0]
        bad_addend = bytearray(caller.data)
        struct.pack_into("<I", bad_addend, 0x02, 4)
        bad_padding = bytearray(caller.data)
        bad_padding[-1] = 0xCC
        definitions = {
            "addend": replace(caller, data=bytes(bad_addend)),
            "padding": replace(caller, data=bytes(bad_padding)),
            "symbol": replace(caller, relocations=(replace(first, symbol_name="?wrong@@3HA"), *caller.relocations[1:])),
            "type": replace(caller, relocations=(replace(first, type=0x14), *caller.relocations[1:])),
            "missing": replace(caller, relocations=caller.relocations[1:]),
            "mask": replace(caller, relocation_mask=(*caller.relocation_mask[:0x02], False, *caller.relocation_mask[0x03:])),
            "external": replace(caller, undefined_external_functions=()),
        }
        for label, definition in definitions.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "complete candidate body|COFF|relocation mask|padding|external"
            ):
                self._hud_enable_stacks_candidate(
                    fixture,
                    candidate=replace(fixture["candidate"], caller_definition=definition),
                )
        instructions = fixture["candidate"].instructions
        for label, index, line in (
            ("top-storage", 2, "0000b 8b 0d 00 00 00 00 mov ecx, dword ?g_HudUiChatMessageStack@@3PAUHudUiTextStack4@@A"),
            ("eax-vptr", 4, "00013 8b 11 mov edx, dword [ecx]"),
            ("top-slot", 5, "00015 ff 50 08 call dword [eax+8]"),
            ("chat-argument", 9, "00029 6a 00 push 0"),
            ("return", 12, "00030 c2 04 00 retn 4"),
        ):
            changed = list(instructions)
            changed[index] = tuple(parse_assembly(line, source="cod"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "candidate top/chat|call population|topology"
            ):
                self._hud_enable_stacks_candidate(
                    fixture,
                    candidate=replace(fixture["candidate"], instructions=tuple(changed)),
                )
        with self.assertRaisesRegex(ValueError, "complete topology"):
            self._hud_enable_stacks_candidate(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({5}),
                    local_control_flow_targets={5: (8,)},
                ),
            )

