    def test_hud_disable_stacks_proves_exact_false_four_call_unit(self) -> None:
        fixture = self._hud_disable_stacks_fixture()
        retail_vptr = self._hud_disable_stacks_retail(fixture)
        candidate_vptr = self._hud_disable_stacks_candidate(fixture)
        self.assertEqual({"0x413965", "0x41397d"}, set(retail_vptr))
        self.assertEqual({"0x15", "0x2d"}, set(candidate_vptr))
        retail_contract = extract_invocation_contract(
            fixture["retail"],
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x413950",
            caller_end_exclusive="0x413990",
            indexes=fixture["indexes"],
            bridge_names={
                "HudUiTextStack4::Clear": SimpleNamespace(address="0x4bd2a0")
            },
            reviewed_loop_vptr_storage_bridges=retail_vptr,
        )
        candidate_contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x413950",
            caller_end_exclusive="0x413990",
            indexes=fixture["indexes"],
            reviewed_loop_vptr_storage_bridges=candidate_vptr,
        )
        self.assertEqual(fixture["expected"], retail_contract)
        self.assertEqual(fixture["expected"], candidate_contract)
        self.assertTrue(
            compare_call_contracts(retail_contract, candidate_contract)["passed"]
        )

