    def test_hud_apply_text_label_rejects_candidate_coff_and_topology_drift(self) -> None:
        fixture = self._hud_apply_text_label_fixture()
        caller = fixture["caller"]
        bad_padding = bytearray(caller.data)
        bad_padding[-1] = 0xCC
        bad_addend = bytearray(caller.data)
        struct.pack_into("<I", bad_addend, 0x60, 4)
        for label, definition in {
            "padding": replace(caller, data=bytes(bad_padding)),
            "addend": replace(caller, data=bytes(bad_addend)),
            "relocation": replace(caller, relocations=()),
            "mask": replace(
                caller,
                relocation_mask=(
                    *caller.relocation_mask[:0x60],
                    False,
                    *caller.relocation_mask[0x61:],
                ),
            ),
            "external": replace(caller, defined_external_data=()),
        }.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "complete candidate body|COFF|relocation|padding|external"
            ):
                self._hud_apply_text_label_candidate(
                    fixture,
                    candidate=replace(
                        fixture["candidate"], caller_definition=definition
                    ),
                )
        instruction_mutations = {
            "fastcall-receiver": (3, "00006 8b f1 mov esi, ecx"),
            "edx-vptr": (25, "0003b 8b 0e mov ecx, dword [esi]"),
            "eax-vptr": (32, "00048 8b 16 mov edx, dword [esi]"),
            "ecx-vptr": (42, "0005d 8b 06 mov eax, dword [esi]"),
            "setpos-slot": (
                29,
                "00041 ff 52 10 call dword [edx+16]",
            ),
            "nonnull-slot-74": (
                35,
                "0004c ff 50 70 call dword [eax+112]",
            ),
            "empty-slot-74": (
                45,
                "00065 ff 51 70 call dword [ecx+112]",
            ),
            "nonnull-cleanup": (36, "0004f 83 c4 04 add esp, 4"),
            "empty-cleanup": (46, "00068 83 c4 04 add esp, 4"),
            "branch": (31, "00046 74 13 je $L_wrong"),
            "return": (41, "0005a c2 08 00 ret 8"),
        }
        for label, (index, line) in instruction_mutations.items():
            instructions = list(fixture["candidate"].instructions)
            instructions[index] = tuple(
                parse_assembly(line, source="cod")
            )[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "candidate EDX receiver"
            ):
                self._hud_apply_text_label_candidate(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(instructions),
                    ),
                )
        with self.assertRaisesRegex(ValueError, "candidate EDX receiver"):
            self._hud_apply_text_label_candidate(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({35}),
                    local_control_flow_targets={35: (42,)},
                ),
            )
        with self.assertRaisesRegex(ValueError, "three-call contract"):
            changed = deepcopy(fixture)
            changed["expected"][2]["cleanup_bytes"] = None
            self._hud_apply_text_label_candidate(changed)

