        for label, (index, line) in replacements.items():
            changed = list(instructions)
            changed[index] = tuple(parse_assembly(line, source="cod"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "semantic drift|receiver|argument|vptr|slot|byte",
            ):
                self._hud_update_frame_objective_timer_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(changed),
                    ),
                )

        with self.assertRaisesRegex(ValueError, "branch|CFG"):
            self._hud_update_frame_objective_timer_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({14}),
                    local_control_flow_targets={14: (26,)},
                ),
            )

        consumed = tuple(
            parse_assembly("  00056 8b f0 mov esi, eax", source="cod")
        )[0]
        changed = (*instructions[:26], consumed)
        with self.assertRaisesRegex(ValueError, "result consumption"):
            self._hud_update_frame_objective_timer_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=changed,
                ),
            )

