    def _hud_update_frame_stack_menu_bridges(
        self,
        fixture: dict,
        **overrides: object,
    ) -> tuple[dict, dict, dict, dict]:
        arguments = {
            "candidate": fixture["candidate"],
            "document": fixture["document"],
            "caller_identity": fixture["caller_identity"],
            "caller_start": "0x410fe0",
            "caller_end_exclusive": "0x411170",
            "indexes": fixture["indexes"],
        }
        arguments.update(overrides)
        return _hud_ui_mgr_update_frame_stack_menu_candidate_bridges(
            fixture["expected"],
            **arguments,
        )

    def test_hud_update_frame_stack_menu_exact_three_slot_zero_calls(
        self,
    ) -> None:
        fixture = self._hud_update_frame_stack_menu_fixture()
        static, absolute, member = (
            self._hud_update_frame_stack_menu_bridges(fixture)
        )
        self.assertEqual(
            {
                f"{fixture['aggregate_symbol']}+24",
                f"{fixture['aggregate_symbol']}+2084",
                f"{fixture['aggregate_symbol']}+2420",
                f"{fixture['aggregate_symbol']}+18308",
                f"{fixture['aggregate_symbol']}+3808",
            },
            set(static),
        )
        self.assertEqual({"0x93", "0xa3"}, set(absolute))
        self.assertEqual(
            {"0x8", "0x35", "0x40", "0x51", "0x9f", "0xaf", "0xbf"},
            set(member),
        )
        contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410fe0",
            caller_end_exclusive="0x411170",
            indexes=fixture["indexes"],
            reviewed_static_storage_reference_bridges=static,
            reviewed_absolute_storage_load_bridges=absolute,
            reviewed_member_vptr_storage_bridges=member,
        )
        self.assertEqual(fixture["expected"], contract)

        for ordinal, field, value in (
            (9, "target_identity", "symbol:wrong"),
            (10, "storage_identity", "load(storage:wrong)"),
            (11, "slot_displacement", 4),
            (12, "cleanup_bytes", 4),
        ):
            changed = deepcopy(fixture)
            changed["expected"][ordinal][field] = value
            with self.subTest(ordinal=ordinal, field=field), (
                self.assertRaisesRegex(ValueError, "ordinal-9-through-12")
            ):
                self._hud_update_frame_stack_menu_bridges(changed)

    def test_hud_update_frame_stack_menu_rejects_object_authority_drift(
        self,
    ) -> None:
        fixture = self._hud_update_frame_stack_menu_fixture()
        caller = fixture["caller"]
        bad_body = bytearray(caller.data)
        bad_body[0xA1] = 0x90
        bad_addend = bytearray(caller.data)
        struct.pack_into("<I", bad_addend, 0xB5, 0xEE4)
        mutations = {
            "body": replace(caller, data=bytes(bad_body)),
            "target": replace(
                caller,
                relocations=(
                    *caller.relocations[:-7],
                    replace(
                        caller.relocations[-7],
                        symbol_name="?Wrong@@YIXXZ",
                    ),
                    *caller.relocations[-6:],
                ),
            ),
            "addend": replace(caller, data=bytes(bad_addend)),
            "duplicate": replace(
                caller,
                relocations=(
                    *caller.relocations,
                    caller.relocations[-1],
                ),
            ),
            "mask": replace(
                caller,
                relocation_mask=(
                    *caller.relocation_mask[:0x95],
                    False,
                    *caller.relocation_mask[0x96:],
                ),
            ),
        }
        for label, definition in mutations.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "object body|relocation|mask",
            ):
                self._hud_update_frame_stack_menu_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

        data = deepcopy(fixture["document"].data)
        data["symbols"]["recoil:data:0x56bd24"][
            "navigation_name"
        ] = "wrong"
        with self.assertRaisesRegex(ValueError, "top stack"):
            self._hud_update_frame_stack_menu_bridges(
                fixture,
                document=ProgressDocument(data),
            )
        data = deepcopy(fixture["document"].data)
        data["symbols"]["recoil:function:0x4bc900"][
            "pipeline_class"
        ] = "non-authored"
        with self.assertRaisesRegex(ValueError, "UpdateAll identity"):
            self._hud_update_frame_stack_menu_bridges(
                fixture,
                document=ProgressDocument(data),
            )

    def test_hud_update_frame_stack_menu_rejects_semantic_cfg_use_drift(
        self,
    ) -> None:
        fixture = self._hud_update_frame_stack_menu_fixture()
        instructions = fixture["candidate"].instructions
        replacements = {
            "base-argument": (33, "  00088 51 push eax"),
            "base-receiver": (
                34,
                (
                    "  00089 b9 00 00 00 00 mov edx, OFFSET FLAT:"
                    f"{fixture['aggregate_symbol']}"
                ),
            ),
            "top-receiver": (
                36,
                (
                    "  00093 8b 0d 00 00 00 00 mov eax, dword "
                    f"{fixture['top_symbol']}"
                ),
            ),
            "top-argument": (38, "  0009e 50 push ecx"),
            "chat-vptr": (44, "  000af 8b 11 mov eax, dword [ecx]"),
            "chat-slot": (45, "  000b1 ff 52 04 call dword [edx+4]"),
            "menu-field": (
                46,
                (
                    "  000b3 8b 0d e0 0e 00 00 mov ecx, dword "
                    f"{fixture['aggregate_symbol']}+3812"
                ),
            ),
        }
        for label, (index, line) in replacements.items():
            changed = list(instructions)
            changed[index] = tuple(parse_assembly(line, source="cod"))[0]
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "byte|base-call|receiver|argument|vptr|slot|field",
            ):
                self._hud_update_frame_stack_menu_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(changed),
                    ),
                )

        with self.assertRaisesRegex(ValueError, "CFG"):
            self._hud_update_frame_stack_menu_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({40}),
                    local_control_flow_targets={40: (41,)},
                ),
            )
        consumed = tuple(
            parse_assembly("  000c3 8b f0 mov esi, eax", source="cod")
        )[0]
        with self.assertRaisesRegex(ValueError, "result consumption"):
            self._hud_update_frame_stack_menu_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=(*instructions[:-1], consumed),
                ),
            )

