    def _hud_ensure_sensor_center_candidate(
        self,
        fixture: dict,
    ) -> CandidateAssembly:
        base = self._hud_ensure_font_loop_candidate(fixture)
        definition = base.caller_definition
        target = base.target
        assert definition is not None
        assert target is not None
        direct_symbol = "?TestDirect@HudUiMgr@@YIXXZ"
        rows = [
            f"{offset:05x} e8 00 00 00 00 call {direct_symbol}"
            for offset in (
                0x180,
                0x190,
                0x1A0,
                0x1B0,
                0x1C0,
                0x1D0,
                0x1E0,
                0x1F0,
                0x200,
                0x23D,
                0x263,
            )
        ]
        aggregate = "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
        rows.extend(
            [
                (
                    "00268 8b 15 24 0c 00 00 mov edx, DWORD PTR "
                    f"{aggregate}+3108"
                ),
                (
                    "0026e b9 24 0c 00 00 mov ecx, OFFSET FLAT:"
                    f"{aggregate}+3108"
                ),
                "00273 ff 52 64 call DWORD PTR [edx+100]",
                "00276 8b f8 mov edi, eax",
                (
                    "00278 a1 24 0c 00 00 mov eax, DWORD PTR "
                    f"{aggregate}+3108"
                ),
                (
                    "0027d b9 24 0c 00 00 mov ecx, OFFSET FLAT:"
                    f"{aggregate}+3108"
                ),
                "00282 ff 50 68 call DWORD PTR [eax+104]",
            ]
        )
        added_instructions = tuple(
            parse_assembly("\n".join(rows), source="cod")
        )
        instructions = tuple(
            sorted(
                (*base.instructions, *added_instructions),
                key=lambda instruction: int(
                    re.match(
                        r"^\s*([0-9a-fA-F]+)",
                        instruction.source_line,
                    ).group(1),
                    16,
                ),
            )
        )
        body = bytearray(definition.data)
        for instruction in added_instructions:
            match = re.match(
                r"^\s*([0-9a-fA-F]+)",
                instruction.source_line,
            )
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(int(value, 16) for value in instruction.bytes)
            body[offset : offset + len(encoded)] = encoded
        added_relocations = tuple(
            CoffRelocation(
                offset=offset,
                symbol_index=800,
                type=0x06,
                symbol_name=aggregate,
            )
            for offset in (0x26A, 0x26F, 0x279, 0x27E)
        )
        mask = list(definition.relocation_mask)
        for relocation in added_relocations:
            for index in range(relocation.offset, relocation.offset + 4):
                mask[index] = True

        contribution = target.translation_unit_function_order[0]
        ensure_row = contribution.functions[0]
        get_center_x = SimpleNamespace(
            address="0x404d90",
            symbol="?GetCenterX@HudUiWidget@@UAEHXZ",
            symbol_regex=None,
            name="HudUiWidget::GetCenterX",
            pipeline_class="authored",
            authored_order_role="authored-body",
            required_presence=True,
            full_order_gate=True,
        )
        get_center_y = SimpleNamespace(
            address="0x404dd0",
            symbol="?GetCenterY@HudUiWidget@@UAEHXZ",
            symbol_regex=None,
            name="HudUiWidget::GetCenterY",
            pipeline_class="authored",
            authored_order_role="authored-body",
            required_presence=True,
            full_order_gate=True,
        )
        expanded_contribution = SimpleNamespace(
            source_from=contribution.source_from,
            order_scope=contribution.order_scope,
            functions=(ensure_row, get_center_x, get_center_y),
        )
        expanded_target = SimpleNamespace(
            **{
                **vars(target),
                "translation_unit_function_order": (
                    expanded_contribution,
                ),
            }
        )
        return replace(
            base,
            instructions=instructions,
            target=expanded_target,
            caller_definition=replace(
                definition,
                data=bytes(body),
                relocations=(
                    *definition.relocations,
                    *added_relocations,
                ),
                relocation_mask=tuple(mask),
            ),
        )

