    def test_hud_ensure_sensor_center_exact_pair_converges(self) -> None:
        fixture = self._hud_ensure_sensor_center_fixture()
        candidate = self._hud_ensure_sensor_center_candidate(fixture)
        expected = self._hud_ensure_sensor_center_expected(fixture)
        bridges = self._hud_ensure_sensor_center_candidate_bridges(
            fixture,
            candidate,
            expected=expected,
        )
        self.assertEqual(
            {
                "0x268": ReviewedAbsoluteStorageLoadBridge(
                    register="edx",
                    aggregate_symbol=(
                        "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
                    ),
                    displacement=0xC24,
                    access_width=4,
                    storage_identity="storage:recoil:data:0x4e5ed0",
                ),
                "0x278": ReviewedAbsoluteStorageLoadBridge(
                    register="eax",
                    aggregate_symbol=(
                        "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
                    ),
                    displacement=0xC24,
                    access_width=4,
                    storage_identity="storage:recoil:data:0x4e5ed0",
                ),
            },
            bridges,
        )
        loop_bridges = self._hud_ensure_font_loop_candidate_bridges(
            fixture,
            candidate,
            expected=expected,
            indexes=fixture["indexes"],
        )
        actual = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=fixture["indexes"],
            reviewed_absolute_storage_load_bridges=bridges,
            reviewed_loop_vptr_storage_bridges=loop_bridges,
        )
        self.assertEqual(len(expected) + 1, len(actual))
        for retail_ordinal, candidate_ordinal in ((24, 25), (25, 26)):
            self.assertEqual(
                {
                    key: value
                    for key, value in expected[retail_ordinal].items()
                    if key != "ordinal"
                },
                {
                    key: value
                    for key, value in actual[candidate_ordinal].items()
                    if key != "ordinal"
                },
            )
        self.assertEqual(
            (
                "load(storage:recoil:data:0x4e5ed0+0xc24)",
                0x64,
            ),
            (
                actual[25]["storage_identity"],
                actual[25]["slot_displacement"],
            ),
        )
        self.assertEqual(
            (
                "load(storage:recoil:data:0x4e5ed0+0xc24)",
                0x68,
            ),
            (
                actual[26]["storage_identity"],
                actual[26]["slot_displacement"],
            ),
        )

