    def test_hud_ensure_sensor_center_candidate_relocations_fail_closed(
        self,
    ) -> None:
        fixture = self._hud_ensure_sensor_center_fixture()
        exact = self._hud_ensure_sensor_center_candidate(fixture)
        definition = exact.caller_definition
        assert definition is not None
        addend_drift = bytearray(definition.data)
        struct.pack_into("<I", addend_drift, 0x279, 0xC28)
        cases = {
            "missing": replace(
                definition,
                relocations=tuple(
                    row
                    for row in definition.relocations
                    if row.offset != 0x279
                ),
            ),
            "extra": replace(
                definition,
                relocations=(
                    *definition.relocations,
                    CoffRelocation(
                        offset=0x277,
                        symbol_index=900,
                        type=0x06,
                        symbol_name=(
                            "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
                        ),
                    ),
                ),
            ),
            "type": replace(
                definition,
                relocations=tuple(
                    replace(row, type=0x14)
                    if row.offset == 0x279
                    else row
                    for row in definition.relocations
                ),
            ),
            "addend": replace(
                definition,
                data=bytes(addend_drift),
            ),
        }
        for name, drifted in cases.items():
            with self.subTest(name=name):
                with self.assertRaisesRegex(
                    ValueError,
                    "structural/COFF|DIR32 \\+0xc24",
                ):
                    self._hud_ensure_sensor_center_candidate_bridges(
                        fixture,
                        replace(exact, caller_definition=drifted),
                    )

    def test_hud_ensure_sensor_center_authority_and_expected_fail_closed(
        self,
    ) -> None:
        fixture = self._hud_ensure_sensor_center_fixture()
        candidate = self._hud_ensure_sensor_center_candidate(fixture)
        expected = self._hud_ensure_sensor_center_expected(fixture)
        aliased_indexes = replace(
            fixture["indexes"],
            by_candidate_name={
                **fixture["indexes"].by_candidate_name,
                "?getcenterx@huduIwidget@@uaehxz": (
                    "symbol:other:get-center-x"
                ),
            },
        )
        with self.assertRaisesRegex(ValueError, "unique typed authored"):
            self._hud_ensure_sensor_center_candidate_bridges(
                fixture,
                candidate,
                indexes=aliased_indexes,
            )

        wrong_expected = deepcopy(expected)
        wrong_expected[25]["slot_displacement"] = 0x64
        with self.assertRaisesRegex(
            ValueError,
            "independently retail-derived",
        ):
            self._hud_ensure_sensor_center_candidate_bridges(
                fixture,
                candidate,
                expected=wrong_expected,
            )

        wrong_caller = replace(
            fixture["indexes"],
            by_address={
                **fixture["indexes"].by_address,
                "0x410160": "symbol:other:caller",
            },
        )
        with self.assertRaisesRegex(ValueError, "caller identity"):
            self._hud_ensure_sensor_center_candidate_bridges(
                fixture,
                candidate,
                indexes=wrong_caller,
            )

