        definition = base.caller_definition
        assert definition is not None
        direct_symbol = "?TestDirect@HudUiMgr@@YIXXZ"
        aggregate = "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
        add_child = (
            "?AddChild@HudUiContainer@@QAEHPAUHudUiElement@@@Z"
        )
        rows = [
            f"{offset:05x} e8 00 00 00 00 call {direct_symbol}"
            for offset in (0x290, 0x2A0, 0x300, 0x350, 0x382)
        ]
        rows.extend(
            [
                (
                    "00387 8b 0d 60 0c 00 00 mov ecx, DWORD PTR "
                    f"{aggregate}+3168"
                ),
                (
                    "0038d 8b 15 9c 0d 00 00 mov edx, DWORD PTR "
                    f"{aggregate}+3484"
                ),
                (
                    "00393 8d 44 24 34 lea eax, DWORD PTR "
                    "_meterRect$TEST[esp+148]"
                ),
                (
                    "00397 c7 05 d0 0e 00 00 e0 07 00 00 "
                    f"mov DWORD PTR {aggregate}+3792, 2016"
                ),
                "003a1 50 push eax",
                "003a2 51 push ecx",
                (
                    "003a3 b9 9c 0d 00 00 mov ecx, OFFSET FLAT:"
                    f"{aggregate}+3484"
                ),
                "003a8 ff 52 18 call DWORD PTR [edx+24]",
                (
                    "003ab b9 00 00 00 00 mov ecx, OFFSET FLAT:"
                    f"{aggregate}"
                ),
                (
                    "003b0 68 24 0c 00 00 push OFFSET FLAT:"
                    f"{aggregate}+3108"
                ),
                f"003b5 e8 00 00 00 00 call {add_child}",
                (
                    "003ba b9 00 00 00 00 mov ecx, OFFSET FLAT:"
                    f"{aggregate}"
                ),
                (
                    "003bf 68 e0 0c 00 00 push OFFSET FLAT:"
                    f"{aggregate}+3296"
                ),
                f"003c4 e8 00 00 00 00 call {add_child}",
                (
                    "003c9 b9 00 00 00 00 mov ecx, OFFSET FLAT:"
                    f"{aggregate}"
                ),
                (
                    "003ce 68 9c 0d 00 00 push OFFSET FLAT:"
                    f"{aggregate}+3484"
                ),
                f"003d3 e8 00 00 00 00 call {add_child}",
            ]
        )
        added_instructions = tuple(
            parse_assembly("\n".join(rows), source="cod")
        )
        instructions = tuple(
            sorted(
                (*base.instructions, *added_instructions),
                key=lambda instruction: int(
                    re.match(
                        r"^\s*([0-9a-fA-F]+)",
                        instruction.source_line,
                    ).group(1),
                    16,
                ),
            )
        )
        body = bytearray(definition.data)
        for instruction in added_instructions:
            match = re.match(
                r"^\s*([0-9a-fA-F]+)",
                instruction.source_line,
            )
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(int(value, 16) for value in instruction.bytes)
            body[offset : offset + len(encoded)] = encoded
        dir32_specs = {
            0x389: 0xC60,
            0x38F: 0xD9C,
            0x399: 0xED0,
            0x3A4: 0xD9C,
            0x3AC: 0,
            0x3B1: 0xC24,
            0x3BB: 0,
            0x3C0: 0xCE0,
            0x3CA: 0,
            0x3CF: 0xD9C,
        }
        relocations = [
            *definition.relocations,
            *[
                CoffRelocation(
                    offset=offset,
                    symbol_index=800,
                    type=0x06,
                    symbol_name=aggregate,
                )
                for offset in dir32_specs
            ],
            *[
                CoffRelocation(
                    offset=offset,
                    symbol_index=901,
                    type=0x14,
                    symbol_name=add_child,
                )
                for offset in (0x3B6, 0x3C5, 0x3D4)
            ],
        ]
        mask = list(definition.relocation_mask)
        for relocation in relocations[len(definition.relocations) :]:
            for index in range(relocation.offset, relocation.offset + 4):
                mask[index] = True
        return replace(
            base,
            instructions=instructions,
            caller_definition=replace(
                definition,
                data=bytes(body),
                relocations=tuple(relocations),
                relocation_mask=tuple(mask),
                undefined_external_functions=(
                    *definition.undefined_external_functions,
                    add_child,
                ),
            ),
        )

