    def test_hud_ensure_sensor_meter_setclip_exact_unit_converges(
        self,
    ) -> None:
        fixture = self._hud_ensure_sensor_meter_setclip_fixture()
        candidate = self._hud_ensure_sensor_meter_setclip_candidate(
            fixture
        )
        expected = self._hud_ensure_sensor_meter_setclip_expected(fixture)
        bridge = self._hud_ensure_sensor_meter_setclip_candidate_bridge(
            fixture,
            candidate,
            expected=expected,
        )
        self.assertEqual(
            {
                "0x38d": ReviewedAbsoluteStorageLoadBridge(
                    register="edx",
                    aggregate_symbol=(
                        "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
                    ),
                    displacement=0xD9C,
                    access_width=4,
                    storage_identity="storage:recoil:data:0x4e5ed0",
                )
            },
            bridge,
        )
        center_bridges = (
            _hud_ui_mgr_ensure_sensor_center_candidate_absolute_load_bridges(
                expected,
                candidate,
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=fixture["indexes"],
            )
        )
        absolute_bridges = {**center_bridges, **bridge}
        actual = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=fixture["indexes"],
            reviewed_absolute_storage_load_bridges=absolute_bridges,
            reviewed_loop_vptr_storage_bridges=(
                self._hud_ensure_font_loop_candidate_bridges(
                    fixture,
                    candidate,
                    expected=expected,
                    indexes=fixture["indexes"],
                )
            ),
        )
        self.assertEqual("", expected[31]["target_identity"])
        self.assertEqual("virtual-slot", expected[31]["identity_kind"])
        self.assertEqual(
            {
                key: value
                for key, value in expected[31].items()
                if key != "ordinal"
            },
            {
                key: value
                for key, value in actual[32].items()
                if key != "ordinal"
            },
        )
        self.assertEqual(
            "load(storage:recoil:data:0x4e5ed0+0xd9c)",
            actual[32]["storage_identity"],
        )
        self.assertEqual(0x18, actual[32]["slot_displacement"])
        self.assertEqual("", actual[32]["target_identity"])

    def test_hud_ensure_sensor_meter_accepts_symbolic_local_layout_drift(
        self,
    ) -> None:
        fixture = self._hud_ensure_sensor_meter_setclip_fixture()
        candidate = self._hud_ensure_sensor_meter_setclip_candidate(fixture)
        definition = candidate.caller_definition
        assert definition is not None
        body = bytearray(definition.data)
        body[0x396] = 0x38
        drifted_rows = tuple(
            parse_assembly(
                "\n".join(
                    instruction.source_line.replace(
                        "00393 8d 44 24 34",
                        "00393 8d 44 24 38",
                    )
                    for instruction in candidate.instructions
                ),
                source="cod",
            )
        )
        drifted = replace(
            candidate,
            instructions=drifted_rows,
            caller_definition=replace(definition, data=bytes(body)),
        )
        self.assertEqual(
            {
                "0x38d": ReviewedAbsoluteStorageLoadBridge(
                    register="edx",
                    aggregate_symbol=(
                        "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
                    ),
                    displacement=0xD9C,
                    access_width=4,
                    storage_identity="storage:recoil:data:0x4e5ed0",
                )
            },
            self._hud_ensure_sensor_meter_setclip_candidate_bridge(
                fixture,
                drifted,
            ),
        )
        malformed_rows = tuple(
            parse_assembly(
                "\n".join(
                    instruction.source_line.replace(
                        "_meterRect$TEST[esp+148]",
                        "_otherRect$TEST[esp+148]",
                    )
                    for instruction in drifted.instructions
                ),
                source="cod",
            )
        )
        with self.assertRaisesRegex(ValueError, "symbolic local-stack operand"):
            self._hud_ensure_sensor_meter_setclip_candidate_bridge(
                fixture,
                replace(drifted, instructions=malformed_rows),
            )

