    def test_hud_ensure_objective_sensor_center_exact_pair_converges(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_sensor_center_fixture()
        candidate = self._hud_ensure_objective_sensor_center_candidate(
            fixture
        )
        expected = self._hud_ensure_objective_sensor_center_expected(fixture)
        objective_bridges = (
            self._hud_ensure_objective_sensor_candidate_bridges(
                fixture,
                candidate,
                expected,
            )
        )
        self.assertEqual(
            {
                "0x409": ReviewedAbsoluteStorageLoadBridge(
                    register="edx",
                    aggregate_symbol=(
                        "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
                    ),
                    displacement=0xC24,
                    access_width=4,
                    storage_identity="storage:recoil:data:0x4e5ed0",
                ),
                "0x425": ReviewedAbsoluteStorageLoadBridge(
                    register="eax",
                    aggregate_symbol=(
                        "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
                    ),
                    displacement=0xC24,
                    access_width=4,
                    storage_identity="storage:recoil:data:0x4e5ed0",
                ),
            },
            objective_bridges,
        )
        center = (
            _hud_ui_mgr_ensure_sensor_center_candidate_absolute_load_bridges(
                expected,
                candidate,
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=fixture["indexes"],
            )
        )
        meter = (
            _hud_ui_mgr_ensure_sensor_meter_setclip_candidate_absolute_load_bridge(
                expected,
                candidate,
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=fixture["indexes"],
            )
        )
        zrd_bridges = self._hud_ensure_objective_sensor_zrd_bridges(
            fixture,
            candidate,
            expected,
        )
        actual = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=fixture["indexes"],
            bridge_names=fixture["bridge_names"],
            compiler_generated_bridges=zrd_bridges,
            reviewed_absolute_storage_load_bridges={
                **center,
                **meter,
                **objective_bridges,
            },
            reviewed_loop_vptr_storage_bridges=(
                self._hud_ensure_font_loop_candidate_bridges(
                    fixture,
                    candidate,
                    expected=expected,
                    indexes=fixture["indexes"],
                )
            ),
            local_control_flow_indices=(
                candidate.local_control_flow_indices
            ),
            local_control_flow_targets=(
                candidate.local_control_flow_targets
            ),
        )
        for expected_ordinal, candidate_ordinal in ((36, 38), (37, 39)):
            self.assertEqual(
                {
                    key: value
                    for key, value in expected[expected_ordinal].items()
                    if key != "ordinal"
                },
                {
                    key: value
                    for key, value in actual[candidate_ordinal].items()
                    if key != "ordinal"
                },
            )
        self.assertEqual(
            fixture["indexes"].by_candidate_name[
                fixture["apply_symbol"]
            ],
            actual[40]["target_identity"],
        )
        self.assertEqual(
            fixture["caller_identity"],
            actual[37]["target_identity"],
        )
        self.assertEqual(0, len(candidate.local_control_flow_indices))
        self.assertEqual(
            5,
            sum(
                instruction.raw_text.lower().startswith(
                    ("je ", "jmp ")
                )
                for instruction in candidate.instructions
                if 0x3D8
                <= int(
                    re.match(
                        r"^\s*([0-9a-fA-F]+)",
                        instruction.source_line,
                    ).group(1),
                    16,
                )
                <= 0x447
            ),
        )

    def test_hud_ensure_objective_sensor_center_retail_fails_closed(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_sensor_center_fixture()
        cases = {
            "slot": (
                "004104e9 ff 52 64 call dword [edx+0x64]",
                "004104e9 ff 52 60 call dword [edx+0x60]",
            ),
            "result": (
                "004104ec 89 45 e8 mov dword [ebp-0x18], eax",
                "004104ec 89 45 e4 mov dword [ebp-0x1c], eax",
            ),
            "flow": (
                "004104cc 0f 84 00 03 00 00 je 0x4107d2",
                "004104cc 0f 85 00 03 00 00 jne 0x4107d2",
            ),
            "following": (
                (
                    "00410512 e8 19 38 00 00 "
                    "call HudUiLayoutNode::ApplyImageWidget"
                ),
                "00410512 e8 19 38 00 00 call 0x413c10",
            ),
        }
        for name, (before, after) in cases.items():
            with self.subTest(name=name):
                rows = [row.replace(before, after) for row in fixture["rows"]]
                with self.assertRaisesRegex(
                    ValueError,
                    "exact lookup|unconditional",
                ):
                    _hud_ui_mgr_ensure_objective_sensor_center_retail_guard(
                        tuple(
                            parse_assembly(
                                "\n".join(rows),
                                source="bn",
                            )
                        ),
                        document=fixture["document"],
                        caller_identity=fixture["caller_identity"],
                        caller_start="0x410160",
                        caller_end_exclusive="0x410d10",
                        indexes=fixture["indexes"],
                    )

    def test_hud_ensure_objective_sensor_center_candidate_fails_closed(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_sensor_center_fixture()
        candidate = self._hud_ensure_objective_sensor_center_candidate(
            fixture
        )
        expected = self._hud_ensure_objective_sensor_center_expected(fixture)
        definition = candidate.caller_definition
        assert definition is not None
        cases = {
            "register": (
                "00414 ff 52 64 call DWORD PTR [edx+100]",
                "00414 ff 50 64 call DWORD PTR [eax+100]",
            ),
            "result": (
                (
                    "00432 89 44 24 4c mov DWORD PTR "
                    "_panelCenter$TEST[esp+152], eax"
                ),
                (
                    "00432 89 44 24 48 mov DWORD PTR "
                    "_panelCenter$TEST[esp+148], eax"
                ),
            ),
            "following": (
                (
                    "00447 e8 00 00 00 00 call "
                    f"{fixture['apply_symbol']}"
                ),
                "00447 e8 00 00 00 00 call ?WrongApply@@YAXXZ",
            ),
            "flow": (
                "00401 74 06 je SHORT $LTEST_X",
                "00401 75 06 jne SHORT $LTEST_X",
            ),
        }
        for name, (before, after) in cases.items():
            with self.subTest(name=name):
                instructions = tuple(
                    parse_assembly(
                        "\n".join(
                            instruction.source_line.replace(before, after)
                            for instruction in candidate.instructions
                        ),
                        source="cod",
                    )
                )
                changed = next(
                    instruction
                    for instruction in instructions
                    if instruction.source_line.strip().startswith(
                        after.split()[0]
                    )
                )
                offset = int(after.split()[0], 16)
                body = bytearray(definition.data)
                encoded = bytes(
                    int(value, 16) for value in changed.bytes
                )
                body[offset : offset + len(encoded)] = encoded
                with self.assertRaisesRegex(
                    ValueError,
                    "structural/COFF|exact lookup|DIR32/REL32",
                ):
                    self._hud_ensure_objective_sensor_candidate_bridges(
                        fixture,
                        replace(
                            candidate,
                            instructions=instructions,
                            caller_definition=replace(
                                definition,
                                data=bytes(body),
                            ),
                        ),
                        expected,
                    )

        source_index = next(
            index
            for index, instruction in enumerate(candidate.instructions)
            if instruction.source_line.strip().startswith("00401 ")
        )
        with self.assertRaisesRegex(ValueError, "conditional CFG"):
            self._hud_ensure_objective_sensor_candidate_bridges(
                fixture,
                replace(
                    candidate,
                    local_control_flow_indices=frozenset({source_index}),
                    local_control_flow_targets={source_index: ()},
                ),
                expected,
            )

    def test_hud_ensure_objective_sensor_center_relocations_fail_closed(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_sensor_center_fixture()
        candidate = self._hud_ensure_objective_sensor_center_candidate(
            fixture
        )
        expected = self._hud_ensure_objective_sensor_center_expected(fixture)
        definition = candidate.caller_definition
        assert definition is not None
        addend = bytearray(definition.data)
        struct.pack_into("<I", addend, 0x40B, 0xC28)
        mask = list(definition.relocation_mask)
        mask[0x40B] = False
        cases = {
            "missing": replace(
                definition,
                relocations=tuple(
                    row
                    for row in definition.relocations
                    if row.offset != 0x40B
                ),
            ),
            "extra": replace(
                definition,
                relocations=(
                    *definition.relocations,
                    CoffRelocation(
                        offset=0x432,
                        symbol_index=920,
                        type=0x06,
                        symbol_name=(
                            "?g_HudUiMgr@@"
                            "3THudUiMgrDataStorage@@A"
                        ),
                    ),
                ),
            ),
            "addend": replace(definition, data=bytes(addend)),
            "mask": replace(
                definition,
                relocation_mask=tuple(mask),
            ),
            "identity": replace(
                definition,
                relocations=tuple(
                    replace(row, symbol_name="?WrongKey@@3PADA")
                    if row.offset == 0x40B
                    else row
                    for row in definition.relocations
                ),
            ),
        }
        for name, changed in cases.items():
            with self.subTest(name=name):
                with self.assertRaisesRegex(
                    ValueError,
                    "structural/COFF|DIR32/REL32",
                ):
                    self._hud_ensure_objective_sensor_candidate_bridges(
                        fixture,
                        replace(
                            candidate,
                            caller_definition=changed,
                        ),
                        expected,
                    )

