        for instruction in added:
            match = re.match(
                r"^\s*([0-9a-fA-F]+)",
                instruction.source_line,
            )
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(int(value, 16) for value in instruction.bytes)
            body[offset : offset + len(encoded)] = encoded
        dir32 = {
            0x44E: 0x6AC,
            0x453: 0x6AC,
            0x45F: 0x6AC,
            0x464: 0x6AC,
            0x488: 0x978,
        }
        rel32 = {
            0x494: fixture["apply_corner_symbol"],
        }
        for offset, addend in dir32.items():
            struct.pack_into("<I", body, offset, addend)
        relocations = tuple(
            [
                CoffRelocation(
                    offset=offset,
                    symbol_index=930,
                    type=0x06,
                    symbol_name=aggregate,
                )
                for offset in dir32
            ]
            + [
                CoffRelocation(
                    offset=offset,
                    symbol_index=931,
                    type=0x14,
                    symbol_name=symbol,
                )
                for offset, symbol in rel32.items()
            ]
        )
        mask = list(definition.relocation_mask)
        for relocation in relocations:
            for index in range(relocation.offset, relocation.offset + 4):
                mask[index] = True
        return replace(
            base,
            instructions=instructions,
            caller_definition=replace(
                definition,
                data=bytes(body),
                relocations=(
                    *definition.relocations,
                    *relocations,
                ),
                relocation_mask=tuple(mask),
                defined_external_functions=(
                    *definition.defined_external_functions,
                    fixture["apply_corner_symbol"],
                ),
            ),
        )

