    def test_hud_ensure_objective_widget_center_exact_pair_converges(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_widget_center_fixture()
        candidate = self._hud_ensure_objective_widget_center_candidate(fixture)
        expected = self._hud_ensure_objective_widget_center_expected(fixture)
        widget = self._hud_ensure_objective_widget_candidate_bridges(
            fixture,
            candidate,
            expected,
        )
        self.assertEqual({"0x44c", "0x45e"}, set(widget))
        center = (
            _hud_ui_mgr_ensure_sensor_center_candidate_absolute_load_bridges(
                expected,
                candidate,
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=fixture["indexes"],
            )
        )
        meter = (
            _hud_ui_mgr_ensure_sensor_meter_setclip_candidate_absolute_load_bridge(
                expected,
                candidate,
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=fixture["indexes"],
            )
        )
        objective_sensor = (
            self._hud_ensure_objective_sensor_candidate_bridges(
                fixture,
                candidate,
                expected,
            )
        )
        zrd = self._hud_ensure_objective_sensor_zrd_bridges(
            fixture,
            candidate,
            expected,
        )
        actual = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=fixture["indexes"],
            bridge_names=fixture["bridge_names"],
            compiler_generated_bridges=zrd,
            reviewed_absolute_storage_load_bridges={
                **center,
                **meter,
                **objective_sensor,
                **widget,
            },
            reviewed_loop_vptr_storage_bridges=(
                self._hud_ensure_font_loop_candidate_bridges(
                    fixture,
                    candidate,
                    expected=expected,
                    indexes=fixture["indexes"],
                )
            ),
        )
        for expected_ordinal, candidate_ordinal in ((39, 41), (40, 42)):
            self.assertEqual(
                {
                    key: value
                    for key, value in expected[expected_ordinal].items()
                    if key != "ordinal"
                },
                {
                    key: value
                    for key, value in actual[candidate_ordinal].items()
                    if key != "ordinal"
                },
            )
        self.assertEqual(
            fixture["indexes"].by_candidate_name[
                fixture["apply_corner_symbol"]
            ],
            actual[43]["target_identity"],
        )

    def test_hud_ensure_objective_widget_accepts_symbolic_local_drift(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_widget_center_fixture()
        candidate = self._hud_ensure_objective_widget_center_candidate(fixture)
        expected = self._hud_ensure_objective_widget_center_expected(fixture)
        definition = candidate.caller_definition
        assert definition is not None
        body = bytearray(definition.data)
        for offset, displacement in (
            (0x45D, 0x28),
            (0x470, 0x2C),
            (0x480, 0x28),
        ):
            body[offset] = displacement
        replacements = {
            "0045a 89 44 24 24": "0045a 89 44 24 28",
            "0046d 89 44 24 28": "0046d 89 44 24 2c",
            "0047d 8d 44 24 24": "0047d 8d 44 24 28",
        }
        instructions = tuple(
            parse_assembly(
                "\n".join(
                    next(
                        (
                            row.replace(before, after)
                            for before, after in replacements.items()
                            if before in row
                        ),
                        row,
                    )
                    for row in (
                        instruction.source_line
                        for instruction in candidate.instructions
                    )
                ),
                source="cod",
            )
        )
        drifted = replace(
            candidate,
            instructions=instructions,
            caller_definition=replace(definition, data=bytes(body)),
        )
        self.assertEqual(
            {"0x44c", "0x45e"},
            set(
                self._hud_ensure_objective_widget_candidate_bridges(
                    fixture,
                    drifted,
                    expected,
                )
            ),
        )
        malformed = tuple(
            parse_assembly(
                "\n".join(
                    instruction.source_line.replace(
                        "_objectiveCenter$TEST[esp+148]",
                        "_wrongCenter$TEST[esp+148]",
                    )
                    for instruction in drifted.instructions
                ),
                source="cod",
            )
        )
        with self.assertRaisesRegex(ValueError, "symbolic local-stack operand"):
            self._hud_ensure_objective_widget_candidate_bridges(
                fixture,
                replace(drifted, instructions=malformed),
                expected,
            )

    def test_hud_ensure_objective_widget_center_retail_fails_closed(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_widget_center_fixture()
        cases = {
            "slot": (
                "00410522 ff 52 64 call dword [edx+0x64]",
                "00410522 ff 52 60 call dword [edx+0x60]",
            ),
            "result": (
                "00410525 89 45 e8 mov dword [ebp-0x18], eax",
                "00410525 89 45 e4 mov dword [ebp-0x1c], eax",
            ),
            "neighbor": (
                (
                    "0041054b e8 c0 35 00 00 "
                    "call HudUiLayoutNode::ApplyCornerTextQuad"
                ),
                "0041054b e8 c0 35 00 00 call 0x413d30",
            ),
        }
        for name, (before, after) in cases.items():
            with self.subTest(name=name):
                rows = [row.replace(before, after) for row in fixture["rows"]]
                with self.assertRaisesRegex(
                    ValueError,
                    "exact ApplyImageWidget|absorbed-neighbor",
                ):
                    _hud_ui_mgr_ensure_objective_widget_center_retail_guard(
                        tuple(
                            parse_assembly(
                                "\n".join(rows),
                                source="bn",
                            )
                        ),
                        document=fixture["document"],
                        caller_identity=fixture["caller_identity"],
                        caller_start="0x410160",
                        caller_end_exclusive="0x410d10",
                        indexes=fixture["indexes"],
                    )

    def test_hud_ensure_objective_widget_center_candidate_fails_closed(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_widget_center_fixture()
        candidate = self._hud_ensure_objective_widget_center_candidate(fixture)
        expected = self._hud_ensure_objective_widget_center_expected(fixture)
        definition = candidate.caller_definition
        assert definition is not None
        drifted = bytearray(definition.data)
        struct.pack_into("<I", drifted, 0x44E, 0x6B0)
        mask = list(definition.relocation_mask)
        mask[0x44E] = False
        cases = {
            "call": replace(
                definition,
                data=(
                    definition.data[:0x457]
                    + bytes.fromhex("ff 50 64")
                    + definition.data[0x45A:]
                ),
            ),
            "addend": replace(definition, data=bytes(drifted)),
            "mask": replace(definition, relocation_mask=tuple(mask)),
            "relocation": replace(
                definition,
                relocations=tuple(
                    row
                    for row in definition.relocations
                    if row.offset != 0x464
                ),
            ),
        }
        for name, changed in cases.items():
            with self.subTest(name=name):
                with self.assertRaisesRegex(
                    ValueError,
                    "structural/COFF|exact ApplyImageWidget|DIR32/REL32",
                ):
                    self._hud_ensure_objective_widget_candidate_bridges(
                        fixture,
                        replace(candidate, caller_definition=changed),
                        expected,
                    )

