    def test_hud_ensure_objective_label_setpos_exact_unit_converges(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_label_setpos_fixture()
        _hud_ui_mgr_ensure_objective_label_setpos_retail_guard(
            fixture["instructions"],
            document=fixture["document"],
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=fixture["indexes"],
        )
        candidate = self._hud_ensure_objective_label_setpos_candidate(fixture)
        bridge = self._hud_ensure_objective_label_setpos_bridge(
            fixture,
            candidate,
        )
        self.assertEqual({"0x62a"}, set(bridge))
        self.assertEqual(0x828, bridge["0x62a"].displacement)
        expected = self._hud_ensure_objective_label_setpos_expected()[55]
        self.assertEqual("virtual-slot", expected["identity_kind"])
        self.assertEqual("", expected["target_identity"])
        self.assertEqual(
            "load(load(storage:recoil:data:0x4e5ed0+0x828))",
            expected["storage_identity"],
        )
        self.assertEqual(0x0C, expected["slot_displacement"])

        label_unit = tuple(
            parse_assembly(
                "\n".join(
                    (
                        (
                            "0062a 8b 0d 28 08 00 00 mov ecx, DWORD PTR "
                            "?g_HudUiMgr@@3THudUiMgrDataStorage@@A+2088"
                        ),
                        "00634 8b 01 mov eax, DWORD PTR [ecx]",
                        "0063e ff 50 0c call DWORD PTR [eax+12]",
                    )
                ),
                source="cod",
            )
        )
        extracted = extract_invocation_contract(
            label_unit,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=fixture["indexes"],
            reviewed_absolute_storage_load_bridges=bridge,
        )
        self.assertEqual(
            "load(load(storage:recoil:data:0x4e5ed0+0x828))",
            extracted[0]["storage_identity"],
        )

        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register",
        ):
            extract_invocation_contract(
                label_unit,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=fixture["indexes"],
            )
        for name, malformed in {
            "register": replace(bridge["0x62a"], register="edx"),
            "storage": replace(
                bridge["0x62a"],
                storage_identity="storage:unreviewed",
            ),
        }.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "reviewed absolute-storage load bridge",
            ):
                extract_invocation_contract(
                    label_unit,
                    source="cod",
                    caller_identity=fixture["caller_identity"],
                    caller_start="0x410160",
                    caller_end_exclusive="0x410d10",
                    indexes=fixture["indexes"],
                    reviewed_absolute_storage_load_bridges={
                        "0x62a": malformed
                    },
                )
        unapproved = extract_invocation_contract(
            label_unit,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=fixture["indexes"],
            reviewed_absolute_storage_load_bridges={
                "0x62a": replace(
                    bridge["0x62a"],
                    canonicalize_nested_load=False,
                )
            },
        )
        self.assertEqual(
            (
                "load(exact-load(ecx,"
                "load(storage:recoil:data:0x4e5ed0+0x828)))"
            ),
            unapproved[0]["storage_identity"],
        )

