    def test_hud_ensure_objective_label_setpos_candidate_fails_closed(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_label_setpos_fixture()
        candidate = self._hud_ensure_objective_label_setpos_candidate(fixture)
        definition = candidate.caller_definition
        assert definition is not None
        addend = bytearray(definition.data)
        struct.pack_into("<I", addend, 0x62C, 0x82C)
        mask = list(definition.relocation_mask)
        mask[0x62C] = False
        cases = {
            "slot": replace(
                definition,
                data=(
                    definition.data[:0x63E]
                    + bytes.fromhex("ff 50 10")
                    + definition.data[0x641:]
                ),
            ),
            "addend": replace(definition, data=bytes(addend)),
            "mask": replace(definition, relocation_mask=tuple(mask)),
            "target": replace(
                definition,
                relocations=tuple(
                    replace(row, symbol_name="?WrongAggregate@@3HA")
                    if row.offset == 0x62C
                    else row
                    for row in definition.relocations
                ),
            ),
            "right-boundary": replace(
                definition,
                relocations=tuple(
                    replace(row, symbol_name="?WrongBoundary@@YAXXZ")
                    if row.offset == 0x64E
                    else row
                    for row in definition.relocations
                ),
            ),
        }
        for name, changed in cases.items():
            with self.subTest(name=name):
                with self.assertRaisesRegex(
                    ValueError,
                    (
                        "structural/COFF|exact ReadInt3|"
                        "contiguous ordered COD/COFF|DIR32/REL32|right boundary"
                    ),
                ):
                    self._hud_ensure_objective_label_setpos_bridge(
                        fixture,
                        replace(candidate, caller_definition=changed),
                    )

        expected = self._hud_ensure_objective_label_setpos_expected()
        expected[55] = {
            **expected[55],
            "target_identity": "symbol:recoil:function:0x404cd0",
        }
        with self.assertRaisesRegex(
            ValueError,
            "no unconditional direct target",
        ):
            self._hud_ensure_objective_label_setpos_bridge(
                fixture,
                candidate,
                expected=expected,
            )

