    def _hud_ensure_objective_label_settextfmt_repaired_candidate(
        self,
        candidate: CandidateAssembly,
    ) -> CandidateAssembly:
        definition = candidate.caller_definition
        assert definition is not None
        removed_offsets = {
            0x659,
            0x65E,
            0x65F,
            0x662,
            0x668,
            0x66B,
            0x67D,
        }
        retained = tuple(
            instruction
            for instruction in candidate.instructions
            if int(
                re.match(
                    r"^\s*([0-9a-fA-F]+)",
                    instruction.source_line,
                ).group(1),
                16,
            )
            not in removed_offsets
        )
        rows = (
            "00659 51 push ecx",
            "0065a ff 56 74 call DWORD PTR [esi+116]",
            (
                "0065d 8b 15 04 00 00 00 mov edx, DWORD PTR "
                "?g_HudUiMgrSensorFxRect@@3UHudUiRect@@A+4"
            ),
            "00663 83 c4 08 add esp, 8",
            "00666 52 push edx",
            (
                "00667 a1 00 00 00 00 mov eax, DWORD PTR "
                "?g_HudUiMgrSensorFxRect@@3UHudUiRect@@A"
            ),
            "00678 ff 52 0c call DWORD PTR [edx+12]",
        )
        added = tuple(parse_assembly("\n".join(rows), source="cod"))
        instructions = tuple(
            sorted(
                (*retained, *added),
                key=lambda instruction: int(
                    re.match(
                        r"^\s*([0-9a-fA-F]+)",
                        instruction.source_line,
                    ).group(1),
                    16,
                ),
            )
        )
        body = bytearray(definition.data)
        for instruction in added:
            match = re.match(
                r"^\s*([0-9a-fA-F]+)",
                instruction.source_line,
            )
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(int(value, 16) for value in instruction.bytes)
            body[offset : offset + len(encoded)] = encoded
        mask = list(definition.relocation_mask)
        for index in range(0x65A, 0x65E):
            mask[index] = False
        return replace(
            candidate,
            instructions=instructions,
            caller_definition=replace(
                definition,
                data=bytes(body),
                relocations=tuple(
                    row
                    for row in definition.relocations
                    if row.offset != 0x65A
                ),
                relocation_mask=tuple(mask),
            ),
        )

    def test_hud_ensure_objective_label_settextfmt_cached_vptr_converges(
        self,
    ) -> None:
        fixture = self._hud_ensure_objective_label_setpos_fixture()
        candidate = self._hud_ensure_objective_label_setpos_candidate(fixture)
        retail, absolute, current = (
            self._hud_ensure_objective_label_settextfmt_bridges(
                fixture,
                candidate,
            )
        )
        self.assertEqual({"0x4106d2"}, set(retail))
        self.assertEqual({"0x65f"}, set(current))
        for bridge in current.values():
            self.assertEqual("esi", bridge.register)
            self.assertEqual("virtual-slot", bridge.identity_kind)
            self.assertEqual(0x74, bridge.slot_displacement)
            self.assertEqual(
                "load(load(storage:recoil:data:0x4e5ed0+0x828))",
                bridge.storage_identity,
            )
        self.assertEqual("esi", retail["0x4106d2"].register)
        self.assertEqual(0x74, retail["0x4106d2"].slot_displacement)
        self.assertEqual(
            "load(load(storage:recoil:data:0x4e5ed0+0x828))",
            retail["0x4106d2"].storage_identity,
        )
        self.assertEqual("bn", retail["0x4106d2"].assembly_source)
        self.assertEqual(
            (
                "load(exact-load(eax,"
                "load(storage:recoil:data:0x4e5ed0+0x828)))"
            ),
            current["0x65f"].provenance,
        )

        candidate_unit = tuple(
            instruction
            for instruction in candidate.instructions
            if 0x641
            <= int(
                re.match(
                    r"^\s*([0-9a-fA-F]+)",
                    instruction.source_line,
                ).group(1),
                16,
            )
            <= 0x668
        )
        extracted = extract_invocation_contract(
            candidate_unit,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=fixture["indexes"],
            compiler_generated_bridges={
                "?GetMessageString@zLoc@@YIPADI@Z": (
                    "symbol:recoil:function:0x4a5bf0"
                )
            },
            reviewed_absolute_storage_load_bridges=absolute,
            reviewed_vptr_storage_bridges=current,
        )
        self.assertEqual(2, len(extracted))
        self.assertEqual(
            {
                "dispatch": "indirect",
                "identity_kind": "virtual-slot",
                "target_identity": "",
                "storage_identity": (
                    "load(load(storage:recoil:data:0x4e5ed0+0x828))"
                ),
                "slot_displacement": 0x74,
                "cleanup_bytes": 12,
            },
            {
                key: extracted[1][key]
                for key in (
                    "dispatch",
                    "identity_kind",
                    "target_identity",
                    "storage_identity",
                    "slot_displacement",
                    "cleanup_bytes",
                )
            },
        )

        expected = self._hud_ensure_objective_label_setpos_expected()[57]
        candidate_contract = {
            **expected,
            "cleanup_bytes": 12,
        }
        comparison = compare_call_contracts(
            [{**expected, "ordinal": 0}],
            [{**candidate_contract, "ordinal": 0}],
        )
        self.assertFalse(comparison["passed"])
        self.assertEqual(
            8,
            comparison["first_divergence"]["expected"]["cleanup_bytes"],
        )
        self.assertEqual(
            12,
            comparison["first_divergence"]["candidate"]["cleanup_bytes"],
        )
        self.assertEqual(
            "mismatch",
            comparison["first_divergence"]["kind"],
        )

