    def test_hud_ensure_ceil_exact_retail_iat_identity(
        self,
    ) -> None:
        fixture = self._hud_ensure_ceil_iat_fixture()
        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(self._hud_ensure_ceil_import_target(), {}),
        ):
            indexes = self._hud_ensure_ceil_iat_indexes(fixture)
        self.assertEqual(
            "iat:ceil",
            indexes.storage_by_address["0x4cc500"],
        )
        self.assertEqual("iat:ceil", indexes.storage_by_name["ceil"])
        self.assertEqual(
            "iat:ceil",
            indexes.storage_by_name["__imp__ceil"],
        )

        loop_bridges = self._hud_ensure_font_loop_bridges(
            fixture,
            indexes=indexes,
        )
        contract = extract_invocation_contract(
            fixture["instructions"],
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=indexes,
            reviewed_loop_vptr_storage_bridges=loop_bridges,
        )
        self.assertEqual(52, len(contract))
        self.assertEqual(
            {
                "ordinal": 51,
                "form": "call",
                "dispatch": "indirect",
                "identity_kind": "iat",
                "target_identity": "iat:ceil",
                "storage_identity": "iat:ceil",
                "slot_displacement": None,
                "cleanup_bytes": 8,
            },
            contract[-1],
        )

        candidate = tuple(
            parse_assembly(
                "\n".join(
                    (
                        "  00010 83 ec 08 sub esp, 8",
                        "  00013 dd 1c 24 fstp qword [esp], st0",
                        (
                            "  00016 ff 15 00 00 00 00 "
                            "call dword __imp__ceil"
                        ),
                        "  0001c 83 c4 08 add esp, 8",
                    )
                ),
                source="cod",
            )
        )
        self.assertEqual(
            {
                **contract[-1],
                "ordinal": 0,
            },
            extract_invocation_contract(
                candidate,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x410160",
                caller_end_exclusive="0x410d10",
                indexes=indexes,
            )[0],
        )

