    def test_hud_objective_ceil_rejects_call_shape_name_and_symbol_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_ceil_iat_fixture()

        def parsed(rows: Sequence[str]) -> tuple[Instruction, ...]:
            return tuple(parse_assembly("\n".join(rows), source="bn"))

        call_index = next(
            index
            for index, row in enumerate(fixture["rows"])
            if row.startswith("00411787 ")
        )
        shape_cases: dict[str, list[str]] = {}
        opcode = list(fixture["rows"])
        opcode[call_index] = (
            "00411787 ff 15 04 c5 4c 00 call dword [ceil]"
        )
        shape_cases["opcode"] = opcode
        address = list(fixture["rows"])
        address[call_index] = (
            "00411786 ff 15 00 c5 4c 00 call dword [ceil]"
        )
        shape_cases["address"] = address
        ordinal = list(fixture["rows"])
        ordinal.insert(
            call_index,
            "00411780 ff 50 60 call dword [eax+0x60]",
        )
        shape_cases["ordinal"] = ordinal
        cleanup = list(fixture["rows"])
        cleanup[-1] = "0041178d 83 c4 04 add esp, 4"
        shape_cases["cleanup"] = cleanup
        name = [
            row.replace("dword [ceil]", "dword [Ceil]")
            for row in fixture["rows"]
        ]
        shape_cases["name"] = name
        prior_slot = list(fixture["rows"])
        prior_slot[1] = "00411765 ff 50 64 call dword [eax+0x64]"
        shape_cases["prior-slot"] = prior_slot

        for name, rows in shape_cases.items():
            with patch(
                "_recoil.commands.call_contract_verify.retail_import_target",
                return_value=(self._hud_ensure_ceil_import_target(), {}),
            ), self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "exact retail argument|ordinal-2 FF15",
            ):
                self._hud_objective_ceil_iat_indexes(
                    fixture,
                    retail_instructions=parsed(rows),
                )

        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(self._hud_ensure_ceil_import_target(), {}),
        ):
            indexes = self._hud_objective_ceil_iat_indexes(fixture)
        bad_candidate = tuple(
            parse_assembly(
                "\n".join(
                    (
                        (
                            "  00010 ff 15 00 00 00 00 "
                            "call dword __imp__Ceil"
                        ),
                        "  00016 83 c4 08 add esp, 8",
                    )
                ),
                source="cod",
            )
        )
        with self.assertRaisesRegex(
            ValueError,
            "unresolved exact tracker-backed candidate IAT storage",
        ):
            extract_invocation_contract(
                bad_candidate,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x411760",
                caller_end_exclusive="0x4117f0",
                indexes=indexes,
            )

