    def test_hud_shield_ratio_ceil_exact_two_call_identity(
        self,
    ) -> None:
        fixture = self._hud_shield_ratio_ceil_iat_fixture()
        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(self._hud_ensure_ceil_import_target(), {}),
        ):
            indexes = self._hud_shield_ratio_ceil_iat_indexes(fixture)
        self.assertEqual("iat:ceil", indexes.storage_by_address["0x4cc500"])
        self.assertEqual("iat:ceil", indexes.storage_by_name["ceil"])
        self.assertEqual("iat:ceil", indexes.storage_by_name["__imp__ceil"])

        for call_address in ("00411fae", "00412002"):
            call_index = next(
                index
                for index, row in enumerate(fixture["rows"])
                if row.startswith(f"{call_address} ")
            )
            contract = extract_invocation_contract(
                tuple(
                    parse_assembly(
                        "\n".join(
                            fixture["rows"][call_index : call_index + 2]
                        ),
                        source="bn",
                    )
                ),
                source="bn",
                caller_identity=fixture["caller_identity"],
                caller_start="0x411f10",
                caller_end_exclusive="0x412050",
                indexes=indexes,
            )
            self.assertEqual("iat:ceil", contract[0]["target_identity"])
            self.assertEqual("iat:ceil", contract[0]["storage_identity"])
            self.assertEqual(8, contract[0]["cleanup_bytes"])

