    def test_hud_selected_progress_ceil_exact_retail_and_candidate_identity(
        self,
    ) -> None:
        fixture = self._hud_selected_progress_ceil_iat_fixture()
        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(self._hud_ensure_ceil_import_target(), {}),
        ):
            indexes = self._hud_selected_progress_ceil_iat_indexes(fixture)
        self.assertEqual("iat:ceil", indexes.storage_by_address["0x4cc500"])
        self.assertEqual("iat:ceil", indexes.storage_by_name["ceil"])
        self.assertEqual("iat:ceil", indexes.storage_by_name["__imp__ceil"])

        retail_contract = extract_invocation_contract(
            tuple(
                parse_assembly(
                    "\n".join(fixture["rows"][-3:-1]),
                    source="bn",
                )
            ),
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x4124b0",
            caller_end_exclusive="0x412620",
            indexes=indexes,
        )
        candidate_contract = extract_invocation_contract(
            fixture["candidate"].instructions[-2:],
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x4124b0",
            caller_end_exclusive="0x412620",
            indexes=indexes,
        )
        for contract in (retail_contract[0], candidate_contract[0]):
            self.assertEqual("call", contract["form"])
            self.assertEqual("indirect", contract["dispatch"])
            self.assertEqual("iat", contract["identity_kind"])
            self.assertEqual("iat:ceil", contract["target_identity"])
            self.assertEqual("iat:ceil", contract["storage_identity"])
            self.assertIsNone(contract["slot_displacement"])
            self.assertEqual(8, contract["cleanup_bytes"])

    def test_hud_selected_progress_ceil_rejects_authority_and_provider_drift(
        self,
    ) -> None:
        fixture = self._hud_selected_progress_ceil_iat_fixture()
        drifted = deepcopy(fixture["document"].data)
        drifted["symbols"]["recoil:function:0x4124b0"][
            "source_traceability"
        ]["source_edges"][0]["anchor_id"] = "recoil:anchor:wrong"
        authority_cases = {
            "caller": {"caller_identity": "symbol:recoil:function:0x4124c0"},
            "extent": {"caller_end_exclusive": "0x412610"},
            "tracker": {"document": ProgressDocument(drifted)},
        }
        for name, overrides in authority_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "current authored caller and source authority",
            ):
                self._hud_selected_progress_ceil_iat_indexes(
                    fixture,
                    **overrides,
                )

        target = fixture["candidate"].target
        contribution = target.translation_unit_function_order[0]
        rows = contribution.functions
        wrong_row = SimpleNamespace(
            **{
                **vars(rows[-1]),
                "symbol_regex": r"\?Wrong@HudUiMgrTarget@@.*",
            }
        )
        wrong_target = SimpleNamespace(
            **{
                **vars(target),
                "translation_unit_function_order": (
                    SimpleNamespace(
                        **{
                            **vars(contribution),
                            "functions": (*rows[:-1], wrong_row),
                        }
                    ),
                ),
            }
        )
        contribution_cases = {
            "symbol": replace(
                fixture["candidate"],
                caller_definition=replace(
                    fixture["candidate"].caller_definition,
                    symbol="?Wrong@HudUiMgrTarget@@YIXH@Z",
                ),
            ),
            "row": replace(fixture["candidate"], target=wrong_target),
        }
        for name, candidate in contribution_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "candidate contribution authority|authored hud.cpp contribution",
            ):
                self._hud_selected_progress_ceil_iat_indexes(
                    fixture,
                    candidate=candidate,
                )

        bad_type_rows = (
            replace(
                fixture["bridge_data_rows"][0],
                type_text="float (* const)(float)",
            ),
            fixture["bridge_data_rows"][1],
        )
        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(self._hud_ensure_ceil_import_target(), {}),
        ), self.assertRaisesRegex(ValueError, "typed IAT data row"):
            self._hud_selected_progress_ceil_iat_indexes(
                fixture,
                bridge_data_rows=bad_type_rows,
            )
        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(
                self._hud_ensure_ceil_import_target(dll="MSVCR71.dll"),
                {},
            ),
        ), self.assertRaisesRegex(ValueError, "immutable retail import tuple"):
            self._hud_selected_progress_ceil_iat_indexes(fixture)
        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(self._hud_ensure_ceil_import_target(), {}),
        ), self.assertRaisesRegex(ValueError, "retail slot bytes"):
            self._hud_selected_progress_ceil_iat_indexes(
                fixture,
                bridge=SimpleNamespace(
                    hexdump=lambda _address, _length: (
                        "4cc500  19 8e 7c 00"
                    )
                ),
            )

    def test_hud_selected_progress_ceil_rejects_retail_shape_and_order_drift(
        self,
    ) -> None:
        fixture = self._hud_selected_progress_ceil_iat_fixture()

        def parsed(rows: Sequence[str]) -> tuple[Instruction, ...]:
            return tuple(parse_assembly("\n".join(rows), source="bn"))

        call_index = fixture["rows"].index(
            "004125cd ff 15 00 c5 4c 00 call dword [ceil]"
        )
        shape_cases: dict[str, list[str]] = {}
        fpu = list(fixture["rows"])
        fpu[call_index - 4] = "004125c6 d8 c8 fmul st0, st0"
        shape_cases["fpu"] = fpu
        opcode = list(fixture["rows"])
        opcode[call_index] = (
            "004125cd ff 15 04 c5 4c 00 call dword [ceil]"
        )
        shape_cases["opcode"] = opcode
        cleanup = list(fixture["rows"])
        cleanup[call_index + 1] = "004125d3 83 c4 04 add esp, 4"
        shape_cases["cleanup"] = cleanup
        ordinal = list(fixture["rows"])
        ordinal.insert(
            call_index,
            "004125cc e8 00 00 00 00 call 0x500030",
        )
        shape_cases["ordinal"] = ordinal
        duplicate = list(fixture["rows"])
        duplicate.insert(
            call_index,
            "004125cc ff 15 00 c5 4c 00 call dword [ceil]",
        )
        shape_cases["duplicate"] = duplicate

        for name, rows in shape_cases.items():
            with patch(
                "_recoil.commands.call_contract_verify.retail_import_target",
                return_value=(self._hud_ensure_ceil_import_target(), {}),
            ), self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "exact retail argument|reviewed ordinal-3 FF15 ceil call",
            ):
                self._hud_selected_progress_ceil_iat_indexes(
                    fixture,
                    retail_instructions=parsed(rows),
                )

    def test_hud_selected_progress_ceil_rejects_candidate_call_drift(
        self,
    ) -> None:
        fixture = self._hud_selected_progress_ceil_iat_fixture()
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None

        def with_rows(rows: Sequence[str]) -> CandidateAssembly:
            return replace(
                candidate,
                instructions=tuple(
                    parse_assembly("\n".join(rows), source="cod")
                ),
            )

        wrong_operand = list(fixture["candidate_rows"])
        wrong_operand[-2] = (
            "0012d ff 15 00 00 00 00 call DWORD PTR __imp__floor"
        )
        wrong_cleanup = list(fixture["candidate_rows"])
        wrong_cleanup[-1] = "00133 83 c4 04 add esp, 4"
        extra_call = list(fixture["candidate_rows"])
        extra_call.insert(3, "00100 e8 00 00 00 00 call helper_extra")

        addend_body = bytearray(caller.data)
        struct.pack_into("<I", addend_body, 0x12F, 1)
        bad_mask = list(caller.relocation_mask)
        bad_mask[0x130] = False
        candidate_cases = {
            "operand": with_rows(wrong_operand),
            "cleanup": with_rows(wrong_cleanup),
            "ordinal": with_rows(extra_call),
            "relocation-type": replace(
                candidate,
                caller_definition=replace(
                    caller,
                    relocations=(
                        replace(caller.relocations[0], type=0x14),
                    ),
                ),
            ),
            "relocation-symbol": replace(
                candidate,
                caller_definition=replace(
                    caller,
                    relocations=(
                        replace(
                            caller.relocations[0],
                            symbol_name="__imp__floor",
                        ),
                    ),
                ),
            ),
            "relocation-addend": replace(
                candidate,
                caller_definition=replace(
                    caller,
                    data=bytes(addend_body),
                ),
            ),
            "relocation-mask": replace(
                candidate,
                caller_definition=replace(
                    caller,
                    relocation_mask=tuple(bad_mask),
                ),
            ),
            "external-identity": replace(
                candidate,
                caller_definition=replace(
                    caller,
                    undefined_external_functions=(
                        "helper_0",
                        "helper_1",
                        "helper_2",
                    ),
                ),
            ),
        }
        for name, changed in candidate_cases.items():
            with patch(
                "_recoil.commands.call_contract_verify.retail_import_target",
                return_value=(self._hud_ensure_ceil_import_target(), {}),
            ), self.subTest(name=name), self.assertRaisesRegex(
                ValueError, "rejects exact candidate ordinal-3 FF15",
            ):
                self._hud_selected_progress_ceil_iat_indexes(
                    fixture,
                    candidate=changed,
                )

