    def test_hud_selected_progress_set_visible_rejects_shape_and_topology(
        self,
    ) -> None:
        fixture = self._hud_selected_progress_set_visible_fixture()

        def retail(rows: Sequence[str]) -> tuple[Instruction, ...]:
            return tuple(parse_assembly("\n".join(rows), source="bn"))

        retail_cases: dict[str, list[str]] = {}
        wrong_false = list(fixture["rows"])
        wrong_false[1] = "00412546 6a 01 push 1"
        retail_cases["argument"] = wrong_false
        wrong_slot = list(fixture["rows"])
        wrong_slot[3] = "0041254d ff 52 64 call dword [edx+0x64]"
        retail_cases["slot"] = wrong_slot
        wrong_successor = list(fixture["rows"])
        wrong_successor[4] = (
            "00412550 8b 15 6c 6c 4e 00 "
            "mov edx, dword [0x4e6c6c]"
        )
        retail_cases["successor"] = wrong_successor
        earlier_call = list(fixture["rows"])
        earlier_call.insert(
            0,
            "00412530 e8 00 00 00 00 call 0x500000",
        )
        retail_cases["ordinal"] = earlier_call
        for name, rows in retail_cases.items():
            with self.subTest(name=f"retail-{name}"), self.assertRaisesRegex(
                ValueError,
                "exact retail|rejects retail",
            ):
                self._hud_selected_progress_set_visible_bridges(
                    fixture,
                    retail_instructions=retail(rows),
                )

        candidate = fixture["candidate"]
        definition = candidate.caller_definition
        assert definition is not None

        def replace_candidate_row(
            row_index: int,
            row: str,
        ) -> CandidateAssembly:
            instructions = list(candidate.instructions)
            replacement = tuple(parse_assembly(row, source="cod"))[0]
            instructions[row_index] = replacement
            match = re.match(
                r"^\s*([0-9a-fA-F]+)",
                replacement.source_line,
            )
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(
                int(value, 16) for value in replacement.bytes
            )
            body = bytearray(definition.data)
            body[offset : offset + len(encoded)] = encoded
            return replace(
                candidate,
                instructions=tuple(instructions),
                caller_definition=replace(
                    definition,
                    data=bytes(body),
                ),
            )

        candidate_cases = {
            "register": replace_candidate_row(
                0,
                (
                    "000a0 8b 0d 9c 0d 00 00 mov ecx, DWORD PTR "
                    "?g_HudUiMgr@@3THudUiMgrDataStorage@@A+3484"
                ),
            ),
            "argument": replace_candidate_row(
                1,
                "000a6 6a 01 push 1",
            ),
            "receiver": replace_candidate_row(
                2,
                (
                    "000a8 b8 9c 0d 00 00 mov eax, OFFSET FLAT:"
                    "?g_HudUiMgr@@3THudUiMgrDataStorage@@A+3484"
                ),
            ),
            "slot": replace_candidate_row(
                3,
                "000ad ff 52 64 call DWORD PTR [edx+100]",
            ),
            "successor": replace_candidate_row(
                4,
                (
                    "000b0 8b 15 9c 0d 00 00 mov edx, DWORD PTR "
                    "?g_HudUiMgr@@3THudUiMgrDataStorage@@A+3484"
                ),
            ),
            "topology": replace(
                candidate,
                local_control_flow_indices=frozenset({3}),
            ),
        }
        for name, changed in candidate_cases.items():
            with self.subTest(name=f"candidate-{name}"), self.assertRaisesRegex(
                ValueError,
                "exact candidate|rejects candidate",
            ):
                self._hud_selected_progress_set_visible_bridges(
                    fixture,
                    candidate=changed,
                )

