    def test_hud_update_objective_dirty_center_rejects_direct_shape_drift(
        self,
    ) -> None:
        fixture = self._hud_update_objective_dirty_center_fixture()
        direct = self._hud_update_objective_dirty_direct_candidate(fixture)
        definition = direct.caller_definition
        assert definition is not None

        bad_body = bytearray(definition.data)
        bad_body[0x8F] ^= 1
        bad_mask = list(definition.relocation_mask)
        bad_mask[0x74] = False
        definition_cases = {
            "body": replace(definition, data=bytes(bad_body)),
            "relocation": replace(
                definition,
                relocations=(
                    *definition.relocations[:8],
                    replace(
                        definition.relocations[8],
                        symbol_name="?WrongInvalidate@@YAXXZ",
                    ),
                    *definition.relocations[9:],
                ),
            ),
            "mask": replace(
                definition,
                relocation_mask=tuple(bad_mask),
            ),
            "missing-direct-external": replace(
                definition,
                undefined_external_functions=(
                    "?InvalidateRect@HudUiWidget@@QAEXPBUHudUiRect@@@Z",
                ),
            ),
        }
        for name, changed in definition_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "rejects candidate body",
            ):
                self._hud_update_objective_dirty_center_bridges(
                    fixture,
                    candidate=replace(
                        direct,
                        caller_definition=changed,
                    ),
                )

        instructions = list(direct.instructions)
        direct_call_index = next(
            index
            for index, instruction in enumerate(instructions)
            if "?Invalidate@HudUiElement@@UAEXXZ"
            in instruction.source_line
        )
        instructions[direct_call_index] = tuple(
            parse_assembly(
                "00073 e8 00 00 00 00 call ?WrongInvalidate@@YAXXZ",
                source="cod",
            )
        )[0]
        with self.assertRaisesRegex(ValueError, "topology drift"):
            self._hud_update_objective_dirty_center_bridges(
                fixture,
                candidate=replace(
                    direct,
                    instructions=tuple(instructions),
                ),
            )

        with self.assertRaisesRegex(ValueError, "topology drift"):
            self._hud_update_objective_dirty_center_bridges(
                fixture,
                candidate=replace(
                    direct,
                    local_control_flow_indices=frozenset(
                        {direct_call_index}
                    ),
                ),
            )

        cleanup_instructions = list(direct.instructions)
        cleanup_instructions.insert(
            direct_call_index + 1,
            tuple(
                parse_assembly(
                    "00078 83 c4 04 add esp, 4",
                    source="cod",
                )
            )[0],
        )
        with self.assertRaisesRegex(ValueError, "topology drift"):
            self._hud_update_objective_dirty_center_bridges(
                fixture,
                candidate=replace(
                    direct,
                    instructions=tuple(cleanup_instructions),
                ),
            )

        terminal_instructions = list(direct.instructions)
        terminal_instructions[-1] = tuple(
            parse_assembly("0008d 90 nop", source="cod")
        )[0]
        with self.assertRaisesRegex(ValueError, "topology drift"):
            self._hud_update_objective_dirty_center_bridges(
                fixture,
                candidate=replace(
                    direct,
                    instructions=tuple(terminal_instructions),
                ),
            )

        unresolved_indexes = replace(
            fixture["indexes"],
            by_candidate_name={
                **fixture["indexes"].by_candidate_name,
                "?Invalidate@HudUiElement@@UAEXXZ": "",
            },
        )
        with self.assertRaisesRegex(ValueError, "target identity authority"):
            self._hud_update_objective_dirty_center_bridges(
                fixture,
                candidate=direct,
                indexes=unresolved_indexes,
            )

        direct_target_drift = deepcopy(fixture["document"].data)
        direct_target_drift["symbols"]["recoil:function:0x4b4180"][
            "source_traceability"
        ]["source_edges"][0]["anchor_id"] = "recoil:anchor:wrong"
        with self.assertRaisesRegex(ValueError, "target identity authority"):
            self._hud_update_objective_dirty_center_bridges(
                fixture,
                candidate=direct,
                document=ProgressDocument(direct_target_drift),
            )

