                (0x74, 0x14, "?Invalidate@HudUiElement@@UAEXXZ"),
                (0x79, 0x06, "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"),
                (0x7E, 0x14, "?Draw@HudUiTripletPanel@@UAEXXZ"),
