    def test_hud_update_objective_dirty_center_rejects_dual_direct_drift(
        self,
    ) -> None:
        fixture = self._hud_update_objective_dirty_center_fixture()
        candidate = self._hud_update_objective_dirty_dual_direct_candidate(
            fixture
        )
        definition = candidate.caller_definition
        assert definition is not None

        bad_body = bytearray(definition.data)
        bad_body[0x8A] ^= 1
        bad_mask = list(definition.relocation_mask)
        bad_mask[0x7E] = False
        definition_cases = {
            "body": replace(definition, data=bytes(bad_body)),
            "relocation": replace(
                definition,
                relocations=(
                    *definition.relocations[:10],
                    replace(
                        definition.relocations[10],
                        symbol_name="?WrongDraw@@YAXXZ",
                    ),
                ),
            ),
            "mask": replace(
                definition,
                relocation_mask=tuple(bad_mask),
            ),
            "missing-draw-external": replace(
                definition,
                defined_external_functions=(),
            ),
            "wrong-undefined-draw-class": replace(
                definition,
                undefined_external_functions=(
                    *definition.undefined_external_functions,
                    "?Draw@HudUiTripletPanel@@UAEXXZ",
                ),
                defined_external_functions=(),
            ),
            "competing-draw-classes": replace(
                definition,
                undefined_external_functions=(
                    *definition.undefined_external_functions,
                    "?Draw@HudUiTripletPanel@@UAEXXZ",
                ),
            ),
            "duplicate-defined-draw": replace(
                definition,
                defined_external_functions=(
                    *definition.defined_external_functions,
                    "?Draw@HudUiTripletPanel@@UAEXXZ",
                ),
            ),
        }
        for name, changed in definition_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "rejects candidate body",
            ):
                self._hud_update_objective_dirty_center_bridges(
                    fixture,
                    candidate=replace(
                        candidate,
                        caller_definition=changed,
                    ),
                )

        instructions = list(candidate.instructions)
        draw_index = next(
            index
            for index, instruction in enumerate(instructions)
            if "?Draw@HudUiTripletPanel@@UAEXXZ"
            in instruction.source_line
        )
        instructions[draw_index] = tuple(
            parse_assembly(
                "0007d e8 00 00 00 00 call ?WrongDraw@@YAXXZ",
                source="cod",
            )
        )[0]
        with self.assertRaisesRegex(ValueError, "topology drift"):
            self._hud_update_objective_dirty_center_bridges(
                fixture,
                candidate=replace(
                    candidate,
                    instructions=tuple(instructions),
                ),
            )

        unresolved_indexes = replace(
            fixture["indexes"],
            by_address={
                **fixture["indexes"].by_address,
                "0x40f400": "",
            },
        )
        with self.assertRaisesRegex(
            ValueError,
            "target .*identity authority",
        ):
            self._hud_update_objective_dirty_center_bridges(
                fixture,
                candidate=candidate,
                indexes=unresolved_indexes,
            )

        target = candidate.target
        assert target is not None
        contribution = target.translation_unit_function_order[0]
        target_rows = tuple(contribution.functions)
        draw_row = next(
            row
            for row in target_rows
            if row.address == "0x40f400"
        )

        def with_target_rows(rows: tuple[object, ...]) -> CandidateAssembly:
            changed_contribution = SimpleNamespace(
                **{
                    **vars(contribution),
                    "functions": rows,
                }
            )
            changed_target = SimpleNamespace(
                **{
                    **vars(target),
                    "translation_unit_function_order": (
                        changed_contribution,
                    ),
                }
            )
            return replace(candidate, target=changed_target)

        registration_cases = {
            "missing": tuple(
                row for row in target_rows if row is not draw_row
            ),
            "drifted": tuple(
                SimpleNamespace(
                    **{
                        **vars(row),
                        "symbol": "?Draw@HudUiTripletPanel@@UAEXXZ",
                    }
                )
                if row is draw_row
                else row
                for row in target_rows
            ),
            "duplicate": (*target_rows, draw_row),
        }
        for name, rows in registration_cases.items():
            with self.subTest(
                registration=name
            ), self.assertRaisesRegex(
                ValueError,
                "target .*identity authority",
            ):
                self._hud_update_objective_dirty_center_bridges(
                    fixture,
                    candidate=with_target_rows(rows),
                )

