    def test_hud_update_objective_dirty_center_requires_immutable_retail_extent(
        self,
    ) -> None:
        fixture = self._hud_update_objective_dirty_center_fixture()
        retail_path = REPO_ROOT / "support" / "Recoil.exe"
        retail_data = bytearray(retail_path.read_bytes())
        exact_extent = bytes.fromhex(
            "a1 b8 65 4e 00 83 ec 10 85 c0 56 57 8b f9 74 06 "
            "0f bf 70 04 eb 02 33 f6 a1 7c 65 4e 00 b9 7c 65 4e 00 "
            "ff 50 64 8b 0d 78 65 4e 00 8b 15 7c 65 4e 00 03 c6 "
            "89 4c 24 10 b9 7c 65 4e 00 89 44 24 08 ff 52 68 "
            "8b 0d b8 65 4e 00 89 44 24 0c 85 c9 74 06 0f bf 49 06 "
            "eb 02 33 c9 03 c1 8d 8f b4 01 00 00 89 44 24 14 "
            "8d 44 24 08 50 e8 71 0b 0a 00 b9 f0 62 4e 00 "
            "e8 57 0e 0a 00 b9 f0 62 4e 00 e8 cd c0 ff ff "
            "5f 5e 83 c4 10 c3 90 90 90 90 90 90 90"
        )
        extent_offset = retail_data.find(exact_extent)
        self.assertGreaterEqual(extent_offset, 0)
        self.assertEqual(
            -1,
            retail_data.find(exact_extent, extent_offset + 1),
        )
        retail_data[extent_offset + len(exact_extent) - 1] ^= 1
        with tempfile.TemporaryDirectory() as temporary:
            changed_reference = Path(temporary) / "Recoil.exe"
            changed_reference.write_bytes(retail_data)
            with self.assertRaisesRegex(
                ValueError,
                "immutable support/Recoil.exe",
            ):
                self._hud_update_objective_dirty_center_bridges(
                    fixture,
                    reference=changed_reference,
                )

