    def test_hud_hide_tracked_progress_rejects_candidate_shape_and_topology(
        self,
    ) -> None:
        fixture = self._hud_hide_tracked_progress_set_visible_fixture()
        candidate = fixture["candidate"]
        definition = candidate.caller_definition
        assert definition is not None

        def replace_candidate_row(
            row_index: int,
            row: str,
        ) -> CandidateAssembly:
            instructions = list(candidate.instructions)
            replacement = tuple(parse_assembly(row, source="cod"))[0]
            instructions[row_index] = replacement
            match = re.match(
                r"^\s*([0-9a-fA-F]+)",
                replacement.source_line,
            )
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(
                int(value, 16) for value in replacement.bytes
            )
            body = bytearray(definition.data)
            body[offset : offset + len(encoded)] = encoded
            return replace(
                candidate,
                instructions=tuple(instructions),
                caller_definition=replace(
                    definition,
                    data=bytes(body),
                ),
            )

        aggregate = "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
        cases = {
            "tracked-storage": replace_candidate_row(
                0,
                (
                    "00000 a1 24 0c 00 00 mov eax, DWORD PTR "
                    f"{aggregate}+3108"
                ),
            ),
            "null-guard": replace_candidate_row(
                2,
                "00007 74 17 je SHORT $L84540",
            ),
            "owner-guard": replace_candidate_row(
                4,
                "0000c 39 48 08 cmp DWORD PTR [eax+8], ecx",
            ),
            "vptr": replace_candidate_row(
                6,
                (
                    "00011 8b 0d 9c 0d 00 00 mov ecx, DWORD PTR "
                    f"{aggregate}+3484"
                ),
            ),
            "argument": replace_candidate_row(
                7,
                "00017 6a 01 push 1",
            ),
            "receiver": replace_candidate_row(
                8,
                (
                    "00019 b8 9c 0d 00 00 mov eax, OFFSET FLAT:"
                    f"{aggregate}+3484"
                ),
            ),
            "slot": replace_candidate_row(
                9,
                "0001e ff 52 64 call DWORD PTR [edx+100]",
            ),
            "return": replace_candidate_row(
                10,
                "00021 90 nop",
            ),
            "local-switch": replace(
                candidate,
                local_control_flow_indices=frozenset({2}),
                local_control_flow_targets={2: (10,)},
            ),
        }
        for name, changed in cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "exact candidate|rejects candidate",
            ):
                self._hud_hide_tracked_progress_set_visible_bridges(
                    fixture,
                    candidate=changed,
                )

    def test_hud_hide_tracked_progress_rejects_relocation_drift(
        self,
    ) -> None:
        fixture = self._hud_hide_tracked_progress_set_visible_fixture()
        candidate = fixture["candidate"]
        definition = candidate.caller_definition
        assert definition is not None
        wrong_addend = bytearray(definition.data)
        wrong_addend[0x1A:0x1E] = struct.pack("<I", 0xDA0)
        wrong_padding = bytearray(definition.data)
        wrong_padding[-1] = 0
        relocation_cases = {
            "missing": replace(
                definition,
                relocations=definition.relocations[:-1],
            ),
            "extra": replace(
                definition,
                relocations=(
                    *definition.relocations,
                    replace(definition.relocations[0], offset=0x05),
                ),
            ),
            "type": replace(
                definition,
                relocations=(
                    replace(definition.relocations[0], type=0x14),
                    *definition.relocations[1:],
                ),
            ),
            "target": replace(
                definition,
                relocations=(
                    replace(
                        definition.relocations[0],
                        symbol_name="?g_Wrong@@3HA",
                    ),
                    *definition.relocations[1:],
                ),
            ),
            "addend": replace(
                definition,
                data=bytes(wrong_addend),
            ),
            "padding": replace(
                definition,
                data=bytes(wrong_padding),
            ),
            "mask": replace(
                definition,
                relocation_mask=tuple(
                    False if index == 0x13 else value
                    for index, value in enumerate(definition.relocation_mask)
                ),
            ),
            "external": replace(
                definition,
                undefined_external_data=(
                    "?g_HudUiMgr@@3THudUiMgrDataStorage@@A",
                    "?g_HudUiMgr@@3THudUiMgrDataStorage@@A",
                ),
            ),
        }
        for name, changed in relocation_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "DIR32 relocations",
            ):
                self._hud_hide_tracked_progress_set_visible_bridges(
                    fixture,
                    candidate=replace(
                        candidate,
                        caller_definition=changed,
                    ),
                )

