    def _hud_shield_meter_post_edit_candidate(
        self,
        fixture: dict,
    ) -> CandidateAssembly:
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None
        instructions = list(candidate.instructions)
        lea_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.source_line.strip().startswith("00048 ")
        )
        shifted = tuple(
            parse_assembly(
                "\n".join(
                    (
                        "00048 6a 00 push 0",
                        (
                            "0004a 8d b3 7c 03 00 00 "
                            "lea esi, DWORD PTR [ebx+892]"
                        ),
                    )
                ),
                source="cod",
            )
        )
        instructions[lea_index : lea_index + 1] = shifted
        body = bytearray(caller.data)
        body[0x48:0x50] = b"\x6a\x00\x8d\xb3\x7c\x03\x00\x00"
        return replace(
            candidate,
            instructions=tuple(instructions),
            caller_definition=replace(caller, data=bytes(body)),
        )

    def test_hud_shield_meter_affine_exact_retail_and_candidate_contract(
        self,
    ) -> None:
        fixture = self._hud_shield_ratio_ceil_iat_fixture()
        aggregate = "?g_HudUiMgr@@3THudUiMgrDataStorage@@A"
        candidate_layouts = {
            "pre-edit": fixture["candidate"],
            "post-edit": self._hud_shield_meter_post_edit_candidate(
                fixture
            ),
        }
        for name, candidate in candidate_layouts.items():
            with self.subTest(name=name):
                retail_bridges, candidate_bridges = (
                    self._hud_shield_meter_affine_bridges(
                        fixture,
                        candidate=candidate,
                    )
                )
                self.assertEqual(
                    {
                        "0x4e6dac": (
                            "storage:recoil:data:0x4e5ed0+0xedc"
                        )
                    },
                    retail_bridges,
                )
                self.assertEqual(
                    {
                        f"{aggregate}+3804": (
                            ReviewedStaticStorageReferenceBridge(
                                aggregate_symbol=aggregate,
                                displacement=0xEDC,
                                access_width=4,
                                storage_identity=(
                                    "storage:recoil:data:0x4e5ed0+0xedc"
                                ),
                            )
                        )
                    },
                    candidate_bridges,
                )

        retail_unit = tuple(
            instruction
            for instruction in fixture["instructions"]
            if (
                0x411FD6
                <= int(
                    re.match(
                        r"^0*([0-9a-fA-F]+)",
                        instruction.source_line.strip(),
                    ).group(1),
                    16,
                )
                <= 0x411FE7
            )
        )
        retail_bridges, candidate_bridges = (
            self._hud_shield_meter_affine_bridges(fixture)
        )
        candidate_unit = tuple(
            instruction
            for instruction in fixture["candidate"].instructions
            if int(
                re.match(
                    r"^\s*([0-9a-fA-F]+)",
                    instruction.source_line,
                ).group(1),
                16,
            )
            in {0x42, 0x48, 0x9B, 0xA1, 0xAD, 0xB0}
        )
        retail_contract = extract_invocation_contract(
            retail_unit,
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x411f10",
            caller_end_exclusive="0x412050",
            indexes=fixture["indexes"],
            reviewed_register_storage_bridges=retail_bridges,
        )
        candidate_contract = extract_invocation_contract(
            candidate_unit,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x411f10",
            caller_end_exclusive="0x412050",
            indexes=fixture["indexes"],
            reviewed_static_storage_reference_bridges=candidate_bridges,
        )
        self.assertEqual(retail_contract, candidate_contract)
        self.assertEqual(
            {
                "ordinal": 0,
                "form": "call",
                "dispatch": "indirect",
                "identity_kind": "virtual-slot",
                "target_identity": "",
                "storage_identity": (
                    "load(storage:recoil:data:0x4e5ed0+0xedc+0x37c)"
                ),
                "slot_displacement": 0x20,
                "cleanup_bytes": None,
            },
            retail_contract[0],
        )

