    def test_hud_shield_meter_affine_rejects_topology_and_cleanup(
        self,
    ) -> None:
        fixture = self._hud_shield_ratio_ceil_iat_fixture()

        def parsed(rows: Sequence[str]) -> tuple[Instruction, ...]:
            return tuple(parse_assembly("\n".join(rows), source="bn"))

        call_index = next(
            index
            for index, row in enumerate(fixture["rows"])
            if row.startswith("00411fe4 ")
        )
        retail_cases: dict[str, list[str]] = {}
        add = list(fixture["rows"])
        add[call_index - 2] = (
            "00411fdc 81 c1 78 03 00 00 add ecx, 0x378"
        )
        retail_cases["add"] = add
        slot = list(fixture["rows"])
        slot[call_index] = (
            "00411fe4 ff 52 24 call dword [edx+0x24]"
        )
        retail_cases["slot"] = slot
        ordinal = list(fixture["rows"])
        ordinal.insert(
            call_index,
            "00411fe3 e8 be 40 0b 00 call 0x4c60a6",
        )
        retail_cases["ordinal"] = ordinal
        cleanup = list(fixture["rows"])
        cleanup[call_index + 1] = (
            "00411fe7 83 c4 04 add esp, 4"
        )
        retail_cases["cleanup"] = cleanup
        for name, rows in retail_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "exact retail load|retail ordinal-5",
            ):
                self._hud_shield_meter_affine_bridges(
                    fixture,
                    retail_instructions=parsed(rows),
                )

        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None

        def changed_instruction(
            offset: int,
            row: str,
        ) -> CandidateAssembly:
            instructions = list(candidate.instructions)
            index = next(
                index
                for index, instruction in enumerate(instructions)
                if instruction.source_line.strip().startswith(
                    f"{offset:05x} "
                )
            )
            replacement = tuple(
                parse_assembly(row, source="cod")
            )[0]
            instructions[index] = replacement
            body = bytearray(caller.data)
            encoded = bytes(
                int(value, 16) for value in replacement.bytes
            )
            body[offset : offset + len(encoded)] = encoded
            return replace(
                candidate,
                instructions=tuple(instructions),
                caller_definition=replace(
                    caller,
                    data=bytes(body),
                ),
            )

        missing_vptr = tuple(
            instruction
            for instruction in candidate.instructions
            if not instruction.source_line.strip().startswith("000a1 ")
        )
        duplicate_rows = tuple(
            parse_assembly(
                "\n".join(
                    (
                        (
                            "00110 8d bb 7c 03 00 00 "
                            "lea edi, DWORD PTR [ebx+892]"
                        ),
                        "00116 8b cf mov ecx, edi",
                        "00118 8b 17 mov edx, DWORD PTR [edi]",
                        "0011a ff 52 20 call DWORD PTR [edx+32]",
                        "0011d 90 nop",
                    )
                ),
                source="cod",
            )
        )
        duplicate_body = bytearray(caller.data)
        duplicate_body.extend(
            b"\x00" * (0x140 - len(duplicate_body))
        )
        for instruction in duplicate_rows:
            match = re.match(
                r"^\s*([0-9a-fA-F]+)",
                instruction.source_line,
            )
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(
                int(value, 16) for value in instruction.bytes
            )
            duplicate_body[offset : offset + len(encoded)] = encoded
        duplicate_mask = (
            *caller.relocation_mask,
            *(False for _ in range(0x140 - len(caller.relocation_mask))),
        )
        candidate_cases = {
            "missing": replace(
                candidate,
                instructions=missing_vptr,
            ),
            "disconnected": changed_instruction(
                0x48,
                (
                    "00048 8d b7 7c 03 00 00 "
                    "lea esi, DWORD PTR [edi+892]"
                ),
            ),
            "receiver": changed_instruction(
                0x9B,
                "0009b 8b cb mov ecx, ebx",
            ),
            "slot": changed_instruction(
                0xAD,
                "000ad ff 50 24 call DWORD PTR [eax+36]",
            ),
            "cleanup": changed_instruction(
                0xB0,
                "000b0 83 c4 04 add esp, 4",
            ),
            "ambiguous": replace(
                candidate,
                instructions=(
                    *candidate.instructions,
                    *duplicate_rows,
                ),
                caller_definition=replace(
                    caller,
                    data=bytes(duplicate_body),
                    relocation_mask=tuple(duplicate_mask),
                ),
            ),
        }
        for name, changed in candidate_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "unique connected candidate",
            ):
                self._hud_shield_meter_affine_bridges(
                    fixture,
                    candidate=changed,
                )

        extra_call = tuple(
            parse_assembly(
                "00050 e8 00 00 00 00 call __ftol",
                source="cod",
            )
        )[0]
        extra_call_body = bytearray(caller.data)
        extra_call_body[0x50:0x55] = b"\xe8\x00\x00\x00\x00"
        extra_call_candidate = replace(
            candidate,
            instructions=(
                *candidate.instructions[:2],
                extra_call,
                *candidate.instructions[2:],
            ),
            caller_definition=replace(
                caller,
                data=bytes(extra_call_body),
            ),
        )
        self.assertTrue(
            self._hud_shield_meter_affine_bridges(
                fixture,
                candidate=extra_call_candidate,
            )[1]
        )

