    def _hud_refresh_counter_panel_bridges(
        self,
        fixture: dict,
        **overrides: object,
    ) -> tuple[
        dict[str, ReviewedStaticStorageReferenceBridge],
        dict[str, ReviewedLoopVptrStorageBridge],
    ]:
        expected = extract_invocation_contract(
            overrides.pop(
                "retail_instructions",
                fixture["retail_instructions"],
            ),
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x412050",
            caller_end_exclusive="0x412070",
            indexes=fixture["indexes"],
        )
        arguments = {
            "expected": expected,
            "retail_instructions": fixture["retail_instructions"],
            "candidate": fixture["candidate"],
            "document": fixture["document"],
            "caller_identity": fixture["caller_identity"],
            "caller_start": "0x412050",
            "caller_end_exclusive": "0x412070",
            "indexes": fixture["indexes"],
        }
        arguments.update(overrides)
        return (
            _hud_ui_mgr_objective_refresh_counter_panel_storage_bridges(
                **arguments
            )
        )

    def test_hud_refresh_counter_panel_exact_retail_candidate_contract(
        self,
    ) -> None:
        fixture = self._hud_refresh_counter_panel_fixture()
        static_bridges, member_bridges = (
            self._hud_refresh_counter_panel_bridges(fixture)
        )
        aggregate = fixture["aggregate"]
        self.assertEqual(
            {
                f"{aggregate}+3016":
                    ReviewedStaticStorageReferenceBridge(
                        aggregate_symbol=aggregate,
                        displacement=0xBC8,
                        access_width=4,
                        storage_identity=(
                            "storage:recoil:data:0x4e5ed0+0xbc8"
                        ),
                    )
            },
            static_bridges,
        )
        field_provenance = (
            "storage:recoil:data:0x4e5ed0+0xbc8"
        )
        self.assertEqual(
            {
                "0xd": ReviewedMemberVptrStorageBridge(
                    register="eax",
                    source_register="esi",
                    source_provenance=field_provenance,
                    receiver_register="esi",
                    receiver_provenance=field_provenance,
                    storage_identity=(
                        "load(load("
                        "storage:recoil:data:0x4e5ed0+0xbc8))"
                    ),
                    slot_displacement=0x74,
                    call_address="0x10",
                ),
                "0x13": ReviewedMemberVptrStorageBridge(
                    register="edx",
                    source_register="esi",
                    source_provenance=field_provenance,
                    receiver_register="ecx",
                    receiver_provenance=field_provenance,
                    storage_identity=(
                        "load(load("
                        "storage:recoil:data:0x4e5ed0+0xbc8))"
                    ),
                    slot_displacement=0x78,
                    call_address="0x1a",
                ),
            },
            member_bridges,
        )
        expected = extract_invocation_contract(
            fixture["retail_instructions"],
            source="bn",
            caller_identity=fixture["caller_identity"],
            caller_start="0x412050",
            caller_end_exclusive="0x412070",
            indexes=fixture["indexes"],
        )
        candidate = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x412050",
            caller_end_exclusive="0x412070",
            indexes=fixture["indexes"],
            reviewed_static_storage_reference_bridges=static_bridges,
            reviewed_member_vptr_storage_bridges=member_bridges,
        )
        self.assertEqual(expected, candidate)
        self.assertEqual(
            [
                {
                    "ordinal": 0,
                    "form": "call",
                    "dispatch": "indirect",
                    "identity_kind": "virtual-slot",
                    "target_identity": "",
                    "storage_identity": (
                        "load(load(storage:recoil:data:0x4e5ed0+0xbc8))"
                    ),
                    "slot_displacement": 0x74,
                    "cleanup_bytes": 12,
                },
                {
                    "ordinal": 1,
                    "form": "call",
                    "dispatch": "indirect",
                    "identity_kind": "virtual-slot",
                    "target_identity": "",
                    "storage_identity": (
                        "load(load(storage:recoil:data:0x4e5ed0+0xbc8))"
                    ),
                    "slot_displacement": 0x78,
                    "cleanup_bytes": None,
                },
            ],
            candidate,
        )

    def test_hud_refresh_counter_panel_rejects_authority_and_relocation_drift(
        self,
    ) -> None:
        fixture = self._hud_refresh_counter_panel_fixture()
        tracker_drift = deepcopy(fixture["document"].data)
        tracker_drift["symbols"]["recoil:function:0x412050"][
            "source_traceability"
        ]["source_edges"][0]["anchor_id"] = "recoil:anchor:wrong"
        owner_drift = deepcopy(fixture["document"].data)
        owner_drift["owners"]["recoil:owner:hud_ui.hud_ui_mgr_data"][
            "gates"
        ]["source"] = "blocked"
        authority_cases = {
            "caller": {
                "caller_identity": "symbol:recoil:function:0x411f10"
            },
            "extent": {"caller_end_exclusive": "0x412080"},
            "source": {"document": ProgressDocument(tracker_drift)},
            "owner": {"document": ProgressDocument(owner_drift)},
        }
        for name, overrides in authority_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "exact authored caller|exact reviewed aggregate",
            ):
                self._hud_refresh_counter_panel_bridges(
                    fixture,
                    **overrides,
                )

        target = fixture["candidate"].target
        contribution = target.translation_unit_function_order[0]
        row = contribution.functions[0]
        wrong_target = SimpleNamespace(
            **{
                **vars(target),
                "translation_unit_function_order": (
                    SimpleNamespace(
                        **{
                            **vars(contribution),
                            "functions": (
                                SimpleNamespace(
                                    **{
                                        **vars(row),
                                        "symbol_regex": (
                                            r"\?Wrong@HudUiMgrObjective@@.*"
                                        ),
                                    }
                                ),
                            ),
                        }
                    ),
                ),
            }
        )
        with self.assertRaisesRegex(
            ValueError,
            "exact authored hud.cpp contribution row",
        ):
            self._hud_refresh_counter_panel_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    target=wrong_target,
                ),
            )

        caller = fixture["candidate"].caller_definition
        assert caller is not None
        aggregate_relocation = caller.relocations[0]
        relocation_cases = {
            "missing": replace(
                caller,
                relocations=caller.relocations[1:],
            ),
            "duplicate": replace(
                caller,
                relocations=(
                    aggregate_relocation,
                    replace(aggregate_relocation, symbol_index=3),
                    *caller.relocations[1:],
                ),
            ),
            "type": replace(
                caller,
                relocations=(
                    replace(aggregate_relocation, type=0x14),
                    *caller.relocations[1:],
                ),
            ),
            "symbol": replace(
                caller,
                relocations=(
                    replace(
                        aggregate_relocation,
                        symbol_name="?g_Wrong@@3HA",
                    ),
                    *caller.relocations[1:],
                ),
            ),
            "mask": replace(
                caller,
                relocation_mask=tuple(
                    False if index == 0x03 else value
                    for index, value in enumerate(
                        caller.relocation_mask
                    )
                ),
            ),
            "addend": replace(
                caller,
                data=(
                    caller.data[:0x03]
                    + struct.pack("<I", 0xBC4)
                    + caller.data[0x07:]
                ),
            ),
            "owner": replace(
                caller,
                relocations=(
                    replace(aggregate_relocation, offset=0x1F),
                    *caller.relocations[1:],
                ),
            ),
        }
        for name, changed in relocation_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "aggregate\\+0xbc8|aggregate symbol",
            ):
                self._hud_refresh_counter_panel_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=changed,
                    ),
                )

    def test_hud_refresh_counter_panel_rejects_topology_cleanup_and_order(
        self,
    ) -> None:
        fixture = self._hud_refresh_counter_panel_fixture()
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None

        def changed_instruction(
            offset: int,
            row: str,
        ) -> CandidateAssembly:
            instructions = list(candidate.instructions)
            index = next(
                index
                for index, instruction in enumerate(instructions)
                if instruction.source_line.strip().startswith(
                    f"{offset:05x} "
                )
            )
            replacement = tuple(
                parse_assembly(row, source="cod")
            )[0]
            instructions[index] = replacement
            body = bytearray(caller.data)
            encoded = bytes(
                int(value, 16) for value in replacement.bytes
            )
            body[offset : offset + len(encoded)] = encoded
            return replace(
                candidate,
                instructions=tuple(instructions),
                caller_definition=replace(
                    caller,
                    data=bytes(body),
                ),
            )

        topology_cases = {
            "vptr": changed_instruction(
                0x0D,
                "0000d 8b 16 mov edx, DWORD PTR [esi]",
            ),
            "receiver": changed_instruction(
                0x0F,
                "0000f 57 push edi",
            ),
            "slot": changed_instruction(
                0x10,
                "00010 ff 50 78 call DWORD PTR [eax+120]",
            ),
            "cleanup": changed_instruction(
                0x15,
                "00015 83 c4 08 add esp, 8",
            ),
            "disconnected": changed_instruction(
                0x0D,
                "0000d 8b 07 mov eax, DWORD PTR [edi]",
            ),
        }
        for name, changed in topology_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "unique connected candidate",
            ):
                self._hud_refresh_counter_panel_bridges(
                    fixture,
                    candidate=changed,
                )

        extra_call = tuple(
            parse_assembly(
                "00007 e8 00 00 00 00 call __ftol",
                source="cod",
            )
        )[0]
        extra_body = bytearray(caller.data)
        extra_body[0x07:0x0C] = b"\xe8\x00\x00\x00\x00"
        with self.assertRaisesRegex(
            ValueError,
            "unique connected candidate",
        ):
            self._hud_refresh_counter_panel_bridges(
                fixture,
                candidate=replace(
                    candidate,
                    instructions=(
                        candidate.instructions[0],
                        extra_call,
                        *candidate.instructions[1:],
                    ),
                    caller_definition=replace(
                        caller,
                        data=bytes(extra_body),
                    ),
                ),
            )

        aggregate_relocation = caller.relocations[0]
        with self.assertRaisesRegex(
            ValueError,
            "one exact candidate aggregate\\+0xbc8 relocation",
        ):
            self._hud_refresh_counter_panel_bridges(
                fixture,
                candidate=replace(
                    candidate,
                    caller_definition=replace(
                        caller,
                        relocations=(
                            aggregate_relocation,
                            replace(
                                aggregate_relocation,
                                symbol_index=3,
                            ),
                            *caller.relocations[1:],
                        ),
                    ),
                ),
            )

