        body = bytearray(0x1D0)
        for instruction in parse_assembly(
            "\n".join(candidate_rows),
            source="cod",
        ):
            match = re.match(
                r"^\s*([0-9a-fA-F]{5})",
                instruction.source_line,
            )
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(int(value, 16) for value in instruction.bytes)
            body[offset : offset + len(encoded)] = encoded
        body[0x40:0x46] = b"\x8b\x0d\xc8\x0b\x00\x00"
        relocation = CoffRelocation(
            offset=0x42,
            symbol_index=1,
            type=0x06,
            symbol_name=aggregate,
        )
        mask = [False] * len(body)
        mask[0x42:0x46] = [True] * 4
        candidate = CandidateAssembly(
            instructions=tuple(
                parse_assembly(
                    "\n".join(candidate_rows),
                    source="cod",
                )
            ),
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
            target=target,
            caller_definition=CandidateCallerDefinition(
                symbol=caller_symbol,
                data=bytes(body),
                relocations=(relocation,),
                relocation_mask=tuple(mask),
                undefined_external_functions=(),
                defined_external_functions=(),
                undefined_external_data=(aggregate,),
                defined_external_data=(),
            ),
        )
        expected = [
            {
                "ordinal": ordinal,
                "form": "call",
                "dispatch": "direct",
                "identity_kind": "direct",
                "target_identity": f"symbol:recoil:function:0x{500000 + ordinal:x}",
                "storage_identity": "",
                "slot_displacement": None,
                "cleanup_bytes": None,
            }
            for ordinal in range(4)
        ]
        expected.append(
            {
                "ordinal": 4,
                "form": "call",
                "dispatch": "indirect",
                "identity_kind": "virtual-slot",
                "target_identity": "",
                "storage_identity": "load(this)",
                "slot_displacement": 0x18,
                "cleanup_bytes": None,
            }
        )
        expected.append(
            {
                "ordinal": 5,
                "form": "call",
                "dispatch": "indirect",
                "identity_kind": "virtual-slot",
                "target_identity": "",
                "storage_identity": (
                    "load(load(storage:recoil:data:0x4e5ed0+0xbc8))"
                ),
                "slot_displacement": 0x18,
                "cleanup_bytes": None,
            }
        )
        indexes = replace(
            shared["indexes"],
            by_address={
                **shared["indexes"].by_address,
                "0x4130d0": caller_identity,
            },
        )
        return {
            "aggregate": aggregate,
            "caller_identity": caller_identity,
            "candidate": candidate,
            "document": ProgressDocument(data),
            "expected": expected,
            "indexes": indexes,
        }

