    def test_hud_layout_set_active_objective_rejects_topology_drift(
        self,
    ) -> None:
        fixture = self._hud_layout_set_active_objective_fixture()
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None

        def changed_instruction(
            offset: int,
            row: str,
        ) -> CandidateAssembly:
            instructions = list(candidate.instructions)
            index = next(
                index
                for index, instruction in enumerate(instructions)
                if instruction.source_line.strip().startswith(
                    f"{offset:05x} "
                )
            )
            replacement = tuple(parse_assembly(row, source="cod"))[0]
            instructions[index] = replacement
            body = bytearray(caller.data)
            encoded = bytes(
                int(value, 16) for value in replacement.bytes
            )
            body[offset : offset + len(encoded)] = encoded
            return replace(
                candidate,
                instructions=tuple(instructions),
                caller_definition=replace(
                    caller,
                    data=bytes(body),
                ),
            )

        cleanup = tuple(
            parse_assembly(
                "0004f 83 c4 08 add esp, 8",
                source="cod",
            )
        )[0]
        cleanup_body = bytearray(caller.data)
        cleanup_body[0x4F:0x52] = b"\x83\xc4\x08"
        extra_call = tuple(
            parse_assembly(
                "00020 e8 00 00 00 00 call 0x500020",
                source="cod",
            )
        )[0]
        extra_call_body = bytearray(caller.data)
        extra_call_body[0x20:0x25] = b"\xe8\x00\x00\x00\x00"
        cases = {
            "first-zero": changed_instruction(
                0x46,
                "00046 6a 01 push 1",
            ),
            "second-zero": changed_instruction(
                0x48,
                "00048 6a 01 push 1",
            ),
            "receiver": changed_instruction(
                0x4A,
                "0004a 8b 10 mov edx, DWORD PTR [eax]",
            ),
            "slot": changed_instruction(
                0x4C,
                "0004c ff 52 1c call DWORD PTR [edx+28]",
            ),
            "cleanup": replace(
                candidate,
                instructions=(*candidate.instructions, cleanup),
                caller_definition=replace(
                    caller,
                    data=bytes(cleanup_body),
                ),
            ),
            "order": replace(
                candidate,
                instructions=(
                    *candidate.instructions[:4],
                    extra_call,
                    *candidate.instructions[4:],
                ),
                caller_definition=replace(
                    caller,
                    data=bytes(extra_call_body),
                ),
            ),
        }
        for name, changed in cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "exact ECX-load|receiver|call order",
            ):
                self._hud_layout_set_active_objective_bridges(
                    fixture,
                    candidate=changed,
                )

        retail_drift = deepcopy(fixture["expected"])
        retail_drift[5]["slot_displacement"] = 0x1C
        with self.assertRaisesRegex(
            ValueError,
            "immutable retail ordinal-5",
        ):
            self._hud_layout_set_active_objective_bridges(
                fixture,
                expected=retail_drift,
            )

