    def test_hud_layout_set_active_static_census_returns_exact_bridges(
        self,
    ) -> None:
        fixture = self._hud_layout_set_active_static_census_fixture()
        static_bridges, loop_bridges = (
            self._hud_layout_set_active_static_census(fixture)
        )
        aggregate = fixture["aggregate"]
        self.assertEqual(
            {
                f"{aggregate}+1056",
                f"{aggregate}+3016",
                f"{aggregate}+18308",
            },
            set(static_bridges),
        )
        self.assertEqual(
            {"0x6d", "0xe7", "0xf5", "0x135"},
            set(loop_bridges),
        )
        self.assertEqual(
            "load(storage:recoil:data:0x4e5ed0+0x420)",
            loop_bridges["0x6d"].storage_identity,
        )
        self.assertEqual(
            "load(storage:recoil:data:0x4e5ed0+0x420)",
            loop_bridges["0x135"].storage_identity,
        )

    def test_hud_layout_set_active_static_census_rejects_topology_drift(
        self,
    ) -> None:
        fixture = self._hud_layout_set_active_static_census_fixture()
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None
        changed_body = bytearray(caller.data)
        changed_body[0x66] = 0x6B
        with self.assertRaisesRegex(ValueError, "first NanitePanel body"):
            self._hud_layout_set_active_static_census(
                fixture,
                candidate=replace(
                    candidate,
                    caller_definition=replace(
                        caller,
                        data=bytes(changed_body),
                    ),
                ),
            )
        changed_expected = deepcopy(fixture["expected"])
        changed_expected[15]["slot_displacement"] = 0x1C
        with self.assertRaisesRegex(ValueError, "immutable retail"):
            self._hud_layout_set_active_static_census(
                fixture,
                expected=changed_expected,
            )

    def test_hud_layout_set_active_static_census_rejects_coff_and_origin_drift(
        self,
    ) -> None:
        fixture = self._hud_layout_set_active_static_census_fixture()
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None
        changed_relocations = tuple(
            replace(relocation, type=0x14)
            if relocation.offset == 0x60
            else relocation
            for relocation in caller.relocations
        )
        with self.assertRaisesRegex(ValueError, "first NanitePanel body/COFF"):
            self._hud_layout_set_active_static_census(
                fixture,
                candidate=replace(
                    candidate,
                    caller_definition=replace(
                        caller,
                        relocations=changed_relocations,
                    ),
                ),
            )
        instructions = list(candidate.instructions)
        origin_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.source_line.strip().startswith("000d6 ")
        )
        instructions[origin_index] = tuple(
            parse_assembly(
                "000d6 8b 9e 2c 01 00 00 "
                "mov ebx, DWORD PTR [esi+300]",
                source="cod",
            )
        )[0]
        with self.assertRaisesRegex(ValueError, "argument-origin drift"):
            self._hud_layout_set_active_static_census(
                fixture,
                candidate=replace(
                    candidate,
                    instructions=tuple(instructions),
                ),
            )

