    def test_hud_layout_set_active_active_first_complete_variant(
        self,
    ) -> None:
        fixture = self._hud_layout_set_active_active_first_fixture()
        objective_static, objective_loop = (
            self._hud_layout_set_active_objective_bridges(fixture)
        )
        timer_static, timer_member = (
            self._hud_layout_set_active_timer_bridges(fixture)
        )
        census_static, census_loop = (
            self._hud_layout_set_active_static_census(fixture)
        )
        message_loop = self._hud_layout_set_active_message_loops(fixture)
        aggregate = fixture["aggregate"]
        self.assertEqual({f"{aggregate}+3016"}, set(objective_static))
        self.assertEqual({"0x5e"}, set(objective_loop))
        self.assertEqual({f"{aggregate}+18308"}, set(timer_static))
        self.assertEqual({"0x6a"}, set(timer_member))
        self.assertEqual(
            {
                f"{aggregate}+1056",
                f"{aggregate}+3016",
                f"{aggregate}+18308",
            },
            set(census_static),
        )
        self.assertEqual(
            {"0xab", "0x155", "0x164", "0x175"},
            set(census_loop),
        )
        self.assertEqual(
            {"0x7b", "0x8d", "0x185", "0x198"},
            set(message_loop),
        )

