    def _hud_track_counter_slot_current_candidate(
        self,
        fixture: dict,
    ) -> CandidateAssembly:
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None
        replaced_offsets = {0x7F, 0x81, 0x82, 0x83, 0x85}
        instructions = [
            instruction
            for instruction in candidate.instructions
            if int(instruction.source_line.split()[0], 16)
            not in replaced_offsets
        ]
        instructions.extend(
            parse_assembly(
                "\n".join(
                    (
                        "00073 8b 2e mov ebp, DWORD PTR [esi]",
                        "00075 e8 00 00 00 00 call __ftol",
                        "0007a 50 push eax",
                        "0007b 57 push edi",
                        "0007c 8b ce mov ecx, esi",
                        "0007e ff 55 0c call DWORD PTR [ebp+12]",
                    )
                ),
                source="cod",
            )
        )
        instructions.sort(
            key=lambda instruction: int(
                instruction.source_line.split()[0],
                16,
            )
        )
        body = bytearray(caller.data)
        body[0x73:0x89] = b"\0" * (0x89 - 0x73)
        for offset, instruction_body in (
            (0x73, b"\x8b\x2e"),
            (0x75, b"\xe8\0\0\0\0"),
            (0x7A, b"\x50"),
            (0x7B, b"\x57"),
            (0x7C, b"\x8b\xce"),
            (0x7E, b"\xff\x55\x0c"),
        ):
            body[offset : offset + len(instruction_body)] = instruction_body
        ftol_relocation = CoffRelocation(0x76, 4, 0x14, "__ftol")
        relocations = (*caller.relocations, ftol_relocation)
        relocation_mask = list(caller.relocation_mask)
        relocation_mask[0x76:0x7A] = [True] * 4
        return replace(
            candidate,
            instructions=tuple(instructions),
            caller_definition=replace(
                caller,
                data=bytes(body),
                relocations=relocations,
                relocation_mask=tuple(relocation_mask),
                undefined_external_functions=("__ftol",),
            ),
        )

    def _hud_track_counter_slot_frame_candidate(
        self,
        fixture: dict,
        *,
        frame_size: int,
        cleanup_size: int | None = None,
        missing_allocation: bool = False,
        missing_cleanup: bool = False,
        duplicate_allocation: bool = False,
        duplicate_cleanup: bool = False,
    ) -> CandidateAssembly:
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None
        cleanup_size = (
            frame_size if cleanup_size is None else cleanup_size
        )
        replaced_offsets = {0x00, 0x1F}
        instructions = [
            instruction
            for instruction in candidate.instructions
            if int(instruction.source_line.split()[0], 16)
            not in replaced_offsets
        ]
        rows: list[str] = []
        if not missing_allocation:
            rows.append(
                f"00000 83 ec {frame_size:02x} sub esp, {frame_size}"
            )
        if not missing_cleanup:
            rows.append(
                f"0001f 83 c4 {cleanup_size:02x} "
                f"add esp, {cleanup_size}"
            )
        if duplicate_allocation:
            rows.append(
                f"00015 83 ec {frame_size:02x} sub esp, {frame_size}"
            )
        if duplicate_cleanup:
            rows.append(
                f"00015 83 c4 {frame_size:02x} add esp, {frame_size}"
            )
        instructions.extend(
            parse_assembly("\n".join(rows), source="cod")
        )
        instructions.sort(
            key=lambda instruction: int(
                instruction.source_line.split()[0],
                16,
            )
        )
        body = bytearray(caller.data)
        body[0x00:0x03] = b"\0\0\0"
        body[0x1F:0x22] = b"\0\0\0"
        body[0x15:0x18] = b"\0\0\0"
        if not missing_allocation:
            body[0x00:0x03] = bytes((0x83, 0xEC, frame_size))
        if not missing_cleanup:
            body[0x1F:0x22] = bytes((0x83, 0xC4, cleanup_size))
        if duplicate_allocation:
            body[0x15:0x18] = bytes((0x83, 0xEC, frame_size))
        if duplicate_cleanup:
            body[0x15:0x18] = bytes((0x83, 0xC4, frame_size))
        return replace(
            candidate,
            instructions=tuple(instructions),
            caller_definition=replace(caller, data=bytes(body)),
        )

