    def test_hud_track_counter_slot_structural_chain_drift_fails(
        self,
    ) -> None:
        fixture = self._hud_track_counter_slot_fixture()
        current = self._hud_track_counter_slot_current_candidate(fixture)
        caller = current.caller_definition
        assert caller is not None

        def candidate_with_row(
            offset: int,
            row: str | None,
            instruction_body: bytes,
        ) -> CandidateAssembly:
            instructions = [
                instruction
                for instruction in current.instructions
                if int(instruction.source_line.split()[0], 16) != offset
            ]
            if row is not None:
                instructions.extend(parse_assembly(row, source="cod"))
            instructions.sort(
                key=lambda instruction: int(
                    instruction.source_line.split()[0],
                    16,
                )
            )
            data = bytearray(caller.data)
            data[offset : offset + max(3, len(instruction_body))] = (
                b"\0" * max(3, len(instruction_body))
            )
            data[offset : offset + len(instruction_body)] = instruction_body
            return replace(
                current,
                instructions=tuple(instructions),
                caller_definition=replace(caller, data=bytes(data)),
            )

        cases = (
            ("missing", candidate_with_row(0x7E, None, b"")),
            (
                "receiver register",
                candidate_with_row(
                    0x7C,
                    "0007c 8b cf mov ecx, edi",
                    b"\x8b\xcf",
                ),
            ),
            (
                "slot",
                candidate_with_row(
                    0x7E,
                    "0007e ff 55 10 call DWORD PTR [ebp+16]",
                    b"\xff\x55\x10",
                ),
            ),
        )
        for label, changed_candidate in cases:
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "unique connected candidate",
            ):
                self._hud_track_counter_slot_bridges(
                    fixture,
                    candidate=changed_candidate,
                )

        cleanup_instruction = parse_assembly(
            "00081 83 c4 08 add esp, 8",
            source="cod",
        )[0]
        cleanup_body = bytearray(caller.data)
        cleanup_body[0x81:0x84] = b"\x83\xc4\x08"
        cleanup_candidate = replace(
            current,
            instructions=tuple(
                sorted(
                    (*current.instructions, cleanup_instruction),
                    key=lambda instruction: int(
                        instruction.source_line.split()[0],
                        16,
                    ),
                )
            ),
            caller_definition=replace(
                caller,
                data=bytes(cleanup_body),
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "unique connected candidate",
        ):
            self._hud_track_counter_slot_bridges(
                fixture,
                candidate=cleanup_candidate,
            )

    def test_hud_track_counter_slot_duplicate_or_disconnected_chain_fails(
        self,
    ) -> None:
        fixture = self._hud_track_counter_slot_fixture()
        current = self._hud_track_counter_slot_current_candidate(fixture)
        caller = current.caller_definition
        assert caller is not None
        duplicate_rows = parse_assembly(
            "\n".join(
                (
                    "00082 8b 16 mov edx, DWORD PTR [esi]",
                    "00084 50 push eax",
                    "00085 57 push edi",
                    "00086 8b ce mov ecx, esi",
                    "00088 ff 52 0c call DWORD PTR [edx+12]",
                )
            ),
            source="cod",
        )
        duplicate_body = bytearray(caller.data)
        for offset, instruction_body in (
            (0x82, b"\x8b\x16"),
            (0x84, b"\x50"),
            (0x85, b"\x57"),
            (0x86, b"\x8b\xce"),
            (0x88, b"\xff\x52\x0c"),
        ):
            duplicate_body[
                offset : offset + len(instruction_body)
            ] = instruction_body
        duplicate_candidate = replace(
            current,
            instructions=tuple(
                sorted(
                    (*current.instructions, *duplicate_rows),
                    key=lambda instruction: int(
                        instruction.source_line.split()[0],
                        16,
                    ),
                )
            ),
            caller_definition=replace(
                caller,
                data=bytes(duplicate_body),
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "one unique connected candidate",
        ):
            self._hud_track_counter_slot_bridges(
                fixture,
                candidate=duplicate_candidate,
            )

        vptr_index = next(
            index
            for index, instruction in enumerate(current.instructions)
            if instruction.source_line.startswith("00073 ")
        )
        disconnected_candidate = replace(
            current,
            local_control_flow_targets={0: (vptr_index,)},
        )
        with self.assertRaisesRegex(
            ValueError,
            "unique connected candidate",
        ):
            self._hud_track_counter_slot_bridges(
                fixture,
                candidate=disconnected_candidate,
            )

    def test_hud_track_counter_slot_relocation_type_and_authority_fail(
        self,
    ) -> None:
        fixture = self._hud_track_counter_slot_fixture()
        candidate = self._hud_track_counter_slot_current_candidate(fixture)
        caller = candidate.caller_definition
        assert caller is not None
        changed_relocations = tuple(
            replace(relocation, type=0x14)
            if relocation.offset == 0x34
            else relocation
            for relocation in caller.relocations
        )
        with self.assertRaisesRegex(ValueError, "aggregate\\+0xefc"):
            self._hud_track_counter_slot_bridges(
                fixture,
                candidate=replace(
                    candidate,
                    caller_definition=replace(
                        caller,
                        relocations=changed_relocations,
                    ),
                ),
            )

        changed_document_data = deepcopy(fixture["document"].data)
        changed_document_data["symbols"][
            "recoil:function:0x412070"
        ]["source_traceability"]["source_edges"][0][
            "emission_context"
        ] = {"translation_unit": "src/Battlesport/not_hud.cpp"}
        with self.assertRaisesRegex(ValueError, "exact authored caller"):
            self._hud_track_counter_slot_bridges(
                fixture,
                candidate=candidate,
                document=ProgressDocument(changed_document_data),
            )

