    def test_hud_track_counter_switch_three_way_tail_drift_fails(
        self,
    ) -> None:
        fixture = self._hud_track_counter_switch_three_way_fixture()
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None
        original_offsets = [
            int(instruction.source_line.split()[0], 16)
            for instruction in candidate.instructions
        ]
        original_dispatch_index = next(
            iter(candidate.local_control_flow_indices)
        )
        dispatch_offset = original_offsets[original_dispatch_index]
        target_offsets = tuple(
            original_offsets[index]
            for index in candidate.local_control_flow_targets[
                original_dispatch_index
            ]
        )

        def changed_row(
            offset: int,
            row: str | None,
            instruction_body: bytes,
            prior_size: int,
        ) -> CandidateAssembly:
            instructions = [
                instruction
                for instruction in candidate.instructions
                if int(instruction.source_line.split()[0], 16) != offset
            ]
            if row is not None:
                instructions.extend(parse_assembly(row, source="cod"))
            instructions.sort(
                key=lambda instruction: int(
                    instruction.source_line.split()[0],
                    16,
                )
            )
            data = bytearray(caller.data)
            data[offset : offset + max(prior_size, len(instruction_body))] = (
                b"\0" * max(prior_size, len(instruction_body))
            )
            data[offset : offset + len(instruction_body)] = instruction_body
            index_by_offset = {
                int(instruction.source_line.split()[0], 16): index
                for index, instruction in enumerate(instructions)
            }
            new_dispatch_index = index_by_offset[dispatch_offset]
            return replace(
                candidate,
                instructions=tuple(instructions),
                local_control_flow_indices=frozenset(
                    {new_dispatch_index}
                ),
                local_control_flow_targets={
                    new_dispatch_index: tuple(
                        index_by_offset[target_offset]
                        for target_offset in target_offsets
                    )
                },
                caller_definition=replace(caller, data=bytes(data)),
            )

        cases = (
            (
                "wrong-case4-target",
                changed_row(
                    0x1C8,
                    "001c8 eb 55 jmp $Ldefault",
                    b"\xeb\x55",
                    2,
                ),
                "equal case-8 shared tails",
            ),
            (
                "missing-case4-vptr",
                changed_row(0x1BB, None, b"", 2),
                "case-4",
            ),
            (
                "wrong-shared-receiver",
                changed_row(
                    0x215,
                    "00215 8b cb mov ecx, ebx",
                    b"\x8b\xcb",
                    2,
                ),
                "embedded \\+0x48 widget storage",
            ),
            (
                "wrong-shared-vptr",
                changed_row(
                    0x21C,
                    "0021c ff 50 0c call dword [eax+12]",
                    b"\xff\x50\x0c",
                    3,
                ),
                "unique connected candidate vptr",
            ),
            (
                "missing-shared-argument",
                changed_row(0x208, None, b"", 1),
                "case-8",
            ),
            (
                "missing-shared-call",
                changed_row(0x21C, None, b"", 3),
                "population/order drift in candidate case-8",
            ),
        )
        for label, changed, message in cases:
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                message,
            ):
                self._hud_track_counter_switch_bridges(
                    fixture,
                    candidate=changed,
                )

    def test_hud_track_counter_switch_consumes_structural_base_authority(
        self,
    ) -> None:
        fixture = self._hud_track_counter_switch_fixture()
        storage = "load(address(hud-ui-weapon-slot-array-element))"
        retail_base = {
            "0x4120ea": ReviewedLoopVptrStorageBridge(
                register="ebp",
                storage_identity=storage,
                slot_displacement=0x0C,
                assembly_source="bn",
            )
        }
        structural_candidate_base = {
            "0x85": ReviewedLoopVptrStorageBridge(
                register="eax",
                storage_identity=storage,
                slot_displacement=0x0C,
                assembly_source="cod",
            )
        }
        helper_path = (
            "_recoil.commands.call_contract_verify."
            "_hud_ui_mgr_sensor_track_counter_slot_vptr_bridges"
        )
        with patch(
            helper_path,
            return_value=(retail_base, structural_candidate_base),
        ):
            retail, candidate = self._hud_track_counter_switch_bridges(
                fixture
            )
        self.assertEqual(13, len(retail))
        self.assertEqual(15, len(candidate))

        wrong_candidate_base = {
            "0x85": replace(
                structural_candidate_base["0x85"],
                storage_identity="load(address(unreviewed-element))",
            )
        }
        with patch(
            helper_path,
            return_value=(retail_base, wrong_candidate_base),
        ), self.assertRaisesRegex(
            ValueError,
            "WSI-010's exact structural",
        ):
            self._hud_track_counter_switch_bridges(fixture)

