    def test_hud_track_counter_switch_structural_candidate_drift_fails(
        self,
    ) -> None:
        fixture = self._hud_track_counter_switch_fixture()
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None

        original_offsets = [
            int(instruction.source_line.split()[0], 16)
            for instruction in candidate.instructions
        ]
        original_dispatch_index = next(
            iter(candidate.local_control_flow_indices)
        )
        dispatch_offset = original_offsets[original_dispatch_index]
        target_offsets = tuple(
            original_offsets[index]
            for index in candidate.local_control_flow_targets[
                original_dispatch_index
            ]
        )

        def remapped_control_flow(
            instructions: list | tuple,
        ) -> tuple[frozenset[int], dict[int, tuple[int, ...]]]:
            index_by_offset = {
                int(instruction.source_line.split()[0], 16): index
                for index, instruction in enumerate(instructions)
            }
            new_dispatch_index = index_by_offset[dispatch_offset]
            return (
                frozenset({new_dispatch_index}),
                {
                    new_dispatch_index: tuple(
                        index_by_offset[offset]
                        for offset in target_offsets
                    )
                },
            )

        def changed_candidate(
            *,
            offset: int,
            row: str | None,
            instruction_body: bytes,
            prior_size: int,
        ) -> CandidateAssembly:
            instructions = [
                instruction
                for instruction in candidate.instructions
                if int(instruction.source_line.split()[0], 16) != offset
            ]
            if row is not None:
                instructions.extend(parse_assembly(row, source="cod"))
            instructions.sort(
                key=lambda instruction: int(
                    instruction.source_line.split()[0],
                    16,
                )
            )
            data = bytearray(caller.data)
            data[offset : offset + max(prior_size, len(instruction_body))] = (
                b"\0" * max(prior_size, len(instruction_body))
            )
            data[offset : offset + len(instruction_body)] = instruction_body
            (
                local_control_flow_indices,
                local_control_flow_targets,
            ) = remapped_control_flow(instructions)
            return replace(
                candidate,
                instructions=tuple(instructions),
                local_control_flow_indices=local_control_flow_indices,
                local_control_flow_targets=local_control_flow_targets,
                caller_definition=replace(caller, data=bytes(data)),
            )

        cases = (
            (
                "missing",
                changed_candidate(
                    offset=0x103,
                    row=None,
                    instruction_body=b"",
                    prior_size=3,
                ),
                "population/order drift in candidate case-1",
            ),
            (
                "wrong-slot",
                changed_candidate(
                    offset=0xB3,
                    row="000b3 ff 52 64 call dword [edx+100]",
                    instruction_body=b"\xff\x52\x64",
                    prior_size=3,
                ),
                "virtual slot",
            ),
            (
                "wrong-receiver",
                changed_candidate(
                    offset=0xB1,
                    row="000b1 8b cf mov ecx, edi",
                    instruction_body=b"\x8b\xcf",
                    prior_size=2,
                ),
                "embedded \\+0x48 widget storage",
            ),
            (
                "wrong-storage",
                changed_candidate(
                    offset=0xAC,
                    row=None,
                    instruction_body=b"",
                    prior_size=3,
                ),
                "embedded \\+0x48 widget storage",
            ),
        )
        for label, changed, message in cases:
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                message,
            ):
                self._hud_track_counter_switch_bridges(
                    fixture,
                    candidate=changed,
                )

        duplicate_instruction = parse_assembly(
            "000f9 ff 52 0c call dword [edx+12]",
            source="cod",
        )[0]
        duplicate_data = bytearray(caller.data)
        duplicate_data[0xF9:0xFC] = b"\xff\x52\x0c"
        duplicate_instructions = sorted(
            (*candidate.instructions, duplicate_instruction),
            key=lambda instruction: int(
                instruction.source_line.split()[0],
                16,
            ),
        )
        (
            duplicate_control_flow_indices,
            duplicate_control_flow_targets,
        ) = remapped_control_flow(duplicate_instructions)
        duplicate = replace(
            candidate,
            instructions=tuple(duplicate_instructions),
            local_control_flow_indices=duplicate_control_flow_indices,
            local_control_flow_targets=duplicate_control_flow_targets,
            caller_definition=replace(
                caller,
                data=bytes(duplicate_data),
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "population/order drift in candidate case-1",
        ):
            self._hud_track_counter_switch_bridges(
                fixture,
                candidate=duplicate,
            )

        cleanup_instruction = parse_assembly(
            "000b6 83 c4 04 add esp, 4",
            source="cod",
        )[0]
        cleanup_data = bytearray(caller.data)
        cleanup_data[0xB6:0xB9] = b"\x83\xc4\x04"
        cleanup_instructions = sorted(
            (*candidate.instructions, cleanup_instruction),
            key=lambda instruction: int(
                instruction.source_line.split()[0],
                16,
            ),
        )
        (
            cleanup_control_flow_indices,
            cleanup_control_flow_targets,
        ) = remapped_control_flow(cleanup_instructions)
        cleanup = replace(
            candidate,
            instructions=tuple(cleanup_instructions),
            local_control_flow_indices=cleanup_control_flow_indices,
            local_control_flow_targets=cleanup_control_flow_targets,
            caller_definition=replace(
                caller,
                data=bytes(cleanup_data),
            ),
        )
        with self.assertRaisesRegex(ValueError, "cleanup"):
            self._hud_track_counter_switch_bridges(
                fixture,
                candidate=cleanup,
            )

    def test_hud_track_counter_switch_table_and_dispatch_drift_fails(
        self,
    ) -> None:
        fixture = self._hud_track_counter_switch_fixture()
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None
        table_relocation = next(
            relocation
            for relocation in caller.relocations
            if relocation.offset == 0x98
        )
        changed_relocations = tuple(
            replace(table_relocation, type=0x14)
            if relocation is table_relocation
            else relocation
            for relocation in caller.relocations
        )
        with self.assertRaisesRegex(ValueError, "DIR32 scaled-index"):
            self._hud_track_counter_switch_bridges(
                fixture,
                candidate=replace(
                    candidate,
                    caller_definition=replace(
                        caller,
                        relocations=changed_relocations,
                    ),
                ),
            )

        changed_data = bytearray(caller.data)
        struct.pack_into("<I", changed_data, 0x98, 4)
        with self.assertRaisesRegex(ValueError, "DIR32 scaled-index"):
            self._hud_track_counter_switch_bridges(
                fixture,
                candidate=replace(
                    candidate,
                    caller_definition=replace(
                        caller,
                        data=bytes(changed_data),
                    ),
                ),
            )

        dispatch_index = next(iter(candidate.local_control_flow_indices))
        extra_dispatch_index = dispatch_index + 1
        with self.assertRaisesRegex(ValueError, "one unique candidate"):
            self._hud_track_counter_switch_bridges(
                fixture,
                candidate=replace(
                    candidate,
                    local_control_flow_indices=frozenset(
                        {dispatch_index, extra_dispatch_index}
                    ),
                    local_control_flow_targets={
                        **candidate.local_control_flow_targets,
                        extra_dispatch_index: (
                            candidate.local_control_flow_targets[
                                dispatch_index
                            ]
                        ),
                    },
                ),
            )

