    def _hud_track_marker_allocated_candidate(
        self,
        fixture: dict,
        first_register: str,
        second_register: str,
    ) -> CandidateAssembly:
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None
        rows = {
            0x9A: (
                f"0009a 8b {'06' if first_register == 'eax' else '16'} "
                f"mov {first_register}, DWORD PTR [esi]"
            ),
            0x9E: (
                f"0009e ff {'50' if first_register == 'eax' else '52'} 64 "
                f"call DWORD PTR [{first_register}+100]"
            ),
            0xAB: (
                f"000ab 8b {'06' if second_register == 'eax' else '16'} "
                f"mov {second_register}, DWORD PTR [esi]"
            ),
            0xAF: (
                f"000af ff {'50' if second_register == 'eax' else '52'} 68 "
                f"call DWORD PTR [{second_register}+104]"
            ),
        }
        instructions = [
            instruction
            for instruction in candidate.instructions
            if int(instruction.source_line.split()[0], 16) not in rows
        ]
        instructions.extend(
            instruction
            for row in rows.values()
            for instruction in parse_assembly(row, source="cod")
        )
        instructions.sort(
            key=lambda instruction: int(
                instruction.source_line.split()[0],
                16,
            )
        )
        body = bytearray(caller.data)
        for offset, register, slot in (
            (0x9A, first_register, 0x64),
            (0xAB, second_register, 0x68),
        ):
            body[offset : offset + 2] = (
                b"\x8b\x06" if register == "eax" else b"\x8b\x16"
            )
            call_offset = offset + 4
            body[call_offset : call_offset + 3] = bytes(
                (0xFF, 0x50 if register == "eax" else 0x52, slot)
            )
        return replace(
            candidate,
            instructions=tuple(instructions),
            caller_definition=replace(caller, data=bytes(body)),
        )

    def test_hud_track_marker_loop_accepts_eax_edx_allocations(
        self,
    ) -> None:
        fixture = self._hud_track_marker_loop_fixture()
        storage = "load(address(hud-ui-weapon-slot-array-element))"
        for first_register, second_register in (
            ("eax", "edx"),
            ("edx", "eax"),
            ("eax", "eax"),
            ("edx", "edx"),
        ):
            with self.subTest(
                first=first_register,
                second=second_register,
            ):
                candidate = self._hud_track_marker_allocated_candidate(
                    fixture,
                    first_register,
                    second_register,
                )
                bridges = self._hud_track_marker_loop_bridges(
                    fixture,
                    candidate=candidate,
                )
                self.assertEqual(
                    {
                        "0x9e": ReviewedLoopVptrStorageBridge(
                            register=first_register,
                            storage_identity=storage,
                            slot_displacement=0x64,
                            assembly_source="cod",
                        ),
                        "0xaf": ReviewedLoopVptrStorageBridge(
                            register=second_register,
                            storage_identity=storage,
                            slot_displacement=0x68,
                            assembly_source="cod",
                        ),
                    },
                    bridges,
                )

    def test_hud_track_marker_loop_rejects_semantic_and_cfg_drift(
        self,
    ) -> None:
        fixture = self._hud_track_marker_loop_fixture()
        candidate = fixture["candidate"]
        caller = fixture["caller"]

        def changed_row(
            offset: int,
            row: str | None,
            encoded: bytes,
            *,
            prior_size: int,
        ) -> CandidateAssembly:
            instructions = [
                instruction
                for instruction in candidate.instructions
                if int(instruction.source_line.split()[0], 16) != offset
            ]
            if row is not None:
                instructions.extend(parse_assembly(row, source="cod"))
            instructions.sort(
                key=lambda instruction: int(
                    instruction.source_line.split()[0],
                    16,
                )
            )
            body = bytearray(caller.data)
            body[offset : offset + max(prior_size, len(encoded))] = (
                b"\0" * max(prior_size, len(encoded))
            )
            body[offset : offset + len(encoded)] = encoded
            return replace(
                candidate,
                instructions=tuple(instructions),
                caller_definition=replace(caller, data=bytes(body)),
            )

        cases = (
            (
                "receiver",
                changed_row(
                    0x9C,
                    "0009c 8b cf mov ecx, edi",
                    b"\x8b\xcf",
                    prior_size=2,
                ),
            ),
            (
                "vptr-base",
                changed_row(
                    0x9A,
                    "0009a 8b 07 mov eax, DWORD PTR [edi]",
                    b"\x8b\x07",
                    prior_size=2,
                ),
            ),
            (
                "stride",
                changed_row(
                    0xD8,
                    "000d8 81 c6 c4 01 00 00 add esi, 452",
                    b"\x81\xc6\xc4\x01\x00\x00",
                    prior_size=6,
                ),
            ),
            (
                "callsite",
                changed_row(0x9E, None, b"", prior_size=3),
            ),
            (
                "slot",
                changed_row(
                    0x9E,
                    "0009e ff 50 68 call DWORD PTR [eax+104]",
                    b"\xff\x50\x68",
                    prior_size=3,
                ),
            ),
            (
                "following-call",
                changed_row(0xAF, None, b"", prior_size=3),
            ),
            (
                "cfg",
                changed_row(
                    0xE0,
                    "000e0 0f 82 65 ff ff ff jb 0x4b",
                    b"\x0f\x82\x65\xff\xff\xff",
                    prior_size=6,
                ),
            ),
        )
        for label, changed in cases:
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "track-marker loop bridge",
            ):
                self._hud_track_marker_loop_bridges(
                    fixture,
                    candidate=changed,
                )

    def test_hud_track_marker_loop_rejects_relocation_authority_ambiguity(
        self,
    ) -> None:
        fixture = self._hud_track_marker_loop_fixture()
        candidate = fixture["candidate"]
        caller = fixture["caller"]
        relocation = caller.relocations[2]
        relocation_cases = {
            "type": replace(
                caller,
                relocations=(
                    *caller.relocations[:2],
                    replace(relocation, type=0x14),
                ),
            ),
            "symbol": replace(
                caller,
                relocations=(
                    *caller.relocations[:2],
                    replace(relocation, symbol_name="?g_Wrong@@3HA"),
                ),
            ),
            "duplicate": replace(
                caller,
                relocations=(
                    *caller.relocations,
                    replace(relocation, symbol_index=9),
                ),
            ),
            "mask": replace(
                caller,
                relocation_mask=tuple(
                    False if index == 0x1D else value
                    for index, value in enumerate(
                        caller.relocation_mask
                    )
                ),
            ),
        }
        for label, changed in relocation_cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "relocation|aggregate",
            ):
                self._hud_track_marker_loop_bridges(
                    fixture,
                    candidate=replace(
                        candidate,
                        caller_definition=changed,
                    ),
                )

        drifted = deepcopy(fixture["document"].data)
        drifted["symbols"]["recoil:function:0x4122c0"][
            "source_traceability"
        ]["source_edges"][0]["anchor_id"] = "recoil:anchor:wrong"
        with self.assertRaisesRegex(ValueError, "exact unaliased authored"):
            self._hud_track_marker_loop_bridges(
                fixture,
                document=ProgressDocument(drifted),
            )

        duplicate_instruction = parse_assembly(
            "0009e ff 50 64 call DWORD PTR [eax+100]",
            source="cod",
        )[0]
        with self.assertRaisesRegex(ValueError, "unique exact candidate"):
            self._hud_track_marker_loop_bridges(
                fixture,
                candidate=replace(
                    candidate,
                    instructions=(
                        *candidate.instructions,
                        duplicate_instruction,
                    ),
                ),
            )

        wrong_expected = deepcopy(fixture["expected"])
        wrong_expected[1]["slot_displacement"] = 0x64
        with self.assertRaisesRegex(ValueError, "immutable retail"):
            _hud_ui_mgr_sensor_track_marker_loop_candidate_vptr_bridges(
                wrong_expected,
                candidate,
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x4122c0",
                caller_end_exclusive="0x4124b0",
                indexes=fixture["indexes"],
            )

