    def _hud_update_meter_x_vptr_bridges(
        self,
        fixture: dict,
        **overrides: object,
    ) -> tuple[dict, dict]:
        arguments = {
            "candidate": fixture["candidate"],
            "document": fixture["document"],
            "caller_identity": fixture["caller_identity"],
            "caller_start": "0x4118b0",
            "caller_end_exclusive": "0x411900",
            "indexes": fixture["indexes"],
        }
        arguments.update(overrides)
        return _hud_ui_mgr_objective_update_meter_x_candidate_vptr_bridges(
            fixture["expected"],
            **arguments,
        )

    def test_hud_update_meter_x_vptr_exact_contract_and_scope(
        self,
    ) -> None:
        fixture = self._hud_update_meter_x_vptr_fixture()
        absolute, vptr = self._hud_update_meter_x_vptr_bridges(fixture)
        self.assertEqual({"0x1"}, set(absolute))
        self.assertEqual({"0xb"}, set(vptr))
        self.assertEqual(
            fixture["expected"],
            extract_invocation_contract(
                fixture["candidate"].instructions,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x4118b0",
                caller_end_exclusive="0x411900",
                indexes=fixture["indexes"],
                reviewed_absolute_storage_load_bridges=absolute,
                reviewed_vptr_storage_bridges=vptr,
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register storage eax",
        ):
            extract_invocation_contract(
                fixture["candidate"].instructions,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x4118b0",
                caller_end_exclusive="0x411900",
                indexes=fixture["indexes"],
            )

        self.assertEqual(
            ({}, {}),
            _hud_ui_mgr_objective_update_meter_x_candidate_vptr_bridges(
                fixture["expected"],
                fixture["candidate"],
                document=fixture["document"],
                caller_identity="symbol:recoil:function:0x411900",
                caller_start="0x411900",
                caller_end_exclusive="0x411a20",
                indexes=fixture["indexes"],
            ),
        )

    def test_hud_update_meter_x_vptr_rejects_authority_and_provenance_drift(
        self,
    ) -> None:
        fixture = self._hud_update_meter_x_vptr_fixture()
        drifted = deepcopy(fixture["document"].data)
        drifted["symbols"]["recoil:function:0x4118b0"][
            "source_traceability"
        ]["source_edges"][0]["anchor_id"] = "recoil:anchor:wrong"
        authority_cases = {
            "caller": {"caller_identity": "symbol:recoil:function:0x411900"},
            "extent": {"caller_end_exclusive": "0x4118f0"},
            "tracker": {"document": ProgressDocument(drifted)},
        }
        for name, overrides in authority_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "authored caller/source and aggregate storage authority",
            ):
                self._hud_update_meter_x_vptr_bridges(
                    fixture,
                    **overrides,
                )

        drifted_expected = deepcopy(fixture["expected"])
        drifted_expected[0]["storage_identity"] = (
            "load(storage:recoil:data:0x4e5ed0+0x6b0)"
        )
        with self.assertRaisesRegex(ValueError, "immutable retail"):
            _hud_ui_mgr_objective_update_meter_x_candidate_vptr_bridges(
                drifted_expected,
                fixture["candidate"],
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x4118b0",
                caller_end_exclusive="0x411900",
                indexes=fixture["indexes"],
            )

        instruction_cases: dict[str, tuple] = {}
        load_register = list(fixture["candidate"].instructions)
        load_register[1] = replace(
            load_register[1],
            raw_text=load_register[1].raw_text.replace(
                "mov eax",
                "mov edx",
            ),
            text=load_register[1].text.replace("mov eax", "mov edx"),
        )
        instruction_cases["load-register"] = tuple(load_register)
        receiver = list(fixture["candidate"].instructions)
        receiver[2] = replace(
            receiver[2],
            raw_text=receiver[2].raw_text.replace(
                "mov ecx",
                "mov edx",
            ),
            text=receiver[2].text.replace("mov ecx", "mov edx"),
        )
        instruction_cases["receiver-register"] = tuple(receiver)
        slot = list(fixture["candidate"].instructions)
        slot[3] = replace(
            slot[3],
            raw_text=slot[3].raw_text.replace(
                "[eax+100]",
                "[eax+96]",
            ),
            text=slot[3].text.replace("[eax+100]", "[eax+96]"),
        )
        instruction_cases["slot"] = tuple(slot)
        cleanup = list(fixture["candidate"].instructions)
        cleanup.insert(
            4,
            tuple(
                parse_assembly(
                    "  0000e 83 c4 04 add esp, 4",
                    source="cod",
                )
            )[0],
        )
        instruction_cases["cleanup"] = tuple(cleanup)

        for name, instructions in instruction_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "straight-line candidate listing|reaching-definition",
            ):
                self._hud_update_meter_x_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=instructions,
                    ),
                )

        with self.assertRaisesRegex(ValueError, "control-flow drift"):
            self._hud_update_meter_x_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({0}),
                ),
            )

    def test_hud_update_meter_x_vptr_rejects_body_and_relocation_drift(
        self,
    ) -> None:
        fixture = self._hud_update_meter_x_vptr_fixture()
        caller = fixture["caller"]
        cases: dict[str, CandidateCallerDefinition] = {}

        body = bytearray(caller.data)
        body[0x0B] = 0xFE
        cases["body"] = replace(caller, data=bytes(body))

        target = tuple(
            replace(row, symbol_name="?wrong@@3HA")
            if row.offset == 0x02
            else row
            for row in caller.relocations
        )
        cases["target"] = replace(caller, relocations=target)

        addend = bytearray(caller.data)
        struct.pack_into("<I", addend, 0x07, 0x6AD)
        cases["addend"] = replace(caller, data=bytes(addend))

        mask = list(caller.relocation_mask)
        mask[0x02] = False
        cases["mask"] = replace(
            caller,
            relocation_mask=tuple(mask),
        )

        cases["order"] = replace(
            caller,
            relocations=tuple(reversed(caller.relocations)),
        )

        for name, definition in cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "0x50 caller symbol/body",
            ):
                self._hud_update_meter_x_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

