    def test_hud_objective_show_sensor_overlay_vptr_rejects_register_slot_cleanup_and_cfg_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_show_sensor_overlay_vptr_fixture()
        instruction_cases: dict[str, tuple] = {}
        load = list(fixture["candidate"].instructions)
        load[22] = replace(
            load[22],
            raw_text=load[22].raw_text.replace("mov eax", "mov edx"),
            text=load[22].text.replace("mov eax", "mov edx"),
        )
        instruction_cases["load-register"] = tuple(load)
        receiver = list(fixture["candidate"].instructions)
        receiver[24] = replace(
            receiver[24],
            raw_text=receiver[24].raw_text.replace("mov ecx", "mov edx"),
            text=receiver[24].text.replace("mov ecx", "mov edx"),
        )
        instruction_cases["receiver-register"] = tuple(receiver)
        argument = list(fixture["candidate"].instructions)
        argument[25] = replace(
            argument[25],
            raw_text=argument[25].raw_text.replace("push 0", "push 1"),
            text=argument[25].text.replace("push 0", "push 1"),
        )
        instruction_cases["argument"] = tuple(argument)
        slot = list(fixture["candidate"].instructions)
        slot[26] = replace(
            slot[26],
            raw_text=slot[26].raw_text.replace(
                "[eax+96]",
                "[eax+100]",
            ),
            text=slot[26].text.replace("[eax+96]", "[eax+100]"),
        )
        instruction_cases["slot"] = tuple(slot)
        prior_cleanup = list(fixture["candidate"].instructions)
        prior_cleanup[23] = replace(
            prior_cleanup[23],
            raw_text=prior_cleanup[23].raw_text.replace(
                "add esp, 8",
                "add esp, 4",
            ),
            text=prior_cleanup[23].text.replace(
                "add esp, 8",
                "add esp, 4",
            ),
        )
        instruction_cases["prior-cleanup"] = tuple(prior_cleanup)
        current_cleanup = list(fixture["candidate"].instructions)
        current_cleanup.append(
            tuple(
                parse_assembly(
                    "  00052 83 c4 04 add esp, 4",
                    source="cod",
                )
            )[0]
        )
        instruction_cases["current-cleanup"] = tuple(current_cleanup)

        for name, instructions in instruction_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "instruction bytes|reaching-definition|cleanup",
            ):
                self._hud_objective_show_sensor_overlay_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=instructions,
                    ),
                )

        with self.assertRaisesRegex(ValueError, "control-flow drift"):
            self._hud_objective_show_sensor_overlay_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({0}),
                ),
            )

    def test_hud_objective_show_sensor_overlay_vptr_rejects_relocation_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_show_sensor_overlay_vptr_fixture()
        caller = fixture["caller"]
        cases: dict[str, CandidateCallerDefinition] = {}

        body = bytearray(caller.data)
        body[0x4F] = 0xFE
        cases["body"] = replace(caller, data=bytes(body))

        target = tuple(
            replace(row, symbol_name="?wrong@@3HA")
            if row.offset == 0x49
            else row
            for row in caller.relocations
        )
        cases["target"] = replace(caller, relocations=target)

        addend = bytearray(caller.data)
        struct.pack_into("<I", addend, 0x49, 0xCE4)
        cases["addend"] = replace(caller, data=bytes(addend))

        mask = list(caller.relocation_mask)
        mask[0x49] = False
        cases["mask"] = replace(caller, relocation_mask=tuple(mask))

        reordered = list(caller.relocations)
        reordered[-2:] = reversed(reordered[-2:])
        cases["order"] = replace(
            caller,
            relocations=tuple(reordered),
        )

        for name, definition in cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "0x120 caller symbol/window",
            ):
                self._hud_objective_show_sensor_overlay_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

