    def test_hud_objective_show_bar_vptr_rejects_provenance_slot_cleanup_and_cfg_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_show_bar_vptr_fixture()

        def index_of(instructions: list, offset: int) -> int:
            marker = f"{offset:05x}"
            return next(
                index
                for index, instruction in enumerate(instructions)
                if marker in instruction.source_line.lower()
            )

        instruction_cases: dict[str, tuple] = {}
        seed = list(fixture["candidate"].instructions)
        seed_index = index_of(seed, 0x6B)
        seed[seed_index] = replace(
            seed[seed_index],
            raw_text=seed[seed_index].raw_text.replace("mov edi", "mov esi"),
            text=seed[seed_index].text.replace("mov edi", "mov esi"),
        )
        instruction_cases["argument-seed"] = tuple(seed)

        receiver = list(fixture["candidate"].instructions)
        receiver_index = index_of(receiver, 0xB6)
        receiver[receiver_index] = replace(
            receiver[receiver_index],
            raw_text=receiver[receiver_index].raw_text.replace(
                "mov ecx",
                "mov edx",
            ),
            text=receiver[receiver_index].text.replace("mov ecx", "mov edx"),
        )
        instruction_cases["receiver"] = tuple(receiver)

        result_store = list(fixture["candidate"].instructions)
        result_index = index_of(result_store, 0xBB)
        result_store[result_index] = replace(
            result_store[result_index],
            raw_text=result_store[result_index].raw_text.replace(
                ", eax",
                ", edx",
            ),
            text=result_store[result_index].text.replace(", eax", ", edx"),
        )
        instruction_cases["result-store"] = tuple(result_store)

        load = list(fixture["candidate"].instructions)
        load_index = index_of(load, 0xC0)
        load[load_index] = replace(
            load[load_index],
            raw_text=load[load_index].raw_text.replace("mov eax", "mov edx"),
            text=load[load_index].text.replace("mov eax", "mov edx"),
        )
        instruction_cases["vptr-load"] = tuple(load)

        argument = list(fixture["candidate"].instructions)
        argument_index = index_of(argument, 0xC5)
        argument[argument_index] = replace(
            argument[argument_index],
            raw_text=argument[argument_index].raw_text.replace(
                "push edi",
                "push esi",
            ),
            text=argument[argument_index].text.replace("push edi", "push esi"),
        )
        instruction_cases["argument"] = tuple(argument)

        slot = list(fixture["candidate"].instructions)
        call_index = index_of(slot, 0xC6)
        slot[call_index] = replace(
            slot[call_index],
            raw_text=slot[call_index].raw_text.replace(
                "[eax+96]",
                "[eax+100]",
            ),
            text=slot[call_index].text.replace("[eax+96]", "[eax+100]"),
        )
        instruction_cases["slot"] = tuple(slot)

        argument_clobber = list(fixture["candidate"].instructions)
        receiver_index = index_of(argument_clobber, 0xB6)
        argument_clobber.insert(
            receiver_index,
            tuple(
                parse_assembly(
                    "  000b5 33 ff xor edi, edi",
                    source="cod",
                )
            )[0],
        )
        instruction_cases["argument-clobber"] = tuple(argument_clobber)

        receiver_clobber = list(fixture["candidate"].instructions)
        result_index = index_of(receiver_clobber, 0xBB)
        receiver_clobber.insert(
            result_index,
            tuple(
                parse_assembly(
                    "  000ba 33 c9 xor ecx, ecx",
                    source="cod",
                )
            )[0],
        )
        instruction_cases["receiver-clobber"] = tuple(receiver_clobber)

        vptr_clobber = list(fixture["candidate"].instructions)
        argument_index = index_of(vptr_clobber, 0xC5)
        vptr_clobber.insert(
            argument_index,
            tuple(
                parse_assembly(
                    "  000c4 33 c0 xor eax, eax",
                    source="cod",
                )
            )[0],
        )
        instruction_cases["vptr-clobber"] = tuple(vptr_clobber)

        branch = list(fixture["candidate"].instructions)
        result_index = index_of(branch, 0xBB)
        branch.insert(
            result_index,
            tuple(
                parse_assembly(
                    "  000ba 75 00 jne $Ldrift",
                    source="cod",
                )
            )[0],
        )
        instruction_cases["branch"] = tuple(branch)

        cleanup = list(fixture["candidate"].instructions)
        call_index = index_of(cleanup, 0xC6)
        cleanup.insert(
            call_index + 1,
            tuple(
                parse_assembly(
                    "  000c9 83 c4 04 add esp, 4",
                    source="cod",
                )
            )[0],
        )
        instruction_cases["cleanup"] = tuple(cleanup)

        for name, instructions in instruction_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "instruction bytes|reaching-definition|clobber|cleanup|"
                "straight-line",
            ):
                self._hud_objective_show_bar_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=instructions,
                    ),
                )

        with self.assertRaisesRegex(ValueError, "control-flow drift"):
            self._hud_objective_show_bar_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({0}),
                ),
            )

    def test_hud_objective_show_bar_vptr_rejects_relocation_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_show_bar_vptr_fixture()
        caller = fixture["caller"]
        cases: dict[str, CandidateCallerDefinition] = {}

        body = bytearray(caller.data)
        body[0xC6] = 0xFE
        cases["body"] = replace(caller, data=bytes(body))

        target = tuple(
            replace(row, symbol_name="?wrong@@3HA")
            if row.offset == 0xC1
            else row
            for row in caller.relocations
        )
        cases["target"] = replace(caller, relocations=target)

        addend = bytearray(caller.data)
        struct.pack_into("<I", addend, 0xC1, 0x97C)
        cases["addend"] = replace(caller, data=bytes(addend))

        mask = list(caller.relocation_mask)
        mask[0xC1] = False
        cases["mask"] = replace(caller, relocation_mask=tuple(mask))

        reordered = list(caller.relocations)
        reordered[-3:] = reversed(reordered[-3:])
        cases["order"] = replace(
            caller,
            relocations=tuple(reordered),
        )

        for name, definition in cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "0x120 caller symbol/window",
            ):
                self._hud_objective_show_bar_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

