    def test_hud_objective_begin_summary_vptr_rejects_provenance_slot_cleanup_and_cfg_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_begin_summary_vptr_fixture()

        def index_of(instructions: list, offset: int) -> int:
            marker = f"{offset:05x}"
            return next(
                index
                for index, instruction in enumerate(instructions)
                if marker in instruction.source_line.lower()
            )

        instruction_cases: dict[str, tuple] = {}
        load = list(fixture["candidate"].instructions)
        load_index = index_of(load, 0x17)
        load[load_index] = replace(
            load[load_index],
            raw_text=load[load_index].raw_text.replace("mov ecx", "mov edx"),
            text=load[load_index].text.replace("mov ecx", "mov edx"),
        )
        instruction_cases["load-register"] = tuple(load)

        vptr = list(fixture["candidate"].instructions)
        vptr_index = index_of(vptr, 0x3B)
        vptr[vptr_index] = replace(
            vptr[vptr_index],
            raw_text=vptr[vptr_index].raw_text.replace("mov eax", "mov edx"),
            text=vptr[vptr_index].text.replace("mov eax", "mov edx"),
        )
        instruction_cases["vptr-register"] = tuple(vptr)

