    def test_hud_objective_visibility_vptr_exact_contract(self) -> None:
        fixture = self._hud_objective_visibility_vptr_fixture()
        static, absolute, vptr, member = (
            self._hud_objective_visibility_vptr_bridges(fixture)
        )
        self.assertEqual({f"{fixture['aggregate']}+2088"}, set(static))
        self.assertEqual({"0x13", "0x7c"}, set(absolute))
        self.assertEqual({"0x20", "0x89"}, set(vptr))
        self.assertEqual({"0xe", "0x77"}, set(member))
        visibility_offsets = {
            0x05,
            0x0B,
            0x0C,
            0x0E,
            0x10,
            0x13,
            0x19,
            0x1E,
            0x20,
            0x6F,
            0x75,
            0x77,
            0x79,
            0x7C,
            0x82,
            0x87,
            0x89,
        }
        offsets = tuple(
            (
                address - 0x411760
                if address is not None
                else None
            )
            for address in _instruction_runtime_addresses(
                fixture["candidate"].instructions,
                source="cod",
                caller_start=0x411760,
            )
        )
        visibility_instructions = tuple(
            instruction
            for instruction, offset in zip(
                fixture["candidate"].instructions,
                offsets,
            )
            if offset is not None and offset in visibility_offsets
        )
        contract = extract_invocation_contract(
            visibility_instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x411760",
            caller_end_exclusive="0x4117f0",
            indexes=fixture["indexes"],
            reviewed_static_storage_reference_bridges=static,
            reviewed_absolute_storage_load_bridges=absolute,
            reviewed_member_vptr_storage_bridges=member,
            reviewed_vptr_storage_bridges=vptr,
        )
        self.assertEqual(
            [
                fixture["expected"][0],
                fixture["expected"][1],
                {**fixture["expected"][5], "ordinal": 2},
                {**fixture["expected"][6], "ordinal": 3},
            ],
            contract,
        )
        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register storage eax",
        ):
            extract_invocation_contract(
                visibility_instructions,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x411760",
                caller_end_exclusive="0x4117f0",
                indexes=fixture["indexes"],
            )

    def test_hud_objective_visibility_vptr_rejects_exact_drift(self) -> None:
        fixture = self._hud_objective_visibility_vptr_fixture()
        caller = fixture["caller"]
        drifted_expected = deepcopy(fixture["expected"])
        drifted_expected[5]["storage_identity"] = (
            "load(storage:recoil:data:0x4e5ed0+0x828)"
        )
        with self.assertRaisesRegex(ValueError, "immutable retail"):
            _hud_ui_mgr_objective_visibility_candidate_vptr_bridges(
                drifted_expected,
                candidate=fixture["candidate"],
                document=fixture["document"],
                caller_identity=fixture["caller_identity"],
                caller_start="0x411760",
                caller_end_exclusive="0x4117f0",
                indexes=fixture["indexes"],
            )

        bad_addend = bytearray(caller.data)
        struct.pack_into("<I", bad_addend, 0x71, 0x82C)
        with self.assertRaisesRegex(ValueError, "DIR32/REL32 target/addend/order"):
            self._hud_objective_visibility_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    caller_definition=replace(
                        caller,
                        data=bytes(bad_addend),
                    ),
                ),
            )

        old_false_first = bytearray(0x90)
        old_false_first[:0x42] = bytes.fromhex(
            "51 85 c9 75 1f "
            "8b 0d 28 08 00 00 6a 00 8b 01 ff 50 60 "
            "8b 15 2c 08 00 00 b9 2c 08 00 00 6a 00 ff 52 60 "
            "59 c3 "
            "8b 0d 28 08 00 00 56 6a 01 8b 01 ff 50 60 "
            "8b 15 2c 08 00 00 b9 2c 08 00 00 6a 01 ff 52 60"
        )
        with self.assertRaisesRegex(ValueError, "exact 0x90 caller"):
            self._hud_objective_visibility_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    caller_definition=replace(
                        caller,
                        data=bytes(old_false_first),
                    ),
                ),
            )

        target = fixture["candidate"].target
        entry = target.translation_unit_function_order[0]
        bad_row = SimpleNamespace(
            **{
                **vars(entry.functions[0]),
                "symbol_regex": (
                    r"\?SetVisibleAndResetMeterFill@Wrong@@.*"
                ),
            }
        )
        with self.assertRaisesRegex(ValueError, "contribution row"):
            self._hud_objective_visibility_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    target=SimpleNamespace(
                        **{
                            **vars(target),
                            "translation_unit_function_order": (
                                SimpleNamespace(
                                    **{
                                        **vars(entry),
                                        "functions": (bad_row,),
                                    }
                                ),
                            ),
                        }
                    ),
                ),
            )

        instructions = list(fixture["candidate"].instructions)
        instructions[6] = tuple(
            parse_assembly(
                "  0000e 8b 01 mov eax, dword [edx]",
                source="cod",
            )
        )[0]
        with self.assertRaisesRegex(
            ValueError,
            "retail-ordered listing|label receiver",
        ):
            self._hud_objective_visibility_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    instructions=tuple(instructions),
                ),
            )


