    def _hud_objective_start_hide_bar_vptr_bridges(
        self,
        fixture: dict,
        **overrides: object,
    ) -> tuple[dict, dict]:
        arguments = {
            "candidate": fixture["candidate"],
            "document": fixture["document"],
            "caller_identity": fixture["caller_identity"],
            "caller_start": "0x411ac0",
            "caller_end_exclusive": "0x411eb0",
            "indexes": fixture["indexes"],
        }
        arguments.update(overrides)
        return _hud_ui_mgr_objective_start_hide_candidate_vptr_bridges(
            fixture["expected"],
            **arguments,
        )

    def _assert_hud_objective_start_hide_bar_vptr_rejects(
        self,
        fixture: dict,
        field: str,
        *,
        expected: list[dict] | None = None,
        **overrides: object,
    ) -> None:
        arguments = {
            "candidate": fixture["candidate"],
            "document": fixture["document"],
            "caller_identity": fixture["caller_identity"],
            "caller_start": "0x411ac0",
            "caller_end_exclusive": "0x411eb0",
            "indexes": fixture["indexes"],
        }
        arguments.update(overrides)
        with self.assertRaises(ValueError) as raised:
            _hud_ui_mgr_objective_start_hide_candidate_vptr_bridges(
                fixture["expected"] if expected is None else expected,
                **arguments,
            )
        message = str(raised.exception)
        self.assertIn(f"rejects {field}: expected=", message)
        self.assertIn("; observed=", message)

    def test_hud_objective_start_hide_bar_vptr_exact_contract_and_scope(
        self,
    ) -> None:
        fixture = self._hud_objective_start_hide_bar_vptr_fixture()
        absolute, vptr = (
            self._hud_objective_start_hide_bar_vptr_bridges(fixture)
        )
        self.assertEqual({"0x83"}, set(absolute))
        self.assertEqual({"0x8e"}, set(vptr))
        self.assertEqual(
            fixture["expected"],
            extract_invocation_contract(
                fixture["candidate"].instructions,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x411ac0",
                caller_end_exclusive="0x411eb0",
                indexes=fixture["indexes"],
                reviewed_absolute_storage_load_bridges=absolute,
                reviewed_vptr_storage_bridges=vptr,
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register storage eax",
        ):
            extract_invocation_contract(
                fixture["candidate"].instructions,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x411ac0",
                caller_end_exclusive="0x411eb0",
                indexes=fixture["indexes"],
            )
        self.assertEqual(
            ({}, {}),
            _hud_ui_mgr_objective_start_hide_candidate_vptr_bridges(
                fixture["expected"],
                fixture["candidate"],
                document=fixture["document"],
                caller_identity="symbol:recoil:function:0x411a20",
                caller_start="0x411a20",
                caller_end_exclusive="0x411ac0",
                indexes=fixture["indexes"],
            ),
        )

    def test_hud_objective_start_hide_bar_vptr_rejects_authority_and_contract_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_start_hide_bar_vptr_fixture()
        caller_id = "recoil:function:0x411ac0"
        aggregate_id = "recoil:data:0x4e5ed0"

        def document_with(
            symbol_id: str,
            path: tuple[str | int, ...],
            value: object,
        ) -> ProgressDocument:
            data = deepcopy(fixture["document"].data)
            current: object = data["symbols"][symbol_id]
            for component in path[:-1]:
                current = current[component]  # type: ignore[index]
            current[path[-1]] = value  # type: ignore[index]
            return ProgressDocument(data)

        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_identity",
            caller_identity="symbol:recoil:function:0x411a20",
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_end_exclusive",
            caller_end_exclusive="0x411ea0",
        )
        duplicate_address_indexes = replace(
            fixture["indexes"],
            by_address={
                **fixture["indexes"].by_address,
                "0x411ad0": fixture["caller_identity"],
            },
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_address_index",
            indexes=duplicate_address_indexes,
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_provider_membership",
            indexes=replace(
                fixture["indexes"],
                provider_ids=(
                    fixture["indexes"].provider_ids
                    | {fixture["caller_identity"]}
                ),
            ),
        )
        missing_caller = deepcopy(fixture["document"].data)
        del missing_caller["symbols"][caller_id]
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_symbol_mapping",
            document=ProgressDocument(missing_caller),
        )
        for field, value in (
            ("binary", "messages"),
            ("kind", "data"),
            ("pipeline_class", "non-authored"),
            ("ownership_state", "auxiliary-owned"),
            ("address", "0x411ad0"),
            ("end_exclusive", "0x411ea0"),
            ("extent_state", "unknown"),
            ("size", 0x3E0),
            ("navigation_name", "Wrong::StartHide"),
            ("output_section_id", "recoil:section:.rdata"),
            ("physical_block_id", "recoil:block:0x411ac0"),
            ("verification_target_ids", []),
        ):
            with self.subTest(caller_symbol_field=field):
                self._assert_hud_objective_start_hide_bar_vptr_rejects(
                    fixture,
                    f"caller_symbol.{field}",
                    document=document_with(caller_id, (field,), value),
                )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_source_traceability_mapping",
            document=document_with(
                caller_id,
                ("source_traceability",),
                "unresolved",
            ),
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_source_traceability.state",
            document=document_with(
                caller_id,
                ("source_traceability", "state"),
                "unresolved",
            ),
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_source_traceability.reason_code",
            document=document_with(
                caller_id,
                ("source_traceability", "reason_code"),
                "ambiguous",
            ),
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_source_edges_type",
            document=document_with(
                caller_id,
                ("source_traceability", "source_edges"),
                (),
            ),
        )
        source_edge = deepcopy(
            fixture["document"].data["symbols"][caller_id][
                "source_traceability"
            ]["source_edges"][0]
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_source_edges_count",
            document=document_with(
                caller_id,
                ("source_traceability", "source_edges"),
                [source_edge, deepcopy(source_edge)],
            ),
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "caller_source_edge_mapping",
            document=document_with(
                caller_id,
                ("source_traceability", "source_edges", 0),
                "wrong",
            ),
        )
        for field, value in (
            ("relation", "emits"),
            ("anchor_id", "recoil:anchor:wrong"),
            ("emission_context", {"translation_unit": "wrong.cpp"}),
        ):
            with self.subTest(source_edge_field=field):
                self._assert_hud_objective_start_hide_bar_vptr_rejects(
                    fixture,
                    f"caller_source_edge.{field}",
                    document=document_with(
                        caller_id,
                        ("source_traceability", "source_edges", 0, field),
                        value,
                    ),
                )
        missing_aggregate = deepcopy(fixture["document"].data)
        del missing_aggregate["symbols"][aggregate_id]
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "aggregate_symbol_mapping",
            document=ProgressDocument(missing_aggregate),
        )
        for field, value in (
            ("binary", "messages"),
            ("kind", "function"),
            ("disposition", "provider"),
            ("address", "0x4e5ed4"),
            ("navigation_name", "wrong"),
            ("extent_state", "known"),
            ("storage_contribution_ids", []),
            ("verification_target_ids", []),
        ):
            with self.subTest(aggregate_symbol_field=field):
                self._assert_hud_objective_start_hide_bar_vptr_rejects(
                    fixture,
                    f"aggregate_symbol.{field}",
                    document=document_with(aggregate_id, (field,), value),
                )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "aggregate_storage_address_index",
            indexes=replace(
                fixture["indexes"],
                storage_by_address={
                    **fixture["indexes"].storage_by_address,
                    "0x4e5ed0": "storage:wrong",
                },
            ),
        )
        aggregate_storage = "storage:recoil:data:0x4e5ed0"
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "aggregate_storage_provider_membership",
            indexes=replace(
                fixture["indexes"],
                provider_ids=fixture["indexes"].provider_ids | {aggregate_storage},
            ),
        )

        target = fixture["candidate"].target

        def candidate_with_target(**changes: object) -> CandidateAssembly:
            return replace(
                fixture["candidate"],
                target=SimpleNamespace(**{**vars(target), **changes}),
            )

        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "target_presence",
            candidate=replace(fixture["candidate"], target=None),
        )
        for field, value in (
            ("name", "wrong"),
            ("target_binary", "messages"),
            ("manifest_path", Path("wrong.json")),
            ("check_translation_unit_function_order", False),
            ("source_files", ("wrong.cpp",)),
            ("translation_unit_function_order", ()),
        ):
            diagnostic = {
                "name": "target.name",
                "target_binary": "target.target_binary",
                "manifest_path": "target.manifest_path",
                "check_translation_unit_function_order": (
                    "target.check_translation_unit_function_order"
                ),
                "source_files": "target.hud_source_file_count",
                "translation_unit_function_order": (
                    "target.start_hide_contribution_count"
                ),
            }[field]
            with self.subTest(target_field=field):
                self._assert_hud_objective_start_hide_bar_vptr_rejects(
                    fixture,
                    diagnostic,
                    candidate=candidate_with_target(**{field: value}),
                )

        contribution = target.translation_unit_function_order[0]
        row = contribution.functions[0]

        def candidate_with_contribution(
            *,
            contribution_changes: Mapping[str, object] | None = None,
            row_changes: Mapping[str, object] | None = None,
            caller_symbol: str | None = None,
        ) -> CandidateAssembly:
            changed_row = SimpleNamespace(
                **{**vars(row), **(row_changes or {})}
            )
            changed_contribution = SimpleNamespace(
                **{
                    **vars(contribution),
                    **(contribution_changes or {}),
                    "functions": (changed_row,),
                }
            )
            changed_target = SimpleNamespace(
                **{
                    **vars(target),
                    "translation_unit_function_order": (
                        changed_contribution,
                    ),
                }
            )
            changed_definition = fixture["caller"]
            if caller_symbol is not None:
                changed_definition = replace(
                    changed_definition,
                    symbol=caller_symbol,
                )
            return replace(
                fixture["candidate"],
                target=changed_target,
                caller_definition=changed_definition,
            )

        for field, changes in (
            (
                "contribution.source_from",
                {"contribution_changes": {"source_from": "wrong.cpp"}},
            ),
            (
                "contribution.order_scope",
                {"contribution_changes": {"order_scope": "full"}},
            ),
            ("contribution_row.symbol", {"row_changes": {"symbol": "wrong"}}),
            (
                "contribution_row.symbol_regex",
                {"row_changes": {"symbol_regex": r"\?Wrong@@.*"}},
            ),
            (
                "candidate_caller_symbol_matches_contribution",
                {"caller_symbol": "?Wrong@@YIXXZ"},
            ),
            (
                "contribution_row.name",
                {"row_changes": {"name": "Wrong::StartHide"}},
            ),
            (
                "contribution_row.pipeline_class",
                {"row_changes": {"pipeline_class": "non-authored"}},
            ),
            (
                "contribution_row.authored_order_role",
                {"row_changes": {"authored_order_role": "provider-body"}},
            ),
            (
                "contribution_row.required_presence",
                {"row_changes": {"required_presence": False}},
            ),
            (
                "contribution_row.full_order_gate",
                {"row_changes": {"full_order_gate": False}},
            ),
        ):
            with self.subTest(contribution_field=field):
                self._assert_hud_objective_start_hide_bar_vptr_rejects(
                    fixture,
                    field,
                    candidate=candidate_with_contribution(**changes),
                )

        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "retail_contract.ordinal_0_presence",
            expected=[],
        )
        for field, value in (
            ("ordinal", 1),
            ("form", "tail-call"),
            ("dispatch", "direct"),
            ("identity_kind", "direct"),
            ("target_identity", "symbol:wrong"),
            ("storage_identity", "load(storage:wrong)"),
            ("slot_displacement", 0x24),
            ("cleanup_bytes", 4),
        ):
            drifted_expected = deepcopy(fixture["expected"])
            drifted_expected[0][field] = value
            with self.subTest(retail_contract_field=field):
                self._assert_hud_objective_start_hide_bar_vptr_rejects(
                    fixture,
                    f"retail_contract.ordinal_0.{field}",
                    expected=drifted_expected,
                )
        drifted_expected = deepcopy(fixture["expected"])
        drifted_expected[0]["unexpected"] = True
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "retail_contract.ordinal_0.fields",
            expected=drifted_expected,
        )

    def test_hud_objective_start_hide_bar_vptr_rejects_provenance_register_slot_cleanup_and_cfg_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_start_hide_bar_vptr_fixture()
        rows = fixture["rows"]

        def candidate_with_rows(changed_rows: list[str]) -> CandidateAssembly:
            return replace(
                fixture["candidate"],
                instructions=tuple(
                    parse_assembly("\n".join(changed_rows), source="cod")
                ),
            )

        duplicate_offset_rows = [*rows, rows[-1]]
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "candidate_instruction_offset_counts",
            candidate=candidate_with_rows(duplicate_offset_rows),
        )

        semantic_cases = (
            (
                "candidate_load_operand_count",
                [*rows[:11], "  00083 a1 78 09 00 00 mov eax", *rows[12:]],
            ),
            (
                "candidate_load_register",
                [
                    *rows[:11],
                    (
                        "  00083 a1 78 09 00 00 mov edx, dword "
                        f"{fixture['aggregate']}+2424"
                    ),
                    *rows[12:],
                ],
            ),
            (
                "candidate_load_storage_expression",
                [
                    *rows[:11],
                    (
                        "  00083 a1 78 09 00 00 mov eax, dword "
                        f"{fixture['aggregate']}+2428"
                    ),
                    *rows[12:],
                ],
            ),
            (
                "candidate_receiver_operand_count",
                ["  00053 b9 78 09 00 00 mov ecx", *rows[1:]],
            ),
            (
                "candidate_receiver_register",
                [
                    (
                        "  00053 b9 78 09 00 00 mov edx, OFFSET FLAT:"
                        f"{fixture['aggregate']}+2424"
                    ),
                    *rows[1:],
                ],
            ),
            (
                "candidate_receiver_storage_expression",
                [
                    (
                        "  00053 b9 78 09 00 00 mov ecx, OFFSET FLAT:"
                        f"{fixture['aggregate']}+2428"
                    ),
                    *rows[1:],
                ],
            ),
            (
                "candidate_call_mnemonic",
                [*rows[:-1], "  0008e ff 50 20 jmp dword [eax+32]"],
            ),
            (
                "candidate_call_slot_expression",
                [*rows[:-1], "  0008e ff 50 20 call dword [eax+36]"],
            ),
            (
                "candidate_receiver_load_call_order",
                [rows[11], *rows[1:11], rows[0], *rows[12:]],
            ),
        )
        for field, changed_rows in semantic_cases:
            with self.subTest(semantic_field=field):
                self._assert_hud_objective_start_hide_bar_vptr_rejects(
                    fixture,
                    field,
                    candidate=candidate_with_rows(changed_rows),
                )

        drifted_listing = [
            *rows[:1],
            "  00058 d8 25 00 00 00 00 fsub dword $T88365",
            *rows[2:],
        ]
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "candidate_instruction_listing",
            candidate=candidate_with_rows(drifted_listing),
        )

        for field, clobber in (
            ("candidate_eax_clobber_offsets", "  0008d 8b c1 mov eax, ecx"),
            ("candidate_ecx_clobber_offsets", "  0008d 8b c8 mov ecx, eax"),
        ):
            with self.subTest(clobber_field=field):
                self._assert_hud_objective_start_hide_bar_vptr_rejects(
                    fixture,
                    field,
                    candidate=candidate_with_rows(
                        [*rows[:-1], clobber, rows[-1]]
                    ),
                )

        with patch(
            "_recoil.commands.call_contract_verify."
            "_candidate_static_invocation_indices",
            return_value=(),
        ):
            self._assert_hud_objective_start_hide_bar_vptr_rejects(
                fixture,
                "candidate_invocation_presence",
            )
        with patch(
            "_recoil.commands.call_contract_verify."
            "_candidate_static_invocation_indices",
            return_value=(0,),
        ):
            self._assert_hud_objective_start_hide_bar_vptr_rejects(
                fixture,
                "candidate_first_invocation_index",
            )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "candidate_call_cleanup_bytes",
            candidate=candidate_with_rows(
                [*rows, "  00091 83 c4 04 add esp, 4"]
            ),
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "candidate_reviewed_window_jump_offsets",
            candidate=candidate_with_rows(
                [*rows[:-1], "  0008d 75 01 jne $Lalternate", rows[-1]]
            ),
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "candidate_incoming_reviewed_control_flow_targets",
            candidate=replace(
                fixture["candidate"],
                local_control_flow_targets={999: (0,)},
            ),
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "candidate_local_control_flow_indices",
            candidate=replace(
                fixture["candidate"],
                local_control_flow_indices=frozenset({0}),
                local_control_flow_targets={},
            ),
        )

    def test_hud_objective_start_hide_bar_vptr_rejects_relocation_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_start_hide_bar_vptr_fixture()
        caller = fixture["caller"]
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "candidate_caller_definition_presence",
            candidate=replace(fixture["candidate"], caller_definition=None),
        )

        cases: dict[str, CandidateCallerDefinition] = {
            "candidate_caller_definition.symbol": replace(
                caller,
                symbol="?StartHide@HudUiMgrObjective@@Wrong",
            ),
            "candidate_caller_definition.data_size": replace(
                caller,
                data=caller.data + b"\x00",
                relocation_mask=caller.relocation_mask + (False,),
            ),
        }
        wrong_prefix = bytearray(caller.data)
        wrong_prefix[0] ^= 0x01
        cases["candidate_caller_definition.prefix_bytes"] = replace(
            caller,
            data=bytes(wrong_prefix),
        )
        wrong_target = list(caller.relocations)
        wrong_target[13] = replace(
            wrong_target[13],
            symbol_name="?wrong@@3HA",
        )
        cases[
            "candidate_caller_definition.prefix_relocation_targets"
        ] = replace(caller, relocations=tuple(wrong_target))
        wrong_type = list(caller.relocations)
        wrong_type[13] = replace(wrong_type[13], type=0x14)
        cases[
            "candidate_caller_definition.prefix_relocation_types"
        ] = replace(caller, relocations=tuple(wrong_type))
        wrong_addend = bytearray(caller.data)
        struct.pack_into("<I", wrong_addend, 0x84, 0x97C)
        cases[
            "candidate_caller_definition.prefix_relocation_addends"
        ] = replace(caller, data=bytes(wrong_addend))
        cases[
            "candidate_caller_definition.relocation_mask_size"
        ] = replace(caller, relocation_mask=caller.relocation_mask[:-1])
        mask = list(caller.relocation_mask)
        mask[0x84] = False
        cases[
            "candidate_caller_definition.prefix_relocation_mask"
        ] = replace(caller, relocation_mask=tuple(mask))
        cases[
            "candidate_caller_definition.aggregate_external_count"
        ] = replace(
            caller,
            undefined_external_data=(fixture["time_symbol"],),
        )
        cases[
            "candidate_caller_definition.time_external_count"
        ] = replace(
            caller,
            undefined_external_data=(fixture["aggregate"],),
        )
        for field, definition in cases.items():
            with self.subTest(relocation_field=field):
                self._assert_hud_objective_start_hide_bar_vptr_rejects(
                    fixture,
                    field,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

        positive_one = caller.local_static_definitions[0]
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "positive_one_literal.match_count",
            candidate=replace(
                fixture["candidate"],
                caller_definition=replace(
                    caller,
                    local_static_definitions=(
                        replace(
                            positive_one,
                            data=bytes.fromhex("00 00 00 3f"),
                        ),
                    ),
                ),
            ),
        )
        self._assert_hud_objective_start_hide_bar_vptr_rejects(
            fixture,
            "positive_one_literal.name_count",
            candidate=replace(
                fixture["candidate"],
                caller_definition=replace(
                    caller,
                    local_static_definitions=(
                        positive_one,
                        replace(positive_one, section_name=".data"),
                    ),
                ),
            ),
        )

