    def test_hud_objective_start_hide_widget_vptr_exact_contract_and_scope(
        self,
    ) -> None:
        fixture = self._hud_objective_start_hide_widget_vptr_fixture()
        bar_absolute, bar_vptr = (
            self._hud_objective_start_hide_bar_vptr_bridges(fixture)
        )
        widget_absolute, widget_vptr = (
            self._hud_objective_start_hide_widget_vptr_bridges(fixture)
        )
        self.assertEqual({"0x9a"}, set(widget_absolute))
        self.assertEqual({"0xa7"}, set(widget_vptr))
        self.assertEqual(
            fixture["expected"],
            extract_invocation_contract(
                fixture["candidate"].instructions,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x411ac0",
                caller_end_exclusive="0x411eb0",
                indexes=fixture["indexes"],
                compiler_generated_bridges={
                    "__ftol": "provider:recoil:function:0x4c60a6",
                },
                reviewed_absolute_storage_load_bridges={
                    **bar_absolute,
                    **widget_absolute,
                },
                reviewed_vptr_storage_bridges={
                    **bar_vptr,
                    **widget_vptr,
                },
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register storage edx",
        ):
            extract_invocation_contract(
                fixture["candidate"].instructions,
                source="cod",
                caller_identity=fixture["caller_identity"],
                caller_start="0x411ac0",
                caller_end_exclusive="0x411eb0",
                indexes=fixture["indexes"],
                compiler_generated_bridges={
                    "__ftol": "provider:recoil:function:0x4c60a6",
                },
                reviewed_absolute_storage_load_bridges=bar_absolute,
                reviewed_vptr_storage_bridges=bar_vptr,
            )
        self.assertEqual(
            ({}, {}),
            _hud_ui_mgr_objective_start_hide_widget_candidate_vptr_bridges(
                fixture["expected"],
                fixture["candidate"],
                document=fixture["document"],
                caller_identity="symbol:recoil:function:0x411a20",
                caller_start="0x411a20",
                caller_end_exclusive="0x411ac0",
                indexes=fixture["indexes"],
            ),
        )

    def test_hud_objective_start_hide_widget_vptr_rejects_contract_and_reaching_definition_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_start_hide_widget_vptr_fixture()
        for name, ordinal, key, value in (
            ("ftol-provider", 1, "target_identity", "provider:wrong"),
            ("ftol-cleanup", 1, "cleanup_bytes", 4),
            ("storage", 2, "storage_identity", "load(storage:wrong)"),
            ("slot", 2, "slot_displacement", 0x14),
            ("cleanup", 2, "cleanup_bytes", 4),
        ):
            drifted_expected = deepcopy(fixture["expected"])
            drifted_expected[ordinal][key] = value
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "immutable retail ordinal-1",
            ):
                _hud_ui_mgr_objective_start_hide_widget_candidate_vptr_bridges(
                    drifted_expected,
                    fixture["candidate"],
                    document=fixture["document"],
                    caller_identity=fixture["caller_identity"],
                    caller_start="0x411ac0",
                    caller_end_exclusive="0x411eb0",
                    indexes=fixture["indexes"],
                )

        instruction_cases = {
            "load-register": [
                *fixture["rows"][:-5],
                (
                    "  0009a 8b 0d ac 06 00 00 mov ecx, dword "
                    f"{fixture['aggregate']}+1708"
                ),
                *fixture["rows"][-4:],
            ],
            "load-storage": [
                *fixture["rows"][:-5],
                (
                    "  0009a 8b 15 b0 06 00 00 mov edx, dword "
                    f"{fixture['aggregate']}+1712"
                ),
                *fixture["rows"][-4:],
            ],
            "receiver": [
                *fixture["rows"][:-3],
                (
                    "  000a1 b9 b0 06 00 00 mov ecx, OFFSET FLAT:"
                    f"{fixture['aggregate']}+1712"
                ),
                *fixture["rows"][-2:],
            ],
            "slot": [
                *fixture["rows"][:-1],
                "  000a7 ff 52 14 call dword [edx+20]",
            ],
        }
        for name, rows in instruction_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "exact candidate|reaching-definition",
            ):
                self._hud_objective_start_hide_widget_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(
                            parse_assembly("\n".join(rows), source="cod")
                        ),
                    ),
                )

    def test_hud_objective_start_hide_widget_vptr_rejects_relocation_and_flow_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_start_hide_widget_vptr_fixture()
        caller = fixture["caller"]
        cases: dict[str, CandidateCallerDefinition] = {}

        wrong_target = list(caller.relocations)
        wrong_target[-2] = replace(wrong_target[-2], symbol_name="?wrong@@3HA")
        cases["target"] = replace(caller, relocations=tuple(wrong_target))

        wrong_type = list(caller.relocations)
        wrong_type[-3] = replace(wrong_type[-3], type=0x06)
        cases["type"] = replace(caller, relocations=tuple(wrong_type))

        wrong_addend = bytearray(caller.data)
        struct.pack_into("<I", wrong_addend, 0x9C, 0x6B0)
        cases["addend"] = replace(caller, data=bytes(wrong_addend))

        mask = list(caller.relocation_mask)
        mask[0xA2] = False
        cases["mask"] = replace(caller, relocation_mask=tuple(mask))

        reordered = list(caller.relocations)
        reordered[-2:] = reversed(reordered[-2:])
        cases["order"] = replace(caller, relocations=tuple(reordered))

        cases["external"] = replace(
            caller,
            undefined_external_functions=(),
        )

        for name, definition in cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "0x400 cumulative caller prefix",
            ):
                self._hud_objective_start_hide_widget_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )

        for name, rows in {
            "eax-clobber": [
                *fixture["rows"][:-5],
                "  00099 8b c1 mov eax, ecx",
                *fixture["rows"][-5:],
            ],
            "edx-clobber": [
                *fixture["rows"][:-1],
                "  000a6 8b d0 mov edx, eax",
                fixture["rows"][-1],
            ],
            "ecx-clobber": [
                *fixture["rows"][:-1],
                "  000a6 8b c8 mov ecx, eax",
                fixture["rows"][-1],
            ],
            "cleanup": [
                *fixture["rows"],
                "  000aa 83 c4 04 add esp, 4",
            ],
            "branch": [
                *fixture["rows"][:-1],
                "  000a6 75 01 jne $Lalternate",
                fixture["rows"][-1],
            ],
        }.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "clobber|call order, cleanup|exact candidate",
            ):
                self._hud_objective_start_hide_widget_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(
                            parse_assembly("\n".join(rows), source="cod")
                        ),
                    ),
                )

        with self.assertRaisesRegex(
            ValueError,
            "candidate_local_control_flow_indices",
        ):
            self._hud_objective_start_hide_widget_vptr_bridges(
                fixture,
                candidate=replace(
                    fixture["candidate"],
                    local_control_flow_indices=frozenset({0}),
                    local_control_flow_targets={0: (16,)},
                ),
            )


