    def test_hud_objective_update_vptr_rejects_contract_count_storage_slot_register_and_cleanup_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_update_vptr_fixture()
        for name, ordinal, key, value in (
            ("direct-dispatch", 0, "dispatch", "direct"),
            ("retail-storage", 2, "storage_identity", "load(storage:wrong)"),
            ("retail-slot", 4, "slot_displacement", 0x64),
            ("retail-cleanup", 1, "cleanup_bytes", 4),
        ):
            drifted_expected = deepcopy(fixture["expected"])
            drifted_expected[ordinal][key] = value
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "immutable retail five-call",
            ):
                _hud_ui_mgr_objective_update_candidate_vptr_bridges(
                    drifted_expected,
                    fixture["candidate"],
                    document=fixture["document"],
                    caller_identity=fixture["caller_identity"],
                    caller_start="0x411eb0",
                    caller_end_exclusive="0x411f10",
                    indexes=fixture["indexes"],
                )

        rows = fixture["rows"]
        row_cases = {
            "missing-call": [
                row for row in rows if not row.startswith("  00050 ")
            ],
            "wrong-order": [
                *rows,
                "  00051 ff 50 60 call dword [eax+96]",
            ],
            "direct-call": [
                (
                    "  0000c e8 00 00 00 00 call ?Wrong@@YIXXZ"
                    if row.startswith("  0000c ")
                    else row
                )
                for row in rows
            ],
            "storage": [
                (
                    "  00053 a1 6c 07 00 00 mov eax, dword "
                    f"{fixture['aggregate']}+1900"
                    if row.startswith("  00053 ")
                    else row
                )
                for row in rows
            ],
            "slot": [
                (
                    "  0005f ff 50 64 call dword [eax+100]"
                    if row.startswith("  0005f ")
                    else row
                )
                for row in rows
            ],
            "register": [
                (
                    "  00018 8b 05 78 09 00 00 mov eax, dword "
                    f"{fixture['aggregate']}+2424"
                    if row.startswith("  00018 ")
                    else row
                )
                for row in rows
            ],
            "cleanup": [
                *rows[:-1],
                "  00062 83 c4 04 add esp, 4",
                rows[-1],
            ],
        }
        for name, drifted_rows in row_cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "exact aggregate load|five-call count/order",
            ):
                self._hud_objective_update_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        instructions=tuple(
                            parse_assembly(
                                "\n".join(drifted_rows),
                                source="cod",
                            )
                        ),
                    ),
                )

    def test_hud_objective_update_vptr_rejects_extent_relocation_external_and_mask_drift(
        self,
    ) -> None:
        fixture = self._hud_objective_update_vptr_fixture()
        caller = fixture["caller"]
        cases: dict[str, CandidateCallerDefinition] = {}
        cases["extent"] = replace(
            caller,
            data=caller.data[:-1],
            relocation_mask=caller.relocation_mask[:-1],
        )
        wrong_target = list(caller.relocations)
        wrong_target[6] = replace(
            wrong_target[6],
            symbol_name="?wrong@@3HA",
        )
        cases["target"] = replace(
            caller,
            relocations=tuple(wrong_target),
        )
        wrong_type = list(caller.relocations)
        wrong_type[4] = replace(wrong_type[4], type=0x14)
        cases["type"] = replace(
            caller,
            relocations=tuple(wrong_type),
        )
        wrong_addend = bytearray(caller.data)
        struct.pack_into("<I", wrong_addend, 0x44, 0x82C)
        cases["addend"] = replace(
            caller,
            data=bytes(wrong_addend),
        )
        reordered = list(caller.relocations)
        reordered[6:8] = reversed(reordered[6:8])
        cases["order"] = replace(
            caller,
            relocations=tuple(reordered),
        )
        mask = list(caller.relocation_mask)
        mask[0x44] = False
        cases["mask"] = replace(
            caller,
            relocation_mask=tuple(mask),
        )
        cases["external-data"] = replace(
            caller,
            undefined_external_data=(),
        )
        cases["external-function"] = replace(
            caller,
            defined_external_functions=(),
        )
        for name, definition in cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "exact natural 0x70 COFF",
            ):
                self._hud_objective_update_vptr_bridges(
                    fixture,
                    candidate=replace(
                        fixture["candidate"],
                        caller_definition=definition,
                    ),
                )


