    def prove(self, fixture: dict, **overrides: object) -> dict[str, str]:
        arguments = {
            "document": fixture["document"],
            "caller_identity": self.caller_identity,
            "caller_start": "0x43d740",
            "caller_end_exclusive": "0x43d980",
            "indexes": fixture["indexes"],
            "bridge_names": fixture["bridge_names"],
            "ordinal_import_thunks": fixture["ordinal_import_thunks"],
        }
        arguments.update(overrides)
        return _wol_cedit_provider_candidate_bridge(
            fixture["expected"],
            fixture["candidate"],
            **arguments,
        )

    def rebuild_document(self, fixture: dict) -> None:
        first_identity = fixture["indexes"].by_candidate_name[
            self.first_symbol
        ]
        last_identity = fixture["indexes"].by_candidate_name[
            self.last_symbol
        ]
        fixture["document"] = ProgressDocument(fixture["data"])
        fixture["indexes"] = build_identity_indexes(fixture["document"])
        fixture["indexes"] = replace(
            fixture["indexes"],
            by_address={
                **fixture["indexes"].by_address,
                "0x43d740": self.caller_token,
            },
            by_candidate_name={
                **fixture["indexes"].by_candidate_name,
                self.first_symbol: first_identity,
                self.last_symbol: last_identity,
            },
        )

    def expected_bridge_map(self) -> dict[str, str]:
        return {
            **{
                symbol: self.target_identity
                for symbol in self.control_symbols
            },
            self.cstring_symbol: self.cstring_target_identity,
        }

    def test_exact_wol_cedit_provider_bridge(self) -> None:
        fixture = self.fixture()
        self.assertNotEqual(self.caller_token, self.caller_id)
        self.assertEqual(
            self.caller_token,
            fixture["indexes"].by_address["0x43d740"],
        )
        self.assertIsNone(
            fixture["data"]["symbols"][self.caller_id].get(
                "authored_order_role"
            )
        )
        definition = fixture["candidate"].caller_definition
        self.assertEqual(432, len(definition.data))
        self.assertEqual(0, definition.section_start)
        self.assertEqual(432, definition.section_end)
        self.assertEqual(26, len(definition.relocations))
        self.assertTrue(
            set(self.control_destructor_symbols).issubset(
                definition.undefined_external_functions
            )
        )
        bridges = self.prove(fixture)
        self.assertEqual(
            self.expected_bridge_map(),
            bridges,
        )
        self.assertEqual(
            fixture["expected"],
            extract_invocation_contract(
                fixture["candidate"].instructions,
                source="cod",
                caller_identity=self.caller_identity,
                caller_start="0x43d740",
                caller_end_exclusive="0x43d980",
                indexes=fixture["indexes"],
                bridge_names=fixture["bridge_names"],
                compiler_generated_bridges=bridges,
            ),
        )
        self.assertEqual(
            {},
            self.prove(
                fixture,
                caller_identity="symbol:recoil:function:0x43d720",
                caller_start="0x43d720",
                caller_end_exclusive="0x43d740",
            ),
        )

    def test_wol_control_bridges_feed_complete_ordinal_producer_extraction(
        self,
    ) -> None:
        fixture = self.fixture()
        wol_bridges = self.prove(fixture)
        ordinal_indexes = replace(
            fixture["indexes"],
            storage_by_name={
                **fixture["indexes"].storage_by_name,
                self.cstring_iat_object_symbol: (
                    fixture["ordinal_import_thunks"][0].iat_identity
                ),
            },
        )
        arguments = {
            "thunks": fixture["ordinal_import_thunks"],
            "caller_identity": self.caller_identity,
            "caller_start": "0x43d740",
            "caller_end_exclusive": "0x43d980",
            "indexes": ordinal_indexes,
            "bridge_names": fixture["bridge_names"],
            "reviewed_candidate_direct_bridges": {},
        }

        self.assertEqual(
            {self.cstring_symbol: self.cstring_target_identity},
            call_contract_verify_module._provider_ordinal_import_thunk_candidate_bridges_from_reviewed_directs(
                fixture["expected"],
                fixture["candidate"],
                supplemental_candidate_direct_bridges=wol_bridges,
                **arguments,
            ),
        )

        missing_control_bridges = dict(wol_bridges)
        del missing_control_bridges[self.candidate_symbol]
        with self.assertRaisesRegex(
            ValueError,
            re.escape(self.candidate_symbol),
        ):
            call_contract_verify_module._provider_ordinal_import_thunk_candidate_bridges_from_reviewed_directs(
                fixture["expected"],
                fixture["candidate"],
                supplemental_candidate_direct_bridges=(
                    missing_control_bridges
                ),
                **arguments,
            )

        with self.assertRaisesRegex(
            ValueError,
            "conflicts with another reviewed direct identity",
        ):
            call_contract_verify_module._provider_ordinal_import_thunk_candidate_bridges_from_reviewed_directs(
                fixture["expected"],
                fixture["candidate"],
                supplemental_candidate_direct_bridges=wol_bridges,
                **{
                    **arguments,
                    "reviewed_candidate_direct_bridges": {
                        self.candidate_symbol: (
                            "provider:recoil:function:0x4c5bb2"
                        )
                    },
                },
            )

        wrong_ordinal_bridges = {
            **wol_bridges,
            self.cstring_symbol: "provider:recoil:function:0x4c5ba6",
        }
        with self.assertRaisesRegex(
            ValueError,
            "conflicts with the ordinal producer identity",
        ):
            call_contract_verify_module._provider_ordinal_import_thunk_candidate_bridges_from_reviewed_directs(
                fixture["expected"],
                fixture["candidate"],
                supplemental_candidate_direct_bridges=wrong_ordinal_bridges,
                **arguments,
            )

    def test_wol_ordinal_supplemental_composition_includes_chkstk_fail_closed(
        self,
    ) -> None:
        chkstk_identity = "provider:recoil:function:0x4c6100"
        composed = (
            call_contract_verify_module._compose_supplemental_candidate_direct_bridges(
                {self.candidate_symbol: self.target_identity},
                {"__chkstk": chkstk_identity},
                {"__chkstk": chkstk_identity},
            )
        )
        self.assertEqual(self.target_identity, composed[self.candidate_symbol])
        self.assertEqual(chkstk_identity, composed["__chkstk"])

        with self.assertRaisesRegex(
            ValueError,
            "supplemental candidate direct bridge producers conflict",
        ):
            call_contract_verify_module._compose_supplemental_candidate_direct_bridges(
                {"__chkstk": chkstk_identity},
                {"__chkstk": "provider:recoil:function:0x4c6101"},
            )

