    def test_wol_cedit_bridge_rejects_bn_import_and_alias_drift(self) -> None:
        for attribute, value in (
            ("address", "0x4c5bb2"),
            ("name", "??0CDialog@@QAE@XZ"),
            ("raw_name", "??0CDialog@@QAE@XZ"),
            ("full_name", "CDialog::CDialog(CDialog* this)"),
            ("kind", "function"),
        ):
            with self.subTest(attribute=attribute):
                fixture = self.fixture()
                symbol = fixture["bridge_names"][self.retail_name][0]
                setattr(symbol, attribute, value)
                with self.assertRaisesRegex(
                    ValueError, "current-provider"
                ):
                    self.prove(fixture)

        fixture = self.fixture()
        fixture["bridge_names"][self.retail_full_name] = [
            deepcopy(fixture["bridge_names"][self.retail_name][0])
        ]
        with self.assertRaisesRegex(ValueError, "identical current import"):
            self.prove(fixture)

        fixture = self.fixture()
