    def _zinterp_camera_owner_fixture(
        self,
        *,
        shift: int = 0,
        generation_shaped_coordinate_gap: bool = False,
        direct_route: bool = False,
        unrelated_trailing_cod_directive: bool = False,
    ) -> dict[str, object]:
        module = call_contract_verify_module
        lines: list[str] = []
        encoded: dict[int, bytes] = {}

        def add(offset: int, raw: str, text_value: str) -> None:
            body = bytes.fromhex(raw)
            current = offset + shift
            encoded[current] = body
            lines.append(f"{current:05x} {body.hex(' ')} {text_value}")

        add(
            0x00,
            "68 00 00 00 00",
            "push OFFSET FLAT:" + module._ZINTERP_CAMERA_ROTATE_LITERAL_SYMBOL,
        )
        rotate_calls = (
            (0x10, "ff d7", "edi"),
            (0x20, "e8 00 00 00 00", "?ParseFloatToken@zInterp_Context@@QAEMXZ"),
            (0x30, "e8 00 00 00 00", "?ParseFloatToken@zInterp_Context@@QAEMXZ"),
            (0x40, "e8 00 00 00 00", "?ParseFloatToken@zInterp_Context@@QAEMXZ"),
            (
                0x50,
                "e8 00 00 00 00",
                "?gwCameraSetPosition@zClass_Camera@@"
                "YIHPAUzClass_NodePartial@@MMM@Z",
            ),
        )
        for offset, raw, target in rotate_calls:
            add(offset, raw, f"call {target}")
        add(0x58, "c2 04 00", "ret 4")

        add(0x60, "8b 56 20", "mov edx, DWORD PTR [esi+32]")
        add(
            0x63,
            "bf 00 00 00 00",
            "mov edi, OFFSET FLAT:"
            + module._ZINTERP_CAMERA_GET_TRANSLATE_LITERAL_SYMBOL,
        )
        inline_rows = (
            (0x68, "8b c2", "mov eax, edx"),
            (0x6A, "8a 10", "mov dl, BYTE PTR [eax]"),
            (0x6C, "8a ca", "mov cl, dl"),
            (0x6E, "3a 17", "cmp dl, BYTE PTR [edi]"),
            (0x70, "75 22", "jne 0x94"),
            (0x72, "84 c9", "test cl, cl"),
            (0x74, "74 16", "je 0x8c"),
            (0x76, "8a 50 01", "mov dl, BYTE PTR [eax+1]"),
            (0x79, "8a ca", "mov cl, dl"),
            (0x7B, "3a 57 01", "cmp dl, BYTE PTR [edi+1]"),
            (0x7E, "75 14", "jne 0x94"),
            (0x80, "83 c0 02", "add eax, 2"),
            (0x83, "83 c7 02", "add edi, 2"),
            (0x86, "84 c9", "test cl, cl"),
            (0x88, "75 e0", "jne 0x6a"),
            (0x8A, "33 c0", "xor eax, eax"),
            (0x8C, "eb 05", "jmp 0x93"),
            (0x8E, "1b c0", "sbb eax, eax"),
            (0x90, "83 d8 ff", "sbb eax, -1"),
            (0x93, "85 c0", "test eax, eax"),
            (0x95, "75 49", "jne 0xe0"),
        ) + (
            (
                (0x1C7, "8b 8e c8 00 00 00", "mov ecx, DWORD PTR [esi+200]"),
                (0x1CD, "85 c9", "test ecx, ecx"),
                (0x1CF, "0f 84 46 00 00 00", "je 0x21b"),
                (0x1D5, "8d 54 24 28", "lea edx, DWORD PTR [esp+40]"),
                (0x1D9, "8d 44 24 14", "lea eax, DWORD PTR [esp+20]"),
                (0x1DD, "52", "push edx"),
                (0x1DE, "50", "push eax"),
                (0x1DF, "8d 54 24 18", "lea edx, DWORD PTR [esp+24]"),
            )
            if direct_route
            else (
                (0x97, "8b be c8 00 00 00", "mov edi, DWORD PTR [esi+200]"),
                (0x9D, "33 db", "xor ebx, ebx"),
                (0x9F, "3b fb", "cmp edi, ebx"),
                (0xA1, "74 75", "je 0x118"),
                (0xA3, "89 5c 24 10", "mov DWORD PTR [esp+16], ebx"),
                (0xA7, "89 5c 24 14", "mov DWORD PTR [esp+20], ebx"),
                (0xAB, "89 5c 24 28", "mov DWORD PTR [esp+40], ebx"),
                (0xAF, "8d 54 24 28", "lea edx, DWORD PTR [esp+40]"),
                (0xB3, "8d 44 24 14", "lea eax, DWORD PTR [esp+20]"),
                (0xB7, "52", "push edx"),
                (0xB8, "50", "push eax"),
                (0xB9, "8d 54 24 18", "lea edx, DWORD PTR [esp+24]"),
                (0xBD, "8b cf", "mov ecx, edi"),
            )
        )
        for offset, raw, text_value in inline_rows:
            add(offset, raw, text_value)
        get_target_offset = 0x1E3 if direct_route else 0xBF
        logf_offset = 0x213 if direct_route else 0x10D
        cleanup_offset = 0x218 if direct_route else 0x112
        add(
            get_target_offset,
            "e8 00 00 00 00",
            "call ?gwCameraGetTarget@zClass_Camera@@"
            "YIHPAUzClass_NodePartial@@PAM11@Z",
        )
        if direct_route:
            add(0x1E8, "d9 44 24 28", "fld DWORD PTR [esp+40]")
            add(0x1EF, "8b 8e c8 00 00 00", "mov ecx, DWORD PTR [esi+200]")
            add(0x20C, "51", "push ecx")
            add(0x20D, "68 00 00 00 00", "push OFFSET FLAT:" + module._ZINTERP_SHARED_LOGF_FORMAT_SYMBOL)
            add(0x212, "56", "push esi")
            add(0x213, "e8 00 00 00 00", "call " + module._ZINTERP_LOGF_CANDIDATE_SYMBOL)
            add(0x218, "83 c4 24", "add esp, 36")
            add(0x21B, "c2 04 00", "ret 4")
        else:
            add(0xC4, "d9 44 24 28", "fld DWORD PTR [esp+40]")
            add(0xC8, "e9 33 00 00 00", "jmp 0x100")
            add(0x100, "83 ec 08", "sub esp, 8")
            add(0x103, "dd 1c 24", "fstp QWORD PTR [esp]")
            add(0x106, "57", "push edi")
            add(
                0x107,
                "68 00 00 00 00",
                "push OFFSET FLAT:" + module._ZINTERP_SHARED_LOGF_FORMAT_SYMBOL,
            )
            add(0x10C, "56", "push esi")
            add(
                0x10D,
                "e8 00 00 00 00",
                "call " + module._ZINTERP_LOGF_CANDIDATE_SYMBOL,
            )
            add(0x112, "83 c4 24", "add esp, 36")
            add(0x115, "c2 04 00", "ret 4")
        if not direct_route:
            add(0x118, "c2 04 00", "ret 4")

        instructions = list(parse_assembly("\n".join(lines), source="cod"))
        if generation_shaped_coordinate_gap:
            gap_index = next(
                index
                for index, instruction in enumerate(instructions)
                if module.address_value(instruction.source_line.split()[0])
                == 0x72 + shift
            )
            instructions[gap_index] = replace(
                instructions[gap_index],
                source_line="\t00\t\t test\t cl, cl",
            )
        data = bytearray((0x240 if direct_route else 0x180) + shift)
        if unrelated_trailing_cod_directive:
            trailing_offset = len(data) - 4
            instructions.extend(
                parse_assembly(
                    f"{trailing_offset:05x} 00 00 00 00 DD $Ltail",
                    source="cod",
                )
            )
        for offset, raw in encoded.items():
            data[offset : offset + len(raw)] = raw
        relocations = (
            CoffRelocation(
                0x01 + shift, 1, 0x06,
                module._ZINTERP_CAMERA_ROTATE_LITERAL_SYMBOL,
            ),
            CoffRelocation(
                0x64 + shift, 2, 0x06,
                module._ZINTERP_CAMERA_GET_TRANSLATE_LITERAL_SYMBOL,
            ),
            CoffRelocation(
                get_target_offset + 1 + shift, 3, 0x14,
                "?gwCameraGetTarget@zClass_Camera@@"
                "YIHPAUzClass_NodePartial@@PAM11@Z",
            ),
            CoffRelocation(
                (0x20E if direct_route else 0x108) + shift, 4, 0x06,
                module._ZINTERP_SHARED_LOGF_FORMAT_SYMBOL,
            ),
            CoffRelocation(
                logf_offset + 1 + shift, 5, 0x14,
                module._ZINTERP_LOGF_CANDIDATE_SYMBOL,
            ),
        )
        relocation_mask = [False] * len(data)
        for relocation in relocations:
            relocation_mask[relocation.offset : relocation.offset + 4] = (
                [True] * 4
            )
        candidate = CandidateAssembly(
            instructions=tuple(instructions),
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
            caller_definition=CandidateCallerDefinition(
                symbol=module._ZINTERP_SHARED_LOGF_CANDIDATE_CALLER,
                data=bytes(data),
                relocations=relocations,
                relocation_mask=tuple(relocation_mask),
                undefined_external_functions=(),
                section_start=0,
                section_end=len(data),
            ),
        )

        def row(
            identity: str,
            *,
            dispatch: str = "direct",
            identity_kind: str = "direct",
            storage: str = "",
            cleanup: int | None = None,
        ) -> dict[str, object]:
            return {
                "ordinal": 0,
                "form": "call",
                "dispatch": dispatch,
                "identity_kind": identity_kind,
                "target_identity": identity,
                "storage_identity": storage,
                "slot_displacement": None,
                "cleanup_bytes": cleanup,
            }

        contract = [
            row(
                "iat:strncmp",
                dispatch="indirect",
                identity_kind="iat",
                storage="iat:strncmp",
                cleanup=12,
            ),
            row("symbol:parse-float"),
            row("symbol:parse-float"),
            row("symbol:parse-float"),
            row("symbol:camera-set-position"),
            row("symbol:camera-get-target"),
            row(module._ZINTERP_LOGF_CALLER_IDENTITY, cleanup=36),
        ]
        for ordinal, contract_row in enumerate(contract):
            contract_row["ordinal"] = ordinal
        expected = deepcopy(contract)
        expected.append(
            row(module._ZINTERP_LOGF_CALLER_IDENTITY, cleanup=36)
        )
        for ordinal, contract_row in enumerate(expected):
            contract_row["ordinal"] = ordinal
        call_offsets = (
            0x10, 0x20, 0x30, 0x40, 0x50,
            get_target_offset, logf_offset,
        )
        call_sites = [
            module.normalize_address(
                module.address_value(module._ZINTERP_SHARED_LOGF_CALLER_START)
                + shift
                + offset
            )
            for offset in call_offsets
        ]
        return {
            "expected": expected,
            "contract": contract,
            "candidate": candidate,
            "call_sites": call_sites,
            "rotate_return": 0x58 + shift,
            "inline_compare": 0x6E + shift,
            "null_gate": 0xA1 + shift,
            "get_target": 0xBF + shift,
            "route_branch": None if direct_route else 0xC8 + shift,
            "first_logf": logf_offset + shift,
            "first_cleanup": cleanup_offset + shift,
        }

    def _validate_zinterp_camera_owner(
        self,
        fixture: Mapping[str, object],
    ) -> list[dict[str, object]]:
        module = call_contract_verify_module
        return module._zinterp_camera_owner_candidate_validation(
            fixture["expected"],
            fixture["contract"],
            fixture["candidate"],
            fixture["call_sites"],
            caller_identity=module._ZINTERP_SHARED_LOGF_CALLER_IDENTITY,
            caller_start=module._ZINTERP_SHARED_LOGF_CALLER_START,
            caller_end_exclusive=module._ZINTERP_SHARED_LOGF_CALLER_END_EXCLUSIVE,
        )

    @staticmethod
    def _replace_zinterp_camera_instruction(
        fixture: dict[str, object],
        offset: int,
        replacement_line: str | None,
    ) -> None:
        module = call_contract_verify_module
        candidate = fixture["candidate"]
        rows = list(candidate.instructions)
        index = next(
            index
            for index, instruction in enumerate(rows)
            if module.address_value(instruction.source_line.split()[0]) == offset
        )
        if replacement_line is None:
            rows.pop(index)
        else:
            rows[index] = parse_assembly(replacement_line, source="cod")[0]
        fixture["candidate"] = replace(candidate, instructions=tuple(rows))

    def test_zinterp_camera_owner_validation_accepts_generation_shaped_source(
        self,
    ) -> None:
        module = call_contract_verify_module
        for shift, generation_gap in ((0, True), (0x40, False)):
            with self.subTest(shift=shift, generation_gap=generation_gap):
                fixture = self._zinterp_camera_owner_fixture(
                    shift=shift,
                    generation_shaped_coordinate_gap=generation_gap,
                )
                validated = self._validate_zinterp_camera_owner(fixture)
                self.assertEqual(fixture["contract"], validated)
                self.assertFalse(
                    compare_call_contracts(
                        fixture["expected"], validated
                    )["passed"]
                )
                self.assertEqual(
                    1,
                    sum(
                        row["target_identity"]
                        == module._ZINTERP_LOGF_CALLER_IDENTITY
                        and row["cleanup_bytes"] == 36
                        for row in validated
                    ),
                )
        direct = self._zinterp_camera_owner_fixture(
            shift=0x80,
            direct_route=True,
            unrelated_trailing_cod_directive=True,
        )
        validated = self._validate_zinterp_camera_owner(direct)
        self.assertEqual(direct["contract"], validated)

    def test_zinterp_camera_owner_validation_fails_closed_on_independent_drift(
        self,
    ) -> None:
        module = call_contract_verify_module

        def rejected(fixture: dict[str, object], detail: str) -> None:
            with self.assertRaisesRegex(
                ValueError,
                "camera owner validation drifted: .*" + detail,
            ):
                self._validate_zinterp_camera_owner(fixture)

        command_identity = self._zinterp_camera_owner_fixture()
        candidate = command_identity["candidate"]
        caller = candidate.caller_definition
        relocations = list(caller.relocations)
        relocations[0] = replace(
            relocations[0], symbol_name="wrong-camera-command"
        )
        command_identity["candidate"] = replace(
            candidate,
            caller_definition=replace(caller, relocations=tuple(relocations)),
        )
        rejected(command_identity, "unique command literal")

        command_order = self._zinterp_camera_owner_fixture()
        candidate = command_order["candidate"]
        caller = candidate.caller_definition
        relocations = list(caller.relocations)
        relocations[0] = replace(
            relocations[0],
            symbol_name=module._ZINTERP_CAMERA_GET_TRANSLATE_LITERAL_SYMBOL,
        )
        relocations[1] = replace(
            relocations[1],
            symbol_name=module._ZINTERP_CAMERA_ROTATE_LITERAL_SYMBOL,
        )
        command_order["candidate"] = replace(
            candidate,
            caller_definition=replace(caller, relocations=tuple(relocations)),
        )
        rejected(command_order, "command identity or order")

        rotate_calls = self._zinterp_camera_owner_fixture()
        self._replace_zinterp_camera_instruction(
            rotate_calls,
            0x30,
            "00030 e8 00 00 00 00 call ?WrongParseFloat@@YAXXZ",
        )
        rejected(rotate_calls, "ParseFloat x3")

        rotate_return = self._zinterp_camera_owner_fixture()
        self._replace_zinterp_camera_instruction(
            rotate_return, rotate_return["rotate_return"], None
        )
        rejected(rotate_return, "immediate post-SetPosition return")

        inline_compare = self._zinterp_camera_owner_fixture()
