    def _validate_zinterp_load_prepared_tailfold(
        self,
        fixture: Mapping[str, object],
    ) -> list[dict[str, object]]:
        module = call_contract_verify_module
        return module._zinterp_load_prepared_fclose_tailfold_candidate_projection(
            fixture["expected"],
            fixture["contract"],
            fixture["candidate"],
            fixture["call_sites"],
            caller_identity=module._ZINTERP_LOAD_PREPARED_CALLER_IDENTITY,
            caller_start=module._ZINTERP_LOAD_PREPARED_CALLER_START,
            caller_end_exclusive=(
                module._ZINTERP_LOAD_PREPARED_CALLER_END_EXCLUSIVE
            ),
        )

    def test_zinterp_load_prepared_projects_only_shared_fclose_tail(self) -> None:
        fixture = self._zinterp_load_prepared_tailfold_fixture()
        projected = self._validate_zinterp_load_prepared_tailfold(fixture)
        self.assertEqual(fixture["expected"], projected)
        self.assertEqual(12, len(projected))
        self.assertEqual(
            [3, 5, 8, 10],
            [
                row["ordinal"]
                for row in projected
                if row["target_identity"] == "iat:fclose"
            ],
        )
        self.assertEqual("iat:_stat", projected[9]["target_identity"])
        self.assertEqual("iat:free", projected[11]["target_identity"])
        self.assertNotEqual("iat:fclose", projected[-1]["target_identity"])

    def test_zinterp_load_prepared_tailfold_fails_closed_on_drift(self) -> None:
        def rejected(fixture: dict[str, object], detail: str) -> None:
            with self.assertRaisesRegex(
                ValueError,
                "LoadPreparedScriptIndex fclose tail-fold projection drifted: .*"
                + detail,
            ):
                self._validate_zinterp_load_prepared_tailfold(fixture)

        branch = self._zinterp_load_prepared_tailfold_fixture()
        candidate = branch["candidate"]
        rows = list(candidate.instructions)
        index = next(
            index
            for index, row in enumerate(rows)
            if row.source_line.split()[0] == "00080"
        )
        rows[index] = parse_assembly(
            "00080 e9 35 01 00 00 jmp 0x1ba", source="cod"
        )[0]
        data = bytearray(candidate.caller_definition.data)
        data[0x80:0x85] = bytes.fromhex("e9 35 01 00 00")
        branch["candidate"] = replace(
            candidate,
            instructions=tuple(rows),
            caller_definition=replace(
                candidate.caller_definition, data=bytes(data)
            ),
        )
        rejected(branch, "ingress control flow")

        relocation = self._zinterp_load_prepared_tailfold_fixture()
        candidate = relocation["candidate"]
        caller = candidate.caller_definition
        relocations = list(caller.relocations)
        relocations[-1] = replace(relocations[-1], symbol_name="__imp__free")
        relocation["candidate"] = replace(
            candidate,
            caller_definition=replace(caller, relocations=tuple(relocations)),
        )
        rejected(relocation, "relocations or masks")

        stale = self._zinterp_load_prepared_tailfold_fixture()
        contract = list(stale["contract"])
        contract[7] = {**contract[7], "target_identity": "iat:free"}
        stale["contract"] = contract
        rejected(stale, "logical call mapping")

        population = self._zinterp_load_prepared_tailfold_fixture()
        population["call_sites"] = population["call_sites"][:-1]
        rejected(population, "call population")

        collision = self._zinterp_load_prepared_tailfold_fixture()
        call_sites = list(collision["call_sites"])
        call_sites[-1] = call_sites[-2]
        collision["call_sites"] = call_sites
        rejected(collision, "call population")

        late_extra = self._zinterp_load_prepared_tailfold_fixture()
        contract = [dict(row) for row in late_extra["contract"]]
        contract.append(dict(contract[-1]))
        for ordinal, row in enumerate(contract):
            row["ordinal"] = ordinal
        late_extra["contract"] = contract
        late_extra["call_sites"] = [
            *late_extra["call_sites"],
            call_contract_verify_module.normalize_address(0x4C5711),
        ]
        rejected(late_extra, "call population")

