            (0x4C2DDB, "83 c4 08", "add esp, 8"),
            (0x4C2DDE, "b8 01 00 00 00", "mov eax, 1"),
            (0x4C2DE3, "3b c3", "cmp eax, ebx"),
            (0x4C2DE5, "0f 84 ef 25 00 00", "je 0x4c53da"),
            (0x4C2DEB, "56", "push esi"),
            (0x4C2DEC, "68 78 54 4e 00", "push 0x4e5478"),
            (0x4C2DF1, "ff d7", "call edi"),
            (0x4C2DF3, "83 c4 08", "add esp, 8"),
