    def zsnd_directsound_duplicate_candidate_proofs(
        self,
        listing: str,
        *,
        source: str = "cod",
        caller_start: str = "0x4a3690",
        caller_end: str = "0x4a3850",
        local_control_flow_indices: frozenset[int] | None = None,
        local_control_flow_targets: dict[int, tuple[int, ...]] | None = None,
    ) -> dict[int, str]:
        rows = parse_assembly(listing, source=source)
        if local_control_flow_indices is None and source == "cod":
            jump_index = next(
                index
                for index, row in enumerate(rows)
                if "jmp 0x148" in row.text
            )
            nop_indices = [
                index for index, row in enumerate(rows) if row.text == "nop"
            ]
            local_control_flow_indices = frozenset({jump_index})
            local_control_flow_targets = {jump_index: (nop_indices[-1],)}
        return call_contract_verify_module._exact_targetless_vptr_call_proofs(
            rows,
            source=source,
            caller_start=caller_start,
            caller_end_exclusive=caller_end,
            indexes=self.zsnd_a3d_duplicate_candidate_indexes(),
            local_control_flow_indices=(
                local_control_flow_indices or frozenset()
            ),
            local_control_flow_targets=local_control_flow_targets,
        )

    def test_exact_callback_storage_chain_remains_dynamic(self) -> None:
        rows = parse_assembly(
            "\n".join((
                "0048affc 33 ed xor ebp, ebp",
                "0048b009 0f 87 b9 01 00 00 ja 0x48b1c8",
                "0048b1c8 83 c0 cf add eax, 0xffffffcf",
                "0048b1cb 3d dc 00 00 00 cmp eax, 0xdc",
                "0048b1d0 0f 87 4a fe ff ff ja 0x48b020",
                "0048b1d6 33 c9 xor ecx, ecx",
                "0048b1d8 8a 88 b4 b2 48 00 mov cl, byte [eax+0x48b2b4]",
                "0048b1de ff 24 8d 98 b2 48 00 jmp dword [ecx*4+0x48b298]",
                "0048b1f4 a1 fc aa 56 00 mov eax, dword [0x56aafc]",
                "0048b1f9 3b c5 cmp eax, ebp",
                "0048b1fb 74 05 je 0x48b202",
                "0048b1fd 83 c9 ff or ecx, 0xffffffff",
                "0048b200 ff d0 call eax",
                "0048b292 e9 a5 fd ff ff jmp 0x48b03c",
            )),
            source="bn",
        )
        self.assertEqual(
            {
                "0x48b200": ReviewedRegisterCallStorageBridge(
                    register="eax",
                    storage_identity="storage:recoil:data:0x56aafc",
                    identity_kind="callback",
                )
            },
            _reviewed_r3994_retail_register_storage_bridges(
                rows,
                caller_start="0x48afe0",
                caller_end_exclusive="0x48b3a0",
                indexes=self.indexes(),
            ),
        )
        drifted = list(rows)
        route_index = next(
            index
            for index, row in enumerate(drifted)
            if call_contract_verify_module._source_instruction_address(row)
            == "0x48b1d8"
        )
        drifted[route_index] = parse_assembly(
            "0048b1d8 8a 88 b5 b2 48 00 mov cl, byte [eax+0x48b2b5]",
            source="bn",
        )[0]
        with self.assertRaisesRegex(ValueError, "guard/argument"):
            _reviewed_r3994_retail_register_storage_bridges(
                drifted,
                caller_start="0x48afe0",
                caller_end_exclusive="0x48b3a0",
                indexes=self.indexes(),
            )

