        def replace_row(address: str, assembly: str) -> list[Instruction]:
            drifted = list(rows)
            index = next(
                index for index, row in enumerate(drifted)
                if call_contract_verify_module._source_instruction_address(row)
                == address
            )
            drifted[index] = parse_assembly(assembly, source="bn")[0]
            return drifted

