    def test_exact_dplay_ordinal_local_thunk_and_iat(self) -> None:
        rows = parse_assembly(
            "0048be14 6a 00 push 0\n"
            "0048be16 6a 00 push 0\n"
            "0048be18 8d 44 24 18 lea eax, [esp+0x18]\n"
            "0048be1c 6a 00 push 0\n"
            "0048be1e 50 push eax\n"
            "0048be1f 8b ce mov ecx, esi\n"
            "0048be21 6a 00 push 0\n"
            "0048be23 89 44 24 18 mov dword [esp+0x18], eax\n"
            "0048be2b 89 4c 24 1c mov dword [esp+0x1c], ecx\n"
            "0048be33 e8 b2 a5 03 00 call 0x4c63ea\n"
            "0048be38 85 c0 test eax, eax\n"
            "0048be69 c3 ret",
            source="bn",
        )
        bridge = SimpleNamespace(
            hexdump=lambda address, size: (
                "004c63ea: ff 25 54 c0 4c 00"
                if address == "0x4c63ea"
                else "004cc054: 0c 8c 7c 00"
            )
        )
        indexes = self.indexes()
        provider_identity = "provider:recoil:function:0x4c63ea"
        indexes = replace(
            indexes,
            by_address={"0x4c63ea": provider_identity},
            provider_ids=frozenset({provider_identity}),
            storage_by_address={
                **indexes.storage_by_address,
                "0x4cc054": "iat:ordinal:10:DPLAYX.dll:4",
            },
            reviewed_direct_import_thunk_by_call_site={
                "0x48be33": ("0x4c63ea", provider_identity)
            },
        )
        ordinal_package = ProviderOrdinalImportThunk(
            provider_identity=provider_identity,
            thunk_address="0x4c63ea",
            retail_name="Ordinal_DPLAYX_4",
            callable_symbol="_DirectPlayCreate@12",
            iat_object_symbol="__imp__DirectPlayCreate",
            iat_identity="iat:ordinal:10:DPLAYX.dll:4",
            import_dll="DPLAYX.dll",
            import_ordinal=4,
        )
        resolved = _reviewed_r3994_dplay_ordinal_thunk_indexes(
            rows,
            caller_start="0x48be10",
            caller_end_exclusive="0x48be70",
            indexes=indexes,
            bridge=bridge,
        )
        governed_pre_adapter_indexes = replace(
            indexes,
            storage_by_name={
                **indexes.storage_by_name,
                "__imp__DirectPlayCreate": (
                    "iat:ordinal:10:DPLAYX.dll:4"
                ),
            },
            reviewed_direct_import_thunk_by_call_site={},
        )
        governed_pre_adapter_indexes = (
            call_contract_verify_module._retail_direct_import_thunk_indexes(
                rows,
                indexes=governed_pre_adapter_indexes,
                thunks=(ordinal_package,),
            )
        )
        self.assertEqual(
            ("0x4c63ea", provider_identity),
            governed_pre_adapter_indexes
            .reviewed_direct_import_thunk_by_call_site["0x48be33"],
        )
        package_only_adapters = (
            call_contract_verify_module
            ._compose_reviewed_retail_provenance_adapters(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=replace(
                    indexes,
                    reviewed_direct_import_thunk_by_call_site={},
                ),
                bridge=bridge,
                ordinal_provider_thunks=(ordinal_package,),
            )
        )
        self.assertEqual(
            ("0x4c63ea", provider_identity),
            package_only_adapters.indexes
            .reviewed_direct_import_thunk_by_call_site["0x48be33"],
        )
        empty_ordinal_population_adapters = (
            call_contract_verify_module
            ._compose_reviewed_retail_provenance_adapters(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=replace(
                    indexes,
                    reviewed_direct_import_thunk_by_call_site={},
                ),
                bridge=bridge,
                ordinal_provider_thunks=(),
            )
        )
        self.assertEqual(
            ("0x4c63ea", provider_identity),
            empty_ordinal_population_adapters.indexes
            .reviewed_direct_import_thunk_by_call_site["0x48be33"],
        )
        with self.assertRaisesRegex(ValueError, "provider proof conflicts"):
            call_contract_verify_module._compose_reviewed_retail_provenance_adapters(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=replace(
                    indexes,
                    reviewed_direct_import_thunk_by_call_site={},
                ),
                bridge=bridge,
                ordinal_provider_thunks=(
                    replace(
                        ordinal_package,
                        provider_identity="provider:conflicting-dplay-thunk",
                    ),
                ),
            )
        with self.assertRaisesRegex(ValueError, "duplicated or ambiguous"):
            call_contract_verify_module._compose_reviewed_retail_provenance_adapters(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=replace(
                    indexes,
                    reviewed_direct_import_thunk_by_call_site={},
                ),
                bridge=bridge,
                ordinal_provider_thunks=(ordinal_package, ordinal_package),
            )
        with self.assertRaisesRegex(ValueError, "provider proof conflicts"):
            call_contract_verify_module._compose_reviewed_retail_provenance_adapters(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=replace(
                    indexes,
                    by_address={},
                    reviewed_direct_import_thunk_by_call_site={},
                ),
                bridge=bridge,
                ordinal_provider_thunks=(),
            )
        governed_adapters = (
            call_contract_verify_module
            ._compose_reviewed_retail_provenance_adapters(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=governed_pre_adapter_indexes,
                bridge=bridge,
            )
        )
        self.assertEqual(
            ("0x4c63ea", provider_identity),
            governed_adapters.indexes
            .reviewed_direct_import_thunk_by_call_site["0x48be33"],
        )
        self.assertEqual(
            ("0x4c63ea", provider_identity),
            resolved.reviewed_direct_import_thunk_by_call_site["0x48be33"],
        )
        unpublished_indexes = replace(
            indexes,
            storage_by_address={
                address: identity
                for address, identity in indexes.storage_by_address.items()
                if address != "0x4cc054"
            },
        )
        published = _reviewed_r3994_dplay_ordinal_thunk_indexes(
            rows,
            caller_start="0x48be10",
            caller_end_exclusive="0x48be70",
            indexes=unpublished_indexes,
            bridge=bridge,
        )
        self.assertEqual(
            "iat:ordinal:10:DPLAYX.dll:4",
            published.storage_by_address["0x4cc054"],
        )
        colliding_unpublished = replace(
            unpublished_indexes,
            storage_by_address={
                **unpublished_indexes.storage_by_address,
                "0x4cc050": "iat:ordinal:10:DPLAYX.dll:4",
            },
        )
        with self.assertRaisesRegex(ValueError, "IAT identity collides"):
            _reviewed_r3994_dplay_ordinal_thunk_indexes(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=colliding_unpublished,
                bridge=bridge,
            )
        adapters = call_contract_verify_module._compose_reviewed_retail_provenance_adapters(
            rows,
            caller_start="0x48be10",
            caller_end_exclusive="0x48be70",
            indexes=indexes,
            bridge=bridge,
        )
        self.assertEqual(
            provider_identity,
            extract_invocation_contract(
                rows,
                source="bn",
                caller_identity="symbol:recoil:function:0x48be10",
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=adapters.indexes,
            )[0]["target_identity"],
        )
        friendly_name = "DPLAYX_Ordinal4_ImportThunk"
        friendly_rows = list(rows)
        friendly_call_index = next(
            index
            for index, row in enumerate(friendly_rows)
            if call_contract_verify_module._source_instruction_address(row)
            == "0x48be33"
        )
        friendly_rows[friendly_call_index] = parse_assembly(
            "0048be33 e8 b2 a5 03 00 call " + friendly_name,
            source="bn",
        )[0]
        friendly_symbol = SimpleNamespace(
            address="0x4c63ea",
            name=friendly_name,
            raw_name=friendly_name,
            full_name=friendly_name,
            kind="function",
        )
        caller_local_names = call_contract_verify_module._reviewed_r3994_dplay_ordinal_retail_bridge_names(
            friendly_rows,
            caller_start="0x48be10",
            indexes=adapters.indexes,
            bridge_names={},
        )
        self.assertEqual(
            ["0x4c63ea"],
            [
                row.address
                for row in caller_local_names[friendly_name]
            ],
        )
        self.assertEqual(
            provider_identity,
            extract_invocation_contract(
                friendly_rows,
                source="bn",
                caller_identity="symbol:recoil:function:0x48be10",
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=adapters.indexes,
                bridge_names=caller_local_names,
            )[0]["target_identity"],
        )
        with self.assertRaisesRegex(ValueError, "collides"):
            call_contract_verify_module._reviewed_r3994_dplay_ordinal_retail_bridge_names(
                friendly_rows,
                caller_start="0x48be10",
                indexes=adapters.indexes,
                bridge_names={
                    friendly_name: [
                        SimpleNamespace(address="0x4c63f0"),
                    ],
                },
            )
        with self.assertRaisesRegex(ValueError, "caller-local provider proof"):
            call_contract_verify_module._reviewed_r3994_dplay_ordinal_retail_bridge_names(
                friendly_rows,
                caller_start="0x48be10",
                indexes=replace(
                    adapters.indexes,
                    reviewed_direct_import_thunk_by_call_site={},
                ),
                bridge_names={},
            )
        self.assertEqual(
            provider_identity,
            extract_invocation_contract(
                friendly_rows,
                source="bn",
                caller_identity="symbol:recoil:function:0x48be10",
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=adapters.indexes,
                bridge_names={friendly_name: [friendly_symbol]},
            )[0]["target_identity"],
        )
        with self.assertRaisesRegex(
            ValueError,
            "does not join friendly target",
        ):
            extract_invocation_contract(
                friendly_rows,
                source="bn",
                caller_identity="symbol:recoil:function:0x48be10",
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=adapters.indexes,
                bridge_names={
                    friendly_name: [
                        friendly_symbol,
                        SimpleNamespace(address="0x4c63f0"),
                    ]
                },
            )
        oversized_symbol = {
            "address": "0x4c63ea",
            "end_exclusive": "0x4c7498",
            "size": 0x10AE,
            "binary": "recoil",
            "kind": "function",
            "ownership_state": "unresolved",
            "disposition": "unresolved",
            "pipeline_class": "non-authored",
            "authored_order_role": "non-authored",
            "extent_state": "known",
            "output_section_id": "recoil:section:.text",
            "navigation_name": "DPLAYX_Ordinal4_ImportThunk",
        }
        local_result = (
            call_contract_verify_module._retail_local_named_import_thunk_indexes(
                rows,
                document=SimpleNamespace(
                    collection=lambda name: (
                        {"recoil:function:0x4c63ea": oversized_symbol}
                        if name == "symbols"
                        else {}
                    )
                ),
                indexes=indexes,
                bridge=bridge,
                caller_start="0x48be10",
                retail_import_targets=(
                    SimpleNamespace(
                        address="0x4cc054",
                        dll="DPLAYX.dll",
                        import_name="#4",
                        import_ordinal=4,
                    ),
                ),
                precomposed_call_sites=frozenset(),
            )
        )
        self.assertEqual(
            ("0x4c63ea", provider_identity),
            local_result.reviewed_direct_import_thunk_by_call_site["0x48be33"],
        )
        with self.assertRaisesRegex(ValueError, "six-byte thunk lineage"):
            call_contract_verify_module._retail_local_named_import_thunk_indexes(
                rows,
                document=SimpleNamespace(
                    collection=lambda name: (
                        {"recoil:function:0x4c63ea": oversized_symbol}
                        if name == "symbols"
                        else {}
                    )
                ),
                indexes=replace(
                    indexes,
                    reviewed_direct_import_thunk_by_call_site={
                        "0x48be33": (
                            "0x4c63ea", "provider:conflicting-dplay-thunk"
                        )
                    },
                ),
                bridge=bridge,
                caller_start="0x48be10",
                retail_import_targets=(
                    SimpleNamespace(
                        address="0x4cc054",
                        dll="DPLAYX.dll",
                        import_name="#4",
                        import_ordinal=4,
                    ),
                ),
            )
        with self.assertRaisesRegex(ValueError, "FF25 thunk"):
            _reviewed_r3994_dplay_ordinal_thunk_indexes(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=indexes,
                bridge=SimpleNamespace(
                    hexdump=lambda address, size: (
                        "004c63ea ff 25 58 c0 4c 00"
                    )
                ),
            )
        iat_overwrite = replace(
            indexes,
            reviewed_direct_import_thunk_by_call_site={
                "0x48be33": (
                    "0x4c63ea", "iat:ordinal:10:DPLAYX.dll:4"
                )
            },
        )
        with self.assertRaisesRegex(ValueError, "canonical provider identity"):
            _reviewed_r3994_dplay_ordinal_thunk_indexes(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=iat_overwrite,
                bridge=bridge,
            )
        original_interval = call_contract_verify_module._immutable_retail_interval
        with (
            patch.object(
                call_contract_verify_module,
                "_immutable_retail_interval",
                side_effect=lambda reference, *, start, end_exclusive: (
                    b"\x90" * 5 + b"\xcc"
                    if start == 0x48BE6A
                    else original_interval(
                        reference,
                        start=start,
                        end_exclusive=end_exclusive,
                    )
                ),
            ),
            self.assertRaisesRegex(ValueError, "caller padding"),
        ):
            _reviewed_r3994_dplay_ordinal_thunk_indexes(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=indexes,
                bridge=bridge,
            )
        with self.assertRaisesRegex(ValueError, "five-argument"):
            _reviewed_r3994_dplay_ordinal_thunk_indexes(
                rows[1:],
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=indexes,
                bridge=bridge,
            )
        stale_iat_identity = replace(
            indexes,
            storage_by_address={
                **indexes.storage_by_address,
                "0x4cc054": "iat:Ordinal_DPLAYX_4",
            },
        )
        with self.assertRaisesRegex(ValueError, "IAT identity conflicts"):
            _reviewed_r3994_dplay_ordinal_thunk_indexes(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=stale_iat_identity,
                bridge=bridge,
            )
        drifted_cell_bridge = SimpleNamespace(
            hexdump=lambda address, size: (
                "004c63ea ff 25 54 c0 4c 00"
                if address == "0x4c63ea"
                else "004cc054 0d 8c 7c 00"
            )
        )
        with self.assertRaisesRegex(ValueError, "IAT cell"):
            _reviewed_r3994_dplay_ordinal_thunk_indexes(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be70",
                indexes=indexes,
                bridge=drifted_cell_bridge,
            )
        with self.assertRaisesRegex(ValueError, "caller extent"):
            _reviewed_r3994_dplay_ordinal_thunk_indexes(
                rows,
                caller_start="0x48be10",
                caller_end_exclusive="0x48be6a",
                indexes=indexes,
                bridge=bridge,
            )

    def test_exact_static_vptr_table_cell_and_lineage(self) -> None:
        indexes = IdentityIndexes(
            by_address={
                "0x4b3dd0": "symbol:recoil:function:0x4b3dd0",
                "0x404d20": "symbol:recoil:function:0x404d20",
            },
            by_candidate_name={},
            provider_ids=frozenset(),
            storage_by_address={"0x4d3428": "storage:recoil:data:0x4d3428"},
            storage_by_name={},
        )
        rows = parse_assembly(
            "\n".join((
                "004b82a5 8b 11 mov edx, dword [ecx]",
                "004b82a7 90 nop",
                "004b82a8 ff 52 0c call dword [edx+0xc]",
                "004b82b4 8b 11 mov edx, dword [ecx]",
                "004b82b6 ff 52 60 call dword [edx+0x60]",
            )),
            source="bn",
        )
        bridge = SimpleNamespace(
            assembly=lambda address: (
                "004b3d11 c7 06 28 34 4d 00 mov dword [esi], 0x4d3428"
            ),
            hexdump=lambda address, size: (
                "004d3434 d0 3d 4b 00"
                if address == "0x4d3434"
                else "004d3488 20 4d 40 00"
            ),
        )
        result = _reviewed_r3994_static_vptr_dispatch_bridges(
            rows,
            caller_start="0x4b8200",
            caller_end_exclusive="0x4b82e0",
            indexes=indexes,
            bridge=bridge,
        )
        self.assertEqual(
            ReviewedLoopVptrStorageBridge(
                register="edx",
                storage_identity="storage:recoil:data:0x4d3428",
                slot_displacement=0x0C,
                assembly_source="bn",
                target_identity="symbol:recoil:function:0x4b3dd0",
            ),
            result["0x4b82a8"],
        )
        clobbered = parse_assembly(
            "\n".join((
                "004b82a5 8b 11 mov edx, dword [ecx]",
                "004b82a7 42 inc edx",
                "004b82a8 ff 52 0c call dword [edx+0xc]",
            )),
            source="bn",
        )
        with self.assertRaisesRegex(ValueError, "register lineage"):
            _reviewed_r3994_static_vptr_dispatch_bridges(
                clobbered,
                caller_start="0x4b8200",
                caller_end_exclusive="0x4b82e0",
                indexes=indexes,
                bridge=bridge,
            )

