    @staticmethod
    def zinterp_logf_candidate(
        listing: str | None = None,
        *,
        pad_to_extent: bool = False,
        undefined_external_functions: tuple[str, ...] = (),
        undefined_external_data: tuple[str, ...] = (),
    ) -> CandidateAssembly:
        module = call_contract_verify_module
        rows = parse_assembly(
            listing
            or "\n".join((
                "00000 8b 44 24 04 mov eax, dword [esp+4]",
                "00004 8b 40 70 mov eax, dword [eax+0x70]",
                "00007 85 c0 test eax, eax",
                "00009 74 0a je 0x15",
                "0000b 8b 4c 24 08 mov ecx, dword [esp+8]",
                "0000f 8d 54 24 0c lea edx, [esp+0xc]",
                "00013 ff e0 jmp eax",
                "00015 c3 ret",
            )),
            source="cod",
        )
        body = b"".join(
            bytes(int(item, 16) for item in row.bytes) for row in rows
        )
        physical_body = (
            body + b"\x90" * (0x20 - len(body))
            if pad_to_extent
            else body
        )
        return CandidateAssembly(
            instructions=tuple(rows),
            local_control_flow_indices=frozenset(),
            caller_definition=CandidateCallerDefinition(
                symbol=module._ZINTERP_LOGF_CANDIDATE_SYMBOL,
                data=physical_body,
                relocations=(),
                relocation_mask=(False,) * len(physical_body),
                undefined_external_functions=undefined_external_functions,
                undefined_external_data=undefined_external_data,
            ),
        )

    def zinterp_logf_candidate_indexes(self) -> IdentityIndexes:
        module = call_contract_verify_module
        base = self.indexes()
        return replace(
            base,
            by_address={
                **base.by_address,
                module._ZINTERP_LOGF_CALLER_START:
                module._ZINTERP_LOGF_CALLER_IDENTITY,
            },
            by_candidate_name={
                module._ZINTERP_LOGF_CANDIDATE_SYMBOL:
                module._ZINTERP_LOGF_CALLER_IDENTITY,
            },
        )

    def prove_zinterp_logf_candidate(
        self,
        candidate: CandidateAssembly | None = None,
        **changes: object,
    ) -> dict[str, ReviewedLoopVptrStorageBridge]:
        module = call_contract_verify_module
        arguments = {
            "caller_identity": module._ZINTERP_LOGF_CALLER_IDENTITY,
            "caller_start": module._ZINTERP_LOGF_CALLER_START,
            "caller_end_exclusive": module._ZINTERP_LOGF_CALLER_END_EXCLUSIVE,
            "indexes": self.zinterp_logf_candidate_indexes(),
        }
        arguments.update(changes)
        return module._zinterp_logf_candidate_ctx_callback_bridge(
            candidate or self.zinterp_logf_candidate(),
            **arguments,
        )

