            "0000b 8b 54 24 08 mov edx, dword [esp+8]",
            "0000f 8d 4c 24 0c lea ecx, [esp+0xc]",
            "00013 51 push ecx",
            "00014 52 push edx",
            "00015 ff d0 call eax",
