    def test_zinterp_logf_candidate_accepts_exact_live_tu_container(self) -> None:
        module = call_contract_verify_module
        listing = "\n".join((
            "00000 8b 44 24 04 mov eax, dword _ctx$[esp-4]",
            "00004 8b 40 70 mov eax, dword [eax+0x70]",
            "00007 85 c0 test eax, eax",
            "00009 74 0f je 0x1a",
            "0000b 8b 54 24 08 mov edx, dword _fmt$[esp-4]",
            "0000f 8d 4c 24 0c lea ecx, [esp+0xc]",
            "00013 51 push ecx",
            "00014 52 push edx",
            "00015 ff d0 call eax",
            "00017 83 c4 08 add esp, 8",
            "0001a c3 ret",
        ))
        candidate = self.zinterp_logf_candidate(
            listing,
            pad_to_extent=True,
            undefined_external_functions=("?Neighbor@@YAXXZ", "__imp__printf"),
            undefined_external_data=("?g_Neighbor@@3HA",),
        )
        bridges = self.prove_zinterp_logf_candidate(candidate)
        self.assertEqual(["0x15"], list(bridges))
        contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=module._ZINTERP_LOGF_CALLER_IDENTITY,
            caller_start=module._ZINTERP_LOGF_CALLER_START,
            caller_end_exclusive=module._ZINTERP_LOGF_CALLER_END_EXCLUSIVE,
            indexes=self.zinterp_logf_candidate_indexes(),
            reviewed_loop_vptr_storage_bridges=bridges,
        )
        self.assertEqual("call", contract[0]["form"])
        self.assertEqual(8, contract[0]["cleanup_bytes"])
        definition = candidate.caller_definition
        self.assertIsNotNone(definition)
        self.assertEqual(0x20, len(definition.data))
        self.assertEqual(b"\x90" * 5, definition.data[-5:])

        wrong_padding = replace(
            definition,
            data=definition.data[:-1] + b"\xcc",
        )
        with self.assertRaisesRegex(ValueError, "body_shape"):
            self.prove_zinterp_logf_candidate(
                replace(candidate, caller_definition=wrong_padding)
            )

        for label, old, new in (
            ("ctx-symbol", "_ctx$[esp-4]", "_other$[esp-4]"),
            ("ctx-rendered-slot", "_ctx$[esp-4]", "_ctx$[esp-8]"),
            ("fmt-symbol", "_fmt$[esp-4]", "_other$[esp-4]"),
            ("fmt-rendered-slot", "_fmt$[esp-4]", "_fmt$[esp-8]"),
        ):
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "lineage drifted"
            ):
                self.prove_zinterp_logf_candidate(
                    self.zinterp_logf_candidate(
                        listing.replace(old, new),
                        pad_to_extent=True,
                    )
                )

    def test_zinterp_logf_candidate_ctx_callback_fails_closed_on_drift(self) -> None:
        exact = "\n".join((
            "00000 8b 44 24 04 mov eax, dword [esp+4]",
            "00004 8b 40 70 mov eax, dword [eax+0x70]",
            "00007 85 c0 test eax, eax",
            "00009 74 0a je 0x15",
            "0000b 8b 4c 24 08 mov ecx, dword [esp+8]",
            "0000f 8d 54 24 0c lea edx, [esp+0xc]",
            "00013 ff e0 jmp eax",
            "00015 c3 ret",
        ))
        cases = {
            "field": exact.replace("8b 40 70", "8b 40 74").replace(
                "[eax+0x70]", "[eax+0x74]"
            ),
            "root": exact.replace("8b 44 24 04", "8b 44 24 08").replace(
                "[esp+4]", "[esp+8]", 1
            ),
            "register": exact.replace("ff e0 jmp eax", "ff e1 jmp ecx"),
            "clobber": exact.replace(
                "8d 54 24 0c lea edx, [esp+0xc]",
                "8b 44 24 0c mov eax, dword [esp+0xc]",
            ),
            "opcode": exact.replace("ff e0 jmp eax", "ff d0 call eax"),
        }
        for label, listing in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "exact authored caller|lineage drifted"
            ):
                self.prove_zinterp_logf_candidate(
                    self.zinterp_logf_candidate(listing)
                )

        with self.assertRaisesRegex(ValueError, "exact authored caller"):
            self.prove_zinterp_logf_candidate(
                caller_end_exclusive="0x4c1b4f"
            )
        candidate = self.zinterp_logf_candidate()
        definition = candidate.caller_definition
        self.assertIsNotNone(definition)
        with self.assertRaisesRegex(ValueError, "empty relocation set"):
            self.prove_zinterp_logf_candidate(
                replace(
                    candidate,
                    caller_definition=replace(
                        definition,
                        relocations=(CoffRelocation(0, 1, 0x06, "?wrong"),),
                    ),
                )
            )

