    def test_zinterp_report_errorf_candidate_callback_is_exact_and_targetless(
        self,
    ) -> None:
        module = call_contract_verify_module
        candidate = self.zinterp_report_errorf_candidate()
        bridges = self.prove_zinterp_report_errorf_candidate(candidate)
        self.assertEqual(
            {
                "0x1c": ReviewedLoopVptrStorageBridge(
                    register="eax",
                    storage_identity=module._ZINTERP_CONTEXT_CALLBACK_IDENTITY,
                    slot_displacement=0,
                    assembly_source="cod",
                )
            },
            bridges,
        )
        contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=module._ZINTERP_REPORT_ERRORF_CALLER_IDENTITY,
            caller_start=module._ZINTERP_REPORT_ERRORF_CALLER_START,
            caller_end_exclusive=(
                module._ZINTERP_REPORT_ERRORF_CALLER_END_EXCLUSIVE
            ),
            indexes=self.zinterp_report_errorf_candidate_indexes(),
            reviewed_loop_vptr_storage_bridges=bridges,
        )
        self.assertEqual("callback", contract[0]["identity_kind"])
        self.assertEqual("", contract[0]["target_identity"])
        self.assertEqual(
            module._ZINTERP_CONTEXT_CALLBACK_IDENTITY,
            contract[0]["storage_identity"],
        )
        self.assertEqual(8, contract[0]["cleanup_bytes"])

    def test_zinterp_report_errorf_candidate_callback_fails_closed_on_drift(
        self,
    ) -> None:
        exact = "\n".join((
            "00000 8b 44 24 04 mov eax, dword _ctx$[esp-4]",
            "00004 c7 40 10 01 00 00 00 mov dword [eax+0x10], 1",
            "0000b 8b 40 70 mov eax, dword [eax+0x70]",
            "0000e 85 c0 test eax, eax",
            "00010 74 0f je 0x21",
            "00012 8b 54 24 08 mov edx, dword _fmt$[esp-4]",
            "00016 8d 4c 24 0c lea ecx, [esp+0xc]",
            "0001a 51 push ecx",
            "0001b 52 push edx",
            "0001c ff d0 call eax",
            "0001e 83 c4 08 add esp, 8",
            "00021 c3 ret",
        ))
        for label, old, new in (
            ("root", "8b 44 24 04", "8b 44 24 08"),
            ("flag", "c7 40 10", "c7 40 14"),
            ("field", "8b 40 70", "8b 40 74"),
            ("branch", "74 0f", "74 0e"),
            ("format", "8b 54 24 08", "8b 54 24 0c"),
            ("argument", "8d 4c 24 0c", "8d 4c 24 10"),
            ("register", "ff d0 call eax", "ff d1 call ecx"),
            ("cleanup", "83 c4 08", "83 c4 04"),
        ):
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "exact authored caller|lineage drifted"
            ):
                self.prove_zinterp_report_errorf_candidate(
                    self.zinterp_report_errorf_candidate(
                        exact.replace(old, new)
                    )
                )

        candidate = self.zinterp_report_errorf_candidate()
        definition = candidate.caller_definition
        self.assertIsNotNone(definition)
        with self.assertRaisesRegex(ValueError, "exact authored caller"):
            self.prove_zinterp_report_errorf_candidate(
                replace(
                    candidate,
                    caller_definition=replace(
                        definition,
                        data=definition.data[:-1] + b"\xcc",
                    ),
                )
            )
        with self.assertRaisesRegex(ValueError, "empty relocation set"):
            self.prove_zinterp_report_errorf_candidate(
                replace(
                    candidate,
                    caller_definition=replace(
                        definition,
                        relocations=(CoffRelocation(0, 1, 0x06, "?wrong"),),
                    ),
                )
            )
        with self.assertRaisesRegex(ValueError, "exact authored caller"):
            self.prove_zinterp_report_errorf_candidate(
                caller_end_exclusive="0x4c554f"
            )
        conflicting = ReviewedLoopVptrStorageBridge(
            register="eax",
            storage_identity="dynamic:wrong-callback",
            slot_displacement=0,
            assembly_source="cod",
        )
        with self.assertRaisesRegex(ValueError, "conflicting existing provenance"):
            self.prove_zinterp_report_errorf_candidate(
                existing_bridges={"0x1c": conflicting}
            )

    def test_exact_later_directsound_duplicate_release_is_distinct(self) -> None:
        rows = parse_assembly(
            "\n".join((
                "004a3742 8b 86 84 00 00 00 mov eax, dword [esi+0x84]",
                "004a3748 8b 3c 98 mov edi, dword [eax+ebx*4]",
                "004a374b 8b 47 08 mov eax, dword [edi+8]",
                "004a3751 85 c0 test eax, eax",
                "004a3753 74 0c je 0x4a3761",
                "004a3755 8b 08 mov ecx, dword [eax]",
                "004a3757 50 push eax",
                "004a3758 ff 51 08 call dword [ecx+8]",
                "004a375b c7 07 00 00 00 00 mov dword [edi], 0",
                "004a37a4 8b 08 mov ecx, dword [eax]",
                "004a37a6 50 push eax",
                "004a37a7 ff 51 18 call dword [ecx+0x18]",
                "004a37b5 8b 46 4c mov eax, dword [esi+0x4c]",
                "004a37b8 50 push eax",
                "004a37b9 8b 10 mov edx, dword [eax]",
                "004a37bb ff 52 08 call dword [edx+8]",
                "004a37c8 8b 86 84 00 00 00 mov eax, dword [esi+0x84]",
                "004a37ce 8b 3c 98 mov edi, dword [eax+ebx*4]",
                "004a37d1 8b 47 08 mov eax, dword [edi+8]",
                "004a37d7 85 c0 test eax, eax",
                "004a37d9 74 0c je 0x4a37e7",
                "004a37db 8b 08 mov ecx, dword [eax]",
                "004a37dd 50 push eax",
                "004a37de ff 51 08 call dword [ecx+8]",
                "004a37e1 c7 07 00 00 00 00 mov dword [edi], 0",
                "004a3826 8b 08 mov ecx, dword [eax]",
                "004a3828 50 push eax",
                "004a3829 ff 51 08 call dword [ecx+8]",
                "004a3840 c3 ret",
            )),
            source="bn",
        )
        bridges = _reviewed_r3994_dynamic_vptr_dispatch_bridges(
            rows,
            caller_start="0x4a3690",
            caller_end_exclusive="0x4a3850",
        )
        self.assertEqual(5, len(bridges))
        self.assertEqual(
            "dynamic:zSndSample-DirectSound-duplicate-backendBuffer-vptr",
            bridges["0x4a37de"].storage_identity,
        )
        drifted = list(rows)
        drifted[23] = parse_assembly(
            "004a37de ff 51 0c call dword [ecx+0xc]", source="bn"
        )[0]
        with self.assertRaisesRegex(ValueError, "dual-backend|call shape"):
            _reviewed_r3994_dynamic_vptr_dispatch_bridges(
                drifted,
                caller_start="0x4a3690",
                caller_end_exclusive="0x4a3850",
            )

    def test_exact_zui_static_table_inbound_ff15_guard(self) -> None:
        bridge = SimpleNamespace(
            hexdump=lambda address, size: (
                "004cc888 70 40 40 00 50 98 4b 00 90 3d 40 00"
            ),
            get_json=lambda endpoint, **kwargs: {
                "code_references": [{"source_address": "0x403f00"}],
                "data_references": [],
                "total": 1,
                "truncated": False,
            },
            assembly=lambda address: (
                "00403f00 ff 15 8c c8 4c 00 call dword [0x4cc88c]"
            ),
            function_at=lambda address: [{"name": "InboundOwner"}],
            function_info=lambda name: {"start": "0x403ed0"},
        )
        indexes = IdentityIndexes(
            by_address={"0x4b9850": "symbol:recoil:function:0x4b9850"},
            by_candidate_name={}, provider_ids=frozenset(),
            storage_by_address={}, storage_by_name={},
        )
        self.assertEqual(
            {},
            _reviewed_r3994_static_table_inbound_target_bridges(
                (), caller_start="0x4b9850", caller_end_exclusive="0x4b98d0",
                indexes=indexes, bridge=bridge,
            ),
        )
        with self.assertRaisesRegex(ValueError, "FF15"):
            _reviewed_r3994_static_table_inbound_target_bridges(
                (), caller_start="0x4b9850", caller_end_exclusive="0x4b98d0",
                indexes=indexes,
                bridge=SimpleNamespace(
                    **{
                        **vars(bridge),
                        "assembly": lambda address: (
                            "00403f00 e8 4b 59 0b 00 call 0x4b9850"
                        ),
                    }
                ),
            )

    def test_text_label_inbound_ignores_only_exact_nop_padding_xref(self) -> None:
        def make_bridge(padding: str) -> SimpleNamespace:
            return SimpleNamespace(
                get_json=lambda endpoint, **kwargs: {
                    "code_references": [
                        {"source_address": "0x4ba772"},
                        {"source_address": "0x4bcb4f"},
                    ],
                    "data_references": [],
                    "total": 2,
                    "truncated": False,
                },
                hexdump=lambda address, size: padding,
                function_at=lambda address: [{"name": "InboundOwner"}],
                function_info=lambda name: {"start": "0x4ba740"},
                assembly=lambda address: (
                    "004ba772 e8 d9 23 00 00 call 0x4bcb50"
                ),
            )

        transfers = (
            call_contract_verify_module._complete_bn_inbound_direct_transfers(
                make_bridge("004bcb4f 90"),
                target_address="0x4bcb50",
            )
        )
        self.assertIsNotNone(transfers)
        self.assertEqual(["0x4ba772"], [row[0] for row in transfers or ()])
        with self.assertRaisesRegex(ValueError, "padding xref byte"):
            call_contract_verify_module._complete_bn_inbound_direct_transfers(
                make_bridge("004bcb4f cc"),
                target_address="0x4bcb50",
            )


