    def test_zwep_process_runtime_stack_probe_rejects_nearby_malformed_and_collision_drift(
        self,
    ) -> None:
        fixture = self.zwep_stack_probe_fixture()
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=parse_assembly(
                "00000 b8 6d 1f 00 00 mov eax, 0x1f6d\n"
                "00005 e8 00 00 00 00 call __chkstk",
                source="cod",
            ),
        )
        with self.assertRaisesRegex(ValueError, "EAX setup"):
            self.prove(fixture, **fixture["zwep_arguments"])

        fixture = self.zwep_stack_probe_fixture()
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=(
                *fixture["candidate"].instructions,
                parse_assembly(
                    "00020 e8 00 00 00 00 call __chkstk",
                    source="cod",
                )[0],
            ),
        )
        with self.assertRaisesRegex(ValueError, "unique undefined helper"):
            self.prove(fixture, **fixture["zwep_arguments"])

        fixture = self.zwep_stack_probe_fixture()
        definition = fixture["candidate"].caller_definition
        fixture["candidate"] = replace(
            fixture["candidate"],
            caller_definition=replace(
                definition,
                relocations=(replace(
                    definition.relocations[0], symbol_index=293
                ),),
            ),
        )
        with self.assertRaisesRegex(ValueError, "REL32 relocation"):
            self.prove(fixture, **fixture["zwep_arguments"])

        fixture = self.zwep_stack_probe_fixture()
        fixture["bridge_names"]["__chkstk"] = deepcopy(
            fixture["bridge_names"]["__alloca_probe"]
        )
        with self.assertRaisesRegex(ValueError, "collision drift"):
            self.prove(fixture, **fixture["zwep_arguments"])

