    def test_zwep_process_runtime_stack_probe_accepts_governed_r4562_artifact(
        self,
    ) -> None:
        module = call_contract_verify_module
        artifact_root = (
            REPO_ROOT
            / "build"
            / "live-validation"
            / "worker-call-contract-convergence"
            / "0001-r4562"
            / "call-contract-zwep_init_4ae380_4b2960_authored_order"
        )
        cod_path = artifact_root / "zwep_init.cod"
        obj_path = artifact_root / "zwep_init.obj"
        if not cod_path.is_file() or not obj_path.is_file():
            self.skipTest("governed r4562 zWep COD/OBJ artifact is unavailable")

        fixture = self.zwep_stack_probe_fixture()
        symbol = str(
            module.MSVC_CHKSTK_CALLER_SPECS[
                fixture["zwep_arguments"]["caller_identity"]
            ]["symbol"]
        )
        coff_object = module.CoffObject.from_path(obj_path)
        caller_bytes = coff_object.function_bytes(symbol)
        parsed = module._extract_cod_proc_with_local_switches(cod_path, symbol)
        (
            undefined_external_functions,
            defined_external_functions,
            undefined_external_data,
            defined_external_data,
        ) = module._candidate_external_symbol_inventory(coff_object)
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=parsed.instructions,
            local_control_flow_indices=parsed.local_control_flow_indices,
            local_control_flow_targets=parsed.local_control_flow_targets,
            caller_definition=CandidateCallerDefinition(
                symbol=symbol,
                data=caller_bytes.data,
                relocations=caller_bytes.relocations,
                relocation_mask=caller_bytes.relocation_mask,
                undefined_external_functions=undefined_external_functions,
                defined_external_functions=defined_external_functions,
                undefined_external_data=undefined_external_data,
                defined_external_data=defined_external_data,
                section_index=caller_bytes.section_index,
                section_start=caller_bytes.start,
                section_end=caller_bytes.end,
            ),
        )
        self.assertEqual(
            {"__chkstk": self.target_identity},
            self.prove(fixture, **fixture["zwep_arguments"]),
        )
        definition = fixture["candidate"].caller_definition
        self.assertEqual(0x14C0, len(definition.data))
        self.assertEqual(67, definition.section_index)
        self.assertEqual(
            (6, 294, module.IMAGE_REL_I386_REL32, "__chkstk"),
            (
                definition.relocations[0].offset,
                definition.relocations[0].symbol_index,
                definition.relocations[0].type,
                definition.relocations[0].symbol_name,
            ),
        )

