    def test_additional_wol_chkstk_callers_reject_all_exact_fact_drift(
        self,
    ) -> None:
        caller_identity = "symbol:recoil:function:0x43ec00"

        fixture = self.wol_submit_status_fixture(caller_identity)
        self.assertEqual(
            {},
            self.prove(
                fixture,
                caller_identity="symbol:recoil:function:0x43ec01",
                caller_start="0x43ec01",
                caller_end_exclusive="0x43ed10",
            ),
        )

        fixture = self.wol_submit_status_fixture(caller_identity)
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=parse_assembly(
                "00000 b8 09 10 00 00 mov eax, 4105\n"
                "00005 e8 00 00 00 00 call __chkstk",
                source="cod",
            ),
        )
        with self.assertRaisesRegex(ValueError, "EAX setup"):
            self.prove(fixture, **fixture["wol_arguments"])

        fixture = self.wol_submit_status_fixture(caller_identity)
        fixture["retail"] = parse_assembly(
            "0043ec00 b8 08 10 00 00 mov eax, 0x1008\n"
            "0043ec05 e8 f7 74 08 00 call __alloca_probe",
            source="bn",
        )
        with self.assertRaisesRegex(ValueError, "retail caller"):
            self.prove(fixture, **fixture["wol_arguments"])

        fixture = self.wol_submit_status_fixture(caller_identity)
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=parse_assembly(
                "00000 b8 08 10 00 00 mov eax, 4104\n"
                "00006 e8 00 00 00 00 call __chkstk",
                source="cod",
            ),
        )
        with self.assertRaisesRegex(ValueError, "offset-five"):
            self.prove(fixture, **fixture["wol_arguments"])

        fixture = self.wol_submit_status_fixture(caller_identity)
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=parse_assembly(
                "00000 b8 08 10 00 00 mov eax, 4104\n"
                "00005 e9 00 00 00 00 call __chkstk",
                source="cod",
            ),
        )
        with self.assertRaisesRegex(ValueError, "offset-five"):
            self.prove(fixture, **fixture["wol_arguments"])

        for label, replacement in (
            (
                "symbol",
                lambda definition: replace(definition, symbol="?Wrong@@YAXXZ"),
            ),
            (
                "relocation-type",
                lambda definition: replace(
                    definition,
                    relocations=(CoffRelocation(6, 1, 0x06, "__chkstk"),),
                ),
            ),
            (
                "relocation-addend",
                lambda definition: replace(
                    definition,
                    data=definition.data[:6] + b"\x01" + definition.data[7:],
                ),
            ),
            (
                "relocation-mask",
                lambda definition: replace(
                    definition,
                    relocation_mask=(
                        definition.relocation_mask[:6]
                        + (False,)
                        + definition.relocation_mask[7:]
                    ),
                ),
            ),
            (
                "undefined-population",
                lambda definition: replace(
                    definition,
                    undefined_external_functions=("__chkstk", "__chkstk"),
                ),
            ),
        ):
            with self.subTest(label=label):
                fixture = self.wol_submit_status_fixture(caller_identity)
                definition = fixture["candidate"].caller_definition
                fixture["candidate"] = replace(
                    fixture["candidate"],
                    caller_definition=replacement(definition),
                )
                expected_error = (
                    "EAX setup"
                    if label in {"symbol", "undefined-population"}
                    else "REL32 relocation"
                )
                with self.assertRaisesRegex(ValueError, expected_error):
                    self.prove(fixture, **fixture["wol_arguments"])

        fixture = self.wol_submit_status_fixture(caller_identity)
        fixture["expected"] = []
        with self.assertRaisesRegex(ValueError, "retail direct no-cleanup"):
            self.prove(fixture, **fixture["wol_arguments"])

        fixture = self.wol_submit_status_fixture(caller_identity)
        target_values = vars(fixture["candidate"].target).copy()
        target_values["source_from"] = "src/Battlesport/Wrong.cpp"
        fixture["candidate"] = replace(
            fixture["candidate"],
            target=SimpleNamespace(**target_values),
        )
        with self.assertRaisesRegex(ValueError, "selected two-TU"):
            self.prove(fixture, **fixture["wol_arguments"])

