    def test_chkstk_bridge_accepts_only_the_two_additional_reviewed_callers(
        self,
    ) -> None:
        cases = (
            {
                "caller_id": "recoil:function:0x438350",
                "address": "0x438350",
                "end": "0x4383e0",
                "size": 0x90,
                "block": "recoil:block:0x438350",
                "symbol": "?ShowMessageBox@HudUi@@YIHPBD0PAX@Z",
                "retail": (
                    "0043835e b8 14 b2 00 00 mov eax, 0xb214\n"
                    "0043836a e8 91 dd 08 00 call __alloca_probe"
                ),
                "candidate_frame": 0xB214,
            },
            {
                "caller_id": "recoil:function:0x460490",
                "address": "0x460490",
                "end": "0x4606d0",
                "size": 0x240,
                "block": "recoil:block:0x4603d0",
                "symbol": (
                    "?SaveActivationRecords@zEffect_Anim@@"
                    "YIHPAUzZbdSectionCallbackCtx@@@Z"
                ),
                "retail": (
                    "00460490 b8 84 44 00 00 mov eax, 0x4484\n"
                    "00460495 e8 66 5c 06 00 call __alloca_probe"
                ),
                "candidate_frame": 0x448C,
            },
        )
        for row in cases:
            with self.subTest(address=row["address"]):
                fixture = self.fixture()
                fixture["data"]["symbols"][row["caller_id"]] = {
                    "binary": "recoil",
                    "kind": "function",
                    "pipeline_class": "authored",
                    "address": row["address"],
                    "end_exclusive": row["end"],
                    "extent_state": "known",
                    "size": row["size"],
                    "ownership_state": "primary-owned",
                    "physical_block_id": row["block"],
                }
                self.rebuild_document(fixture)
                frame = int(row["candidate_frame"])
                body = b"\xb8" + struct.pack("<I", frame) + b"\xe8\0\0\0\0"
                fixture["retail"] = parse_assembly(
                    str(row["retail"]),
                    source="bn",
                )
                fixture["candidate"] = CandidateAssembly(
                    instructions=parse_assembly(
                        "00000 b8 "
                        + struct.pack("<I", frame).hex(" ")
                        + f" mov eax, {frame}\n"
                        "00005 e8 00 00 00 00 call __chkstk",
                        source="cod",
                    ),
                    local_control_flow_indices=frozenset(),
                    caller_definition=CandidateCallerDefinition(
                        symbol=str(row["symbol"]),
                        data=body,
                        relocations=(
                            CoffRelocation(6, 1, 0x14, "__chkstk"),
                        ),
                        relocation_mask=(False,) * 6 + (True,) * 4,
                        undefined_external_functions=("__chkstk",),
                    ),
                )
                self.assertEqual(
                    {"__chkstk": self.target_identity},
                    self.prove(
                        fixture,
                        caller_identity=f"symbol:{row['caller_id']}",
                        caller_start=str(row["address"]),
                        caller_end_exclusive=str(row["end"]),
                    ),
                )

