    def test_qualification_rejects_partial_census_and_candidate_truth(self):
        module = call_contract_verify_module
        symbol_ids = [
            f"recoil:function:0x{0x410000 + index * 0x10:x}"
            for index in range(module.PLAYER_PROFILE_MATRIX_BODY_COUNT)
        ]
        symbol_ids[0] = module.PLAYER_PROFILE_MATRIX_CALLER_ID
        contracts = {symbol_id: [] for symbol_id in symbol_ids}
        signatures = [{"path": module.PLAYER_PROFILE_MATRIX_SOURCE}]
        result = {
            "kind": "authored-call-contract-target-convergence-result",
            "target_id": module.PLAYER_PROFILE_MATRIX_TARGET_ID,
            "body_count": module.PLAYER_PROFILE_MATRIX_BODY_COUNT,
            "symbol_ids": symbol_ids,
            "expected_contracts": contracts,
            "candidate_contracts": deepcopy(contracts),
            "caller_census": {
                "complete": True,
                "ordered_caller_count": module.PLAYER_PROFILE_MATRIX_BODY_COUNT,
                "evaluated_caller_count": module.PLAYER_PROFILE_MATRIX_BODY_COUNT,
                "passing_caller_count": module.PLAYER_PROFILE_MATRIX_BODY_COUNT,
                "divergent_caller_count": 0,
                "semantic_mismatch_caller_count": 0,
                "verifier_blocked_caller_count": 0,
                "divergences": [],
            },
            "source_changed_during_validation": False,
            "source_header_signatures_before": signatures,
            "source_header_signatures_after": signatures,
            "all_authored_bodies": True,
            "compiled_target_ids": [module.PLAYER_PROFILE_MATRIX_TARGET_ID],
            "selected_target_compile_count": 1,
            "all_caller_divergences_collected": True,
            "definition_closure_deferred": True,
            "expected_truth": (
                "retail-binary-ninja-plus-reviewed-tracker-identities"
            ),
            "candidate_expected_truth": False,
            "passed": True,
        }
        qualified = module._player_profile_matrix_qualification(
            target_id=module.PLAYER_PROFILE_MATRIX_TARGET_ID,
            live_result=result,
            signatures_before=signatures,
            signatures_after=signatures,
        )
        self.assertTrue(qualified["proof_complete"])
        self.assertTrue(qualified["caller_0x42a070_result"]["passed"])
        for label, mutate in (
            (
                "partial-census",
                lambda row: row["caller_census"].update(
                    evaluated_caller_count=168
                ),
            ),
            (
                "candidate-truth",
                lambda row: row.update(candidate_expected_truth=True),
            ),
        ):
            with self.subTest(label=label):
                malformed = deepcopy(result)
                mutate(malformed)
                self.assertFalse(
                    module._player_profile_matrix_qualification(
                        target_id=module.PLAYER_PROFILE_MATRIX_TARGET_ID,
                        live_result=malformed,
                        signatures_before=signatures,
                        signatures_after=signatures,
                    )["proof_complete"]
                )

        deleted = deepcopy(result)
        deleted["candidate_contracts"].pop(symbol_ids[-1])
        self.assertFalse(
            module._player_profile_matrix_qualification(
                target_id=module.PLAYER_PROFILE_MATRIX_TARGET_ID,
                live_result=deleted,
                signatures_before=signatures,
                signatures_after=signatures,
            )["proof_complete"]
        )
        substituted = deepcopy(result)
        substituted["candidate_contracts"]["recoil:function:0xdeadbeef"] = (
            substituted["candidate_contracts"].pop(symbol_ids[-1])
        )
        self.assertFalse(
            module._player_profile_matrix_qualification(
                target_id=module.PLAYER_PROFILE_MATRIX_TARGET_ID,
                live_result=substituted,
                signatures_before=signatures,
                signatures_after=signatures,
            )["proof_complete"]
        )

    def test_profile_comparison_uses_exact_sets_and_regressions_block_selection(self):
        module = call_contract_verify_module
        proof = {"passed": True}
        compared = module._player_profile_matrix_profile_comparison(
            {
                "proof_complete": True,
                "passing_symbol_ids": ["a", "b"],
            },
            {
                "proof_complete": True,
                "passing_symbol_ids": ["a", "c"],
            },
            strict_paired_proof=proof,
        )
        self.assertEqual(["c"], compared["repaired_by_ob1"])
        self.assertEqual(["b"], compared["regressed_by_ob1"])
        self.assertEqual("regressed", compared["ob1_disposition"])
        self.assertFalse(compared["selection_eligible"])
        self.assertFalse(compared["naturally_explains"])

        no_regression = module._player_profile_matrix_profile_comparison(
            {
                "proof_complete": True,
                "passing_symbol_ids": ["a"],
            },
            {
                "proof_complete": True,
                "passing_symbol_ids": ["a", "c"],
            },
            strict_paired_proof=proof,
        )
        self.assertTrue(no_regression["selection_eligible"])
        failed_strict = module._player_profile_matrix_profile_comparison(
            {
                "proof_complete": True,
                "passing_symbol_ids": ["a"],
            },
            {
                "proof_complete": True,
                "passing_symbol_ids": ["a", "c"],
            },
            strict_paired_proof={"passed": False},
        )
        self.assertFalse(failed_strict["selection_eligible"])

        with self.assertRaisesRegex(ValueError, "exact complete"):
            module._player_profile_matrix_profile_comparison(
                {
                    "proof_complete": True,
                    "passing_symbol_ids": ["a"],
                },
                {
                    "proof_complete": False,
                    "passing_symbol_ids": ["a", "c"],
                },
                strict_paired_proof=proof,
            )

    def test_strict_paired_proof_rejects_19_to_13_and_source_receipt_drift(self):
        module = call_contract_verify_module

        def graph(count):
            return {
                "caller": {
                    "symbol": "?caller@@YAXXZ",
                    "call_sites": [
                        {
                            "instruction_offset": index * 5,
                            "form": "call",
                            "relocation": {
                                "offset": index * 5 + 1,
                                "type": module.IMAGE_REL_I386_REL32,
                                "symbol": f"?leaf{index}@@YAXXZ",
                            },
                        }
                        for index in range(count)
                    ],
                },
                "definitions": {},
            }

        receipt = {
            "kind": "vc5-preprocess-once-paired-input-receipt",
            "contract_version": 1,
            "candidate_expected_truth": False,
            "preprocess_invocation_count": 1,
            "preprocessed_input_equal_direct": True,
            "non_ob_options_equal": True,
            "ob0_inline_option": "/Ob0",
            "ob1_inline_option": "/Ob1",
            "toolchain_components_equal": True,
            "fresh_exclusive_artifacts": True,
        }
        proof = module._player_strict_paired_profile_proof(
            graph(19),
            graph(13),
            same_preprocessed_source_receipt=receipt,
            stage_c_exact_retail=True,
        )
        self.assertEqual(19, proof["stage_a_projected_invocation_count"])
        self.assertEqual(13, proof["stage_b_ob1_physical_invocation_count"])
        self.assertFalse(proof["stage_b_cardinality_equal"])
        self.assertFalse(proof["passed"])
        self.assertIn("projected_ob0=19", proof["failure"]["reason"])

        drifted = deepcopy(receipt)
        drifted["preprocessed_input_equal_direct"] = False
        same_population = module._player_strict_paired_profile_proof(
            graph(2),
            graph(2),
            same_preprocessed_source_receipt=drifted,
            stage_c_exact_retail=True,
        )
        self.assertFalse(same_population["same_preprocessed_source"])
        self.assertFalse(same_population["passed"])

    def test_profile_matrix_runs_both_complete_direct_retail_censuses(self):
        module = call_contract_verify_module
        document = self.document()
        source_signatures = [{"path": module.PLAYER_PROFILE_MATRIX_SOURCE}]
        ob0_live = self.retail_result(
            divergent_symbol_ids=(
                module.PLAYER_PROFILE_MATRIX_CALLER_ID,
                "recoil:function:0x410010",
            )
        )
        ob1_live = self.retail_result(
            divergent_symbol_ids=("recoil:function:0x410010",)
        )

        def compile_units(
            *,
            target,
            build_dir,
            compiler_env,
            capture_verification_receipt,
        ):
            del build_dir, compiler_env
            self.assertIs(True, capture_verification_receipt)
            return (self.matrix_compile_unit(target),), 0

        def run(snapshot):
            with (
                patch.object(
                    module,
                    "prepare_clean_build_dir",
                    return_value=REPO_ROOT / "build/player-matrix-test",
                ),
                patch.object(
                    module,
                    "compile_translation_unit_order",
                    side_effect=compile_units,
                ) as compile_spy,
                patch.object(
                    module,
                    "_player_profile_matrix_candidate_snapshot",
                    side_effect=[deepcopy(snapshot), deepcopy(snapshot)],
                ),
                patch.object(module.CoffObject, "from_path", return_value=object()),
                patch.object(
                    module,
                    "live_call_contract_result",
                    side_effect=[deepcopy(ob0_live), deepcopy(ob1_live)],
                ) as live_spy,
                patch.object(
                    module,
                    "file_dependency_states",
                    return_value=source_signatures,
                ),
            ):
                result = module.player_call_contract_profile_matrix(
                    document=document,
                    target_id=module.PLAYER_PROFILE_MATRIX_TARGET_ID,
                    build_root=REPO_ROOT / "build/player-matrix-test",
                )
            self.assertEqual(2, compile_spy.call_count)
            self.assertEqual(2, live_spy.call_count)
            for call in live_spy.call_args_list:
                self.assertTrue(call.kwargs["all_authored_bodies"])
                self.assertTrue(call.kwargs["collect_all_divergences"])
                self.assertFalse(call.kwargs["compile_definition_closure"])
                self.assertEqual(
                    [module.PLAYER_PROFILE_MATRIX_TARGET_ID],
                    list(call.kwargs["precompiled_target_units"]),
                )
            return result

        drifted = run(self.raw_snapshot(legacy_match=False))
        self.assertTrue(drifted["matrix_completed"])
        self.assertEqual(
            [module.PLAYER_PROFILE_MATRIX_CALLER_ID],
            drifted["repaired_by_ob1"],
        )
        self.assertEqual([], drifted["regressed_by_ob1"])
        self.assertFalse(drifted["selection_eligible"])
        self.assertFalse(
            drifted["caller_0x42a070_ob1_naturally_explains_retail"]
        )
        self.assertFalse(
            drifted["caller_0x42a070_strict_paired_proof"]
            ["recursive_candidate_graph_used"]
        )
        for scenario, live_result in zip(
            drifted["profiles"], (ob0_live, ob1_live)
        ):
            expected_rows = live_result["caller_census"]["divergences"]
            self.assertEqual(expected_rows, scenario["caller_divergences"])
            self.assertIsNot(expected_rows, scenario["caller_divergences"])
            expected_ids = [row["symbol_id"] for row in expected_rows]
            self.assertEqual(
                expected_ids,
                list(scenario["divergent_expected_contracts"]),
            )
            self.assertEqual(
                expected_ids,
                list(scenario["divergent_candidate_contracts"]),
            )
            self.assertTrue(scenario["proof_complete"])

        drifted["profiles"][0]["caller_divergences"][0]["kind"] = (
            "mutated-report"
        )
        drifted["profiles"][0]["divergent_expected_contracts"][
            module.PLAYER_PROFILE_MATRIX_CALLER_ID
        ].append({"mutated": True})
        self.assertEqual(
            "semantic-mismatch",
            ob0_live["caller_census"]["divergences"][0]["kind"],
        )
        self.assertEqual(
            [],
            ob0_live["expected_contracts"][
                module.PLAYER_PROFILE_MATRIX_CALLER_ID
            ],
        )
        requalified = module._player_profile_matrix_qualification(
            target_id=module.PLAYER_PROFILE_MATRIX_TARGET_ID,
            live_result=ob0_live,
            signatures_before=source_signatures,
            signatures_after=source_signatures,
        )
        self.assertTrue(requalified["proof_complete"])
        self.assertEqual(
            ob0_live["caller_census"]["divergences"],
            requalified["caller_divergences"],
        )

        repeated = run(self.raw_snapshot(legacy_match=True))
        self.assertEqual(drifted["ob0_pass_set"], repeated["ob0_pass_set"])
        self.assertEqual(drifted["ob1_pass_set"], repeated["ob1_pass_set"])
        self.assertEqual(
            drifted["repaired_by_ob1"], repeated["repaired_by_ob1"]
        )
        self.assertEqual(
            drifted["regressed_by_ob1"], repeated["regressed_by_ob1"]
        )

