    def test_caller_body_extent_cod_and_relocation_mutations_fail_closed(self) -> None:
        module = call_contract_verify_module
        address = "0x42a070"
        base = self.candidate(address)
        caller = base.caller_definition
        self.assertIsNotNone(caller)
        relocation = caller.relocations[14]
        mutations = {
            "body": replace(
                base,
                caller_definition=replace(
                    caller, data=b"\x90" + caller.data[1:]
                ),
            ),
            "extent": replace(
                base,
                caller_definition=replace(caller, section_end=0x251),
            ),
            "relocation-offset": replace(
                base,
                caller_definition=replace(
                    caller,
                    relocations=tuple(
                        replace(row, offset=row.offset + 1)
                        if row is relocation else row
                        for row in caller.relocations
                    ),
                ),
            ),
            "relocation-type": replace(
                base,
                caller_definition=replace(
                    caller,
                    relocations=tuple(
                        replace(row, type=module.IMAGE_REL_I386_DIR32)
                        if row is relocation else row
                        for row in caller.relocations
                    ),
                ),
            ),
            "relocation-symbol": replace(
                base,
                caller_definition=replace(
                    caller,
                    relocations=tuple(
                        replace(row, symbol_name="?_Construct@std@@YAXXZ")
                        if row is relocation else row
                        for row in caller.relocations
                    ),
                ),
            ),
            "mask": replace(
                base,
                caller_definition=replace(
                    caller,
                    relocation_mask=tuple(
                        False if index == relocation.offset else value
                        for index, value in enumerate(caller.relocation_mask)
                    ),
                ),
            ),
        }
        for label, candidate in mutations.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "Player /Ob1 finite caller profile"
            ):
                self.project(address, candidate=candidate)

    def test_helper_body_graph_selection_population_and_provenance_fail_closed(self) -> None:
        address = "0x42a070"
        base = self.candidate(address)
        name = (
            "?_Ucopy@?$vector@PAUzInput_BindGroupInfo@@"
            "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@"
            "IAEPAPAUzInput_BindGroupInfo@@PBQAU3@0PAPAU3@@Z"
        )
        helper = base.tu_local_function_definitions[name]
        caller = base.caller_definition
        helper_symbol = next(
            row for row in caller.coff_symbols if row.name == name
        )
        duplicate = replace(
            helper_symbol,
            index=max(row.index for row in caller.coff_symbols) + 1,
        )
        mutations = {
            "body": replace(helper, data=b"\x90" + helper.data[1:]),
            "nop": replace(
                helper, data=helper.data[:-1] + b"\xcc"
            ),
            "selection": replace(helper, comdat_selection=1),
            "provenance": replace(helper, source_provenance="other/vector"),
            "nested-relocation": replace(
                helper,
                relocations=(CoffRelocation(
                    1, helper_symbol.index,
                    call_contract_verify_module.IMAGE_REL_I386_REL32,
                    name,
                ),),
            ),
        }
        for label, changed in mutations.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "Player /Ob1 finite helper"
            ):
                self.project(
                    address,
                    candidate=replace(
                        base,
                        tu_local_function_definitions={
                            **base.tu_local_function_definitions,
                            name: changed,
                        },
                    ),
                )
        with self.assertRaisesRegex(ValueError, "finite helper"):
            self.project(
                address,
                candidate=replace(
                    base,
                    caller_definition=replace(
                        caller,
                        coff_symbols=(*caller.coff_symbols, duplicate),
                    ),
                ),
            )
        fake_name = (
            "?unexpected@?$vector@PAUzInput_BindGroupInfo@@"
            "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@QAEXXZ"
        )
        with self.assertRaisesRegex(ValueError, "pointer-vector helper graph"):
            self.project(
                address,
                candidate=replace(
                    base,
                    tu_local_function_definitions={
                        **base.tu_local_function_definitions,
                        fake_name: replace(helper, symbol=fake_name),
                    },
                ),
            )
        destroy_name = next(
            item for item in base.tu_local_function_definitions
            if item.startswith(
                "?_Destroy@?$vector@PAUzInput_BindGroupInfo@@"
            )
        )
        destroy = base.tu_local_function_definitions[destroy_name]
        with self.assertRaisesRegex(ValueError, "finite helper"):
            self.project(
                address,
                candidate=replace(
                    base,
                    tu_local_function_definitions={
                        **base.tu_local_function_definitions,
                        destroy_name: replace(
                            destroy,
                            data=b"\xc2\x0c\x00" + destroy.data[3:],
                        ),
                    },
                ),
            )

    def test_row_deletion_reorder_substitution_and_dispatch_drift_fail_closed(self) -> None:
        address = "0x42a070"
        expected = self.identity_rows(address)
        cases = {
            "delete-size": [*expected[:9], *expected[10:]],
            "duplicate-size": [*expected, expected[9]],
            "swap-copy-fill": [
                *expected[:4], expected[5], expected[4], *expected[6:]
            ],
            "construct-substitution": [
                *expected[:4],
                {**expected[4], "target_identity": "candidate-local-coff:_Construct"},
                *expected[5:],
            ],
            "dispatch": [
                *expected[:4],
                {**expected[4], "dispatch": "indirect"},
                *expected[5:],
            ],
            "cleanup": [
                {**expected[0], "cleanup_bytes": None}, *expected[1:]
            ],
        }
        for label, candidate_rows in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "row deletion, reorder, substitution"
            ):
                self.project(
                    address,
                    expected=expected,
                    candidate_rows=candidate_rows,
                )
        immutable_truth_mutations = {
            "ordinal-1-local-record-constructor": (
                1, "candidate-local-coff:??0zInput_BindGroupInfo@@QAE@XZ"
            ),
            "ordinal-1-wrong-import-thunk": (
                1, "provider:recoil:function:0x4c5ba6"
            ),
            "ordinal-4-construct": (
                4, "candidate-local-coff:?_Construct@std@@YAXXZ"
            ),
        }
        for label, (ordinal, identity) in immutable_truth_mutations.items():
            contaminated = deepcopy(expected)
            contaminated[ordinal] = {
                **contaminated[ordinal], "target_identity": identity
            }
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "immutable retail target identity drift"
            ):
                self.project(
                    address,
                    expected=contaminated,
                    candidate_rows=deepcopy(contaminated),
                )

