    def inline_empty_check_fixture(self):
        instructions = tuple(
            parse_assembly(
                "00065 a1 00 00 00 00 mov eax, DWORD PTR "
                "_?pendingStatusText@?4??SubmitVisibleSessionRequestsAndStatusText@"
                "WestwoodOnlineUpgradeDialog@@QAEXXZ@4VCString@@A$S74970\n"
                "0006a 8b 48 f8 mov ecx, DWORD PTR [eax-8]\n"
                "0006d 85 c9 test ecx, ecx\n"
                "0006f 0f 84 00 00 00 00 je $L74999",
                source="cod",
            )
        )
        data = bytearray(0x75)
        data[0x65:0x6A] = b"\xa1\0\0\0\0"
        data[0x6A:0x6F] = b"\x8b\x48\xf8\x85\xc9"
        data[0x6F:0x75] = b"\x0f\x84\0\0\0\0"
        mask = [False] * len(data)
        mask[0x66:0x6A] = [True] * 4
        parsed = CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=frozenset(),
        )
        body = call_contract_verify_module.CoffFunctionBytes(
            symbol=call_contract_verify_module.WOL_PROFILE_MATRIX_EMPTY_CHECK_SYMBOL,
            section_name=".text",
            section_index=1,
            start=0,
            end=len(data),
            natural_end=len(data),
            data=bytes(data),
            relocations=(
                CoffRelocation(
                    0x66,
                    1,
                    0x06,
                    "_?pendingStatusText@?4??"
                    "SubmitVisibleSessionRequestsAndStatusText@"
                    "WestwoodOnlineUpgradeDialog@@QAEXXZ@4VCString@@A$S74970",
                ),
            ),
            relocation_mask=tuple(mask),
            excluded_tail_relocation_count=0,
        )
        return parsed, body

    def test_profile_matrix_requires_exact_inline_empty_check_dataflow(self) -> None:
        module = call_contract_verify_module
        parsed, body = self.inline_empty_check_fixture()
        self.assertTrue(
            module._wol_profile_matrix_inline_empty_check(parsed, body)[
                "matched"
            ]
        )

        drifted = replace(
            parsed,
            instructions=(
                *parsed.instructions,
                parse_assembly(
                    "00075 e8 00 00 00 00 call ?IsEmpty@CString@@QBEHXZ",
                    source="cod",
                )[0],
            ),
        )
        self.assertFalse(
            module._wol_profile_matrix_inline_empty_check(drifted, body)[
                "matched"
            ]
        )

    def test_profile_matrix_retail_normalization_is_exact_and_fail_closed(
        self,
    ) -> None:
        module = call_contract_verify_module
        signatures = [{"path": "WOL.cpp", "exists": True, "size": 1}]

        def qualify(*, result=None, scenario=None, after=None, ambiguity=0,
                    scope="wol-only", profile="P1"):
            return module._wol_profile_matrix_retail_normalization_qualification(
                target_id=self.target_id,
                scope=scope,
                profile_id=profile,
                scenario=scenario or self.retail_scenario(),
                live_result=result or self.retail_result(),
                source_signatures_before=signatures,
                source_signatures_after=signatures if after is None else after,
                ambiguous_delta_count=ambiguity,
            )

        positive = qualify()
        self.assertTrue(positive["passed"])
        self.assertTrue(positive["selection_eligible"])
        self.assertTrue(positive["manifest_mutation_allowed"])
        self.assertEqual(109, positive["expected_body_count"])
        self.assertEqual(109, positive["candidate_body_count"])
        self.assertEqual([], positive["failure_reasons"])

        blocked = qualify(
            result=self.retail_result(
                passed=False,
                first_divergence={"kind": "verifier-blocked"},
                caller_divergences=[{"kind": "verifier-blocked"}],
            )
        )
        self.assertIn("retail-verifier-blocked", blocked["failure_reasons"])
        self.assertFalse(blocked["selection_eligible"])

        mismatch = qualify(
            result=self.retail_result(
                passed=False,
                first_divergence={"kind": "call-count"},
                caller_divergences=[{"kind": "call-count"}],
            )
        )
        self.assertIn("retail-contract-mismatch", mismatch["failure_reasons"])

        incomplete_result = self.retail_result()
        incomplete_result["candidate_contracts"] = dict(
            list(incomplete_result["candidate_contracts"].items())[:-1]
        )
        incomplete = qualify(result=incomplete_result)
        self.assertIn("incomplete-retail-population", incomplete["failure_reasons"])

        drift = qualify(
            after=[{"path": "WOL.cpp", "exists": True, "size": 2}]
        )
        self.assertIn("source-drift", drift["failure_reasons"])

        wrong_scenario = qualify(scope="both-tu")
        self.assertIn(
            "wrong-retail-normalization-scenario",
            wrong_scenario["failure_reasons"],
        )

        misuse = qualify(
            result=self.retail_result(
                compiled_target_ids=[],
                selected_target_compile_count=0,
            )
        )
        self.assertIn("precompiled-target-misuse", misuse["failure_reasons"])

        ambiguous = qualify(ambiguity=1)
        self.assertNotIn(
            "ambiguous-profile-delta", ambiguous["failure_reasons"]
        )
        self.assertEqual(1, ambiguous["scenario_ambiguous_delta_count"])
        self.assertTrue(ambiguous["selection_eligible"])

        missing_inline = qualify(
            scenario=self.retail_scenario(
                inline_empty_check={
                    "matched": False,
                    "address": module.WOL_PROFILE_MATRIX_EMPTY_CHECK_ADDRESS,
                }
            )
        )
        self.assertIn(
            "missing-positive-inline-dataflow",
            missing_inline["failure_reasons"],
        )

    @unittest.skip("retired profile-reuse fixture")
    def test_profile_matrix_orchestration_is_nonaccepting_and_reports_ambiguity(
        self,
    ) -> None:
        module = call_contract_verify_module
        target = self.target()
        document = ProgressDocument(
            {
                **empty_progress_document(),
                "verification_targets": {
                    self.target_id: {
                        "binary": "recoil",
                        "kind": "vc5",
                        "name": target.name,
                        "registration": {
                            "manifest_path": target.manifest_path.relative_to(
                                REPO_ROOT
                            ).as_posix(),
                            "source_from": module.WOL_PROFILE_MATRIX_WOL_SOURCE,
                            "check_translation_unit_function_order": True,
                            "function_order_scope": "authored",
                        },
                    }
                },
            }
        )
        body_keys = [f"0x{0x430000 + index * 0x10:x}:?Body{index}@@YAXXZ"
                     for index in range(109)]
        target_key = body_keys[0]

        def snapshot(variant, _units):
            profile = dict(variant.source_compile_profiles)[
                module.canonical_source_key(module.WOL_PROFILE_MATRIX_WOL_SOURCE)
            ].rsplit("-", 1)[-1]
            positive = profile in {"P1", "P2", "implicit"}
            contracts = {}
            for index, key in enumerate(body_keys):
                contract = [
                    {
                        "ordinal": 0,
                        "form": "call",
                        "dispatch": "direct",
                        "target": "?baseline@@yaxxz",
                    }
                ]
                if key == target_key and positive:
                    contract = []
                if index == 1 and profile in {"P1", "implicit"}:
                    contract.append(
                        {
                            "ordinal": len(contract),
                            "form": "call",
                            "dispatch": "direct",
                            "target": "?ambiguous@@yaxxz",
                        }
                    )
                address, symbol = key.split(":", 1)
                contracts[key] = {
                    "address": (
                        module.WOL_PROFILE_MATRIX_EMPTY_CHECK_ADDRESS
                        if key == target_key
                        else address
                    ),
                    "symbol": symbol,
                    "source_from": module.WOL_PROFILE_MATRIX_WOL_SOURCE,
                    "contract": contract,
                }
            return {
                "body_count": 109,
                "contracts": contracts,
                "inline_empty_check": {
                    "matched": positive,
                    "address": module.WOL_PROFILE_MATRIX_EMPTY_CHECK_ADDRESS,
                },
                "selected_artifact_receipt": {
                    "kind": "wol-selected-body-population-receipt",
                    "contract_version": 1,
                    "body_count": 109,
                    "population_rows": (
                        "p1-equivalent"
                        if profile in {"P1", "implicit"}
                        else profile
                    ),
                    "candidate_expected_truth": False,
                },
            }

        def compile_units(*, target, build_dir, compiler_env):
            del build_dir, compiler_env
            return (
                tuple(
                    SimpleNamespace(
                        manifest_index=index,
                        source_from=entry.source_from,
                        effective_compiler_profile=(
                            module.effective_source_compile_context(
                                target, entry.source_from
                            )[0]
                        ),
                        effective_compiler_flags=(
                            module.effective_source_compile_context(
                                target, entry.source_from
                            )[1]
                        ),
                        compile_command=(
                            "cl "
                            + " ".join(
                                module.effective_source_compile_context(
                                    target, entry.source_from
                                )[1]
                            )
                            + " /c "
                            + entry.source_from
                        ),
                        obj_path=REPO_ROOT / "build/matrix.obj",
                        cod_path=REPO_ROOT / "build/matrix.cod",
                    )
                    for index, entry in enumerate(
                        target.translation_unit_function_order
                    )
                ),
                0,
            )

        signatures = [
            {"path": path, "exists": True, "size": 1, "mtime_ns": 1}
            for path in (
                module.WOL_PROFILE_MATRIX_WOL_SOURCE,
                module.WOL_PROFILE_MATRIX_COMPANION_SOURCE,
            )
        ]
        with (
            patch.object(module, "load_manifest", return_value=target),
            patch.object(module, "require_clean_target_source_fragments"),
            patch.object(module, "prepare_clean_build_dir", return_value=REPO_ROOT / "build/matrix"),
            patch.object(module, "compile_translation_unit_order", side_effect=compile_units) as compile_spy,
            patch.object(module, "_wol_profile_matrix_candidate_snapshot", side_effect=snapshot),
            patch.object(module.CoffObject, "from_path", return_value=object()),
            patch.object(
                module,
                "live_call_contract_result",
                return_value=self.retail_result(),
            ) as live_spy,
            patch.object(module, "file_dependency_states", return_value=signatures),
        ):
            result = module.wol_call_contract_profile_matrix(
                document=document,
                target_id=self.target_id,
                build_root=REPO_ROOT / "build/matrix",
            )

        self.assertTrue(result["passed"])
        self.assertTrue(result["nonaccepting"])
        self.assertFalse(result["acceptance_eligible"])
        self.assertTrue(result["selection_eligible"])
        self.assertTrue(result["retail_selection_eligible"])
        self.assertTrue(result["manifest_mutation_allowed"])
        self.assertTrue(result["profile_supported_for_source_repair"])
        self.assertEqual("P1", result["provisional_effective_profile"]["profile_id"])
        self.assertEqual(8, len(result["scenarios"]))
        self.assertEqual(8, compile_spy.call_count)
        live_spy.assert_called_once()
        live_kwargs = live_spy.call_args.kwargs
        self.assertTrue(live_kwargs["collect_all_divergences"])
        self.assertFalse(live_kwargs["compile_definition_closure"])
        self.assertEqual(
            [self.target_id],
            list(live_kwargs["precompiled_target_units"]),
        )
        precompiled_target, precompiled_units = (
            live_kwargs["precompiled_target_units"][self.target_id]
        )
        self.assertEqual(target.name, precompiled_target.name)
        self.assertEqual(2, len(precompiled_units))
        self.assertGreater(result["diagnostic_ambiguous_delta_count"], 0)
        self.assertEqual(
            "scope-profile-local-report-only",
            result["ambiguity_disposition"],
        )
        self.assertTrue(result["p1_meets_zero_hard_regression_threshold"])
        self.assertTrue(result["p1_implicit_equivalence"]["passed"])
        p2_rows = [
            row for row in result["scenarios"]
            if row["profile_id"] == "P2"
        ]
        self.assertEqual(2, len(p2_rows))
        self.assertTrue(
            all(row["profile_status"] == "falsified" for row in p2_rows)
        )
        for scenario in result["scenarios"]:
            self.assertEqual(109, scenario["body_count"])
            self.assertEqual(2, len(scenario["unit_commands"]))
            self.assertTrue(
                all(row["compile_command"].startswith("cl ")
                    for row in scenario["unit_commands"])
            )


