class HudUiMgrZrdPayloadTuLocalIdentityBridgeTests(unittest.TestCase):
    cod_symbol = (
        "?HudUiZrdPayload@?_tu_order\\00_hud.cpp2653028044"
        "@@YIPAUNode@zReader@@PAU23@@Z"
    )
    coff_symbol = (
        "?HudUiZrdPayload@?%_tu_order\\00_hud.cpp2653028044"
        "@@YIPAUNode@zReader@@PAU23@@Z"
    )
    call_offsets = (0x23D, 0x3E8, 0x748, 0x829, 0xAD9, 0xB85, 0xBC5)
    helper_body = bytes.fromhex(
        "85 c9 74 09 83 39 04 75 04 8b 41 04 c3 33 c0 c3"
    )

    def fixture(self) -> dict:
        invocation = InvocationSignatureTests()
        retail_fixture = invocation._hud_ensure_font_loop_fixture()
        candidate = invocation._hud_ensure_font_loop_candidate(
            retail_fixture
        )
        indexes = replace(
            retail_fixture["indexes"],
            by_candidate_name={
                "?TestDirect@HudUiMgr@@YIXXZ": (
                    retail_fixture["direct_identity"]
                ),
                (
                    "?ReadRect@HudUiLayoutNode@@YIHPAUNode@zReader@@"
                    "PAUHudUiRect@@@Z"
                ): retail_fixture["direct_identity"],
            },
        )
        retail_bridges = invocation._hud_ensure_font_loop_bridges(
            retail_fixture
        )
        expected = extract_invocation_contract(
            retail_fixture["instructions"],
            source="bn",
            caller_identity=retail_fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=indexes,
            reviewed_loop_vptr_storage_bridges=retail_bridges,
        )

        payload_instructions = tuple(
            parse_assembly(
                "\n".join(
                    f"{offset:05x} e8 00 00 00 00 call {self.cod_symbol}"
                    for offset in self.call_offsets
                ),
                source="cod",
            )
        )
        caller = candidate.caller_definition
        assert caller is not None
        data = bytearray(caller.data)
        relocation_mask = list(caller.relocation_mask)
        payload_relocations = tuple(
            CoffRelocation(
                offset=offset + 1,
                symbol_index=911,
                type=0x14,
                symbol_name=self.coff_symbol,
            )
            for offset in self.call_offsets
        )
        for offset in self.call_offsets:
            data[offset : offset + 5] = b"\xe8\x00\x00\x00\x00"
            for index in range(offset + 1, offset + 5):
                relocation_mask[index] = True
        candidate = replace(
            candidate,
            instructions=(
                *candidate.instructions,
                *payload_instructions,
            ),
            tu_local_function_definitions={
                self.coff_symbol: CandidateTuLocalFunctionDefinition(
                    symbol=self.coff_symbol,
                    data=self.helper_body,
                    relocations=(),
                    relocation_mask=(False,) * len(self.helper_body),
                    section_size=len(self.helper_body),
                    section_external_functions=(self.coff_symbol,),
                )
            },
            caller_definition=replace(
                caller,
                data=bytes(data),
                relocations=(
                    *caller.relocations,
                    *payload_relocations,
                ),
                relocation_mask=tuple(relocation_mask),
                defined_external_functions=(self.coff_symbol,),
            ),
        )
        return {
            "candidate": candidate,
            "document": retail_fixture["document"],
            "indexes": indexes,
            "expected": expected,
            "caller_identity": retail_fixture["caller_identity"],
            "loop_bridges": {
                "0x167": ReviewedLoopVptrStorageBridge(
                    register="eax",
                    storage_identity=(
                        "load(address("
                        "hud-ui-string-menu-item-loop-element))"
                    ),
                    slot_displacement=0x80,
                    assembly_source="cod",
                )
            },
        }

    def bridges(
        self,
        fixture: dict,
        *,
        candidate: CandidateAssembly | None = None,
        **overrides: object,
    ) -> dict[str, str]:
        arguments = {
            "expected": fixture["expected"],
            "candidate": (
                candidate
                if candidate is not None
                else fixture["candidate"]
            ),
            "document": fixture["document"],
            "caller_identity": fixture["caller_identity"],
            "caller_start": "0x410160",
            "caller_end_exclusive": "0x410d10",
            "indexes": fixture["indexes"],
            "bridge_names": {},
            "compiler_generated_bridges": {},
        }
        arguments.update(overrides)
        return _hud_ui_mgr_zrd_payload_tu_local_candidate_bridge(
            **arguments
        )

    def test_exact_helper_keeps_all_seven_candidate_calls_visible(
        self,
    ) -> None:
        fixture = self.fixture()
        bridges = self.bridges(fixture)
        self.assertEqual(
            {self.cod_symbol: fixture["caller_identity"]},
            bridges,
        )
        candidate_contract = extract_invocation_contract(
            fixture["candidate"].instructions,
            source="cod",
            caller_identity=fixture["caller_identity"],
            caller_start="0x410160",
            caller_end_exclusive="0x410d10",
            indexes=fixture["indexes"],
            compiler_generated_bridges=bridges,
            reviewed_loop_vptr_storage_bridges=fixture["loop_bridges"],
        )
        sentinel_rows = [
            row
            for row in candidate_contract
            if row["target_identity"] == fixture["caller_identity"]
        ]
        self.assertEqual(7, len(sentinel_rows))
        self.assertTrue(
            all(
                row["form"] == "call"
                and row["dispatch"] == "direct"
                and row["identity_kind"] == "direct"
                and row["cleanup_bytes"] is None
                for row in sentinel_rows
            )
        )
        comparison = compare_call_contracts(
            fixture["expected"],
            candidate_contract,
        )
        self.assertFalse(comparison["passed"])
        self.assertEqual(
            {
                "ordinal": len(fixture["expected"]),
                "expected": None,
                "candidate": sentinel_rows[0],
                "kind": "extra",
            },
            comparison["first_divergence"],
        )

    def test_accepts_uniform_caller_size_and_payload_call_shift(self) -> None:
        fixture = self.fixture()
        candidate = fixture["candidate"]
        caller = candidate.caller_definition
        assert caller is not None
        shift = 4
        shifted_payload = tuple(
            parse_assembly(
                "\n".join(
                    (
                        f"{offset + shift:05x} e8 00 00 00 00 "
                        f"call {self.cod_symbol}"
                    )
                    for offset in self.call_offsets
                ),
                source="cod",
            )
        )
        shifted = replace(
            candidate,
            instructions=(
                *(
                    instruction
                    for instruction in candidate.instructions
                    if self.cod_symbol
                    not in instruction.source_line
                ),
                *shifted_payload,
            ),
            caller_definition=replace(
                caller,
                data=b"\x90" * shift + caller.data,
                relocations=tuple(
                    replace(row, offset=row.offset + shift)
                    for row in caller.relocations
                ),
                relocation_mask=(False,) * shift + caller.relocation_mask,
            ),
        )
        self.assertEqual(
            {self.cod_symbol: fixture["caller_identity"]},
            self.bridges(fixture, candidate=shifted),
        )

    def test_rejects_helper_definition_alias_body_and_relocation_drift(
        self,
    ) -> None:
        fixture = self.fixture()
        candidate = fixture["candidate"]
        helper = candidate.tu_local_function_definitions[self.coff_symbol]

        with self.assertRaisesRegex(ValueError, "16-byte"):
            self.bridges(
                fixture,
                candidate=replace(
                    candidate,
                    tu_local_function_definitions={
                        self.coff_symbol: replace(
                            helper,
                            data=b"\x90" + helper.data[1:],
                        )
                    },
                ),
            )

        with self.assertRaisesRegex(ValueError, "16-byte"):
            self.bridges(
                fixture,
                candidate=replace(
                    candidate,
                    tu_local_function_definitions={
                        self.coff_symbol: replace(
                            helper,
                            section_external_functions=(
                                self.coff_symbol,
                                "?Alias@@YAXXZ",
                            ),
                        )
                    },
                ),
            )

        caller = candidate.caller_definition
        assert caller is not None
        with self.assertRaisesRegex(ValueError, "ordered COFF relocation"):
            self.bridges(
                fixture,
                candidate=replace(
                    candidate,
                    caller_definition=replace(
                        caller,
                        relocations=(
                            *caller.relocations,
                            CoffRelocation(
                                offset=0x301,
                                symbol_index=911,
                                type=0x14,
                                symbol_name=self.coff_symbol,
                            ),
                        ),
                    ),
                ),
            )

    def test_rejects_name_topology_and_cleanup_drift(self) -> None:
        fixture = self.fixture()
        candidate = fixture["candidate"]

        malformed = tuple(
            parse_assembly(
                (
                    "0023d e8 00 00 00 00 call "
                    "?HudUiZrdPayload@?_tu_order\\00_hud.cppBAD"
                    "@@YIPAUNode@zReader@@PAU23@@Z"
                ),
                source="cod",
            )
        )[0]
        instructions = list(candidate.instructions)
        first_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.source_line.strip().startswith("0023d ")
        )
        instructions[first_index] = malformed
        with self.assertRaisesRegex(ValueError, "decimal discriminator"):
            self.bridges(
                fixture,
                candidate=replace(
                    candidate,
                    instructions=tuple(instructions),
                ),
            )

        with self.assertRaisesRegex(ValueError, "seven calls"):
            self.bridges(
                fixture,
                candidate=replace(
                    candidate,
                    instructions=tuple(
                        instruction
                        for instruction in candidate.instructions
                        if not instruction.source_line.strip().startswith(
                            "00bc5 "
                        )
                    ),
                ),
            )

        cleanup = tuple(
            parse_assembly(
                "00242 83 c4 04 add esp, 4",
                source="cod",
            )
        )[0]
        instructions = list(candidate.instructions)
        first_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.source_line.strip().startswith("0023d ")
        )
        instructions.insert(first_index + 1, cleanup)
        with self.assertRaisesRegex(ValueError, "callee-cleanup"):
            self.bridges(
                fixture,
                candidate=replace(
                    candidate,
                    instructions=tuple(instructions),
                ),
            )


class HudTripletSortKeyTuLocalIdentityBridgeTests(unittest.TestCase):
    caller_identity = "symbol:recoil:function:0x40d220"
    caller_symbol = (
        "?CompareSortKey@HudUiListMenuEntry@@"
        "YIHPBUHudUiScoreboardEntry@@0@Z"
    )
    cod_symbol = (
        r"?HudUiTripletEntrySortKey@?_tu_order\00_hud.cpp89365816"
        r"@@YIHABUHudUiScoreboardEntry@@@Z"
    )
    coff_symbol = (
        r"?HudUiTripletEntrySortKey@?%_tu_order\00_hud.cpp89365816"
        r"@@YIHABUHudUiScoreboardEntry@@@Z"
    )

    def indexes(self) -> IdentityIndexes:
        return IdentityIndexes(
            by_address={"0x40d220": self.caller_identity},
            by_candidate_name={},
            provider_ids=frozenset(),
            storage_by_address={},
            storage_by_name={},
        )

    def candidate(
        self,
        *,
        second_call_offset: int = 0x10,
        second_relocation_offset: int = 0x11,
        second_relocation_type: int = 0x14,
        defined_external_functions: tuple[str, ...] | None = None,
        second_operand: str | None = None,
    ) -> CandidateAssembly:
        operand = second_operand or self.cod_symbol
        instructions = tuple(
            parse_assembly(
                "\n".join(
                    [
                        f"  00007 e8 00 00 00 00 call {self.cod_symbol}",
                        (
                            f"  {second_call_offset:05x} e8 00 00 00 00 "
                            f"call {operand}"
                        ),
                        "  00015 c3 ret 0",
                    ]
                ),
                source="cod",
            )
        )
        data = bytearray(0x30)
        data[0x07] = 0xE8
        data[second_call_offset] = 0xE8
        relocation_mask = [False] * len(data)
        for offset in (0x08, second_relocation_offset):
            for index in range(offset, offset + 4):
                relocation_mask[index] = True
        return CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=frozenset(),
            caller_definition=CandidateCallerDefinition(
                symbol=self.caller_symbol,
                data=bytes(data),
                relocations=(
                    CoffRelocation(
                        offset=0x08,
                        symbol_index=31,
                        type=0x14,
                        symbol_name=self.coff_symbol,
                    ),
                    CoffRelocation(
                        offset=second_relocation_offset,
                        symbol_index=31,
                        type=second_relocation_type,
                        symbol_name=self.coff_symbol,
                    ),
                ),
                relocation_mask=tuple(relocation_mask),
                undefined_external_functions=(),
                defined_external_functions=(
                    defined_external_functions
                    if defined_external_functions is not None
                    else (self.coff_symbol,)
                ),
            ),
        )

    def bridge(
        self,
        candidate: CandidateAssembly | None = None,
        *,
        caller_identity: str | None = None,
        expected: list[dict[str, object]] | None = None,
    ) -> dict[str, str]:
        return _hud_triplet_sort_key_tu_local_candidate_bridge(
            expected or [],
            candidate or self.candidate(),
            caller_identity=caller_identity or self.caller_identity,
            caller_start="0x40d220",
            caller_end_exclusive="0x40d260",
            indexes=self.indexes(),
            bridge_names={},
        )

    def test_exact_same_object_tu_local_calls_map_to_retail_caller_identity(
        self,
    ) -> None:
        candidate = self.candidate()
        bridges = self.bridge(candidate)
        self.assertEqual(
            {self.cod_symbol: self.caller_identity},
            bridges,
        )
        contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=self.caller_identity,
            caller_start="0x40d220",
            caller_end_exclusive="0x40d260",
            indexes=self.indexes(),
            compiler_generated_bridges=bridges,
        )
        self.assertEqual(2, len(contract))
        self.assertTrue(
            all(
                row["target_identity"] == self.caller_identity
                and row["identity_kind"] == "direct"
                and row["form"] == "call"
                for row in contract
            )
        )
        comparison = compare_call_contracts([], contract)
        self.assertFalse(comparison["passed"])
        self.assertEqual("extra", comparison["first_divergence"]["kind"])

    def test_caller_identity_retail_contract_and_same_object_definition_fail_closed(
        self,
    ) -> None:
        with self.assertRaisesRegex(ValueError, "exact reviewed 0x40d220"):
            self.bridge(caller_identity="symbol:recoil:function:0x40d260")
        with self.assertRaisesRegex(ValueError, "empty retail invocation"):
            self.bridge(
                expected=[
                    {
                        "ordinal": 0,
                        "target_identity": self.caller_identity,
                    }
                ]
            )
        with self.assertRaisesRegex(ValueError, "exactly one same-object"):
            self.bridge(
                self.candidate(
                    defined_external_functions=(
                        self.coff_symbol,
                        self.coff_symbol,
                    )
                )
            )

    def test_signature_call_and_relocation_topology_fail_closed(self) -> None:
        drifted_signature = self.cod_symbol.replace(
            "HudUiScoreboardEntry",
            "HudUiOtherEntry",
        )
        with self.assertRaisesRegex(ValueError, "helper name, 00_hud.cpp TU marker"):
            self.bridge(self.candidate(second_operand=drifted_signature))
        with self.assertRaisesRegex(ValueError, "one exact candidate helper"):
            self.bridge(
                self.candidate(
                    second_operand=self.cod_symbol.replace(
                        "89365816",
                        "59468533",
                    )
                )
            )
        with self.assertRaisesRegex(ValueError, "two-call candidate topology"):
            self.bridge(
                self.candidate(
                    second_call_offset=0x11,
                    second_relocation_offset=0x12,
                )
            )
        with self.assertRaisesRegex(ValueError, "zero-addend fully masked"):
            self.bridge(
                self.candidate(second_relocation_type=0x06)
            )


class HudTripletEnsureCapacityTuLocalIdentityBridgeTests(
    unittest.TestCase
):
    caller_identity = "symbol:recoil:function:0x40e590"
    caller_symbol = (
        "?AddEntry@HudUiTriplet@@QAEXPAUGameNetPlayerRow@@@Z"
    )
    cod_symbol = (
        r"?HudUiTripletEnsureCapacity@?_tu_order\00_hud.cpp683515235"
        r"@@YIXAAUHudUiTripletEntries@@I@Z"
    )
    coff_symbol = (
        r"?HudUiTripletEnsureCapacity@?%_tu_order\00_hud.cpp683515235"
        r"@@YIXAAUHudUiTripletEntries@@I@Z"
    )
    get_count_symbol = "?GetCount@HudUiTripletEntries@@QAEHXZ"
    get_count_identity = "symbol:recoil:function:0x414670"

    def expected(self) -> list[dict[str, object]]:
        return [
            {
                "ordinal": 0,
                "form": "call",
                "dispatch": "direct",
                "identity_kind": "direct",
                "target_identity": "provider:recoil:function:0x4c652c",
                "storage_identity": "",
                "slot_displacement": None,
                "cleanup_bytes": None,
            }
        ]

    def indexes(
        self,
        *,
        by_address: dict[str, str] | None = None,
        by_candidate_name: dict[str, str] | None = None,
        provider_ids: frozenset[str] = frozenset(),
        storage_by_name: dict[str, str] | None = None,
    ) -> IdentityIndexes:
        return IdentityIndexes(
            by_address=(
                by_address
                if by_address is not None
                else {"0x40e590": self.caller_identity}
            ),
            by_candidate_name=by_candidate_name or {},
            provider_ids=provider_ids,
            storage_by_address={},
            storage_by_name=storage_by_name or {},
        )

    def candidate(
        self,
        *,
        operand: str | None = None,
        mnemonic: str = "call",
        opcode: int = 0xE8,
        call_offset: int = 0x60,
        relocations: tuple[CoffRelocation, ...] | None = None,
        relocation_type: int = 0x14,
        relocation_symbol: str | None = None,
        relocation_offset: int = 0x61,
        relocation_addend: int = 0,
        fully_masked: bool = True,
        caller_symbol: str | None = None,
        defined_external_functions: tuple[str, ...] | None = None,
        undefined_external_functions: tuple[str, ...] = (),
        duplicate_call: bool = False,
        get_count_call: bool = False,
    ) -> CandidateAssembly:
        selected_operand = operand or self.cod_symbol
        instruction_lines = []
        if get_count_call:
            instruction_lines.append(
                f"  00056 e8 00 00 00 00 call {self.get_count_symbol}"
            )
        instruction_lines.append(
            (
                f"  {call_offset:05x} {opcode:02x} 00 00 00 00 "
                f"{mnemonic} {selected_operand}"
            )
        )
        if duplicate_call:
            instruction_lines.append(
                f"  00068 e8 00 00 00 00 call {self.cod_symbol}"
            )
        instruction_lines.append("  00070 c3 ret 0")
        instructions = tuple(
            parse_assembly(
                "\n".join(instruction_lines),
                source="cod",
            )
        )
        data = bytearray(0x80)
        if get_count_call:
            data[0x56] = 0xE8
        data[call_offset] = opcode
        struct.pack_into("<I", data, relocation_offset, relocation_addend)
        relocation_mask = [False] * len(data)
        if get_count_call:
            for index in range(0x57, 0x5B):
                relocation_mask[index] = True
        if fully_masked:
            for index in range(relocation_offset, relocation_offset + 4):
                relocation_mask[index] = True
        selected_relocations = (
            relocations
            if relocations is not None
            else tuple(
                (
                    [
                        CoffRelocation(
                            offset=0x57,
                            symbol_index=40,
                            type=0x14,
                            symbol_name=self.get_count_symbol,
                        )
                    ]
                    if get_count_call
                    else []
                )
                + [
                    CoffRelocation(
                        offset=relocation_offset,
                        symbol_index=41,
                        type=relocation_type,
                        symbol_name=relocation_symbol or self.coff_symbol,
                    )
                ]
            )
        )
        return CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=frozenset(),
            caller_definition=CandidateCallerDefinition(
                symbol=caller_symbol or self.caller_symbol,
                data=bytes(data),
                relocations=selected_relocations,
                relocation_mask=tuple(relocation_mask),
                undefined_external_functions=undefined_external_functions,
                defined_external_functions=(
                    defined_external_functions
                    if defined_external_functions is not None
                    else (
                        (
                            self.get_count_symbol,
                            self.coff_symbol,
                        )
                        if get_count_call
                        else (self.coff_symbol,)
                    )
                ),
            ),
        )

    def bridge(
        self,
        candidate: CandidateAssembly | None = None,
        *,
        expected: list[dict[str, object]] | None = None,
        caller_identity: str | None = None,
        caller_start: str = "0x40e590",
        caller_end_exclusive: str = "0x40e800",
        indexes: IdentityIndexes | None = None,
        bridge_names: dict[str, object] | None = None,
        compiler_generated_bridges: dict[str, str] | None = None,
    ) -> dict[str, str]:
        return _hud_triplet_ensure_capacity_tu_local_candidate_bridge(
            self.expected() if expected is None else expected,
            candidate or self.candidate(),
            caller_identity=caller_identity or self.caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
            indexes=indexes or self.indexes(),
            bridge_names=bridge_names or {},
            compiler_generated_bridges=compiler_generated_bridges or {},
        )

    def test_exact_same_object_helper_maps_to_comparison_sentinel(
        self,
    ) -> None:
        candidate = self.candidate()
        bridges = self.bridge(candidate)
        self.assertEqual(
            {self.cod_symbol: self.caller_identity},
            bridges,
        )
        contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=self.caller_identity,
            caller_start="0x40e590",
            caller_end_exclusive="0x40e800",
            indexes=self.indexes(),
            compiler_generated_bridges=bridges,
        )
        self.assertEqual(
            [
                {
                    "ordinal": 0,
                    "form": "call",
                    "dispatch": "direct",
                    "identity_kind": "direct",
                    "target_identity": self.caller_identity,
                    "storage_identity": "",
                    "slot_displacement": None,
                    "cleanup_bytes": None,
                }
            ],
            contract,
        )
        comparison = compare_call_contracts(self.expected(), contract)
        self.assertFalse(comparison["passed"])
        self.assertEqual(
            "mismatch",
            comparison["first_divergence"]["kind"],
        )
        self.assertEqual(
            self.caller_identity,
            comparison["first_divergence"]["candidate"][
                "target_identity"
            ],
        )

