        data = bytearray(caller.data)
        data[0x86] ^= 1
        with self.assertRaisesRegex(ValueError, "complete 0x650"):
            self.next_world_bridge(
                candidate=replace(
                    candidate,
                    caller_definition=replace(caller, data=bytes(data)),
                )
            )

        relocations = list(caller.relocations)
        relocation_index = next(
            index
            for index, relocation in enumerate(relocations)
            if relocation.offset == 0x89
        )
        relocations[relocation_index] = replace(
            relocations[relocation_index],
            type=0x06,
        )
        with self.assertRaisesRegex(ValueError, "ordered 105-row"):
            self.next_world_bridge(
                candidate=replace(
                    candidate,
                    caller_definition=replace(
                        caller,
                        relocations=tuple(relocations),
                    ),
                )
            )

        mask = list(caller.relocation_mask)
        mask[0x89] = False
        with self.assertRaisesRegex(ValueError, "relocation mask"):
            self.next_world_bridge(
                candidate=replace(
                    candidate,
                    caller_definition=replace(
                        caller,
                        relocation_mask=tuple(mask),
                    ),
                )
            )

        instructions = list(candidate.instructions)
        cod_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.source_line.startswith("0008d ")
        )
        instructions[cod_index] = replace(
            instructions[cod_index],
            source_line=instructions[cod_index].source_line.replace(
                "0008d ", "0008e ", 1
            ),
        )
        with self.assertRaisesRegex(ValueError, "394-instruction"):
            self.next_world_bridge(
                candidate=replace(candidate, instructions=tuple(instructions))
            )

