    def test_prev_world_retail_row_signature_and_vtable_fail_closed(
        self,
    ) -> None:
        expected = self.expected()
        expected[6]["target_identity"] = self.cycle_identity
        with self.assertRaisesRegex(ValueError, "immutable retail ordinal-6"):
            self.prev_world_bridge(expected=expected)

        candidate = self.candidate()
        instructions = list(candidate.instructions)
        call_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.source_line.startswith("000a0 ")
        )
        wrong_symbol = "??0HudUiZrdWidget@@QAE@H@Z"
        instructions[call_index] = replace(
            instructions[call_index],
            text=f"call {wrong_symbol}",
            raw_text=f"call {wrong_symbol}",
        )
        with self.assertRaisesRegex(ValueError, "zero-argument.*signature"):
            self.prev_world_bridge(
                candidate=replace(candidate, instructions=tuple(instructions))
            )

        instructions = list(candidate.instructions)
        vftable_index = next(
            index
            for index, instruction in enumerate(instructions)
            if instruction.source_line.startswith("000a5 ")
        )
        instructions[vftable_index] = replace(
            instructions[vftable_index],
            text="mov DWORD PTR [ebx], OFFSET FLAT:??_7Wrong@@6B@",
            raw_text="mov DWORD PTR [ebx], OFFSET FLAT:??_7Wrong@@6B@",
        )
        with self.assertRaisesRegex(ValueError, "derived-vftable COD topology"):
            self.prev_world_bridge(
                candidate=replace(candidate, instructions=tuple(instructions))
            )

        expected = self.expected()
