        definitions = dict(candidate.numeric_constructor_definitions)
        definitions[self.numeric_wrapper_symbol] = replace(
            wrapper,
            relocations=(
                replace(
                    wrapper.relocations[0],
                    symbol_name=self.base_symbol,
                ),
            ),
        )
        with self.assertRaisesRegex(ValueError, "sole direct delegation"):
            self.numeric_bridge(
                candidate=replace(
                    candidate,
                    numeric_constructor_definitions=definitions,
                )
            )

        instructions = list(wrapper.instructions)
        instructions[4] = replace(
            instructions[4],
            text=f"jmp {self.numeric_symbol}",
            raw_text=f"jmp {self.numeric_symbol}",
        )
        definitions = dict(candidate.numeric_constructor_definitions)
        definitions[self.numeric_wrapper_symbol] = replace(
            wrapper,
            instructions=tuple(instructions),
        )
        with self.assertRaisesRegex(ValueError, "sole direct delegation"):
            self.numeric_bridge(
                candidate=replace(
                    candidate,
                    numeric_constructor_definitions=definitions,
                )
            )

        instructions = list(wrapper.instructions)
        instructions.append(
            Instruction(
                text=f"call {self.numeric_symbol}",
                raw_text=f"call {self.numeric_symbol}",
                bytes=(),
                source_line=f"00010 call {self.numeric_symbol}",
            )
        )
        definitions = dict(candidate.numeric_constructor_definitions)
        definitions[self.numeric_wrapper_symbol] = replace(
            wrapper,
            instructions=tuple(instructions),
        )
        with self.assertRaisesRegex(ValueError, "sole direct delegation"):
            self.numeric_bridge(
                candidate=replace(
                    candidate,
                    numeric_constructor_definitions=definitions,
                )
            )

