    def test_member_expected_contract_is_independent_and_exact(self) -> None:
        cases = {
            "ordinal": [{**self.member_expected()[0], "ordinal": 5}],
            "storage": [
                {
                    **self.member_expected()[0],
                    "storage_identity": (
                        "load(storage:recoil:data:0x4ed718+0x1b4)"
                    ),
                }
            ],
            "slot": [
                {
                    **self.member_expected()[0],
                    "slot_displacement": 0x64,
                }
            ],
        }
        for name, expected in cases.items():
            with self.subTest(name=name):
                with self.assertRaisesRegex(
                    ValueError,
                    "independently retail-derived",
                ):
                    self.member_bridges(expected=expected)

    def test_member_clobber_wrong_receiver_and_alternate_path_fail(self) -> None:
        cases = {
            "ebx-clobber": self.member_instructions(
                extra_before_load="  00098 31 db xor ebx, ebx"
            ),
            "edx-clobber": self.member_instructions(
                load="  000a4 31 d2 xor edx, edx"
            ),
            "wrong-receiver": self.member_instructions(
                receiver="  000a6 8b ce mov ecx, esi"
            ),
            "alternate-path": self.member_instructions(
                extra_before_load="  00098 75 0a jne $Lload"
            ),
        }
        for name, instructions in cases.items():
            with self.subTest(name=name):
                with self.assertRaisesRegex(
                    ValueError,
                    "instruction bytes|reaching|receiver|alternate",
                ):
                    self.member_bridges(
                        candidate=self.member_candidate(
                            instructions=instructions
                        )
                    )

    def test_member_alias_indexed_duplicate_and_unused_fail(self) -> None:
        exact_candidate = self.member_candidate()
        bridges = self.member_bridges(candidate=exact_candidate)
        indexed = self.member_candidate(
            instructions=self.member_instructions(
                call=(
                    "  000a8 ff 54 8a 68 "
                    "call dword ptr [edx+ecx*4+104]"
                )
            )
        )
        alias = self.member_candidate(
            instructions=self.member_instructions(
                receiver="  000a6 8b c2 mov eax, edx",
                call="  000a8 ff 50 68 call dword ptr [eax+104]",
            )
        )
        for name, candidate in {
            "indexed": indexed,
            "alias": alias,
        }.items():
            with self.subTest(name=name):
                with self.assertRaisesRegex(
                    ValueError,
                    "member-vptr storage bridge|register storage",
                ):
                    self.member_extract(candidate, bridges)
        duplicate = self.member_candidate(
            instructions=(
                *self.member_instructions(),
                *parse_assembly(
                    "  000a4 8b 13 mov edx, dword ptr [ebx]",
                    source="cod",
                ),
            )
        )
        with self.assertRaisesRegex(ValueError, "unique instructions"):
            self.member_bridges(candidate=duplicate)
        with self.assertRaisesRegex(
            ValueError,
            "unused reviewed member-vptr",
        ):
            extract_invocation_contract(
                tuple(
                    parse_assembly(
                        "  00000 c3 ret 0",
                        source="cod",
                    )
                ),
                source="cod",
                caller_identity=self.caller_identity,
                caller_start="0x40f2e0",
                caller_end_exclusive="0x40f3e0",
                indexes=self.member_indexes(),
                reviewed_member_vptr_storage_bridges=bridges,
            )

    def test_member_direct_call_relocation_and_identity_drift_fail(self) -> None:
        exact = self.member_candidate().caller_definition
        self.assertIsNotNone(exact)
        assert exact is not None
        relocation = exact.relocations[0]
        addend = bytearray(exact.data)
        addend[0xA0:0xA4] = struct.pack("<I", 4)
        mask = list(exact.relocation_mask)
        mask[0xA2] = False
        cases = {
            "symbol": self.member_candidate(
                relocations=(
                    replace(relocation, symbol_name="?Other@@YAXXZ"),
                )
            ),
            "type": self.member_candidate(
                relocations=(replace(relocation, type=0x06),)
            ),
            "offset": self.member_candidate(
                relocations=(replace(relocation, offset=0xA1),)
            ),
            "duplicate": self.member_candidate(
                relocations=(relocation, relocation)
            ),
            "addend": self.member_candidate(data=bytes(addend)),
            "mask": self.member_candidate(relocation_mask=tuple(mask)),
            "ambiguous-symbol": self.member_candidate(
                defined_external_functions=(self.apply_image_symbol,)
            ),
        }
        for name, candidate in cases.items():
            with self.subTest(name=name):
                with self.assertRaisesRegex(
                    ValueError,
                    "REL32|candidate identity|relocation-free",
                ):
                    self.member_bridges(candidate=candidate)

