    def test_tracker_alias_owner_provider_and_index_conflicts_fail(self) -> None:
        def alias(data: dict) -> None:
            data["symbols"]["recoil:data:0x4ed718"][
                "logical_aliases"
            ] = ["recoil:data:alias"]

        def provider(data: dict) -> None:
            data["owners"][self.owner_id]["provider_state"] = "accepted"

        cases = {
            "alias": (
                self.document(alias),
                self.indexes(),
            ),
            "provider": (
                self.document(provider),
                self.indexes(),
            ),
            "index": (
                self.document(),
                self.indexes(
                    storage_by_address={
                        "0x4ed718": "storage:recoil:data:0x4ed000"
                    }
                ),
            ),
            "provider-index": (
                self.document(),
                self.indexes(
                    provider_ids=frozenset({self.storage_identity})
                ),
            ),
        }
        for name, (document, indexes) in cases.items():
            with self.subTest(name=name):
                with self.assertRaisesRegex(
                    ValueError,
                    "tracker|storage identity",
                ):
                    self.bridges(document=document, indexes=indexes)

    def test_clobber_and_second_definition_fail_closed(self) -> None:
        cases = {
            "clobber": self.instructions(
                between="  00018 31 c0 xor eax, eax"
            ),
            "second-definition": self.instructions(
                between="  00018 8b c3 mov eax, ebx"
            ),
        }
        for name, instructions in cases.items():
            with self.subTest(name=name):
                candidate = self.candidate(instructions=instructions)
                with self.assertRaisesRegex(
                    ValueError,
                    "unresolved indirect register (?:storage|provenance) eax",
                ):
                    self.extract(candidate, self.bridges(candidate=candidate))

    def test_cfg_path_bypassing_load_merges_to_unresolved(self) -> None:
        candidate = self.candidate(
            instructions=self.instructions(
                prefix="  00000 74 1d je $Lcall",
            )
        )
        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register storage eax",
        ):
            self.extract(candidate, self.bridges(candidate=candidate))

    def test_indexed_and_aliased_invocations_fail_closed(self) -> None:
        bridge = {
            "0x13": ReviewedAbsoluteStorageLoadBridge(
                register="eax",
                aggregate_symbol=self.aggregate_symbol,
                displacement=0x1B4,
                access_width=4,
                storage_identity=self.storage_identity,
            )
        }
        cases = {
            "indexed": self.instructions(
                call=(
                    "  0001f ff 54 88 64 "
                    "call dword ptr [eax+ecx*4+100]"
                )
            ),
            "alias": self.instructions(
                between="  00018 8b d0 mov edx, eax",
                call="  0001f ff 52 64 call dword ptr [edx+100]",
            ),
        }
        for name, instructions in cases.items():
            with self.subTest(name=name):
                candidate = self.candidate(instructions=instructions)
                register = "eax" if name == "indexed" else "edx"
                with self.assertRaisesRegex(
                    ValueError,
                    f"unresolved indirect register storage {register}",
                ):
                    self.extract(candidate, bridge)


