    def test_candidate_later_independent_direct_constructors_are_allowed(
        self,
    ) -> None:
        exact = self.candidate().caller_definition
        self.assertIsNotNone(exact)
        assert exact is not None
        later_call = tuple(
            parse_assembly(
                (
                    "  00104 e8 00 00 00 00 call "
                    f"{self.direct_constructor_symbol}"
                ),
                source="cod",
            )
        )
        body = bytearray(exact.data)
        body[0x104:0x109] = b"\xe8\x00\x00\x00\x00"
        mask = list(exact.relocation_mask)
        for index in range(0x105, 0x109):
            mask[index] = True
        candidate = self.candidate(
            instructions=(
                *self.candidate_instructions(),
                *later_call,
            ),
            data=bytes(body),
            relocation_mask=tuple(mask),
            relocations=(
                *exact.relocations,
                CoffRelocation(
                    offset=0x105,
                    symbol_index=900,
                    type=0x14,
                    symbol_name=self.direct_constructor_symbol,
                ),
            ),
            undefined_external_functions=(
                self.array_constructor_symbol,
                self.add_child_symbol,
                self.direct_constructor_symbol,
            ),
        )
        self.assertEqual(
            self.candidate_bridges(),
            self.candidate_bridges(candidate),
        )

