    @staticmethod
    def instructions(
        rows: Sequence[str],
        *,
        source: str,
    ) -> tuple:
        return tuple(parse_assembly("\n".join(rows), source=source))

    def candidate(
        self,
        *,
        rows: Sequence[str] | None = None,
        relocations: tuple[CoffRelocation, ...] | None = None,
        local_control_flow_indices: frozenset[int] = frozenset(),
    ) -> CandidateAssembly:
        instructions = self.instructions(
            rows or self.candidate_rows,
            source="cod",
        )
        body = bytearray(0x90)
        for instruction in instructions:
            match = re.match(r"^\s*([0-9a-fA-F]+)", instruction.source_line)
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(int(value, 16) for value in instruction.bytes)
            body[offset : offset + len(encoded)] = encoded
        mask = [False] * len(body)
        for offset in (0x12, 0x1B, 0x3F, 0x68, 0x70, 0x76):
            mask[offset : offset + 4] = [True] * 4
        return CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=local_control_flow_indices,
            local_control_flow_targets={},
            caller_definition=CandidateCallerDefinition(
                symbol=self.caller_symbol,
                data=bytes(body),
                relocations=(
                    relocations
                    if relocations is not None
                    else (
                        CoffRelocation(
                            offset=0x12,
                            symbol_index=1,
                            type=0x06,
                            symbol_name=self.aggregate_symbol,
                        ),
                        CoffRelocation(
                            offset=0x1B,
                            symbol_index=1,
                            type=0x06,
                            symbol_name=self.aggregate_symbol,
                        ),
                        CoffRelocation(
                            offset=0x3F,
                            symbol_index=2,
                            type=0x06,
                            symbol_name=self.token_symbol,
                        ),
                        CoffRelocation(
                            offset=0x68,
                            symbol_index=3,
                            type=0x06,
                            symbol_name="__imp__ceil",
                        ),
                        CoffRelocation(
                            offset=0x70,
                            symbol_index=4,
                            type=0x14,
                            symbol_name="__ftol",
                        ),
                        CoffRelocation(
                            offset=0x76,
                            symbol_index=5,
                            type=0x06,
                            symbol_name="??_C@_02MECO@?$CFd?$AA@",
                        ),
                    )
                ),
                relocation_mask=tuple(mask),
                undefined_external_functions=("__imp__ceil", "__ftol"),
                undefined_external_data=(
                    self.aggregate_symbol,
                    self.token_symbol,
                ),
                defined_external_data=("??_C@_02MECO@?$CFd?$AA@",),
            ),
        )

