    def candidate(
        self,
        *,
        rows: Sequence[str] | None = None,
        relocations: tuple[CoffRelocation, ...] | None = None,
        relocation_mask: tuple[bool, ...] | None = None,
        target: SimpleNamespace | None = None,
        undefined_external_functions: tuple[str, ...] | None = None,
        undefined_external_data: tuple[str, ...] | None = None,
        defined_external_data: tuple[str, ...] | None = None,
    ) -> CandidateAssembly:
        instructions = self.instructions(
            rows or self.candidate_rows,
            source="cod",
        )
        body = bytearray(0x50)
        for instruction in instructions:
            match = re.match(
                r"^\s*([0-9a-fA-F]+)",
                instruction.source_line,
            )
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(int(value, 16) for value in instruction.bytes)
            body[offset : offset + len(encoded)] = encoded
        mask = [False] * len(body)
        for offset in (0x12, 0x19, 0x26, 0x37):
            mask[offset : offset + 4] = [True] * 4
        return CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
            target=target or self.target(),
            caller_definition=CandidateCallerDefinition(
                symbol=self.caller_symbol,
                data=bytes(body),
                relocations=(
                    relocations
                    if relocations is not None
                    else (
                        CoffRelocation(
                            offset=0x12,
                            symbol_index=1,
                            type=0x06,
                            symbol_name=self.aggregate_symbol,
                        ),
                        CoffRelocation(
                            offset=0x19,
                            symbol_index=2,
                            type=0x14,
                            symbol_name=self.direct_symbol,
                        ),
                        CoffRelocation(
                            offset=0x26,
                            symbol_index=2,
                            type=0x14,
                            symbol_name=self.direct_symbol,
                        ),
                        CoffRelocation(
                            offset=0x37,
                            symbol_index=3,
                            type=0x06,
                            symbol_name=self.literal_symbol,
                        ),
                    )
                ),
                relocation_mask=(
                    relocation_mask
                    if relocation_mask is not None
                    else tuple(mask)
                ),
                undefined_external_functions=(
                    undefined_external_functions
                    if undefined_external_functions is not None
                    else (self.direct_symbol,)
                ),
                undefined_external_data=(
                    undefined_external_data
                    if undefined_external_data is not None
                    else (self.aggregate_symbol,)
                ),
                defined_external_data=(
                    defined_external_data
                    if defined_external_data is not None
                    else (self.literal_symbol,)
                ),
            ),
        )

    def bridges(self, **overrides: object):
        arguments = {
            "retail_instructions": self.instructions(
                self.retail_rows,
                source="bn",
            ),
            "candidate": self.candidate(),
            "document": self.document(),
            "caller_identity": self.caller_identity,
            "caller_start": "0x4127d0",
            "caller_end_exclusive": "0x412820",
            "indexes": self.indexes(),
            "bridge_names": {
                "HudUiWidget::SetImageBorrowedAndInvalidate": (
                    SimpleNamespace(address="0x4b3e70")
                ),
            },
        }
        arguments.update(overrides)
        return _hud_ui_message_clear_display_vptr_bridges(**arguments)

    def test_independent_contracts_reveal_exact_panel_mismatch(self) -> None:
        candidate = self.candidate()
        retail_bridges, candidate_bridges = self.bridges(
            candidate=candidate
        )
        self.assertEqual(
            {"0x41280c", "0x412816"},
            set(retail_bridges),
        )
        self.assertEqual({"0x3b", "0x45"}, set(candidate_bridges))
        self.assertEqual(
            self.panel_storage_identity,
            retail_bridges["0x41280c"].storage_identity,
        )
        self.assertEqual(
            self.panel_storage_identity,
            candidate_bridges["0x3b"].storage_identity,
        )
        self.assertEqual(
            self.message_vptr_identity,
            retail_bridges["0x412816"].storage_identity,
        )
        self.assertEqual(
            self.message_vptr_identity,
            candidate_bridges["0x45"].storage_identity,
        )
        expected = extract_invocation_contract(
            self.instructions(self.retail_rows, source="bn"),
            source="bn",
            caller_identity=self.caller_identity,
            caller_start="0x4127d0",
            caller_end_exclusive="0x412820",
            indexes=self.indexes(),
            reviewed_loop_vptr_storage_bridges=retail_bridges,
        )
        actual = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=self.caller_identity,
            caller_start="0x4127d0",
            caller_end_exclusive="0x412820",
            indexes=self.indexes(),
            reviewed_loop_vptr_storage_bridges=candidate_bridges,
        )
        comparison = compare_call_contracts(expected, actual)
        self.assertFalse(comparison["passed"])
        self.assertEqual(
            {
                "ordinal": 2,
                "expected": {
                    "ordinal": 2,
                    "form": "call",
                    "dispatch": "indirect",
                    "identity_kind": "virtual-slot",
                    "target_identity": "",
                    "storage_identity": self.panel_storage_identity,
                    "slot_displacement": 0x74,
                    "cleanup_bytes": 8,
                },
                "candidate": {
                    "ordinal": 2,
                    "form": "call",
                    "dispatch": "indirect",
                    "identity_kind": "virtual-slot",
                    "target_identity": "",
                    "storage_identity": self.panel_storage_identity,
                    "slot_displacement": 0x8C,
                    "cleanup_bytes": None,
                },
                "kind": "mismatch",
            },
            comparison["first_divergence"],
        )
        self.assertEqual(
            expected[:2],
            actual[:2],
        )
        self.assertEqual(
            expected[3],
            actual[3],
        )

    def test_corrected_settextfmt_candidate_passes_exact_contract(self) -> None:
        candidate = self.candidate(rows=self.corrected_candidate_rows)
        retail_bridges, candidate_bridges = self.bridges(
            candidate=candidate
        )
        self.assertEqual(
            {"0x41280c", "0x412816"},
            set(retail_bridges),
        )
        self.assertEqual({"0x3c", "0x46"}, set(candidate_bridges))
        self.assertEqual(
            self.panel_storage_identity,
            candidate_bridges["0x3c"].storage_identity,
        )
        self.assertEqual(0x74, candidate_bridges["0x3c"].slot_displacement)
        self.assertEqual(
            self.message_vptr_identity,
            candidate_bridges["0x46"].storage_identity,
        )
        expected = extract_invocation_contract(
            self.instructions(self.retail_rows, source="bn"),
            source="bn",
            caller_identity=self.caller_identity,
            caller_start="0x4127d0",
            caller_end_exclusive="0x412820",
            indexes=self.indexes(),
            reviewed_loop_vptr_storage_bridges=retail_bridges,
        )
        actual = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=self.caller_identity,
            caller_start="0x4127d0",
            caller_end_exclusive="0x412820",
            indexes=self.indexes(),
            reviewed_loop_vptr_storage_bridges=candidate_bridges,
        )
        comparison = compare_call_contracts(expected, actual)
        self.assertTrue(comparison["passed"])
        self.assertEqual(expected, actual)

    def test_rejection_matrix_fails_closed(self) -> None:
        exact_candidate = self.candidate()
        caller = exact_candidate.caller_definition
        assert caller is not None

        def retail_with(old: str, new: str) -> tuple:
            rows = list(self.retail_rows)
            rows[rows.index(old)] = new
            return self.instructions(rows, source="bn")

        def candidate_with(old: str, new: str) -> CandidateAssembly:
            rows = list(self.candidate_rows)
            rows[rows.index(old)] = new
            return self.candidate(rows=rows)

        wrong_direct_relocations = tuple(
            (
                replace(row, symbol_name="?Wrong@@YAXXZ")
                if row.offset == 0x19
                else row
            )
            for row in caller.relocations
        )
        wrong_literal_relocations = tuple(
            (
                replace(row, type=0x14)
                if row.offset == 0x37
                else row
            )
            for row in caller.relocations
        )
        wrong_mask = list(caller.relocation_mask)
        wrong_mask[0x38] = False
        wrong_document_data = deepcopy(self.document().data)
        wrong_document_data["symbols"]["recoil:data:0x4e5ce0"][
            "disposition"
        ] = "authored"
