    def test_corrected_candidate_rejects_coff_topology_and_class_drift(
        self,
    ) -> None:
        exact = self.candidate(corrected=True)
        caller = exact.caller_definition
        assert caller is not None

        wrong_relocations = tuple(
            replace(row, symbol_name="?Wrong@@YAXXZ")
            if row.offset == 0x1FD
            else row
            for row in caller.relocations
        )
        wrong_addend_data = bytearray(caller.data)
        struct.pack_into("<I", wrong_addend_data, 0x227, 0x4E9D)
        wrong_mask = list(caller.relocation_mask)
        wrong_mask[0x254] = False
        extra_terminal_rows = (
            *self.corrected_candidate_rows,
            "002ae c2 04 00 retn 4",
        )
        wrong_call_rows = list(self.corrected_candidate_rows)
        wrong_call_rows[wrong_call_rows.index(
            "001fc e8 00 00 00 00 call " + self.set_image_symbol
        )] = "001fc e8 00 00 00 00 call ?Wrong@@YAXXZ"
        cases = {
            "ninth-image-target": (
                {
                    "candidate": self.candidate(
                        corrected=True,
                        rows=tuple(wrong_call_rows),
                    )
                },
                "unresolved cod decorated call target",
            ),
            "relocation-identity": (
                {
                    "candidate": replace(
                        exact,
                        caller_definition=replace(
                            caller,
                            relocations=wrong_relocations,
                        ),
                    )
                },
                "COFF relocation identity/type/addend/mask",
            ),
            "relocation-addend": (
                {
                    "candidate": replace(
                        exact,
                        caller_definition=replace(
                            caller,
                            data=bytes(wrong_addend_data),
                        ),
                    )
                },
                "COFF relocation identity/type/addend/mask",
            ),
            "relocation-mask": (
                {
                    "candidate": replace(
                        exact,
                        caller_definition=replace(
                            caller,
                            relocation_mask=tuple(wrong_mask),
                        ),
                    )
                },
                "COFF relocation identity/type/addend/mask",
            ),
            "external-class": (
                {
                    "candidate": replace(
                        exact,
                        caller_definition=replace(
                            caller,
                            undefined_external_functions=(
                                "__ftol",
                                "__imp__ceil",
                            ),
                            defined_external_functions=(
                                self.set_image_symbol,
                            ),
                        ),
                    )
                },
                "external function/data symbol-class",
            ),
            "local-static": (
                {
                    "candidate": replace(
                        exact,
                        caller_definition=replace(
                            caller,
                            local_static_definitions=(
                                replace(
                                    caller.local_static_definitions[0],
                                    name="$T88364",
                                ),
                                caller.local_static_definitions[1],
                            ),
                        ),
                    )
                },
                "local-static",
            ),
            "terminal-census": (
                {
                    "candidate": self.candidate(
                        corrected=True,
                        rows=extra_terminal_rows,
                    )
                },
                "terminal census",
            ),
        }
        for name, (overrides, message) in cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                message,
            ):
                self.bridges(**overrides)

