    def test_retail_shaped_candidate_rejects_clear_float_semantic_drift(
        self,
    ) -> None:
        shifted_symbol = "_kHudUiMessageClearSpecialTokenValue$S83572"
        exact = self.candidate(
            retail_shaped=True,
            retail_shaped_clear_float_symbol=shifted_symbol,
        )
        caller = exact.caller_definition
        assert caller is not None

        def replace_clear_relocations(
            *,
            first_name: str = shifted_symbol,
            second_name: str = shifted_symbol,
            first_type: int = 0x06,
        ) -> tuple[CoffRelocation, ...]:
            return tuple(
                replace(
                    row,
                    symbol_name=(
                        first_name if row.offset == 0x1A9 else second_name
                    ),
                    type=(first_type if row.offset == 0x1A9 else row.type),
                )
                if row.offset in {0x1A9, 0x2B4}
                else row
                for row in caller.relocations
            )

        clear_local = caller.local_static_definitions[1]
        wrong_addend = bytearray(caller.data)
        struct.pack_into("<I", wrong_addend, 0x2B4, 1)
        wrong_mask = list(caller.relocation_mask)
        wrong_mask[0x1A9] = False
        cases = {
            "wrong-basename": replace(
                caller,
                relocations=replace_clear_relocations(
                    first_name="_kHudUiMessageOtherValue$S83572",
                    second_name="_kHudUiMessageOtherValue$S83572",
                ),
                local_static_definitions=(
                    caller.local_static_definitions[0],
                    replace(clear_local, name="_kHudUiMessageOtherValue$S83572"),
                ),
            ),
            "nonnumeric-private-suffix": replace(
                caller,
                relocations=replace_clear_relocations(
                    first_name=(
                        "_kHudUiMessageClearSpecialTokenValue$S83572_tail"
                    ),
                    second_name=(
                        "_kHudUiMessageClearSpecialTokenValue$S83572_tail"
                    ),
                ),
                local_static_definitions=(
                    caller.local_static_definitions[0],
                    replace(
                        clear_local,
                        name=(
                            "_kHudUiMessageClearSpecialTokenValue$S83572_tail"
                        ),
                    ),
                ),
            ),
            "split-private-alias": replace(
                caller,
                relocations=replace_clear_relocations(
                    second_name="_kHudUiMessageClearSpecialTokenValue$S83573"
                ),
            ),
            "extra-semantic-local": replace(
                caller,
                local_static_definitions=(
                    *caller.local_static_definitions,
                    replace(
                        clear_local,
                        name="_kHudUiMessageClearSpecialTokenValue$S83573",
                    ),
                ),
            ),
            "extra-semantic-relocation": replace(
                caller,
                relocations=tuple(
                    replace(row, symbol_name=shifted_symbol)
                    if row.offset == 0x17
                    else row
                    for row in caller.relocations
                ),
            ),
            "section": replace(
                caller,
                local_static_definitions=(
                    caller.local_static_definitions[0],
                    replace(clear_local, section_name=".data"),
                ),
            ),
            "storage-class": replace(
                caller,
                local_static_definitions=(
                    caller.local_static_definitions[0],
                    replace(clear_local, storage_class=2),
                ),
            ),
            "local-data": replace(
                caller,
                local_static_definitions=(
                    caller.local_static_definitions[0],
                    replace(clear_local, data=b"\x00\x00\x00\x00"),
                ),
            ),
            "external-collision": replace(
                caller,
                undefined_external_data=(
                    *caller.undefined_external_data,
                    shifted_symbol,
                ),
            ),
            "relocation-type": replace(
                caller,
                relocations=replace_clear_relocations(first_type=0x14),
            ),
            "relocation-addend": replace(caller, data=bytes(wrong_addend)),
            "relocation-mask": replace(
                caller,
                relocation_mask=tuple(wrong_mask),
            ),
        }
        for name, changed_caller in cases.items():
            with self.subTest(name=name), self.assertRaisesRegex(
                ValueError,
                "ClearSpecialToken constant semantic identity",
            ):
                self.bridges(
                    candidate=replace(
                        exact,
                        caller_definition=changed_caller,
                    )
                )

