    def indexes(self, **changes: object) -> IdentityIndexes:
        by_address = {"0x414550": self.caller_identity}
        by_candidate_name = {}
        for address, name in self.direct_calls:
            identity = f"symbol:recoil:function:{address}"
            by_address[address] = identity
            by_candidate_name[name] = identity
        values: dict[str, object] = {
            "by_address": by_address,
            "by_candidate_name": by_candidate_name,
            "provider_ids": frozenset(),
            "storage_by_address": {"0x4e5ed0": self.aggregate_identity},
            "storage_by_name": {},
            "storage_containers": (
                StorageContainer(
                    start=0x4E5ED0,
                    end_exclusive=0x4ED714,
                    identity=self.aggregate_identity,
                ),
            ),
        }
        values.update(changes)
        return IdentityIndexes(**values)

    def definition(self) -> CandidateCallerDefinition:
        relocations = (
            CoffRelocation(0x01, 1, 0x14, self.direct_calls[0][1]),
            CoffRelocation(0x0C, 2, 0x06, self.aggregate_symbol),
            CoffRelocation(0x11, 3, 0x14, self.direct_calls[1][1]),
            CoffRelocation(0x16, 2, 0x06, self.aggregate_symbol),
            CoffRelocation(0x1B, 2, 0x06, self.aggregate_symbol),
            CoffRelocation(0x22, 4, 0x14, self.direct_calls[2][1]),
            CoffRelocation(0x28, 2, 0x06, self.aggregate_symbol),
        )
        mask = [False] * len(self.candidate_code)
        for row in relocations:
            mask[row.offset : row.offset + 4] = [True] * 4
        return CandidateCallerDefinition(
            symbol=self.caller_symbol,
            data=self.candidate_code,
            relocations=relocations,
            relocation_mask=tuple(mask),
            undefined_external_functions=tuple(name for _address, name in self.direct_calls),
            undefined_external_data=(self.aggregate_symbol,),
        )

    def candidate(
        self,
        *,
        instructions: tuple[Instruction, ...] | None = None,
        definition: CandidateCallerDefinition | None = None,
        target: SimpleNamespace | None = None,
    ) -> CandidateAssembly:
        return CandidateAssembly(
            instructions=instructions or self.candidate_instructions(),
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
            target=target or self.target(),
            caller_definition=definition or self.definition(),
        )

