    def test_candidate_body_relocation_external_and_collision_fail_closed(self) -> None:
        definition = self.definition()
        wrong_body = bytearray(definition.data)
        wrong_body[0x30] ^= 1
        wrong_type = tuple(
            replace(row, type=0x14) if row.offset == 0x16 else row
            for row in definition.relocations
        )
        duplicate = definition.relocations + (definition.relocations[1],)
        wrong_mask = list(definition.relocation_mask)
        wrong_mask[0x17] = False
        cases = {
            "body": replace(definition, data=bytes(wrong_body)),
            "type": replace(definition, relocations=wrong_type),
            "duplicate": replace(definition, relocations=duplicate),
            "mask": replace(definition, relocation_mask=tuple(wrong_mask)),
            "external": replace(
                definition,
                undefined_external_data=(),
                defined_external_data=(self.aggregate_symbol,),
            ),
        }
        for label, changed in cases.items():
            fixture = self.fixture()
            fixture["candidate"] = self.candidate(definition=changed)
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "object symbol/body|seven candidate"
            ):
                self.prove(fixture)

        fixture = self.fixture()
        fixture["indexes"] = self.indexes(
            storage_by_name={self.aggregate_symbol: "storage:collision"}
        )
        with self.assertRaisesRegex(ValueError, "conflicting reviewed"):
            self.prove(fixture)


