    @staticmethod
    def instructions_from_segments(
        code: bytes,
        segments: tuple[tuple[int, int, str], ...],
        *,
        source: str,
    ) -> tuple[Instruction, ...]:
        rows: list[Instruction] = []
        cursor = 0
        for offset, size, text in segments:
            if cursor < offset:
                body = code[cursor:offset]
                address = 0x414590 + cursor if source == "bn" else cursor
                rows.append(
                    Instruction(
                        text="nop",
                        raw_text="nop",
                        bytes=tuple(f"{value:02x}" for value in body),
                        source_line=(
                            f"{address:08x} nop"
                            if source == "bn"
                            else f"{address:05x} nop"
                        ),
                    )
                )
            body = code[offset : offset + size]
            address = 0x414590 + offset if source == "bn" else offset
            rows.append(
                Instruction(
                    text=text,
                    raw_text=text,
                    bytes=tuple(f"{value:02x}" for value in body),
                    source_line=(
                        f"{address:08x} {text}"
                        if source == "bn"
                        else f"{address:05x} {text}"
                    ),
                )
            )
            cursor = offset + size
        if cursor < len(code):
            address = 0x414590 + cursor if source == "bn" else cursor
            rows.append(
                Instruction(
                    text="nop",
                    raw_text="nop",
                    bytes=tuple(f"{value:02x}" for value in code[cursor:]),
                    source_line=(
                        f"{address:08x} nop"
                        if source == "bn"
                        else f"{address:05x} nop"
                    ),
                )
            )
        return tuple(rows)

