    def test_caller_source_tu_target_and_import_authority_fail_closed(self) -> None:
        wrong_anchor = deepcopy(self.document().data)
        wrong_anchor["symbols"]["recoil:function:0x414590"][
            "source_traceability"
        ]["source_edges"][0]["anchor_id"] = "recoil:anchor:wrong"
        wrong_source_tu = deepcopy(self.document().data)
        wrong_source_tu["symbols"]["recoil:function:0x414590"][
            "source_traceability"
        ]["source_edges"][0]["emission_context"] = {
            "translation_unit": "src/Battlesport/game_net.cpp"
        }
        wrong_contribution = self.target()
        wrong_contribution.translation_unit_function_order[0].functions[
            0
        ].symbol_regex = (
            r"\?Wrong@GameNet@@.*"
        )
        wrong_target = self.target()
        wrong_target.name = "stale_hud_target"
        cases = {
            "extent": {"caller_end_exclusive": "0x414650"},
            "stale-caller-symbol": {
                "candidate": self.candidate(
                    definition=replace(
                        self.definition(), symbol=self.stale_caller_symbol
                    )
                )
            },
            "source-anchor": {"document": ProgressDocument(wrong_anchor)},
            "source-tu": {"document": ProgressDocument(wrong_source_tu)},
            "governed-target": {
                "candidate": self.candidate(target=wrong_target)
            },
            "contribution": {
                "candidate": self.candidate(target=wrong_contribution)
            },
            "iat-index": {
                "indexes": self.indexes(
                    storage_by_address={"0x4cc4f0": "iat:wrong"}
                )
            },
            "direct-name-index": {
                "indexes": self.indexes(
                    by_candidate_name={
                        "?Begin@HudUiMgrObjective@@YIXXZ": "symbol:wrong"
                    }
                )
            },
        }
        for label, changes in cases.items():
            fixture = self.fixture()
            fixture.update(changes)
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "authority|contribution-row|IAT tuple|retail-address identities"
            ):
                self.prove(fixture)

        fixture = self.fixture()
        wrong_import = SimpleNamespace(
            address="0x4cc4f0",
            dll="MSVCRT.dll",
            import_name="strncpy",
            import_ordinal=None,
        )
        with patch(
            "_recoil.commands.call_contract_verify.retail_import_target",
            return_value=(wrong_import, {}),
        ), self.assertRaisesRegex(ValueError, "IAT tuple"):
            self.prove(fixture)

    def test_body_relocation_call_cleanup_and_lifetime_drift_fail_closed(self) -> None:
        definition = self.definition()
        wrong_body = bytearray(definition.data)
        wrong_body[0x40] ^= 1
        missing_relocation = replace(
            definition,
            relocations=tuple(
                row for row in definition.relocations if row.offset != 0x61
            ),
        )
        retail_form = list(self.retail_instructions())
        retail_form[next(
            index
            for index, row in enumerate(retail_form)
            if row.source_line.startswith("00414604")
        )] = replace(
            retail_form[next(
                index
                for index, row in enumerate(retail_form)
                if row.source_line.startswith("00414604")
            )],
            text="call eax",
            raw_text="call eax",
        )
        candidate_cleanup = list(self.candidate_instructions())
        cleanup_index = next(
            index
            for index, row in enumerate(candidate_cleanup)
            if row.source_line.startswith("00083")
        )
        candidate_cleanup[cleanup_index] = replace(
            candidate_cleanup[cleanup_index],
            text="add esp, 8",
            raw_text="add esp, 8",
        )
        candidate_clobber = list(self.candidate_instructions())
        gap_index = next(
            index
            for index, row in enumerate(candidate_clobber)
            if row.source_line.startswith("0007a")
        )
        candidate_clobber[gap_index] = replace(
            candidate_clobber[gap_index],
            text="mov esi, eax",
            raw_text="mov esi, eax",
        )
        cases = {
            "stale-body": {
                "candidate": self.candidate(
                    definition=replace(definition, data=bytes(wrong_body))
                )
            },
            "relocation": {
                "candidate": self.candidate(definition=missing_relocation)
            },
            "retail-register-form": {
                "retail_instructions": tuple(retail_form)
            },
            "candidate-cleanup": {
                "candidate": self.candidate(
                    instructions=tuple(candidate_cleanup)
                )
            },
            "candidate-register-clobber": {
                "candidate": self.candidate(
                    instructions=tuple(candidate_clobber)
                )
            },
        }
        for label, changes in cases.items():
            fixture = self.fixture()
            fixture.update(changes)
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "object symbol/body|thirteen|register form|cleanup|clobbered",
            ):
                self.prove(fixture)


