    def candidate(
        self,
        *,
        instructions: tuple[Instruction, ...] | None = None,
        definition: CandidateCallerDefinition | None = None,
        target: SimpleNamespace | None = None,
    ) -> CandidateAssembly:
        data = bytearray(0x80)
        data[0x52:0x58] = b"\xff\x15\x00\x00\x00\x00"
        data[0x64:0x6A] = b"\xff\x15\x00\x00\x00\x00"
        mask = [False] * len(data)
        mask[0x54:0x58] = [True] * 4
        mask[0x66:0x6A] = [True] * 4
        exact_definition = CandidateCallerDefinition(
            symbol=self.caller_symbol,
            data=bytes(data),
            relocations=(
                CoffRelocation(0x54, 1, 0x06, self.puts_symbol),
                CoffRelocation(0x66, 2, 0x06, self.fflush_symbol),
            ),
            relocation_mask=tuple(mask),
            undefined_external_functions=(
                self.puts_symbol,
                self.fflush_symbol,
            ),
        )
        return CandidateAssembly(
            instructions=instructions or self.candidate_instructions(),
            local_control_flow_indices=frozenset(),
            target=target or self.target(),
            caller_definition=definition or exact_definition,
        )

