    def test_independent_contracts_validate_current_virtual_slot_candidate(self) -> None:
        candidate = self.candidate()
        retail, current = self.bridge(candidate=candidate)
        self.assertEqual(
            {"0x414083", "0x414093", "0x4140dd", "0x4140eb", "0x414134", "0x414142", "0x414171"},
            set(retail),
        )
        self.assertEqual(
            {"0x13", "0x23", "0x6f", "0x7d", "0xc8", "0xd6", "0x109"},
            set(current),
        )
        self.assertEqual(
            ReviewedLoopVptrStorageBridge(
                register="edx",
                storage_identity="load(this+0xe0)",
                slot_displacement=0x18,
                assembly_source="cod",
            ),
            current["0xd6"],
        )
        expected = extract_invocation_contract(
            self.retail_instructions(),
            source="bn",
            caller_identity=self.caller_identity,
            caller_start="0x414070",
            caller_end_exclusive="0x414180",
            indexes=self.indexes(),
            reviewed_loop_vptr_storage_bridges=retail,
        )
        actual = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity=self.caller_identity,
            caller_start="0x414070",
            caller_end_exclusive="0x414180",
            indexes=self.indexes(),
            reviewed_loop_vptr_storage_bridges=current,
        )
        comparison = compare_call_contracts(expected, actual)
        self.assertTrue(comparison["passed"])
        self.assertIsNone(comparison["first_divergence"])

