class RecoilMainMenuTransitionEaxBridgeTests(unittest.TestCase):
    caller_symbol = "?OnTryBecomeCurrent@RecoilStateMainMenuTransition@@UAEHXZ"
    caller_identity = "symbol:recoil:function:0x415220"

    @staticmethod
    def _instructions(
        code: bytes,
        *,
        base: int,
        end: int,
        source: str,
        specifications: dict[int, tuple[str, str, int]],
    ) -> tuple[Instruction, ...]:
        rows: list[Instruction] = []
        cursor = 0
        for offset in sorted(specifications):
            if cursor < offset:
                body = code[cursor:offset]
                rows.append(Instruction(
                    text="nop",
                    raw_text="nop",
                    bytes=tuple(f"{item:02x}" for item in body),
                    source_line=f"{base + cursor:08x} {body.hex(' ')} nop",
                ))
            mnemonic, operand, size = specifications[offset]
            body = code[offset : offset + size]
            raw_text = f"{mnemonic} {operand}".strip()
            rows.append(Instruction(
                text=raw_text,
                raw_text=raw_text,
                bytes=tuple(f"{item:02x}" for item in body),
                source_line=(
                    f"{base + offset:08x} {body.hex(' ')} {raw_text}"
                ),
            ))
            cursor = offset + size
        if cursor < end:
            body = code[cursor:end]
            rows.append(Instruction(
                text="nop",
                raw_text="nop",
                bytes=tuple(f"{item:02x}" for item in body),
                source_line=f"{base + cursor:08x} {body.hex(' ')} nop",
            ))
        return tuple(rows)

