    def test_indirect_candidate_storage_receiver_slot_and_cleanup_fail_closed(
        self,
    ) -> None:
        fixture = self.fixture()
        exact = self.indirect_candidate(fixture)
        cases = (
            (
                "storage",
                self.replace_indirect_instruction(
                    exact,
                    offset=0x59,
                    raw_text="mov eax, [esp+0xc]",
                    body=bytes.fromhex("8b44240c"),
                ),
                "vptr reaching definition",
            ),
            (
                "receiver",
                self.replace_indirect_instruction(
                    exact,
                    offset=0x61,
                    raw_text="lea ecx, [esp+0xc]",
                    body=bytes.fromhex("8d4c240c"),
                ),
                "population, register, slot, receiver, or order",
            ),
            (
                "slot",
                self.replace_indirect_instruction(
                    exact,
                    offset=0x6D,
                    raw_text="call dword [eax+0xc]",
                    body=bytes.fromhex("ff500c"),
                ),
                "population, register, slot, receiver, or order",
            ),
            (
                "cleanup",
                self.replace_indirect_instruction(
                    exact,
                    offset=0x70,
                    raw_text="add esp, 4",
                ),
                "call form, or cleanup",
            ),
        )
        for label, candidate, message in cases:
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, message
            ):
                self.invoke(fixture, candidate=candidate)

