    def test_deferred_header_comdat_rebinds_from_exact_numbered_source_rows(
        self,
    ) -> None:
        symbol = "?_Ucopy@?$vector@UFixture@@V?$allocator@UFixture@@@std@@@std@@IAEXXZ"
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            header = root / "VC" / "INCLUDE" / "vector"
            source = root / "src" / "fixture.cpp"
            header.parent.mkdir(parents=True)
            source.parent.mkdir(parents=True)
            header.write_text(
                "ignored\nignored\n\t{for (; first != last; ++first)\n",
                encoding="utf-8",
            )
            source.write_text(
                "ignored\nignored\n    unrelated_source_row();\n",
                encoding="utf-8",
            )
            cod_path = root / "fixture.cod"
            cod_path.write_text(
                "\n".join(
                    [
                        f"; File {header}",
                        f"; File {source}",
                        "_TEXT SEGMENT",
                        f"{symbol} PROC NEAR ; deferred header COMDAT",
                        "; 3 : \t{for (; first != last; ++first)",
                        "  00000 c3 ret 0",
                        f"{symbol} ENDP",
                        "_TEXT ENDS",
                    ]
                ),
                encoding="utf-8",
            )

            provenance = (
                call_contract_verify_module._candidate_comdat_source_provenance(
                    cod_path, symbol
                )
            )

        self.assertEqual(str(header), provenance)

