    def test_exact_erase_comdat_uses_reviewed_structural_provider(self) -> None:
        candidate = self.erase_provider_candidate()
        indexes = self.erase_provider_indexes()
        name = next(iter(candidate.tu_local_function_definitions))
        identity = "provider:recoil:function:0x4ba4d0"
        bridges = self.bridge(candidate, indexes=indexes)
        self.assertEqual({name: identity}, bridges)
        contract = extract_invocation_contract(
            candidate.instructions,
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x1000",
            caller_end_exclusive="0x1010",
            indexes=indexes,
            compiler_generated_bridges=bridges,
        )
        self.assertEqual(identity, contract[0]["target_identity"])
        self.assertEqual("provider", contract[0]["identity_kind"])

        tail = self.erase_provider_candidate(
            assembly=f"00000 e9 00 00 00 00 jmp {name}\n00005 c3 ret 0",
            data=b"\xe9\x00\x00\x00\x00\xc3",
        )
        tail_bridges = self.bridge(tail, indexes=indexes)
        tail_contract = extract_invocation_contract(
            tail.instructions,
            source="cod",
            caller_identity="symbol:caller",
            caller_start="0x1000",
            caller_end_exclusive="0x1010",
            indexes=indexes,
            compiler_generated_bridges=tail_bridges,
        )
        self.assertEqual(identity, tail_contract[0]["target_identity"])
        self.assertEqual("tail", tail_contract[0]["form"])

