class CppDefinitionClosureTests(unittest.TestCase):
    def test_document_inventory_cache_reuses_exact_path_and_define_context(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "unit.cpp"
            source.write_text(
                "namespace Unit { void Run() {} }", encoding="utf-8"
            )
            document = ProgressDocument(empty_progress_document())
            resolver = (
                call_contract_verify_module
                ._call_contract_callable_inventory_resolver(
                    document, root=root
                )
            )
            with patch.object(
                call_contract_verify_module,
                "callable_inventory",
                wraps=call_contract_verify_module.callable_inventory,
            ) as parse:
                first = resolver("unit.cpp", ("FEATURE=1",))
                second = resolver("unit.cpp", ("FEATURE=1",))
                different_context = resolver(
                    "unit.cpp", ("FEATURE=0",)
                )

        self.assertIs(first, second)
        self.assertEqual(first, different_context)
        self.assertEqual(2, parse.call_count)

    def test_document_inventory_cache_invalidates_changed_or_missing_file(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source = root / "unit.cpp"
            source.write_text(
                "namespace Unit { void First() {} }", encoding="utf-8"
            )
            document = ProgressDocument(empty_progress_document())
            resolver = (
                call_contract_verify_module
                ._call_contract_callable_inventory_resolver(
                    document, root=root
                )
            )
            with patch.object(
                call_contract_verify_module,
                "callable_inventory",
                wraps=call_contract_verify_module.callable_inventory,
            ) as parse:
                first = resolver("unit.cpp", ())
                before = source.stat()
                source.write_text(
                    "namespace Unit { void SecondWithLongerName() {} }",
                    encoding="utf-8",
                )
                os.utime(
                    source,
                    ns=(before.st_atime_ns, before.st_mtime_ns + 1_000_000),
                )
                second = resolver("unit.cpp", ())
                source.unlink()
                with self.assertRaisesRegex(
                    ProgressError, "source disappeared"
                ):
                    resolver("unit.cpp", ())

        self.assertNotEqual(first, second)
        self.assertEqual(2, parse.call_count)
        self.assertIn(
            CallableKey("Unit::SecondWithLongerName", ()),
            second.definitions,
        )

    def test_cached_inventory_hook_preserves_ambiguous_definition_failure(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            (root / "unit.h").write_text(
                "namespace Unit { void Run(); }", encoding="utf-8"
            )
            definition = "namespace Unit { void Run() {} }"
