    def test_real_pickup_and_zclass_definition_regressions(self) -> None:
        config = call_contract_verify_module.load_final_build_config()
        source_texts = [
            (
                source.resolve().relative_to(REPO_ROOT.resolve()).as_posix(),
                source.read_text(encoding="utf-8", errors="ignore"),
                call_contract_verify_module._call_contract_vc5_preprocessor_defines(
                    config,
                    source,
                ),
            )
            for source in config.sources
        ]
        contexts = sorted({row[2] for row in source_texts})

        def definitions(header_path: str) -> tuple[str, ...]:
            text = (REPO_ROOT / header_path).read_text(
                encoding="utf-8", errors="ignore"
            )
            return exact_definition_sources(
                header_texts=[
                    (header_path, text, context) for context in contexts
                ],
                source_texts=source_texts,
            )

        pickup_sources = definitions("src/Battlesport/pickup.h")
        self.assertEqual(
            (
                "src/Battlesport/pickup.cpp",
                "src/Battlesport/RecoilApp.cpp",
            ),
            pickup_sources,
        )
