    def test_exact_candidate_identity_attaches_bounded_dependent_owner(self) -> None:
        decoded = (
            call_contract_verify_module.decode_vc5_zero_argument_callable_identity(
                "?MatLoadIdentity@zMath@@YIXXZ"
            )
        )
        assert decoded is not None
        error = call_contract_verify_module.CandidateCallTargetBridgeError(
            decorated_identity=decoded.decorated_identity,
            decoded_identity=decoded,
            call_site_address="0x44ac31",
            message="unit",
            call_site_unique=True,
        )
        resolution = call_contract_verify_module.DependentOwnerResolution(
            mode="exact",
            declaration_paths=(
                "src/GameZRecoil/zMath/zmth_decls.h",
            ),
            definition_paths=("src/GameZRecoil/zMath/zmth_main.c",),
            source_edit_paths=(
                "src/GameZRecoil/zMath/zmth_decls.h",
                "src/GameZRecoil/zMath/zmth_main.c",
            ),
        )
        config = self._config(
            REPO_ROOT, "src/GameZRecoil/zMath/zmth_main.c"
        )
        with (
            patch.object(
                call_contract_verify_module,
                "load_final_build_config",
                return_value=config,
            ),
            patch.object(
                call_contract_verify_module,
                "_call_contract_vc5_preprocessor_defines",
                return_value=("_MSC_VER=1100",),
            ),
            patch.object(
                call_contract_verify_module,
                "_call_contract_callable_inventory_resolver",
                return_value=object(),
            ),
            patch.object(
                call_contract_verify_module,
                "resolve_dependent_callable_owner",
                return_value=resolution,
            ) as resolve_owner,
        ):
            result = (
                call_contract_verify_module._candidate_dependent_owner_provenance(
                    SimpleNamespace(),
                    self._closure(),
                    caller_symbol_id="recoil:function:0x44abf0",
                    caller_address="0x44abf0",
                    caller_end_exclusive="0x44ad00",
                    caller_target_id="recoil:vc5-target:camera",
                    caller_source_edit_paths=("src/Battlesport/camera.cpp",),
                    error=error,
                )
            )
            caller_owned = (
                call_contract_verify_module._candidate_dependent_owner_provenance(
                    SimpleNamespace(),
                    self._closure(),
                    caller_symbol_id="recoil:function:0x44abf0",
                    caller_address="0x44abf0",
                    caller_end_exclusive="0x44ad00",
                    caller_target_id="recoil:vc5-target:zmath",
                    caller_source_edit_paths=(
                        "src/GameZRecoil/zMath/zmth_decls.h",
                        "src/GameZRecoil/zMath/zmth_main.c",
                    ),
                    error=error,
                )
            )

        self.assertEqual("exact-dependent-owner", result["owner_relation"])
        self.assertEqual("recoil:function:0x44abf0", result["caller_symbol_id"])
        self.assertEqual("0x44ac31", result["candidate_call_site_address"])
        self.assertEqual("__fastcall", result["identity"]["calling_convention"])
        self.assertFalse(result["candidate_expected_truth"])
        self.assertEqual("caller-owned", caller_owned["owner_relation"])
        self.assertEqual(
            ["src/Battlesport/camera.cpp"],
            result["caller_target_source_edit_paths"],
        )
        self.assertEqual(
            [
                "src/GameZRecoil/zMath/zmth_decls.h",
                "src/GameZRecoil/zMath/zmth_main.c",
            ],
            caller_owned["caller_target_source_edit_paths"],
        )
        self.assertEqual(
            [
                "src/GameZRecoil/zMath/zmth_decls.h",
                "src/GameZRecoil/zMath/zmth_main.c",
            ],
            result["owner_resolution"]["source_edit_paths"],
        )
        self.assertEqual(4, resolve_owner.call_count)

        for label, call_site, unique in (
            ("null", None, True),
            ("wrong-extent", "0x44ae00", True),
            ("duplicate", "0x44ac31", False),
        ):
            invalid_error = (
                call_contract_verify_module.CandidateCallTargetBridgeError(
                    decorated_identity=decoded.decorated_identity,
                    decoded_identity=decoded,
                    call_site_address=call_site,
                    message="unit",
                    call_site_unique=unique,
                )
            )
            with (
                patch.object(
                    call_contract_verify_module,
                    "load_final_build_config",
                    return_value=config,
                ),
                patch.object(
                    call_contract_verify_module,
                    "_call_contract_vc5_preprocessor_defines",
                    return_value=("_MSC_VER=1100",),
                ),
                patch.object(
                    call_contract_verify_module,
                    "_call_contract_callable_inventory_resolver",
                    return_value=object(),
                ),
                patch.object(
                    call_contract_verify_module,
                    "resolve_dependent_callable_owner",
                    return_value=resolution,
                ),
            ):
                invalid = call_contract_verify_module._candidate_dependent_owner_provenance(
                    SimpleNamespace(),
                    self._closure(),
                    caller_symbol_id="recoil:function:0x44abf0",
                    caller_address="0x44abf0",
                    caller_end_exclusive="0x44ad00",
                    caller_target_id="recoil:vc5-target:camera",
                    caller_source_edit_paths=("src/Battlesport/camera.cpp",),
                    error=invalid_error,
                )
            with self.subTest(label=label):
                self.assertEqual(
                    "non-source-ambiguity", invalid["owner_relation"]
                )
                self.assertIs(
                    call_site,
                    invalid["candidate_call_site_address"],
                ) if call_site is None else self.assertEqual(
                    call_site, invalid["candidate_call_site_address"]
                )
                self.assertNotEqual(
                    "None", invalid["candidate_call_site_address"]
                )

    def test_many_callers_retain_only_exact_definition_context_inventories(
        self,
    ) -> None:
        """Dependent-owner cache plateaus independently of unrelated TUs."""

        with tempfile.TemporaryDirectory(
            prefix="call_contract_dependent_owner_retention_"
        ) as temporary:
            root = Path(temporary)
            header = "src/Unit/unit.h"
            definition = "src/Unit/unit.cpp"
            header_path = root / header
            definition_path = root / definition
            header_path.parent.mkdir(parents=True)
            header_path.write_text(
                "namespace Unit { void Run(); }\n",
                encoding="utf-8",
            )
            definition_path.write_text(
                "namespace Unit { void Run() {} }\n",
                encoding="utf-8",
            )
            unrelated_relatives = tuple(
                f"src/Unrelated/context_{index}.cpp"
                for index in range(96)
            )
            unrelated_sources = tuple(
                root / relative for relative in unrelated_relatives
            )
            for index, source in enumerate(unrelated_sources):
                source.parent.mkdir(parents=True, exist_ok=True)
                source.write_text(
                    f"namespace Unrelated {{ void Context{index}() {{}} }}\n",
                    encoding="utf-8",
                )
            config = self._config(
                root, definition, *unrelated_relatives
            )
            closure = call_contract_verify_module.CallContractSourceClosure(
                source_edit_paths=(definition,),
                registered_source_paths=(definition,),
                header_paths=(header,),
                definition_source_paths=(definition, *unrelated_relatives),
                dependency_paths=(
                    header,
                    definition,
                    *unrelated_relatives,
                ),
            )
            decoded = (
                call_contract_verify_module
                .decode_vc5_zero_argument_callable_identity(
                    "?Run@Unit@@YIXXZ"
                )
            )
            assert decoded is not None
            error = call_contract_verify_module.CandidateCallTargetBridgeError(
                decorated_identity=decoded.decorated_identity,
                decoded_identity=decoded,
                call_site_address="0x401008",
                message="unit",
                call_site_unique=True,
            )
            document = ProgressDocument(empty_progress_document())

            def exact_context(source: Path) -> tuple[str, ...]:
                relative = source.resolve().relative_to(root).as_posix()
                token = re.sub(r"[^A-Za-z0-9_]", "_", relative).upper()
                return (f"PROFILE_{token}=1",)

            with (
                patch.object(call_contract_verify_module, "REPO_ROOT", root),
                patch.object(
                    call_contract_verify_module,
                    "load_final_build_config",
                    return_value=config,
                ),
                patch.object(
                    call_contract_verify_module,
                    "_call_contract_vc5_preprocessor_defines",
                    side_effect=lambda _config, source: exact_context(source),
                ),
            ):
                first = None
                for index in range(132):
                    result = (
                        call_contract_verify_module
                        ._candidate_dependent_owner_provenance(
                            document,
                            closure,
                            caller_symbol_id=f"recoil:function:0x{0x401000 + index:x}",
                            caller_address="0x401000",
                            caller_end_exclusive="0x401100",
                            caller_target_id="recoil:vc5-target:unit",
                            caller_source_edit_paths=(header, definition),
                            error=error,
                        )
                    )
                    self.assertEqual("caller-owned", result["owner_relation"])
                    cache = getattr(
                        document,
                        "_call_contract_callable_inventory_cache_v1",
                    )
                    if first is None:
                        first = tuple(cache)
                    self.assertEqual(first, tuple(cache))
                    self.assertEqual(98, len(cache))

        assert first is not None
        header_keys = tuple(
            key for key in first if str(key[0]).casefold().endswith("/unit.h")
        )
        self.assertEqual(1, len(header_keys))
        self.assertEqual(exact_context(definition_path), header_keys[0][1])
        self.assertFalse(
            any("UNRELATED" in value for key in header_keys for value in key[1])
        )

