    def test_dependent_owner_header_cannot_borrow_unrelated_source_context(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory(
            prefix="call_contract_dependent_owner_context_"
        ) as temporary:
            root = Path(temporary)
            header = "src/Unit/unit.h"
            definition = "src/Unit/unit.cpp"
            unrelated = "src/Other/other.cpp"
            for relative, text in (
                (
                    header,
                    "#if FEATURE\nnamespace Unit { void Run(); }\n#endif\n",
                ),
                (definition, "namespace Unit { void Run() {} }\n"),
                (unrelated, "namespace Other { void Work() {} }\n"),
            ):
                path = root / relative
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(text, encoding="utf-8")
            closure = call_contract_verify_module.CallContractSourceClosure(
                source_edit_paths=(definition,),
                registered_source_paths=(definition,),
                header_paths=(header,),
                definition_source_paths=(definition, unrelated),
                dependency_paths=(header, definition, unrelated),
            )
            decoded = (
                call_contract_verify_module
                .decode_vc5_zero_argument_callable_identity(
                    "?Run@Unit@@YIXXZ"
                )
            )
            assert decoded is not None
            error = call_contract_verify_module.CandidateCallTargetBridgeError(
                decorated_identity=decoded.decorated_identity,
                decoded_identity=decoded,
                call_site_address="0x401008",
                message="unit",
                call_site_unique=True,
            )
            config = SimpleNamespace(
                sources=(root / definition, root / unrelated),
                source_repository_paths=(definition, unrelated),
            )


            def source_context(_config: object, source: Path) -> tuple[str, ...]:
                return (
                    ("FEATURE=0",)
                    if source.resolve() == (root / definition).resolve()
                    else ("FEATURE=1",)
                )

            document = ProgressDocument(empty_progress_document())
            with (
                patch.object(call_contract_verify_module, "REPO_ROOT", root),
                patch.object(
                    call_contract_verify_module,
                    "load_final_build_config",
                    return_value=config,
                ),
                patch.object(
                    call_contract_verify_module,
                    "_call_contract_vc5_preprocessor_defines",
                    side_effect=source_context,
                ),
            ):
                result = (
                    call_contract_verify_module
                    ._candidate_dependent_owner_provenance(
                        document,
                        closure,
                        caller_symbol_id="recoil:function:0x401000",
                        caller_address="0x401000",
                        caller_end_exclusive="0x401100",
                        caller_target_id="recoil:vc5-target:unit",
                        caller_source_edit_paths=(header, definition),
                        error=error,
                    )
                )

        self.assertEqual("non-source-ambiguity", result["owner_relation"])
        self.assertEqual("unresolved", result["owner_resolution"]["mode"])
        self.assertEqual([], result["owner_resolution"]["declaration_paths"])
        self.assertEqual([definition], result["owner_resolution"]["definition_paths"])
        self.assertEqual([], result["owner_resolution"]["source_edit_paths"])

