    def test_r4564_dependent_identity_allowlist_is_exact_and_typed(self) -> None:
        module = call_contract_verify_module
        expected = {
            "?BaseConstructor@HudUiNumericTextInput@@QAEPAU1@XZ": (
                "HudUiNumericTextInput::BaseConstructor", (), "__thiscall"
            ),
            "??1HudUiNumericTextInput@@UAE@XZ": (
                "HudUiNumericTextInput::~HudUiNumericTextInput", (), "__thiscall"
            ),
            "?Constructor@HudUiZrdWidget@@QAEPAU1@XZ": (
                "HudUiZrdWidget::Constructor", (), "__thiscall"
            ),
            "?TransformPointByMatrix@Player@@YI?AUzVec3@@ABU2@ABUzMat4x3@@@Z": (
                "Player::TransformPointByMatrix",
                ("const zVec3 &", "const zMat4x3 &"),
                "__fastcall",
            ),
            "?ResetAltGunAttachNode@Player@@YIXPAUPlayerGunFireController@@@Z": (
                "Player::ResetAltGunAttachNode",
                ("PlayerGunFireController *",),
                "__fastcall",
            ),
            "?Constructor@HudUiWidget@@QAEPAU1@I@Z": (
                "HudUiWidget::Constructor", ("unsigned int",), "__thiscall"
            ),
            "?DestructorCore@HudUiZrdWidget@@QAEXXZ": (
                "HudUiZrdWidget::DestructorCore", (), "__thiscall"
            ),
            "?SetEnabled@HudUiBackgroundContainer@@UAEXH@Z": (
                "HudUiBackgroundContainer::SetEnabled", ("int",), "__thiscall"
            ),
            "?Constructor@HudUiElement@@QAEPAU1@HH@Z": (
                "HudUiElement::Constructor", ("int", "int"), "__thiscall"
            ),
            "?DestructorCore@HudUiWidget@@QAEXXZ": (
                "HudUiWidget::DestructorCore", (), "__thiscall"
            ),
        }
        for identity, (name, parameters, calling) in expected.items():
            with self.subTest(identity=identity):
                decoded = module._decode_candidate_dependent_callable_identity(
                    identity
                )
                self.assertIsNotNone(decoded)
                assert decoded is not None
                self.assertEqual(name, decoded.callable_key.qualified_name)
                self.assertEqual(parameters, decoded.callable_key.parameter_shapes)
                self.assertEqual(calling, decoded.calling_convention)
                self.assertEqual(
                    "msvc-exact-reviewed-r4564", decoded.identity_format
                )
                self.assertIsNone(
                    module._decode_candidate_dependent_callable_identity(
                        identity + "A"
                    )
                )

