    def test_r4564_inlined_extra_helpers_route_only_as_exact_caller_source(
        self,
    ) -> None:
        module = call_contract_verify_module
        identity = (
            "?TransformPointByMatrix@Player@@YI?AUzVec3@@"
            "ABU2@ABUzMat4x3@@@Z"
        )
        exact = module.CandidateCallTargetBridgeError(
            decorated_identity=identity,
            decoded_identity=(
                module._decode_candidate_dependent_callable_identity(identity)
            ),
            call_site_address="0x43aaaa",
            message="unit",
            call_site_unique=True,
        )
        self.assertTrue(
            module._r4564_candidate_extra_helper_is_caller_source(
                caller_address="0x43aa30",
                caller_end_exclusive="0x43acf0",
                error=exact,
            )
        )
        def changed_error(
            *,
            name: str = identity,
            site: str = "0x43aaaa",
            unique: bool = True,
        ) -> object:
            return module.CandidateCallTargetBridgeError(
                decorated_identity=name,
                decoded_identity=(
                    module._decode_candidate_dependent_callable_identity(name)
                ),
                call_site_address=site,
                message="unit",
                call_site_unique=unique,
            )
        for label, start, end, error in (
            ("caller", "0x43aa20", "0x43acf0", exact),
            ("extent", "0x43aa30", "0x43ace0", exact),
            (
                "site",
                "0x43aa30",
                "0x43acf0",
                changed_error(site="0x43aaab"),
            ),
            (
                "name",
                "0x43aa30",
                "0x43acf0",
                changed_error(name=identity + "A"),
            ),
            (
                "duplicate",
                "0x43aa30",
                "0x43acf0",
                changed_error(unique=False),
            ),
        ):
            with self.subTest(label=label):
                self.assertFalse(
                    module._r4564_candidate_extra_helper_is_caller_source(
                        caller_address=start,
                        caller_end_exclusive=end,
                        error=error,
                    )
                )

