    def test_pump_switch_and_folded_final_dispatch_are_exact_and_fail_closed(
        self,
    ) -> None:
        candidate, indexes = self.pump_switch_fixture()
        switch_targets = (
            call_contract_verify_module
            ._znetwork_pump_exact_candidate_switch_targets(
                candidate,
                caller_identity=(
                    call_contract_verify_module
                    ._ZNETWORK_FATAL_CALLBACK_CALLER_IDENTITY
                ),
                caller_start="0x48afe0",
                caller_end_exclusive="0x48b3a0",
                indexes=indexes,
            )
        )
        self.assertEqual(1, len(switch_targets))
        self.assertEqual(6, len(next(iter(switch_targets.values()))))

        prefix = [{
            "ordinal": ordinal,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": f"symbol:prefix:{ordinal}",
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        } for ordinal in range(10)]
        final = {
            "ordinal": 10,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": (
                call_contract_verify_module._ZNETWORK_DISPATCH_CALLER_IDENTITY
            ),
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        }
        observed = [*prefix, final]
        expected = [*observed, {**final, "ordinal": 11}]
        call_sites = tuple(
            call_contract_verify_module.normalize_address(0x48AFE0 + offset)
            for offset in (
                0x39, 0x68, 0x70, 0x8F, 0xA8, 0x138,
                0x193, 0x198, 0x1A8, 0x1E0, 0x231,
            )
        )
        result = (
            call_contract_verify_module
            ._znetwork_pump_folded_dispatch_candidate_projection(
                expected,
                observed,
                candidate,
                call_sites,
                switch_targets,
                caller_identity=(
                    call_contract_verify_module
                    ._ZNETWORK_FATAL_CALLBACK_CALLER_IDENTITY
                ),
                caller_start="0x48afe0",
                caller_end_exclusive="0x48b3a0",
            )
        )
        self.assertEqual(expected, result)

        changed_body = bytearray(candidate.caller_definition.data)
        changed_body[0x2A0] ^= 1
        with self.assertRaisesRegex(ValueError, "classifier"):
            call_contract_verify_module._znetwork_pump_exact_candidate_switch_targets(
                replace(
                    candidate,
                    caller_definition=replace(
                        candidate.caller_definition,
                        data=bytes(changed_body),
                    ),
                ),
                caller_identity=(
                    call_contract_verify_module
                    ._ZNETWORK_FATAL_CALLBACK_CALLER_IDENTITY
                ),
                caller_start="0x48afe0",
                caller_end_exclusive="0x48b3a0",
                indexes=indexes,
            )
        with self.assertRaisesRegex(ValueError, "folded-dispatch"):
            call_contract_verify_module._znetwork_pump_folded_dispatch_candidate_projection(
                expected,
                observed,
                candidate,
                call_sites[:-1],
                switch_targets,
                caller_identity=(
                    call_contract_verify_module
                    ._ZNETWORK_FATAL_CALLBACK_CALLER_IDENTITY
                ),
                caller_start="0x48afe0",
                caller_end_exclusive="0x48b3a0",
            )

