    def test_znetwork_append_exact_source_comdat_uses_reviewed_provider(self):
        fixture = self.znetwork_append_provider_fixture()
        provider_function_document = deepcopy(fixture["document"])
        provider_function_document.collection("symbols")[
            "recoil:function:0x40c1c0"
        ]["kind"] = "provider-function"
        fixture["document"] = provider_function_document
        result = _comparison_scoped_provider_comdat_contract(**{
            key: value for key, value in fixture.items() if key != "name"
        })
        self.assertEqual(
            call_contract_verify_module._ZNETWORK_APPEND_PROVIDER_IDENTITY,
            result[3]["target_identity"],
        )
        self.assertEqual("provider", result[3]["identity_kind"])
        self.assertEqual(4, result[3]["cleanup_bytes"])
        self.assertEqual(fixture["expected"], result)

    def test_znetwork_append_body_source_relocation_and_cleanup_drift_fail_closed(
        self,
    ) -> None:
        fixture = self.znetwork_append_provider_fixture()
        candidate = fixture["candidate"]
        helper = candidate.tu_local_function_definitions[fixture["name"]]
        changed_body = bytearray(helper.data)
        changed_body[0] = 0x90
        cases = {
            "provider-kind": {
                "document": ProgressDocument({
                    **deepcopy(fixture["document"].data),
                    "symbols": {
                        **deepcopy(
                            fixture["document"].collection("symbols")
                        ),
                        "recoil:function:0x40c1c0": {
                            **deepcopy(
                                fixture["document"].collection("symbols")[
                                    "recoil:function:0x40c1c0"
                                ]
                            ),
                            "kind": "data",
                        },
                    },
                })
            },
            "caller-padding": {
                "candidate": replace(
                    candidate,
                    caller_definition=replace(
                        candidate.caller_definition,
                        data=candidate.caller_definition.data[:-1],
                    ),
                )
            },
            "body": {
                "candidate": replace(
                    candidate,
                    tu_local_function_definitions={
                        fixture["name"]: replace(
                            helper, data=bytes(changed_body)
                        )
                    },
                )
            },
            "source": {
                "candidate": replace(
                    candidate,
                    tu_local_function_definitions={
                        fixture["name"]: replace(
                            helper,
                            source_provenance=str(
                                REPO_ROOT / "src" / "wrong.cpp"
                            ),
                        )
                    },
                )
            },
            "relocation": {
                "candidate": replace(
                    candidate,
                    tu_local_function_definitions={
                        fixture["name"]: replace(
                            helper,
                            relocations=(
                                replace(helper.relocations[0], offset=4),
                                *helper.relocations[1:],
                            ),
                        )
                    },
                )
            },
            "cleanup": {
                "candidate_contract": [{
                    **row,
                    **(
                        {"cleanup_bytes": None}
                        if index == 3
                        else {}
                    ),
                } for index, row in enumerate(
                    fixture["candidate_contract"]
                )]
            },
            "copy-provider-body": {
                "bridge": SimpleNamespace(
                    hexdump=lambda address, size: (
                        "0040c1c0 90 90 90 90 90 90 90 90 "
                        "90 90 90 90 90 90 90 90"
                        if address == "0x40c1c0"
                        else "004c5b76 ff 25 ac c2 4c 00"
                    )
                )
            },
            "provider-tail-population": {
                "expected": fixture["expected"][:-1]
            },
            "provider-tail-authority": {
                "indexes": replace(
                    fixture["indexes"],
                    provider_ids=frozenset(
                        identity
                        for identity in fixture["indexes"].provider_ids
                        if identity
                        != "provider:recoil:function:0x42a9d0"
                    ),
                )
            },
        }
        for label, changes in cases.items():
            values = {
                key: value
                for key, value in fixture.items()
                if key != "name"
            }
            values.update(changes)
            with self.subTest(label=label), self.assertRaises(ValueError):
                _comparison_scoped_provider_comdat_contract(**values)

