    def test_candidate_cleanup_receipt_is_independent_of_expected_cleanup(self):
        fixture = self.cobject_operator_new_fixture()
        candidate_only, receipts = (
            call_contract_verify_module
            ._candidate_only_direct_callee_cleanup_contract(
                fixture["candidate_contract"], fixture["candidate"]
            )
        )
        changed_expected = deepcopy(fixture["expected"])
        changed_expected[0]["cleanup_bytes"] = 8
        repeated, repeated_receipts = (
            call_contract_verify_module
            ._candidate_only_direct_callee_cleanup_contract(
                fixture["candidate_contract"], fixture["candidate"]
            )
        )
        self.assertEqual(candidate_only, repeated)
        self.assertEqual(receipts, repeated_receipts)
        self.assertEqual(4, repeated[0]["cleanup_bytes"])
        self.assertEqual(8, changed_expected[0]["cleanup_bytes"])
        with self.assertRaisesRegex(ValueError, "candidate invocation drift"):
            _comparison_scoped_provider_comdat_contract(
                **{**fixture, "expected": changed_expected}
            )

