class LateCandidateLocalReviewedArbitrationTests(unittest.TestCase):
    destructor_name = "??1UnitDestructor@@QAE@XZ"
    destructor_identity = "symbol:recoil:function:0x401000"
    constructor_name = "??0UnitConstructor@@QAE@XZ"
    constructor_identity = "symbol:recoil:function:0x401020"
    ordinary_name = "?UnitOrdinaryHelper@@YAXXZ"
    equal_provider_name = "?UnitEqualProvider@@YAXXZ"
    equal_provider_identity = "provider:recoil:function:0x402000"

    def test_exact_destructor_proof_replaces_only_its_local_sentinel(
        self,
    ) -> None:
        ordinary_identity = f"candidate-local-coff:{self.ordinary_name}"
        local = {
            self.destructor_name: (
                f"candidate-local-coff:{self.destructor_name}"
            ),
            self.ordinary_name: ordinary_identity,
            self.equal_provider_name: self.equal_provider_identity,
        }
        reviewed = {
            self.destructor_name: self.destructor_identity,
            self.equal_provider_name: self.equal_provider_identity,
        }
        self.assertEqual(
            {
                self.destructor_name: self.destructor_identity,
                self.ordinary_name: ordinary_identity,
                self.equal_provider_name: self.equal_provider_identity,
            },
            _arbitrate_candidate_local_reviewed_bridges(
                local,
                reviewed_compiler_provider_bridges=reviewed,
                exact_destructor_bridges={
                    self.destructor_name: self.destructor_identity
                },
                exact_constructor_bridges={},
            ),
        )

    def test_exact_constructor_proof_replaces_only_its_local_sentinel(
        self,
    ) -> None:
        ordinary_identity = f"candidate-local-coff:{self.ordinary_name}"
        local = {
            self.constructor_name: (
                f"candidate-local-coff:{self.constructor_name}"
            ),
            self.ordinary_name: ordinary_identity,
            self.equal_provider_name: self.equal_provider_identity,
        }
        reviewed = {
            self.constructor_name: self.constructor_identity,
            self.equal_provider_name: self.equal_provider_identity,
        }
        self.assertEqual(
            {
                self.constructor_name: self.constructor_identity,
                self.ordinary_name: ordinary_identity,
                self.equal_provider_name: self.equal_provider_identity,
            },
            _arbitrate_candidate_local_reviewed_bridges(
                local,
                reviewed_compiler_provider_bridges=reviewed,
                exact_destructor_bridges={},
                exact_constructor_bridges={
                    self.constructor_name: self.constructor_identity
                },
            ),
        )

    def test_name_only_or_unauthorized_overlap_fails_closed(self) -> None:
        local = {
            self.destructor_name: (
                f"candidate-local-coff:{self.destructor_name}"
            )
        }
        reviewed = {self.destructor_name: self.destructor_identity}
        with self.assertRaisesRegex(
            ValueError, "unproved or conflicting reviewed overlap"
        ):
            _arbitrate_candidate_local_reviewed_bridges(
                local,
                reviewed_compiler_provider_bridges=reviewed,
                exact_destructor_bridges={},
                exact_constructor_bridges={},
            )

    def test_constructor_overlap_requires_proof_and_exact_sentinel(
        self,
    ) -> None:
        reviewed = {self.constructor_name: self.constructor_identity}
        with self.assertRaisesRegex(
            ValueError, "unproved or conflicting reviewed overlap"
        ):
            _arbitrate_candidate_local_reviewed_bridges(
                {
                    self.constructor_name: (
                        f"candidate-local-coff:{self.constructor_name}"
                    )
                },
                reviewed_compiler_provider_bridges=reviewed,
                exact_destructor_bridges={},
                exact_constructor_bridges={},
            )

        with self.assertRaisesRegex(
            ValueError, "unproved or conflicting reviewed overlap"
        ):
            _arbitrate_candidate_local_reviewed_bridges(
                {
                    self.constructor_name: (
                        "candidate-local-coff:wrong-definition"
                    )
                },
                reviewed_compiler_provider_bridges=reviewed,
                exact_destructor_bridges={},
                exact_constructor_bridges={
                    self.constructor_name: self.constructor_identity
                },
            )

        non_destructor = "?NotADestructor@@YAXXZ"
        with self.assertRaisesRegex(
            ValueError, "unproved or conflicting reviewed overlap"
        ):
            _arbitrate_candidate_local_reviewed_bridges(
                {
                    non_destructor: (
                        f"candidate-local-coff:{non_destructor}"
                    )
                },
                reviewed_compiler_provider_bridges={
                    non_destructor: self.destructor_identity
                },
                exact_destructor_bridges={},
                exact_constructor_bridges={},
            )

    def test_non_sentinel_local_identity_fails_closed(self) -> None:
        with self.assertRaisesRegex(
            ValueError, "unproved or conflicting reviewed overlap"
        ):
            _arbitrate_candidate_local_reviewed_bridges(
                {
                    self.destructor_name: (
                        "candidate-local-coff:wrong-definition"
                    )
                },
                reviewed_compiler_provider_bridges={
                    self.destructor_name: self.destructor_identity
                },
                exact_destructor_bridges={
                    self.destructor_name: self.destructor_identity
                },
                exact_constructor_bridges={},
            )

    def test_destructor_proof_identity_drift_fails_closed(self) -> None:
        with self.assertRaisesRegex(
            ValueError, "does not survive unchanged"
        ):
            _arbitrate_candidate_local_reviewed_bridges(
                {
                    self.destructor_name: (
                        f"candidate-local-coff:{self.destructor_name}"
                    )
                },
                reviewed_compiler_provider_bridges={
                    self.destructor_name: self.destructor_identity
                },
                exact_destructor_bridges={
                    self.destructor_name: (
                        "symbol:recoil:function:0x401010"
                    )
                },
                exact_constructor_bridges={},
            )

        with self.assertRaisesRegex(
            ValueError, "does not survive unchanged"
        ):
            _arbitrate_candidate_local_reviewed_bridges(
                {},
                reviewed_compiler_provider_bridges={},
                exact_destructor_bridges={
                    self.destructor_name: self.destructor_identity
                },
                exact_constructor_bridges={},
            )

    def test_constructor_proof_identity_drift_fails_closed(self) -> None:
        local = {
            self.constructor_name: (
                f"candidate-local-coff:{self.constructor_name}"
            )
        }
        reviewed = {self.constructor_name: self.constructor_identity}
        with self.assertRaisesRegex(ValueError, "does not survive unchanged"):
            _arbitrate_candidate_local_reviewed_bridges(
                local,
                reviewed_compiler_provider_bridges=reviewed,
                exact_destructor_bridges={},
                exact_constructor_bridges={
                    self.constructor_name: (
                        "symbol:recoil:function:0x401030"
                    )
                },
            )

    def test_authorized_proof_producers_may_not_disagree(self) -> None:
        with self.assertRaisesRegex(
            ValueError, "conflicting identities from its authorized exact"
        ):
            _arbitrate_candidate_local_reviewed_bridges(
                {},
                reviewed_compiler_provider_bridges={
                    self.constructor_name: self.constructor_identity
                },
                exact_destructor_bridges={
                    self.constructor_name: self.constructor_identity
                },
                exact_constructor_bridges={
                    self.constructor_name: (
                        "symbol:recoil:function:0x401030"
                    )
                },
            )

    def test_equal_reviewed_identity_needs_no_sentinel_rewrite(self) -> None:
        self.assertEqual(
            {self.equal_provider_name: self.equal_provider_identity},
            _arbitrate_candidate_local_reviewed_bridges(
                {
                    self.equal_provider_name: self.equal_provider_identity
                },
                reviewed_compiler_provider_bridges={
                    self.equal_provider_name: self.equal_provider_identity
                },
                exact_destructor_bridges={},
                exact_constructor_bridges={},
            ),
        )


class MissionQueueEnterFastcallRegistrationTests(unittest.TestCase):
    address = "0x41ad80"
    symbol_id = "recoil:function:0x41ad80"
    identity = "symbol:recoil:function:0x41ad80"
    fastcall_symbol = (
        "?QueueEnterWithReconfigureFlag@"
        "HudUiNetGameSetupOverlayOwner@@SIXH@Z"
    )
    stale_cdecl_symbol = (
        "?QueueEnterWithReconfigureFlag@"
        "HudUiNetGameSetupOverlayOwner@@SAXH@Z"
    )

    def indexes(self) -> IdentityIndexes:
        path = (
            REPO_ROOT
            / "tools/vc5_verify_targets/"
            "mission_417350_41cc10_authored_order.json"
        )
        target_id, target = vc5_target_registration(path)
        data = empty_progress_document()
        data["symbols"][self.symbol_id] = {
            "address": self.address,
            "binary": "recoil",
            "kind": "function",
            "pipeline_class": "authored",
        }
        data["verification_targets"][target_id] = target
        return build_identity_indexes(ProgressDocument(data))

    def contract(self, symbol: str) -> list[dict[str, object]]:
        return extract_invocation_contract(
            parse_assembly(
                f"00000 e8 00 00 00 00 call {symbol}\n00005 c3 ret 0",
                source="cod",
            ),
            source="cod",
            caller_identity="symbol:recoil:function:0x419490",
            caller_start="0x419490",
            caller_end_exclusive="0x419500",
            indexes=self.indexes(),
            bridge_names={},
        )

    def test_current_fastcall_symbol_resolves_without_caller_cleanup(self) -> None:
        indexes = self.indexes()
        self.assertEqual(
            self.identity,
            indexes.by_candidate_name[self.fastcall_symbol],
        )
        self.assertNotIn(self.stale_cdecl_symbol, indexes.by_candidate_name)
        self.assertEqual(
            [
                {
                    "ordinal": 0,
                    "form": "call",
                    "dispatch": "direct",
                    "identity_kind": "direct",
                    "target_identity": self.identity,
                    "storage_identity": "",
                    "slot_displacement": None,
                    "cleanup_bytes": None,
                }
            ],
            self.contract(self.fastcall_symbol),
        )

    def test_stale_cdecl_symbol_fails_closed(self) -> None:
        with self.assertRaisesRegex(
            ValueError,
            "unresolved cod decorated call target",
        ):
            self.contract(self.stale_cdecl_symbol)


