    def test_vc5_local_constant_renumbering_is_normalized_only_at_row_zero(
        self,
    ) -> None:
        fixture = self.fixture()
        definition = fixture["candidate"].caller_definition
        assert definition is not None
        rows = list(definition.relocations)
        rows[0] = replace(rows[0], symbol_name="$T1")
        fixture["candidate"] = replace(
            fixture["candidate"],
            caller_definition=replace(definition, relocations=tuple(rows)),
        )
        self.assertEqual({"0x8a"}, set(self.prove(fixture)))

    def test_vc5_local_constant_relocation_drift_fails_closed(self) -> None:
        fixture = self.fixture()
        definition = fixture["candidate"].caller_definition
        assert definition is not None
        local_relocation = definition.relocations[0]
        wrong_addend = bytearray(definition.data)
        struct.pack_into("<I", wrong_addend, 0x1B, 1)
        cases = {
            "malformed-local": replace(
                definition,
                relocations=(
                    replace(local_relocation, symbol_name="$T85783_suffix"),
                    *definition.relocations[1:],
                ),
            ),
            "wrong-type": replace(
                definition,
                relocations=(
                    replace(local_relocation, type=0x14),
                    *definition.relocations[1:],
                ),
            ),
            "wrong-offset": replace(
                definition,
                relocations=(
                    replace(local_relocation, offset=0x1C),
                    *definition.relocations[1:],
                ),
            ),
            "wrong-addend": replace(definition, data=bytes(wrong_addend)),
        }
        for label, changed_definition in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "stale candidate body|COFF relocation population|addend|mask",
            ):
                fixture["candidate"] = replace(
                    fixture["candidate"],
                    caller_definition=changed_definition,
                )
                self.prove(fixture)

    def test_vc5_local_constant_normalization_does_not_hide_nonlocal_drift(
        self,
    ) -> None:
        fixture = self.fixture()
        definition = fixture["candidate"].caller_definition
        assert definition is not None
        rows = list(definition.relocations)
        rows[1] = replace(rows[1], symbol_name="$T85784")
        fixture["candidate"] = replace(
            fixture["candidate"],
            caller_definition=replace(definition, relocations=tuple(rows)),
        )
        with self.assertRaisesRegex(ValueError, "COFF relocation population"):
            self.prove(fixture)

    def test_stale_candidate_body_fails_closed(self) -> None:
        fixture = self.fixture()
        definition = fixture["candidate"].caller_definition
        assert definition is not None
        stale = bytearray(definition.data)
        stale[0x88] = 0x8B
        stale[0x89] = 0x01
        fixture["candidate"] = replace(
            fixture["candidate"],
            caller_definition=replace(definition, data=bytes(stale)),
        )
        with self.assertRaisesRegex(ValueError, "stale candidate body"):
            self.prove(fixture)

    def test_conflicting_storage_identity_fails_closed(self) -> None:
        fixture = self.fixture()
        fixture["indexes"] = replace(
            fixture["indexes"],
            storage_by_address={
                "0x56bd24": "storage:recoil:data:0x56bd20"
            },
        )
        with self.assertRaisesRegex(ValueError, "stack symbol, storage"):
            self.prove(fixture)

    def test_stale_relocation_target_fails_closed(self) -> None:
        fixture = self.fixture()
        definition = fixture["candidate"].caller_definition
        assert definition is not None
        rows = list(definition.relocations)
        rows[6] = CoffRelocation(
            rows[6].offset,
            rows[6].symbol_index,
            rows[6].type,
            "?g_HudUiChatMessageStack@@3PAUHudUiTextStack4@@A",
        )
        fixture["candidate"] = replace(
            fixture["candidate"],
            caller_definition=replace(definition, relocations=tuple(rows)),
        )
        with self.assertRaisesRegex(ValueError, "COFF relocation population"):
            self.prove(fixture)

    def test_stale_cod_call_offset_fails_closed(self) -> None:
        fixture = self.fixture()
        shifted = tuple(
            parse_assembly(
                "\n".join(
                    (
                        "0007c 8b 0d 00 00 00 00 mov ecx, dword "
                        "[?g_HudUiTopMessageStack@@3PAUHudUiTextStack4@@A]",
                        "00082 a1 00 00 00 00 mov eax, dword "
                        "[_g_Time_UnscaledDeltaTimeSec]",
                        "00087 50 push eax",
                        "00089 8b 11 mov edx, dword [ecx]",
                        "0008b ff 12 call dword [edx]",
                    )
                ),
                source="cod",
            )
        )
        fixture["candidate"] = replace(
            fixture["candidate"], instructions=shifted
        )
        with self.assertRaisesRegex(ValueError, "stack-call bytes"):
            self.prove(fixture)


