    def acquire_instructions(
        self,
        *,
        branch_displacement: int = 0x10,
        vptr_register: str = "ecx",
        receiver_register: str = "eax",
        call_slot: int = 0x1C,
        extra_row: str | None = None,
    ) -> tuple[Instruction, ...]:
        vptr_opcode = {"ecx": "08", "edx": "10"}[vptr_register]
        receiver_opcode = {"eax": "50", "ecx": "51"}[receiver_register]
        call_opcode = {"ecx": "51", "edx": "52"}[vptr_register]
        rows = [
            (
                "00000 a1 20 3f 00 00 mov eax, dword ptr "
                f"{self.aggregate_symbol}+16160"
            ),
            "00005 85 c0 test eax, eax",
            (
                f"00007 74 {branch_displacement:02x} "
                "je SHORT $L43509"
            ),
            (
                f"00009 8b {vptr_opcode} mov {vptr_register}, "
                "dword ptr [eax]"
            ),
            f"0000b {receiver_opcode} push {receiver_register}",
            (
                f"0000c ff {call_opcode} {call_slot:02x} call dword ptr "
                f"[{vptr_register}+{call_slot}]"
            ),
            "0000f 33 d2 xor edx, edx",
            "00011 85 c0 test eax, eax",
            "00013 0f 94 c2 sete dl",
            "00016 8b c2 mov eax, edx",
            "00018 c3 ret 0",
            "00019 33 c0 xor eax, eax",
            "0001b c3 ret 0",
        ]
        if extra_row is not None:
            rows.append(extra_row)
        return tuple(parse_assembly("\n".join(rows), source="cod"))

    def acquire_candidate(
        self,
        *,
        instructions: tuple[Instruction, ...] | None = None,
        target: SimpleNamespace | None = None,
        symbol: str | None = None,
        relocation_offset: int = 0x01,
        relocation_type: int = 0x06,
        relocation_symbol: str | None = None,
        relocation_addend: int = 0x3F20,
        relocation_mask: tuple[bool, ...] | None = None,
        section_index: int = 7,
        section_start: int = 0,
        section_end: int = 0x20,
        local_control_flow_indices: frozenset[int] = frozenset(),
        local_control_flow_targets: Mapping[int, tuple[int, ...]] | None = None,
    ) -> CandidateAssembly:
        instructions = instructions or self.acquire_instructions()
        body = bytearray(b"\x00" * 0x1C + b"\x90" * 4)
        for instruction in instructions:
            match = re.match(r"^\s*([0-9a-fA-F]+)", instruction.source_line)
            assert match is not None
            offset = int(match.group(1), 16)
            encoded = bytes(int(value, 16) for value in instruction.bytes)
            body[offset : offset + len(encoded)] = encoded
        struct.pack_into("<I", body, relocation_offset, relocation_addend)
        if relocation_mask is None:
            mask = [False] * len(body)
            mask[relocation_offset : relocation_offset + 4] = [True] * 4
            relocation_mask = tuple(mask)
        return CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=local_control_flow_indices,
            local_control_flow_targets=local_control_flow_targets or {},
            target=target or self.target(),
            caller_definition=CandidateCallerDefinition(
                symbol=symbol or self.acquire_symbol,
                data=bytes(body),
                relocations=(
                    CoffRelocation(
                        offset=relocation_offset,
                        symbol_index=1,
                        type=relocation_type,
                        symbol_name=(
                            relocation_symbol or self.aggregate_symbol
                        ),
                    ),
                ),
                relocation_mask=relocation_mask,
                undefined_external_functions=(),
                undefined_external_data=(self.aggregate_symbol,),
                section_index=section_index,
                section_start=section_start,
                section_end=section_end,
            ),
        )

