    def assert_cod_and_population_negatives(self) -> None:
        instructions = list(self.instructions())
        vptr_index = next(
            index
            for index, instruction in enumerate(instructions)
            if (
                re.match(
                    r"^\s*([0-9a-fA-F]+)",
                    instruction.source_line,
                )
                and int(
                    re.match(
                        r"^\s*([0-9a-fA-F]+)",
                        instruction.source_line,
                    ).group(1),
                    16,
                )
                == self.first_vptr_offset
            )
        )
        changed_vptr = list(instructions)
        changed_vptr[vptr_index] = replace(
            changed_vptr[vptr_index],
            raw_text="mov ecx, dword [edx]",
            text="mov ecx, dword [edx]",
        )
        clobber = list(instructions)
        clobber.insert(
            vptr_index,
            tuple(parse_assembly(
                f"{self.clobber_offset:05x} 33 c0 xor eax, eax",
                source="cod",
            ))[0],
        )
        incomplete = tuple(
            instruction
            for instruction in instructions
            if not instruction.raw_text.strip().startswith(self.omitted_call_text)
        )
        candidates = {
            "vptr": self.candidate(instructions=tuple(changed_vptr)),
            "clobber": self.candidate(instructions=tuple(clobber)),
            "population": self.candidate(instructions=incomplete),
        }
        for label, candidate in candidates.items():
            with self.subTest(label=label), self.assertRaises(ValueError):
                self.bridges(candidate=candidate)

    def direct_identities(self):
        raise NotImplementedError

    def expected(self):
        raise NotImplementedError

