class ZInputRuntimeDispatchBridgeTests(unittest.TestCase):
    """WSI-011 r4390 finite retail/candidate dispatch regression set."""

    module = call_contract_verify_module

    def indexes(self, **changes: object) -> IdentityIndexes:
        values = {
            "by_address": {},
            "by_candidate_name": {},
            "provider_ids": frozenset(),
            "storage_by_address": {
                "0x561c48": "storage:recoil:data:0x561c48",
                "0x561cc4": "storage:recoil:data:0x561cc4",
                "0x561cc8": "storage:recoil:data:0x561cc8",
                "0x565bc4": "storage:recoil:data:0x565bc4",
                "0x565bc8": "storage:recoil:data:0x565bc8",
                "0x561cd4": "storage:recoil:data:0x561cd4",
                "0x565ea0": "storage:recoil:data:0x565ea0",
                "0x561ccc": "storage:recoil:data:0x561ccc",
                "0x561cd0": "storage:recoil:data:0x561cd0",
            },
            "storage_by_name": {},
            "storage_containers": (
                StorageContainer(
                    start=0x561C48,
                    end_exclusive=0x561C4C,
                    identity="storage:recoil:data:0x561c48",
                ),
                StorageContainer(
                    start=0x561CC4,
                    end_exclusive=0x561CC8,
                    identity="storage:recoil:data:0x561cc4",
                ),
                StorageContainer(
                    start=0x561CC8,
                    end_exclusive=0x561CCC,
                    identity="storage:recoil:data:0x561cc8",
                ),
                StorageContainer(
                    start=0x561CCC,
                    end_exclusive=0x561CD0,
                    identity="storage:recoil:data:0x561ccc",
                ),
                StorageContainer(
                    start=0x561CD0,
                    end_exclusive=0x561CD4,
                    identity="storage:recoil:data:0x561cd0",
                ),
                StorageContainer(
                    start=0x565BC4,
                    end_exclusive=0x565BC8,
                    identity="storage:recoil:data:0x565bc4",
                ),
                StorageContainer(
                    start=0x565BC8,
                    end_exclusive=0x565BCC,
                    identity="storage:recoil:data:0x565bc8",
                ),
            ),
        }
        values.update(changes)
        return IdentityIndexes(**values)

    @staticmethod
    def retail_instructions(spec: Mapping[str, object]) -> tuple[Instruction, ...]:
        bodies = dict(spec["rows"])
        call_sites = tuple(spec["calls"])
        rows: list[Instruction] = []
        for address in sorted(set(bodies) | set(call_sites), key=lambda value: int(value, 16)):
            body = bodies.get(address, b"\xe8\x00\x00\x00\x00")
            if address in call_sites:
                tail = any(
                    row[0] == address and row[3] == "tail"
                    for row in spec.get("register_callbacks", ())
                )
                raw = "jmp edx" if tail else "call eax"
            else:
                raw = "mov eax, eax"
            rows.append(Instruction(
                text=raw,
                raw_text=raw,
                bytes=tuple(f"{value:02x}" for value in body),
                source_line=(
                    f"{int(address, 16):08x} {body.hex(' ')} {raw}"
                ),
            ))
        return tuple(rows)

    def test_exact_retail_routes_are_finite_targetless_and_index_derived(self) -> None:
        for start, spec in self.module.ZINPUT_RUNTIME_DISPATCH_RETAIL_SPECS.items():
            with self.subTest(start=start):
                register, vptr = (
                    self.module._zinput_runtime_dispatch_retail_bridges(
                        self.retail_instructions(spec),
                        caller_start=start,
                        caller_end_exclusive=spec["end"],
                        indexes=self.indexes(),
                    )
                )
                self.assertEqual(len(spec.get("register_callbacks", ())), len(register))
                self.assertEqual(len(spec.get("vptr", ())), len(vptr))
                self.assertTrue(all(row.target_identity == "" for row in vptr.values()))
                self.assertTrue(all(row.identity_kind == "callback" for row in register.values()))
                self.assertTrue(all(not row.storage_identity.startswith("iat:") for row in register.values()))
        poll_register, _ = self.module._zinput_runtime_dispatch_retail_bridges(
            self.retail_instructions(
                self.module.ZINPUT_RUNTIME_DISPATCH_RETAIL_SPECS["0x46f690"]
            ),
            caller_start="0x46f690",
            caller_end_exclusive="0x46f970",
            indexes=self.indexes(),
        )
        self.assertIn("storage:recoil:data:0x561cd4+0x4", poll_register["0x46f870"].storage_identity)

    def test_retail_bytes_population_extent_and_storage_drift_fail_closed(self) -> None:
        reset_spec = self.module.ZINPUT_RUNTIME_DISPATCH_RETAIL_SPECS["0x46f450"]
        self.assertIn(
            ("0x46f47d", bytes.fromhex("8b 08")), reset_spec["rows"]
        )
        self.assertNotIn(
            ("0x46f47e", bytes.fromhex("8b 08")), reset_spec["rows"]
        )
        shifted_reset = list(self.retail_instructions(reset_spec))
        reset_vptr_load_index = next(
            index
            for index, instruction in enumerate(shifted_reset)
            if instruction.source_line.startswith("0046f47d ")
        )
        reset_vptr_load = shifted_reset[reset_vptr_load_index]
        shifted_reset[reset_vptr_load_index] = replace(
            reset_vptr_load,
            source_line=reset_vptr_load.source_line.replace(
                "0046f47d ", "0046f47e ", 1
            ),
        )
        with self.assertRaisesRegex(
            ValueError,
            "retail bytes/neighbors drifted at 0x46f47d",
        ):
            self.module._zinput_runtime_dispatch_retail_bridges(
                tuple(shifted_reset),
                caller_start="0x46f450",
                caller_end_exclusive="0x46f690",
                indexes=self.indexes(),
            )

        for start, spec in self.module.ZINPUT_RUNTIME_DISPATCH_RETAIL_SPECS.items():
            base = self.retail_instructions(spec)
            for row_address, _ in spec["rows"]:
                changed = list(base)
                row_index = next(
                    index
                    for index, instruction in enumerate(changed)
                    if instruction.source_line.startswith(
                        f"{int(row_address, 16):08x} "
                    )
                )
                instruction = changed[row_index]
                first_byte = int(instruction.bytes[0], 16) ^ 1
                changed[row_index] = replace(
                    instruction,
                    bytes=(f"{first_byte:02x}", *instruction.bytes[1:]),
                )
                with self.subTest(
                    start=start, row=row_address, drift="bytes"
                ), self.assertRaisesRegex(
                    ValueError,
                    f"retail bytes/neighbors drifted at {row_address}",
                ):
                    self.module._zinput_runtime_dispatch_retail_bridges(
                        tuple(changed),
                        caller_start=start,
                        caller_end_exclusive=spec["end"],
                        indexes=self.indexes(),
                    )
            for call_address in spec["calls"]:
                changed = list(base)
                call_index = next(
                    index
                    for index, instruction in enumerate(changed)
                    if instruction.source_line.startswith(
                        f"{int(call_address, 16):08x} "
                    )
                )
                changed[call_index] = replace(
                    changed[call_index], text="nop", raw_text="nop"
                )
                with self.subTest(
                    start=start, row=call_address, drift="population"
                ), self.assertRaisesRegex(
                    ValueError,
                    "retail invocation population drifted",
                ):
                    self.module._zinput_runtime_dispatch_retail_bridges(
                        tuple(changed),
                        caller_start=start,
                        caller_end_exclusive=spec["end"],
                        indexes=self.indexes(),
                    )
            with self.subTest(
                start=start, drift="extent"
            ), self.assertRaisesRegex(
                ValueError, "requires the exact caller extent"
            ):
                self.module._zinput_runtime_dispatch_retail_bridges(
                    base,
                    caller_start=start,
                    caller_end_exclusive=hex(int(spec["end"], 16) - 1),
                    indexes=self.indexes(),
                )
            with self.subTest(
                start=start, drift="storage"
            ), self.assertRaisesRegex(
                ValueError, "requires unique tracker-backed authored storage"
            ):
                self.module._zinput_runtime_dispatch_retail_bridges(
                    base,
                    caller_start=start,
                    caller_end_exclusive=spec["end"],
                    indexes=self.indexes(storage_by_address={}),
                )

    def test_poll_logical_order_and_raw_memory_callback_replace_iat_shape(self) -> None:
        spec = self.module.ZINPUT_RUNTIME_DISPATCH_RETAIL_SPECS["0x46f690"]
        rows = [
            {
                "ordinal": ordinal,
                "form": "call",
                "dispatch": "indirect" if site == "0x46f7f5" else "direct",
                "identity_kind": "iat" if site == "0x46f7f5" else "direct",
                "target_identity": "iat:false" if site == "0x46f7f5" else site,
                "storage_identity": "iat:false" if site == "0x46f7f5" else "",
                "slot_displacement": 0x565BC4 if site == "0x46f7f5" else None,
                "cleanup_bytes": None,
            }
            for ordinal, site in enumerate(spec["calls"])
        ]
        normalized, sites = (
            self.module._zinput_runtime_dispatch_normalize_retail_contract(
                rows,
                spec["calls"],
                caller_start="0x46f690",
                indexes=self.indexes(),
            )
        )
        self.assertEqual(list(spec["logical_calls"]), sites)
        raw = normalized[sites.index("0x46f7f5")]
        self.assertEqual("callback", raw["identity_kind"])
        self.assertEqual("storage:recoil:data:0x565bc4", raw["storage_identity"])
        self.assertEqual("", raw["target_identity"])
        self.assertIsNone(raw["slot_displacement"])

    def test_non_callback_loads_preempt_only_the_finite_zero_callback_probe(self) -> None:
        expected = {
            "0x46f450": {
                "0x46f451": "storage:recoil:data:0x561cc4",
                "0x46f462": "storage:recoil:data:0x561cc8",
                "0x46f46e": "storage:recoil:data:0x561ccc",
                "0x46f495": "storage:recoil:data:0x561cc8",
                "0x46f4a4": "storage:recoil:data:0x561ccc",
                "0x46f4d7": "storage:recoil:data:0x561cd0",
                "0x46f4f8": "storage:recoil:data:0x561cd0",
                "0x46f519": "storage:recoil:data:0x561cd0",
                "0x46f537": "storage:recoil:data:0x561cd0",
                "0x46f546": "storage:recoil:data:0x561cd0",
                "0x46f554": "storage:recoil:data:0x561cd0",
            },
            "0x46f690": {
                "0x46f693": "storage:recoil:data:0x561cc8",
                "0x46f6a3": "storage:recoil:data:0x561ccc",
                "0x46f6d2": "storage:recoil:data:0x561cc8",
                "0x46f6e1": "storage:recoil:data:0x561ccc",
                "0x46f70f": "storage:recoil:data:0x561cd0",
                "0x46f733": "storage:recoil:data:0x561cd0",
                "0x46f751": "storage:recoil:data:0x561cd0",
                "0x46f76c": "storage:recoil:data:0x561cd0",
                "0x46f78b": "storage:recoil:data:0x561cd0",
                "0x46f79d": "storage:recoil:data:0x561cd0",
                "0x46f7af": "storage:recoil:data:0x561cd0",
                "0x46f7df": "storage:recoil:data:0x565bc4",
                "0x46f7ed": "storage:recoil:data:0x565bc8",
                "0x46f81d": "storage:recoil:data:0x561ccc",
            },
        }
        zero_bridge = SimpleNamespace(
            hexdump=lambda address, size: f"{int(address, 16):08x}: 00 00 00 00"
        )
        for start, published in expected.items():
            spec = self.module.ZINPUT_RUNTIME_DISPATCH_RETAIL_SPECS[start]
            with self.subTest(start=start):
                self.assertEqual(
                    published,
                    self.module
                    ._zinput_runtime_dispatch_non_callback_register_loads(
                        self.retail_instructions(spec),
                        caller_start=start,
                        caller_end_exclusive=spec["end"],
                        indexes=self.indexes(),
                        bridge=zero_bridge,
                        retail_import_targets=(),
                    ),
                )
        translate = parse_assembly(
            "0046fba0 a1 48 1c 56 00 mov eax, dword [0x561c48]\n"
            "0046fba5 56 push esi\n"
            "0046fba6 85 c0 test eax, eax\n"
            "0046fba8 8b f1 mov esi, ecx\n"
            "0046fbaa 75 0f jne 0x46fbbb\n"
            "0046fbac e8 6f 01 00 00 call 0x46fd20\n"
            "0046fbb1 c7 05 48 1c 56 00 01 00 00 00 "
            "mov dword [0x561c48], 1",
            source="bn",
        )
        self.assertEqual(
            {"0x46fba0": "storage:recoil:data:0x561c48"},
            self.module._zinput_runtime_dispatch_non_callback_register_loads(
                translate,
                caller_start="0x46fba0",
                caller_end_exclusive="0x46fd20",
                indexes=self.indexes(),
                bridge=zero_bridge,
                retail_import_targets=(),
            ),
        )
        drifted_translate = tuple(
            replace(
                row,
                bytes=tuple("02" if index == 6 else value for index, value in enumerate(row.bytes)),
            )
            if row.source_line.startswith("0046fbb1 ")
            else row
            for row in translate
        )
        with self.assertRaisesRegex(ValueError, "control topology drifted"):
            self.module._zinput_runtime_dispatch_non_callback_register_loads(
                drifted_translate,
                caller_start="0x46fba0",
                caller_end_exclusive="0x46fd20",
                indexes=self.indexes(),
                bridge=zero_bridge,
                retail_import_targets=(),
            )
        reset_spec = self.module.ZINPUT_RUNTIME_DISPATCH_RETAIL_SPECS["0x46f450"]
        with self.assertRaisesRegex(
            ValueError, "requires one exact storage container"
        ):
            self.module._zinput_runtime_dispatch_non_callback_register_loads(
                self.retail_instructions(reset_spec),
                caller_start="0x46f450",
                caller_end_exclusive=reset_spec["end"],
                indexes=self.indexes(storage_containers=()),
                bridge=zero_bridge,
                retail_import_targets=(),
            )
        reset_rows = self.retail_instructions(reset_spec)
        missing = tuple(
            row for row in reset_rows
            if not row.source_line.startswith("0046f451 ")
        )
        extra = (*reset_rows, Instruction(
            text="mov eax, dword [0x561cc4]",
            raw_text="mov eax, dword [0x561cc4]",
            bytes=("a1", "c4", "1c", "56", "00"),
            source_line="0046f45a a1 c4 1c 56 00 mov eax, dword [0x561cc4]",
        ))
        for rows, drift in ((missing, "missing"), (extra, "extra")):
            with self.subTest(drift=drift), self.assertRaisesRegex(
                ValueError, "census cardinality drifted"
            ):
                self.module._zinput_runtime_dispatch_non_callback_register_loads(
                    rows,
                    caller_start="0x46f450",
                    caller_end_exclusive=reset_spec["end"],
                    indexes=self.indexes(),
                    bridge=zero_bridge,
                    retail_import_targets=(),
                )
        with self.assertRaisesRegex(ValueError, "immutable import"):
            self.module._zinput_runtime_dispatch_non_callback_register_loads(
                reset_rows,
                caller_start="0x46f450",
                caller_end_exclusive=reset_spec["end"],
                indexes=self.indexes(),
                bridge=zero_bridge,
                retail_import_targets=(SimpleNamespace(address="0x561cc8"),),
            )
        with self.assertRaisesRegex(ValueError, "static callback"):
            self.module._zinput_runtime_dispatch_non_callback_register_loads(
                reset_rows,
                caller_start="0x46f450",
                caller_end_exclusive=reset_spec["end"],
                indexes=self.indexes(
                    reviewed_static_callback_target_by_storage={
                        "storage:recoil:data:0x561ccc": "symbol:callback"
                    }
                ),
                bridge=zero_bridge,
                retail_import_targets=(),
            )

        definition = next(
            instruction
            for instruction in self.retail_instructions(reset_spec)
            if instruction.source_line.startswith("0046f4a4 ")
        )
        with patch.object(
            self.module,
            "_retail_register_definition_transfer_addresses",
        ) as lineage:
            result = (
                self.module._comparison_scoped_retail_zero_callback_storage_indexes(
                    (definition,),
                    caller_start="0x46f4a4",
                    caller_end_exclusive="0x46f4a9",
                    indexes=self.indexes(),
                    bridge=SimpleNamespace(),
                    precomposed_non_callback_loads={
                        "0x46f4a4": "storage:recoil:data:0x561ccc"
                    },
                )
            )
            lineage.assert_not_called()
            self.assertEqual(self.indexes().storage_by_address, result.storage_by_address)
        with patch.object(
            self.module,
            "_retail_register_definition_transfer_addresses",
            side_effect=ValueError("generic lineage remains fail closed"),
        ):
            with self.assertRaisesRegex(
                ValueError, "generic lineage remains fail closed"
            ):
                self.module._comparison_scoped_retail_zero_callback_storage_indexes(
                    (definition,),
                    caller_start="0x46f4a4",
                    caller_end_exclusive="0x46f4a9",
                    indexes=self.indexes(),
                    bridge=SimpleNamespace(),
                )
        stored_bridge = SimpleNamespace(
            get_json=lambda *args, **kwargs: {},
            hexdump=lambda address, size: f"{int(address, 16):08x}: 00 00 00 00",
        )
        with patch.object(
            self.module,
            "_retail_register_definition_transfer_addresses",
        ) as lineage:
            self.module._comparison_scoped_retail_stored_callback_targets(
                (definition,),
                caller_start="0x46f4a4",
                caller_end_exclusive="0x46f4a9",
                indexes=self.indexes(),
                bridge=stored_bridge,
                precomposed_non_callback_loads={
                    "0x46f4a4": "storage:recoil:data:0x561ccc"
                },
            )
            lineage.assert_not_called()
        with patch.object(
            self.module,
            "_retail_register_definition_transfer_addresses",
            side_effect=ValueError(
                "generic stored-callback lineage remains fail closed"
            ),
        ):
            with self.assertRaisesRegex(
                ValueError, "generic stored-callback lineage remains fail closed"
            ):
                self.module._comparison_scoped_retail_stored_callback_targets(
                    (definition,),
                    caller_start="0x46f4a4",
                    caller_end_exclusive="0x46f4a9",
                    indexes=self.indexes(),
                    bridge=stored_bridge,
                )
        modrm_definition = next(
            instruction
            for instruction in reset_rows
            if instruction.source_line.startswith("0046f4d7 ")
        )
        with patch.object(
            self.module,
            "_retail_register_definition_transfer_addresses",
        ) as lineage:
            self.module._comparison_scoped_retail_register_iat_indexes(
                (modrm_definition,),
                document=MagicMock(),
                caller_identity="symbol:recoil:function:0x46f450",
                caller_start="0x46f4d7",
                caller_end_exclusive="0x46f4dd",
                indexes=self.indexes(),
                retail_import_targets=(),
                precomposed_non_iat_loads={
                    "0x46f4d7": "storage:recoil:data:0x561cd0"
                },
            )
            lineage.assert_not_called()
        with patch.object(
            self.module,
            "_retail_register_definition_transfer_addresses",
        ) as lineage:
            unchanged = (
                self.module._comparison_scoped_retail_register_iat_indexes(
                    (modrm_definition,),
                    document=MagicMock(),
                    caller_identity="symbol:recoil:function:0x46f450",
                    caller_start="0x46f4d7",
                    caller_end_exclusive="0x46f4dd",
                    indexes=self.indexes(),
                    retail_import_targets=(),
                )
            )
            lineage.assert_not_called()
        self.assertEqual({}, unchanged.reviewed_retail_iat_load_proofs)

    def test_poll_candidate_register_callbacks_require_exact_cod_coff_rows(self) -> None:
        spec = self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS["0x46f690"]
        body = bytearray(spec["candidate_size"])
        renderings = {
            0x189: "mov eax, DWORD PTR _g_zInput_GlobalStateStorage+16148",
            0x18E: "test eax, eax",
            0x190: "je SHORT $L43574",
            0x192: "mov ebx, DWORD PTR _g_zInput_GlobalStateStorage+16152",
            0x198: "mov esi, eax",
            0x19A: (
                "call ?Keyboard_TranslateDikToAscii@zInput@@YIHH@Z ; "
                "zInput::Keyboard_TranslateDikToAscii"
            ),
            0x19F: "mov ecx, eax",
            0x1A1: "mov edx, ebx",
            0x1A3: "call esi",
            0x20C: (
                "mov eax, DWORD PTR "
                "_g_zInput_GlobalStateStorage[esi*8+40]"
            ),
            0x213: "test eax, eax",
            0x215: "je SHORT $L43579",
            0x217: (
                "test BYTE PTR "
                "_g_zInput_GlobalStateStorage[esi*8+36], 1"
            ),
            0x21F: "je SHORT $L43579",
            0x221: "mov ecx, esi",
            0x223: "call eax",
        }
        instructions = []
        for _role, offset, encoded, _pattern in spec["callback_rows"]:
            body[offset : offset + len(encoded)] = encoded
            raw = renderings[offset]
            instructions.append(Instruction(
                text=raw,
                raw_text=raw,
                bytes=tuple(f"{value:02x}" for value in encoded),
                source_line=f"{offset:05x} {encoded.hex(' ')} {raw}",
            ))
        for offset, encoded, raw in (
            (0x1B5, bytes.fromhex("8b 54 24 14"), "mov edx, dword [esp+0x14]"),
            (0x23A, bytes.fromhex("45"), "inc ebp"),
        ):
            body[offset : offset + len(encoded)] = encoded
            instructions.append(Instruction(
                text=raw,
                raw_text=raw,
                bytes=tuple(f"{value:02x}" for value in encoded),
                source_line=f"{offset:05x} {encoded.hex(' ')} {raw}",
            ))
        instructions.sort(
            key=lambda row: int(row.source_line.split()[0], 16)
        )
        relocations = tuple(
            CoffRelocation(
                offset=offset,
                symbol_index=index + 1,
                type=relocation_type,
                symbol_name=symbol,
            )
            for index, (
                offset,
                relocation_type,
                symbol,
                _addend,
            ) in enumerate(spec["callback_relocations"])
        )
        mask = [False] * len(body)
        for offset, _type, _symbol, addend in spec["callback_relocations"]:
            body[offset : offset + 4] = struct.pack("<I", addend)
            mask[offset : offset + 4] = [True] * 4
        candidate = CandidateAssembly(
            instructions=tuple(instructions),
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
            caller_definition=CandidateCallerDefinition(
                symbol=spec["symbol"], data=bytes(body),
                relocations=relocations,
                relocation_mask=tuple(mask),
                undefined_external_functions=(), undefined_external_data=(),
                section_index=spec["section"], section_start=0,
                section_end=spec["candidate_size"],
            ),
        )
        bridges = self.module._zinput_runtime_dispatch_candidate_register_bridges(
            candidate, caller_start="0x46f690", indexes=self.indexes()
        )
        self.assertEqual({"0x1a3", "0x223"}, set(bridges))
        self.assertEqual("storage:recoil:data:0x565bc4", bridges["0x1a3"].storage_identity)
        self.assertEqual(
            "load(indexed(storage:recoil:data:0x561cd4+0x4,stride=0x4))",
            bridges["0x223"].storage_identity,
        )
        self.assertEqual(
            (
                0x189, 0x18E, 0x190, 0x192, 0x198, 0x19A, 0x19F,
                0x1A1, 0x1A3, 0x20C, 0x213, 0x215, 0x217, 0x21F,
                0x221, 0x223,
            ),
            tuple(row[1] for row in spec["callback_rows"]),
        )

        renamed_labels = tuple(
            replace(
                instruction,
                text=(
                    "je SHORT $L99001"
                    if int(instruction.source_line.split()[0], 16) == 0x190
                    else "je SHORT $L99002"
                ),
                raw_text=(
                    "je SHORT $L99001"
                    if int(instruction.source_line.split()[0], 16) == 0x190
                    else "je SHORT $L99002"
                ),
            )
            if int(instruction.source_line.split()[0], 16)
            in {0x190, 0x215, 0x21F}
            else instruction
            for instruction in candidate.instructions
        )
        self.assertEqual(
            {"0x1a3", "0x223"},
            set(self.module._zinput_runtime_dispatch_candidate_register_bridges(
                replace(candidate, instructions=renamed_labels),
                caller_start="0x46f690",
                indexes=self.indexes(),
            )),
        )
        alias_drift = tuple(
            replace(
                instruction,
                text="je SHORT $L99003",
                raw_text="je SHORT $L99003",
            )
            if int(instruction.source_line.split()[0], 16) == 0x21F
            else instruction
            for instruction in renamed_labels
        )
        with self.assertRaisesRegex(ValueError, "alias partition"):
            self.module._zinput_runtime_dispatch_candidate_register_bridges(
                replace(candidate, instructions=alias_drift),
                caller_start="0x46f690",
                indexes=self.indexes(),
            )

        changed = bytearray(body)
        changed[0x20C] ^= 1
        with self.assertRaisesRegex(ValueError, "COD/COFF bytes"):
            self.module._zinput_runtime_dispatch_candidate_register_bridges(
                replace(candidate, caller_definition=replace(
                    candidate.caller_definition, data=bytes(changed)
                )),
                caller_start="0x46f690", indexes=self.indexes(),
            )

        register_drift = tuple(
            replace(
                instruction,
                text="mov edi, eax",
                raw_text="mov edi, eax",
            )
            if int(instruction.source_line.split()[0], 16) == 0x198
            else instruction
            for instruction in candidate.instructions
        )
        with self.assertRaisesRegex(ValueError, "registers"):
            self.module._zinput_runtime_dispatch_candidate_register_bridges(
                replace(candidate, instructions=register_drift),
                caller_start="0x46f690", indexes=self.indexes(),
            )

        old_coordinate = tuple(
            replace(
                instruction,
                source_line=instruction.source_line.replace(
                    "00189", "00185", 1
                ),
            )
            if int(instruction.source_line.split()[0], 16) == 0x189
            else instruction
            for instruction in candidate.instructions
        )
        with self.assertRaisesRegex(ValueError, "old coordinate"):
            self.module._zinput_runtime_dispatch_candidate_register_bridges(
                replace(candidate, instructions=old_coordinate),
                caller_start="0x46f690", indexes=self.indexes(),
            )

        missing = tuple(
            instruction
            for instruction in candidate.instructions
            if int(instruction.source_line.split()[0], 16) != 0x192
        )
        with self.assertRaisesRegex(ValueError, "missing, extra"):
            self.module._zinput_runtime_dispatch_candidate_register_bridges(
                replace(candidate, instructions=missing),
                caller_start="0x46f690", indexes=self.indexes(),
            )

        extra = tuple(sorted(
            (
                *candidate.instructions,
                Instruction(
                    text="nop",
                    raw_text="nop",
                    bytes=("90",),
                    source_line="00191 90 nop",
                ),
            ),
            key=lambda instruction: int(
                instruction.source_line.split()[0], 16
            ),
        ))
        with self.assertRaisesRegex(ValueError, "missing, extra"):
            self.module._zinput_runtime_dispatch_candidate_register_bridges(
                replace(candidate, instructions=extra),
                caller_start="0x46f690", indexes=self.indexes(),
            )

        storage_drift = replace(
            candidate.caller_definition,
            relocations=(
                replace(relocations[0], symbol_name="_wrong_storage"),
                *relocations[1:],
            ),
        )
        with self.assertRaisesRegex(ValueError, "storage relocation"):
            self.module._zinput_runtime_dispatch_candidate_register_bridges(
                replace(candidate, caller_definition=storage_drift),
                caller_start="0x46f690", indexes=self.indexes(),
            )

        callsite_specs = deepcopy(
            self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS
        )
        callsite_specs["0x46f690"]["register_callbacks"] = (
            (0x1A4, "esi", "raw", "call"),
            (0x223, "eax", "key-table", "call"),
        )
        with patch.object(
            self.module,
            "ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS",
            callsite_specs,
        ), self.assertRaisesRegex(ValueError, "role partition"):
            self.module._zinput_runtime_dispatch_candidate_register_bridges(
                candidate,
                caller_start="0x46f690", indexes=self.indexes(),
            )

        role_specs = deepcopy(
            self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS
        )
        role_rows = list(role_specs["0x46f690"]["callback_rows"])
        role_rows[0] = ("indexed-key-callback", *role_rows[0][1:])
        role_specs["0x46f690"]["callback_rows"] = tuple(role_rows)
        with patch.object(
            self.module,
            "ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS",
            role_specs,
        ), self.assertRaisesRegex(ValueError, "role partition"):
            self.module._zinput_runtime_dispatch_candidate_register_bridges(
                candidate,
                caller_start="0x46f690", indexes=self.indexes(),
            )

    def _runtime_candidate_provenance_fixture(
        self,
        start: str,
    ) -> tuple[ProgressDocument, IdentityIndexes, CandidateAssembly]:
        base = ZInputKeyboardAggregateLeafCandidateBridgeTests(
            methodName="test_exact_keyboard_bridge_and_generic_negative"
        )
        document = base.document()
        spec = self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[start]
        caller_identity = f"symbol:recoil:function:{start}"
        symbols = document.collection("symbols")
        del symbols[base.caller_identity.removeprefix("symbol:")]
        symbols[caller_identity.removeprefix("symbol:")] = {
            "address": start,
            "authored_order_role": "authored-body",
            "binary": "recoil",
            "end_exclusive": spec["end"],
            "extent_state": "known",
            "kind": "function",
            "navigation_name": spec["name"],
            "output_section_id": "recoil:section:.text",
            "ownership_state": "primary-owned",
            "physical_block_id": "recoil:block:0x46f300",
            "pipeline_class": "authored",
            "size": spec["retail_size"],
            "source_traceability": {
                "state": "resolved",
                "reason_code": None,
                "source_edges": [{
                    "relation": "defines",
                    "anchor_id": spec["anchor"],
                    "emission_context": {
                        "translation_unit": base.source_path,
                    },
                }],
            },
        }
        base_indexes = base.indexes()
        by_address = dict(base_indexes.by_address)
        del by_address[base.caller_start]
        by_address.update({
            start: caller_identity,
            "0x472490": "symbol:recoil:function:0x472490",
            "0x46fba0": "symbol:recoil:function:0x46fba0",
        })
        by_candidate_name = dict(base_indexes.by_candidate_name)
        del by_candidate_name[base.caller_symbol]
        by_candidate_name[spec["symbol"]] = caller_identity
        by_candidate_name.update({
            alias: caller_identity for alias in spec["candidate_aliases"]
        })
        storage_by_address = dict(base_indexes.storage_by_address)
        storage_by_address.update({
            "0x565bc4": "storage:recoil:data:0x565bc4",
            "0x565bc8": "storage:recoil:data:0x565bc8",
            "0x561cd4": "storage:recoil:data:0x561cd4",
        })
        indexes = replace(
            base_indexes,
            by_address=by_address,
            by_candidate_name=by_candidate_name,
            storage_by_address=storage_by_address,
        )
        candidate = CandidateAssembly(
            instructions=(),
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
        )
        return document, indexes, candidate

    def _invoke_runtime_candidate_provenance(
        self,
        start: str,
        *,
        document: ProgressDocument | None = None,
        indexes: IdentityIndexes | None = None,
    ) -> None:
        fixture_document, fixture_indexes, candidate = (
            self._runtime_candidate_provenance_fixture(start)
        )
        spec = self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[start]
        self.module._zinput_keyboard_aggregate_leaf_candidate_bridges(
            [],
            candidate,
            document=document or fixture_document,
            caller_identity=f"symbol:recoil:function:{start}",
            caller_start=start,
            caller_end_exclusive=spec["end"],
            indexes=indexes or fixture_indexes,
        )

    def _assert_runtime_provenance_reaches_candidate_gate(
        self,
        start: str,
    ) -> None:
        with self.assertRaisesRegex(ValueError, "exact registered target"):
            self._invoke_runtime_candidate_provenance(start)

    def test_runtime_candidate_provenance_accepts_only_reviewed_name_sets(
        self,
    ) -> None:
        for start in ("0x46f450", "0x46f690", "0x46fa10"):
            with self.subTest(start=start):
                self._assert_runtime_provenance_reaches_candidate_gate(start)

        reset_document, reset_indexes, _candidate = (
            self._runtime_candidate_provenance_fixture("0x46f450")
        )
        reset_identity = "symbol:recoil:function:0x46f450"
        reset_fastcall = "?Keyboard_ResetTransitionState@zInput@@YIXXZ"
        missing = dict(reset_indexes.by_candidate_name)
        del missing[reset_fastcall]
        extra = dict(reset_indexes.by_candidate_name)
        extra["?Keyboard_ResetTransitionState@zInput@@YQXXZ"] = (
            reset_identity
        )
        for label, names in (("missing", missing), ("extra", extra)):
            with self.subTest(reset_alias=label), self.assertRaisesRegex(
                ValueError,
                "same-owner provenance",
            ):
                self._invoke_runtime_candidate_provenance(
                    "0x46f450",
                    document=reset_document,
                    indexes=replace(
                        reset_indexes,
                        by_candidate_name=names,
                    ),
                )

        for start in ("0x46f690", "0x46fa10"):
            document, indexes, _candidate = (
                self._runtime_candidate_provenance_fixture(start)
            )
            names = dict(indexes.by_candidate_name)
            names[f"?unexpected_alias_{start}"] = (
                f"symbol:recoil:function:{start}"
            )
            with self.subTest(extra_alias=start), self.assertRaisesRegex(
                ValueError,
                "same-owner provenance",
            ):
                self._invoke_runtime_candidate_provenance(
                    start,
                    document=document,
                    indexes=replace(indexes, by_candidate_name=names),
                )

    def test_runtime_candidate_provenance_field_drift_fails_closed(self) -> None:
        start = "0x46f450"
        identity = "recoil:function:0x46f450"
        mutations: list[tuple[str, ProgressDocument, IdentityIndexes]] = []

        document, indexes, _candidate = (
            self._runtime_candidate_provenance_fixture(start)
        )
        document.collection("symbols")[identity]["size"] += 1
        mutations.append(("caller", document, indexes))

        document, indexes, _candidate = (
            self._runtime_candidate_provenance_fixture(start)
        )
        document.collection("symbols")[identity]["source_traceability"][
            "source_edges"
        ][0]["anchor_id"] = "recoil:anchor:wrong"
        mutations.append(("trace", document, indexes))

        document, indexes, _candidate = (
            self._runtime_candidate_provenance_fixture(start)
        )
        document.collection("storage_contributions")[
            self.module.ZINPUT_JOYSTICK_AGGREGATE_STORAGE_ID
        ]["owner_ids"] = ["recoil:owner:wrong"]
        mutations.append(("aggregate-owner", document, indexes))

        document, indexes, _candidate = (
            self._runtime_candidate_provenance_fixture(start)
        )
        document.collection("storage_contributions")[
            self.module.ZINPUT_KEYBOARD_DEVICE_STORAGE_ID
        ]["owner_ids"] = ["recoil:owner:wrong"]
        mutations.append(("leaf-owner", document, indexes))

        document, indexes, _candidate = (
            self._runtime_candidate_provenance_fixture(start)
        )
        mutations.append((
            "storage-collision",
            document,
            replace(
                indexes,
                storage_by_address={
                    **indexes.storage_by_address,
                    self.module.ZINPUT_KEYBOARD_DEVICE_ADDRESS: (
                        "storage:recoil:data:0x561cb0"
                    ),
                },
            ),
        ))

        for label, document, indexes in mutations:
            with self.subTest(field=label), self.assertRaisesRegex(
                ValueError,
                "same-owner provenance",
            ):
                self._invoke_runtime_candidate_provenance(
                    start,
                    document=document,
                    indexes=indexes,
                )

    def _runtime_switch_candidate(
        self,
        start: str,
        *,
        relational_names: dict[str, str] | None = None,
    ) -> CandidateAssembly:
        spec = self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[start]
        switch = spec["switch"]
        assert switch is not None
        if switch.get("relational_labels"):
            default_names = {
                "0x46f450": {
                    "classifier": "$L44905",
                    "table": "$L44906",
                    "control": "$L43546",
                    "shift": "$L43549",
                    "alt": "$L43543",
                    "default": "$L43552",
                },
                "0x46f690": {
                    "classifier": "$L44958",
                    "table": "$L44959",
                    "control": "$L44925",
                    "shift": "$L44926",
                    "alt": "$L44924",
                    "default": "$L44927",
                },
            }
            names = relational_names or default_names[start]
            target_name_by_role = {
                "control-case": names["control"],
                "shift-case": names["shift"],
                "alt-case": names["alt"],
                "default-case": names["default"],
            }
            table_names = tuple(
                target_name_by_role[role]
                for role, _target in switch["table_targets"]
            )
            renderings = {
                "0x46f450": (
                    "cmp ecx, 155",
                    f"ja SHORT {names['default']}",
                    f"mov dl, BYTE PTR {names['classifier']}[ecx]",
                    f"jmp DWORD PTR {names['table']}[edx*4]",
                ),
                "0x46f690": (
                    "cmp esi, 155",
                    f"ja {names['default']}",
                    f"mov dl, BYTE PTR {names['classifier']}[esi]",
                    f"jmp DWORD PTR {names['table']}[edx*4]",
                ),
            }[start]
            relocation_names = (
                names["classifier"], names["table"], *table_names
            )
            symbol_values = {
                names["classifier"]: switch["classifier_offset"],
                names["table"]: switch["table_offset"],
                **{
                    target_name_by_role[role]: target
                    for role, target in switch["table_targets"]
                },
            }
        else:
            raise AssertionError("runtime switch fixture requires relational labels")
        instructions = [
            Instruction(
                text=rendering,
                raw_text=rendering,
                bytes=tuple(f"{value:02x}" for value in body),
                source_line=(
                    f"{offset:05x} {body.hex(' ')} {rendering}"
                ),
            )
            for (offset, body, _pattern), rendering in zip(
                switch["rows"], renderings
            )
        ]
        present = {row[0] for row in switch["rows"]}
        for _name, target in switch["table_targets"]:
            if target in present:
                continue
            instructions.append(Instruction(
                text="nop",
                raw_text="nop",
                bytes=("90",),
                source_line=f"{target:05x} 90 nop",
            ))
            present.add(target)
        for index, target_name in enumerate(table_names):
            offset = switch["table_offset"] + index * 4
            instructions.append(Instruction(
                text=target_name,
                raw_text=target_name,
                bytes=("00", "00", "00", "00", "dd"),
                source_line=f"{offset:05x} 00 00 00 00 {target_name}",
            ))
        for index, value in enumerate(
            self.module.ZINPUT_KEYBOARD_SWITCH_CLASSIFIER
        ):
            offset = switch["classifier_offset"] + index
            instructions.append(Instruction(
                text=str(value),
                raw_text=str(value),
                bytes=(f"{value:02x}", "db"),
                source_line=f"{offset:05x} {value:02x} {value}",
            ))
        padding = switch.get("padding")
        if padding is not None:
            offset, encoded, rendering = padding
            rendering = "npad 2"
            instructions.append(Instruction(
                text=rendering,
                raw_text=rendering,
                bytes=tuple(f"{value:02x}" for value in encoded),
                source_line=f"{offset:05x} {encoded.hex(' ')} {rendering}",
            ))
        instructions.sort(
            key=lambda row: int(row.source_line.split()[0], 16)
        )

        body = bytearray(spec["candidate_size"])
        for instruction in instructions:
            offset = int(instruction.source_line.split()[0], 16)
            encoded_items = (
                instruction.bytes[:-1]
                if instruction.bytes[-1:] in {("dd",), ("db",)}
                else instruction.bytes
            )
            encoded = bytes(int(value, 16) for value in encoded_items)
            body[offset : offset + len(encoded)] = encoded
        classifier_offset = switch["classifier_offset"]
        body[
            classifier_offset:
            classifier_offset
            + len(self.module.ZINPUT_KEYBOARD_SWITCH_CLASSIFIER)
        ] = self.module.ZINPUT_KEYBOARD_SWITCH_CLASSIFIER
        relocation_offsets = (
            switch["classifier_load_relocation"][0],
            switch["dispatch_relocation"][0],
            *(
                switch["table_offset"] + index * 4
                for index in range(len(switch["table_targets"]))
            ),
        )
        symbol_index_by_name = {
            name: index + 100
            for index, name in enumerate(dict.fromkeys(relocation_names))
        }
        relocations = [
            CoffRelocation(
                offset=offset,
                symbol_index=symbol_index_by_name[symbol],
                type=0x06,
                symbol_name=symbol,
            )
            for offset, symbol in zip(relocation_offsets, relocation_names)
        ]
        coff_symbols = tuple(
            CandidateCoffSymbolDefinition(
                index=symbol_index_by_name[name],
                name=name,
                value=value,
                section_number=spec["section"],
                symbol_type=0,
                storage_class=6,
                aux_count=0,
                weak_external_tag_index=None,
                weak_external_characteristics=None,
                section_name=".text",
                section_size=spec["candidate_size"],
                section_characteristics=0x60001020,
                natural_end=spec["candidate_size"],
            )
            for name, value in symbol_values.items()
        )
        mask = [False] * len(body)
        for relocation in relocations:
            mask[relocation.offset : relocation.offset + 4] = [True] * 4
        return CandidateAssembly(
            instructions=tuple(instructions),
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
            caller_definition=CandidateCallerDefinition(
                symbol=spec["symbol"],
                data=bytes(body),
                relocations=tuple(relocations),
                relocation_mask=tuple(mask),
                undefined_external_functions=(),
                undefined_external_data=(),
                coff_symbols=coff_symbols,
                section_index=spec["section"],
                section_start=0,
                section_end=spec["candidate_size"],
            ),
        )

    def test_runtime_candidate_complete_chain_and_switch_census(self) -> None:
        self.assertEqual(
            (
                (0x12, 0x2D, 0x32, 0x33, "ecx", 0x28),
                (0x45, 0x4B, 0x4A, 0x4D, "ecx", 0x1C),
            ),
            self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[
                "0x46f450"
            ]["leaf_calls"],
        )
        self.assertEqual(
            (
                (0x03, 0x25, 0x2A, 0x2B, "ecx", 0x28),
                (0x52, 0x58, 0x57, 0x5A, "ecx", 0x1C),
            ),
            self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[
                "0x46f690"
            ]["leaf_calls"],
        )
        self.assertEqual(
            (
                (0x21, 0x33, 0x37, 0x38, "ecx", 0x28),
                (0x4A, 0x50, 0x4F, 0x52, "ecx", 0x1C),
            ),
            self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[
                "0x46fa10"
            ]["leaf_calls"],
        )
        self.assertEqual(
            {
                "0x46f450": (0, 1),
                "0x46f690": (0, 2),
                "0x46fa10": (0, 1),
            },
            self.module.ZINPUT_RUNTIME_AGGREGATE_LEAF_LOGICAL_ORDINALS,
        )
        self.assertEqual(156, len(
            self.module.ZINPUT_KEYBOARD_SWITCH_CLASSIFIER
        ))
        for start in ("0x46f450", "0x46f690"):
            candidate = self._runtime_switch_candidate(start)
            switch = self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[
                start
            ]["switch"]
            result, data_indices = (
                self.module._zinput_exact_candidate_switch_successors(
                candidate,
                switch,
                label=f"test {start}",
                )
            )
            offsets = self.module._candidate_complete_instruction_offsets(
                candidate
            )
            self.assertEqual(1, len(result))
            self.assertEqual(
                163 + (1 if switch.get("padding") is not None else 0),
                len(data_indices),
            )
            self.assertEqual(
                {target for _name, target in switch["table_targets"]},
                {offsets[index] for index in next(iter(result.values()))},
            )

    def test_reset_switch_accepts_renumbered_labels_but_rejects_role_drift(
        self,
    ) -> None:
        switch = self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[
            "0x46f450"
        ]["switch"]
        renamed = {
            "classifier": "$L99001",
            "table": "$L99002",
            "control": "$L88001",
            "shift": "$L88002",
            "alt": "$L88003",
            "default": "$L88004",
        }
        candidate = self._runtime_switch_candidate(
            "0x46f450", relational_names=renamed
        )
        result, _data = self.module._zinput_exact_candidate_switch_successors(
            candidate, switch, label="renumbered reset"
        )
        self.assertEqual(1, len(result))

        assert candidate.caller_definition is not None
        definition = candidate.caller_definition
        control_symbol = next(
            symbol
            for symbol in definition.coff_symbols
            if symbol.name == renamed["control"]
        )
        control_relocation = next(
            relocation
            for relocation in definition.relocations
            if relocation.offset == switch["table_offset"]
        )
        mutations = {
            "symbol-value": replace(
                definition,
                coff_symbols=tuple(
                    replace(symbol, value=symbol.value + 1)
                    if symbol.name == renamed["control"]
                    else symbol
                    for symbol in definition.coff_symbols
                ),
            ),
            "symbol-index": replace(
                definition,
                relocations=tuple(
                    replace(relocation, symbol_index=control_symbol.index + 1)
                    if relocation is control_relocation
                    else relocation
                    for relocation in definition.relocations
                ),
            ),
            "symbol-class": replace(
                definition,
                coff_symbols=tuple(
                    replace(symbol, storage_class=3)
                    if symbol.name == renamed["control"]
                    else symbol
                    for symbol in definition.coff_symbols
                ),
            ),
        }
        for drift, mutated in mutations.items():
            with self.subTest(drift=drift), self.assertRaisesRegex(
                ValueError, "relational label"
            ):
                self.module._zinput_exact_candidate_switch_successors(
                    replace(candidate, caller_definition=mutated),
                    switch,
                    label="renumbered reset",
                )

        colliding = dict(renamed)
        colliding["default"] = colliding["control"]
        with self.assertRaisesRegex(ValueError, "relational label"):
            self.module._zinput_exact_candidate_switch_successors(
                self._runtime_switch_candidate(
                    "0x46f450", relational_names=colliding
                ),
                switch,
                label="colliding reset",
            )

    def test_runtime_leaf_logical_ordinal_population_fails_closed(
        self,
    ) -> None:
        occupied = {
            "0x46f450": (2,),
            "0x46f690": (1, 3, 4, 5),
            "0x46fa10": (2,),
        }
        expected = {
            "0x46f450": (0, 1),
            "0x46f690": (0, 2),
            "0x46fa10": (0, 1),
        }
        for start, ordinals in expected.items():
            with self.subTest(start=start):
                self.assertEqual(
                    ordinals,
                    self.module
                    ._zinput_runtime_aggregate_leaf_logical_ordinals(
                        start,
                        leaf_count=2,
                        invocation_count=len(ordinals) + len(occupied[start]),
                        occupied_ordinals=occupied[start],
                    ),
                )

        base = dict(
            self.module.ZINPUT_RUNTIME_AGGREGATE_LEAF_LOGICAL_ORDINALS
        )
        mutations = {
            "missing": (
                {key: value for key, value in base.items() if key != "0x46f690"},
                "missing",
            ),
            "duplicate": ({**base, "0x46f690": (0, 0)}, "duplicate"),
            "out-of-range": (
                {**base, "0x46f690": (0, 6)},
                "out of range",
            ),
            "direct-row-overlap": (
                {**base, "0x46f690": (0, 1)},
                "overlaps a direct/callback row",
            ),
            "cardinality": (
                {**base, "0x46f690": (0,)},
                "cardinality",
            ),
        }
        for label, (population, message) in mutations.items():
            with self.subTest(drift=label), patch.object(
                self.module,
                "ZINPUT_RUNTIME_AGGREGATE_LEAF_LOGICAL_ORDINALS",
                population,
            ), self.assertRaisesRegex(ValueError, message):
                self.module._zinput_runtime_aggregate_leaf_logical_ordinals(
                    "0x46f690",
                    leaf_count=2,
                    invocation_count=6,
                    occupied_ordinals=occupied["0x46f690"],
                )

        with self.assertRaisesRegex(ValueError, "missing a caller row"):
            self.module._zinput_runtime_aggregate_leaf_logical_ordinals(
                "0x46f690",
                leaf_count=2,
                invocation_count=6,
                occupied_ordinals=(1, 3, 4),
            )

    def test_runtime_candidate_switch_every_row_and_offset_drift(self) -> None:
        for start in ("0x46f450", "0x46f690"):
            exact = self._runtime_switch_candidate(start)
            switch = self.module.ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[
                start
            ]["switch"]
            assert exact.caller_definition is not None
            for row_offset, _body, _pattern in switch["rows"]:
                changed = tuple(
                    replace(
                        instruction,
                        bytes=(
                            f"{int(instruction.bytes[0], 16) ^ 1:02x}",
                            *instruction.bytes[1:],
                        ),
                    )
                    if int(instruction.source_line.split()[0], 16)
                    == row_offset
                    else instruction
                    for instruction in exact.instructions
                )
                with self.subTest(start=start, row=hex(row_offset)), (
                    self.assertRaisesRegex(ValueError, "COD/COFF row")
                ):
                    self.module._zinput_exact_candidate_switch_successors(
                        replace(exact, instructions=changed),
                        switch,
                        label=f"test {start}",
                    )

            definition = exact.caller_definition
            classifier = bytearray(definition.data)
            classifier[switch["classifier_offset"]] ^= 1
            table = bytearray(definition.data)
            table[switch["table_offset"]] ^= 1
            mutations = {
                "classifier": replace(definition, data=bytes(classifier)),
                "table": replace(definition, data=bytes(table)),
                "relocation-type": replace(
                    definition,
                    relocations=(
                        replace(definition.relocations[0], type=0x14),
                        *definition.relocations[1:],
                    ),
                ),
                "relocation-symbol": replace(
                    definition,
                    relocations=(
                        replace(
                            definition.relocations[1],
                            symbol_name="$Lwrong",
                        ),
                        *definition.relocations[:1],
                        *definition.relocations[2:],
                    ),
                ),
                "relocation-missing": replace(
                    definition,
                    relocations=definition.relocations[:-1],
                ),
                "mask": replace(
                    definition,
                    relocation_mask=(
                        *definition.relocation_mask[:
                            switch["table_offset"]
                        ],
                        False,
                        *definition.relocation_mask[
                            switch["table_offset"] + 1:
                        ],
                    ),
                ),
            }
            for label, mutation in mutations.items():
                with self.subTest(start=start, drift=label), (
                    self.assertRaises(ValueError)
                ):
                    self.module._zinput_exact_candidate_switch_successors(
                        replace(exact, caller_definition=mutation),
                        switch,
                        label=f"test {start}",
                    )

    def test_runtime_switch_package_reaches_all_candidate_extractors(
        self,
    ) -> None:
        for start in ("0x46f450", "0x46f690"):
            candidate = self._runtime_switch_candidate(start)
            composed, reviewed_indices = (
                self.module
                ._zinput_runtime_candidate_switch_extraction_package(
                    candidate,
                    caller_start=start,
                )
            )
            self.assertEqual(1, len(reviewed_indices))
            self.assertTrue(
                reviewed_indices.issubset(
                    composed.local_control_flow_indices
                )
            )
            self.assertEqual(
                [],
                extract_invocation_contract(
                    composed.instructions,
                    source="cod",
                    caller_identity=f"symbol:recoil:function:{start}",
                    caller_start=start,
                    caller_end_exclusive=(
                        self.module
                        .ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[start][
                            "end"
                        ]
                    ),
                    indexes=self.indexes(),
                    local_control_flow_indices=(
                        composed.local_control_flow_indices
                    ),
                    local_control_flow_targets=(
                        composed.local_control_flow_targets
                    ),
                ),
            )
            with self.assertRaisesRegex(
                ValueError,
                r"unresolved indirect .*edx",
            ):
                extract_invocation_contract(
                    candidate.instructions,
                    source="cod",
                    caller_identity=f"symbol:recoil:function:{start}",
                    caller_start=start,
                    caller_end_exclusive=(
                        self.module
                        .ZINPUT_RUNTIME_DISPATCH_CANDIDATE_SPECS[start][
                            "end"
                        ]
                    ),
                    indexes=self.indexes(),
                )

            dispatch_index = next(iter(reviewed_indices))
            with self.assertRaisesRegex(ValueError, "conflicts"):
                self.module._zinput_runtime_candidate_switch_extraction_package(
                    replace(
                        candidate,
                        local_control_flow_indices=frozenset({dispatch_index}),
                        local_control_flow_targets={
                            dispatch_index: (0,),
                        },
                    ),
                    caller_start=start,
                )

        wait = CandidateAssembly(
            instructions=(),
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
        )
        composed_wait, wait_indices = (
            self.module._zinput_runtime_candidate_switch_extraction_package(
                wait,
                caller_start="0x46fa10",
            )
        )
        self.assertIs(wait, composed_wait)
        self.assertFalse(wait_indices)
        with self.assertRaisesRegex(ValueError, "Wait rejects"):
            self.module._zinput_runtime_candidate_switch_extraction_package(
                replace(
                    wait,
                    local_control_flow_indices=frozenset({0}),
                    local_control_flow_targets={0: (0,)},
                ),
                caller_start="0x46fa10",
            )

        generic = CandidateAssembly(
            instructions=tuple(parse_assembly(
                "00401000 ff d2 call edx",
                source="cod",
            )),
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
        )
        unchanged, generic_indices = (
            self.module._zinput_runtime_candidate_switch_extraction_package(
                generic,
                caller_start="0x401000",
            )
        )
        self.assertIs(generic, unchanged)
        self.assertFalse(generic_indices)

