    def test_registration_tracker_and_source_mutations_fail_closed(self) -> None:
        document = self.document()
        document.collection("verification_targets")[
            self.module.ZCLASS_FREEALL_TARGET_ID
        ]["name"] = "wrong"
        with self.assertRaisesRegex(ValueError, "synchronized registered"):
            self.bridge(document=document)

        document = self.document()
        document.collection("symbols")[
            self.module.ZCLASS_FREEALL_TARGET_SYMBOL_ID
        ]["source_traceability"]["source_edges"][0]["anchor_id"] = "wrong"
        with self.assertRaisesRegex(ValueError, "symbol/source provenance"):
            self.bridge(document=document)

        document = self.document()
        document.collection("physical_blocks")[
            self.module.ZCLASS_FREEALL_CALLER_BLOCK_ID
        ]["accepted_order_facts"]["target_id"] = "wrong"
        with self.assertRaisesRegex(ValueError, "physical-block provenance"):
            self.bridge(document=document)

        real_factory = self.module._call_contract_callable_inventory_resolver
        freeall_key = CallableKey(
            self.module.ZCLASS_FREEALL_TARGET_NAME, ()
        )

        def factory(*args: object, **kwargs: object):
            resolver = real_factory(*args, **kwargs)

            def mutated(path: str, defines: tuple[str, ...]):
                inventory = resolver(path, defines)
                if path == self.module.ZCLASS_FREEALL_TARGET_SOURCE_PATH:
                    return replace(
                        inventory,
                        definitions=inventory.definitions - {freeall_key},
                    )
                return inventory

            return mutated

        with patch.object(
            self.module,
            "_call_contract_callable_inventory_resolver",
            side_effect=factory,
        ):
            with self.assertRaisesRegex(ValueError, "header declaration"):
                self.bridge()

    def test_expected_identity_and_name_collision_fail_closed(self) -> None:
        with self.assertRaisesRegex(ValueError, "retail authored"):
            self.bridge(expected=self.expected(ordinal=2))
        with self.assertRaisesRegex(ValueError, "collision-free"):
            self.bridge(indexes=self.indexes(by_candidate_name={
                self.module.ZCLASS_FREEALL_CANDIDATE_SYMBOL:
                    self.module.ZCLASS_FREEALL_TARGET_IDENTITY,
            }))

    def test_coff_mutations_fail_closed(self) -> None:
        candidate = self.candidate()
        definition = candidate.caller_definition
        assert definition is not None
        mutations = {
            "body": replace(definition, data=b"\x90" + definition.data[1:]),
            "offset": replace(
                definition,
                relocations=(
                    replace(definition.relocations[0], offset=8),
                    *definition.relocations[1:],
                ),
            ),
            "type": replace(
                definition,
                relocations=(
                    definition.relocations[0],
                    replace(definition.relocations[1], type=0x06),
                    *definition.relocations[2:],
                ),
            ),
            "symbol": replace(
                definition,
                undefined_external_functions=(),
            ),
            "mask": replace(
                definition,
                relocation_mask=(
                    *definition.relocation_mask[:12],
                    False,
                    *definition.relocation_mask[13:],
                ),
            ),
        }
        for label, mutation in mutations.items():
            with self.subTest(label=label):
                with self.assertRaisesRegex(ValueError, "complete caller COFF"):
                    self.bridge(candidate=replace(
                        candidate, caller_definition=mutation
                    ))

    def test_cod_mutations_fail_closed(self) -> None:
        candidate = self.candidate()
        rows = candidate.instructions
        cases = {
            "offset": replace(
                candidate,
                instructions=(
                    rows[0],
                    replace(
                        rows[1],
                        source_line=rows[1].source_line.replace(
                            "0000b", "0000c"
                        ),
                    ),
                    rows[2],
                ),
            ),
            "indirect": replace(
                candidate,
                instructions=(
                    rows[0],
                    replace(
                        rows[1],
                        text=(
                            "call dword "
                            + self.module.ZCLASS_FREEALL_CANDIDATE_SYMBOL
                        ),
                        raw_text=(
                            "call dword "
                            + self.module.ZCLASS_FREEALL_CANDIDATE_SYMBOL
                        ),
                    ),
                    rows[2],
                ),
            ),
            "duplicate": replace(
                candidate, instructions=(*rows, rows[1])
            ),
            "bytes": replace(
                candidate,
                instructions=(
                    rows[0],
                    replace(rows[1], bytes=("e9", *rows[1].bytes[1:])),
                    rows[2],
                ),
            ),
        }
        for label, mutation in cases.items():
            with self.subTest(label=label):
                with self.assertRaises(ValueError):
                    self.bridge(candidate=mutation)


