    def test_schema83_zsys_exact_iat_loop_near_misses_fail_closed(
        self,
    ) -> None:
        candidate, indexes, imports = self._schema83_zsys_qpc_loop_fixture()
        definition = candidate.caller_definition
        assert definition is not None

        def replace_instruction(
            current: CandidateAssembly,
            index: int,
            instruction: Instruction,
        ) -> CandidateAssembly:
            return replace(
                current,
                instructions=(
                    *current.instructions[:index],
                    instruction,
                    *current.instructions[index + 1 :],
                ),
            )

        clobber = replace_instruction(
            candidate,
            3,
            replace(
                candidate.instructions[3],
                text="pop edi",
                raw_text="pop edi",
                bytes=("5f",),
            ),
        )
        escape = replace_instruction(
            candidate,
            3,
            replace(
                candidate.instructions[3],
                text="push edi",
                raw_text="push edi",
                bytes=("57",),
            ),
        )
        wrong_iat_symbol = "__imp__QueryPerformanceFrequency@4"
        wrong_iat = replace(
            replace_instruction(
                candidate,
                0,
                replace(
                    candidate.instructions[0],
                    text=f"mov edi, DWORD PTR {wrong_iat_symbol}",
                    raw_text=f"mov edi, DWORD PTR {wrong_iat_symbol}",
                ),
            ),
            caller_definition=replace(
                definition,
                relocations=(
                    replace(
                        definition.relocations[0],
                        symbol_name=wrong_iat_symbol,
                    ),
                ),
                undefined_external_functions=(wrong_iat_symbol,),
            ),
        )
        byte_drift = replace_instruction(
            candidate,
            22,
            replace(
                candidate.instructions[22],
                bytes=("75", "cc"),
            ),
        )
        rendering_drift = replace_instruction(
            candidate,
            22,
            replace(
                candidate.instructions[22],
                text="jne SHORT $recoil_cpu_bsf_sample_loop",
                raw_text="jne SHORT $recoil_cpu_bsf_sample_loop",
            ),
        )
        population_drift = replace(
            candidate,
            caller_definition=replace(
                definition,
                relocations=(
                    definition.relocations[0],
                    definition.relocations[0],
                ),
            ),
        )
        cases = {
            "clobber": (clobber, "overwritten before an exact use"),
            "escape": (escape, "ambiguous mixed data/call"),
            "wrong-iat": (wrong_iat, "already-published immutable retail identity"),
            "byte-drift": (byte_drift, "unresolved downstream CFG"),
            "rendering-drift": (rendering_drift, "unresolved downstream CFG"),
            "population-drift": (population_drift, "exact MOV/DIR32"),
        }
        for label, (malformed, error) in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                call_contract_verify_module.CandidateCallContractEvidenceError,
                error,
            ):
                call_contract_verify_module._candidate_exact_iat_register_load_proofs(
                    malformed,
                    indexes=indexes,
                    retail_import_targets=imports,
                )

        dead = replace(
            candidate,
            instructions=tuple(
                replace(
                    instruction,
                    text="nop",
                    raw_text="nop",
                    bytes=("90",) * len(instruction.bytes),
                )
                if index in {4, 12}
                else instruction
                for index, instruction in enumerate(candidate.instructions)
            ),
        )
        with self.assertRaisesRegex(
            call_contract_verify_module.CandidateCallContractEvidenceError,
            "overwritten before an exact use",
        ):
            call_contract_verify_module._candidate_exact_iat_register_load_proofs(
                dead,
                indexes=indexes,
                retail_import_targets=imports,
            )

        join = CandidateAssembly(
            instructions=tuple(
                parse_assembly(
                    "\n".join(
                        (
                            "00000 8b 3d 00 00 00 00 "
                            "mov edi, DWORD PTR __imp__QueryPerformanceCounter@4",
                            "00006 85 c0 test eax, eax",
                            "00008 74 02 je SHORT $recoil_join$1",
                            "0000a 8b f7 mov esi, edi",
                            "0000c ff d6 call esi",
                            "0000e c3 ret 0",
                        )
                    ),
                    source="cod",
                )
            ),
            local_control_flow_indices=frozenset(),
        )
        with self.assertRaisesRegex(
            call_contract_verify_module.CandidateCallContractEvidenceError,
            "wrong-register",
        ):
            call_contract_verify_module._candidate_iat_load_reached_transfer_offsets(
                join,
                load_index=0,
                destination="edi",
                offsets=(
                    call_contract_verify_module
                    ._candidate_complete_instruction_offsets(join)
                ),
            )

