    def test_schema84_candidate_exact_iat_transfer_reinjection_fails_closed(
        self,
    ) -> None:
        candidate, indexes, imports = (
            self._schema84_zsys_qpc_outer_loop_fixture()
        )
        proofs = dict(
            call_contract_verify_module._candidate_exact_iat_register_load_proofs(
                candidate,
                indexes=indexes,
                retail_import_targets=imports,
            )
        )
        proof = proofs["0x0"]

        def extract(
            current: dict[
                str,
                call_contract_verify_module.CandidateExactIatRegisterLoadProof,
            ],
        ) -> list[dict[str, object]]:
            return extract_invocation_contract(
                candidate.instructions,
                source="cod",
                caller_identity="symbol:recoil:function:0x4b38e0",
                caller_start="0x4b38e0",
                caller_end_exclusive="0x4b3900",
                indexes=indexes,
                reviewed_iat_register_definition_offsets=frozenset({"0x0"}),
                candidate_exact_iat_register_load_proofs=current,
            )

        malformed = {
            "missing-transfer": (
                {"0x0": replace(proof, transfer_offsets=("0x6", "0xd"))},
                "unresolved indirect register storage esi",
            ),
            "extra-transfer": (
                {
                    "0x0": replace(
                        proof,
                        transfer_offsets=(*proof.transfer_offsets, "0x13"),
                    )
                },
                "unused candidate exact-IAT register-load transfer proof",
            ),
            "wrong-identity": (
                {"0x0": replace(proof, identity="iat:GetTickCount")},
                "candidate IAT register load symbol/placeholder identity drift",
            ),
            "wrong-storage-register": (
                {"0x0": replace(proof, destination="edi")},
                "candidate IAT register load symbol/placeholder identity drift",
            ),
            "population-collision": (
                {
                    **proofs,
                    "0x1": replace(proof, definition_offset="0x1"),
                },
                "candidate exact-IAT register-load proof is ambiguous",
            ),
        }
        for label, (current, error) in malformed.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                error,
            ):
                extract(current)

        third_call_index = next(
            index
            for index, instruction in enumerate(candidate.instructions)
            if instruction.source_line.startswith("00012 ")
        )
        byte_drift = replace(
            candidate,
            instructions=(
                *candidate.instructions[:third_call_index],
                replace(
                    candidate.instructions[third_call_index],
                    bytes=("ff", "d7"),
                ),
                *candidate.instructions[third_call_index + 1 :],
            ),
        )
        byte_drift_proofs = (
            call_contract_verify_module._candidate_exact_iat_register_load_proofs(
                byte_drift,
                indexes=indexes,
                retail_import_targets=imports,
            )
        )
        self.assertEqual(
            ("0x6", "0xd"),
            byte_drift_proofs["0x0"].transfer_offsets,
        )
        with self.assertRaisesRegex(
            ValueError,
            "exact x86 CALL/JMP encoding|unresolved indirect register storage",
        ):
            extract_invocation_contract(
                byte_drift.instructions,
                source="cod",
                caller_identity="symbol:recoil:function:0x4b38e0",
                caller_start="0x4b38e0",
                caller_end_exclusive="0x4b3900",
                indexes=indexes,
                reviewed_iat_register_definition_offsets=frozenset(
                    byte_drift_proofs
                ),
                candidate_exact_iat_register_load_proofs=byte_drift_proofs,
            )

