    def test_schema23_differing_or_missing_caller_targets_remain_unbound(
        self,
    ) -> None:
        cases = {
            "different": (
                "00432b5b ba 00 40 43 00 mov edx, 0x434000\n"
                "00432b60 b9 30 3c 43 00 mov ecx, 0x433c30\n"
                "00432b65 e9 e6 50 02 00 jmp 0x457c50",
                {
                    "0x433de0": "symbol:recoil:function:0x433de0",
                    "0x433c30": "symbol:recoil:function:0x433c30",
                    "0x434000": "symbol:recoil:function:0x434000",
                },
                {1},
            ),
            "missing": (
                "00432b60 b9 30 3c 43 00 mov ecx, 0x433c30\n"
                "00432b65 e9 e6 50 02 00 jmp 0x457c50",
                {
                    "0x433de0": "symbol:recoil:function:0x433de0",
                    "0x433c30": "symbol:recoil:function:0x433c30",
                },
                {1},
            ),
        }
        for label, (second, identities, expected_ordinals) in cases.items():
            with self.subTest(label=label):
                callee, _indexes, bridge = self.inbound_bridge(
                    xrefs=[
                        {"source_address": "0x432a65", "kind": "call"},
                        {"source_address": "0x432b65", "kind": "tail"},
                    ],
                    caller_assemblies={
                        "0x432a5b": self.inbound_rows()[1],
                        "0x432b5b": second,
                    },
                    function_starts={
                        "0x432a65": "0x432a5b",
                        "0x432b65": "0x432b5b",
                    },
                )
                indexes = self.indexes(by_address=identities)
                bridges = (
                    call_contract_verify_module
                    ._retail_inbound_entry_register_target_bridges(
                        callee,
                        caller_start="0x457c50",
                        caller_end_exclusive="0x457cb7",
                        indexes=indexes,
                        bridge=bridge,
                    )
                )
                self.assertEqual(expected_ordinals, set(bridges))

