    def test_schema85_retail_iat_loop_reload_and_unanimous_phi_compose(
        self,
    ) -> None:
        route = SimpleNamespace(
            address="0x4cc0b0",
            dll="KERNEL32.dll",
            import_name="Sleep",
            import_ordinal=None,
        )
        cases = (
            (
                "loop-header-reload",
                "0x430500",
                "0x43050c",
                (
                    "00430500 8b 35 b0 c0 4c 00 "
                    "mov esi, dword [0x4cc0b0]\n"
                    "00430506 ff d6 call esi\n"
                    "00430508 49 dec ecx\n"
                    "00430509 75 f5 jne 0x430500\n"
                    "0043050b c3 ret"
                ),
                {"0x430500": ("0x430506",)},
            ),
            (
                "equal-branch-phi",
                "0x430600",
                "0x430613",
                (
                    "00430600 74 08 je 0x43060a\n"
                    "00430602 8b 35 b0 c0 4c 00 "
                    "mov esi, dword [0x4cc0b0]\n"
                    "00430608 eb 06 jmp 0x430610\n"
                    "0043060a 8b 35 b0 c0 4c 00 "
                    "mov esi, dword [0x4cc0b0]\n"
                    "00430610 ff d6 call esi\n"
                    "00430612 c3 ret"
                ),
                {
                    "0x430602": ("0x430610",),
                    "0x43060a": ("0x430610",),
                },
            ),
        )
        for label, start, end, assembly, expected_proofs in cases:
            document, caller_identity = self.authored_document(start, end)
            rows = parse_assembly(assembly, source="bn")
            indexes = (
                call_contract_verify_module
                ._comparison_scoped_retail_register_iat_indexes(
                    rows,
                    document=document,
                    caller_identity=caller_identity,
                    caller_start=start,
                    caller_end_exclusive=end,
                    indexes=self.indexes(
                        by_address={start: caller_identity}
                    ),
                    retail_import_targets=(route,),
                )
            )
            with self.subTest(label=label):
                self.assertEqual(
                    expected_proofs,
                    {
                        definition: proof.transfer_offsets
                        for definition, proof in (
                            indexes.reviewed_retail_iat_load_proofs.items()
                        )
                    },
                )
                contract = extract_invocation_contract(
                    rows,
                    source="bn",
                    caller_identity=caller_identity,
                    caller_start=start,
                    caller_end_exclusive=end,
                    indexes=indexes,
                )
                self.assertTrue(contract)
                self.assertEqual(
                    {"iat:Sleep"},
                    {row["target_identity"] for row in contract},
                )

