    def test_schema91_nonzero_import_cells_do_not_activate_stored_callbacks(
        self,
    ) -> None:
        cases = (
            ("sprintf", 0x4CC5C4, "edi", "8b 3d", "90 8e 7c 00", True),
            ("free", 0x4CC5B4, "ebx", "8b 1d", "44 8e 7c 00", False),
            ("Sleep", 0x4CC0B0, "esi", "8b 35", "30 8d 7c 00", False),
            ("toupper", 0x4CC598, "ebx", "8b 1d", "c8 8e 7c 00", False),
            (
                "LoadLibraryA",
                0x4CC0B8,
                "edi",
                "8b 3d",
                "ec 8b 7c 00",
                True,
            ),
        )
        for ordinal, (
            import_name,
            cell,
            register,
            mov_opcode,
            initial_bytes,
            include_direct,
        ) in enumerate(cases):
            start_value = 0x460000 + ordinal * 0x100
            start = f"0x{start_value:x}"
            end = f"0x{start_value + 0x20:x}"
            mov_bytes = mov_opcode + " " + " ".join(
                f"{value:02x}" for value in struct.pack("<I", cell)
            )
            register_opcode = {"edi": "ff d7", "ebx": "ff d3", "esi": "ff d6"}[
                register
            ]
            lines = [
                f"{start_value:08x} {mov_bytes} "
                f"mov {register}, dword [0x{cell:x}]",
                f"{start_value + 6:08x} {register_opcode} call {register}",
                f"{start_value + 8:08x} {register_opcode} call {register}",
            ]
            if include_direct:
                lines.append(
                    f"{start_value + 10:08x} ff 15 "
                    + " ".join(
                        f"{value:02x}" for value in struct.pack("<I", cell)
                    )
                    + f" call dword [0x{cell:x}]"
                )
            lines.append(f"{start_value + 16:08x} c3 ret")
            rows = parse_assembly("\n".join(lines), source="bn")
            identity = f"iat:{import_name}"
            indexes = self.indexes(
                by_address={start: f"symbol:caller-{ordinal}"},
                storage_by_address={f"0x{cell:x}": identity},
                storage_by_name={import_name: identity},
                storage_containers=(
                    StorageContainer(cell, cell + 4, identity),
                ),
            )
            bridge = SimpleNamespace(
                hexdump=lambda _address, _size, value=initial_bytes: (
                    f"{cell:08x} {value}"
                ),
                get_json=lambda *_args, **_kwargs: self.fail(
                    "nonzero import cell reached callback xref activation"
                ),
            )
            with self.subTest(import_name=import_name):
                unchanged = (
                    call_contract_verify_module
                    ._comparison_scoped_retail_stored_callback_targets(
                        rows,
                        caller_start=start,
                        caller_end_exclusive=end,
                        indexes=indexes,
                        bridge=bridge,
                    )
                )
                self.assertEqual(
                    {},
                    unchanged.reviewed_static_callback_target_by_storage,
                )
                document, caller_identity = self.authored_document(start, end)
                routed = (
                    call_contract_verify_module
                    ._comparison_scoped_retail_register_iat_indexes(
                        rows,
                        document=document,
                        caller_identity=caller_identity,
                        caller_start=start,
                        caller_end_exclusive=end,
                        indexes=replace(
                            indexes,
                            by_address={start: caller_identity},
                        ),
                        retail_import_targets=(
                            SimpleNamespace(
                                address=f"0x{cell:x}",
                                dll="KERNEL32.dll",
                                import_name=import_name,
                                import_ordinal=None,
                            ),
                        ),
                    )
                )
                self.assertEqual(
                    identity,
                    next(
                        iter(routed.reviewed_retail_iat_load_proofs.values())
                    ).identity,
                )

        unknown_start = "0x461000"
        unknown_end = "0x461010"
        unknown_rows = parse_assembly(
            "00461000 8b 1d b4 c5 4c 00 mov ebx, dword [0x4cc5b4]\n"
            "00461006 ff d3 call ebx\n"
            "00461008 c3 ret",
            source="bn",
        )
        unknown_indexes = self.indexes(
            storage_by_address={"0x4cc5b4": "iat:free"},
            storage_containers=(
                StorageContainer(0x4CC5B4, 0x4CC5B8, "iat:free"),
            ),
        )
        unknown_bridge = SimpleNamespace(
            hexdump=lambda _address, _size: "",
            get_json=lambda *_args, **_kwargs: self.fail(
                "unknown initial bytes reached callback xref activation"
            ),
        )
        self.assertEqual(
            {},
            call_contract_verify_module
            ._comparison_scoped_retail_stored_callback_targets(
                unknown_rows,
                caller_start=unknown_start,
                caller_end_exclusive=unknown_end,
                indexes=unknown_indexes,
                bridge=unknown_bridge,
            ).reviewed_static_callback_target_by_storage,
        )

    def test_schema92_sleep_full_proof_package_rebinds_identical_rows(self) -> None:
        start = "0x404180"
        end = "0x404280"
        document, caller_identity = self.authored_document(start, end)
        prefix = "\n".join(
            f"{0x404180 + index:08x} 90 nop" for index in range(52)
        )
        assembly = (
            prefix
            + "\n00404253 8b 35 b0 c0 4c 00 "
            "mov esi, dword [0x4cc0b0]"
            "\n00404259 6a 01 push 1"
            "\n0040425b ff d6 call esi"
            "\n0040425d c3 ret"
        )
        rows = parse_assembly(assembly, source="bn")
        route = SimpleNamespace(
            address="0x4cc0b0",
            dll="KERNEL32.dll",
            import_name="Sleep",
            import_ordinal=None,
        )
        bridge = MagicMock()
        bridge.hexdump.return_value = ""
        indexes, package = (
            call_contract_verify_module
            ._compose_caller_scoped_retail_proof_package(
                rows,
                document=document,
                caller_identity=caller_identity,
                caller_start=start,
                caller_end_exclusive=end,
                indexes=self.indexes(by_address={start: caller_identity}),
                bridge=bridge,
                retail_import_targets=(route,),
            )
        )
        self.assertEqual(
            [("0x404253", rows[52], (rows[54],))],
            list(package.iat_instruction_objects),
        )
        self.assertIs(package, indexes.active_retail_caller_proof_package)
        contract = extract_invocation_contract(
            rows,
            source="bn",
            caller_identity=caller_identity,
            caller_start=start,
            caller_end_exclusive=end,
            indexes=indexes,
        )
        self.assertEqual("iat:Sleep", contract[0]["target_identity"])
        self.assertEqual(
            [],
            extract_invocation_contract(
                rows[:52],
                source="bn",
                caller_identity=caller_identity,
                caller_start=start,
                caller_end_exclusive=end,
                indexes=indexes,
            ),
        )
        reparsed_subset = parse_assembly(
            "\n".join(row.source_line for row in rows[10:15]),
            source="bn",
        )
        self.assertEqual(
            [],
            extract_invocation_contract(
                reparsed_subset,
                source="bn",
                caller_identity="symbol:recoil:function:0x40418a",
                caller_start="0x40418a",
                caller_end_exclusive="0x40418f",
                indexes=indexes,
            ),
        )
        rejected_subsets = (
            tuple(reversed(reparsed_subset)),
            parse_assembly("00409999 90 nop", source="bn"),
            parse_assembly("0040418a cc int3", source="bn"),
            parse_assembly("0040418a 90 xchg eax, eax", source="bn"),
        )
        for rejected_subset in rejected_subsets:
            with self.assertRaisesRegex(
                ValueError, "exact ordered caller instructions"
            ):
                extract_invocation_contract(
                    rejected_subset,
                    source="bn",
                    caller_identity="symbol:recoil:function:0x40418a",
                    caller_start="0x40418a",
                    caller_end_exclusive="0x40418f",
                    indexes=indexes,
                )
        collision_rows = list(package.instruction_objects)
        collision_rows[11] = replace(
            collision_rows[11],
            source_line=collision_rows[10].source_line,
        )
        collision_package = replace(
            package,
            instruction_objects=tuple(collision_rows),
        )
        with self.assertRaisesRegex(
            ValueError, "exact ordered caller instructions"
        ):
            extract_invocation_contract(
                reparsed_subset[:1],
                source="bn",
                caller_identity="symbol:recoil:function:0x40418a",
                caller_start="0x40418a",
                caller_end_exclusive="0x40418b",
                indexes=replace(
                    indexes,
                    active_retail_caller_proof_package=collision_package,
                ),
            )
        with self.assertRaisesRegex(ValueError, "exact ordered caller instructions"):
            extract_invocation_contract(
                (rows[1], rows[0]),
                source="bn",
                caller_identity=caller_identity,
                caller_start=start,
                caller_end_exclusive=end,
                indexes=indexes,
            )
        with self.assertRaisesRegex(ValueError, "identical caller instructions"):
            extract_invocation_contract(
                parse_assembly(assembly, source="bn"),
                source="bn",
                caller_identity=caller_identity,
                caller_start=start,
                caller_end_exclusive=end,
                indexes=indexes,
            )

    def test_schema85_retail_iat_composition_rejects_partial_and_conflicting_paths(
        self,
    ) -> None:
        routes = (
            SimpleNamespace(
                address="0x4cc0b0",
                dll="KERNEL32.dll",
                import_name="Sleep",
                import_ordinal=None,
            ),
            SimpleNamespace(
                address="0x4cc134",
                dll="KERNEL32.dll",
                import_name="ReadFile",
                import_ordinal=None,
            ),
        )
        cases = (
            (
                "partial-path",
                "0x430700",
                "0x43070b",
                (
                    "00430700 74 06 je 0x430708\n"
                    "00430702 8b 35 b0 c0 4c 00 "
                    "mov esi, dword [0x4cc0b0]\n"
                    "00430708 ff d6 call esi\n"
                    "0043070a c3 ret"
                ),
                "does not cover every CFG path",
            ),
            (
                "conflicting-routes",
                "0x430800",
                "0x430813",
                (
                    "00430800 74 08 je 0x43080a\n"
                    "00430802 8b 35 b0 c0 4c 00 "
                    "mov esi, dword [0x4cc0b0]\n"
                    "00430808 eb 06 jmp 0x430810\n"
                    "0043080a 8b 35 34 c1 4c 00 "
                    "mov esi, dword [0x4cc134]\n"
                    "00430810 ff d6 call esi\n"
                    "00430812 c3 ret"
                ),
                "unresolved indirect register storage",
            ),
        )
        for label, start, end, assembly, error in cases:
            document, caller_identity = self.authored_document(start, end)
