            with self.subTest(label=label):
                if label == "wrong-slot":
                    self.assertEqual(
                        {}, indexes.reviewed_retail_iat_load_proofs
                    )
                    with self.assertRaisesRegex(
                        ValueError,
                        "unresolved indirect register (?:storage|provenance)",
                    ):
                        extract_invocation_contract(
                            rows,
                            source="bn",
                            caller_identity=caller_identity,
                            caller_start=start,
                            caller_end_exclusive=end,
                            indexes=indexes,
                        )
                    continue
                if label == "esi-redefinition":
                    self.assertEqual(
                        {}, indexes.reviewed_retail_iat_load_proofs
                    )
                    with self.assertRaisesRegex(
                        ValueError,
                        "unresolved indirect register (?:storage|provenance)",
                    ):
                        extract_invocation_contract(
                            rows,
                            source="bn",
                            caller_identity=caller_identity,
                            caller_start=start,
                            caller_end_exclusive=end,
                            indexes=indexes,
                        )
                    continue
                with self.assertRaisesRegex(
                    ValueError,
                    "does not cover every CFG path",
                ):
                    extract_invocation_contract(
                        rows,
                        source="bn",
                        caller_identity=caller_identity,
                        caller_start=start,
                        caller_end_exclusive=end,
                        indexes=indexes,
                    )

