        self.assertEqual({0, 1}, set(bridges))
        contract = extract_invocation_contract(
            callee_rows,
            source="bn",
            caller_identity="symbol:recoil:function:0x457c50",
            caller_start="0x457c50",
            caller_end_exclusive="0x457c59",
            indexes=indexes,
            reviewed_inbound_entry_register_target_bridges=bridges,
        )
        self.assertEqual(
            [target_edx, target_ecx],
            [row["target_identity"] for row in contract],
        )

