    def test_schema69_bounded_targetless_forms_fail_closed_on_drift(
        self,
    ) -> None:
        valid = parse_assembly(
            "00413000 8b f1 mov esi, ecx\n"
            "00413002 33 ff xor edi, edi\n"
            "00413004 8b c7 mov eax, edi\n"
            "00413006 69 c0 c0 02 00 00 imul eax, eax, 0x2c0\n"
            "0041300c 8b 4c 06 20 "
            "mov ecx, dword [esi+eax*1+0x20]\n"
            "00413010 8b 11 mov edx, dword [ecx]\n"
            "00413012 ff 92 94 00 00 00 call dword [edx+0x94]\n"
            "00413018 47 inc edi\n"
            "00413019 83 ff 03 cmp edi, 3\n"
            "0041301c 7c e6 jl 0x413004",
            source="bn",
        )
        cases = {
            "imul-byte-render": valid[:3] + [
                replace(valid[3], bytes=("69", "c0", "ac", "02", "00", "00"))
            ] + valid[4:],
            "receiver-kill": valid[:5] + [
                *valid[5:6],
                parse_assembly("00413012 8b ce mov ecx, esi", source="bn")[0],
                replace(
                    valid[6],
                    source_line="00413014 ff 92 94 00 00 00 call dword [edx+0x94]",
                ),
                *valid[7:],
            ],
            "unreviewed-slot": valid[:6] + [
                replace(
                    valid[6],
                    raw_text="call dword [edx+0x98]",
                    text="call dword [edx+0x98]",
                    bytes=("ff", "92", "98", "00", "00", "00"),
                )
            ] + valid[7:],
            "overflow": valid[:3] + [
                replace(
                    valid[3],
                    raw_text="imul eax, eax, 0x10001",
                    text="imul eax, eax, 0x10001",
                    bytes=("69", "c0", "01", "00", "01", "00"),
                )
            ] + valid[4:],
        }
        for label, malformed in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "unresolved indirect|unreviewed slot|receiver/vptr",
            ):
                extract_invocation_contract(
                    malformed,
                    source="bn",
                    caller_identity="symbol:recoil:function:0x413000",
                    caller_start="0x413000",
                    caller_end_exclusive="0x413040",
                    indexes=self.indexes(),
                )

        cursor_without_bound = parse_assembly(
            "00413100 8b f1 mov esi, ecx\n"
            "00413102 bf 50 01 00 00 mov edi, 0x150\n"
            "00413107 8b 0c 3e mov ecx, dword [esi+edi*1]\n"
            "0041310a 8b 01 mov eax, dword [ecx]\n"
            "0041310c ff 50 80 call dword [eax+0x80]\n"
            "0041310f 83 c7 04 add edi, 4",
            source="bn",
        )
        with self.assertRaisesRegex(ValueError, "unresolved indirect"):
            extract_invocation_contract(
                cursor_without_bound,
                source="bn",
                caller_identity="symbol:recoil:function:0x413100",
                caller_start="0x413100",
                caller_end_exclusive="0x413112",
                indexes=self.indexes(),
            )

        ambiguous_join = parse_assembly(
            "00413200 8b f1 mov esi, ecx\n"
            "00413202 33 ff xor edi, edi\n"
            "00413204 8b c7 mov eax, edi\n"
            "00413206 85 d2 test edx, edx\n"
            "00413208 74 06 je 0x413210\n"
            "0041320a 69 c0 c0 02 00 00 imul eax, eax, 0x2c0\n"
            "00413210 8b 4c 06 20 "
            "mov ecx, dword [esi+eax*1+0x20]\n"
            "00413214 8b 11 mov edx, dword [ecx]\n"
            "00413216 ff 92 94 00 00 00 call dword [edx+0x94]\n"
            "0041321c 47 inc edi\n"
            "0041321d 83 ff 03 cmp edi, 3\n"
            "00413220 7c e2 jl 0x413204",
            source="bn",
        )
        with self.assertRaisesRegex(ValueError, "unresolved indirect"):
            extract_invocation_contract(
                ambiguous_join,
                source="bn",
                caller_identity="symbol:recoil:function:0x413200",
                caller_start="0x413200",
                caller_end_exclusive="0x413222",
                indexes=self.indexes(),
            )

    def test_schema51_direct_ret_cleanup_and_irrelevant_iat_calls_are_bounded(
        self,
    ) -> None:
        rows = parse_assembly(
            "00404140 8b f1 mov esi, ecx\n"
            "00404142 6a 01 push 1\n"
            "00404144 e8 b7 0e 00 00 call 0x405000\n"
            "00404149 48 dec eax\n"
            "0040414a 75 f6 jne 0x404142\n"
            "0040414c ff d6 call esi",
            source="bn",
        )
        bridge = SimpleNamespace(
            assembly=lambda target: (
                "00405000 c2 04 00 ret 4"
                if target == "0x405000"
                else ""
            )
        )
        cleanup = call_contract_verify_module._retail_direct_call_cleanup_by_ordinal(
            rows,
            caller_start="0x404140",
            caller_end_exclusive="0x40414e",
            bridge=bridge,
        )
        self.assertEqual({0: 4}, cleanup)
        self.assertEqual(
            [(1, "0x40414c", "esi", "ecx")],
            call_contract_verify_module._entry_register_lineage_calls(
                rows,
                caller_start="0x404140",
                caller_end_exclusive="0x40414e",
                entry_registers=frozenset({"ecx"}),
                cleanup_by_ordinal=cleanup,
            ),
        )

        ambiguous_bridge = SimpleNamespace(
            assembly=lambda _target: (
                "00405000 c2 04 00 ret 4\n"
                "00405003 c2 08 00 ret 8"
            )
        )
        self.assertEqual(
            {},
            call_contract_verify_module._retail_direct_call_cleanup_by_ordinal(
                rows,
                caller_start="0x404140",
                caller_end_exclusive="0x40414e",
                bridge=ambiguous_bridge,
            ),
        )

        callee = parse_assembly(
            "00403040 8b f1 mov esi, ecx\n"
            "00403042 8b 06 mov eax, dword [esi]\n"
            "00403044 ff 50 20 call dword [eax+0x20]",
            source="bn",
        )
        caller = (
            "00402fce 8b ce mov ecx, esi\n"
            "00402fd0 e8 6b 00 00 00 call 0x403040"
        )

        def bridge_for(code_references, assembly=caller):
            return SimpleNamespace(
                get_json=lambda _endpoint, **_kwargs: {
                    "code_references": code_references,
                    "data_references": [],
                    "total": len(code_references),
                    "truncated": False,
                },
                function_at=lambda _address: [{"name": "sole_caller"}],
                function_info=lambda _name: {"start": "0x402fce"},
                assembly=lambda _address: assembly,
            )
        roots = frozenset({"ecx"})

        cases = {
            "missing": ([], caller),
            "multiple": (
                [
                    {"source_address": "0x402fd0"},
                    {"source_address": "0x402fd8"},
                ],
                caller
                + "\n00402fd6 8b ce mov ecx, esi"
                + "\n00402fd8 e8 63 00 00 00 call 0x403040",
            ),
            "not-immediate": (
                [{"source_address": "0x402fd1"}],
                "00402fce 8b ce mov ecx, esi\n"
                "00402fd0 90 nop\n"
                "00402fd1 e8 6a 00 00 00 call 0x403040",
            ),
            "stack-argument": (
                [{"source_address": "0x402fd0"}],
                "00402fcd 56 push esi\n"
                "00402fce 8b ce mov ecx, esi\n"
                "00402fd0 e8 6b 00 00 00 call 0x403040",
            ),
        }
        for label, (references, assembly) in cases.items():
            with self.subTest(label=label):
                self.assertEqual(
                    frozenset(),
                    call_contract_verify_module._retail_inbound_entry_register_lineage_roots(
                        callee,
                        caller_start="0x403040",
                        bridge=bridge_for(references, assembly),
                    ),
                )

        killed = parse_assembly(
            "00403040 8b f1 mov esi, ecx\n"
            "00403042 33 f6 xor esi, esi\n"
            "00403044 8b 06 mov eax, dword [esi]\n"
            "00403046 ff 50 20 call dword [eax+0x20]",
            source="bn",
        )
        with self.assertRaisesRegex(
            ValueError,
            "unresolved indirect register storage",
        ):
            extract_invocation_contract(
                killed,
                source="bn",
                caller_identity="symbol:recoil:function:0x403040",
                caller_start="0x403040",
                caller_end_exclusive="0x403049",
                indexes=self.indexes(),
                reviewed_inbound_entry_register_roots=roots,
            )

