    def cedit_fixture(self) -> dict:
        fixture = self.combo_fixture()
        offsets = call_contract_verify_module.WOL_CONFIG_CEDIT_INVOCATION_OFFSETS
        symbols = call_contract_verify_module.WOL_CONFIG_CEDIT_INVOCATION_ORDER
        body = bytearray(
            call_contract_verify_module.WOL_CONFIG_CEDIT_CANDIDATE_SIZE
        )
        mask = [False] * len(body)
        relocations = []
        for ordinal, (offset, symbol) in enumerate(zip(offsets, symbols), 1):
            body[offset : offset + 5] = b"\xe8\0\0\0\0"
            mask[offset + 1 : offset + 5] = [True] * 4
            relocations.append(
                CoffRelocation(offset + 1, ordinal, 0x14, symbol)
            )
        dummy_offsets = (3, 9, 17, 112, 117, 143, 148, 174, 179, 205, 210, 236, 249, 279)
        for ordinal, offset in enumerate(dummy_offsets, len(relocations) + 1):
            is_cstring_callback = offset in (
                call_contract_verify_module.WOL_CONFIG_CSTRING_CALLBACK_RELOCATION_OFFSETS
            )
            if is_cstring_callback:
                body[offset - 1] = 0x68
            mask[offset : offset + 4] = [True] * 4
            relocations.append(
                CoffRelocation(
                    offset,
                    ordinal,
                    0x06,
                    (
                        call_contract_verify_module.WOL_CSTRING_CANDIDATE_SYMBOL
                        if is_cstring_callback
                        else f"$exact{ordinal}"
                    ),
                )
            )
        definition = CandidateCallerDefinition(
            symbol=(
                "??0WestwoodOnlineUpgradeConfigDialog@@"
                "QAE@PAVCWnd@@@Z"
            ),
            data=bytes(body),
            relocations=tuple(relocations),
            relocation_mask=tuple(mask),
            undefined_external_functions=tuple(dict.fromkeys(symbols)),
            section_start=0,
            section_end=len(body),
        )
        fixture["candidate"] = replace(
            fixture["candidate"],
            instructions=parse_assembly(
                "\n".join(
                    f"{offset:05x} e8 00 00 00 00 call {symbol}"
                    for offset, symbol in zip(offsets, symbols)
                ),
                source="cod",
            ),
            caller_definition=definition,
        )
        target_row = fixture["data"]["symbols"][
            call_contract_verify_module.WOL_CEDIT_TARGET_SYMBOL_ID
        ]
        target_row.update(
            output_section_id="recoil:section:.text",
            disposition="unresolved",
            ownership_state="unresolved",
        )
        self.rebuild(fixture)
        fixture["expected"] = [
            {
                "ordinal": ordinal,
                "form": "call",
                "dispatch": "direct",
                "identity_kind": (
                    "provider" if ordinal in {0, 1, 2, 3, 4} else "direct"
                ),
                "target_identity": (
                    "provider:recoil:function:0x4c5b64"
                    if ordinal == 0
                    else "provider:recoil:function:0x4c5bac"
                    if ordinal in {1, 2}
                    else "provider:recoil:function:0x4c5ba0"
                    if ordinal in {3, 4}
                    else "symbol:recoil:function:0x4a1000"
                    if ordinal in {5, 6, 7, 8}
                    else f"symbol:recoil:function:0x{0x440000 + ordinal:x}"
                ),
                "storage_identity": "",
                "slot_displacement": None,
                "cleanup_bytes": None,
            }
            for ordinal in range(len(symbols))
        ]
        return fixture

