    def test_time_reset_generic_direct_row_is_exact_and_adversarial(self) -> None:
        symbol = call_contract_verify_module.WOL_TIME_RESET_CANDIDATE_SYMBOL
        fixture = self.time_fixture()
        self.assertEqual(
            {symbol: "symbol:recoil:function:0x4a5670"},
            self.prove_direct(fixture),
        )

        candidate = fixture["candidate"]
        definition = candidate.caller_definition
        assert definition is not None
        relocation = definition.relocations[0]
        instruction = candidate.instructions[0]
        malformed_body = bytearray(definition.data)
        malformed_body[8] = 0x90
        lower_symbol = symbol.lower()
        cases = {
            "malformed-opcode": replace(
                candidate,
                caller_definition=replace(
                    definition, data=bytes(malformed_body)
                ),
            ),
            "ambiguous-call": replace(
                candidate,
                instructions=(
                    *candidate.instructions,
                    *parse_assembly(
                        f"00010 e8 00 00 00 00 call {symbol}",
                        source="cod",
                    ),
                ),
            ),
            "wrong-case": replace(
                candidate,
                instructions=(
                    replace(
                        instruction,
                        text=f"call {lower_symbol}",
                        raw_text=f"call {lower_symbol}",
                    ),
                ),
                caller_definition=replace(
                    definition,
                    relocations=(
                        replace(relocation, symbol_name=lower_symbol),
                    ),
                    undefined_external_functions=(lower_symbol,),
                ),
            ),
            "wrong-relocation": replace(
                candidate,
                caller_definition=replace(
                    definition,
                    relocations=(
                        replace(
                            relocation,
                            type=call_contract_verify_module.IMAGE_REL_I386_DIR32,
                        ),
                    ),
                ),
            ),
            "wrong-target": replace(
                candidate,
                caller_definition=replace(
                    definition,
                    relocations=(
                        replace(relocation, symbol_name="?Reset@Other@@YIXXZ"),
                    ),
                ),
            ),
            "wrong-caller": replace(
                candidate,
                caller_definition=replace(definition, symbol="?WrongCaller@@YAXXZ"),
            ),
        }
        for label, malformed in cases.items():
            mutated = self.time_fixture()
            mutated["candidate"] = malformed
            with self.subTest(label=label), self.assertRaises(ValueError):
                self.prove_direct(mutated)

        collision = self.time_fixture()
        collision["arguments"]["indexes"] = replace(
            collision["indexes"],
            by_candidate_name={symbol.lower(): "symbol:wrong"},
        )
        with self.assertRaisesRegex(ValueError, "collision drift"):
            self.prove_direct(collision)

    def test_both_atoi_bridges_publish_into_generic_exact_iat_proof(self) -> None:
        for caller_identity in (
            "symbol:recoil:function:0x4407e0",
            "symbol:recoil:function:0x440a30",
        ):
            with self.subTest(caller_identity=caller_identity):
                fixture = self.atoi_fixture(caller_identity)
                bridges, explicit_proofs = self.prove_atoi_full(fixture)
                self.assertEqual({"__imp__atoi": "iat:atoi"}, bridges)
                indexes = call_contract_verify_module._candidate_exact_iat_register_storage_indexes(
                    fixture["indexes"], bridges
                )
                proofs = call_contract_verify_module._candidate_exact_iat_register_load_proofs(
                    fixture["candidate"],
                    indexes=indexes,
                    retail_import_targets=(
                        SimpleNamespace(
                            address="0x4cc5d4",
                            dll="MSVCRT.dll",
                            import_name="atoi",
                            import_ordinal=None,
                        ),
                    ),
                )
                self.assertEqual({"0x93"}, set(proofs))
                self.assertEqual(proofs, explicit_proofs)

