    def test_config_cedit_bridge_rejects_cod_coff_and_collision_drift(self) -> None:
        symbol = call_contract_verify_module.WOL_CONFIG_CEDIT_CANDIDATE_SYMBOL
        fixture = self.cedit_fixture()
        definition = fixture["candidate"].caller_definition
        assert definition is not None
        cedit_relocation = next(
            row for row in definition.relocations if row.symbol_name == symbol
        )
        cedit_instruction = next(
            row
            for row in fixture["candidate"].instructions
            if symbol in row.text
        )
        lower_symbol = symbol.lower()
        cases = {
            "wrong-case": replace(
                fixture["candidate"],
                instructions=tuple(
                    replace(
                        row,
                        text=f"call {lower_symbol}",
                        raw_text=f"call {lower_symbol}",
                    )
                    if row is cedit_instruction
                    else row
                    for row in fixture["candidate"].instructions
                ),
                caller_definition=replace(
                    definition,
                    relocations=tuple(
                        replace(row, symbol_name=lower_symbol)
                        if row is cedit_relocation
                        else row
                        for row in definition.relocations
                    ),
                    undefined_external_functions=tuple(
                        lower_symbol if name == symbol else name
                        for name in definition.undefined_external_functions
                    ),
                ),
            ),
            "wrong-relocation": replace(
                fixture["candidate"],
                caller_definition=replace(
                    definition,
                    relocations=tuple(
                        replace(row, type=0x06)
                        if row is cedit_relocation
                        else row
                        for row in definition.relocations
                    ),
                ),
            ),
            "wrong-caller": replace(
                fixture["candidate"],
                caller_definition=replace(
                    definition, symbol="??0WrongDialog@@QAE@XZ"
                ),
            ),
            "wrong-population": replace(
                fixture["candidate"],
                instructions=fixture["candidate"].instructions[:-1],
            ),
            "duplicate-call": replace(
                fixture["candidate"],
                instructions=(
                    *fixture["candidate"].instructions,
                    *parse_assembly(
                        f"00120 e8 00 00 00 00 call {symbol}",
                        source="cod",
                    ),
                ),
            ),
        }
        for label, candidate in cases.items():
            current = self.cedit_fixture()
            current["candidate"] = candidate
            with self.subTest(label=label), self.assertRaises(ValueError):
                self.prove_cedit(current)

        fixture = self.cedit_fixture()
        fixture["arguments"]["indexes"] = replace(
            fixture["indexes"],
            by_candidate_name={symbol: "provider:recoil:function:0x4c5bb2"},
        )
        with self.assertRaisesRegex(ValueError, "collision drift"):
            self.prove_cedit(fixture)

        fixture = self.cedit_fixture()
        fixture["bridge_names"][symbol] = [
            SimpleNamespace(address="0x4c5bb2")
        ]
        with self.assertRaisesRegex(ValueError, "collision drift"):
            self.prove_cedit(fixture)

    def test_config_cstring_ordinal_population_excludes_only_reviewed_callbacks(
        self,
    ) -> None:
        fixture = self.cedit_fixture()
        self.assertEqual(
            {
                "??0CString@@QAE@XZ": (
                    "provider:recoil:function:0x4c5ba0"
                )
            },
            self.prove_config_cstring_ordinal(fixture),
        )

        fixture = self.cedit_fixture()
        with self.assertRaisesRegex(ValueError, "equal nonempty retail"):
            self.prove_config_cstring_ordinal(
                fixture,
                supplemental={
                    "??0CEdit@@QAE@XZ": (
                        "provider:recoil:function:0x4c5bb2"
                    ),
                    "??0CComboBox@@QAE@XZ": (
                        "provider:recoil:function:0x4c5bac"
                    )
                },
            )

        for label, mutate in (
            (
                "wrong-type",
                lambda row: replace(row, type=0x14),
            ),
            (
                "wrong-case",
                lambda row: replace(
                    row, symbol_name="??0cstring@@qae@xz"
                ),
            ),
            (
                "wrong-offset",
                lambda row: replace(row, offset=row.offset + 1),
            ),
        ):
            fixture = self.cedit_fixture()
            definition = fixture["candidate"].caller_definition
            assert definition is not None
            callback_offset = (
                call_contract_verify_module.WOL_CONFIG_CSTRING_CALLBACK_RELOCATION_OFFSETS[0]
            )
            fixture["candidate"] = replace(
                fixture["candidate"],
                caller_definition=replace(
                    definition,
                    relocations=tuple(
                        mutate(row)
                        if row.offset == callback_offset
                        else row
                        for row in definition.relocations
                    ),
                ),
            )
            with self.subTest(label=label), self.assertRaises(ValueError):
                self.prove_config_cstring_ordinal(fixture)

        fixture = self.cedit_fixture()
        definition = fixture["candidate"].caller_definition
        assert definition is not None
        callback_offset = (
            call_contract_verify_module.WOL_CONFIG_CSTRING_CALLBACK_RELOCATION_OFFSETS[0]
        )
        body = bytearray(definition.data)
        body[callback_offset - 1] = 0x90
        fixture["candidate"] = replace(
            fixture["candidate"],
            caller_definition=replace(definition, data=bytes(body)),
        )
        with self.assertRaisesRegex(ValueError, "PUSH/DIR32"):
            self.prove_config_cstring_ordinal(fixture)


