    def test_schema87_recoilapp_aligned_symbolic_stack_vptr_is_exactly_bounded(
        self,
    ) -> None:
        assembly = (
            "00003 83 e4 f8 and esp, -8\n"
            "001b9 8b 44 24 38 mov eax, dword _blurAction$83126[esp+116]\n"
            "001bd 6a 00 push 0\n"
            "001bf 6a 00 push 0\n"
            "001c1 8d 4c 24 40 lea ecx, dword _blurAction$83126[esp+124]\n"
            "001c5 c7 44 24 78 00 00 00 00 mov dword __$EHRec$[esp+132], 0\n"
            "001cd ff 50 08 call dword [eax+8]\n"
            "001d0 8b 54 24 38 mov edx, dword _blurAction$83126[esp+116]\n"
            "001d4 6a 00 push 0\n"
            "001d6 6a 00 push 0\n"
            "001d8 8d 4c 24 40 lea ecx, dword _blurAction$83126[esp+124]\n"
            "001dc ff 52 04 call dword [edx+4]\n"
            "001df 85 c0 test eax, eax\n"
            "001e1 74 13 je 0x1f6\n"
            "001e3 8b 44 24 38 mov eax, dword _blurAction$83126[esp+116]\n"
            "001e7 6a 00 push 0\n"
            "001e9 6a 00 push 0\n"
            "001eb 8d 4c 24 40 lea ecx, dword _blurAction$83126[esp+124]\n"
            "001ef ff 50 04 call dword [eax+4]\n"
            "001f2 85 c0 test eax, eax\n"
            "001f4 75 ed jne 0x1e3\n"
            "001f6 8b 54 24 38 mov edx, dword _blurAction$83126[esp+116]\n"
            "001fa 8d 4c 24 38 lea ecx, dword _blurAction$83126[esp+116]\n"
            "001fe ff 52 0c call dword [edx+12]"
        )
        rows = parse_assembly(assembly, source="cod")
        marker = "bounded-stack-vptr-sequence(+0x8,+0x4,+0x4,+0xc)"
        contract = extract_invocation_contract(
            rows,
            source="cod",
            caller_identity="symbol:recoil:function:0x42f5e0",
            caller_start="0x42f5e0",
            caller_end_exclusive="0x42f8a0",
            indexes=self.indexes(),
        )
        self.assertEqual([8, 4, 4, 0xC], [row["slot_displacement"] for row in contract])
        self.assertEqual([marker] * 4, [row["storage_identity"] for row in contract])

        for label, changed_assembly, changed_start in (
            ("wrong-caller", assembly, "0x42f5d0"),
            (
                "symbol-collision",
                assembly.replace(
                    "_blurAction$83126[esp+124]",
                    "_otherAction$83126[esp+124]",
                    1,
                ),
                "0x42f5e0",
            ),
            (
                "rendered-bias-drift",
                assembly.replace(
                    "_blurAction$83126[esp+116]",
                    "_blurAction$83126[esp+120]",
                    1,
                ),
                "0x42f5e0",
            ),
        ):
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "unresolved indirect register storage"
            ):
                extract_invocation_contract(
                    parse_assembly(changed_assembly, source="cod"),
                    source="cod",
                    caller_identity="symbol:recoil:function:0x42f5e0",
                    caller_start=changed_start,
                    caller_end_exclusive="0x42f8a0",
                    indexes=self.indexes(),
                )

    def test_schema87_caller_census_is_ordered_complete_and_nonaccepting(
        self,
    ) -> None:
        symbol_ids = [
            "recoil:function:0x42f280",
            "recoil:function:0x42f5e0",
            "recoil:function:0x42f8a0",
        ]
        addresses = ["0x42f280", "0x42f5e0", "0x42f8a0"]
        blocker = {
            "symbol_id": symbol_ids[1],
            "address": addresses[1],
            "kind": "verifier-blocked",
            "side": "candidate",
            "message": "fixture extraction failure",
        }
        mismatch = {
            "symbol_id": symbol_ids[2],
            "address": addresses[2],
            "kind": "mismatch",
            "ordinal": 0,
        }
        expected = {symbol_ids[0]: [], symbol_ids[2]: []}
        candidate = {symbol_ids[0]: [], symbol_ids[2]: []}
        census = call_contract_verify_module._caller_isolated_diagnostic_census(
            symbol_ids=symbol_ids,
            addresses=addresses,
            expected_contracts=expected,
            candidate_contracts=candidate,
            caller_divergences=[blocker, mismatch],
            complete=True,
        )
        self.assertTrue(census["complete"])
        self.assertTrue(census["nonaccepting"])
        self.assertFalse(census["acceptance_eligible"])
        self.assertEqual(3, census["evaluated_caller_count"])
        self.assertEqual(2, census["divergent_caller_count"])
        self.assertEqual(1, census["verifier_blocked_caller_count"])
        self.assertEqual(1, census["semantic_mismatch_caller_count"])
        self.assertEqual(1, census["later_divergence_count"])
        self.assertEqual([blocker, mismatch], census["divergences"])
        self.assertEqual(
            {
                "collect_all_divergences": True,
                "compile_definition_closure": False,
            },
            call_contract_verify_module._direct_cli_target_census_options(
                target_id="recoil:vc5-target:recoil_app",
                all_authored_bodies=True,
            ),
        )
        self.assertEqual(
            {},
            call_contract_verify_module._direct_cli_target_census_options(
                target_id=None,
                all_authored_bodies=False,
            ),
        )

        with self.assertRaisesRegex(ValueError, "out of retail order"):
            call_contract_verify_module._caller_isolated_diagnostic_census(
                symbol_ids=symbol_ids,
                addresses=addresses,
                expected_contracts=expected,
                candidate_contracts=candidate,
                caller_divergences=[mismatch, blocker],
                complete=True,
            )
        with self.assertRaisesRegex(ValueError, "omitted callers"):
            call_contract_verify_module._caller_isolated_diagnostic_census(
                symbol_ids=symbol_ids,
                addresses=addresses,
                expected_contracts={symbol_ids[0]: []},
                candidate_contracts={symbol_ids[0]: []},
                caller_divergences=[blocker],
                complete=True,
            )

    def test_schema85_fresh_retail_vptr_slice_composes_call_result_and_nested_receiver(
        self,
    ) -> None:
        call_address = 0x4432F7
        displacement = 0x443140 - (call_address + 5)
        appframe = parse_assembly(
            f"004432f7 "
            + " ".join(
                f"{value:02x}"
                for value in b"\xe8" + struct.pack("<i", displacement)
            )
            + " call 0x443140\n"
            "004432fc 90 nop\n"
            "004432fd 8b d8 mov ebx, eax\n"
            "004432ff 90 nop\n"
            "00443300 8b 03 mov eax, dword [ebx]\n"
            "00443302 8b cb mov ecx, ebx\n"
            "00443304 ff 50 14 call dword [eax+0x14]",
            source="bn",
        )
        appframe_indexes = self.indexes(
            by_address={"0x443140": "symbol:GetCurrentState"}
        )
        proofs = call_contract_verify_module._exact_targetless_vptr_call_proofs(
            appframe,
            source="bn",
            caller_start="0x4432f7",
            indexes=appframe_indexes,
        )
        self.assertEqual(
            "load(call-result(symbol:GetCurrentState))",
            proofs[6],
        )
        appframe_contract = extract_invocation_contract(
            appframe,
            source="bn",
            caller_identity="symbol:appframe-call-result",
            caller_start="0x4432f7",
            caller_end_exclusive="0x443307",
            indexes=appframe_indexes,
        )
        self.assertEqual(0x14, appframe_contract[1]["slot_displacement"])
        self.assertEqual(
            "load(call-result(symbol:GetCurrentState))",
            appframe_contract[1]["storage_identity"],
        )

        nested = parse_assembly(
            "004a3690 8b f1 mov esi, ecx\n"
            "004a374f 8b 7e 54 mov edi, dword [esi+0x54]\n"
            "004a3752 8b 47 08 mov eax, dword [edi+0x8]\n"
            "004a3755 8b 08 mov ecx, dword [eax]\n"
            "004a3758 ff 51 08 call dword [ecx+0x8]",
            source="bn",
        )
        nested_proofs = (
            call_contract_verify_module._exact_targetless_vptr_call_proofs(
                nested,
                source="bn",
                caller_start="0x4a3690",
                indexes=self.indexes(),
            )
        )
        self.assertEqual(
            "load(load(load(this+0x54)+0x8))",
            nested_proofs[4],
        )
        nested_contract = extract_invocation_contract(
            nested,
            source="bn",
            caller_identity="symbol:nested-targetless-receiver",
            caller_start="0x4a3690",
            caller_end_exclusive="0x4a375b",
            indexes=self.indexes(),
        )[0]
        self.assertEqual("virtual-slot", nested_contract["identity_kind"])
        self.assertEqual("", nested_contract["target_identity"])
        self.assertEqual(8, nested_contract["slot_displacement"])
        self.assertEqual(
            "load(load(load(this+0x54)+0x8))",
            nested_contract["storage_identity"],
        )

