    def test_schema87_appframe_switch_join_threads_exact_retail_cfg(self) -> None:
        first_call = 0x444000
        get_state = 0x443140
        first_bytes = b"\xe8" + struct.pack(
            "<i", get_state - (first_call + 5)
        )
        rows = parse_assembly(
            f"{first_call:08x} "
            + " ".join(f"{value:02x}" for value in first_bytes)
            + " call 0x443140\n"
            "00444005 8b f8 mov edi, eax\n"
            "00444007 8b d8 mov ebx, eax\n"
            "00444009 ff 24 85 00 50 00 00 "
            "jmp dword [eax*4+0x500000]\n"
            "00444010 90 nop\n"
            "00444011 eb 02 jmp 0x444015\n"
            "00444013 8b df mov ebx, edi\n"
            "00444015 8b 03 mov eax, dword [ebx]\n"
            "00444017 8b cb mov ecx, ebx\n"
            "00444019 ff 50 14 call dword [eax+0x14]",
            source="bn",
        )
        indexes = self.indexes(
            by_address={"0x443140": "symbol:GetCurrentState"}
        )
        without_switch = (
            call_contract_verify_module._exact_targetless_vptr_call_proofs(
                rows,
                source="bn",
                caller_start="0x444000",
                caller_end_exclusive="0x44401c",
                indexes=indexes,
            )
        )
        self.assertNotIn(9, without_switch)

        proofs = (
            call_contract_verify_module._exact_targetless_vptr_call_proofs(
                rows,
                source="bn",
                caller_start="0x444000",
                caller_end_exclusive="0x44401c",
                indexes=indexes,
                local_control_flow_indices=frozenset({3}),
                local_control_flow_targets={3: (4, 6)},
            )
        )
        self.assertEqual(
            "load(call-result(symbol:GetCurrentState))",
            proofs[9],
        )

        conflicting = list(rows)
        conflicting[6] = replace(
            conflicting[6],
            raw_text="xor ebx, ebx",
            bytes=("33", "db"),
        )
        self.assertNotIn(
            9,
            call_contract_verify_module._exact_targetless_vptr_call_proofs(
                conflicting,
                source="bn",
                caller_start="0x444000",
                caller_end_exclusive="0x44401c",
                indexes=indexes,
                local_control_flow_indices=frozenset({3}),
                local_control_flow_targets={3: (4, 6)},
            ),
        )

    def test_schema89_appframe_direct_branch_stack_reload_join_is_exact(
        self,
    ) -> None:
        get_state_call = 0x444100
        grow_call = 0x444114
        get_state = 0x443140
        grow = 0x443120
        get_state_bytes = b"\xe8" + struct.pack(
            "<i", get_state - (get_state_call + 5)
        )
        grow_bytes = b"\xe8" + struct.pack(
            "<i", grow - (grow_call + 5)
        )
        rows = parse_assembly(
            f"{get_state_call:08x} "
            + " ".join(f"{value:02x}" for value in get_state_bytes)
            + " call 0x443140\n"
            "00444105 8b d8 mov ebx, eax\n"
            "00444107 89 5c 24 10 mov dword [esp+0x10], ebx\n"
            "0044410b 49 dec ecx\n"
            "0044410c 74 06 je 0x444114\n"
            "0044410e 90 nop\n"
            "0044410f eb 08 jmp 0x444119\n"
            f"{grow_call:08x} "
            + " ".join(f"{value:02x}" for value in grow_bytes)
            + " call 0x443120\n"
            "00444119 8b 5c 24 10 mov ebx, dword [esp+0x10]\n"
            "0044411d 8b 03 mov eax, dword [ebx]\n"
            "0044411f 8b cb mov ecx, ebx\n"
            "00444121 ff 50 14 call dword [eax+0x14]",
            source="bn",
        )
        indexes = self.indexes(
            by_address={
                "0x443140": "symbol:GetCurrentState",
                "0x443120": "symbol:GrowStateArray",
            }
        )
        proofs = (
            call_contract_verify_module._exact_targetless_vptr_call_proofs(
                rows,
                source="bn",
                caller_start="0x444100",
                caller_end_exclusive="0x444124",
                indexes=indexes,
                direct_call_cleanup_by_instruction_index={0: 0, 7: 0},
            )
        )
        self.assertEqual(
            "load(call-result(symbol:GetCurrentState))",
            proofs[11],
        )

        conflicting = list(rows)
        conflicting[2] = parse_assembly(
            "00444107 89 7c 24 10 mov dword [esp+0x10], edi",
            source="bn",
        )[0]
        self.assertNotIn(
            11,
            call_contract_verify_module._exact_targetless_vptr_call_proofs(
                conflicting,
                source="bn",
                caller_start="0x444100",
                caller_end_exclusive="0x444124",
                indexes=indexes,
                direct_call_cleanup_by_instruction_index={0: 0, 7: 0},
            ),
        )

    def test_schema90_appframe_retn_cleanup_normalizes_physical_stack_slots(
        self,
    ) -> None:
        get_state = 0x443140
        cleanup_four = 0x443690
        rows = parse_assembly(
            "00443160 83 ec 24 sub esp, 0x24\n"
            "00443163 e8 d8 ff ff ff call 0x443140\n"
            "00443168 8b d8 mov ebx, eax\n"
            "0044316a 6a 00 push 0\n"
            "0044316c 89 5c 24 14 mov dword [esp+0x14], ebx\n"
            "00443170 e8 1b 05 00 00 call 0x443690\n"
            "00443175 8b 5c 24 10 mov ebx, dword [esp+0x10]\n"
            "00443179 8b 03 mov eax, dword [ebx]\n"
            "0044317b 8b cb mov ecx, ebx\n"
            "0044317d ff 50 14 call dword [eax+0x14]",
            source="bn",
        )
        indexes = self.indexes(
            by_address={
                f"0x{get_state:x}": "symbol:GetCurrentState",
                f"0x{cleanup_four:x}": "symbol:QueueGrow",
            }
        )
        bridge = SimpleNamespace(
            assembly=lambda address: (
                "00443140 c3 ret"
                if address == "0x443140"
                else "00443690 c2 04 00 retn 4"
                if address == "0x443690"
                else ""
            )
        )
        cleanups = (
            call_contract_verify_module
            ._retail_direct_call_cleanup_by_instruction_index(
                rows,
                caller_start="0x443160",
                caller_end_exclusive="0x443180",
                bridge=bridge,
            )
        )
        self.assertEqual({1: 0, 5: 4}, cleanups)
        proofs = call_contract_verify_module._exact_targetless_vptr_call_proofs(
            rows,
            source="bn",
            caller_start="0x443160",
            caller_end_exclusive="0x443180",
            indexes=indexes,
            direct_call_cleanup_by_instruction_index=cleanups,
        )
        self.assertEqual(
            "load(call-result(symbol:GetCurrentState))",
            proofs[9],
        )
        for cleanups in ({1: 0}, {1: 0, 5: 8}):
            with self.subTest(cleanups=cleanups):
                self.assertNotIn(
                    9,
                    call_contract_verify_module
                    ._exact_targetless_vptr_call_proofs(
                        rows,
                        source="bn",
                        caller_start="0x443160",
                        caller_end_exclusive="0x443180",
                        indexes=indexes,
                        direct_call_cleanup_by_instruction_index=cleanups,
                    ),
                )
        ambiguous_bridge = SimpleNamespace(
            assembly=lambda address: (
                "00443140 c3 ret"
                if address == "0x443140"
                else (
                    "00443690 c3 ret\n"
                    "00443691 c2 04 00 retn 4"
                )
                if address == "0x443690"
                else ""
            )
        )
        self.assertEqual(
            {1: 0},
            call_contract_verify_module
            ._retail_direct_call_cleanup_by_instruction_index(
                rows,
                caller_start="0x443160",
                caller_end_exclusive="0x443180",
                bridge=ambiguous_bridge,
            ),
        )

    def test_schema92_appframe_full_packages_precede_targetless_extraction(
        self,
    ) -> None:
        document = SimpleNamespace(collection=lambda _name: {})
        cases = (
            (
                "entry-this-edx",
                "0x442d00",
                "0x442d0b",
                (
                    "00442d00 8b f1 mov esi, ecx\n"
                    "00442d02 8b 16 mov edx, dword [esi]\n"
                    "00442d04 8b ce mov ecx, esi\n"
                    "00442d06 ff 52 64 call dword [edx+0x64]"
                ),
                {},
                3,
                "load(this)",
            ),
            (
                "retn4-ebx-eax",
                "0x443160",
                "0x443180",
                (
                    "00443160 83 ec 24 sub esp, 0x24\n"
                    "00443163 e8 d8 ff ff ff call 0x443140\n"
                    "00443168 8b d8 mov ebx, eax\n"
                    "0044316a 6a 00 push 0\n"
                    "0044316c 89 5c 24 14 mov dword [esp+0x14], ebx\n"
                    "00443170 e8 1b 05 00 00 call 0x443690\n"
                    "00443175 8b 5c 24 10 mov ebx, dword [esp+0x10]\n"
                    "00443179 8b 03 mov eax, dword [ebx]\n"
                    "0044317b 8b cb mov ecx, ebx\n"
                    "0044317d ff 50 14 call dword [eax+0x14]"
                ),
                {
                    "0x443140": "symbol:GetCurrentState",
                    "0x443690": "symbol:QueueGrow",
                },
                9,
                "load(call-result(symbol:GetCurrentState))",
            ),
            (
                "retn4-ebp-eax",
                "0x443310",
                "0x44332a",
                (
                    "00443310 83 ec 24 sub esp, 0x24\n"
                    "00443313 8b 6c 24 28 mov ebp, dword [esp+0x28]\n"
                    "00443317 6a 00 push 0\n"
                    "00443319 e8 72 03 00 00 call 0x443690\n"
                    "0044331e 8b 6c 24 28 mov ebp, dword [esp+0x28]\n"
                    "00443322 8b 45 00 mov eax, dword [ebp]\n"
                    "00443325 8b cd mov ecx, ebp\n"
                    "00443327 ff 50 08 call dword [eax+0x8]"
                ),
                {"0x443690": "symbol:QueueGrow"},
                7,
                "bounded-stack-receiver-vptr",
            ),
        )
        for label, start, end, assembly, targets, call_index, marker in cases:
            rows = parse_assembly(assembly, source="bn")
            caller_identity = f"symbol:recoil:function:{start}"
            indexes = self.indexes(
                by_address={start: caller_identity, **targets}
            )
            bridge = MagicMock()
            bridge.hexdump.return_value = ""
            bridge.assembly.side_effect = lambda address: (
                "00443140 c3 ret"
                if address == "0x443140"
                else "00443690 c2 04 00 retn 4"
                if address == "0x443690"
                else ""
            )
            with self.subTest(label=label):
                composed, package = (
                    call_contract_verify_module
                    ._compose_caller_scoped_retail_proof_package(
                        rows,
                        document=document,
                        caller_identity=caller_identity,
                        caller_start=start,
                        caller_end_exclusive=end,
                        indexes=indexes,
                        bridge=bridge,
                        retail_import_targets=(),
                    )
                )
                self.assertEqual(
                    marker,
                    dict(package.targetless_vptr_call_proofs)[call_index],
                )
                contract = extract_invocation_contract(
                    rows,
                    source="bn",
                    caller_identity=caller_identity,
                    caller_start=start,
                    caller_end_exclusive=end,
                    indexes=composed,
                )
                self.assertEqual(
                    marker,
                    contract[-1]["storage_identity"],
                )
                self.assertEqual(
                    "virtual-slot",
                    contract[-1]["identity_kind"],
                )

    def test_schema86_appframe_reviewed_eax_roots_keep_exact_receiver_sources(
        self,
    ) -> None:
        cases = (
            (
                "call-result-a",
                0x4432F7,
                0x14,
                "ebx",
            ),
            (
                "call-result-b",
                0x44363D,
                0x14,
                "ebx",
            ),
        )
        indexes = self.indexes(
            by_address={"0x443140": "symbol:GetCurrentState"}
        )
        for label, call_address, slot, receiver in cases:
            displacement = 0x443140 - (call_address + 5)
            rows = parse_assembly(
                f"{call_address:08x} "
                + " ".join(
                    f"{value:02x}"
                    for value in b"\xe8" + struct.pack("<i", displacement)
                )
                + " call 0x443140\n"
                + f"{call_address + 5:08x} 8b d8 mov {receiver}, eax\n"
                + f"{call_address + 7:08x} 8b 03 mov eax, dword [{receiver}]\n"
                + f"{call_address + 9:08x} 8b cb mov ecx, {receiver}\n"
                + f"{call_address + 11:08x} ff 50 14 "
                "call dword [eax+0x14]",
                source="bn",
            )
            contract = extract_invocation_contract(
                rows,
                source="bn",
                caller_identity=f"symbol:{label}",
                caller_start=hex(call_address),
                caller_end_exclusive=hex(call_address + 14),
                indexes=indexes,
            )
            self.assertEqual(slot, contract[1]["slot_displacement"])
            self.assertEqual(
                "load(call-result(symbol:GetCurrentState))",
                contract[1]["storage_identity"],
            )

        stack_rows = parse_assembly(
            "00443494 8b 6c 24 04 mov ebp, dword [esp+0x4]\n"
            "00443499 8b 45 00 mov eax, dword [ebp]\n"
            "0044349c 8b cd mov ecx, ebp\n"
            "0044349d ff 50 08 call dword [eax+0x8]",
            source="bn",
        )
        stack_contract = extract_invocation_contract(
            stack_rows,
            source="bn",
            caller_identity="symbol:incoming-stack-receiver",
            caller_start="0x443494",
            caller_end_exclusive="0x4434a0",
            indexes=indexes,
        )[0]
        self.assertEqual(8, stack_contract["slot_displacement"])
        self.assertEqual(
            "bounded-stack-receiver-vptr",
            stack_contract["storage_identity"],
        )

