    def test_schema98_cfg_saved_this_alias_requires_unanimous_restore_paths(
        self,
    ) -> None:
        exact = (
            "  00000 56 push esi\n"
            "  00001 8b f1 mov esi, ecx\n"
            "  00003 8b 4e 08 mov ecx, dword [esi+8]\n"
            "  00006 8b 01 mov eax, dword [ecx]\n"
            "  00008 ff 50 08 call dword [eax+8]\n"
            "  0000b 8b 4e 08 mov ecx, dword [esi+8]\n"
            "  0000e 8b 11 mov edx, dword [ecx]\n"
            "  00010 ff 52 74 call dword [edx+116]\n"
            "  00013 8b 4e 08 mov ecx, dword [esi+8]\n"
            "  00016 6a 01 push 1\n"
            "  00018 8b 01 mov eax, dword [ecx]\n"
            "  0001a ff 50 60 call dword [eax+96]\n"
            "  0001d 85 c0 test eax, eax\n"
            "  0001f 74 09 je 0x2a\n"
            "  00021 b8 01 00 00 00 mov eax, 1\n"
            "  00026 5e pop esi\n"
            "  00027 c2 04 00 ret 4\n"
            "  0002a 33 c0 xor eax, eax\n"
            "  0002c 5e pop esi\n"
            "  0002d c2 04 00 ret 4"
        )

        def proofs(assembly: str) -> dict[int, str]:
            return call_contract_verify_module._exact_targetless_vptr_call_proofs(
                parse_assembly(assembly, source="cod"),
                source="cod",
                caller_start="0x0",
                caller_end_exclusive="0x30",
                indexes=self.indexes(),
            )

        marker = "load(exact-receiver-field(this,+0x8))"
        self.assertEqual({4: marker, 7: marker, 11: marker}, proofs(exact))

        cases = {
            "clobbered-branch": exact.replace(
                "0002a 33 c0 xor eax, eax",
                "0002a 33 f6 xor esi, esi",
            ),
            "escaped-branch": exact.replace(
                "0002a 33 c0 xor eax, eax",
                "0002a 8b fe mov edi, esi",
            ),
            "partial-restore": exact.replace(
                "  0002c 5e pop esi\n", ""
            ),
            "mismatched-restore": exact.replace(
                "0002c 5e pop esi", "0002c 5f pop edi"
            ),
            "unknown-edge": exact.replace(
                "0001f 74 09 je 0x2a",
                "0001f 74 7f je $Lmissing",
            ),
            "loop-edge": exact.replace(
                "0001f 74 09 je 0x2a",
                "0001f 75 df jne 0x0",
            ),
            "field-byte-render-drift": exact.replace(
                "8b 4e 08 mov ecx, dword [esi+8]",
                "8b 4e 0c mov ecx, dword [esi+8]",
            ),
        }
        for label, assembly in cases.items():
            with self.subTest(label=label):
                self.assertNotIn(marker, proofs(assembly).values())

        slot_byte_render_drift = exact.replace(
            "ff 50 08 call dword [eax+8]",
            "ff 50 0c call dword [eax+8]",
        )
        self.assertNotIn(4, proofs(slot_byte_render_drift))

        def contracts(assembly: str) -> list[dict[str, object]]:
            return extract_invocation_contract(
                parse_assembly(assembly, source="cod"),
                source="cod",
                caller_identity="symbol:CfgSavedThisFixture",
                caller_start="0x0",
                caller_end_exclusive="0x30",
                indexes=self.indexes(),
            )

        expected = contracts(exact)
        wrong_field = contracts(
            exact.replace(
                "8b 4e 08 mov ecx, dword [esi+8]",
                "8b 4e 0c mov ecx, dword [esi+12]",
            )
        )
        self.assertEqual(
            "load(exact-receiver-field(this,+0xc))",
            wrong_field[0]["storage_identity"],
        )
        self.assertFalse(compare_call_contracts(expected, wrong_field)["passed"])

        wrong_slot = contracts(
            exact.replace(
                "ff 50 08 call dword [eax+8]",
                "ff 50 0c call dword [eax+12]",
            )
        )
        self.assertEqual(marker, wrong_slot[0]["storage_identity"])
        self.assertEqual(12, wrong_slot[0]["slot_displacement"])
        self.assertFalse(compare_call_contracts(expected, wrong_slot)["passed"])

    def test_schema99_cfg_saved_this_alias_ends_at_exact_restore(self) -> None:
        exact = (
            "  00000 55 push ebp\n"
            "  00001 8b ec mov ebp, esp\n"
            "  00003 56 push esi\n"
            "  00004 8b f1 mov esi, ecx\n"
            "  00006 8b 4e 04 mov ecx, dword [esi+4]\n"
            "  00009 8b 01 mov eax, dword [ecx]\n"
            "  0000b ff 50 04 call dword [eax+4]\n"
            "  0000e 8b 4e 04 mov ecx, dword [esi+4]\n"
            "  00011 8b 11 mov edx, dword [ecx]\n"
            "  00013 ff 52 08 call dword [edx+8]\n"
            "  00016 8b 4e 04 mov ecx, dword [esi+4]\n"
            "  00019 8b 01 mov eax, dword [ecx]\n"
            "  0001b ff 50 0c call dword [eax+12]\n"
            "  0001e 85 c0 test eax, eax\n"
            "  00020 74 2e je 0x50\n"
            "  00022 5e pop esi\n"
            "  00023 8b e5 mov esp, ebp\n"
            "  00025 c7 05 78 56 34 12 00 00 00 00 "
            "mov dword [0x12345678], 0\n"
            "  0002f b8 01 00 00 00 mov eax, 1\n"
            "  00034 64 89 0d 00 00 00 00 "
            "mov dword fs:__except_list, ecx\n"
            "  0003b 5d pop ebp\n"
            "  0003c e8 00 00 00 00 call 0x41\n"
            "  00041 c3 ret 0\n"
            "  00050 5e pop esi\n"
            "  00051 83 c4 10 add esp, 16\n"
            "  00054 c2 04 00 ret 4"
        )

        def proofs(assembly: str) -> dict[int, str]:
            return call_contract_verify_module._exact_targetless_vptr_call_proofs(
                parse_assembly(assembly, source="cod"),
                source="cod",
                caller_start="0x0",
                caller_end_exclusive="0x60",
                indexes=self.indexes(),
            )

        marker = "load(exact-receiver-field(this,+0x4))"
        # The authored absolute store, compiler SEH-chain restoration, frame
        # teardown, and unrelated direct call stay ordinary instructions.  The
        # POP ends only the saved-alias lifetime; it does not classify the tail.
        self.assertEqual({6: marker, 9: marker, 12: marker}, proofs(exact))

        cases = {
            "alias-read": exact.replace(
                "00025 c7 05 78 56 34 12 00 00 00 00 "
                "mov dword [0x12345678], 0",
                "00025 8b c6 mov eax, esi",
            ),
            "alias-redefinition": exact.replace(
                "00025 c7 05 78 56 34 12 00 00 00 00 "
                "mov dword [0x12345678], 0",
                "00025 33 f6 xor esi, esi",
            ),
            "alias-save": exact.replace(
                "00025 c7 05 78 56 34 12 00 00 00 00 "
                "mov dword [0x12345678], 0",
                "00025 56 push esi",
            ),
            "alias-second-restore": exact.replace(
                "00025 c7 05 78 56 34 12 00 00 00 00 "
                "mov dword [0x12345678], 0",
                "00025 5e pop esi",
            ),
            "alias-implicit-use": exact.replace(
                "00025 c7 05 78 56 34 12 00 00 00 00 "
                "mov dword [0x12345678], 0",
                "00025 a5 movsd",
            ),
            "resolved-post-restore-cycle": exact.replace(
                "00025 c7 05 78 56 34 12 00 00 00 00 "
                "mov dword [0x12345678], 0",
                "00025 75 fb jne 0x22",
            ),
            "unresolved-post-restore-edge": exact.replace(
                "00025 c7 05 78 56 34 12 00 00 00 00 "
                "mov dword [0x12345678], 0",
                "00025 75 7f jne $Lmissing",
            ),
            "malformed-return": exact.replace(
                "00041 c3 ret 0", "00041 c2 04 00 ret 8"
            ),
            "restore-bypass": exact.replace(
                "00020 74 2e je 0x50", "00020 74 1f je 0x41"
            ),
        }
        for label, assembly in cases.items():
            with self.subTest(label=label):
                self.assertNotIn(marker, proofs(assembly).values())

