        def proofs(assembly: str) -> dict[int, str]:
            return call_contract_verify_module._exact_targetless_vptr_call_proofs(
                parse_assembly(assembly, source="cod"),
                source="cod",
                caller_start="0x0",
                caller_end_exclusive="0x50",
                indexes=self.indexes(),
            )

        marker = "load(exact-receiver-field(this,+0x4))"
        self.assertEqual({10: marker}, proofs(exact))

        cases = {
            "missing-save": exact.replace("  00000 56 push esi\n", ""),
            "wrong-entry-root": exact.replace(
                "00001 8b f1 mov esi, ecx",
                "00001 8b f2 mov esi, edx",
            ),
            "rebind-bypass-to-call": exact.replace(
                "00008 74 36 je 0x40",
                "00008 74 0a je 0x14",
            ),
            "field-byte-render-drift": exact.replace(
                "8b 76 04 mov esi, dword [esi+4]",
                "8b 76 08 mov esi, dword [esi+4]",
            ),
            "ambiguous-rebind": exact.replace(
                "  00012 6a 01 push 1\n",
                "  00010 8b 76 08 mov esi, dword [esi+8]\n"
                "  00012 6a 01 push 1\n",
            ),
            "field-phase-clobber": exact.replace(
                "  00012 6a 01 push 1\n",
                "  00010 33 f6 xor esi, esi\n"
                "  00012 6a 01 push 1\n",
            ),
            "field-phase-escape": exact.replace(
                "  00012 6a 01 push 1\n",
                "  00010 8b fe mov edi, esi\n"
                "  00012 6a 01 push 1\n",
            ),
            "wrong-vptr-root": exact.replace(
                "8b 06 mov eax, dword [esi]",
                "8b 07 mov eax, dword [edi]",
            ),
            "result-reuse-not-from-eax": exact.replace(
                "00034 8b f0 mov esi, eax",
                "00034 8b f2 mov esi, edx",
            ),
            "result-reuse-not-after-direct-call": exact.replace(
                "0002f e8 00 00 00 00 call 0x34",
                "0002f 90 nop",
            ),
            "missing-restore": exact.replace("  00040 5e pop esi\n", ""),
            "post-restore-use": exact.replace(
                "  00041 c2 04 00 ret 4",
                "  00041 8b c6 mov eax, esi\n"
                "  00043 c2 04 00 ret 4",
            ),
            "resolved-cycle": exact.replace(
                "0003f 90 nop", "0003f 75 f5 jne 0x36"
            ),
            "unresolved-edge": exact.replace(
                "0003f 90 nop", "0003f 75 7f jne $Lmissing"
            ),
        }
        for label, assembly in cases.items():
            with self.subTest(label=label):
                self.assertNotIn(marker, proofs(assembly).values())

        different_field = exact.replace(
            "8b 76 04 mov esi, dword [esi+4]",
            "8b 76 08 mov esi, dword [esi+8]",
        )
        self.assertEqual(
            "load(exact-receiver-field(this,+0x8))",
            proofs(different_field)[10],
        )

        def contracts(assembly: str) -> list[dict[str, object]]:
            return extract_invocation_contract(
                parse_assembly(assembly, source="cod"),
                source="cod",
                caller_identity="symbol:PostReceiverAliasReuseFixture",
                caller_start="0x0",
                caller_end_exclusive="0x50",
                indexes=self.indexes(),
            )

        expected = contracts(exact)
        wrong_slot = contracts(
            exact.replace(
                "ff 50 04 call dword [eax+4]",
                "ff 50 08 call dword [eax+8]",
            )
        )
        self.assertEqual(marker, wrong_slot[1]["storage_identity"])
        self.assertEqual(8, wrong_slot[1]["slot_displacement"])
        self.assertFalse(compare_call_contracts(expected, wrong_slot)["passed"])

