    def test_player_saved_this_cycle_proof_is_host_recursion_independent(
        self,
    ) -> None:
        module = call_contract_verify_module

        def lifetime(*, late_cycle: bool):
            rows = [
                "00000 56 push esi",
                "00001 8b f1 mov esi, ecx",
            ]
            rows.extend(
                f"{offset:05x} 90 nop" for offset in range(3, 1203)
            )
            call_offset = 1203
            if late_cycle:
                rows.append("004b3 75 fd jne 0x4b2")
                call_offset = 1205
            rows.extend(
                (
                    f"{call_offset:05x} e8 00 00 00 00 call Helper",
                    f"{call_offset + 5:05x} 5e pop esi",
                    f"{call_offset + 6:05x} c3 ret 0",
                )
            )
            instructions = parse_assembly("\n".join(rows), source="cod")
            addresses = module._instruction_runtime_addresses(
                instructions,
                source="cod",
                caller_start=0,
            )
            return module._exact_candidate_cfg_saved_entry_this_alias_lifetime(
                instructions,
                invocation_indices=(len(instructions) - 3,),
                addresses=addresses,
                caller_start=0,
                caller_end=call_offset + 7,
                local_control_flow_indices=frozenset(),
                local_control_flow_targets={},
            )

        self.assertEqual(
            ("esi", 1, frozenset({1203})),
            lifetime(late_cycle=False),
        )
        self.assertIsNone(lifetime(late_cycle=True))

    def test_player_saved_this_cycle_proof_reaches_r4646_late_cycle(
        self,
    ) -> None:
        module = call_contract_verify_module
        artifact_root = (
            REPO_ROOT
            / "build"
            / "live-validation"
            / "worker-workspace-issue"
            / "wsi-20260822-013-r3360"
            / "call-contract-player_41ea90_42de10_authored_order"
        )
        cod_path = artifact_root / "player.cod"
        if not cod_path.is_file():
            self.skipTest("governed r4646 Player COD artifact is unavailable")
        symbol = (
            "?LoadMasterModalDataFromNode@Player@@YIX"
            "PAUPlayerMasterModalData@@PAUNode@zReader@@PBD@Z"
        )
        candidate = module._extract_cod_proc_with_local_switches(
            cod_path, symbol
        )
        self.assertEqual(779, len(candidate.instructions))
        invocation_indices = module._candidate_static_invocation_indices(
            candidate,
            caller_start="0x0",
            caller_end_exclusive="0x360",
        )
        addresses = module._instruction_runtime_addresses(
            candidate.instructions,
            source="cod",
            caller_start=0,
        )
        self.assertIsNone(
            module._exact_candidate_cfg_saved_entry_this_alias_lifetime(
                candidate.instructions,
                invocation_indices=invocation_indices,
                addresses=addresses,
                caller_start=0,
                caller_end=0x360,
                local_control_flow_indices=(
                    candidate.local_control_flow_indices
                ),
                local_control_flow_targets=(
                    candidate.local_control_flow_targets
                ),
            )
        )

