    def test_exact_c705_callback_stores_are_not_inbound_calls(self) -> None:
        helper = call_contract_verify_module._exact_inbound_callback_address_materialization
        exact_stores = (
            (0x431D88, 0x539DE8, 0x433AD0),
            (0x431D92, 0x539DE4, 0x433CA0),
            (0x431D9C, 0x56BC9C, 0x4340C0),
            (0x431DB0, 0x56BCA4, 0x434240),
        )
        for source, storage, target in exact_stores:
            body = b"\xc7\x05" + struct.pack("<I", storage) + struct.pack("<I", target)
            exact = parse_assembly(
                f"{source:08x} "
                + " ".join(f"{value:02x}" for value in body)
                + f" mov dword [0x{storage:x}], 0x{target:x}",
                source="bn",
            )
            self.assertTrue(
                helper(
                    exact,
                    source_address=hex(source),
                    target_address=hex(target),
                )
            )
        exact = parse_assembly(
            "00431d88 c7 05 e8 9d 53 00 d0 3a 43 00 "
            "mov dword [0x539de8], 0x433ad0",
            source="bn",
        )
        malformed = {
            "wrong-target-bytes": replace(
                exact[0],
                bytes=(*exact[0].bytes[:-1], "44"),
            ),
            "wrong-storage-rendering": replace(
                exact[0], raw_text="mov dword [0x539dec], 0x433ad0"
            ),
            "wrong-target-rendering": replace(
                exact[0], raw_text="mov dword [0x539de8], 0x433ca0"
            ),
            "wrong-opcode": replace(
                exact[0], bytes=("c6", *exact[0].bytes[1:])
            ),
        }
        for label, instruction in malformed.items():
            with self.subTest(label=label):
                if label == "wrong-opcode":
                    self.assertFalse(
                        helper((instruction,), source_address="0x431d88", target_address="0x433ad0")
                    )
                else:
                    with self.assertRaisesRegex(ValueError, "absolute-store"):
                        helper((instruction,), source_address="0x431d88", target_address="0x433ad0")

    def test_adjacent_bn_rows_prove_one_exact_targetless_callback_cell(self) -> None:
        data = call_contract_fixture(1)
        data_id = "recoil:data:0x56bc68"
        data["symbols"][data_id] = {
            "binary": "recoil",
            "kind": "data",
            "address": "0x56bc68",
            "start": "0x56bc68",
            "extent_state": "unknown",
        }
        rows = (
            DataVariable("0x56bc64", "cell_56bc64", "_cell_56bc64", "void *", 0),
            DataVariable(
                "0x56bc68",
                "g_zVideo_pfnDrawPointColor16",
                "_g_zVideo_pfnDrawPointColor16",
                "void *",
                0,
            ),
            DataVariable("0x56bc6c", "cell_56bc6c", "_cell_56bc6c", "void *", 0),
        )
        indexes = build_identity_indexes(
            ProgressDocument(data), bridge_data_rows=rows
        )
        self.assertIn(
            StorageContainer(0x56BC68, 0x56BC6C, f"storage:{data_id}"),
            indexes.storage_containers,
        )
        for caller in (0x476CF0, 0x477B30, 0x479020):
            contract = extract_invocation_contract(
                parse_assembly(
                    f"{caller:08x} ff 15 68 bc 56 00 call dword [0x56bc68]",
                    source="bn",
                ),
                source="bn",
                caller_identity=f"symbol:caller:{caller:x}",
                caller_start=hex(caller),
                caller_end_exclusive=hex(caller + 6),
                indexes=indexes,
            )[0]
            self.assertEqual("callback", contract["identity_kind"])
            self.assertEqual("", contract["target_identity"])
            self.assertEqual(f"storage:{data_id}", contract["storage_identity"])
            self.assertEqual(0, contract["slot_displacement"])
            self.assertIsNone(contract["cleanup_bytes"])

        symbolic = extract_invocation_contract(
            parse_assembly(
                "00476cf0 ff 15 68 bc 56 00 "
                "call dword [g_zVideo_pfnDrawPointColor16]",
                source="bn",
            ),
            source="bn",
            caller_identity="symbol:caller:symbolic-cell",
            caller_start="0x476cf0",
            caller_end_exclusive="0x476cf6",
            indexes=indexes,
        )[0]
        self.assertEqual(0, symbolic["slot_displacement"])
        self.assertEqual(f"storage:{data_id}", symbolic["storage_identity"])

        one_sided = build_identity_indexes(
            ProgressDocument(data), bridge_data_rows=rows[:2]
        )
        self.assertNotIn(
            f"storage:{data_id}",
            {container.identity for container in one_sided.storage_containers},
        )
        duplicate = build_identity_indexes(
            ProgressDocument(data), bridge_data_rows=(*rows, rows[1])
        )
        self.assertNotIn(
            f"storage:{data_id}",
            {container.identity for container in duplicate.storage_containers},
        )

    def test_zloc_getproc_result_cell_is_exact_targetless_cleanup4_callback(
        self,
    ) -> None:
        cell = "0x56b568"
        storage = "storage:recoil:data:0x56b568"
        reader_text = (
            "004a5b20 a1 68 b5 56 00 mov eax, dword [0x56b568]\n"
            "004a5b25 85 c0 test eax, eax\n"
            "004a5b27 74 07 je 0x4a5b30\n"
            "004a5b29 51 push ecx\n"
            "004a5b2a ff d0 call eax\n"
            "004a5b2c 83 c4 04 add esp, 4\n"
            "004a5b2f c3 ret\n"
            "004a5b30 33 c0 xor eax, eax\n"
            "004a5b32 c3 ret"
        )
        writer_text = (
            "004a5ad0 90 nop\n"
            "004a5ae2 68 f8 2f 4e 00 push aZLocGetID\n"
            "004a5ae7 90 nop\n"
            "004a5aed 50 push eax\n"
            "004a5aee ff 15 bc c0 4c 00 call dword [GetProcAddress]\n"
            "004a5af4 a3 68 b5 56 00 mov dword [0x56b568], eax\n"
            "004a5af9 90 nop\n"
            "004a5afc c3 ret"
        )
        indexes = self.indexes(
            storage_by_address={
                cell: storage,
                "0x4cc0bc": "iat:GetProcAddress",
            },
            storage_by_name={"GetProcAddress": "iat:GetProcAddress"},
            storage_containers=(
                StorageContainer(0x56B568, 0x56B56C, storage),
            ),
        )

        class Bridge:
            def __init__(
                self,
                *,
                mutation: str = "",
                writer: str = writer_text,
            ) -> None:
                self.mutation = mutation
                self.writer = writer

            def hexdump(self, address: str, size: int) -> str:
                if (address, size) == (cell, 4):
                    return "0056b568 00 00 00 00"
                if (address, size) == ("0x4e2ff8", 10):
                    value = (
                        b"ZLocGetIX\x00"
                        if self.mutation == "literal"
                        else b"ZLocGetID\x00"
                    )
                    return "004e2ff8 " + " ".join(
                        f"{item:02x}" for item in value
                    )
                return ""

            def get_json(self, endpoint: str, **_kwargs: object) -> dict:
                if endpoint != "getXrefsTo":
                    return {}
                refs = ["0x4a5af4", "0x4a5b20"]
                if self.mutation == "extra-xref":
                    refs.append("0x4a5af9")
                return {
                    "code_references": [
                        {"source_address": address} for address in refs
                    ],
                    "data_references": (
                        [{"source_address": "0x4e2ff8"}]
                        if self.mutation == "data-xref"
                        else []
                    ),
                    "total": len(refs) + (self.mutation == "data-xref"),
                    "truncated": self.mutation == "truncated",
                }

            def function_at(self, address: str) -> list[dict[str, str]]:
                return (
                    [{"name": "zLoc::LoadMessagesDll"}]
                    if address == "0x4a5af4"
                    else []
                )

            def function_info(self, name: str) -> dict[str, str]:
                if name != "zLoc::LoadMessagesDll":
                    return {}
                return {
                    "start": (
                        "0x4a5ad1"
                        if self.mutation == "writer-extent"
                        else "0x4a5ad0"
                    )
                }

            def assembly(self, address: str) -> str:
                return self.writer if address in {"0x4a5ad0", "0x4a5ad1"} else ""

        def prove(
            *,
            reader: str = reader_text,
            bridge: Bridge | None = None,
            current_indexes: IdentityIndexes = indexes,
        ) -> IdentityIndexes:
            rows = parse_assembly(reader, source="bn")
            live_bridge = bridge or Bridge()
            composed = (
                call_contract_verify_module
                ._comparison_scoped_retail_zero_callback_storage_indexes(
                    rows,
                    caller_start="0x4a5b20",
                    caller_end_exclusive="0x4a5b33",
                    indexes=current_indexes,
                    bridge=live_bridge,
                )
            )
            return (
                call_contract_verify_module
                ._comparison_scoped_retail_stored_callback_targets(
                    rows,
                    caller_start="0x4a5b20",
                    caller_end_exclusive="0x4a5b33",
                    indexes=composed,
                    bridge=live_bridge,
                )
            )

        composed = prove()
        contract = extract_invocation_contract(
            parse_assembly(reader_text, source="bn"),
            source="bn",
            caller_identity="symbol:recoil:function:0x4a5b20",
            caller_start="0x4a5b20",
            caller_end_exclusive="0x4a5b33",
            indexes=composed,
        )[0]
        self.assertEqual("indirect", contract["dispatch"])
        self.assertEqual("callback", contract["identity_kind"])
        self.assertEqual("", contract["target_identity"])
        self.assertEqual(storage, contract["storage_identity"])
        self.assertEqual(4, contract["cleanup_bytes"])
        self.assertEqual({}, composed.reviewed_static_callback_target_by_storage)

        drift_cases = {
            "extra-xref": (reader_text, Bridge(mutation="extra-xref"), indexes),
            "data-xref": (reader_text, Bridge(mutation="data-xref"), indexes),
            "truncated": (reader_text, Bridge(mutation="truncated"), indexes),
            "writer-bytes": (
                reader_text,
                Bridge(writer=writer_text.replace("ff 15 bc", "ff 15 bd")),
                indexes,
            ),
            "writer-extent": (reader_text, Bridge(mutation="writer-extent"), indexes),
            "literal": (reader_text, Bridge(mutation="literal"), indexes),
            "import": (
                reader_text,
                Bridge(),
                replace(
                    indexes,
                    storage_by_address={
                        cell: storage,
                        "0x4cc0bc": "iat:LoadLibraryA",
                    },
                ),
            ),
            "reader-cfg": (
                reader_text.replace("74 07 je 0x4a5b30", "74 06 je 0x4a5b2f"),
                Bridge(),
                indexes,
            ),
            "cleanup": (
                reader_text.replace("83 c4 04 add esp, 4", "83 c4 08 add esp, 8"),
                Bridge(),
                indexes,
            ),
            "extent": (
                reader_text,
                Bridge(),
                replace(
                    indexes,
                    storage_containers=(
                        StorageContainer(0x56B568, 0x56B570, storage),
                    ),
                ),
            ),
        }
        for label, (reader, bridge, current_indexes) in drift_cases.items():
            with self.subTest(label=label), self.assertRaises(ValueError):
                prove(
                    reader=reader,
                    bridge=bridge,
                    current_indexes=current_indexes,
                )

    def test_entry_register_spill_reload_and_appframe_lineages_are_generic(self) -> None:
        entry_rows = parse_assembly(
            "00457c50 89 54 24 08 mov dword [esp+0x8], edx\n"
            "00457c54 8b ea mov ebp, edx\n"
            "00457c56 ff d5 call ebp\n"
            "00457c58 50 push eax\n"
            "00457c59 50 push eax\n"
            "00457c5a 8b 54 24 10 mov edx, dword [esp+0x10]\n"
            "00457c5e ff d2 call edx",
            source="bn",
        )
        lineages = call_contract_verify_module._entry_register_lineage_calls(
            entry_rows,
            caller_start="0x457c50",
            caller_end_exclusive="0x457c60",
            entry_registers=frozenset({"ecx", "edx"}),
        )
        self.assertEqual(
            [(0, "0x457c56", "ebp", "edx"), (1, "0x457c5e", "edx", "edx")],
            lineages,
        )

        inbound_rows = parse_assembly(
            "00432a5b ba e0 3d 43 00 mov edx, 0x433de0\n"
            "00432a60 b9 30 3c 43 00 mov ecx, 0x433c30\n"
            "00432a65 e8 e6 51 02 00 call 0x457c50",
            source="bn",
        )
        self.assertEqual(
            {
                "ecx": "symbol:entry-ecx-target",
                "edx": "symbol:entry-edx-target",
            },
            call_contract_verify_module._immediate_entry_register_targets(
                inbound_rows,
                call_address="0x432a65",
                indexes=self.indexes(
                    by_address={
                        "0x433c30": "symbol:entry-ecx-target",
                        "0x433de0": "symbol:entry-edx-target",
                    }
                ),
                callable_registers=frozenset({"ecx", "edx"}),
            ),
        )

        this_rows = parse_assembly(
            "00442d00 8b f1 mov esi, ecx\n"
            "00442d4f 8b 16 mov edx, dword [esi]\n"
            "00442d51 8b ce mov ecx, esi\n"
            "00442d53 ff 52 64 call dword [edx+0x64]\n"
            "00442d5a 8b 06 mov eax, dword [esi]\n"
            "00442d5c 8b ce mov ecx, esi\n"
            "00442d5e ff 50 70 call dword [eax+0x70]\n"
            "00442fd3 8b 16 mov edx, dword [esi]\n"
            "00442fd5 8b ce mov ecx, esi\n"
            "00442fd7 ff 92 a8 00 00 00 call dword [edx+0xa8]",
            source="bn",
        )
        this_calls = extract_invocation_contract(
            this_rows,
            source="bn",
            caller_identity="symbol:appframe-this",
            caller_start="0x442d00",
            caller_end_exclusive="0x442fdd",
            indexes=self.indexes(),
        )
        self.assertEqual([0x64, 0x70, 0xA8], [row["slot_displacement"] for row in this_calls])
        self.assertEqual(["load(this)"] * 3, [row["storage_identity"] for row in this_calls])

        stack_rows = parse_assembly(
            "00443310 8b 6c 24 04 mov ebp, dword [esp+0x4]\n"
            "00443314 8b 45 00 mov eax, dword [ebp]\n"
            "00443317 8b cd mov ecx, ebp\n"
            "00443319 ff 50 08 call dword [eax+0x8]",
            source="bn",
        )
        stack_call = extract_invocation_contract(
            stack_rows,
            source="bn",
            caller_identity="symbol:appframe-stack",
            caller_start="0x443310",
            caller_end_exclusive="0x44331c",
            indexes=self.indexes(),
        )[0]
        self.assertEqual("virtual-slot", stack_call["identity_kind"])
        self.assertEqual(8, stack_call["slot_displacement"])

        queued_rows = parse_assembly(
            "004432f1 8b 4c 24 28 mov ecx, dword [esp+0x28]\n"
            "004432f5 8b 11 mov edx, dword [ecx]\n"
            "004432f7 ff 52 08 call dword [edx+0x8]",
            source="bn",
        )
        queued_call = extract_invocation_contract(
            queued_rows,
            source="bn",
            caller_identity="symbol:appframe-queued",
            caller_start="0x4432f1",
            caller_end_exclusive="0x4432fa",
            indexes=self.indexes(),
        )[0]
        self.assertEqual("bounded-stack-receiver-vptr", queued_call["storage_identity"])
        self.assertEqual(8, queued_call["slot_displacement"])

        result_rows = parse_assembly(
            "00443160 e8 9b fe ff ff call 0x443000\n"
            "00443165 8b d8 mov ebx, eax\n"
            "00443167 8b cb mov ecx, ebx\n"
            "00443169 8b 03 mov eax, dword [ebx]\n"
            "0044316b ff 50 14 call dword [eax+0x14]",
            source="bn",
        )
        result_contracts = extract_invocation_contract(
            result_rows,
            source="bn",
            caller_identity="symbol:appframe-state",
            caller_start="0x443160",
            caller_end_exclusive="0x44316e",
            indexes=self.indexes(
                by_address={"0x443000": "symbol:GetCurrentState"}
            ),
        )
        self.assertEqual("virtual-slot", result_contracts[1]["identity_kind"])
        self.assertEqual(0x14, result_contracts[1]["slot_displacement"])
        self.assertEqual(
            "load(call-result(symbol:GetCurrentState))",
            result_contracts[1]["storage_identity"],
        )

    def test_schema110_shared_zero_callback_populations_are_complete_and_generic(
        self,
    ) -> None:
        cases = (
            {
                "cell": "0x53a2e4",
                "storage": "storage:recoil:data:0x53a2e4",
                "start": "0x461970",
                "end": "0x461a90",
                "current": "0x461a67",
                "readers": (
                    ("0x461a67", "0x461970", "ReadCallbackA", "0x461a76"),
                    ("0x461b69", "0x461aa0", "ReadCallbackB", "0x461b78"),
                    ("0x461ccf", "0x461ba0", "ReadCallbackC", "0x461cde"),
                    ("0x461e7e", "0x461d00", "ReadCallbackD", "0x461e8d"),
                ),
                "writers": (
                    (
                        "0x461eb3",
                        "0x461eb0",
                        "SetCallback",
                        "00461eb0 90 nop\n"
                        "00461eb1 90 nop\n"
                        "00461eb2 90 nop\n"
                        "00461eb3 89 0d e4 a2 53 00 "
                        "mov dword [0x53a2e4], ecx\n"
                        "00461eb9 c3 ret",
                    ),
                ),
            },
            {
                "cell": "0x56aafc",
                "storage": "storage:recoil:data:0x56aafc",
                "start": "0x48afe0",
                "end": "0x48b203",
                "current": "0x48b1f4",
                "readers": (
                    ("0x48b1f4", "0x48afe0", "ReadDPlayCallback", "0x48b200"),
                ),
                "writers": (
                    (
                        "0x489d26",
                        "0x489d00",
                        "InitializeDPlayCallback",
                        "00489d24 33 ff xor edi, edi\n"
                        "00489d26 89 3d fc aa 56 00 "
                        "mov dword [0x56aafc], edi\n"
                        "00489d2c c3 ret",
                    ),
                    (
                        "0x489f90",
                        "0x489f90",
                        "SetDPlayCallback",
                        "00489f90 89 0d fc aa 56 00 "
                        "mov dword [0x56aafc], ecx\n"
                        "00489f96 c3 ret",
                    ),
                ),
            },
            {
                # zImage's optional callback is a complete one-reader,
                # no-writer population: static zero initialization is the only
                # population fact and must not imply a callable identity.
                "cell": "0x53d788",
                "storage": "storage:recoil:data:0x53d788",
                "start": "0x46de50",
                "end": "0x46df50",
                "current": "0x46de80",
                "readers": (
                    (
                        "0x46de80",
                        "0x46de50",
                        "ReadOptionalImageCallback",
                        "0x46de90",
                    ),
                ),
                "writers": (),
            },
        )

        def reader_assembly(
            source: str,
            cell: str,
            call: str,
        ) -> str:
            source_value = int(source, 16)
            call_value = int(call, 16)
            cell_bytes = " ".join(
                f"{value:02x}" for value in struct.pack("<I", int(cell, 16))
            )
            padding = "\n".join(
                f"{address:08x} 90 nop"
                for address in range(source_value + 12, call_value)
            )
            branch_displacement = call_value - source_value - 7
            return (
                f"{source_value:08x} a1 {cell_bytes} "
                f"mov eax, dword [{cell}]\n"
                f"{source_value + 5:08x} 85 c0 test eax, eax\n"
                f"{source_value + 7:08x} 74 {branch_displacement:02x} "
                f"je 0x{call_value + 2:x}\n"
                f"{source_value + 9:08x} 83 c9 ff or ecx, -1\n"
                + (padding + "\n" if padding else "")
                + f"{call_value:08x} ff d0 call eax\n"
                f"{call_value + 2:08x} c3 ret"
            )

        for spec in cases:
            cell = str(spec["cell"])
            storage = str(spec["storage"])
            assemblies = {
                str(function_start): reader_assembly(
                    str(source), cell, str(call)
                )
                for source, function_start, _name, call in spec["readers"]
            }
            assemblies.update(
                {
                    str(function_start): str(assembly)
                    for _source, function_start, _name, assembly in spec["writers"]
                }
            )
            names_by_source = {
                str(source): (str(name), str(function_start))
                for source, function_start, name, _call in spec["readers"]
            }
            names_by_source.update(
                {
                    str(source): (str(name), str(function_start))
                    for source, function_start, name, _assembly in spec["writers"]
                }
            )
            xrefs = tuple(
                [str(row[0]) for row in spec["readers"]]
                + [str(row[0]) for row in spec["writers"]]
            )

            class Bridge:
                def __init__(self, *, mutation: str = "") -> None:
                    self.mutation = mutation

                def hexdump(self, address: str, size: int) -> str:
                    value = "01 00 00 00" if self.mutation == "nonzero" else "00 00 00 00"
                    return f"{address.removeprefix('0x')} {value}" if size == 4 else ""

                def get_json(self, endpoint: str, **_kwargs):
                    rows = list(xrefs)
                    if self.mutation == "extra-xref":
                        rows.append("0x400001")
                    if self.mutation == "missing-reader":
                        rows = [str(row[0]) for row in spec["writers"]]
                    return {
                        "code_references": [
                            {"source_address": address} for address in rows
                        ],
                        "data_references": (
                            [{"source_address": "0x500000"}]
                            if self.mutation == "data-xref"
                            else []
                        ),
                        "total": len(rows) + (1 if self.mutation == "data-xref" else 0),
                        "truncated": False,
                    }

                def function_at(self, address: str):
                    row = names_by_source.get(address)
                    return [{"name": row[0]}] if row is not None else []

                def function_info(self, name: str):
                    starts = [
                        start
                        for current_name, start in names_by_source.values()
                        if current_name == name
                    ]
                    return {"start": starts[0]} if len(starts) == 1 else {}

                def assembly(self, address: str) -> str:
                    return assemblies.get(address, "")

            current_rows = parse_assembly(
                assemblies[str(spec["start"])], source="bn"
            )
            indexes = self.indexes(
                storage_by_address={cell: storage},
                storage_containers=(
                    StorageContainer(
                        int(cell, 16), int(cell, 16) + 4, storage
                    ),
                ),
            )
            composed = call_contract_verify_module._comparison_scoped_retail_zero_callback_storage_indexes(
                current_rows,
                caller_start=str(spec["start"]),
                caller_end_exclusive=str(spec["end"]),
                indexes=indexes,
                bridge=Bridge(),
            )
            composed = call_contract_verify_module._comparison_scoped_retail_stored_callback_targets(
                current_rows,
                caller_start=str(spec["start"]),
                caller_end_exclusive=str(spec["end"]),
                indexes=composed,
                bridge=Bridge(),
            )
            self.assertEqual(
                {}, composed.reviewed_static_callback_target_by_storage
            )
            contract = extract_invocation_contract(
                current_rows,
                source="bn",
                caller_identity=f"symbol:fixture:{cell}",
                caller_start=str(spec["start"]),
                caller_end_exclusive=str(spec["end"]),
                indexes=composed,
            )[0]
            self.assertEqual("callback", contract["identity_kind"])
            self.assertEqual(storage, contract["storage_identity"])
            self.assertEqual("", contract["target_identity"])

            for mutation, error in (
                ("extra-xref", "complete validated reader/writer"),
                ("missing-reader", "complete xrefs omit the activating reader"),
                ("data-xref", "ambiguous or colliding complete xref"),
            ):
                with self.subTest(cell=cell, mutation=mutation), self.assertRaisesRegex(
                    ValueError, error
                ):
                    call_contract_verify_module._comparison_scoped_retail_stored_callback_targets(
                        current_rows,
                        caller_start=str(spec["start"]),
                        caller_end_exclusive=str(spec["end"]),
                        indexes=composed,
                        bridge=Bridge(mutation=mutation),
                    )

            nonzero = call_contract_verify_module._comparison_scoped_retail_stored_callback_targets(
                current_rows,
                caller_start=str(spec["start"]),
                caller_end_exclusive=str(spec["end"]),
                indexes=replace(
                    composed,
                    reviewed_static_callback_target_by_storage={},
                ),
                bridge=Bridge(mutation="nonzero"),
            )
            self.assertEqual(
                {}, nonzero.reviewed_static_callback_target_by_storage
            )

    def test_zcom_interface_map_resolver_is_targetless_per_entry_callback(
        self,
    ) -> None:
        module = call_contract_verify_module
        expected = [
            {
                "ordinal": 0,
                "form": "call",
                "dispatch": "indirect",
                "identity_kind": "callback",
                "target_identity": "",
                "storage_identity": module._ZCOM_INTERFACE_MAP_RESOLVER_STORAGE,
                "slot_displacement": None,
                "cleanup_bytes": None,
            },
            {
                "ordinal": 1,
                "form": "call",
                "dispatch": "indirect",
                "identity_kind": "virtual-slot",
                "target_identity": "",
                "storage_identity": module._ZCOM_INTERFACE_MAP_ADDREF_STORAGE,
                "slot_displacement": 4,
                "cleanup_bytes": None,
            },
        ]
        definition = CandidateCallerDefinition(
            symbol=module._ZCOM_INTERFACE_MAP_CALLER_SYMBOL,
            data=module._ZCOM_INTERFACE_MAP_BODY,
            relocations=(),
            relocation_mask=(False,) * len(module._ZCOM_INTERFACE_MAP_BODY),
            undefined_external_functions=(),
            section_start=0,
            section_end=len(module._ZCOM_INTERFACE_MAP_BODY),
        )
        candidate = CandidateAssembly(
            instructions=(),
            local_control_flow_indices=frozenset(),
            caller_definition=definition,
        )
        indexes = self.indexes(
            by_address={
                module._ZCOM_INTERFACE_MAP_CALLER_START:
                module._ZCOM_INTERFACE_MAP_CALLER_IDENTITY
            }
        )
        with patch.object(
            module,
            "_require_zcom_interface_map_resolver_instruction_body",
        ) as exact_body:
            bridges = module._zcom_interface_map_resolver_candidate_register_bridge(
                expected,
                candidate,
                caller_identity=module._ZCOM_INTERFACE_MAP_CALLER_IDENTITY,
                caller_start=module._ZCOM_INTERFACE_MAP_CALLER_START,
                caller_end_exclusive=module._ZCOM_INTERFACE_MAP_CALLER_END_EXCLUSIVE,
                indexes=indexes,
            )
        exact_body.assert_called_once_with((), source="cod")
        self.assertEqual(
            {module._ZCOM_INTERFACE_MAP_RESOLVER_CANDIDATE_CALL},
            set(bridges),
        )
        bridge = bridges[module._ZCOM_INTERFACE_MAP_RESOLVER_CANDIDATE_CALL]
        self.assertEqual("ecx", bridge.register)
        self.assertEqual("callback", bridge.identity_kind)
        self.assertEqual(module._ZCOM_INTERFACE_MAP_RESOLVER_STORAGE, bridge.storage_identity)
        self.assertNotIn("static", bridge.storage_identity)
        with patch.object(
            module, "_require_zcom_interface_map_resolver_instruction_body"
        ):
            addref = module._zcom_interface_map_addref_candidate_indirect_bridge(
                expected,
                candidate,
                caller_identity=module._ZCOM_INTERFACE_MAP_CALLER_IDENTITY,
                caller_start=module._ZCOM_INTERFACE_MAP_CALLER_START,
                caller_end_exclusive=module._ZCOM_INTERFACE_MAP_CALLER_END_EXCLUSIVE,
                indexes=indexes,
            )
        self.assertEqual(
            {module._ZCOM_INTERFACE_MAP_ADDREF_CANDIDATE_CALL}, set(addref)
        )
        self.assertEqual(
            module._ZCOM_INTERFACE_MAP_ADDREF_STORAGE,
            addref[module._ZCOM_INTERFACE_MAP_ADDREF_CANDIDATE_CALL]
            .storage_identity,
        )
        self.assertEqual(
            4,
            addref[module._ZCOM_INTERFACE_MAP_ADDREF_CANDIDATE_CALL]
            .slot_displacement,
        )

        for label, mutated_expected, mutated_candidate in (
            (
                "static-target",
                [{**expected[0], "target_identity": "symbol:wrong"}, expected[1]],
                candidate,
            ),
            (
                "body-drift",
                expected,
                replace(
                    candidate,
                    caller_definition=replace(
                        definition,
                        data=definition.data[:-1] + b"\xcc",
                    ),
                ),
            ),
            (
                "addref-slot-drift",
                [expected[0], {**expected[1], "slot_displacement": 8}],
                candidate,
            ),
        ):
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "rejects expected targetless truth",
            ):
                module._zcom_interface_map_resolver_candidate_register_bridge(
                    mutated_expected,
                    mutated_candidate,
                    caller_identity=module._ZCOM_INTERFACE_MAP_CALLER_IDENTITY,
                    caller_start=module._ZCOM_INTERFACE_MAP_CALLER_START,
                    caller_end_exclusive=module._ZCOM_INTERFACE_MAP_CALLER_END_EXCLUSIVE,
                    indexes=indexes,
                )

    def test_r4564_finite_retail_adapter_rows_are_exact_and_targetless(
        self,
    ) -> None:
        module = call_contract_verify_module
        indexes = self.indexes(
            storage_by_address={"0x53d788": "storage:recoil:data:0x53d788"},
            storage_containers=(
                StorageContainer(
                    0x53D788,
                    0x53D78C,
                    "storage:recoil:data:0x53d788",
                ),
            ),
        )
        retail_import_targets = (
            SimpleNamespace(
                address="0x4cc594",
                dll="MSVCRT.dll",
                import_name="fwrite",
                import_ordinal=None,
            ),
            SimpleNamespace(
                address="0x4cc664",
                dll="USER32.dll",
                import_name="MessageBoxA",
                import_ordinal=None,
            ),
        )

        class ZImageBridge:
            def hexdump(self, address: str, size: int) -> str:
                if address == "0x53d788" and size == 4:
                    return "53d788 00 00 00 00"
                return ""

            def get_json(self, endpoint: str, **kwargs):
                self_endpoint = endpoint
                self_address = kwargs.get("address")
                if self_endpoint != "getXrefsTo" or self_address != "0x53d788":
                    return {}
                return {
                    "code_references": [{"source_address": "0x46de99"}],
                    "data_references": [],
                    "total": 1,
                    "truncated": False,
                }

        zimage = parse_assembly(
            "0046de99 a1 88 d7 53 00 mov eax, dword [0x53d788]\n"
            "0046de9e 85 c0 test eax, eax\n"
            "0046dea0 74 06 je 0x46dea8\n"
            "0046dea2 8b ce mov ecx, esi\n"
            "0046dea4 ff d0 call eax\n"
            "0046dea6 89 07 mov dword [edi], eax\n"
            "0046dedc ff 15 18 bc 56 00 call dword [0x56bc18]\n"
            "0046df09 ff 15 08 bc 56 00 call dword [0x56bc08]",
            source="bn",
        )
        registers, vptrs, indirect = (
            module._r4564_retail_provenance_adapters(
                zimage,
                caller_start="0x46de50",
                caller_end_exclusive="0x46df50",
                indexes=indexes,
                bridge=ZImageBridge(),
                retail_import_targets=retail_import_targets,
            )
        )
        self.assertEqual({}, vptrs)
        self.assertEqual({}, indirect)
        self.assertEqual("callback", registers["0x46dea4"].identity_kind)
        self.assertEqual(
            "storage:recoil:data:0x53d788",
            registers["0x46dea4"].storage_identity,
        )

        player = parse_assembly(
            "0042dc0e 8b 0e mov ecx, dword [esi]\n"
            "0042dc10 ff 51 04 call dword [ecx+0x4]",
            source="bn",
        )
        registers, vptrs, indirect = (
            module._r4564_retail_provenance_adapters(
                player,
                caller_start="0x42db50",
                caller_end_exclusive="0x42dc30",
                indexes=indexes,
            )
        )
        self.assertEqual({}, registers)
        self.assertEqual({}, indirect)
        self.assertEqual(4, vptrs["0x42dc10"].slot_displacement)
        self.assertEqual("", vptrs["0x42dc10"].target_identity)

        zmodel = parse_assembly(
            "00481a0c 8b 35 94 c5 4c 00 mov esi, dword [0x4cc594]\n"
            "00481a54 ff d6 call esi\n"
            "00481a56 83 c4 10 add esp, 0x10",
            source="bn",
        )
        registers, vptrs, indirect = (
            module._r4564_retail_provenance_adapters(
                zmodel,
                caller_start="0x4815c0",
                caller_end_exclusive="0x481aa0",
                indexes=indexes,
                retail_import_targets=retail_import_targets,
            )
        )
        self.assertEqual("iat:fwrite", registers["0x481a54"].storage_identity)
        self.assertEqual({}, vptrs)
        self.assertEqual({}, indirect)

        message_box_sites = (
            "0x48a595", "0x48a5b3", "0x48a5e5", "0x48a602",
            "0x48a634", "0x48a652", "0x48a683", "0x48a6a1",
            "0x48a6d3", "0x48a6f0", "0x48a722", "0x48a740",
            "0x48a771", "0x48a78f", "0x48a7c9", "0x48a7e7",
            "0x48a805", "0x48a822", "0x48a840", "0x48a85e",
            "0x48a87b",
        )
        znetwork_rows = (
            [
                "0048a52d e8 00 00 00 00 call 0x48a532",
                "0048a564 ff 51 60 call dword [ecx+0x60]",
            ]
            + [
                    f"00{site.removeprefix('0x')} ff 15 64 c6 4c 00 "
                    "call dword [0x4cc664]"
                    for site in message_box_sites
                    if int(site, 16) < 0x48A7B0
            ]
            + [
                "0048a7b0 ff 24 85 00 00 00 00 "
                "jmp dword [eax*4+0x0]",
            ]
            + [
                    f"00{site.removeprefix('0x')} ff 15 64 c6 4c 00 "
                    "call dword [0x4cc664]"
                    for site in message_box_sites
                    if int(site, 16) > 0x48A7B0
            ]
            + [
                "0048a886 e8 00 00 00 00 call 0x48a88b",
                "0048a897 ff 51 10 call dword [ecx+0x10]",
            ]
        )
        def znetwork_adapter(
            rows=znetwork_rows,
            *,
            end="0x48a909",
            imports=retail_import_targets,
        ):
            return module._r4564_retail_provenance_adapters(
                parse_assembly("\n".join(rows), source="bn"),
                caller_start="0x48a520",
                caller_end_exclusive=end,
                indexes=indexes,
                retail_import_targets=imports,
            )
        registers, vptrs, indirect = znetwork_adapter()
        self.assertEqual({}, registers)
        self.assertEqual({}, indirect)
        self.assertEqual({"0x48a564", "0x48a897"}, set(vptrs))
        self.assertEqual(0x60, vptrs["0x48a564"].slot_displacement)
        self.assertEqual(0x10, vptrs["0x48a897"].slot_displacement)

        znetwork_mutations = (
            ("missing", znetwork_rows[:-1], "instruction drifted|ordered 25-call"),
            (
                "extra",
                [*znetwork_rows, "0048a8a0 e8 00 00 00 00 call 0x48a8a5"],
                "ordered 25-call",
            ),
            (
                "multiplicity",
                [*znetwork_rows[:3], znetwork_rows[2], *znetwork_rows[3:]],
                "coordinates collide|ordered 25-call",
            ),
            (
                "order",
                [znetwork_rows[1], znetwork_rows[0], *znetwork_rows[2:]],
                "ordered 25-call",
            ),
            (
                "direct-opcode",
                [
                    znetwork_rows[0].replace(
                        "e8 00 00 00 00", "ff d0 90 90 90"
                    ),
                    *znetwork_rows[1:],
                ],
                "direct E8",
            ),
            (
                "iat",
                [
                    row.replace("ff 15 64 c6 4c 00", "ff 15 68 c6 4c 00")
                    if "48a595" in row else row
                    for row in znetwork_rows
                ],
                "instruction drifted|FF15",
            ),
            (
                "vptr",
                [
                    row.replace("ff 51 60", "ff 51 64")
                    if "48a564" in row else row
                    for row in znetwork_rows
                ],
                "instruction drifted",
            ),
            (
                "jump-class",
                [
                    row.replace("jmp dword", "call dword")
                    if "48a7b0" in row else row
                    for row in znetwork_rows
                ],
                "ordered 25-call",
            ),
            (
                "jump-opcode",
                [
                    row.replace("ff 24 85", "ff 25 85")
                    if "48a7b0" in row else row
                    for row in znetwork_rows
                ],
                "FF24 jump-table",
            ),
        )
        for label, rows, error in znetwork_mutations:
            with self.subTest(znetwork=label), self.assertRaisesRegex(
                ValueError, error
            ):
                znetwork_adapter(rows)
        with self.assertRaisesRegex(ValueError, "extent drifted"):
            znetwork_adapter(end="0x48a980")
        with self.assertRaisesRegex(ValueError, "IAT identity drifted"):
            znetwork_adapter(imports=tuple(
                SimpleNamespace(
                    address=row.address,
                    dll=row.dll,
                    import_name="MessageBeep",
                    import_ordinal=row.import_ordinal,
                )
                if row.address == "0x4cc664" else row
                for row in retail_import_targets
            ))

        render = parse_assembly(
            "00494a99 ff 54 24 74 call dword [esp+0x74]",
            source="bn",
        )
        registers, vptrs, indirect = (
            module._r4564_retail_provenance_adapters(
                render,
                caller_start="0x493df0",
                caller_end_exclusive="0x494af0",
                indexes=indexes,
                retail_import_targets=retail_import_targets,
            )
        )
        self.assertEqual({}, registers)
        self.assertEqual({}, vptrs)
        self.assertEqual("callback", indirect["0x494a99"].identity_kind)
        self.assertIn(
            "6320c8-6320d4", indirect["0x494a99"].storage_identity
        )

        render_last = parse_assembly(
            "00498a32 ff 94 24 88 00 00 00 call dword [esp+0x88]\n"
            "00498b5c ff 94 24 88 00 00 00 call dword [esp+0x88]",
            source="bn",
        )
        _registers, _vptrs, last_indirect = (
            module._r4564_retail_provenance_adapters(
                render_last,
                caller_start="0x497ac0",
                caller_end_exclusive="0x498bd0",
                indexes=indexes,
                retail_import_targets=retail_import_targets,
            )
        )
        self.assertEqual({"0x498a32", "0x498b5c"}, set(last_indirect))

        for label, rows, start, end, error in (
            (
                "player-slot",
                parse_assembly(
                    "0042dc0e 8b 0e mov ecx, dword [esi]\n"
                    "0042dc10 ff 51 08 call dword [ecx+0x8]",
                    source="bn",
                ),
                "0x42db50", "0x42dc30", "instruction drifted",
            ),
            (
                "zmodel-iat",
                zmodel,
                "0x4815c0", "0x481aa0", "IAT identity drifted",
            ),
            (
                "render-extent",
                render,
                "0x493df0", "0x494ae0", "extent drifted",
            ),
        ):
            current_import_targets = (
                tuple(
                    SimpleNamespace(
                        address=row.address,
                        dll=row.dll,
                        import_name="fread",
                        import_ordinal=row.import_ordinal,
                    )
                    if row.address == "0x4cc594"
                    else row
                    for row in retail_import_targets
                )
                if label == "zmodel-iat"
                else retail_import_targets
            )
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, error
            ):
                module._r4564_retail_provenance_adapters(
                    rows,
                    caller_start=start,
                    caller_end_exclusive=end,
                    indexes=indexes,
                    retail_import_targets=current_import_targets,
                )

    def test_znetwork_retail_execution_end_is_derived_inside_byte_envelope(
        self,
    ) -> None:
        module = call_contract_verify_module

        def execution_rows(
            *,
            omit: int | None = None,
            terminal: str = "c3 ret",
            append_tail_instruction: bool = False,
        ):
            lines = [
                f"{address:08x} 90 nop"
                for address in range(0x48A520, 0x48A908)
                if address != omit
            ]
            lines.append(f"0048a908 {terminal}")
            if append_tail_instruction:
                lines.append("0048a909 90 nop")
            return parse_assembly("\n".join(lines), source="bn")

        rows = execution_rows()
        self.assertEqual(
            "0x48a909",
            module._retail_call_contract_comparison_end_exclusive(
                rows,
                caller_start="0x48a520",
                caller_end_exclusive="0x48a980",
            ),
        )
        self.assertEqual(
            "0x401100",
            module._retail_call_contract_comparison_end_exclusive(
                parse_assembly("00401000 c3 ret", source="bn"),
                caller_start="0x401000",
                caller_end_exclusive="0x401100",
            ),
        )

        adversarial = (
            (
                "tracker-envelope",
                rows,
                "0x48a909",
                "tracker byte envelope drifted",
            ),
            (
                "missing-row",
                execution_rows(omit=0x48A700),
                "0x48a980",
                "not complete and contiguous",
            ),
            (
                "terminal-opcode",
                execution_rows(terminal="90 nop"),
                "0x48a980",
                "execution end drifted",
            ),
            (
                "tail-instruction",
                execution_rows(append_tail_instruction=True),
                "0x48a980",
                "execution end drifted",
            ),
        )
        for label, mutated_rows, envelope_end, message in adversarial:
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, message
            ):
                module._retail_call_contract_comparison_end_exclusive(
                    mutated_rows,
                    caller_start="0x48a520",
                    caller_end_exclusive=envelope_end,
                )

    def test_znetwork_attached_switch_table_is_finite_and_fail_closed(
        self,
    ) -> None:
        module = call_contract_verify_module
        instruction_specs = {
            0x48A7A8: ("33 d2", "xor edx, edx"),
            0x48A7AA: (
                "8a 90 2c a9 48 00",
                "mov dl, byte [eax+0x48a92c]",
            ),
            0x48A7B0: (
                "ff 24 95 0c a9 48 00",
                "jmp dword [edx*4+0x48a90c]",
            ),
            0x48A908: ("c3", "ret"),
        }
        lines = []
        address = 0x48A520
        while address < 0x48A909:
            encoded, rendered = instruction_specs.get(
                address, ("90", "nop")
            )
            lines.append(f"{address:08x} {encoded} {rendered}")
            address += len(bytes.fromhex(encoded))
        rows = parse_assembly("\n".join(lines), source="bn")
        self.assertEqual(
            0x77, len(module._ZNETWORK_OPEN_SELECTED_SESSION_TAIL)
        )

        class TailBridge:
            def __init__(self, tail: bytes) -> None:
                self.tail = tail

            def hexdump(self, address: str, size: int) -> str:
                self_address = address
                self_size = size
                if self_address != "0x48a909" or self_size != 0x77:
                    return ""
                return "48a909 " + self.tail.hex(" ")

        targets = (
            module._znetwork_open_selected_session_retail_switch_targets(
                rows,
                caller_start="0x48a520",
                caller_end_exclusive="0x48a980",
                caller_execution_end_exclusive="0x48a909",
                bridge=TailBridge(
                    module._ZNETWORK_OPEN_SELECTED_SESSION_TAIL
                ),
            )
        )
        self.assertEqual(1, len(targets))
        dispatch_index, target_indices = next(iter(targets.items()))
        self.assertEqual(8, len(target_indices))
        self.assertTrue(all(index > dispatch_index for index in target_indices))

        bad_tail = bytearray(module._ZNETWORK_OPEN_SELECTED_SESSION_TAIL)
        bad_tail[3] ^= 1
        with self.assertRaisesRegex(ValueError, "jump table.*drifted"):
            module._znetwork_open_selected_session_retail_switch_targets(
                rows,
                caller_start="0x48a520",
                caller_end_exclusive="0x48a980",
                caller_execution_end_exclusive="0x48a909",
                bridge=TailBridge(bytes(bad_tail)),
            )
        with self.assertRaisesRegex(ValueError, "execution extent drifted"):
            module._znetwork_open_selected_session_retail_switch_targets(
                rows,
                caller_start="0x48a520",
                caller_end_exclusive="0x48a980",
                caller_execution_end_exclusive="0x48a980",
                bridge=TailBridge(
                    module._ZNETWORK_OPEN_SELECTED_SESSION_TAIL
                ),
            )

