    def test_runtime_factory_or_this_field_join_remains_targetless(self) -> None:
        rows = parse_assembly(
            "00500000 8b f1 mov esi, ecx\n"
            "00500002 85 c0 test eax, eax\n"
            "00500004 74 0a je 0x500010\n"
            "00500006 e8 f5 ff 00 00 call 0x510000\n"
            "0050000b 8b f8 mov edi, eax\n"
            "0050000d eb 04 jmp 0x500013\n"
            "0050000f 90 nop\n"
            "00500010 8d 7e 44 lea edi, [esi+0x44]\n"
            "00500013 8b 47 08 mov eax, dword [edi+0x8]\n"
            "00500016 8b 08 mov ecx, dword [eax]\n"
            "00500018 50 push eax\n"
            "00500019 ff 91 d0 00 00 00 call dword [ecx+0xd0]",
            source="bn",
        )
        indexes = self.indexes(
            by_address={"0x510000": "symbol:AcquireRuntimeObject"}
        )
        contract = extract_invocation_contract(
            rows,
            source="bn",
            caller_identity="symbol:runtime-object-join",
            caller_start="0x500000",
            caller_end_exclusive="0x50001f",
            indexes=indexes,
        )
        self.assertEqual(2, len(contract))
        dynamic = contract[1]
        self.assertEqual("virtual-slot", dynamic["identity_kind"])
        self.assertEqual("", dynamic["target_identity"])
        self.assertEqual(0xD0, dynamic["slot_displacement"])
        self.assertIn("runtime-object-join(", dynamic["storage_identity"])
        self.assertIn(
            "call-result(symbol:AcquireRuntimeObject)",
            dynamic["storage_identity"],
        )
        self.assertIn("this+0x44", dynamic["storage_identity"])

