    @staticmethod
    def copy_listing(
        *,
        prefix: str = "",
        replacements: dict[str, str] | None = None,
    ) -> str:
        exact = (
            "00000 8b 01 mov eax, dword [ecx]\n"
            "00002 83 ec 08 sub esp, 8\n"
            "00005 56 push esi\n"
            "00006 33 f6 xor esi, esi\n"
            "00008 85 c0 test eax, eax\n"
            "0000a 74 07 je 0x13\n"
            "0000c 33 c0 xor eax, eax\n"
            "0000e 5e pop esi\n"
            "0000f 83 c4 08 add esp, 8\n"
            "00012 c3 ret\n"
            "00013 a1 00 00 00 00 mov eax, dword [0]\n"
            "00018 83 e8 00 sub eax, 0\n"
            "0001b 74 24 je 0x41\n"
            "0001d 48 dec eax\n"
            "0001e 75 36 jne 0x56\n"
            "00020 8b 49 4c mov ecx, dword [ecx+0x4c]\n"
            "00023 8d 54 24 04 lea edx, dword [esp+4]\n"
            "00027 52 push edx\n"
            "00028 51 push ecx\n"
            "00029 8b 01 mov eax, dword [ecx]\n"
            "0002b ff 50 4c call dword [eax+0x4c]\n"
            "0002e 8b 4c 24 04 mov ecx, dword [esp+4]\n"
            "00032 8b c6 mov eax, esi\n"
            "00034 f7 d8 neg eax\n"
            "00036 1b c0 sbb eax, eax\n"
            "00038 f7 d0 not eax\n"
            "0003a 23 c1 and eax, ecx\n"
            "0003c 5e pop esi\n"
            "0003d 83 c4 08 add esp, 8\n"
            "00040 c3 ret\n"
            "00041 8b 49 4c mov ecx, dword [ecx+0x4c]\n"
            "00044 8d 54 24 08 lea edx, dword [esp+8]\n"
            "00048 52 push edx\n"
            "00049 8d 54 24 08 lea edx, dword [esp+8]\n"
            "0004d 8b 01 mov eax, dword [ecx]\n"
            "0004f 52 push edx\n"
            "00050 51 push ecx\n"
            "00051 ff 50 10 call dword [eax+0x10]\n"
            "00054 8b f0 mov esi, eax\n"
            "00056 8b 4c 24 04 mov ecx, dword [esp+4]\n"
            "0005a 8b c6 mov eax, esi\n"
            "0005c f7 d8 neg eax\n"
            "0005e 1b c0 sbb eax, eax\n"
            "00060 5e pop esi\n"
            "00061 f7 d0 not eax\n"
            "00063 23 c1 and eax, ecx\n"
            "00065 83 c4 08 add esp, 8\n"
            "00068 c3 ret"
        )
        for old, new in (replacements or {}).items():
            exact = exact.replace(old, new)
        return exact.replace(
            "00000 8b 01 mov eax, dword [ecx]\n",
            "00000 8b 01 mov eax, dword [ecx]\n" + prefix,
        )

    def proofs(
        self,
        listing: str,
        *,
        source: str = "cod",
        caller_start: str = "0x4a34e0",
        caller_end: str = "0x4a3590",
    ) -> dict[int, str]:
        return call_contract_verify_module._exact_targetless_vptr_call_proofs(
            parse_assembly(listing, source=source),
            source=source,
            caller_start=caller_start,
            caller_end_exclusive=caller_end,
            indexes=self.indexes(),
        )

    def finite_proofs(
        self,
        listing: str,
        *,
        source: str = "cod",
        caller_start: str = "0x4a34e0",
        caller_end: str = "0x4a3590",
        local_control_flow_indices: frozenset[int] = frozenset(),
        local_control_flow_targets: dict[int, tuple[int, ...]] | None = None,
    ) -> dict[int, str]:
        rows = parse_assembly(listing, source=source)
        start = int(caller_start, 16)
        addresses = call_contract_verify_module._instruction_runtime_addresses(
            rows,
            source=source,
            caller_start=start,
        )
        invocations = [
            index
            for index, instruction in enumerate(rows)
            if call_contract_verify_module._instruction_mnemonic(instruction)
            in {"call", "jmp"}
            and call_contract_verify_module._exact_invocation_encoding(
                instruction,
                mnemonic=call_contract_verify_module._instruction_mnemonic(
                    instruction
                ),
            )
        ]
        return call_contract_verify_module._exact_candidate_zsnd_a3d_entry_this_receiver_field_vptr_proofs(
            rows,
            invocation_indices=invocations,
            addresses=addresses,
            caller_start=start,
            caller_end=int(caller_end, 16),
            local_control_flow_indices=local_control_flow_indices,
            local_control_flow_targets=local_control_flow_targets or {},
        )

    def test_schema121_zsnd_a3d_live_shape_normalizes_exact_receiver_lineage(
        self,
    ) -> None:
        rows = parse_assembly(self.listing(), source="cod")
        proofs = call_contract_verify_module._exact_targetless_vptr_call_proofs(
            rows,
            source="cod",
            caller_start="0x4a34e0",
            caller_end_exclusive="0x4a3590",
            indexes=self.indexes(),
        )
        call_index = next(
            index
            for index, instruction in enumerate(rows)
            if call_contract_verify_module._instruction_mnemonic(instruction)
            == "call"
        )
        self.assertEqual({call_index: self.marker}, proofs)
        self.assertEqual(
            {call_index: self.marker},
            self.finite_proofs(self.listing()),
        )
        finite_helper = (
            call_contract_verify_module
            ._exact_candidate_zsnd_a3d_entry_this_receiver_field_vptr_proofs
        )
        with patch.object(
            call_contract_verify_module,
            "_exact_candidate_zsnd_a3d_entry_this_receiver_field_vptr_proofs",
            wraps=finite_helper,
        ) as consumed_receiver_proof:
            contract = extract_invocation_contract(
                rows,
                source="cod",
                caller_identity="symbol:recoil:function:0x4a34e0",
                caller_start="0x4a34e0",
                caller_end_exclusive="0x4a3590",
                indexes=self.indexes(),
            )
        consumed_receiver_proof.assert_called_once()
        consumed_arguments = consumed_receiver_proof.call_args.kwargs
        self.assertEqual(0x4A34E0, consumed_arguments["caller_start"])
        self.assertEqual(0x4A3590, consumed_arguments["caller_end"])
        self.assertEqual(
            [call_index],
            list(consumed_arguments["invocation_indices"]),
        )
        self.assertEqual(1, len(contract))
        self.assertEqual("virtual-slot", contract[0]["identity_kind"])
        self.assertEqual("", contract[0]["target_identity"])
        self.assertEqual(0x2C, contract[0]["slot_displacement"])
        self.assertEqual(self.marker, contract[0]["storage_identity"])

