    def test_schema121_zsnd_copy_receiver_lineage_fails_closed_on_drift(
        self,
    ) -> None:
        cases = {
            "caller-start": {"caller_start": "0x4a3610"},
            "caller-extent": {"caller_end": "0x4a3680"},
            "non-candidate-coordinate-space": {"source": "bn"},
            "missing-entry": {
                "listing": self.copy_listing().replace(
                    "00000 8b 01 mov eax, dword [ecx]\n", ""
                ),
            },
            "receiver-field": {
                "listing": self.copy_listing(
                    replacements={
                        "00041 8b 49 4c mov ecx, dword [ecx+0x4c]":
                        "00041 8b 49 48 mov ecx, dword [ecx+0x48]"
                    }
                ),
            },
            "first-argument-address": {
                "listing": self.copy_listing(
                    replacements={
                        "00044 8d 54 24 08 lea edx, dword [esp+8]":
                        "00044 8d 54 24 04 lea edx, dword [esp+4]"
                    }
                ),
            },
            "second-argument-address": {
                "listing": self.copy_listing(
                    replacements={
                        "00049 8d 54 24 08 lea edx, dword [esp+8]":
                        "00049 8d 54 24 04 lea edx, dword [esp+4]"
                    }
                ),
            },
            "vptr-load": {
                "listing": self.copy_listing(
                    replacements={
                        "0004d 8b 01 mov eax, dword [ecx]":
                        "0004d 8b 11 mov edx, dword [ecx]"
                    }
                ),
            },
            "argument-order": {
                "listing": self.copy_listing(
                    replacements={"00050 51 push ecx": "00050 52 push edx"}
                ),
            },
            "slot": {
                "listing": self.copy_listing(
                    replacements={
                        "00051 ff 50 10 call dword [eax+0x10]":
                        "00051 ff 50 14 call dword [eax+0x14]"
                    }
                ),
            },
            "entry-ecx-clobber": {
                "listing": self.copy_listing(
                    prefix="00003 8b cb mov ecx, ebx\n"
                ),
            },
            "invocation-ordinal": {
                "listing": self.copy_listing(
                    prefix="00003 e8 00 00 00 00 call 0x8\n"
                ),
            },
            "missing-governed-row": {
                "listing": self.copy_listing().replace(
                    "00048 52 push edx\n", ""
                ),
            },
        }
        for label, changes in cases.items():
            arguments = {
                "listing": self.copy_listing(),
                "source": "cod",
                "caller_start": "0x4a3620",
                "caller_end": "0x4a3690",
            }
            arguments.update(changes)
            with self.subTest(label=label):
                proofs = self.finite_proofs(**arguments)
                self.assertNotIn(self.marker, proofs.values())

        # Candidate parser metadata is authoritative for local control flow.
        # If the branch that is the only entry path to the governed receiver
        # is present but has no resolved target, the finite proof and the
        # active extractor must both refuse the receiver normalization.
        rows = parse_assembly(self.copy_listing(), source="cod")
        branch_index = 12
        self.assertIn("je 0x41", rows[branch_index].text)
        proofs = self.finite_proofs(
            self.copy_listing(),
            caller_start="0x4a3620",
            caller_end="0x4a3690",
            local_control_flow_indices=frozenset({branch_index}),
        )
        self.assertNotIn(self.marker, proofs.values())
        contract = extract_invocation_contract(
            rows,
            source="cod",
            caller_identity="symbol:recoil:function:0x4a3620",
            caller_start="0x4a3620",
            caller_end_exclusive="0x4a3690",
            indexes=self.indexes(),
            local_control_flow_indices=frozenset({branch_index}),
            local_control_flow_targets={},
        )
        self.assertNotEqual(self.marker, contract[1]["storage_identity"])


