            "0002a 5d pop ebp\n"
            "0002b 5b pop ebx\n"
            "0002c c2 0c 00 ret 12\n"
            "0002f 8b cb mov ecx, ebx\n"
            f"00031 e8 00 00 00 00 call {cls.acquire_symbol}\n"
            "00036 8b f8 mov edi, eax\n"
