    @classmethod
    def candidate_assembly(cls) -> CandidateAssembly:
        rows = tuple(parse_assembly(cls.listing(), source="cod"))
        helper_body = bytes.fromhex(
            "56 8b 71 34 85 f6 74 36 8b 41 2c 85 c0 74 2f "
            "33 c0 85 f6 7e 1d 8b 71 38 40 d9 44 86 fc d8 "
            "05 00 00 00 00 8b 71 3c d8 61 30 d9 5c 86 fc "
            "3b 41 34 7c e3 89 0d 00 00 00 00 89 15 00 00 "
            "00 00 5e c3"
        )
        helper_relocations = (
            (0x1F, 0x06, "_g_Time_UnscaledAccumulatedTimeSec"),
            (0x34, 0x06, "_g_zSndLastVoice"),
            (0x3A, 0x06, "_g_zSndLastVoiceHandle"),
        )
        helper_mask = [False] * len(helper_body)
        for offset, _kind, _name in helper_relocations:
            helper_mask[offset : offset + 4] = [True] * 4
        addresses = call_contract_verify_module._instruction_runtime_addresses(
            rows, source="cod", caller_start=0
        )
        caller_data = bytearray(0x110)
        for instruction, offset in zip(rows, addresses):
            assert offset is not None
            body = bytes(int(item, 16) for item in instruction.bytes)
            caller_data[offset : offset + len(body)] = body
        caller_mask = [False] * len(caller_data)
        caller_relocations = (
            (0xD0, 0x14, cls.refresh_canonical),
            (0xEF, 0x06, "_kZSndPlaySourceFile$S33375"),
            (0xF6, 0x14, cls.report_symbol),
        )
        for offset, _kind, _name in caller_relocations:
            caller_mask[offset : offset + 4] = [True] * 4
        return CandidateAssembly(
            instructions=rows,
            local_control_flow_indices=frozenset(),
            tu_local_function_definitions={
                cls.refresh_canonical: CandidateTuLocalFunctionDefinition(
                    symbol=cls.refresh_canonical,
                    data=helper_body,
                    relocations=tuple(
                        CoffRelocation(
                            offset=offset,
                            symbol_index=100 + index,
                            type=kind,
                            symbol_name=name,
                        )
                        for index, (offset, kind, name) in enumerate(
                            helper_relocations
                        )
                    ),
                    relocation_mask=tuple(helper_mask),
                    section_size=len(helper_body),
                    section_external_functions=(cls.refresh_canonical,),
                    section_is_comdat=True,
                    comdat_selection=1,
                )
            },
            caller_definition=CandidateCallerDefinition(
                symbol=(
                    "?PlayOnDirectSound@zSndSample@@QAIPAUzSndPlayHandle@@"
                    "HPAUzVec3@@0H@Z"
                ),
                data=bytes(caller_data),
                relocations=tuple(
                    CoffRelocation(
                        offset=offset,
                        symbol_index=200 + index,
                        type=kind,
                        symbol_name=name,
                    )
                    for index, (offset, kind, name) in enumerate(
                        caller_relocations
                    )
                ),
                relocation_mask=tuple(caller_mask),
                undefined_external_functions=(),
            ),
        )

    def extract(
        self,
        listing: str | None = None,
        *,
        inbound_roots: frozenset[str] = frozenset(),
        caller_end: str = "0x49fcf0",
    ) -> list[dict[str, object]]:
        return extract_invocation_contract(
            parse_assembly(listing or self.listing(), source="cod"),
            source="cod",
            caller_identity="symbol:recoil:function:0x49fbb0",
            caller_start="0x49fbb0",
            caller_end_exclusive=caller_end,
            indexes=self.indexes(),
            reviewed_inbound_entry_register_roots=inbound_roots,
        )

    def proof_ordinals(self, listing: str) -> set[int]:
        rows = parse_assembly(listing, source="cod")
        addresses = call_contract_verify_module._instruction_runtime_addresses(
            rows, source="cod", caller_start=0x49FBB0
        )
        invocation_indices = [
            index
            for index, instruction in enumerate(rows)
            if call_contract_verify_module._instruction_mnemonic(instruction)
            in {"call", "jmp"}
            and call_contract_verify_module._exact_invocation_encoding(
                instruction,
                mnemonic=(
                    call_contract_verify_module._instruction_mnemonic(
                        instruction
                    )
                ),
            )
        ]
        proofs = (
            call_contract_verify_module
            ._exact_candidate_zsnd_play_directsound_selected_backend_vptr_proofs(
                rows,
                invocation_indices=invocation_indices,
                addresses=addresses,
                caller_start=0x49FBB0,
                caller_end=0x49FCF0,
                indexes=self.indexes(),
                local_control_flow_indices=frozenset(),
                local_control_flow_targets={},
            )
        )
        return {
            ordinal
            for ordinal, index in enumerate(invocation_indices)
            if proofs.get(index) == self.marker
        }

    def test_schema123_complete_caller_uses_active_extractor(self) -> None:
        finite = (
            call_contract_verify_module
            ._exact_candidate_zsnd_play_directsound_selected_backend_vptr_proofs
        )
        with patch.object(
            call_contract_verify_module,
            "_exact_candidate_zsnd_play_directsound_selected_backend_vptr_proofs",
            wraps=finite,
        ) as consumed:
            contract = self.extract(inbound_roots=frozenset({"ecx"}))
        consumed.assert_called_once()
        self.assertEqual(10, len(contract))
        for ordinal, slot in ((1, 0x24), (2, 0x50), (5, 0x3C), (6, 0x34), (8, 0x30)):
            with self.subTest(ordinal=ordinal):
                self.assertEqual("virtual-slot", contract[ordinal]["identity_kind"])
                self.assertEqual("", contract[ordinal]["target_identity"])
                self.assertEqual(slot, contract[ordinal]["slot_displacement"])
                self.assertEqual(
                    self.inbound_marker,
                    contract[ordinal]["storage_identity"],
                )

    def test_schema123_inbound_root_rebase_fails_closed_on_scope_drift(
        self,
    ) -> None:
        for label, roots, caller_end in (
            ("wrong-root", frozenset({"edx"}), "0x49fcf0"),
            ("ambiguous-roots", frozenset({"ecx", "edx"}), "0x49fcf0"),
            ("wrong-extent", frozenset({"ecx"}), "0x49fcf1"),
        ):
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "unresolved indirect register storage",
            ):
                self.extract(inbound_roots=roots, caller_end=caller_end)

    def test_schema123_receiver_arms_fail_closed_independently(self) -> None:
        cases = {
            "get-status": (
                {"00063 ff 51 24": "00063 ff 51 28"},
                {2, 5, 6, 8},
            ),
            "restore": (
                {"00073 ff 51 50": "00073 ff 51 54"},
                {1, 5, 6, 8},
            ),
            "volume": (
                {"000b3 8b 46 24": "000b3 8b 46 28"},
                {1, 2, 6, 8},
            ),
            "current": (
                {"000c8 ff 52 34": "000c8 ff 52 38"},
                {1, 2, 5, 8},
            ),
            "play": (
                {"000d9 83 e2 01": "000d9 83 e2 02"},
                {1, 2, 5, 6},
            ),
        }
        for label, (replacements, retained) in cases.items():
            with self.subTest(label=label):
                self.assertEqual(
                    retained,
                    self.proof_ordinals(self.listing(replacements)),
                )

    def test_schema123_projection_expands_volume_and_removes_helper(self) -> None:
        candidate = self.candidate_assembly()
        contract = self.extract(inbound_roots=frozenset({"ecx"}))
        expected = [
            *[deepcopy(row) for row in contract[:5]],
            deepcopy(contract[5]),
            deepcopy(contract[5]),
            deepcopy(contract[6]),
            deepcopy(contract[8]),
            deepcopy(contract[9]),
        ]
        for ordinal, row in enumerate(expected):
            row["ordinal"] = ordinal
        for ordinal in (1, 2, 5, 6, 7, 8):
            expected[ordinal]["storage_identity"] = self.retail_marker
        projected = (
            call_contract_verify_module
            ._zsnd_play_directsound_candidate_projection(
                expected,
                contract,
                candidate,
                parse_assembly(self.retail_listing(), source="bn"),
                caller_identity="symbol:recoil:function:0x49fbb0",
                caller_start="0x49fbb0",
                caller_end_exclusive="0x49fcf0",
            )
        )
        self.assertEqual(10, len(projected))
        self.assertTrue(compare_call_contracts(expected, projected)["passed"])
        self.assertEqual(self.inbound_marker, projected[5]["storage_identity"])
        self.assertEqual(self.inbound_marker, projected[6]["storage_identity"])
        self.assertEqual(0x34, projected[7]["slot_displacement"])
        self.assertEqual(0x30, projected[8]["slot_displacement"])

    def test_schema123_projection_fails_closed_on_complete_drift_matrix(self) -> None:
        candidate = self.candidate_assembly()
        contract = self.extract()
        expected = [
            *[deepcopy(row) for row in contract[:5]],
            deepcopy(contract[5]),
            deepcopy(contract[5]),
            deepcopy(contract[6]),
            deepcopy(contract[8]),
            deepcopy(contract[9]),
        ]
        for ordinal, row in enumerate(expected):
            row["ordinal"] = ordinal
        for ordinal in (1, 2, 5, 6, 7, 8):
            expected[ordinal]["storage_identity"] = self.retail_marker
        retail = parse_assembly(self.retail_listing(), source="bn")
        helper = candidate.tu_local_function_definitions[self.refresh_canonical]
        caller = candidate.caller_definition
        assert caller is not None
        candidates = {
            "helper-body": replace(
                candidate,
                tu_local_function_definitions={
                    self.refresh_canonical: replace(
                        helper, data=helper.data[:-1] + b"\x90"
                    )
                },
            ),
            "helper-relocation": replace(
                candidate,
                tu_local_function_definitions={
                    self.refresh_canonical: replace(
                        helper, relocations=helper.relocations[:-1]
                    )
                },
            ),
            "caller-relocation": replace(
                candidate,
                caller_definition=replace(
                    caller, relocations=caller.relocations[:-1]
                ),
            ),
        }
        for label, drifted in candidates.items():
            with self.subTest(label=label):
                projected = (
                    call_contract_verify_module
                    ._zsnd_play_directsound_candidate_projection(
                        expected,
                        contract,
                        drifted,
                        retail,
                        caller_identity="symbol:recoil:function:0x49fbb0",
                        caller_start="0x49fbb0",
                        caller_end_exclusive="0x49fcf0",
                    )
                )
                self.assertEqual(contract, projected)

        for label, old, new in (
            ("retail-volume", "49fc69 ff 52 3c", "49fc69 ff 52 40"),
            ("retail-inline", "49fca8 7c e4", "49fca8 7c e2"),
            ("retail-close", "49fcce 68 9f 02 00 00", "49fcce 68 a0 02 00 00"),
        ):
            with self.subTest(label=label):
                drifted_retail = parse_assembly(
                    self.retail_listing().replace(old, new), source="bn"
                )
                projected = (
                    call_contract_verify_module
                    ._zsnd_play_directsound_candidate_projection(
                        expected,
                        contract,
                        candidate,
                        drifted_retail,
                        caller_identity="symbol:recoil:function:0x49fbb0",
                        caller_start="0x49fbb0",
                        caller_end_exclusive="0x49fcf0",
                    )
                )
                self.assertEqual(contract, projected)


