    @classmethod
    def row(
        cls,
        ordinal: int,
        identity: str,
        *,
        kind: str = "direct",
        cleanup: int | None = None,
    ) -> dict[str, object]:
        return {
            "ordinal": ordinal,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": kind,
            "target_identity": identity,
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": cleanup,
        }

    @classmethod
    def contracts(cls) -> tuple[list[dict[str, object]], list[dict[str, object]]]:
        expected = [
            cls.row(0, cls.provider, kind="provider", cleanup=4),
            cls.row(1, cls.provider, kind="provider", cleanup=4),
            cls.row(2, cls.registry_identity),
        ]
        expected.extend(
            cls.row(ordinal, f"symbol:schema124:{ordinal}")
            for ordinal in range(3, 18)
        )
        candidate = deepcopy(expected)
        candidate[1] = cls.row(
            1, f"candidate-local-coff:{cls.constructor}", cleanup=4
        )
        return expected, candidate

    @classmethod
    def indexes(cls) -> IdentityIndexes:
        return IdentityIndexes(
            by_address={"0x4c5b76": cls.provider},
            by_candidate_name={},
            provider_ids=frozenset({cls.provider}),
            storage_by_address={},
            storage_by_name={},
        )

    @classmethod
    def assembly(cls) -> CandidateAssembly:
        instructions = tuple(parse_assembly(cls.candidate_listing, source="cod"))
        caller_data = bytearray(0x250)
        addresses = call_contract_verify_module._instruction_runtime_addresses(
            instructions, source="cod", caller_start=0
        )
        for instruction, offset in zip(instructions, addresses):
            assert offset is not None
            body = bytes(int(item, 16) for item in instruction.bytes)
            caller_data[offset : offset + len(body)] = body
        helper_data = bytes.fromhex(
            "8a 44 24 04 56 8b f1 6a 30 88 06 e8 00 00 00 00 "
            "83 c4 04 89 00 89 40 04 89 46 04 c7 46 08 00 00 "
            "00 00 8b c6 5e c2 04 00 90 90 90 90 90 90 90 90"
        )
        helper_mask = [False] * len(helper_data)
        helper_mask[0x0C:0x10] = [True] * 4
        caller_mask = [False] * len(caller_data)
        for offset in (0x32, 0x4D, 0x60):
            caller_mask[offset : offset + 4] = [True] * 4
        symbol = lambda index, name, section, size, characteristics: (
            CandidateCoffSymbolDefinition(
                index=index,
                name=name,
                value=0,
                section_number=section,
                symbol_type=0x20,
                storage_class=2,
                aux_count=0,
                weak_external_tag_index=None,
                weak_external_characteristics=None,
                section_name=".text" if section else "",
                section_size=size,
                section_characteristics=characteristics,
                natural_end=size,
            )
        )
        return CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=frozenset(),
            tu_local_function_definitions={
                cls.constructor: CandidateTuLocalFunctionDefinition(
                    symbol=cls.constructor,
                    data=helper_data,
                    relocations=(
                        CoffRelocation(0x0C, 10, 0x14, cls.operator_new),
                    ),
                    relocation_mask=tuple(helper_mask),
                    section_size=0x30,
                    section_external_functions=(cls.constructor,),
                    section_is_comdat=True,
                    comdat_selection=2,
                    instructions=tuple(parse_assembly(
                        "00000 8a 44 24 04 mov al,[esp+4]", source="cod"
                    )),
                    source_provenance=str(
                        REPO_ROOT
                        / "src"
                        / "GameZRecoil"
                        / "zSound"
                        / "zsnd_play.cpp"
                    ),
                )
            },
            caller_definition=CandidateCallerDefinition(
                symbol=cls.caller_symbol,
                data=bytes(caller_data),
                relocations=(
                    CoffRelocation(0x32, 10, 0x14, cls.operator_new),
                    CoffRelocation(0x4D, 11, 0x14, cls.constructor),
                    CoffRelocation(0x60, 12, 0x14, cls.registry),
                ),
                relocation_mask=tuple(caller_mask),
                undefined_external_functions=(cls.operator_new, cls.registry),
                defined_external_functions=(cls.constructor,),
                coff_symbols=(
                    symbol(10, cls.operator_new, 0, 0, 0),
                    symbol(11, cls.constructor, 60, 0x30, 0x1000),
                    symbol(12, cls.registry, 0, 0, 0),
                ),
                section_index=54,
                section_start=0,
                section_end=0x250,
            ),
        )

    def project(
        self,
        *,
        expected: list[dict[str, object]] | None = None,
        candidate_contract: list[dict[str, object]] | None = None,
        assembly: CandidateAssembly | None = None,
        retail_listing: str | None = None,
        caller_identity: str | None = None,
        caller_end: str = "0x4a0300",
        indexes: IdentityIndexes | None = None,
    ) -> list[dict[str, object]]:
        baseline_expected, baseline_candidate = self.contracts()
        return call_contract_verify_module._zsnd_snapshot_inline_constructor_candidate_projection(
            expected or baseline_expected,
            candidate_contract or baseline_candidate,
            assembly or self.assembly(),
            parse_assembly(retail_listing or self.retail_listing, source="bn"),
            caller_identity=caller_identity or self.caller_identity,
            caller_start="0x49fff0",
            caller_end_exclusive=caller_end,
            indexes=indexes or self.indexes(),
        )

    def test_schema124_common_live_route_consumes_snapshot_projection(self) -> None:
        names = set(
            call_contract_verify_module.live_call_contract_result.__code__.co_names
        )
        self.assertIn(
            "_compose_reviewed_retail_provenance_adapters", names
        )
        self.assertIn(
            "_zsnd_snapshot_inline_constructor_candidate_projection", names
        )
        source = Path(call_contract_verify_module.__file__).read_text(
            encoding="utf-8"
        )
        self.assertEqual(
            1,
            source.count(
                "candidate = _zsnd_snapshot_inline_constructor_candidate_projection("
            ),
        )

    def test_schema124_exact_projection_matches_retail_contract(self) -> None:
        expected, _candidate = self.contracts()
        projected = self.project()
        self.assertEqual(expected, projected)
        self.assertTrue(compare_call_contracts(expected, projected)["passed"])
        self.assertEqual("", projected[1]["storage_identity"])
        self.assertEqual(self.provider, projected[1]["target_identity"])

    def test_schema124_complete_seam_drift_fails_closed(self) -> None:
        expected, candidate_contract = self.contracts()
        assembly = self.assembly()
        helper = assembly.tu_local_function_definitions[self.constructor]
        caller = assembly.caller_definition
        assert caller is not None
        constructor_symbol = caller.coff_symbols[1]

        bad_provider = replace(
            self.indexes(), by_address={"0x4c5b76": "provider:wrong"}
        )
        bad_expected = deepcopy(expected)
        bad_expected[1]["cleanup_bytes"] = None
        bad_contract = deepcopy(candidate_contract)
        bad_contract[1]["target_identity"] = "candidate-local-coff:wrong"
        bad_helper_data = replace(
            helper, data=helper.data[:-1] + bytes([helper.data[-1] ^ 1])
        )
        bad_helper_cfg = replace(
            helper, local_control_flow_indices=frozenset({0})
        )
        bad_provenance = replace(helper, source_provenance=str(REPO_ROOT))
        bad_helper_coff = replace(helper, comdat_selection=1)
        bad_caller_relocations = replace(
            caller, relocations=caller.relocations[:-1]
        )
        bad_caller_symbol = replace(caller, symbol="?Wrong@@YAXXZ")
        bad_coff_symbol = replace(
            caller,
            coff_symbols=(
                caller.coff_symbols[0],
                replace(constructor_symbol, section_characteristics=0),
                caller.coff_symbols[2],
            ),
        )
        bad_alias = replace(
            caller,
            coff_symbols=caller.coff_symbols
            + (replace(constructor_symbol, index=13),),
        )
        bad_instruction_rows = list(assembly.instructions)
        bad_instruction_rows[0] = replace(
            bad_instruction_rows[0], bytes=("6a", "0d")
        )

        cases = {
            "caller-identity": {"caller_identity": "symbol:wrong"},
            "caller-extent": {"caller_end": "0x4a02ff"},
            "population": {"expected": expected[:-1]},
            "provider-abi": {"expected": bad_expected},
            "provider-index": {"indexes": bad_provider},
            "candidate-ordinal": {"candidate_contract": bad_contract},
            "helper-body": {
                "assembly": replace(
                    assembly,
                    tu_local_function_definitions={
                        self.constructor: bad_helper_data
                    },
                )
            },
            "helper-cfg": {
                "assembly": replace(
                    assembly,
                    tu_local_function_definitions={
                        self.constructor: bad_helper_cfg
                    },
                )
            },
            "source-provenance": {
                "assembly": replace(
                    assembly,
                    tu_local_function_definitions={
                        self.constructor: bad_provenance
                    },
                )
            },
            "comdat-selection": {
                "assembly": replace(
                    assembly,
                    tu_local_function_definitions={
                        self.constructor: bad_helper_coff
                    },
                )
            },
            "caller-relocation": {
                "assembly": replace(
                    assembly, caller_definition=bad_caller_relocations
                )
            },
            "caller-symbol": {
                "assembly": replace(
                    assembly, caller_definition=bad_caller_symbol
                )
            },
            "coff-section": {
                "assembly": replace(
                    assembly, caller_definition=bad_coff_symbol
                )
            },
            "coff-alias": {
                "assembly": replace(assembly, caller_definition=bad_alias)
            },
            "caller-bytes": {
                "assembly": replace(
                    assembly, instructions=tuple(bad_instruction_rows)
                )
            },
            "retail-inline": {
                "retail_listing": self.retail_listing.replace(
                    "4a0047 89 40 04", "4a0047 89 40 08"
                )
            },
        }
        for label, arguments in cases.items():
            with self.subTest(label=label):
                with self.assertRaisesRegex(ValueError, "snapshot inline-constructor"):
                    self.project(**arguments)


