    def test_schema127_complete_caller_uses_active_candidate_extractor(
        self,
    ) -> None:
        rows = parse_assembly(self.listing(), source="cod")
        call_indices = [
            index
            for index, instruction in enumerate(rows)
            if call_contract_verify_module._instruction_mnemonic(instruction)
            == "call"
        ]
        self.assertEqual(5, len(call_indices))
        finite_helper = (
            call_contract_verify_module
            ._exact_candidate_zsnd_playwithdelta_a3d_backend_vptr_proofs
        )
        with patch.object(
            call_contract_verify_module,
            "_exact_candidate_zsnd_playwithdelta_a3d_backend_vptr_proofs",
            wraps=finite_helper,
        ) as consumed_receiver_proof:
            contract = extract_invocation_contract(
                rows,
                source="cod",
                caller_identity="symbol:recoil:function:0x4a0380",
                caller_start="0x4a0380",
                caller_end_exclusive="0x4a0400",
                indexes=self.indexes(),
            )
        consumed_receiver_proof.assert_called_once()
        self.assertEqual(
            {call_indices[index]: self.marker for index in (1, 2, 3)},
            self.proofs(),
        )
        for ordinal, slot in ((1, 0xA0), (2, 0x3C), (3, 0x34)):
            with self.subTest(ordinal=ordinal):
                self.assertEqual("virtual-slot", contract[ordinal]["identity_kind"])
                self.assertEqual("", contract[ordinal]["target_identity"])
                self.assertEqual(self.marker, contract[ordinal]["storage_identity"])
                self.assertEqual(slot, contract[ordinal]["slot_displacement"])
        static_target = deepcopy(contract)
        static_target[1]["target_identity"] = "symbol:recoil:function:0x4adead"
        self.assertFalse(compare_call_contracts(contract, static_target)["passed"])
        expected = deepcopy(contract)
        for ordinal in (1, 2, 3):
            expected[ordinal]["storage_identity"] = self.retail_marker
        self.assertTrue(compare_call_contracts(expected, contract)["passed"])

