    def test_schema129_active_extractor_and_projection(self) -> None:
        rows = parse_assembly(self.listing(), source="cod")
        finite = call_contract_verify_module._exact_candidate_zsnd_apply_mute_backend_vptr_proofs
        with patch.object(call_contract_verify_module, "_exact_candidate_zsnd_apply_mute_backend_vptr_proofs", wraps=finite) as consumed:
            contract = extract_invocation_contract(
                rows, source="cod", caller_identity="symbol:recoil:function:0x4a0670",
                caller_start="0x4a0670", caller_end_exclusive="0x4a07a0", indexes=self.indexes(),
            )
        consumed.assert_called_once()
        self.assertEqual(9, len(contract))
        for ordinal, slot in ((3, 0x3C), (5, 0xA0), (8, 0xA0)):
            self.assertEqual(self.marker, contract[ordinal]["storage_identity"])
            self.assertEqual(slot, contract[ordinal]["slot_displacement"])
            self.assertEqual("", contract[ordinal]["target_identity"])
        helper = CandidateTuLocalFunctionDefinition(
            symbol=self.float_name,
            data=bytes.fromhex(
                "51 89 4c 24 00 d9 44 24 00 59 c3 90 90 90 90 90"
            ),
            relocations=(), relocation_mask=(False,) * 16,
            section_size=0x10, section_external_functions=(self.float_name,),
            section_is_comdat=True, comdat_selection=1,
            instructions=(), source_provenance=self.source,
        )
        candidate = CandidateAssembly(
            instructions=tuple(rows), local_control_flow_indices=frozenset(),
            tu_local_function_definitions={self.float_name: helper},
        )
        retail_specs = (
            (0x4A0685, "e8 16 01 00 00"), (0x4A06B5, "e8 36 f9 ff ff"),
            (0x4A06E9, "e8 b2 00 00 00"), (0x4A06FD, "ff 91 a0 00 00 00"),
            (0x4A070E, "e8 ed f2 ff ff"), (0x4A0718, "ff 95 a0 00 00 00"),
            (0x4A074F, "e8 4c 00 00 00"), (0x4A0766, "ff 51 3c"),
            (0x4A0778, "ff 52 3c"),
        )
        retail = tuple(
            Instruction(
                text="retail call", raw_text="retail call",
                bytes=tuple(body.split()),
                source_line=f"{address:08x} retail call",
            ) for address, body in retail_specs
        )
        expected = [deepcopy(contract[index]) for index in (0, 1, 4, 5, 7, 8, 2, 3, 3)]
        for ordinal, row in enumerate(expected):
            row["ordinal"] = ordinal
            if row["dispatch"] == "indirect":
                row["storage_identity"] = self.retail_storage
        projected = call_contract_verify_module._zsnd_apply_mute_candidate_projection(
            expected, contract, candidate, retail,
            caller_identity="symbol:recoil:function:0x4a0670",
            caller_start="0x4a0670", caller_end_exclusive="0x4a07a0",
        )
        self.assertTrue(compare_call_contracts(expected, projected)["passed"])
        for ordinal in (3, 5, 7, 8):
            self.assertEqual(self.retail_storage, projected[ordinal]["storage_identity"])

        drifted_expected = deepcopy(expected)
        drifted_expected[3]["storage_identity"] = "dynamic:drift"
        rejected = call_contract_verify_module._zsnd_apply_mute_candidate_projection(
            drifted_expected, contract, candidate, retail,
            caller_identity="symbol:recoil:function:0x4a0670",
            caller_start="0x4a0670", caller_end_exclusive="0x4a07a0",
        )
        self.assertEqual(contract, rejected)

    def test_schema129_finite_authority_fails_closed(self) -> None:
        rows = parse_assembly(self.listing(), source="cod")
        addresses = call_contract_verify_module._instruction_runtime_addresses(rows, source="cod", caller_start=0x4A0670)
        invocations = [i for i, row in enumerate(rows) if call_contract_verify_module._instruction_mnemonic(row) == "call"]
        def prove(listing: str, **overrides: object) -> dict[int, str]:
            local = parse_assembly(listing, source="cod")
            return call_contract_verify_module._exact_candidate_zsnd_apply_mute_backend_vptr_proofs(
                local, invocation_indices=[i for i, row in enumerate(local) if call_contract_verify_module._instruction_mnemonic(row) == "call"],
                addresses=call_contract_verify_module._instruction_runtime_addresses(local, source="cod", caller_start=0x4A0670),
                caller_start=int(overrides.get("caller_start", 0x4A0670)), caller_end=int(overrides.get("caller_end", 0x4A07A0)),
                indexes=overrides.get("indexes", self.indexes()), local_control_flow_indices=frozenset(), local_control_flow_targets={},
            )
        self.assertEqual(3, len(prove(self.listing())))
        self.assertEqual({}, prove(self.listing(), caller_end=0x4A0790))
        self.assertEqual({}, prove(self.listing(replacements={"000d6 ff 90 a0 00 00 00 call dword [eax+0xa0]":"000d6 ff 90 a4 00 00 00 call dword [eax+0xa4]"})))
        self.assertEqual({}, prove(self.listing(), indexes=replace(self.indexes(), by_candidate_name={})))


