    def test_schema136_active_extractor_projects_exact_pushback_graph(self):
        candidate, expected, retail, bridge, indexes, bridges = self.fixture()
        raw = extract_invocation_contract(
            candidate.instructions, source="cod",
            caller_identity=self.caller_identity,
            caller_start="0x4a09e0", caller_end_exclusive="0x4a0c00",
            indexes=indexes, compiler_generated_bridges=bridges,
        )
        raw[2]["cleanup_bytes"] = 4
        self.assertEqual(3, len(raw))
        self.assertEqual("iat:calloc", raw[0]["target_identity"])
        self.assertEqual("iat:_strdup", raw[1]["target_identity"])
        self.assertEqual(
            "candidate-local-coff:"
            + call_contract_verify_module._ZSND_VECTOR_PUSHBACK_COFF,
            raw[2]["target_identity"],
        )
        finite = (
            call_contract_verify_module
            ._zsnd_sample_set_registry_pushback_candidate_projection
        )
        with patch.object(
            call_contract_verify_module,
            "_zsnd_sample_set_registry_pushback_candidate_projection",
            wraps=finite,
        ) as consumed:
            projected = (
                call_contract_verify_module
                ._zsnd_sample_set_registry_pushback_candidate_projection(
                    expected, raw, candidate, retail,
                    caller_identity=self.caller_identity,
                    caller_start="0x4a09e0",
                    caller_end_exclusive="0x4a0c00",
                    indexes=indexes, bridge=bridge,
                )
            )
        consumed.assert_called_once()
        self.assertEqual(expected, projected)
        self.assertTrue(compare_call_contracts(expected, projected)["passed"])

