    def test_schema137_active_extractor_expands_only_exact_scalar_dtor_row(self):
        candidate, expected, retail, bridge, indexes, bridges = self.fixture()
        raw = extract_invocation_contract(
            candidate.instructions, source="cod",
            caller_identity=self.caller_identity,
            caller_start="0x4a0c40", caller_end_exclusive="0x4a0e40",
            indexes=indexes, compiler_generated_bridges=bridges,
        )
        raw[10]["cleanup_bytes"] = 4
        self.assertEqual(13, len(raw))
        self.assertEqual(
            "candidate-local-coff:" + self.scalar_name,
            raw[10]["target_identity"],
        )
        finite = (
            call_contract_verify_module
            ._zsnd_wave_data_scalar_deleting_destructor_candidate_projection
        )
        with patch.object(
            call_contract_verify_module,
            "_zsnd_wave_data_scalar_deleting_destructor_candidate_projection",
            wraps=finite,
        ) as consumed:
            projected = (
                call_contract_verify_module
                ._zsnd_wave_data_scalar_deleting_destructor_candidate_projection(
                    expected, raw, candidate, retail,
                    caller_identity=self.caller_identity,
                    caller_start="0x4a0c40", caller_end_exclusive="0x4a0e40",
                    indexes=indexes, bridge=bridge,
                )
            )
        consumed.assert_called_once()
        self.assertEqual(expected, projected)
        self.assertTrue(compare_call_contracts(expected, projected)["passed"])
        self.assertEqual(
            raw,
            finite(
                expected, raw, candidate, retail,
                caller_identity="symbol:recoil:function:0x4a0fb0",
                caller_start="0x4a0fb0", caller_end_exclusive="0x4a1090",
                indexes=indexes, bridge=bridge,
            ),
        )

    def test_schema137_scalar_dtor_authority_fails_closed(self):
        candidate, expected, retail, bridge, indexes, bridges = self.fixture()
        raw = extract_invocation_contract(
            candidate.instructions, source="cod",
            caller_identity=self.caller_identity,
            caller_start="0x4a0c40", caller_end_exclusive="0x4a0e40",
            indexes=indexes, compiler_generated_bridges=bridges,
        )
        raw[10]["cleanup_bytes"] = 4
        definitions = candidate.tu_local_function_definitions
        scalar = definitions[self.scalar_name]
        complete = definitions[self.complete_name]
        cases = {
            "extent": {"caller_end_exclusive": "0x4a0e30"},
            "tracker": {"indexes": replace(indexes, by_address={})},
            "retail-population": {"expected": expected[:-1]},
            "retail-unchanged-row": {"expected": [{**expected[0], "form": "tail"}, *expected[1:]]},
            "candidate-population": {"candidate_contract": raw[:-1]},
            "candidate-unchanged-row": {"candidate_contract": [{**raw[0], "form": "tail"}, *raw[1:]]},
            "candidate-wrapper-row": {"candidate_contract": [*raw[:10], {**raw[10], "form": "tail"}, *raw[11:]]},
            "caller-body": {"candidate": replace(candidate, caller_definition=replace(candidate.caller_definition, data=b"\x90" * 0x1E0))},
            "caller-relocation": {"candidate": replace(candidate, caller_definition=replace(candidate.caller_definition, relocations=candidate.caller_definition.relocations[:-1]))},
            "caller-cfg": {"candidate": replace(candidate, local_control_flow_indices=frozenset({1}))},
            "source-provenance": {"candidate": replace(candidate, tu_local_function_definitions={**definitions, self.scalar_name: replace(scalar, source_provenance=r"D:\other.cpp")})},
            "scalar-body": {"candidate": replace(candidate, tu_local_function_definitions={**definitions, self.scalar_name: replace(scalar, data=b"\x90" * 0x20)})},
            "scalar-relocation": {"candidate": replace(candidate, tu_local_function_definitions={**definitions, self.scalar_name: replace(scalar, relocations=scalar.relocations[:-1])})},
            "scalar-flag-abi": {"candidate": replace(candidate, tu_local_function_definitions={**definitions, self.scalar_name: replace(scalar, instructions=(*scalar.instructions[:3], replace(scalar.instructions[3], raw_text="test byte ___flags$[esp], 2"), *scalar.instructions[4:]))})},
            "complete-tail": {"candidate": replace(candidate, tu_local_function_definitions={**definitions, self.complete_name: replace(complete, data=b"\x90" * 0x10)})},
            "coff-alias": {"candidate": replace(candidate, caller_definition=replace(candidate.caller_definition, coff_symbols=(*candidate.caller_definition.coff_symbols, candidate.caller_definition.coff_symbols[-1])))},
            "retail-instruction": {"retail_instructions": retail[:-1]},
            "retail-caller-body": {"bridge": SimpleNamespace(hexdump=lambda address, _size: "0x4a0c40 90" if call_contract_verify_module.normalize_address(address) == "0x4a0c40" else bridge.hexdump(address, _size))},
            "retail-target-body": {"bridge": SimpleNamespace(hexdump=lambda address, _size: "0x4a5440 90" if call_contract_verify_module.normalize_address(address) == "0x4a5440" else bridge.hexdump(address, _size))},
        }
        prove = (
            call_contract_verify_module
            ._zsnd_wave_data_scalar_deleting_destructor_candidate_projection
        )
        for label, changes in cases.items():
            arguments = {
                "expected": expected, "candidate_contract": raw,
                "candidate": candidate, "retail_instructions": retail,
                "caller_identity": self.caller_identity,
                "caller_start": "0x4a0c40",
                "caller_end_exclusive": "0x4a0e40",
                "indexes": indexes, "bridge": bridge,
            }
            arguments.update(changes)
            with self.subTest(label=label), self.assertRaises(ValueError):
                prove(**arguments)


