    @staticmethod
    def retail_listing() -> str:
        rows = [
            "004437d0 56 push esi",
            "004437d1 8b f1 mov esi, ecx",
            "004437d3 e8 98 26 08 00 call 0x4c5e70",
            "004437d8 8b 4c 24 08 mov ecx, dword [esp+8]",
            "004437dc c7 86 c8 00 00 00 00 00 00 00 mov dword [esi+0xc8], 0",
            "004437e6 c7 86 c4 00 00 00 e0 22 4d 00 mov dword [esi+0xc4], 0x4d22e0",
            "004437f0 c7 06 d8 21 4d 00 mov dword [esi], 0x4d21d8",
            "004437f6 e8 85 1f 06 00 call 0x4a5780",
            "004437fb e8 30 3d 06 00 call 0x4a7530",
            "00443800 8b c6 mov eax, esi",
            "00443802 5e pop esi",
            "00443803 c2 04 00 ret 4",
        ]
        return "\n".join(rows)

    def project(self, **changes: object) -> list[dict[str, object]]:
        expected, candidate_contract = self.contracts()
        arguments: dict[str, object] = {
            "expected": expected,
            "candidate_contract": candidate_contract,
            "candidate": self.assembly(),
            "retail_instructions": tuple(parse_assembly(self.retail_listing(), source="bn")),
            "caller_identity": self.caller_identity,
            "caller_start": "0x4437d0",
            "caller_end_exclusive": "0x443810",
        }
        arguments.update(changes)
        return call_contract_verify_module._czgameframe_cbitmap_inline_constructor_candidate_projection(**arguments)

    def test_schema139_exact_artifact_is_consumed_and_reordinalized(self) -> None:
        expected, _candidate = self.contracts()
        projected = self.project()
        self.assertEqual(expected, projected)
        self.assertTrue(compare_call_contracts(expected, projected)["passed"])

    def test_schema139_generic_constructor_population_is_a_noop(self) -> None:
        _expected, candidate = self.contracts()
        assembly = CandidateAssembly((), frozenset())
        projected = call_contract_verify_module._czgameframe_cbitmap_inline_constructor_candidate_projection(
            (), candidate, assembly, (), caller_identity="symbol:generic",
            caller_start="0x500000", caller_end_exclusive="0x500010",
        )
        self.assertEqual(candidate, projected)

    def test_schema139_independent_artifact_drifts_fail_closed(self) -> None:
        expected, candidate_contract = self.contracts()
        assembly = self.assembly()
        caller = assembly.caller_definition
        assert caller is not None
        helper = assembly.tu_local_function_definitions[self.cbitmap]

        wrong_name = deepcopy(candidate_contract)
        wrong_name[1]["target_identity"] = "candidate-local-coff:wrong"
        wrong_body = replace(helper, data=bytes([helper.data[0] ^ 1]) + helper.data[1:])
        wrong_relocation = replace(helper, relocations=helper.relocations[:-1])
        collision = replace(
            caller,
            coff_symbols=caller.coff_symbols + (replace(caller.coff_symbols[7], index=99),),
        )
        wrong_member = bytearray(caller.data)
        wrong_member[36] = 0xC0
        cases = {
            "wrong-caller": {"caller_identity": "symbol:wrong"},
            "wrong-offset": {"caller_end_exclusive": "0x44380f"},
            "wrong-name": {"candidate_contract": wrong_name},
            "wrong-body": {"candidate": replace(assembly, tu_local_function_definitions={**assembly.tu_local_function_definitions, self.cbitmap: wrong_body})},
            "wrong-reloc": {"candidate": replace(assembly, tu_local_function_definitions={**assembly.tu_local_function_definitions, self.cbitmap: wrong_relocation})},
            "wrong-population": {"candidate_contract": candidate_contract[:-1]},
            "collision": {"candidate": replace(assembly, caller_definition=collision)},
            "unused-proof": {"candidate_contract": expected},
            "wrong-member-layout": {"candidate": replace(assembly, caller_definition=replace(caller, data=bytes(wrong_member)))},
            "wrong-retail-inline": {"retail_instructions": tuple(parse_assembly(self.retail_listing().replace("c7 86 c4", "c7 86 c0", 1), source="bn"))},
        }
        for label, arguments in cases.items():
            with self.subTest(label=label):
                with self.assertRaisesRegex(ValueError, "CZGameFrame CBitmap"):
                    self.project(**arguments)


