    def test_exact_four_helper_ordinal_projection(self) -> None:
        fixture = self.fixture()
        projected = call_contract_verify_module._czgameframe_onpaint_ordinal_bridge_expected(**fixture)
        self.assertEqual(12, len(projected))
        self.assertEqual([self.hdc_id, self.handle_id, self.hdc_id, self.hdc_id],
                         [projected[i]["target_identity"] for i in (2, 4, 6, 8)])
        self.assertEqual(
            [(2, "direct", ""), (4, "direct", ""),
             (6, "direct", ""), (8, "direct", "")],
            [
                (projected[i]["ordinal"], projected[i]["identity_kind"],
                 projected[i]["storage_identity"])
                for i in (2, 4, 6, 8)
            ],
        )
        self.assertEqual(self.ctor_id, projected[0]["target_identity"])
        self.assertEqual(self.dtor_id, projected[11]["target_identity"])
