    def test_independent_proof_drifts_fail_closed(self) -> None:
        base = self.fixture(); candidate = base["candidate"]; caller = candidate.caller_definition
        assert caller is not None
        wrong_expected = deepcopy(base["expected"]); wrong_expected[7]["ordinal"] = 6
        wrong_form = deepcopy(base["expected"]); wrong_form[0]["form"] = "tail"
        wrong_cleanup = deepcopy(base["expected"]); wrong_cleanup[0]["cleanup_bytes"] = 4
        wrong_target = deepcopy(base["expected"]); wrong_target[7]["target_identity"] = "provider:wrong"
        wrong_body = bytes([caller.data[0] ^ 1]) + caller.data[1:]
        wrong_calls = tuple(parse_assembly(
            f"00024 e8 00 00 00 00 call {self.ctor}", source="cod"
        )) + candidate.instructions[1:]
        wrong_opcode = tuple(parse_assembly(
            f"00023 ff 15 00 00 00 00 call DWORD PTR {self.ctor}", source="cod"
        )) + candidate.instructions[1:]
        wrong_iat_form = candidate.instructions[:3] + tuple(parse_assembly(
            "0005b e8 00 00 00 00 call __imp__CreateCompatibleDC@4", source="cod"
        )) + candidate.instructions[4:]
        extra_calls = candidate.instructions + tuple(parse_assembly(
            "0010d e8 00 00 00 00 call extra", source="cod"
        ))
        wrong_iat = dict(base["indexes"].storage_by_name)
        wrong_iat["CreateCompatibleDC"] = "iat:wrong"
        swapped_iat = dict(base["indexes"].storage_by_name)
        swapped_iat["CreateCompatibleDC"], swapped_iat["SelectObject"] = (
            swapped_iat["SelectObject"], swapped_iat["CreateCompatibleDC"]
        )
        cases = {
            "ordinal": {"expected": wrong_expected}, "form": {"expected": wrong_form},
            "cleanup": {"expected": wrong_cleanup}, "target": {"expected": wrong_target},
            "callsite": {"candidate": replace(candidate, instructions=wrong_calls)},
            "opcode": {"candidate": replace(candidate, instructions=wrong_opcode)},
            "iat-form": {"candidate": replace(candidate, instructions=wrong_iat_form)},
            "missing-call": {"candidate": replace(candidate, instructions=candidate.instructions[:-1])},
            "extra-call": {"candidate": replace(candidate, instructions=extra_calls)},
            "body": {"candidate": replace(candidate, caller_definition=replace(caller, data=wrong_body))},
            "relocation": {"candidate": replace(candidate, caller_definition=replace(caller, relocations=caller.relocations[:-1]))},
            "provider": {"thunks": base["thunks"][:-1]},
            "storage": {"indexes": replace(base["indexes"], storage_by_name={})},
            "iat-storage": {"indexes": replace(base["indexes"], storage_by_name=wrong_iat)},
            "iat-swapped": {"indexes": replace(base["indexes"], storage_by_name=swapped_iat)},
            "eh": {"candidate": replace(candidate, caller_definition=replace(caller, coff_symbols=caller.coff_symbols[1:]))},
            "population": {"expected": base["expected"][:-1]},
            "collision": {"candidate": replace(candidate, caller_definition=replace(caller, coff_symbols=caller.coff_symbols + (replace(caller.coff_symbols[0], index=999),)))},
            "unused": {"expected": base["expected"] + [self.row(8, "symbol:extra")]},
        }
        for label, changes in cases.items():
            fixture = dict(base); fixture.update(changes)
            with self.subTest(label=label), self.assertRaisesRegex(ValueError, "CZGameFrame OnPaint"):
                call_contract_verify_module._czgameframe_onpaint_ordinal_bridge_expected(**fixture)


