    def test_exact_projection_proves_ordinal_one_and_preserves_cbitmap_two(
        self,
    ) -> None:
        fixture = self.fixture()
        expected_before = deepcopy(fixture["expected"])
        proof = call_contract_verify_module._czgameframe_inline_destructor_projection_proof(**fixture)

        self.assertEqual(expected_before, fixture["expected"])
        self.assertIsNotNone(proof)
        assert proof is not None
        adjusted = proof.provider_expected
        self.assertEqual(3, len(adjusted))
        self.assertEqual(
            self.row(
                1,
                self.cbitmap_identity,
                identity_kind="direct",
            ),
            adjusted[1],
        )
        self.assertEqual(self.row(2, self.cframewnd_identity), adjusted[2])
        self.assertEqual(
            self.row(1, self.cbitmap_resolved_identity),
            proof.candidate_resolved_expected[1],
        )

        bridges = call_contract_verify_module._provider_ordinal_import_thunk_candidate_bridges_from_reviewed_directs(
            adjusted,
            fixture["candidate"],
            thunks=fixture["thunks"],
            caller_identity=fixture["caller_identity"],
            caller_start=fixture["caller_start"],
            caller_end_exclusive=fixture["caller_end_exclusive"],
            indexes=fixture["indexes"],
            bridge_names={},
            reviewed_candidate_direct_bridges={
                self.return_symbol: self.return_identity,
                self.cbitmap_symbol: self.cbitmap_identity,
            },
        )
        self.assertEqual(
            {
                self.cframewnd_symbol: self.cframewnd_identity,
            },
            bridges,
        )
        projected = call_contract_verify_module._apply_czgameframe_inline_destructor_projection(
            fixture["expected"], proof.candidate_resolved_expected, proof
        )
        self.assertEqual(fixture["expected"], projected)

