    def test_caller_source_cod_coff_and_mfc_provider_drift_fail_closed(
        self,
    ) -> None:
        base = self.fixture()
        candidate = base["candidate"]
        definition = candidate.caller_definition
        self.assertIsNotNone(definition)
        assert definition is not None
        wrong_instructions = tuple(parse_assembly(
            f"0002b e8 00 00 00 00 call {self.return_symbol}\n0003c e8 00 00 00 00 call {self.cbitmap_symbol}\n0004a e8 00 00 00 00 call {self.cframewnd_symbol}", source="cod"))
        wrong_helper = replace(candidate.tu_local_function_definitions[self.cbitmap_symbol], data=b"\x90" + candidate.tu_local_function_definitions[self.cbitmap_symbol].data[1:])
        cases = {
            "caller": {"caller_identity": "symbol:wrong"},
            "source": {
                "candidate": replace(
                    candidate,
                    target=SimpleNamespace(
                        **{
                            **vars(candidate.target),
                            "source_from": "src/Wrong.cpp",
                        }
                    ),
                )
            },
            "compile": {"candidate": replace(candidate, target=SimpleNamespace(**{**vars(candidate.target), "compiler_flags": ("/TP", "/O2", "/Ob2", "/FAcs")}))},
            "cod": {"candidate": replace(candidate, instructions=wrong_instructions)},
            "coff": {
                "candidate": replace(
                    candidate,
                    caller_definition=replace(
                        definition,
                        relocations=definition.relocations[:-1],
                    ),
                )
            },
            "retail-row": {
                "expected": [
                    base["expected"][0],
                    {**base["expected"][1], "ordinal": 0},
                    base["expected"][2],
                ]
            },
            "helper": {"candidate": replace(candidate, tu_local_function_definitions={**candidate.tu_local_function_definitions, self.cbitmap_symbol: wrong_helper})},
            "retail-inline": {"retail_instructions": tuple(parse_assembly(self.retail_listing().replace("c7 07 f8 22 4d 00", "c7 07 f4 22 4d 00"), source="bn"))},
            "collision": {"candidate": replace(candidate, caller_definition=replace(definition, coff_symbols=definition.coff_symbols + (replace(definition.coff_symbols[6], index=99),)))},
            "mfc-provider": {"thunks": base["thunks"][:-1]},
            "storage": {
                "indexes": replace(
                    base["indexes"],
                    storage_by_name={},
                )
            },
            "resolved-provider": {
                "indexes": replace(
                    base["indexes"],
                    by_address={
                        key: value
                        for key, value in base["indexes"].by_address.items()
                        if key != "0x443c00"
                    },
                )
            },
        }
        for label, changes in cases.items():
            fixture = dict(base)
            fixture.update(changes)
            with (
                self.subTest(label=label),
                self.assertRaisesRegex(
                    ValueError,
                    "CZGameFrame inline-destructor projection",
                ),
            ):
                call_contract_verify_module._czgameframe_inline_destructor_projection_proof(
                    **fixture
                )

