    def test_candidate_a1_com_vptr_bridge_is_exact_and_adversarial(self) -> None:
        candidate = self.candidate_fixture()
        helper = (
            call_contract_verify_module
            ._zvid_dd_candidate_com_vptr_storage_bridges
        )
        with patch.object(
            call_contract_verify_module,
            "_exact_register_definition_set_covers_transfer",
            return_value=True,
        ) as coverage:
            bridges = helper(
                self.candidate_expected(),
                candidate,
                caller_identity=self.caller_identity,
                caller_start="0x4a8220",
                caller_end_exclusive="0x4a82f0",
                indexes=self.indexes(),
            )
        self.assertEqual({"0x38", "0x4c", "0x9a", "0xb0"}, set(bridges))
        self.assertEqual(4, coverage.call_count)
        self.assertEqual(
            [0x14, 0x6C, 0x14, 0x6C],
            [bridges[key].slot_displacement
             for key in ("0x38", "0x4c", "0x9a", "0xb0")],
        )
        self.assertEqual(
            ["ecx", "ecx", "edx", "edx"],
            [bridges[key].register
             for key in ("0x38", "0x4c", "0x9a", "0xb0")],
        )

        assert candidate.caller_definition is not None
        mutations = {}
        drifted_body = bytearray(candidate.caller_definition.data)
        drifted_body[0x6A] = 0xA3
        mutations["a1-opcode"] = replace(
            candidate,
            caller_definition=replace(
                candidate.caller_definition, data=bytes(drifted_body)
            ),
        )
        drifted_relocations = list(candidate.caller_definition.relocations)
        drifted_relocations[5] = replace(
            drifted_relocations[5], symbol_name="_g_wrong_surface"
        )
        mutations["a1-storage"] = replace(
            candidate,
            caller_definition=replace(
                candidate.caller_definition,
                relocations=tuple(drifted_relocations),
            ),
        )
        extra = Instruction(
            text="call eax", raw_text="call eax", bytes=("ff", "d0"),
            source_line="000d6 ff d0 call eax",
        )
        mutations["call-population"] = replace(
            candidate, instructions=(*candidate.instructions, extra)
        )
        for label, drifted in mutations.items():
            with (
                self.subTest(label=label),
                patch.object(
                    call_contract_verify_module,
                    "_exact_register_definition_set_covers_transfer",
                    return_value=True,
                ),
                self.assertRaisesRegex(
                    ValueError, "zVid DD candidate COM-vtable lineage"
                ),
            ):
                helper(
                    self.candidate_expected(),
                    drifted,
                    caller_identity=self.caller_identity,
                    caller_start="0x4a8220",
                    caller_end_exclusive="0x4a82f0",
                    indexes=self.indexes(),
                )

