    def test_exact_finite_short_jump_drifts_fail_closed(self) -> None:
        rows = self.rows()
        short_jump_index = next(
            index
            for index, row in enumerate(rows)
            if call_contract_verify_module._source_instruction_address(row)
            == "0x4a829b"
        )
        short_jump_target_index = next(
            index
            for index, row in enumerate(rows)
            if call_contract_verify_module._source_instruction_address(row)
            == "0x4a82a2"
        )
        cases = {
            "missing": {
                "rows": self.replace_at(
                    rows, "0x4a829b", body="90 90", text="nop"
                )
            },
            "target": {
                "rows": self.replace_at(
                    rows,
                    "0x4a829b",
                    body="eb 05",
                    text="jmp 0x4a82a3",
                )
            },
            "byte": {
                "rows": self.replace_at(
                    rows,
                    "0x4a829b",
                    body="eb 04",
                    text="jmp 0x4a82a2",
                )
            },
            "collision": {
                "local_control_flow_indices": frozenset({short_jump_index}),
                "local_control_flow_targets": {
                    short_jump_index: (short_jump_target_index,)
                },
            },
        }
        for label, arguments in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "zVid DD COM-vtable lineage",
            ):
                self.prove(**{"rows": rows, **arguments})

    def test_live_composer_routes_exact_local_jump_partition_without_fallback(
        self,
    ) -> None:
        rows, jump_index, targets = self.rows_with_local_jump()
        document, caller_identity = (
            RetailInvocationProvenanceV2Tests.authored_document(
                "0x4a8220", "0x4a82f0"
            )
        )
        self.assertEqual(self.caller_identity, caller_identity)

        def compose(
            routed_targets: dict[int, tuple[int, ...]],
        ) -> call_contract_verify_module.RetailCallerScopedProofPackage:
            with (
                patch.object(
                    call_contract_verify_module,
                    "retail_local_switch_targets",
                    return_value=routed_targets,
                ),
                patch.object(
                    call_contract_verify_module,
                    "_exact_targetless_vptr_call_proofs",
                    return_value={},
                ),
            ):
                _indexes, package = (
                    call_contract_verify_module
                    ._compose_caller_scoped_retail_proof_package(
                        rows,
                        document=document,
                        caller_identity=caller_identity,
                        caller_start="0x4a8220",
                        caller_end_exclusive="0x4a82f0",
                        indexes=self.indexes(),
                        bridge=self.inbound_bridge(),
                    )
                )
            return package

        package = compose(targets)
        self.assertEqual(
            ((jump_index, targets[jump_index]),),
            package.local_control_flow_targets,
        )
        self.assertEqual(4, len(package.targetless_vptr_call_proofs))

        drifts = {
            "missing": {},
            "extra": {
                **targets,
                jump_index + 1: (jump_index + 2,),
            },
            "target": {jump_index: (jump_index + 2,)},
        }
        for label, routed_targets in drifts.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "zVid DD COM-vtable lineage",
            ):
                compose(routed_targets)

