    def test_r4564_wol_release_retires_only_exact_inlined_delete_artifact(
        self,
    ) -> None:
        module = call_contract_verify_module
        dtor = "??1WestwoodOnlineUpgradeDownloadEventSink@@QAE@XZ"
        delete = "??3@YAXPAX@Z"
        interlocked = "__imp__InterlockedDecrement@4"
        natural_data = bytes.fromhex(
            "56 8b 74 24 08 57 8d 46 04 50 ff 15 00 00 00 00 "
            "8b f8 85 ff 75 14 85 f6 74 10 8b ce e8 00 00 00 00 "
            "56 e8 00 00 00 00 83 c4 04 8b c7 5f 5e c2 04 00"
        )
        data = natural_data + b"\x90" * (0x40 - len(natural_data))
        relocations = (
            CoffRelocation(0x0C, 11, 0x06, interlocked),
            CoffRelocation(0x1D, 12, 0x14, dtor),
            CoffRelocation(0x23, 13, 0x14, delete),
        )
        mask = tuple(
            index in {*range(0x0C, 0x10), *range(0x1D, 0x21), *range(0x23, 0x27)}
            for index in range(len(data))
        )
        candidate = CandidateAssembly(
            instructions=parse_assembly(
                "\n".join((
                    "00000 56 push esi",
                    "00001 8b 74 24 08 mov esi, dword _this$[esp]",
                    "00005 57 push edi",
                    "00006 8d 46 04 lea eax, dword [esi+4]",
                    "00009 50 push eax",
                    f"0000a ff 15 00 00 00 00 call dword {interlocked}",
                    "00010 8b f8 mov edi, eax",
                    "00012 85 ff test edi, edi",
                    "00014 75 14 jne 0x2a",
                    "00016 85 f6 test esi, esi",
                    "00018 74 10 je 0x2a",
                    "0001a 8b ce mov ecx, esi",
                    f"0001c e8 00 00 00 00 call {dtor}",
                    "00021 56 push esi",
                    f"00022 e8 00 00 00 00 call {delete}",
                    "00027 83 c4 04 add esp, 4",
                    "0002a 8b c7 mov eax, edi",
                    "0002c 5f pop edi",
                    "0002d 5e pop esi",
                    "0002e c2 04 00 ret 4",
                )),
                source="cod",
            ),
            local_control_flow_indices=frozenset(),
            caller_definition=CandidateCallerDefinition(
                symbol=(
                    "?Release@WestwoodOnlineUpgradeDownloadEventSink@@UAGKXZ"
                ),
                data=data,
                relocations=relocations,
                relocation_mask=mask,
                undefined_external_functions=(dtor, delete),
                undefined_external_data=(interlocked,),
                section_start=0,
                section_end=len(data),
            ),
        )
        identity = "symbol:recoil:function:0x442790"
        indexes = IdentityIndexes(
            by_address={"0x442790": identity}, by_candidate_name={},
            provider_ids=frozenset(), storage_by_address={}, storage_by_name={},
        )
        self.assertEqual(
            {},
            module._r4564_non_source_candidate_direct_bridges(
                [], candidate, caller_identity=identity,
                caller_start="0x442790", caller_end_exclusive="0x4427d0",
                indexes=indexes,
            ),
        )
        with self.assertRaisesRegex(ValueError, "complete 64-byte"):
            module._r4564_non_source_candidate_direct_bridges(
                [],
                replace(
                    candidate,
                    caller_definition=replace(
                        candidate.caller_definition,
                        relocations=(
                            relocations[0],
                            replace(relocations[1], offset=0x1E),
                            relocations[2],
                        ),
                    ),
                ),
                caller_identity=identity, caller_start="0x442790",
                caller_end_exclusive="0x4427d0", indexes=indexes,
            )
        scalar = "??_GWestwoodOnlineUpgradeDownloadEventSink@@QAEPAXI@Z"
        with self.assertRaisesRegex(ValueError, "zero scalar-deleting"):
            module._r4564_non_source_candidate_direct_bridges(
                [],
                replace(
                    candidate,
                    caller_definition=replace(
                        candidate.caller_definition,
                        undefined_external_functions=(dtor, delete, scalar),
                    ),
                ),
                caller_identity=identity, caller_start="0x442790",
                caller_end_exclusive="0x4427d0", indexes=indexes,
            )

