    def _appframe_run_v9_catch_fixture(
        self, *, catch_delta: int = 0
    ) -> dict[str, object]:
        module = call_contract_verify_module
        base_target = module.load_manifest(
            REPO_ROOT / module.APPFRAME_V9_MANIFEST_PATH
        )
        target = module._appframe_v10_base_profile_target(
            module.APPFRAME_V9_TARGET_ID,
            module.APPFRAME_V9_MANIFEST_PATH,
            base_target,
        )
        message_box = "__imp__MessageBoxExA@20"
        exit_name = "__imp__exit"
        handler_starts = tuple(
            offset + catch_delta for offset in (0x294, 0x2BB, 0x351)
        )
        continuation_offset = 0x378 + catch_delta
        catch_calls = tuple(
            tuple(offset + catch_delta for offset in sites)
            for sites in ((0x2A4, 0x2AC), (0x33A, 0x342), (0x361, 0x369))
        )
        ranges = tuple(zip(
            handler_starts,
            (*handler_starts[1:], continuation_offset),
        ))
        call_offsets = (
            0x31, 0x49, 0x53, 0x5E, 0x75, 0x7C, 0x8B, 0x96, 0x9E,
            0xFC, 0x12C, 0x15B, 0x173, 0x18C, 0x190, 0x1BF, 0x1C7,
            0x201, 0x216, 0x254, 0x258, 0x27F, 0x289,
            *(offset for sites in catch_calls for offset in sites),
        )
        rendered = {
            offset: "e8 00 00 00 00 call Helper"
            for offset in call_offsets
        }
        rendered[0x19] = "83 ec 0c sub esp, 12"
        for site in (sites[0] for sites in catch_calls):
            rendered[site] = (
                f"ff 15 00 00 00 00 call dword {message_box}"
            )
        for site in (sites[1] for sites in catch_calls):
            rendered[site] = f"ff 15 00 00 00 00 call dword {exit_name}"
        for boundary in (*handler_starts, continuation_offset):
            rendered.setdefault(boundary, "90 nop")
        for _start, end in ranges:
            rendered[end - 1] = "c3 ret"
        instructions = tuple(module.parse_assembly(
            "\n".join(
                f"{offset:05x} {text}"
                for offset, text in sorted(rendered.items())
            ),
            source="cod",
        ))

        body = bytearray(module.APPFRAME_RUN_V9_BODY_SIZE)
        body_mask = [False] * len(body)
        body[0x19:0x1C] = b"\x83\xec\x0c"
        for _start, end in ranges:
            body[end - 1] = 0xC3
        message_symbol = CandidateCoffSymbolDefinition(
            index=2, name=message_box, value=0, section_number=0,
            symbol_type=0x20, storage_class=2, aux_count=0,
            weak_external_tag_index=None,
            weak_external_characteristics=None, section_name="",
            section_size=0, section_characteristics=0, natural_end=0,
        )
        exit_symbol = replace(message_symbol, index=3, name=exit_name)
        body_relocations = []
        for symbol, sites in (
            (message_symbol, tuple(row[0] for row in catch_calls)),
            (exit_symbol, tuple(row[1] for row in catch_calls)),
        ):
            for site in sites:
                body[site : site + 6] = b"\xff\x15\0\0\0\0"
                body_mask[site + 2 : site + 6] = [True] * 4
                body_relocations.append(
                    CoffRelocation(site + 2, symbol.index, 0x06, symbol.name)
                )
        body_relocations.sort(key=lambda row: row.offset)

        caller_symbol = CandidateCoffSymbolDefinition(
            index=1, name=module.APPFRAME_RUN_V9_SYMBOL, value=0,
            section_number=537, symbol_type=0x20, storage_class=2,
            aux_count=0, weak_external_tag_index=None,
            weak_external_characteristics=None, section_name=".text",
            section_size=module.APPFRAME_RUN_V9_BODY_SIZE,
            section_characteristics=module.IMAGE_SCN_LNK_COMDAT,
            natural_end=module.APPFRAME_RUN_V9_BODY_SIZE,
        )
        symbols = [caller_symbol, message_symbol, exit_symbol]
        xdata_section_symbols = []
        xdata_relocations = []
        xdata_body = bytearray(module.APPFRAME_RUN_V9_XDATA)
        xdata_mask = [False] * len(xdata_body)
        xdata_root = CandidateCoffSymbolDefinition(
            index=43, name="$TxdataRoot", value=0, section_number=538,
            symbol_type=0, storage_class=3, aux_count=0,
            weak_external_tag_index=None,
            weak_external_characteristics=None, section_name=".xdata$x",
            section_size=0x78, section_characteristics=0,
            natural_end=0x78,
        )
        symbols.append(xdata_root)
        for index, (relocation_offset, value) in enumerate(
            ((0x08, 0x20), (0x10, 0x30), (0x40, 0x48))
        ):
            name = f"$Txdata{index}"
            coff_symbol = CandidateCoffSymbolDefinition(
                index=40 + index, name=name, value=value,
                section_number=538, symbol_type=0, storage_class=3,
                aux_count=0, weak_external_tag_index=None,
                weak_external_characteristics=None, section_name=".xdata$x",
                section_size=0x78, section_characteristics=0,
                natural_end=0x78,
            )
            symbols.append(coff_symbol)
            xdata_section_symbols.append(CandidateAssociatedSectionSymbol(
                name, value, 538, 0, 3
            ))
            xdata_relocations.append(CoffRelocation(
                relocation_offset, coff_symbol.index, 0x06, name
            ))
            xdata_mask[relocation_offset : relocation_offset + 4] = [True] * 4
        for ordinal, spec in enumerate(module.APPFRAME_RUN_V13_CATCH_SPECS):
            rtti_offset, handler_offset, rtti_name, _lifecycle = spec
            start = handler_starts[ordinal]
            rtti_symbol = CandidateCoffSymbolDefinition(
                index=10 + ordinal * 2, name=rtti_name, value=0,
                section_number=0, symbol_type=0, storage_class=2,
                aux_count=0, weak_external_tag_index=None,
                weak_external_characteristics=None, section_name="",
                section_size=0, section_characteristics=0, natural_end=0,
            )
            handler_symbol = CandidateCoffSymbolDefinition(
                index=11 + ordinal * 2, name=f"$Lcatch{ordinal}",
                value=start, section_number=537, symbol_type=0,
                storage_class=6, aux_count=0,
                weak_external_tag_index=None,
                weak_external_characteristics=None, section_name=".text",
                section_size=module.APPFRAME_RUN_V9_BODY_SIZE,
                section_characteristics=0,
                natural_end=module.APPFRAME_RUN_V9_BODY_SIZE,
            )
            symbols.extend((rtti_symbol, handler_symbol))
            xdata_relocations.extend((
                CoffRelocation(rtti_offset, rtti_symbol.index, 0x06,
                               rtti_symbol.name),
                CoffRelocation(handler_offset, handler_symbol.index, 0x06,
                               handler_symbol.name),
            ))
            xdata_mask[rtti_offset : rtti_offset + 4] = [True] * 4
            xdata_mask[handler_offset : handler_offset + 4] = [True] * 4
        continuation = CandidateCoffSymbolDefinition(
            index=30, name="$Lprimary", value=continuation_offset,
            section_number=537, symbol_type=0, storage_class=6, aux_count=0,
            weak_external_tag_index=None,
            weak_external_characteristics=None, section_name=".text",
            section_size=module.APPFRAME_RUN_V9_BODY_SIZE,
            section_characteristics=0,
            natural_end=module.APPFRAME_RUN_V9_BODY_SIZE,
        )
        symbols.append(continuation)
        xdata = CandidateAssociatedSection(
            section_index=538, association_section_index=537,
            name=".xdata$x", data=bytes(xdata_body),
            relocations=tuple(xdata_relocations),
            relocation_mask=tuple(xdata_mask), section_size=0x78,
            section_is_comdat=True, comdat_selection=5,
            section_external_symbols=(),
            symbols=(
                CandidateAssociatedSectionSymbol(
                    xdata_root.name, 0, 538, 0, 3
                ),
                *xdata_section_symbols,
            ),
        )
        definition = CandidateCallerDefinition(
            symbol=module.APPFRAME_RUN_V9_SYMBOL,
            data=bytes(body), relocations=tuple(body_relocations),
            relocation_mask=tuple(body_mask),
            undefined_external_functions=(message_box, exit_name),
            undefined_external_data=tuple(
                spec[2] for spec in module.APPFRAME_RUN_V13_CATCH_SPECS
            ),
            coff_symbols=tuple(symbols), section_index=537,
            section_start=0, section_end=module.APPFRAME_RUN_V9_BODY_SIZE,
            associated_sections=(xdata,),
        )
        candidate = CandidateAssembly(
            instructions=instructions,
            local_control_flow_indices=frozenset(),
            local_control_flow_targets={},
            target=target,
            caller_definition=definition,
        )
        generic = [
            self._direct_row(index, f"symbol:fixture:{index}")
            for index in range(len(call_offsets))
        ]
        call_sites = [
            module.normalize_address(
                int(module.APPFRAME_RUN_V9_START, 16) + offset
            )
            for offset in call_offsets
        ]
        expected = [
            self._direct_row(index, f"symbol:retail:{index}")
            for index in range(22)
        ]
        return {
            "candidate": candidate,
            "definition": definition,
            "xdata": xdata,
            "expected": expected,
            "generic": generic,
            "call_sites": call_sites,
            "call_offsets": call_offsets,
            "ranges": ranges,
            "catch_calls": catch_calls,
            "continuation_offset": continuation_offset,
        }

    @staticmethod
    def _appframe_run_live_artifact_candidate(
        artifact_version: str | Path,
    ) -> CandidateAssembly | None:
        module = call_contract_verify_module
        artifact_root = (
            artifact_version
            if isinstance(artifact_version, Path)
            else (
                REPO_ROOT
                / "build"
                / "live-validation"
                / "call-contract-integration"
                / artifact_version
                / "call-contract-appframe_442890_443730_authored_order"
            )
        )
        cod_path = artifact_root / "RecoilApp.cod"
        obj_path = artifact_root / "RecoilApp.obj"
        if not cod_path.is_file() or not obj_path.is_file():
            return None

        coff_object = module.CoffObject.from_path(obj_path)
        caller = coff_object.function_bytes(module.APPFRAME_RUN_V9_SYMBOL)
        parsed = module._extract_cod_proc_with_local_switches(
            cod_path, module.APPFRAME_RUN_V9_SYMBOL
        )
        classification_only_targets = (
            module._candidate_exact_local_switch_classification_targets(
                module._extract_cod_proc_lines(
                    cod_path, module.APPFRAME_RUN_V9_SYMBOL
                ),
                parsed,
                caller,
                coff_object,
            )
        )
        external = module._candidate_external_symbol_inventory(coff_object)
        target = module._appframe_v10_base_profile_target(
            module.APPFRAME_V9_TARGET_ID,
            module.APPFRAME_V9_MANIFEST_PATH,
            module.load_manifest(REPO_ROOT / module.APPFRAME_V9_MANIFEST_PATH),
        )
        return CandidateAssembly(
            instructions=parsed.instructions,
            local_control_flow_indices=(
                parsed.local_control_flow_indices
                | frozenset(classification_only_targets)
            ),
            local_control_flow_targets=parsed.local_control_flow_targets,
            classification_only_local_control_flow_targets=(
                classification_only_targets
            ),
            target=target,
            caller_definition=CandidateCallerDefinition(
                symbol=module.APPFRAME_RUN_V9_SYMBOL,
                data=caller.data,
                relocations=caller.relocations,
                relocation_mask=caller.relocation_mask,
                undefined_external_functions=external[0],
                defined_external_functions=external[1],
                undefined_external_data=external[2],
                defined_external_data=external[3],
                coff_symbols=module._candidate_coff_symbol_definitions(
                    coff_object
                ),
                section_index=caller.section_index,
                section_start=caller.start,
                section_end=caller.end,
                associated_sections=(
                    module._candidate_associated_comdat_sections(
                        coff_object, caller.section_index
                    )
                ),
            ),
        )

