    def test_appframe_run_v14_handler_symbol_uses_semantic_coff_identity(
        self,
    ) -> None:
        module = call_contract_verify_module
        fixture = self._appframe_run_v9_catch_fixture()
        candidate = fixture["candidate"]
        definition = fixture["definition"]

        class EqualDistinctSymbolPopulation(Sequence):
            def __init__(
                self, rows: tuple[CandidateCoffSymbolDefinition, ...]
            ) -> None:
                self._rows = rows

            def __len__(self) -> int:
                return len(self._rows)

            def __getitem__(self, index):
                row = self._rows[index]
                if isinstance(index, slice):
                    return tuple(replace(item) for item in row)
                return replace(row)

        distinct_population = EqualDistinctSymbolPopulation(
            definition.coff_symbols
        )
        distinct_candidate = replace(
            candidate,
            caller_definition=replace(
                definition,
                coff_symbols=distinct_population,
            ),
        )
        proof = module._appframe_run_catch_funclet_proof(
            distinct_candidate,
            caller_identity=module.APPFRAME_RUN_V9_CALLER_IDENTITY,
            caller_start=module.APPFRAME_RUN_V9_START,
            caller_end_exclusive=module.APPFRAME_RUN_V9_END,
        )
        self.assertIsNotNone(proof)

        handler = next(
            row for row in definition.coff_symbols
            if row.value == fixture["ranges"][0][0]
        )
        equal_distinct = replace(handler)
        self.assertIsNot(handler, equal_distinct)
        self.assertTrue(
            module._same_candidate_coff_symbol_identity(
                handler, equal_distinct
            )
        )
        adversarial = {
            "index": replace(handler, index=handler.index + 1),
            "name": replace(handler, name=handler.name + "Drift"),
            "value": replace(handler, value=handler.value + 1),
            "section": replace(
                handler, section_number=handler.section_number + 1
            ),
            "type": replace(handler, symbol_type=handler.symbol_type + 1),
            "storage": replace(
                handler, storage_class=handler.storage_class + 1
            ),
            "aux": replace(handler, aux_count=handler.aux_count + 1),
        }
        for label, drifted in adversarial.items():
            with self.subTest(label=label):
                self.assertFalse(
                    module._same_candidate_coff_symbol_identity(
                        handler, drifted
                    )
                )

    def test_appframe_run_v14_handler_equality_matches_governed_artifact(
        self,
    ) -> None:
        module = call_contract_verify_module
        artifact_root = (
            REPO_ROOT
            / "build"
            / "live-validation"
            / "call-contract-integration"
            / "appframe-v13-r4592"
            / "call-contract-appframe_442890_443730_authored_order"
        )
        obj_path = artifact_root / "RecoilApp.obj"
        if not obj_path.is_file():
            self.skipTest("governed appframe-v13-r4592 OBJ is unavailable")

        coff_object = module.CoffObject.from_path(obj_path)
        caller = coff_object.function_bytes(module.APPFRAME_RUN_V9_SYMBOL)
        symbols = module._candidate_coff_symbol_definitions(coff_object)
        symbol_by_index = {row.index: row for row in symbols}
        xdata = next(
            row
            for row in module._candidate_associated_comdat_sections(
                coff_object, caller.section_index
            )
            if row.name == ".xdata$x"
        )
        for _rtti_offset, handler_offset, _rtti_name, _lifecycle in (
            module.APPFRAME_RUN_V13_CATCH_SPECS
        ):
            relocation = next(
                row for row in xdata.relocations
                if row.offset == handler_offset
            )
            handler = symbol_by_index[relocation.symbol_index]
            equal_distinct = replace(handler)
            self.assertIsNot(handler, equal_distinct)
            self.assertTrue(
                module._same_candidate_coff_symbol_identity(
                    handler, equal_distinct
                )
            )
            self.assertFalse(
                module._same_candidate_coff_symbol_identity(
                    handler, replace(equal_distinct, index=handler.index + 1)
                )
            )
            self.assertFalse(
                module._same_candidate_coff_symbol_identity(
                    handler, replace(equal_distinct, name=handler.name + "Drift")
                )
            )

