    def test_appframe_run_v15_defined_rtti_comdat_drifts_fail_closed(
        self,
    ) -> None:
        module = call_contract_verify_module
        candidate = self._appframe_run_live_artifact_candidate(
            "appframe-v14-r4592"
        )
        if candidate is None:
            self.skipTest("governed appframe-v14-r4592 COD/OBJ is unavailable")
        definition = candidate.caller_definition
        assert definition is not None
        symbols = definition.coff_symbols
        rtti = next(
            row for row in symbols
            if row.name == "??_R0PAVCMemoryException@@@8"
        )
        file_rtti = next(
            row for row in symbols
            if row.name == "??_R0PAVCFileException@@@8"
        )
        type_info = next(
            row for row in symbols
            if row.name == module.APPFRAME_RUN_V15_TYPE_INFO_VFTABLE
        )
        relocation = rtti.section_relocations[0]
        next_index = max(row.index for row in symbols) + 1

        def replace_symbol(
            original: CandidateCoffSymbolDefinition,
            changed: CandidateCoffSymbolDefinition,
        ) -> tuple[CandidateCoffSymbolDefinition, ...]:
            return tuple(
                changed if row.index == original.index else row
                for row in symbols
            )

        cases = {
            "index": replace_symbol(
                rtti, replace(rtti, index=next_index)
            ),
            "name": replace_symbol(
                rtti, replace(rtti, name=rtti.name + "Drift")
            ),
            "value": replace_symbol(rtti, replace(rtti, value=1)),
            "section": replace_symbol(
                rtti, replace(rtti, section_number=rtti.section_number + 10)
            ),
            "missing-section-snapshot": replace_symbol(
                rtti, replace(rtti, section_snapshot_number=0)
            ),
            "type": replace_symbol(
                rtti, replace(rtti, symbol_type=0x20)
            ),
            "storage": replace_symbol(
                rtti, replace(rtti, storage_class=3)
            ),
            "aux": replace_symbol(rtti, replace(rtti, aux_count=1)),
            "section-name": replace_symbol(
                rtti, replace(rtti, section_name=".rdata")
            ),
            "section-size": replace_symbol(
                rtti, replace(rtti, section_size=rtti.section_size + 1)
            ),
            "natural-end": replace_symbol(
                rtti, replace(rtti, natural_end=rtti.natural_end - 1)
            ),
            "characteristics": replace_symbol(
                rtti,
                replace(
                    rtti,
                    section_characteristics=(
                        rtti.section_characteristics ^ 0x20
                    ),
                ),
            ),
            "raw-name-bytes": replace_symbol(
                rtti,
                replace(
                    rtti,
                    section_data=(
                        rtti.section_data[:-2]
                        + bytes((rtti.section_data[-2] ^ 1,))
                        + rtti.section_data[-1:]
                    ),
                ),
            ),
            "missing-relocation": replace_symbol(
                rtti, replace(rtti, section_relocations=())
            ),
            "relocation-offset": replace_symbol(
                rtti,
                replace(
                    rtti,
                    section_relocations=(replace(relocation, offset=4),),
                ),
            ),
            "relocation-type": replace_symbol(
                rtti,
                replace(
                    rtti,
                    section_relocations=(
                        replace(relocation, type=module.IMAGE_REL_I386_REL32),
                    ),
                ),
            ),
            "relocation-index": replace_symbol(
                rtti,
                replace(
                    rtti,
                    section_relocations=(
                        replace(relocation, symbol_index=rtti.index),
                    ),
                ),
            ),
            "relocation-name": replace_symbol(
                rtti,
                replace(
                    rtti,
                    section_relocations=(
                        replace(relocation, symbol_name="??_7wrong@@6B@"),
                    ),
                ),
            ),
            "extra-relocation": replace_symbol(
                rtti,
                replace(
                    rtti,
                    section_relocations=(relocation, replace(relocation)),
                ),
            ),
            "duplicate-rtti-name": (
                *symbols,
                replace(rtti, index=next_index),
            ),
            "extra-section-external": (
                *symbols,
                replace(
                    rtti,
                    index=next_index,
                    name="$unexpectedRttiSectionExternal",
                ),
            ),
            "duplicate-type-info": (
                *symbols,
                replace(type_info, index=next_index),
            ),
            "type-info-value": replace_symbol(
                type_info, replace(type_info, value=1)
            ),
            "type-info-section": replace_symbol(
                type_info, replace(type_info, section_number=1)
            ),
            "type-info-type": replace_symbol(
                type_info, replace(type_info, symbol_type=0x20)
            ),
            "type-info-storage": replace_symbol(
                type_info, replace(type_info, storage_class=3)
            ),
            "type-info-aux": replace_symbol(
                type_info, replace(type_info, aux_count=1)
            ),
            "shared-rtti-section": replace_symbol(
                file_rtti,
                replace(
                    file_rtti,
                    section_number=rtti.section_number,
                    section_snapshot_number=rtti.section_number,
                ),
            ),
        }
        for label, drifted_symbols in cases.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "AppFrame Run v9 catch-funclet partition"
            ):
                module._appframe_run_catch_funclet_proof(
                    replace(
                        candidate,
                        caller_definition=replace(
                            definition, coff_symbols=drifted_symbols
                        ),
                    ),
                    caller_identity=module.APPFRAME_RUN_V9_CALLER_IDENTITY,
                    caller_start=module.APPFRAME_RUN_V9_START,
                    caller_end_exclusive=module.APPFRAME_RUN_V9_END,
                )

