    def test_player_r4673_zinput_vector_size_projection_is_exact(self) -> None:
        module = call_contract_verify_module
        helper = module._player_zinput_vector_size_candidate_projection
        candidate = self._player_r4673_artifact_candidate("0x42a070")
        if candidate is None:
            self.skipTest("governed r4673 Player COD/OBJ is unavailable")
        candidate = replace(candidate, target=SimpleNamespace(compiler_env=""))
        size_symbol = (
            "?size@?$vector@PAUzInput_BindGroupInfo@@"
            "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@QBEIXZ"
        )
        ctor_symbol = "??0zInput_BindGroupInfo@@QAE@XZ"
        candidate_contract = [
            self._direct_row(0, f"candidate-local-coff:{size_symbol}"),
            self._direct_row(1, "iat:operator-new", kind="iat"),
            self._direct_row(2, f"candidate-local-coff:{ctor_symbol}"),
            self._direct_row(3, "provider:fixture:cstring", kind="provider"),
            self._direct_row(4, "provider:fixture:push-back", kind="provider"),
        ]
        expected = [dict(row) for row in candidate_contract[1:]]
        for ordinal, row in enumerate(expected):
            row["ordinal"] = ordinal
        expected[1] = self._direct_row(
            1, "provider:recoil:function:0x4c5ba0", kind="provider"
        )
        arguments = {
            "caller_identity": "symbol:recoil:function:0x42a070",
            "caller_start": "0x42a070",
            "caller_end_exclusive": "0x42a2c0",
        }
        formerly_projected = [dict(row) for row in candidate_contract[1:]]
        for ordinal, row in enumerate(formerly_projected):
            row["ordinal"] = ordinal
        exact_profile_contracts = {
            # The pre-provider insertion used to delete the leading size row.
            "pre-provider-old-artifact": candidate_contract,
            # The final comparison insertion must not accept or preserve the
            # already-deleted/reordinaled shape either.
            "final-comparison-former-projection": formerly_projected,
            "identity-drift": [
                {
                    **candidate_contract[0],
                    "target_identity": "candidate-local-coff:wrong",
                },
                *candidate_contract[1:],
            ],
            "population-drift": [
                *candidate_contract,
                self._direct_row(5, "symbol:extra"),
            ],
        }
        for label, contract in exact_profile_contracts.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError,
                "Player zInput vector::size projection is verifier-blocked",
            ):
                helper(expected, contract, candidate, **arguments)

        nonmatching_profiles = {
            "identity": {
                **arguments,
                "caller_identity": "symbol:recoil:function:0x42a071",
            },
            "start": {**arguments, "caller_start": "0x42a071"},
            "end": {**arguments, "caller_end_exclusive": "0x42a2c1"},
        }
        for label, nonmatching in nonmatching_profiles.items():
            with self.subTest(nonmatching=label):
                self.assertEqual(
                    candidate_contract,
                    helper(
                        expected,
                        candidate_contract,
                        candidate,
                        **nonmatching,
                    ),
                )

    def test_player_r4669_cstring_profiles_are_artifact_finite(self) -> None:
        module = call_contract_verify_module
        helper = module._player_cstring_inline_candidate_projection
        profiles = (
            (
                "0x420c60", "0x420d10", 8,
                (0, 1, 3, 4, 5, 6, 7),
                {2: ("call", "??BCString@@QBEPBDXZ")},
                "$L89379",
            ),
            (
                "0x425060", "0x425150", 10,
                (0, 2, 7, 4, 5, 8, 9),
                {
                    1: ("call", "?GetLength@CString@@QBEHXZ"),
                    3: ("call", "?GetLength@CString@@QBEHXZ"),
                    6: ("call", "??BCString@@QBEPBDXZ"),
                },
                "$L89677",
            ),
        )
        for start, end, population, mapping, extras, temporary_label in profiles:
            candidate = self._player_r4669_artifact_candidate(start)
            if candidate is None:
                self.skipTest("governed r4669 Player COD/OBJ is unavailable")
            candidate_contract = [
                self._direct_row(ordinal, f"symbol:fixture:{ordinal}")
                for ordinal in range(population)
            ]
            for ordinal, (form, name) in extras.items():
                candidate_contract[ordinal] = {
                    **self._direct_row(
                        ordinal, f"candidate-local-coff:{name}"
                    ),
                    "form": form,
                }
            expected = [dict(candidate_contract[index]) for index in mapping]
            for ordinal, row in enumerate(expected):
                row["ordinal"] = ordinal
            arguments = {
                "caller_identity": f"symbol:recoil:function:{start}",
                "caller_start": start,
                "caller_end_exclusive": end,
            }
            with self.subTest(start=start, proof="positive"):
                if start == "0x425060":
                    with self.assertRaisesRegex(
                        ValueError, "Player CString inline projection"
                    ):
                        helper(
                            expected,
                            candidate_contract,
                            candidate,
                            **arguments,
                        )
                else:
                    self.assertEqual(
                        expected,
                        helper(
                            expected,
                            candidate_contract,
                            candidate,
                            **arguments,
                        ),
                    )

            caller = candidate.caller_definition
            assert caller is not None
            temporary_reference = next(
                row
                for row in caller.relocations
                if row.symbol_name == temporary_label
            )
            changed_candidate = replace(
                candidate,
                caller_definition=replace(
                    caller,
                    relocations=tuple(
                        replace(row, symbol_name="$Lwrong")
                        if row is temporary_reference else row
                        for row in caller.relocations
                    ),
                ),
            )
            with self.subTest(start=start, proof="temporary-label"), self.assertRaisesRegex(
                ValueError, "Player CString inline projection"
            ):
                helper(
                    expected,
                    candidate_contract,
                    changed_candidate,
                    **arguments,
                )

