    def test_player_ftol_expected_direct_precedence_is_exact_and_finite(
        self,
    ) -> None:
        module = call_contract_verify_module
        name = module.MSVC_FTOL_CANDIDATE_SYMBOL
        provider = module.MSVC_FTOL_PROVIDER_IDENTITY
        iat_storage = module.MSVC_FTOL_IAT_STORAGE_IDENTITY
        helper = module._merge_player_ftol_expected_direct_bridges
        generic = {name: iat_storage, "generic": "provider:generic"}
        expected_direct = {name: provider, "same": "provider:same"}
        player = {name: provider}
        ftol = {name: iat_storage}
        for start in ("0x426770", "0x429870"):
            with self.subTest(start=start):
                self.assertEqual(
                    {
                        name: provider,
                        "generic": "provider:generic",
                        "same": "provider:same",
                    },
                    helper(
                        generic,
                        expected_direct,
                        caller_start=start,
                        player_compiler_provider_bridges=player,
                        ftol_provider_bridges=ftol,
                    ),
                )
        adversarials = {
            "caller": {"caller_start": "0x426771"},
            "player-proof": {
                "player_compiler_provider_bridges": {}
            },
            "ftol-proof": {"ftol_provider_bridges": {}},
            "generic-identity": {
                "compiler_generated_bridges": {name: "iat:wrong"}
            },
            "expected-identity": {
                "expected_direct_identity_bridges": {
                    name: "provider:wrong"
                }
            },
        }
        base = {
            "compiler_generated_bridges": generic,
            "expected_direct_identity_bridges": expected_direct,
            "caller_start": "0x426770",
            "player_compiler_provider_bridges": player,
            "ftol_provider_bridges": ftol,
        }
        for label, drift in adversarials.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "expected authored direct"
            ):
                helper(**{**base, **drift})
        with self.assertRaisesRegex(ValueError, "expected authored direct"):
            helper(
                {**generic, "other": "provider:left"},
                {**expected_direct, "other": "provider:right"},
                caller_start="0x426770",
                player_compiler_provider_bridges=player,
                ftol_provider_bridges=ftol,
            )

