    def test_player_cstring_inline_projections_are_artifact_finite(self) -> None:
        module = call_contract_verify_module
        helper = module._player_cstring_inline_candidate_projection
        profiles = (
            ("0x420c60", "0x420d10", 8, (0, 1, 3, 4, 5, 6, 7), {
                2: ("call", "??BCString@@QBEPBDXZ"),
            }),
        )
        first = None
        first_contract = None
        first_expected = None
        for start, end, population, mapping, extras in profiles:
            candidate = self._player_r4673_artifact_candidate(start)
            if candidate is None:
                self.skipTest("governed r4673 Player COD/OBJ is unavailable")
            candidate_contract = [
                self._direct_row(ordinal, f"symbol:fixture:{ordinal}")
                for ordinal in range(population)
            ]
            for ordinal, (form, name) in extras.items():
                candidate_contract[ordinal] = {
                    **self._direct_row(
                        ordinal, f"candidate-local-coff:{name}"
                    ),
                    "form": form,
                }
            expected = [dict(candidate_contract[index]) for index in mapping]
            for ordinal, row in enumerate(expected):
                row["ordinal"] = ordinal
            arguments = {
                "caller_identity": f"symbol:recoil:function:{start}",
                "caller_start": start,
                "caller_end_exclusive": end,
            }
            with self.subTest(start=start):
                receipts = []
                self.assertEqual(
                    expected,
                    helper(
                        expected,
                        candidate_contract,
                        candidate,
                        expansion_receipts_out=receipts,
                        **arguments,
                    ),
                )
                self.assertEqual(1, len(receipts))
                self.assertEqual(
                    candidate_contract,
                    receipts[0]["raw_physical_calls"],
                )
                self.assertEqual(
                    candidate_contract,
                    helper(
                        expected,
                        candidate_contract,
                        candidate,
                        **{
                            **arguments,
                            "caller_end_exclusive": hex(int(end, 16) + 1),
                        },
                    ),
                )
            if first is None:
                first = candidate
                first_contract = candidate_contract
                first_expected = expected

        assert first is not None
        assert first_contract is not None
        assert first_expected is not None

        blocked = self._player_r4673_artifact_candidate("0x425060")
        if blocked is None:
            self.skipTest("governed r4673 Player COD/OBJ is unavailable")
        blocked_contract = [
            self._direct_row(ordinal, f"symbol:fixture:{ordinal}")
            for ordinal in range(10)
        ]
        for ordinal, (form, name) in {
            1: ("call", "?GetLength@CString@@QBEHXZ"),
            3: ("call", "?GetLength@CString@@QBEHXZ"),
            6: ("call", "??BCString@@QBEPBDXZ"),
        }.items():
            blocked_contract[ordinal] = {
                **self._direct_row(
                    ordinal, f"candidate-local-coff:{name}"
                ),
                "form": form,
            }
        blocked_expected = [
            dict(blocked_contract[index])
            for index in (0, 2, 7, 4, 5, 8, 9)
        ]
        for ordinal, row in enumerate(blocked_expected):
            row["ordinal"] = ordinal
        with self.assertRaisesRegex(
            ValueError, "Player CString inline projection"
        ):
            helper(
                blocked_expected,
                blocked_contract,
                blocked,
                caller_identity="symbol:recoil:function:0x425060",
                caller_start="0x425060",
                caller_end_exclusive="0x425150",
            )

        conversion_name = "??BCString@@QBEPBDXZ"
        conversion = first.tu_local_function_definitions[conversion_name]
        base = {
            "caller_identity": "symbol:recoil:function:0x420c60",
            "caller_start": "0x420c60",
            "caller_end_exclusive": "0x420d10",
        }
        adversarials = {
            "caller-body": replace(
                first,
                caller_definition=replace(
                    first.caller_definition,
                    data=b"\x90" + first.caller_definition.data[1:],
                ),
            ),
            "conversion-body": replace(
                first,
                tu_local_function_definitions={
                    **first.tu_local_function_definitions,
                    conversion_name: replace(
                        conversion, data=b"\x90" + conversion.data[1:]
                    ),
                },
            ),
        }
        for label, candidate in adversarials.items():
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "Player CString inline projection"
            ):
                helper(
                    first_expected,
                    first_contract,
                    candidate,
                    **base,
                )
        with self.assertRaisesRegex(
            ValueError, "Player CString inline projection"
        ):
            helper(
                first_expected,
                [
                    first_contract[0],
                    first_contract[1],
                    {
                        **first_contract[2],
                        "target_identity": "candidate-local-coff:wrong",
                    },
                    *first_contract[3:],
                ],
                first,
                **base,
            )

    def test_player_top_message_static_indirect_bridge_is_artifact_finite(
        self,
    ) -> None:
        module = call_contract_verify_module
        candidate = self._player_r4646_artifact_candidate("0x41fe90")
        if candidate is None:
            self.skipTest("governed r4646 Player COD/OBJ is unavailable")
        expected = [
            self._direct_row(ordinal, f"symbol:fixture:{ordinal}")
            for ordinal in range(121)
        ]
        expected[5] = {
            "ordinal": 5,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": "symbol:recoil:function:0x4bb540",
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": 8,
        }
        expected[9] = {**expected[5], "ordinal": 9}
        indexes = IdentityIndexes(
            by_address={}, by_candidate_name={}, provider_ids=frozenset(),
            storage_by_address={
                "0x4f37b0": "storage:recoil:data:0x4f37b0",
                "0x4f33a8": "storage:recoil:data:0x4f33a8",
            },
            storage_by_name={},
        )
        arguments = {
            "caller_identity": "symbol:recoil:function:0x41fe90",
            "caller_start": "0x41fe90",
            "caller_end_exclusive": "0x420be0",
            "indexes": indexes,
        }
        helper = module._player_top_message_static_indirect_storage_bridge
        self.assertEqual(
            {
                "0x64": ReviewedExactIndirectStorageBridge(
                    register="esi",
                    storage_identity=(
                        "address(storage:recoil:data:0x4f37b0+0x74)"
                    ),
                    slot_displacement=0,
                    assembly_source="cod",
                    identity_kind="callback",
                ),
                "0xb4": ReviewedExactIndirectStorageBridge(
                    register="esi",
                    storage_identity=(
                        "address(storage:recoil:data:0x4f33a8+0x74)"
                    ),
                    slot_displacement=0,
                    assembly_source="cod",
                    identity_kind="callback",
                ),
            },
            helper(expected, candidate, **arguments),
        )
        candidate_contract = [
            self._direct_row(ordinal, f"symbol:candidate:{ordinal}")
            for ordinal in range(81)
        ]
        candidate_contract[5] = {
            "ordinal": 5,
            "form": "call",
            "dispatch": "indirect",
            "identity_kind": "callback",
            "target_identity": "",
            "storage_identity": (
                "address(storage:recoil:data:0x4f37b0+0x74)"
            ),
            "slot_displacement": None,
            "cleanup_bytes": 8,
        }
        candidate_contract[9] = {
            **candidate_contract[5],
            "ordinal": 9,
            "storage_identity": (
                "address(storage:recoil:data:0x4f33a8+0x74)"
            ),
        }
        projected = (
            module._player_top_message_static_indirect_candidate_projection(
                expected,
                candidate_contract,
                caller_identity=arguments["caller_identity"],
                caller_start=arguments["caller_start"],
                caller_end_exclusive=arguments["caller_end_exclusive"],
            )
        )
        self.assertEqual(expected[5], projected[5])
        self.assertEqual(expected[9], projected[9])
        self.assertEqual(81, len(projected))
        self.assertEqual(
            {},
            helper(
                expected,
                candidate,
                **{**arguments, "caller_start": "0x41fe91"},
            ),
        )
        relocation = next(
            row for row in candidate.caller_definition.relocations
            if row.offset == 0x4D
        )
        for label, changed_expected, changed_candidate, changed_indexes in (
            (
                "retail-storage",
                [*expected[:5], {
                    **expected[5], "storage_identity": "storage:wrong",
                }, *expected[6:]],
                candidate,
                indexes,
            ),
            (
                "storage-index",
                expected,
                candidate,
                replace(indexes, storage_by_address={}),
            ),
            (
                "dir32-site",
                expected,
                replace(
                    candidate,
                    caller_definition=replace(
                        candidate.caller_definition,
                        relocations=tuple(
                            replace(row, offset=0x4E)
                            if row is relocation else row
                            for row in candidate.caller_definition.relocations
                        ),
                    ),
                ),
                indexes,
            ),
        ):
            with self.subTest(label=label), self.assertRaisesRegex(
                ValueError, "Player top-message static-indirect"
            ):
                helper(
                    changed_expected,
                    changed_candidate,
                    **{**arguments, "indexes": changed_indexes},
                )

