    def test_recoilapp_exact_receiver_field_profiles_are_body_scoped(self) -> None:
        indexes = IdentityIndexes(
            by_address={},
            by_candidate_name={},
            provider_ids=frozenset(),
            storage_by_address={},
            storage_by_name={},
        )
        profiles = (
            (
                "0x431b10",
                "0x431b50",
                "00000 8b 44 24 0c mov eax, dword ptr [esp+12]\n"
                "00004 56 push esi\n"
                "00005 8b f1 mov esi, ecx\n"
                "00024 8b 8e c0 00 00 00 mov ecx, dword ptr [esi+192]\n"
                "0002a 8b 11 mov edx, dword ptr [ecx]\n"
                "0002c ff 92 a8 00 00 00 call dword ptr [edx+168]",
                "load(exact-receiver-field(this,+0xc0))",
            ),
            (
                "0x435ed0",
                "0x435f50",
                "00000 56 push esi\n"
                "00001 8b f1 mov esi, ecx\n"
                "0000f 8b 4e 04 mov ecx, dword ptr [esi+4]\n"
                "00014 8b 01 mov eax, dword ptr [ecx]\n"
                "00016 ff 50 04 call dword ptr [eax+4]",
                "load(exact-receiver-field(this,+0x4))",
            ),
        )
        for caller_start, caller_end, assembly, marker in profiles:
            with self.subTest(caller_start=caller_start):
                rows = tuple(parse_assembly(assembly, source="cod"))
                proofs = (
                    call_contract_verify_module._exact_targetless_vptr_call_proofs(
                        rows,
                        source="cod",
                        caller_start=caller_start,
                        caller_end_exclusive=caller_end,
                        indexes=indexes,
                    )
                )
                self.assertEqual({len(rows) - 1: marker}, proofs)

                drifted_rows = tuple(
                    parse_assembly(
                        assembly.replace("ff 50 04", "ff 50 08").replace(
                            "ff 92 a8 00 00 00", "ff 92 ac 00 00 00"
                        ),
                        source="cod",
                    )
                )
                self.assertNotIn(
                    len(drifted_rows) - 1,
                    call_contract_verify_module._exact_targetless_vptr_call_proofs(
                        drifted_rows,
                        source="cod",
                        caller_start=caller_start,
                        caller_end_exclusive=caller_end,
                        indexes=indexes,
                    ),
                )

