                "001e3 8b 44 24 38 mov eax, dword _blurAction$83120[esp+116]\n"
                "001e7 6a 00 push 0\n001e9 6a 00 push 0\n"
                "001eb 8d 4c 24 40 lea ecx, dword _blurAction$83120[esp+124]\n"
                "001ef ff 50 04 call dword [eax+4]\n"
                "001f6 8b 54 24 38 mov edx, dword _blurAction$83120[esp+116]\n"
                "001fa 8d 4c 24 38 lea ecx, dword _blurAction$83120[esp+116]\n"
                "001fe ff 52 0c call dword [edx+12]",
