    def test_recoilapp_ftol_branch_join_projection_is_exactly_scoped(self) -> None:
        def direct(ordinal: int, identity: str) -> dict[str, object]:
            return {
                "ordinal": ordinal,
                "form": "call",
                "dispatch": "direct",
                "identity_kind": "provider" if identity == "provider:ftol" else "direct",
                "target_identity": identity,
                "storage_identity": "",
                "slot_displacement": None,
                "cleanup_bytes": None,
            }

        expected = [direct(index, f"symbol:{index}") for index in range(5)]
        expected.extend(direct(index, "provider:ftol") for index in range(5, 8))
        expected.extend(direct(index, f"symbol:{index}") for index in range(8, 10))
        candidate = [direct(index, f"symbol:{index}") for index in range(5)]
        candidate.extend(
            direct(index, call_contract_verify_module.MSVC_FTOL_IAT_STORAGE_IDENTITY)
            for index in range(5, 7)
        )
        candidate.extend(
            direct(index, f"symbol:{index + 1}") for index in range(7, 9)
        )
        projected = (
            call_contract_verify_module._recoilapp_ftol_branch_join_candidate_projection(
                expected,
                candidate,
                caller_identity="symbol:recoil:function:0x432d60",
                caller_start="0x432d60",
                caller_end_exclusive="0x432e70",
                provider_identity="provider:ftol",
            )
        )
        self.assertEqual(10, len(projected))
        self.assertEqual([5, 6, 7], [
            row["ordinal"]
            for row in projected
            if row["target_identity"]
            == call_contract_verify_module.MSVC_FTOL_IAT_STORAGE_IDENTITY
        ])
        self.assertEqual(list(range(10)), [row["ordinal"] for row in projected])
        self.assertEqual(9, len(candidate))

        self.assertEqual(
            candidate,
            call_contract_verify_module._recoilapp_ftol_branch_join_candidate_projection(
                expected,
                candidate,
                caller_identity="symbol:fixture",
                caller_start="0x432d50",
                caller_end_exclusive="0x432e70",
                provider_identity="provider:ftol",
            ),
        )

