    @staticmethod
    def _retained_mission_candidate(symbol, *, artifact_root=None):
        module = call_contract_verify_module
        if artifact_root is None:
            artifact_root = (
                REPO_ROOT
                / "build"
                / "live-validation"
                / "worker-call-contract-convergence"
                / "0001-r4658"
                / "call-contract-mission_417350_41cc10_authored_order"
            )
        cod_path = artifact_root / "mission.cod"
        obj_path = artifact_root / "mission.obj"
        if not cod_path.is_file() or not obj_path.is_file():
            raise unittest.SkipTest(
                f"governed Mission artifact is unavailable: {artifact_root}"
            )
        coff_object = module.CoffObject.from_path(obj_path)
        caller = coff_object.function_bytes(symbol)
        parsed = module._extract_cod_proc_with_local_switches(cod_path, symbol)
        (
            undefined_external_functions,
            defined_external_functions,
            undefined_external_data,
            defined_external_data,
        ) = module._candidate_external_symbol_inventory(coff_object)
        associations = module._candidate_associated_comdat_sections_index(
            coff_object
        )
        return CandidateAssembly(
            instructions=parsed.instructions,
            local_control_flow_indices=parsed.local_control_flow_indices,
            local_control_flow_targets=parsed.local_control_flow_targets,
            caller_definition=CandidateCallerDefinition(
                symbol=symbol,
                data=caller.data,
                relocations=caller.relocations,
                relocation_mask=caller.relocation_mask,
                undefined_external_functions=undefined_external_functions,
                defined_external_functions=defined_external_functions,
                undefined_external_data=undefined_external_data,
                defined_external_data=defined_external_data,
                coff_symbols=module._candidate_coff_symbol_definitions(
                    coff_object
                ),
                section_index=caller.section_index,
                associated_sections=(
                    module._candidate_associated_comdat_sections(
                        coff_object,
                        caller.section_index,
                        sections_by_parent=associations,
                    )
                ),
                section_start=caller.start,
                section_end=caller.end,
            ),
        )

